const OPT_RUN_DEFAULTS = { finalists: 10 };
let optRun = { ...OPT_RUN_DEFAULTS };
let pickerSlot = 0;
// Mod-picker sort/filter prefs — persisted across slots, presets and weapons.
let pickerPrefs = { sort: "gain", dir: "desc", pol: null };
try { const s = JSON.parse(localStorage.getItem("wfsim-picker")); if (s) pickerPrefs = { ...pickerPrefs, ...s }; } catch (_) {}
const savePickerPrefs = () => localStorage.setItem("wfsim-picker", JSON.stringify(pickerPrefs));

// ---- topbar weapon search: filter chips + sort, rows navigate ----------
/// THE COMPUTE PICKER, in the topbar beside the language.
///
/// In the TOPBAR because it is the page's setting rather than any module's —
/// the same place the language and the theme live, and the same reason.
///
/// EVERY ROW NAMES THE LANE COUNT IT BUYS, because a percentage alone is not
/// something a reader can act on: "50%" says nothing until it says "4 of 8".
/// The button shows the LANES rather than the share, for the same reason —
/// that is the number that decides how hot the phone gets.
///
/// …AND IT SAYS WHEN IT IS GUESSING. A browser that will not report its core
/// count (iOS Safari 11–15.3, or a privacy mode) gets a fallback of 4 and a
/// line saying so, rather than a confident number nobody measured.
function renderComputePicker() {
  const host = $("compute-select");
  if (!host) return;
  const { n: cores, known } = detectedCores();
  const steps = computeSteps();
  // LANES OVER CORES on the face — `14/28` states the setting and its ceiling
  // in one, and it is plain text: an emoji or a dingbat is the one glyph the
  // platform draws in its own colour and its own shape, which is why this
  // topbar has none.
  const face = known ? `${poolSize()}/${cores}` : `${poolSize()}/?`;
  host.outerHTML = ddButton("compute-select", {
    value: String(computePct),
    title: known
      ? tr("how much of this machine the page may use — it changes how FAST an answer arrives, never what the answer is")
      : tr("this browser will not say how many cores it has, so 4 is assumed — the share still applies"),
    // A LANE COUNT, not a share: it is what the setting actually does.
    placeholder: face,
    items: steps.map((s) => ({
      value: String(s.pct),
      label: `${s.pct}%`,
      hint: known
        ? tr("{n} of {c} cores").replace("{n}", s.lanes).replace("{c}", cores)
        : tr("{n} lanes · cores unknown, assuming {c}")
            .replace("{n}", s.lanes).replace("{c}", cores),
    })),
    onPick: (v) => setComputePct(v),
  });
  // The face shows the LANES; the list shows the shares.
  const btn = $("compute-select");
  const el = btn && btn.querySelector(".dd-v");
  if (el) el.textContent = face;
}

function initWeaponSearch() {
  const input = $("wsearch-input"), panel = $("wsearch-panel"),
        tools = $("wsearch-tools"), listEl = $("wsearch-list");
  if (!input) return;
  input.placeholder = tr("Search…");
  let flt = "all", srt = "az";
  const cats = [...new Set((META.weapons || []).map((w) => w.subtype || w.mod_class))];
  tools.innerHTML =
    `<span class="pchip sel" data-f="all">${tr("All")}</span>` +
    cats.map((c) => `<span class="pchip" data-f="${c}">${c}</span>`).join("") +
    ddButton("wsearch-sort", {
      value: srt,
      items: [{ value: "az", label: tr("Name A→Z") }, { value: "za", label: tr("Name Z→A") }],
      onPick: (v) => { srt = v; renderList(); },
    });
  const renderList = () => {
    const q = input.value.trim().toLowerCase();
    // ONE ROW PER MODULAR WEAPON, for the reason the home grid shows one card:
    // two entries with one name, one picture and one destination is a list that
    // looks like it has a bug in it.
    const list = oneCardPerChamber(META.weapons || [])
      .filter((w) => flt === "all" || (w.subtype || w.mod_class) === flt)
      .filter((w) => searchHit(w, q))
      .sort((a, b) => (srt === "za" ? -1 : 1) * a.name.localeCompare(b.name));
    listEl.innerHTML = list.map((w) => `
      <div class="opt" data-id="${w.id}">
        ${imgTag(IMG(w.image), "mod")}
        <div class="info"><div class="mn">${w.name}</div><div class="me"><div>${w.subtype || ""}</div></div></div>
      </div>`).join("") || `<div class="sim-empty">${tr("No matches")}</div>`;
  };
  const open = () => { panel.hidden = false; renderList(); };
  input.addEventListener("focus", open);
  input.addEventListener("input", open);
  tools.addEventListener("click", (e) => {
    const chip = e.target.closest(".pchip");
    if (!chip) return;
    flt = chip.dataset.f;
    tools.querySelectorAll(".pchip").forEach((c) => c.classList.toggle("sel", c === chip));
    renderList();
  });
  tools.addEventListener("change", (e) => {

  });
  listEl.addEventListener("click", (e) => {
    const row = e.target.closest(".opt");
    if (!row) return;
    panel.hidden = true;
    input.value = "";
    switchWeapon(row.dataset.id);
    nav(weaponModPath(row.dataset.id));
  });
  document.addEventListener("click", (e) => {
    if (!e.target.closest(".wsearch")) panel.hidden = true;
  });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") panel.hidden = true; });
}

// language dropdown (top right, beside the theme toggle): switching
// reloads with the current build stashed and restored.
(function () {
  // What the DOCUMENT says it is, so a screen reader picks the right voice
  // and a crawler indexes the page under the language it is actually in.
  // The tag ships as `en` and the page may be zh from the first paint.
  document.documentElement.lang = LANG;
  const host = $("lang-select");
  if (!host) return;
  // The topbar's language control is a dropdown like every other, so it is
  // drawn by the same component — the LAST native select on the page, and the
  // most visible one.
  //
  // DEFERRED by a microtask, because this block runs DURING script evaluation
  // and the component it calls is declared further down: `const` and `function
  // expression` bindings are in their temporal dead zone until the line that
  // creates them runs, so drawing here directly threw. A microtask runs after
  // the whole script has evaluated, which is the first moment any part of the
  // file may call any other part.
  queueMicrotask(() => {
    const el = $("lang-select");
    if (!el) return;
    el.outerHTML = ddButton("lang-select", {
      value: LANG,
      title: "Language / 语言",
      items: [{ value: "en", label: "English" }, { value: "zh", label: "中文" }],
      onPick: (v) => {
        localStorage.setItem("wfsim-lang", v);
        try { sessionStorage.setItem("wfsim-lang-stash", JSON.stringify(snapshotState())); } catch (_) {}
        location.reload();
      },
    });
    // …AND THE COMPUTE PICKER BESIDE IT, drawn in the same deferred block and
    // for the same reason: both are the page's own settings and both call a
    // component declared further down this file.
    renderComputePicker();
  });
})();

// Official QQ community group: the topbar mark and the footer entry LINK
// to the join page (qm.qq.com deep-links into the QQ app, Discord-invite
// style); the footer's ⧉ copies the raw number for manual in-QQ search.
// Feedback is inline: no native dialogs.
const QQ_GROUP = "995078378";
(function () {
  const btn = $("qq-copy-foot");
  if (!btn) return;
  btn.addEventListener("click", async () => {
    try { await navigator.clipboard.writeText(QQ_GROUP); } catch (_) {
      const ta = document.createElement("textarea");
      ta.value = QQ_GROUP; document.body.appendChild(ta);
      ta.select(); document.execCommand("copy"); ta.remove();
    }
    btn.textContent = "✓";
    setTimeout(() => { btn.textContent = "⧉"; }, 1200);
  });
})();

// The phone's topbar menu. It opens ONE container that holds the real
// controls — see index.html — so there is nothing here to keep in sync with a
// second copy; this only decides when the container is a box.
(function () {
  const bar = document.querySelector(".topbar"), btn = $("menu-toggle");
  if (!bar || !btn) return;
  const set = (open) => {
    bar.classList.toggle("menu-open", open);
    btn.setAttribute("aria-expanded", open ? "true" : "false");
  };
  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    set(!bar.classList.contains("menu-open"));
  });
  // `#dd-popover` counts as INSIDE: the language dropdown draws into the
  // shared popover, which is a sibling of the menu in the DOM, so a click on
  // "中文" would otherwise close the panel out from under the control.
  document.addEventListener("click", (e) => {
    if (!e.target.closest("#topmenu, #menu-toggle, #dd-popover")) set(false);
  });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") set(false); });
  // A DESTINATION closes it — the page moves and the menu would be left open
  // over the new one. A CONTROL does not: after switching the theme you can
  // still want the language, and neither moves the page.
  document.querySelector("#topmenu .topnav")
    .addEventListener("click", () => set(false));
  // Above the breakpoint the panel is `display:contents` again and the class
  // means nothing — but it would still be there on the way back down.
  addEventListener("resize", () => { if (innerWidth > 700) set(false); });
})();

// THE COMMUNITY LINK A READER CAN ACT ON GOES ON THE BAR;
// the other one is in the overflow. A Chinese reader will never click Discord
// and an English reader will never click QQ, so putting both on the bar spent
// two of its slots to serve half a reader each.
//
// ORDERED, NEVER DROPPED — an English reader still finds the QQ group one
// click away. English is the source everywhere in this repo, so the markup
// ships the English order and this swaps it; a language change reloads the
// page, so it runs exactly once.
function applyCommunityOrder() {
  const primary = $("community-primary"), alt = $("community-alt");
  const qq = document.querySelector(".qq-link"), dc = document.querySelector(".dc-link");
  if (!primary || !alt || !qq || !dc) return;
  const [near, far] = LANG === "zh" ? [qq, dc] : [dc, qq];
  primary.appendChild(near);
  alt.appendChild(far);
}
applyCommunityOrder();

// The topbar overflow. Below 700px it is `display:contents` and the button is
// not drawn, so this only does anything on a desktop — but it binds either
// way, because a resize crosses the breakpoint without reloading.
(function () {
  const box = $("tbmore"), btn = $("tbmore-toggle");
  if (!box || !btn) return;
  const set = (open) => {
    box.classList.toggle("open", open);
    btn.setAttribute("aria-expanded", open ? "true" : "false");
  };
  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    set(!box.classList.contains("open"));
  });
  // `#dd-popover` counts as INSIDE, for the same reason the phone menu counts
  // it: the compute picker draws into the shared popover, which is a SIBLING
  // of this panel in the DOM, so picking a share would close the panel out
  // from under the control that is being used.
  document.addEventListener("click", (e) => {
    if (!e.target.closest("#tbmore, #dd-popover")) set(false);
  });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") set(false); });
  addEventListener("resize", () => set(false));
})();

// theme
(function () {
  const saved = localStorage.getItem("wfsim-theme");
  if (saved) document.documentElement.setAttribute("data-theme", saved);
  $("theme-toggle").addEventListener("click", () => {
    const cur = document.documentElement.getAttribute("data-theme");
    const dark = cur === "dark" || (!cur && matchMedia("(prefers-color-scheme: dark)").matches);
    const next = dark ? "light" : "dark";
    document.documentElement.setAttribute("data-theme", next);
    localStorage.setItem("wfsim-theme", next);
  });
})();

async function init() {
  // BEFORE ANYTHING TOUCHES THE DOM: a page from another build has markup
  // this file does not know, and the failure that produces is unreadable.
  checkBuildMatches();
  // …AND THEN THE FOOTER SAYS THE WHOLE THING. After the guard, never before:
  // the guard reads the token the page was SERVED with, and this overwrites it.
  {
    const el = $("build-stamp");
    if (el && BUILD_SHA !== "dev") el.textContent = `${BUILD_SHA} · ${BUILD_ID}`;
  }
  META = await api("/api/meta");
  {
    let all = null;
    try { all = await api("/api/i18n"); } catch (_) { all = null; }
    I18N = (LANG !== "en" && all && all[LANG]) || null;
    // Keep the OTHER locales' name tables for the search blob. English is not
    // among them — it is already on every entity as `name` or `name_en`.
    ALT_NAMES = all
      ? Object.entries(all).filter(([l]) => l !== LANG).map(([, v]) => v)
      : null;
    applyNameOverlay();
  }
  applyI18n();
  fillSelect("weapon", META.weapons);
  initWeaponSearch();
  const d = META.defaults;
  $("weapon").value = d.weapon;
  arcanes = arcanesFor(d.weapon, d.arcane);
  evoSel = { 1: null, 2: null, 3: null, 4: null, ...(d.evolutions || {}) };
  sim = defaultScenario();
  await loadBoard();          // before presets: the board's rows ARE build presets
  applyWeapon(d.weapon, d.mods);

  $("weapon").addEventListener("change", () => {
    switchWeapon($("weapon").value);
    if (!document.querySelector(".config-page").hidden) nav(weaponModPath($("weapon").value));
  });
  $("run-sim").addEventListener("click", runSim);
  $("run-opt").addEventListener("click", runOptimize);
  $("opt-mod-filter").addEventListener("input", renderOptModList);
  $("opt-arc-filter").addEventListener("input", renderOptArcanes);
  // How full a build must be, as a RANGE. The two ends are one setting: a
  // ceiling below the floor is not a scope, so each end pushes the other.
  $("opt-size").addEventListener("input", () => {
    // THE CEILING MAY BE 0, like every other axis's: 0–0
    // is "search it empty, and keep the marks". On this axis that is the bare
    // weapon, and reaching it by unmarking everything would cost the reader
    // exactly what 0–0 exists to protect.
    opt.size = Math.max(0, Math.min(8, Number($("opt-size").value) || 0));
    if (opt.min > opt.size) { opt.min = opt.size; $("opt-min").value = opt.min; }
    updateOptEstimate();
  });
  // THE FLOOR STARTS AT 0, AND 0 IS THE DEFAULT. Every
  // other axis here treats "nothing marked" as the EMPTY option — an unmarked
  // exilus slot stays empty, an unmarked arcane seat searches no arcane — and
  // the mods axis alone answered it with an error. `updateOptEstimate` has
  // claimed "an empty scope = the bare weapon, still a legal search" since it
  // was written, and a floor of 1 made that sentence false.
  // It costs nothing anywhere else: the moment anything is marked, the DERIVED
  // floor (every required mod, plus one pooled) is at least 1 and wins, so 0
  // and 1 differ in exactly the one case above.
  $("opt-min").addEventListener("input", () => {
    opt.min = Math.max(0, Math.min(8, Number($("opt-min").value) || 0));
    if (opt.min > opt.size) { opt.size = opt.min; $("opt-size").value = opt.size; }
    updateOptEstimate();
  });
  // updateOptEstimate is also the scope's auto-save, so finalists lands in the
  // active preset the same way every other search setting does.
  $("opt-finalists").value = optRun.finalists;
  $("opt-finalists").title = tr("how many builds survive to the last round — each is then run at the final-round run count beside this");
  $("opt-finalists").addEventListener("input", () => {
    optRun.finalists = Math.max(1, Math.min(100, Number($("opt-finalists").value) || 10));
    updateOptEstimate();
  });
  // (The final-round run count is not wired here: it is a PREFERENCE and
  // draws itself — `renderOptRuns`, outside both halves because it is in
  // neither preset. There is no CPU-thread box, because the topbar's compute
  // picker is the one place that question is answered.)
  // BEFORE ANY LIST IS READ: a riven is the FAMILY's as of 2026-08-25, and the
  // lists already on this machine are filed per weapon. It needs `META`, which
  // is why it is called here rather than beside the migrations it belongs with.
  foldRivensIntoOneList();
  initPresets();
  reattachOptimize(); // resume progress display if a server-side job survives a reload
  $("auto-forma").addEventListener("click", () => { autoForma(); renderMods(); });
  $("clear-mods").addEventListener("click", () => { slots.forEach((s, i) => { s.mod = null; s.pol = innate[i]; }); renderMods(); });
  document.addEventListener("click", (e) => {
    // `.rv-pick` opens the same popover from the riven tab, so its own click
    // must not be the click that closes it again.
    if (!e.target.closest(".popover") && !e.target.closest(".slot") && !e.target.closest(".rv-pick")) closePopovers();
  });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") closePopovers(); });
  window.addEventListener("popstate", route);
  // Reloading or closing the tab KILLS a run in progress: the worker dies with
  // the page. That is not a limitation we can engineer around — measured
  // 2026-07-30, a SharedWorker is terminated too, the moment its last client
  // disconnects, whether or not it is busy.
  //
  // The browser's own unload prompt is the only guard that runs before the page
  // goes, and it cannot be replaced by an inline one — so this is the single
  // place the project's no-native-dialogs rule does not reach. It only fires
  // while something is actually running.
  window.addEventListener("beforeunload", (e) => {
    if (optJobId == null) return;
    e.preventDefault();
    e.returnValue = ""; // required by older engines to trigger the prompt
  });
  // In-app navigation: any same-origin root-relative link routes client-side
  // (modified clicks — new tab etc. — keep native behavior; a full page load
  // also works thanks to the server's SPA fallback).
  document.addEventListener("click", (e) => {
    const a = e.target.closest('a[href^="/"]');
    if (!a || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
    e.preventDefault();
    nav(a.getAttribute("href"));
  });
  route();
  // A language switch reloads the page; the pre-switch build is stashed in
  // sessionStorage and restored here so nothing is lost.
  const stash = sessionStorage.getItem("wfsim-lang-stash");
  if (stash) {
    sessionStorage.removeItem("wfsim-lang-stash");
    try { restoreState(JSON.parse(stash)); } catch (_) {}
  }
}

// ---- views: '/' = the weapon list (home); '/weapons/<Wiki_Name>' = the
// BUILDER; '/weapons/<Wiki_Name>/simulator' = the SIMULATOR (tests the
// current build); '/weapons/<Wiki_Name>/optimizer' = the OPTIMIZER — one
// tab per module (the page's three modules, "Simulator
// sits in the middle"). URLs mirror wiki page names
// (display name, spaces → '_'); an id appears only where that name is shared
// by two weapons — see `urlSlug`.
// The weapon <select> stays the internal source of truth; the home grid
// and the path just drive it.
// The WIKI PAGE name behind a weapon's display name. A parenthesised
// qualifier is OURS — "Larkspur Prime (Atmosphere)" is one wiki page with two
// stat columns, and we ship the ground one — so it never reaches a URL.
// `build_site_app.py`'s `wiki_name` splits on the same " (".
const wikiWeaponName = (w) => (w.name_en || w.name).split(" (")[0];
const wikiSlug = (w) => wikiWeaponName(w).replace(/ /g, "_");

/// THE PATH SEGMENT A WEAPON LIVES AT — the wiki page name, and the ID where
/// that name is not this weapon's alone.
///
/// URLs mirror wiki page names and ids never appear, which holds for every
/// weapon whose display name is its own. Two Kitgun slots are ONE wiki page
/// and two roster entries, so the rule maps them onto one address and the
/// loser of that collision has NO URL AT ALL — nothing to link, nothing to
/// prerender. An id is uglier than a wiki name and it is reachable.
///
/// THE LOWEST ID KEEPS THE WIKI NAME, so `/weapons/Tombfinger` is a stable
/// address rather than one that follows roster order, and it stays the one the
/// Slot control swaps INSIDE — switching slots does not navigate, which is
/// what makes a Kitgun one page. `url_slug` in `build_site_app.py` is the same
/// rule and has to stay it, or a link points at a page that was never written.
let SLUG_OWNER = null;
const urlSlug = (w) => {
  // NOT CACHED BEFORE THE ROSTER LANDS: an empty `META.weapons` would freeze an
  // empty map, after which every weapon's path is its id forever.
  if (!SLUG_OWNER && (META.weapons || []).length) {
    SLUG_OWNER = new Map();
    for (const x of META.weapons || []) {
      const g = wikiSlug(x);
      if (!SLUG_OWNER.has(g) || x.id < SLUG_OWNER.get(g)) SLUG_OWNER.set(g, x.id);
    }
  }
  const g = wikiSlug(w);
  return !SLUG_OWNER || SLUG_OWNER.get(g) === w.id ? g : w.id;
};
const weaponPath = (id) => {
  const w = (META.weapons || []).find((x) => x.id === id);
  return "/weapons/" + (w ? urlSlug(w) : id);
};
function nav(path) {
  const moved = location.pathname !== path;
  if (moved) history.pushState(null, "", path);
  route();
  // A NEW PAGE STARTS AT THE TOP.
  //
  // `pushState` does not touch the scroll position, so a click from halfway
  // down the home grid lands on a weapon page ALREADY scrolled into the middle
  // of a panel nobody chose — on every in-app link, since they all come here.
  //
  // ONLY ON A FORWARD MOVE, and only when the path actually changed. `route()`
  // is called on its own for a re-render — a language switch, a share import,
  // every check in `scripts/` — and jumping those to the top would throw away a
  // position the reader never left. BACK and FORWARD go through `popstate`,
  // which never reaches this line, so the browser's own restored position
  // stands and `history.scrollRestoration` is left alone.
  //
  // AFTER the `pushState`, never before. The entry being LEFT records its
  // scroll at the moment the new one is pushed, so scrolling first would file
  // "top of page" against the page the reader is about to come back to.
  //
  // `instant`, not the default `auto`: `auto` defers to CSS, and a smooth
  // scroll from the bottom of a 500-weapon grid is an animation nobody asked
  // for on top of a navigation.
  if (moved) window.scrollTo({ top: 0, left: 0, behavior: "instant" });
}
function route() {
  // A SHARED LINK is answered before anything else on the page is drawn for
  // it, and the query is stripped afterwards so a refresh does not import the
  // same build a second time. `?b=` only ever ADDS — see importShare.
  const shared = SHARE_ENABLED && new URLSearchParams(location.search).get(SHARE_PARAM);
  // A LINK POSTED WHILE SHARING WAS ON still has to open something. The query
  // is stripped either way, so a refresh cannot retry it; with sharing off the
  // visitor gets the weapon's own page and a line saying why, which is a page
  // rather than a blank.
  if (!SHARE_ENABLED && new URLSearchParams(location.search).get(SHARE_PARAM)) {
    history.replaceState(null, "", location.pathname);
    setTimeout(() => presetToast(tr("sharing is off for now — this link opened the weapon instead")), 900);
  }
  if (shared) {
    history.replaceState(null, "", location.pathname);
    // DRAW THE PAGE FIRST, then land the payload into it. Returning here
    // instead left the visitor on the home grid staring at nothing until they
    // refreshed: `importShare` fills the editor in, but which module is
    // VISIBLE is this function's job and it had been skipped. The query is
    // already stripped, so this re-entry takes the ordinary path.
    route();
    importShare(shared);
    return;
  }
  // `/support` is a page of the SHELL, not a fourth module and not a weapon's
  // tab: it belongs to no weapon, so it sits beside the home grid rather than
  // under /weapons/<name>.
  const support = /^\/support\/?$/.test(location.pathname);
  const bench = /^\/benchmark\/?$/.test(location.pathname);
  const dl = /^\/download\/?$/.test(location.pathname);
  const m = (support || bench || dl) ? null : location.pathname.match(/^\/weapons\/([^/]+?)(\/simulator|\/optimizer|\/rivens|\/enemies)?\/?$/);
  // A hand-typed URL is not the canonical slug. Fold case and treat spaces
  // (and their %20) as underscores, so "/weapons/Dual Toxocyst" reaches the
  // same weapon as "/weapons/Dual_Toxocyst" instead of silently falling back
  // to the home grid — which reads as "the site sent me somewhere else".
  const slug = m && decodeURIComponent(m[1]).trim().toLowerCase().replace(/[\s-]+/g, "_");
  // AN ID ANSWERS FIRST. `/weapons/tombfinger_secondary` is that weapon's own
  // address; matching the wiki slug first would hand it to the entry that owns
  // the shared name and the second slot would be unreachable again.
  const w = slug && ((META.weapons || []).find((x) => x.id === slug)
    || (META.weapons || []).find((x) => wikiSlug(x).toLowerCase() === slug));
  // The active module: "" = builder, "simulator", "optimizer".
  const mod = (w && m[2]) ? m[2].slice(1) : "";
  document.body.classList.toggle("on-home", !w && !support && !bench && !dl);
  document.body.classList.toggle("on-support", support);
  document.body.classList.toggle("on-benchmark", bench);
  document.body.classList.toggle("on-download", dl);
  document.body.classList.toggle("on-simulator", mod === "simulator");
  document.body.classList.toggle("on-optimizer", mod === "optimizer");
  document.body.classList.toggle("on-rivens", mod === "rivens");
  document.body.classList.toggle("on-enemies", mod === "enemies");
  $("home-page").hidden = !!w || support || bench || dl;
  $("support-page").hidden = !support;
  $("bench-page").hidden = !bench;
  $("download-page").hidden = !dl;
  // The nav says where you are. `data-nav` rather than a path compare: the
  // roster lives at "/" and a path compare there matches every page.
  const here = bench ? "benchmark" : (!w && !support && !dl) ? "home" : "";
  document.querySelectorAll(".tnav").forEach((a) => {
    a.classList.toggle("sel", a.dataset.nav === here);
  });
  document.querySelector(".config-page").hidden = !w;
  const modTitle = { simulator: " · Simulator", optimizer: " · Optimizer", rivens: " · Rivens", enemies: " · Enemies" }[mod] || "";
  // The home title carries the SEARCH TERMS, not the headline: nobody looks
  // for "Simulacrum Prime", and the tab/result/share-card is the one place
  // that has to be found rather than enjoyed. The joke
  // stays on the page, which is where a player meets it.
  document.title = support ? `${tr("Support")} — WFSim`
    : dl ? `${tr("WFSim for Windows")} — WFSim`
    : bench ? `${tr("Benchmark")} — WFSim`
    : w ? `${w.name}${modTitle} — WFSim` : "WFSim — Ultimate Warframe Calculator";
  if (support) {
    renderSupport();
  } else if (dl) {
    renderDownloadPage();
  } else if (bench) {
    renderBenchBoard();
  } else if (w) {
    // `?mode=` — HOW the linked build is played, carried by the link that made
    // it. A board row is a weapon AND a mode ("Burston Prime, base form"), so a
    // link that dropped the second half landed on a page measuring something
    // else.
    //
    // The QUERY, not a path segment: the path mirrors the wiki's page name and
    // its next segment is already the module (`/simulator`), so a mode there
    // would be a third meaning for one slot.
    //
    // READ BEFORE THE SWITCH. Loading a weapon restores its preset, and that
    // rewrites the address to the weapon's plain path — so by the time the
    // weapon is on screen the query is already gone, and the mode with it.
    const wantMode = new URLSearchParams(location.search).get("mode");
    // WHICH RULER, from a board row. A row is a build AND the ruler it was
    // measured under; arriving with only the build gives you a number you
    // cannot reproduce, and arriving with neither gave you the FIRST ruler's
    // leader whichever board you clicked.
    const wantBench = new URLSearchParams(location.search).get("bench");
    // WHICH OF THE TWO LEADERS — see the link builder. Null when the link
    // predates the parameter, which means "whichever row leads".
    const rivenParam = new URLSearchParams(location.search).get("riven");
    const wantRiven = rivenParam === null ? null : rivenParam === "1";
    if ($("weapon").value !== w.id) {
      switchWeapon(w.id);
    }
    if (wantBench) applyBenchLink(w, wantBench, wantMode, wantRiven);
    if (wantMode && (w.modes || []).includes(wantMode)) {
      if (wantMode !== mode) {
        mode = wantMode;
        renderMode();
        renderMods();
        refreshPanel();
      }
      // ...and put it back on the address bar, which the restore just cleared.
      // Kept rather than stripped: the link has to survive a refresh and a
      // bookmark, and `renderMode` rewrites it when the visitor changes mode so
      // it never says something the page is not doing.
      if (new URLSearchParams(location.search).get("mode") !== wantMode) {
        const q = new URLSearchParams();
        if (wantBench) q.set("bench", wantBench);
        if (rivenParam !== null) q.set("riven", rivenParam);
        q.set("mode", wantMode);
        history.replaceState(null, "", `${location.pathname}?${q}`);
      }
    }
    $("module-tabs").innerHTML =
      `<a class="mtab ${mod === "" ? "sel" : ""}" href="${weaponPath(w.id)}">${tr("Builder")}</a>` +
      `<a class="mtab ${mod === "simulator" ? "sel" : ""}" href="${weaponPath(w.id)}/simulator">${tr("Simulator")}</a>` +
      `<a class="mtab ${mod === "optimizer" ? "sel" : ""}" href="${weaponPath(w.id)}/optimizer">${tr("Optimizer")}</a>` +
      `<a class="mtab ${mod === "rivens" ? "sel" : ""}" href="${weaponPath(w.id)}/rivens">${tr("Rivens")}</a>` +
      `<a class="mtab ${mod === "enemies" ? "sel" : ""}" href="${weaponPath(w.id)}/enemies">${tr("Enemies")}</a>`;
    // Arriving on the simulator: refresh its build summary (builder edits
    // don't re-render sim views while they are hidden). The SCENARIO is one
    // state shared with the optimizer, so each tab redraws its own copy of
    // those fields on arrival — the other tab may have moved them, and the
    // tabs are CSS-hidden rather than re-rendered.
    if (mod === "simulator") renderSim();
    if (mod === "optimizer") { renderOptEnemy(); updateOptEstimate(); }
    if (mod === "rivens") renderRivens();
    if (mod === "enemies") renderEnemies();
  } else {
    renderHome();
  }
}

// The current module's path suffix — weapon switches (search, select,
// preset load) keep the visitor on the tab they are on.
const modSuffix = () => (location.pathname.match(/\/(simulator|optimizer|rivens)\/?$/) || [null, ""])[1];
const weaponModPath = (id) => weaponPath(id) + (modSuffix() ? "/" + modSuffix() : "");

// The home grid groups by EQUIPMENT SLOT in loadout order:
// one flat list stops being readable as soon as the roster holds more than one
// slot's worth. A slot with no weapons renders nothing at all rather than an
// empty heading, and an unknown slot still gets its weapons shown.
// Equipment slots, in the order the arsenal shows them. "sentinel" is a real
// slot, not a kind of primary: a sentinel weapon rides the companion and draws
// from the rifle mod pool without ever occupying a weapon slot.
const SLOT_ORDER = ["primary", "secondary", "kitgun", "melee", "sentinel", "archgun"];
const SLOT_LABEL = { primary: "Primary", secondary: "Secondary", melee: "Melee",
  kitgun: "Kitguns", sentinel: "Sentinel Weapons", archgun: "Arch-Guns", other: "Other" };

// WHAT AN ARCANE SEAT IS CALLED, which is the weapon-group label everywhere but
// one: the group heading is the plural "Kitguns" because it heads a list of
// them, and "add Kitguns arcane" is not a sentence. One override rather than a
// second full table, so a seat added later still reads.
const ARC_POOL_LABEL = { ...SLOT_LABEL, kitgun: "Kitgun" };

/// WHICH GROUP A WEAPON IS LISTED UNDER — its slot, except that a MODULAR
/// weapon gets its own.
///
/// A Kitgun is one weapon with a roster entry per slot, so listing it by slot
/// puts the same name and the same picture in two groups, both linking to the
/// same page. Its own group says what it actually is, and says it once.
const weaponCategory = (w) => (w.assembly ? "kitgun" : (w.slot || ""));

/// ONE CARD PER MODULAR WEAPON. The chamber IS the weapon — one mastery track,
/// one riven, one wiki page — so its two slot entries are one entry here, and
/// which one the card opens is settled on the page by the Slot control.
///
/// IT OPENS THE PRIMARY, stated rather than left to roster ORDER — which
/// happens to be alphabetical and happens to put `_primary` before
/// `_secondary`. That is the right answer arrived at by accident, and an
/// accident stops being right the day a chamber is named so that it is not.
const oneCardPerChamber = (ws) => {
  const best = new Map();
  ws.forEach((w) => {
    const key = w.assembly ? w.assembly.chamber : w.id;
    const cur = best.get(key);
    if (!cur || (w.slot === "primary" && cur.slot !== "primary")) best.set(key, w);
  });
  // A Map keeps insertion order, so this is the roster's order with the
  // duplicates removed — the same list every caller sorted before.
  return [...best.values()];
};

function renderHome() {
  const grid = $("weapon-grid");
  if (!grid) return;
  const card = (w) => {
    const tags = [
      // TRANSLATED, like the group heading above it. `tr` falls through to the
      // English for a subtype no overlay names, so this costs nothing on the
      // ones nobody has translated and stops the Kitgun card reading half in
      // one language.
      `<span class="tag">${escHtml(tr(w.subtype || w.mod_class))}</span>`,
      w.uses_evo2 ? `<span class="tag">Incarnon</span>` : "",
      w.sentinel ? `<span class="tag">Sentinel</span>` : "",
    ].join("");
    return `<a class="wcard" href="/weapons/${urlSlug(w)}">
      ${imgTag(IMG(w.image), "wc-img")}
      <div class="wc-info">
        <div class="wc-name">${w.name}</div>
        <div class="wc-tags">${tags}</div>
      </div>
    </a>`;
  };
  const all = oneCardPerChamber(META.weapons || []);
  const groups = SLOT_ORDER
    .map((s) => [s, all.filter((w) => weaponCategory(w) === s)])
    .filter(([, ws]) => ws.length);
  const rest = all.filter((w) => !SLOT_ORDER.includes(weaponCategory(w)));
  if (rest.length) groups.push(["other", rest]);
  grid.innerHTML = groups.map(([slot, ws]) => `
    <section class="wgroup">
      <h3 class="wgroup-h">${tr(SLOT_LABEL[slot] || slot)}</h3>
      <div class="wgrid">${ws.map(card).join("")}</div>
    </section>`).join("");
}

// ---- THE BOARD: one ruler, every weapon ---------------------------------
//
// WHAT IT IS FOR: the fastest way to see which weapons are
// strong, and which nobody has measured yet — so the empty rows are as much the
// point as the full ones. A visitor who fills one is finding an optimum for
// everybody, and a row that looks impossible is how a bug in this engine gets
// found from outside it.
//
// ONE NUMBER PER WEAPON, its best. Everything else about that weapon — the
// other builds, the deeper ranks — lives on the weapon's own page, which is
// where a click goes. That is what keeps this page O(weapons) whatever the
// board grows to, and what will let a benchmark hold a hundred builds per
// weapon without any of them being fetched to draw this.
let benchPick = null;

const benchList = () => META.benchmarks || [];
// THE LIST IS ALREADY IN THE RIGHT ORDER: `benchmarks_data::all()` puts the
// PRIMARY ruler first, so `[0]` is the one a reader should meet. It was path
// order until a second ruler arrived and put a brand-new empty board in front
// of the populated one.
const benchCurrent = () =>
  benchList().find((b) => b.id === benchPick) || benchList()[0] || null;

/// HOW A WEAPON WAS PLAYED, in words. The ids are the vocabulary a submission
/// and a board row use; this is what a reader sees.
///
/// NAMED FOR THE FORM IT FIRES, not for the mode's own id: a Cernos Prime's
/// `base` mode is its CHARGED shot, because that is what the arsenal hands
/// you, and calling it "base form" would be true of the id and false of the
/// weapon. The mode ids are roles; the labels are the weapon's own words.
/// THE FORM A CYCLE SPENDS — the gauge-fed one, which is the only thing that
/// tells a cycle apart from a free alternate.
const earnedForm = (w) =>
  ((w || {}).forms || []).find((x) => !x.is_default && x.gauge_switched) || null;

/// A MODE'S NAME, which is its FORM's — before it is told from its neighbour.
const bareModeLabel = (w, id) => {
  // NAMED AFTER THE FORM IT SPENDS, not after a product: the Mausolon buys its
  // charged shot with five kills and has no Genesis anywhere, so "Incarnon
  // cycle" names something sixty-nine weapons have and the seventieth does not.
  if (isCycleMode(id)) {
    const f = earnedForm(w);
    return f ? trF("{form} cycle", { form: tr(f.name) }) : tr("cycle");
  }
  // A MODE'S NAME IS FIXED, and the stance changes what it is WORTH. Deriving
  // it from the equipped stance breaks the one question a stance slot exists
  // to answer: "which stance is best for the neutral combo" cannot be asked if
  // the two builds call that mode different things.
  const f = modeForm(w, id);
  return f ? tr(f.name) : tr(id);
};

const modeLabel = (w, id) => {
  const name = bareModeLabel(w, id);
  // TWO MODES CAN ARRIVE AT ONE NAME, and then it names neither: a weapon with
  // two shots has a cycle per shot, and both cycles spend the same form. WHICH
  // SHOT is the difference, so that is what is added — and only where a
  // sibling mode would read the same, so one of each is untouched.
  const twin = ((w || {}).modes || []).some((o) => o !== id && bareModeLabel(w, o) === name);
  const f = twin && modeForm(w, id);
  if (!f) return name;
  // A CYCLE IS TOLD FROM A CYCLE BY THE FORM THAT FILLS ITS GAUGE, which is
  // the one thing the two do differently; anything else is told apart by how
  // it is fired, which is what `firedForm` adds.
  return isCycleMode(id)
    ? trF("{form} cycle ({base})",
      { form: tr((earnedForm(w) || {}).name || ""), base: tr(f.name) })
    : firedForm(f);
};

/// One entry per WEAPON AND MODE: its best row under `id`, or null where nobody
/// has submitted. A weapon with no row is not an error, it is the invitation —
/// and a weapon with a row for one mode and none for the other is the sharpest
/// version of it, because the missing one is a question somebody can answer
/// this afternoon.
/// WHICH BUILDS THE BOARD IS SHOWING — `all`, `plain` or `riven`.
///
/// The RANKING is one list: a riven build does not always beat a plain one, so
/// ranking them apart would publish a comparison the fight does not make. What this decides is which subset each weapon's SHOWN
/// row is drawn from — and the reason it exists is `plain`: under `all`, a
/// weapon whose riven build wins hides its plain build entirely, and those are
/// the builds most readers can actually make.
let benchRivenView = "all";
const BENCH_VIEWS = [
  ["all", "All builds"],
  ["plain", "No riven"],
  ["riven", "Riven only"],
];
const rowHasRiven = (r) => !!(r && r.riven);

/// A BOARD ROW'S RIVEN, AS A LOCAL ITEM — the name it takes on the reader's
/// machine, DERIVED from the shape so opening the same row twice reuses the
/// one riven instead of stacking copies.
///
/// A row cannot name somebody's riven: the item is on one machine and what the
/// board holds is a SHAPE. So the reader's copy is named after the shape, which
/// is also the only honest name for it — it is not anyone's roll, it is what
/// that shape is worth at its ceiling.
const boardRivenName = (rv) =>
  `${tr("board")} · ${(rv.bonuses || []).join(" / ")}${rv.malus ? ` − ${rv.malus}` : ""}`;

/// The definitions `builtinBuilds` met, by the mod id it put in the slot.
///
/// A REGISTRY RATHER THAN A WRITE, so listing the board's builds stays pure:
/// a reader who never opens a riven row never gets one in their riven list.
/// `restoreState` is where it lands, because that is the moment the build is
/// actually being taken: copying a board build also copies its riven
/// locally.
const boardRivenDefs = {};
/// One board riven as a riven PRESET's state — the editor's own shape.
const boardRivenState = (rv) => ({
  bonuses: (rv.bonuses || []).map((id, i) => ({ id, roll: (rv.rolls || [])[i] ?? 1 })),
  malus: rv.malus
    ? { id: rv.malus, roll: (rv.rolls || [])[(rv.bonuses || []).length] ?? 1 }
    : null,
  rank: 8,
  polarity: "madurai",
});
const inBenchView = (r) =>
  benchRivenView === "all"
  || (benchRivenView === "riven") === rowHasRiven(r);

const benchEntries = (id) => {
  const out = [];
  for (const w of META.weapons || []) {
    for (const m of w.modes || ["base"]) {
      const rows = (BOARD[w.id] || [])
        .filter((r) => r.benchmark === id && (r.mode || "base") === m)
        .filter(inBenchView);
      out.push({ w, mode: m,
        row: rows.length ? rows.reduce((a, r) => (r.score > a.score ? r : a), rows[0]) : null });
    }
  }
  return out;
};

/// HOW MANY BUILDS ARE IN THE LIBRARY, asked once per page and cached.
///
/// The board is a STATIC FILE committed to the repo and served from the CDN,
/// which is what makes it fast and free — and what makes it only as fresh as
/// the last scoring run. Moving it behind a service to make it live would trade
/// the fast, unblockable path for a slow one; instead the file stays, and this
/// asks the library the one fact the file cannot carry about itself.
///
/// A COUNT is all that comes back. It is enough for the sentence it is in and
/// it is the most the store can honestly say: nothing about a submitter is kept
/// there, so nothing about one can be reported here.
let benchPending = null;
function benchPendingAsk() {
  if (benchPending !== null) return;
  benchPending = "asking";
  fetch("/api/board/pending")
    .then((r) => (r.ok ? r.json() : null))
    .then((j) => {
      benchPending = j && j.ok ? j : "failed";
      // Only a repaint, and only if the reader is still on the board — the
      // number is a footnote and never worth stealing a render for.
      if ($("bench-board")) renderBenchBoard();
    })
    .catch(() => { benchPending = "failed"; });
}

/// The footnote itself. Silent unless the library is genuinely AHEAD of the
/// board: "0 waiting" is furniture, and a board that IS current should simply
/// look current.
///
/// IT PROMISES NOTHING ABOUT WHEN. The schedule fires three times an hour, but
/// a scheduled run STANDS DOWN while the engine fingerprint has moved — the
/// push that moved it owns that rescore — so "the next run is within 20
/// minutes" was a promise the pipeline does not keep and the page cannot check.
/// How far behind the board is, it can say exactly.
function benchPendingNote(cur) {
  benchPendingAsk();
  if (!benchPending || typeof benchPending !== "object") return "";
  const scored = (cur && cur.submissions) || 0;
  const waiting = benchPending.count - scored;
  // AND NEVER A NEGATIVE ONE. A ruler that has just been added has scored
  // nothing, and a store that has expired records can sit below what the last
  // run read; both are real and neither is "builds are waiting".
  if (!(waiting > 0) || !scored) return "";
  return ` <span class="bench-pending">${escHtml(
    tr("· {n} more submitted since this board was scored")
      .replace("{n}", waiting))}</span>`;
}

function renderBenchBoard() {
  const box = $("bench-board");
  if (!box || !META) return;
  const picker = $("bench-picker");
  const bs = benchList();
  const cur = benchCurrent();
  if (picker) {
    // A RULER IS PICKED, not scrolled past. Two today and dozens later, so it
    // is a list of chips rather than a stack of tables — the page shows one
    // ranking at a time because two rankings side by side is a comparison
    // nobody asked for yet.
    picker.innerHTML = bs.map((b) => `<button type="button" class="bchip${
      cur && b.id === cur.id ? " sel" : ""}" data-bench="${escHtml(b.id)}">${escHtml(tr(b.name))}</button>`).join("");
    picker.querySelectorAll("[data-bench]").forEach((el) => {
      el.onclick = () => { benchPick = el.dataset.bench; renderBenchBoard(); };
    });
  }
  if (!cur) { box.innerHTML = ""; return; }
  // …AND WHICH BUILDS. A separate row of chips from the ruler's, because they
  // are separate questions: the ruler is the FIGHT, this is which entrants are
  // being listed. Drawn on every ruler, since every ruler takes both kinds.
  const view = $("bench-view");
  if (view) {
    view.innerHTML = BENCH_VIEWS.map(([v, label]) => `<button type="button" class="bchip${
      benchRivenView === v ? " sel" : ""}" data-bview="${v}">${escHtml(tr(label))}</button>`).join("");
    view.querySelectorAll("[data-bview]").forEach((el) => {
      el.onclick = () => { benchRivenView = el.dataset.bview; renderBenchBoard(); };
    });
  }
  // THE RULES, under the ruler that makes them. Collapsed by default: a reader
  // who wants the ranking should not have to scroll a standard to reach it, and
  // one who doubts a row should not have to leave the page to check the terms.
  const rules = $("bench-rules");
  if (rules) {
    const rs = cur.rules || [];
    rules.innerHTML = !rs.length ? "" : `<details class="brules">
      <summary>${escHtml(tr("What this benchmark measures"))}</summary>
      <ul>${rs.map((x) => `<li>${escHtml(tr(x))}</li>`).join("")}</ul>
    </details>`;
  }
  // THE RULER'S FIGHT, DRAWN. The rules above say it in sentences; this is
  // the same fight as a picture, by the same component the simulator uses, so
  // the two cannot describe different arenas.
  //
  // READ-ONLY, and doubly so: `mountArena` is told, and the scene also asks
  // `officialScenarioActive` at the gesture — a board's positions are pinned.
  const bar = $("bench-arena");
  if (bar) {
    const sc = { ...defaultScenario(), ...(cur.scenario || {}) };
    sc.player_at = [...(sc.player_at || [0, 0])];
    sc.target_at = [...(sc.target_at || [0, CONTACT_M])];
    // THE RULER'S OWN CROWD, never `= []` and `= null`: a benchmark CAN have
    // a formation, and hardcoding its absence draws a single body for a
    // 361-body fight while the rules beside it say otherwise. A picture that
    // contradicts the standard beside it
    // is worse than no picture.
    sc.formation = (sc.formation || []).map((f) => ({ ...f, at: [...f.at] }));
    sc.aim_at = sc.aim_at ? [...sc.aim_at] : null;
    mountArena(bar, sc, (allEnemies().find((e) => e.id === sc.enemy) || allEnemies()[0]), { readonly: true });
  }
  const entries = benchEntries(cur.id);
  // SORTED BY THE BENCHMARK'S OWN METRIC — it says which one it is measured in
  // (`scenario.metric`), and a second ruler may answer differently. Unmeasured
  // weapons sort last whatever the metric: a zero is not a low score, it is no
  // score, and putting it among the low ones would read as one.
  const metric = metricLabel(metricOf((cur.scenario || {}).metric));
  const rows = entries
    .slice()
    .sort((a, b) => (b.row ? b.row.score : -1) - (a.row ? a.row.score : -1));
  const measured = rows.filter((r) => r.row).length;
  box.innerHTML = `
    <div class="bench-meta">${escHtml(
      tr("{n} of {t} entries measured · ranked by {m}")
        .replace("{n}", measured).replace("{t}", rows.length).replace("{m}", metric))}${
      benchPendingNote(cur)}</div>
    <div class="bench-rows">${rows.map(({ w, mode, row }, i) => `
      <a class="brow${row ? "" : " none"}" href="/weapons/${urlSlug(w)}${
        // WHICH RULER YOU CAME FROM, not just how the weapon is played:
        // without it the link lands on whatever official build is first, and
        // the two boards' leaders are both called "#1 · Incarnon cycle". It
        // selects the FIGHT as well as the build, because a board row is a
        // build AND the ruler it was measured under — arriving with only the
        // build is arriving with a number you cannot reproduce.
        // …AND WHICH OF THE TWO LEADERS. The board holds a riven row and a
        // plain one per weapon and mode, both called "#1", and the ruler and
        // the mode tell them apart no better than they told the two rulers
        // apart in 2026-08-08. Clicking the leader of the "riven only" view
        // opened the PLAIN leader — a different build, with a riven slot the
        // landing page then had nothing to put in.
        //
        // STATED EITHER WAY (`riven=1` / `riven=0`) rather than only when
        // there is one, so an ABSENT parameter keeps meaning what it always
        // meant. The MODE is stated on the same terms: a row is one weapon in
        // one mode whether or not it has a second.
        `?bench=${encodeURIComponent(cur.id)}&mode=${encodeURIComponent(mode)}${
          row ? `&riven=${rowHasRiven(row) ? 1 : 0}` : ""}`}">
        <span class="brank">${row ? `#${i + 1}` : "—"}</span>
        ${imgTag(IMG(w.image), "bimg")}
        <span class="bname">${escHtml(w.name)}${
          // ALWAYS NAMED, including a weapon with one way to be fired — the
          // rule the simulator's build card already carries. A blank beside a
          // neighbour that names its mode reads as "no mode", and this is where
          // weapons are COMPARED.
          ` <span class="bmode">${escHtml(modeLabel(w, mode))}</span>`}${
          // THE BOARD IS WHERE WEAPONS ARE COMPARED, so it is the one place a
          // weapon with unmodelled parts must not look like one without them.
          // A Stug row is four admissions deep and a Torid row is exact; side
          // by side and unmarked they read as the same kind of number.
          // The mark is the banner's own ◈ and carries the same sentences.
          (w.unmodeled || []).length
            ? ` <span class="bgap" title="${escHtml(
                tr("not modelled on this weapon — the numbers below are a floor, not its full output")
                + ": " + gapsOf(w).map(trGap).join(" · "))}">◈</span>`
            : ""}</span>
        <span class="bscore">${row
          ? escHtml(row.shown != null ? String(row.shown) : row.score.toFixed(4))
          : `<span class="bnone">${escHtml(tr("not measured"))}</span>`}</span>
      </a>`).join("")}</div>`;
}

// ---- support: the donation channels -------------------------------------
// A channel is drawn only when it HAS a working link. An option that does not
// work yet is worse than one that is not offered, so an entry with an empty
// `url` renders nothing — and filling that url in is the whole of adding one.
//
// A CHANNEL A READER CANNOT PAY THROUGH IS NOT AN OPTION.
// Ko-fi wants a card or PayPal, which is not how anyone in mainland China pays
// for anything — so a Chinese reader was being shown one channel and offered
// none. The ones that match the display language come first.
//
// ORDERED, NEVER FILTERED, which is the rule the topbar's community links
// follow and for the same reason: a reader who can use the other one still has
// to be able to find it. `locale: null` means "works anywhere" and sorts
// between the two. The per-locale ORDER is all that lives here — the shape a
// domestic channel wants (a scan code rather than a link) is not knowable
// until there is a real payload to draw, so that waits for one.
const chRank = (c) => (c.locale === LANG ? 0 : c.locale ? 2 : 1);
const SUPPORT_CHANNELS = [
  {
    id: "kofi",
    // THE ACCOUNT IS THE PROJECT, AND THE PAGE BEHIND IT IS A PERSON. `ko-fi.com/wfsim` reads as the same thing as `wfsim.app` at
    // the one moment a reader is deciding whether they are in the right place;
    // an account named after the author does not, and that half-second sits
    // exactly where the money is. The FIRST-PERSON half is not lost — it moves
    // to the Ko-fi page's own bio, which is where poe.ninja puts it too.
    name: "Ko-fi",
    url: "https://ko-fi.com/wfsim",
    locale: "en",
    // ONE-OFF ONLY. Ko-fi's memberships are a subscription with perks, which
    // is the one shape DE's non-commercial rule does not allow — they stay
    // switched off in the account, and so do its shop and commissions.
    //
    // $3 IS THE FLOOR, chosen from evidence rather than picked. Cialdini & Schroeder 1976: a request that legitimises a
    // paltry contribution takes compliance from 29% to 50% with NO drop in the
    // mean gift. Wikimedia's banner testing settles on a $3 suggestion.
    // Adena/Huck/Rasul: a higher suggestion raises the mean and LOWERS the
    // participation rate — and at this size participation is the one that
    // compounds.
    //
    // The ladder above the floor is Ko-fi's (x1/x3/x5 plus a free field), so
    // nothing here repeats it — a second copy of a ladder is a staler copy.
    what: "One-off, in USD, from $3. Card or PayPal, no account needed.",
  },
  {
    id: "patreon",
    name: "Patreon",
    // EMPTY UNTIL THE ACCOUNT EXISTS, which is the rule above: an option that
    // does not work yet is worse than one that is not offered, and filling this
    // url in is the whole of adding the channel.
    //
    // TWO CHANNELS, TWO JOBS. Ko-fi is the one-off and
    // Patreon is the month, and the split is what keeps either from being a
    // worse version of the other. There is no third: the donation-page
    // evidence is about REMOVING choices at the moment of decision, and a
    // developer-facing channel belongs in the README, where developers are.
    //
    // WHAT THE MONTH BUYS is stated on the page and bounded there: order and
    // company, never product — never the weapon queue, since a roster fills
    // and a perk that quietly expires is worse than none.
    url: "",
    locale: null,
    what: "Monthly, in USD, from $5. The channel where the work is discussed, and your reports read first.",
  },
];

/// HOW MUCH OF THIS THE READER HAS ACTUALLY USED — on their own machine, and
/// nowhere else.
///
/// The strongest thing this page can say is not what the project is, it is what
/// it has already done FOR the person reading, and that is a number the app can
/// count rather than claim. It is two integers in one key: engagements are what
/// the machine actually paid for (a run at the rulers' 1000 is a thousand of
/// them), and simulations are what the reader remembers doing.
///
/// IT NEVER LEAVES THE BROWSER, and the page says so where it prints it —
/// which is the same promise the board makes about a submission, made in the
/// one place a reader might reasonably suspect otherwise.
///
/// TWO INTEGERS, which is the whole of its storage budget: a measurement costs
/// its summary and never its replay, and a counter that grew per run would be
/// the same mistake one size down.
const SUPPORT_USE = "wfsim-use";
function supportUse() {
  try {
    const v = JSON.parse(localStorage.getItem(SUPPORT_USE) || "{}");
    return { sims: v.sims | 0, engagements: v.engagements | 0 };
  } catch (_) { return { sims: 0, engagements: 0 }; }
}
function noteSimRun(engagements) {
  const v = supportUse();
  v.sims += 1;
  v.engagements += Math.max(1, engagements | 0);
  try { localStorage.setItem(SUPPORT_USE, JSON.stringify(v)); } catch (_) { /* private mode */ }
}

/// HOW MANY PEOPLE HAVE CHIPPED IN — a COUNT, and nothing else.
///
/// Social proof is the one lever here with a replicated experiment behind it
/// (Cialdini & Schroeder's paltry-contribution request is strongest when it is
/// paired with it), and it is also the only figure about this project's money
/// that can be published without publishing the author's finances: the worker
/// stores one row per Ko-fi message id and no amount, no name and no email, so
/// a count is the most it could report even if it were asked for more.
///
/// SILENT UNTIL IT IS CONFIGURED, and silent at zero. A "0 supporters" line is
/// social proof pointing the wrong way, and a channel that has just opened has
/// nothing to be ashamed of.
let supportCount = null;
function supportCountAsk() {
  if (supportCount !== null) return;
  supportCount = "asking";
  fetch("/api/support/count")
    .then((r) => (r.ok ? r.json() : null))
    .then((j) => {
      supportCount = j && j.ok ? j : "failed";
      if (!$("support-page").hidden) renderSupport();
    })
    .catch(() => { supportCount = "failed"; });
}

/// THE FACTS STRIP — what this repository holds, counted rather than claimed.
///
/// Two sources and the split is deliberate: anything the page can count for
/// itself is counted here and is right on the dev server too, and only what
/// lives outside the shipped data — tests, checks, measurements, commits —
/// comes from `PROJECT_FACTS`, which the site build writes. A figure that is
/// missing is DROPPED rather than drawn as a zero.
function projectFacts() {
  const mods = new Set();
  for (const pool of Object.values(META.mod_pools || {})) {
    for (const m of pool || []) mods.add(m.id);
  }
  const f = PROJECT_FACTS || {};
  const rows = [
    [META.weapons ? META.weapons.length : 0, "weapons modelled"],
    [mods.size, "mods and rivens"],
    [f.rust_tests, "tests on the engine"],
    [f.browser_checks, "checks on the page"],
  ];
  return rows.filter(([n]) => n > 0).map(([n, what]) => ({ n, what }));
}

function renderSupport() {
  const facts = $("support-facts");
  if (facts) {
    facts.innerHTML = projectFacts().map((f) => `
      <div class="sup-fact"><b>${escHtml(f.n.toLocaleString())}</b><span>${escHtml(tr(f.what))}</span></div>`).join("");
  }
  // WHEN IT STARTED AND HOW MUCH HAS HAPPENED SINCE. One line rather than two
  // more tiles: it is context for the strip above, not a sixth figure.
  const built = $("support-built");
  if (built) {
    const f = PROJECT_FACTS || {};
    const say = f.commits && f.first_commit_day;
    built.hidden = !say;
    if (say) {
      built.textContent = tr("Built in the open since {day} — {n} commits, every one of them public.")
        .replace("{day}", f.first_commit_day).replace("{n}", f.commits.toLocaleString());
    }
  }
  const used = $("support-usage");
  if (used) {
    const u = supportUse();
    used.hidden = !u.sims;
    if (u.sims) {
      used.textContent = tr("You have run {n} simulations on this machine — {e} engagements. That number is in this browser and has never been sent anywhere.")
        .replace("{n}", u.sims.toLocaleString()).replace("{e}", u.engagements.toLocaleString());
    }
  }
  const box = $("support-channels");
  if (box) {
    box.innerHTML = SUPPORT_CHANNELS.filter((c) => c.url)
      .sort((a, b) => chRank(a) - chRank(b)).map((c) => `
      <a class="sup-card" href="${escHtml(c.url)}" target="_blank" rel="noopener">
        <div class="sup-name">${escHtml(c.name)}</div>
        <div class="sup-what">${escHtml(tr(c.what))}</div>
        <span class="run-btn">${escHtml(tr("Open"))} ↗</span>
      </a>`).join("");
  }
  const count = $("support-count");
  if (count) {
    supportCountAsk();
    const ok = supportCount && typeof supportCount === "object" && supportCount.count > 0;
    count.hidden = !ok;
    if (ok) {
      count.textContent = tr("{n} people have chipped in so far.")
        .replace("{n}", supportCount.count.toLocaleString());
    }
  }
}

// ---- Rivens as MODS ----------------------------------------------------
// A saved riven is equipment, so it belongs in the mod list — findable by its
// preset name ("riven 1"), by its generated name ("Visican"), or by any value
// printed on it.
//
// It is NOT put in `META.mod_pools`: a riven is the visitor's own item, built
// against this weapon's disposition, so it travels WITH the request. The
// engine adds it to the pool for that build only, which is why one shared
// pool can still serve everyone.
//
// An INCOMPLETE riven is deliberately allowed through. A card with no stats
// is a mod that does nothing, which is an ordinary thing for a build to
// contain and not worth refusing.
const RIVEN_PREFIX = "riven:";
/// A CARD'S IDENTITY, WHICH IS NOT ITS NAME.
///
/// A build references a riven as `riven:<id>`. While that id was the NAME, a
/// rename had to chase every saved build that pointed at the card, two cards
/// could not share a label, and a collision had to be settled by renaming
/// somebody's riven. A name is something a player edits; an identity is not.
///
/// Opaque and never shown. `Date.now()` orders them and the suffix separates
/// two made in the same millisecond — uniqueness is checked against the store
/// either way, because that is the only thing this has to be.
const newRivenId = (all) => {
  for (;;) {
    const id = "r" + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
    if (!all.some((p) => p.id === id)) return id;
  }
};
const isRivenId = (id) => typeof id === "string" && id.startsWith(RIVEN_PREFIX);
let rivenModCache = { key: null, list: [] };

// The saved rivens of the CURRENT weapon, shaped like mods so every list,
// picker and slot that already understands a mod understands these.
function rivenMods() {
  const w = $("weapon").value;
  const raw = loadPresetList(RIVENS);
  const key = w + "|" + JSON.stringify(raw) + "|" + JSON.stringify(rivenNames);
  if (rivenModCache.key === key) return rivenModCache.list;
  const list = raw.map((p) => {
    const st = p.state || {};
    const stats = (st.bonuses || st.positives || []).concat(st.malus || st.curse || []);
    const lines = (rivenNames[p.id] || {}).lines || [];
    const official = (rivenNames[p.id] || {}).name || "";
    return {
      id: RIVEN_PREFIX + p.id,
      // DE's own riven card — the game draws every riven the same, so one
      // image serves them all (`data/assets.yaml` mods.riven).
      image: META.riven_image || null,
      name: official ? `${p.name} · ${official}` : p.name,
      name_en: official,
      subtype: "Riven",
      riven: true,
      // A weapon takes ONE riven. Same family = mutually exclusive, the rule
      // the pool already has — so every list, slot and scope enforces it
      // without knowing what a riven is.
      family: "riven",
      rarity: "legendary",
      polarity: (st.polarity || "madurai").replace(/^./, (c) => c.toUpperCase()),
      drain: 2 + 2 * (st.rank ?? 8),
      max_rank: 8,
      exilus: false,
      // The VEILED riven card — DE's own image for every riven type
      // (`imageName` on the riven mod item), and the one on the CDN like
      // every other mod picture.
      image: "OmegaMod.png",
      // Every printed value is searchable, which is how you find the riven
      // with the crit damage on it without remembering what you called it.
      effects: lines.length ? lines : stats.filter((s) => s && s.id).map((s) => s.id.replace(/_/g, " ")),
      unmodeled_effects: (rivenNames[p.id] || {}).unmodeled || [],
      __spec: st,
    };
  });
  rivenModCache = { key, list };
  return list;
}

// The generated name and printed lines per saved riven, filled in by asking
// the engine — the page never computes a riven value itself.
let rivenNames = {};
async function refreshRivenNames() {
  const ps = loadPresetList(RIVENS);
  const out = {};
  for (const p of ps) {
    try {
      const r = await api("/api/riven", { weapon: $("weapon").value, ...(p.state || {}) });
      out[p.id] = {
        name: r.name || "",
        lines: (r.stats || []).map((s) => s.text),
        // …AND WHICH OF THEM PAY NOTHING. A riven's stats are DE's rather than
        // ours, so a card can carry one this engine does not model — a melee
        // card's Finisher Damage — and it gets the same "partly modelled" line
        // a mod with a dead clause gets, naming the line that is dead.
        unmodeled: (r.stats || []).filter((s) => !s.modeled).map((s) => s.text),
      };
    } catch (_) { /* a name is a nicety; the riven still equips */ }
  }
  rivenNames = out;
  rivenModCache = { key: null, list: [] };
  // The lists that show a riven's printed values may already have rendered
  // with only its stat ids — this arrives afterwards, so they get redrawn.
  //
  // THE BUILD'S OWN SLOTS ARE ONE OF THEM. An equipped riven prints its roll in
  // its slot like any other card, and that text comes from here — so a slot
  // drawn before this returned showed the fallback, four bare stat NAMES with
  // no values on them, and nothing ever came back to correct it. It was
  // invisible while the slot printed nothing at all.
  if ($("mod-slots")) renderMods();
  if (typeof renderOptModList === "function" && $("opt-mods") && !$("opt-block").hidden) renderOptModList();
  if ($("riven-all") && !$("riven-block").hidden) renderRivenAll();
  if ($("mod-popover") && !$("mod-popover").hidden && rivenPickerSlot != null) renderMenu(rivenPickerSlot, $("mod-search").value || "");
}
// Which slot the builder's mod picker is open for, so an async refresh can
// redraw it without reopening it.
let rivenPickerSlot = null;

/// Everything equippable on this weapon: the pool, plus this weapon's rivens.
const poolWithRivens = () => currentPool.concat(rivenMods());

/// The mod ids a set of EVOLUTIONS takes off the weapon.
///
/// An equip rule is asked of every firing mode a weapon has, and installing the
/// Incarnon form adds one — so Dual Toxocyst wears Semi-Pistol Cannonade until
/// tier 1 goes in and cannot after ("Weapons with an Incarnon mode must have
/// Semi-Auto trigger type for both firing modes in order to equip this mod",
/// wiki Semi-Pistol_Cannonade; user, 2026-08-04). The RULE is the engine's
/// (`pool_for_build`); `evo_forbids` is its answer per evolution, so this is a
/// lookup rather than a second implementation of it — the last time the client
/// re-derived a pool rule it went stale the same week (see `applyWeaponInner`).
const forbiddenByEvos = (sel) => {
  const map = (weaponInfo($("weapon").value) || {}).evo_forbids || {};
  const out = new Set();
  for (const id of Object.values(sel || evoSel)) for (const m of map[id] || []) out.add(m);
  return out;
};
/// What THIS BUILD can equip: the weapon's pool minus what its evolutions cost
/// it. The optimizer keeps asking `poolWithRivens()` — evolutions are a search
/// DIMENSION there, so a mod one variant refuses is still in scope for the ones
/// that do not, and which is which is decided per candidate by the engine.
const buildPool = () => {
  const no = forbiddenByEvos();
  return poolWithRivens().filter((m) => !no.has(m.id));
};
/// What may go in the EXILUS slot. Both modules ask this one function: the
/// builder used `poolWithRivens()` and the optimizer `currentPool`, which
/// agreed only because no riven is exilus-eligible — a coincidence, not a
/// rule, and the sort that stops being true without anyone noticing.
const exilusPool = () => poolWithRivens().filter((m) => m.exilus);
/// THE STANCE SLOT'S OWN POOL. A stance is legal there and nowhere else, which
/// is the whole reason the slot costs no wire field — and it is why this filter
/// runs in BOTH directions: the stance slot takes only stances, and the eight
/// main slots take everything BUT.
const stancePool = () => poolWithRivens().filter((m) => m.stance);

/// THE WEAPON'S BUILD AXES — one description, read by BOTH modules.
///
/// The builder fills these slots and the optimizer searches them, so they are
/// one question asked twice, and stating it once makes a new weapon a ONE-PLACE
/// change: a sentinel that seats no arcane, an Arch-Gun that seats two, a pool
/// with no exilus mod in it.
///
/// AN AXIS IS SHOWN IFF IT HAS OPTIONS — one rule in place of three category
/// guesses (`!sentinel`, `arcane_slots >= 1`, `uses_evo2`) standing in for "is
/// there anything to choose here", each remembered twice.
// INFINITE AMMO — on by DEFAULT for every weapon, because the sim models no
// ammo PICKUPS: a finite reserve is the pessimistic half of a mechanic we only
// half have. A weapon whose reserve is infinite IN GAME cannot be switched off
// it (every sentinel prints "Ammo Max: infinity / Ammo Type: None"), which
// shows as a TICKED, DISABLED box rather than a hidden one.
// WHERE the fight happens, when that changes the weapon. An Arch-Gun on the
// ground and in Archwing is the SAME weapon — same damage, same mod pool, same
// riven — and only its sustain differs (reload 2.50 vs 4.50, a finite 400-round
// reserve vs a regenerating magazine), so it is a scenario axis rather than a
// second entry. Shown only where there is a choice.
const deployField = (w, state) => {
  const opts = w.deployments || [];
  if (opts.length < 2) return "";
  const cur = opts.includes(state.deployment) ? state.deployment : opts[0];
  return `<label title="${escHtml(tr("where the weapon is fired — it changes reload and ammo, nothing else"))}">${escHtml(tr("Environment"))} ` +
    ddButton("dd-deployment", {
      value: cur,
      dataK: "deployment",
      // The data keys are lowercase; the LABEL is the wiki's own column head.
      items: opts.map((o) => ({ value: o, label: tr(o[0].toUpperCase() + o.slice(1)) })),
    }) + `</label>`;
};

// IS THE TARGET ITS ELITE VARIANT? Offered only where one EXISTS, because
// there is no such unit otherwise — the engine rejects the combination rather
// than quietly simulating an ordinary enemy under an elite label (a Thrax's
// overguard is innate, not Eximus-granted), so a control here would be a
// promise the fight cannot keep.
//
// DEFAULT ON wherever it exists. The Eximus is what a
// Steel Path player actually meets, and it is not a cosmetic difference: it
// adds health and puts a pool of Overguard in front of it, so a build measured
// on the ordinary unit is measured on a fight nobody has.
//
// `sim.eximus` is NULL until you say otherwise, and null means "this unit's
// answer" — which is what makes the default follow the TARGET rather than
// stick to whatever the last target happened to be.
const eximusOn = (en) => sim.eximus ?? !!(en && en.can_be_eximus);
const eximusField = (en) => {
  if (!en || !en.can_be_eximus) return "";
  return `<label class="check" title="${escHtml(tr("the elite variant: more health, and a pool of Overguard in front of it"))}"><input type="checkbox" data-k="eximus" ${eximusOn(en) ? "checked" : ""}> ${escHtml(tr("Eximus"))}</label>`;
};

/// WHAT THIS WEAPON SETTLES THIS FIELD TO, AND WHY — or null when the choice is
/// the reader's.
///
/// THE RULE IS THE ENGINE'S. `engine::scenario::forced_for`
/// decides and `/api/meta` states the consequence per weapon; this reads it.
/// Re-deriving the three rules here from weapon flags is two implementations
/// of one rule, and a forced field looks identical whoever forced it, so they
/// drift without anything going red.
///
/// It still has THREE states and not two, which is what the flags could not say: "there is nothing to run out of" and "there is, and you
/// cannot refill it" force the SAME box to OPPOSITE values. Reading one as the
/// other left the only adjustable weapon being the one weapon the game gives no
/// way to adjust.
const settledAxis = (w, id) => {
  const f = (w || {}).settled || {};
  const hit = f[id];
  return hit ? { value: hit[0], why: hit[1], overridable: !!hit[2] } : null;
};

/// **A FIGHT'S OWN HOUSE RULES, PER WEAPON CLASS**.
///
/// A scenario is ONE DOCUMENT that any weapon can be tested against, so it
/// carries the rules for classes it is not currently pointed at — which is what
/// makes "in my fight, Arch-Guns have infinite ammo" a thing you can write on a
/// Burston's page and have apply the next time you open the Larkspur.
///
/// OVERRIDES SIT BEHIND LEGALITY and the engine draws that line, never this
/// file: `META.class_rules.overridable` is the (class, axis) pairs a scenario
/// may argue with, which is exactly where the capability's absence is OUR
/// stand-in rather than the game's rule. So a control is offered for
/// Arch-Gun ammo and no control exists anywhere for a Sentinel's headshots.
const overridablePairs = () => ((META && META.class_rules) || {}).overridable || [];
const isOverridable = (cls, id) => overridablePairs().some((p) => p[0] === cls && p[1] === id);
const classRuleOf = (cls, id) => ((sim.class_rules || {})[cls] || {})[id];
/// Read a class-rule control and store what it says. Returns whether it WAS
/// one, so a generic `[data-k]` handler can delegate and return early.
///
/// A RULE THAT AGREES WITH THE DEFAULT IS NOT A RULE. `data-crdef` carries the
/// value the capability would have given, and ticking back to it CLEARS the key
/// rather than storing the same answer twice — the absent-key mechanism a
/// Warframe override already uses, for the same reason: a scenario's stored
/// rules should say what it actually decided.
const applyClassRule = (el) => {
  const cr = el.dataset.cr;
  if (!cr) return false;
  const [cls, id] = cr.split("|");
  const v = el.type === "checkbox" ? el.checked : Number(el.value);
  const dflt = el.dataset.crdef;
  const same = dflt !== undefined
    && String(v) === (dflt === "true" || dflt === "false" ? dflt : String(Number(dflt)));
  setClassRule(cls, id, same ? undefined : v);
  return true;
};

/// Write one, or clear it with `undefined`.
///
/// AN ABSENT KEY IS THE MECHANISM, exactly as a Warframe override's is: the
/// engine falls back to the capability when nothing is written, so a rule that
/// merely AGREES with the default is pruned rather than stored. That keeps a
/// scenario's diff about what it actually decided, and keeps the fingerprint a
/// board row stores from moving on a no-op tick.
const setClassRule = (cls, id, v) => {
  const rules = { ...(sim.class_rules || {}) };
  const col = { ...(rules[cls] || {}) };
  if (v === undefined) delete col[id]; else col[id] = v;
  if (Object.keys(col).length) rules[cls] = col; else delete rules[cls];
  if (Object.keys(rules).length) sim.class_rules = rules; else delete sim.class_rules;
  markScenarioDirty();
};
// A SENTINEL WEAPON IS ALWAYS AIMING — it just never aims
// at the HEAD, which is why its headshot default is 0 and every on-headshot
// trigger stays dead anyway. Ticked and disabled, the same shape as infinite
// ammo: the state is real, the control is honestly unavailable.
const aimField = (w, state) => {
  const f = settledAxis(w, "aiming");
  const forced = !!f;
  const on = forced ? !!f.value : state.aiming;
  const why = forced
    ? tr(f.why)
    : tr("mods that only work while aiming (Galvanized Crosshairs, Argon Scope, Sharpened Bullets…) grant nothing when this is off");
  return `<label class="check" title="${escHtml(why)}"><input type="checkbox" data-k="aiming"${on ? " checked" : ""}${forced ? " disabled" : ""}> ${escHtml(tr("Aiming"))}</label>`;
};
/// …AND ITS HEADSHOT RATE IS 0 AND NOT YOURS.
///
/// The VALUE was already right from both ends — `defaultHeadshotPct` opens a
/// sentinel at 0, and `parse_fight` forces 0 on one whatever the request
/// carries. The CONTROL was not: a bare number input, editable, so a reader
/// could type 100 on a Verglas, watch the page accept it, and get a run
/// computed at 0 with nothing on screen saying why. A column that is shown and
/// not applied looks exactly like one that works — the same fault
/// `check_custom_enemies` was written for, in another panel.
///
/// It is DISPLAY-ONLY, and that is deliberate: `sim.headshot_pct` belongs to a
/// scenario SHARED across the whole roster (`SHARED_DOMAINS`), so writing 0
/// into it here would rewrite the fight every time a sentinel was opened and
/// auto-save would store it — which is the exact trap `switchWeapon` documents
/// and avoids. So the field shows 0 and disables itself while the underlying
/// scenario keeps whatever the reader set for the rest of the roster.
const headshotField = (w, state) => {
  const f = settledAxis(w, "headshot_pct");
  const forced = !!f;
  const val = forced ? f.value : state.headshot_pct;
  const why = forced
    ? tr(f.why)
    : tr("a per-PELLET aim weight on the body the shot STRUCK, not a whole-spread promise — the landing spot is rolled for each pellet, and nothing a blast or a chain reaches can be a headshot");
  return `<label title="${escHtml(why)}">${escHtml(tr("Headshot %"))} <input type="number" data-k="headshot_pct" min="0" max="100" value="${val}"${forced ? " disabled" : ""}></label>`;
};
/// …AND THE AMMO BOX IS THE ONE FIELD A FIGHT MAY ARGUE WITH.
///
/// Settled OFF on a ground Arch-Gun because it cannot be resupplied — but that
/// is OUR pessimistic stand-in for ammo pickups the sim has no entities for,
/// not a rule of the game, so a scenario is allowed to say otherwise. When it
/// is, the box stays LIVE and writes this fight's rule for the class rather
/// than the scenario's own field: the setting is about Arch-Guns, so it is
/// stored against Arch-Guns and applies to every one of them.
const ammoField = (w, state) => {
  const f = settledAxis(w, "infinite_ammo");
  const cls = w && w.weapon_class;
  const ruled = f && f.overridable && cls;
  const rule = ruled ? classRuleOf(cls, "infinite_ammo") : undefined;
  const forced = !!f && !ruled;
  const on = ruled
    ? (rule === undefined ? !!f.value : !!rule)
    : (f ? !!f.value : state.infinite_ammo !== false);
  const why = ruled
    ? tr(f.why) + " — " + tr("this fight can rule otherwise for the whole class, and that is what this box writes")
    : f
      ? tr(f.why)
      : tr("on = ammo pickups keep the reserve topped up, which the sim has no entities for; off = it runs dry. The magazine and its reloads apply either way");
  const attr = ruled
    ? `data-cr="${escHtml(cls)}|infinite_ammo" data-crdef="${!!f.value}"`
    : `data-k="infinite_ammo"`;
  return `<label class="check${ruled && rule !== undefined ? " ruled" : ""}" title="${escHtml(why)}"><input type="checkbox" ${attr}${on ? " checked" : ""}${forced ? " disabled" : ""}> ${escHtml(tr("Infinite ammo"))}</label>`;
};

function weaponAxes(weaponId) {
  const w = weaponInfo(weaponId || $("weapon").value) || {};
  const exilus = w.sentinel ? [] : exilusPool();
  return {
    mods: poolWithRivens(),
    exilus,
    hasExilus: exilus.length > 0,
    // …AND THE STANCE SLOT, asked of the POOL rather than of the weapon's
    // class: "this weapon's pool holds a stance" is the only honest test, since
    // a melee class whose stances nobody has transcribed yet would otherwise
    // show an empty slot with nothing to offer — which reads as a broken picker
    // rather than as missing data.
    stance: stancePool(),
    hasStance: stancePool().length > 0,
    // One entry per arcane pool, in the weapon's own pool order.
    arcanes: (w.arcane_pools || []).map((pool, i) => ({ pool, options: arcanePool(i) })),
    // One entry per evolution tier — OF THE WEAPON THIS OBJECT IS ABOUT. It
    // read the live `#weapon` until 2026-08-24, which let this one axis
    // describe a different weapon from the other four.
    evolutions: weaponEvos(w.id),
    // HOW THE WEAPON IS PLAYED — an axis like the rest, because it is one: the
    // builder picks a value and the optimizer searches the set, and the board
    // ranks weapon x mode. Only the modes a fight can HOLD are offered; the
    // engine derives that from whether entering the form costs a gauge you
    // have to earn ("always Incarnon" is not a playstyle, it is a few seconds
    // at a time), so nothing here is a list anyone maintains.
    //
    // A ONE-MODE WEAPON GETS AN EMPTY AXIS, by the same rule every other axis
    // follows: an axis is shown iff it has options, and "base" alone is not a
    // choice anybody has.
    modes: (w.modes || []).length > 1 ? w.modes : [],
  };
}

/// The mode a build plays in: the asked-for one where this weapon offers it,
/// else however the arsenal plays it — the cycle where there is one to run.
///
/// One resolver, so "no mode named" means the same thing in the builder, in a
/// share link and in a board submission.
function defaultMode(weaponId, want) {
  const ms = (weaponInfo(weaponId) || {}).modes || ["base"];
  if (want && ms.includes(want)) return want;
  return ms.includes("cycle") ? "cycle" : (ms[0] || "base");
}

/// The rivens a request must carry for its `riven:` ids to mean anything.
///
/// `id` is what the item id is built from; `name` rides along because it is
/// what a share link written before ids carried, and the server still reads it
/// when there is no id.
const rivenPayload = () =>
  loadPresetList(RIVENS).map((p) => ({ id: p.id, name: p.name, spec: p.state || {} }));

// ---- Rivens ------------------------------------------------------------
// A CONSTRUCTOR, not a roller. Every control is bounded by the formula, so
// the only rivens it can express are legal ones — including the corner where
// every bonus rolls maximal and the malus minimal, which is not an edge
// case here but the CEILING, the riven an optimizer wants to know about.
//
// The arithmetic is NOT duplicated: every change asks `/api/riven`, so a
// slider can never drift from what the sim would build, and a typed value
// comes back as the roll it implies. Under wasm that call is local.
let riven = null;      // the riven being edited
let rivenResolved = null;
const RIVENS = "rivens";   // its preset domain, per weapon like the builds

// The stat pool this weapon's rivens draw from. NOT its mod class: a bow's
// mods are `bow` and its rivens are `rifle`, so the server derives which pool
// applies and says so.
// `riven_excludes` takes out what THIS weapon cannot roll, and the server
// answers from three sources in order (MEASUREMENTS M35): a real card someone
// has, a COUNT over ~12 000 live riven listings per family, and only then the
// derivation — a sentinel weapon has no Zoom and no Recoil, a hit-scan one no
// flight speed, an infinite-ammo one no Ammo Maximum, and a weapon with no
// physical damage rolls no physical attribute (the wiki's 25% rule, which is
// wrong on six of 26 families in both directions). The class table stays
// shared; only the weapon's view of it narrows.
const rivenPoolAll = () => {
  const w = weaponInfo($("weapon").value);
  return (META.riven_stats || {})[w.riven_class || w.mod_class] || [];
};
const rivenPool = () => {
  const out = (weaponInfo($("weapon").value).riven_excludes) || [];
  const all = rivenPoolAll();
  return out.length ? all.filter((s) => !out.includes(s.id)) : all;
};
const rivenRules = () => META.riven_rules || { roll_min: 0.9, roll_max: 1.1, max_rank: 8 };
// Lookup goes through the UNFILTERED pool: a riven saved before its weapon
// learned it could not roll that stat still has to render and still resolves
// server-side (`resolved_slots` finds by id in the whole class pool). Only
// what the picker OFFERS narrows.
const rivenStat = (id) => rivenPoolAll().find((s) => s.id === id);
// The stat's NAME, without the placeholder or the unit: the row already
// shows the value, so repeating "X%" in the picker is noise.
//
// A riven line is OUR sentence built from DE's template, so it localizes the
// way every other engine-generated effect line does — through the locale's
// effect_phrases, which are the official client's words (data/i18n). There is
// nothing riven-specific to translate: "+150% Critical Chance" reads the same
// on a riven as on Point Strike.
// The unit sits between the hole and the name — `%` on most, `s` on Combo
// Duration — and is not part of what the stat is called.
const rivenStatNameEn = (s) =>
  s.text.replace("|val|", "").replace(/^\s*[%s]\s*/, "").replace(/\s+/g, " ").trim();
const rivenStatName = (s) => tf(rivenStatNameEn(s));

// The shape, in the notation everyone already uses: 2, 3, 2+1, 3+1 — the
// count of bonuses, and a +1 for the malus. It leads because it is the
// ONLY thing that decides the multipliers; a 2 and a 2+1 pay their bonuses
// differently before a single stat is chosen.
// Best first, left to right: 3+1, 3, 2+1, 2. A riven is
// shopped for from the top — the third bonus is what makes one worth having,
// and the malus is the price, so the pairs read as "with / without price"
// rather than as a count that happens to climb.
const RIVEN_SHAPES = [
  { id: "3+1", bonuses: 3, malus: true },
  { id: "3", bonuses: 3, malus: false },
  { id: "2+1", bonuses: 2, malus: true },
  { id: "2", bonuses: 2, malus: false },
];
// A new card starts at 3+1 — the shape a riven worth
// making is in. Stated by ID, not by position, so the display order above
// stays a display decision and never doubles as the default.
const RIVEN_SHAPE_DEFAULT = "3+1";

// An EMPTY card. Nothing is pre-picked: a default stat is a claim the visitor
// did not make. Two bonuses is the game's floor for a riven rather than a
// suggestion, and the rolls sit at 1.0 because a slider has to be somewhere.
// FOUR drafts, one per shape, and only the active one is the riven.
//
// Without them, switching 3+1 -> 2+1 -> 3+1 loses the third stat: the slot is
// popped and there is nowhere for it to have gone.
// Keeping each shape's own stats means a shape switch is a switch, not an
// edit — you can compare a 2+1 against a 3+1 by clicking between them.
//
// `bonuses` / `malus` stay the ACTIVE shape's, so everything downstream —
// the rows, the payload, the engine — keeps reading a riven the same way.
const RIVEN_BLANK_DRAFT = (n, malus) => ({
  bonuses: Array.from({ length: n }, () => ({ id: null, roll: 1.0 })),
  malus: malus ? { id: null, roll: 1.0 } : null,
});
function blankRiven() {
  const drafts = {};
  RIVEN_SHAPES.forEach((s) => { drafts[s.id] = RIVEN_BLANK_DRAFT(s.bonuses, s.malus); });
  return {
    shape: RIVEN_SHAPE_DEFAULT,
    drafts,
    bonuses: drafts[RIVEN_SHAPE_DEFAULT].bonuses,
    malus: drafts[RIVEN_SHAPE_DEFAULT].malus,
    rank: rivenRules().max_rank,
    polarity: "madurai",
  };
}

/// Bring a riven up to the four-draft shape — older saved ones carry only the
/// active stats, and a missing draft is simply an empty one.
function withDrafts(r) {
  const out = JSON.parse(JSON.stringify(r || {}));
  out.rank = out.rank ?? rivenRules().max_rank;
  out.polarity = out.polarity || "madurai";
  // A riven saved before the wiki's Bonus/Malus wording still says
  // positives/curse. It is the visitor's own item and outlives our
  // vocabulary, so it is read either way and re-saved in the new words.
  out.bonuses = out.bonuses || out.positives || [];
  out.malus = out.malus || out.curse || null;
  delete out.positives;
  delete out.curse;
  Object.values(out.drafts || {}).forEach((d) => {
    d.bonuses = d.bonuses || d.positives || [];
    d.malus = d.malus || d.curse || null;
    delete d.positives;
    delete d.curse;
  });
  out.shape = out.shape || `${out.bonuses.length || 2}${out.malus ? "+1" : ""}`;
  out.drafts = out.drafts || {};
  RIVEN_SHAPES.forEach((s) => {
    if (!out.drafts[s.id]) out.drafts[s.id] = RIVEN_BLANK_DRAFT(s.bonuses, s.malus);
  });
  // The stats it was saved with belong to the shape it was saved in.
  if (out.bonuses.length) {
    out.drafts[out.shape] = { bonuses: out.bonuses, malus: out.malus };
  }
  const d = out.drafts[out.shape];
  out.bonuses = d.bonuses;
  out.malus = d.malus;
  return out;
}

/// Every slot filled? An unfinished card is not an ILLEGAL riven — it is one
/// that has not been described yet, and it must not be reported as an error.
const rivenComplete = () =>
  riven && riven.bonuses.every((s) => s.id) && (!riven.malus || riven.malus.id);

async function resolveRiven(pending) {
  if (!riven) return;
  try {
    // `pending` carries a typed VALUE for one slot; the server turns it into
    // the roll it implies, clamped, so the formula stays in one place.
    const body = { weapon: $("weapon").value, ...riven };
    if (pending) {
      const clone = JSON.parse(JSON.stringify(body));
      if (pending.slot === "malus") clone.malus.value = pending.value;
      else clone.bonuses[Number(pending.slot)].value = pending.value;
      rivenResolved = await api("/api/riven", clone);
      // Adopt the roll the value implied, so slider and box agree.
      (rivenResolved.stats || []).forEach((s) => {
        const at = s.slot === "malus" ? riven.malus : riven.bonuses[Number(s.slot)];
        if (at) at.roll = s.roll;
      });
    } else {
      rivenResolved = await api("/api/riven", body);
    }
  } catch (e) {
    rivenResolved = { ok: false, illegal: [String(e)], stats: [] };
  }
  renderRivenCard();
}

// The collection, guaranteed non-empty and with a live active name. There is
// ALWAYS one riven, exactly as the builder always has "build 1": a bar whose
// only option is "+ new" makes the visitor do a step the page could have done, and the first one is the empty card they were going to
// fill in anyway.
// Rivens are an OPTIONAL collection: zero is a legal, and the ordinary,
// number to own. Nothing is auto-created — a blank card
// standing in for "no riven" is a claim the visitor never made, and it put a
// phantom legendary in every weapon's mod pool. Custom enemies will be the
// same shape when they arrive.
// The stored list. It does NOT open anything: closing the last file is a
// state, and re-opening one behind the user's back would make "← all rivens" a
// button that does nothing.
//
// AND IT NO LONGER DELETES THE POINTER ON A MISS. It did, which made every
// reason the card was momentarily not in this list — a render that lands
// before the weapon switch completes, a family whose scope has moved — a
// silent forget of which card was open. A pointer at nothing opens nothing,
// which is the whole behaviour that was wanted; throwing it away as well is
// the part that could only lose something.
function ensureRivenList() {
  return loadPresetList(RIVENS);
}

function renderRivens() {
  if (!META || !$("riven-block")) return;
  const w = weaponInfo($("weapon").value);
  const ps = ensureRivenList();
  const open = ps.find((p) => p.id === activeRivenId());
  // The weapon and its disposition, and nothing else: that the values below
  // are scaled by it is what a disposition IS, so saying it was noise.
  //
  // …AND WHOSE RIVEN IT IS, once a family has more than one member on the
  // roster. A card is the FAMILY's, so a riven the player
  // built on the Burston is in the Burston Prime's list — and silent sharing
  // reads as a bug the first time a riven you never made here turns up. It
  // names the other variants rather than counting them, because "also fits 1
  // other" is the one thing a reader cannot act on, and it states the
  // disposition rule, since that is why the same card shows two sets of
  // numbers.
  const kin = (META.weapons || []).filter((x) =>
    x.riven_family && x.riven_family === w.riven_family && x.id !== w.id
    // …AND THE SAME CARD. A Kitgun's two builds share a family and take two
    // different rivens, so the primary must not claim its own card also fits
    // the secondary.
    && (x.riven_class || x.mod_class) === (w.riven_class || w.mod_class));
  // THE FAMILY IS NAMED IN THE READER'S LANGUAGE, by borrowing the localized
  // name of its BASE member rather than printing the family string. That
  // string is DE's module `Family` field and is always English, so a Chinese
  // page said "一张 Burston 紫卡" beside 伯斯顿 Prime — and inventing a
  // Chinese name for it would be a TRANSLATION of an id. The base member's
  // name is DE's own transcription and already in `names.yaml`.
  const base = [w, ...kin].find((x) => x.id === (w.riven_family || "").toLowerCase()
    .replace(/[^a-z0-9]+/g, "_"));
  $("riven-sub").textContent =
    `${w.name} · ${tr("disposition")} ${(w.disposition || 1).toFixed(2)}`
    + (kin.length
      ? ` · ${tr("a {family} riven — it fits {others} too, each at its own disposition")
          .replace("{family}", (base && base.name) || w.riven_family)
          .replace("{others}", kin.map((x) => x.name).join(", "))}`
      : "");
  renderRivenTools();
  if (!open) {
    // LIST MODE — nothing is being edited, so nothing pretends to be. The
    // editor's boxes are emptied rather than hidden: an empty container in
    // the flow keeps the page from jumping when a file is opened.
    riven = null;
    ["riven-shape", "riven-stats", "riven-foot", "riven-card"].forEach((id) => {
      if ($(id)) $(id).innerHTML = "";
    });
    renderRivenAll();
    return;
  }
  // EDIT MODE — the open file, re-read when the weapon changed under it.
  if (!riven || riven.__weapon !== w.id) {
    riven = { ...withDrafts(open.state || blankRiven()), __weapon: w.id };
  }
  renderRivenShape();
  renderRivenStats();
  renderRivenFoot();
  renderRivenAll();
  resolveRiven();
}

// "3 Bonus, 1 Malus" — the shape said in words, in whichever language.
const shapeWords = (s) =>
  `${s.bonuses} ${tr("Bonus")}${s.malus ? `, 1 ${tr("Malus")}` : ""}`;

function renderRivenShape() {
  const now = riven.shape || `${riven.bonuses.length}${riven.malus ? "+1" : ""}`;
  const shapeNow = RIVEN_SHAPES.find((x) => x.id === now)
    || RIVEN_SHAPES.find((x) => x.id === RIVEN_SHAPE_DEFAULT);
  $("riven-shape").innerHTML =
    `<span class="rv-lbl">${escHtml(tr("Shape"))}</span><span class="oseg">` +
    RIVEN_SHAPES.map((s) =>
      `<span class="seg ${s.id === now ? "on" : ""}" data-rv="${s.id}"
             title="${escHtml(shapeWords(s))}">${s.id}</span>`).join("") +
    `</span><span class="rv-lbl dim">${escHtml(shapeWords(shapeNow))}</span>`;
  $("riven-shape").querySelectorAll("[data-rv]").forEach((el) => el.onclick = () => {
    const want = el.dataset.rv;
    if (want === riven.shape) return;
    // Park the current shape's stats in its own draft, then adopt the target
    // shape's. Nothing is discarded, so clicking back and forth is free.
    riven.drafts[riven.shape] = { bonuses: riven.bonuses, malus: riven.malus };
    riven.shape = want;
    const s = RIVEN_SHAPES.find((x) => x.id === want);
    const d = riven.drafts[want] || RIVEN_BLANK_DRAFT(s.bonuses, s.malus);
    riven.drafts[want] = d;
    riven.bonuses = d.bonuses;
    riven.malus = d.malus;
    markRivenDirty();
    renderRivens();
  });
}

// One row per rolled stat: the stat, where in its 0.9-1.1 band it landed, and
// what that comes to. The slider's ENDS are the band and the number box is
// clamped to the same, so an illegal roll is not something a control can
// express — "any legal riven and only legal ones" holds by construction.
function renderRivenStats() {
  const rules = rivenRules();
  const row = (slot, s, isMalus) => {
    const def = rivenStat(s.id);
    return `<div class="rv-row ${isMalus ? "malus" : ""}">
      <span class="rv-tag">${escHtml(tr(isMalus ? "Malus" : "Bonus"))}</span>
      <button class="rv-pick" data-slot="${slot}">${def ? escHtml(rivenStatName(def)) : escHtml(tr("choose a stat"))}</button>
      <input class="rv-roll" type="range" data-slot="${slot}"
             min="${rules.roll_min}" max="${rules.roll_max}" step="0.001" value="${s.roll}">
      <input class="rv-num" type="number" data-slot="${slot}" step="0.1" placeholder="—">
      <span class="rv-pct" data-slot="${slot}" title="${escHtml(tr("where this roll landed in its 0.9-1.1 band"))}"></span>
      <span class="rv-mult" data-slot="${slot}" title="${escHtml(tr("the roll itself — the random multiplier this stat drew, 0.900 to 1.100"))}"></span>
      <span class="rv-unit" data-slot="${slot}"></span>
    </div>`;
  };
  $("riven-stats").innerHTML =
    riven.bonuses.map((s, i) => row(String(i), s, false)).join("") +
    (riven.malus ? row("malus", riven.malus, true) : "");

  const at = (slot) => (slot === "malus" ? riven.malus : riven.bonuses[Number(slot)]);
  $("riven-stats").querySelectorAll(".rv-pick").forEach((el) =>
    el.onclick = () => openRivenPicker(el, el.dataset.slot));
  $("riven-stats").querySelectorAll(".rv-roll").forEach((el) => el.oninput = () => {
    at(el.dataset.slot).roll = Number(el.value);
    markRivenDirty();
    resolveRiven();
  });
  // The number box takes the VALUE, not the roll — the number printed on a
  // riven you own. Out of range snaps to the nearest legal end rather than
  // being refused, so typing is never a dead end.
  $("riven-stats").querySelectorAll(".rv-num").forEach((el) => el.onchange = () => {
    if (!at(el.dataset.slot).id || el.value === "") { renderRivenCard(); return; }
    markRivenDirty();
    resolveRiven({ slot: el.dataset.slot, value: Number(el.value) });
  });
}

// The same searchable popover the mod and arcane pickers use — a riven stat
// is picked the way everything else on this page is picked.
function openRivenPicker(anchor, slot) {
  closePopovers();
  // ITS OWN popover. Borrowing the mod picker's nodes dragged the mod
  // picker's sort header in with them, and using it rendered the mod list
  // into this menu. Separate elements is the only
  // isolation that cannot leak.
  const pop = $("riven-popover");
  const search = $("riven-search");
  const menu = $("riven-menu");
  const at = slot === "malus" ? riven.malus : riven.bonuses[Number(slot)];
  const used = new Set(riven.bonuses.map((x) => x.id).concat(riven.malus ? [riven.malus.id] : []));
  const draw = (q) => {
    const f = (q || "").trim().toLowerCase();
    menu.innerHTML = rivenPool()
      // A stat cannot appear twice on one riven, and five are bonus-only
      // and can never be the malus.
      // A MALUS IS NOT ANY STAT and neither is a bonus: five roll as a bonus
      // only, and one melee stat rolls as the malus only.
      .filter((x) => (!used.has(x.id) || x.id === at.id)
        && (slot === "malus" ? x.malus : x.bonus !== false))
      // Both languages match, exactly as the mod picker does.
      .filter((x) => !f || `${rivenStatNameEn(x)} ${rivenStatName(x)}`.toLowerCase().includes(f))
      .map((x) => `<div class="opt ${x.id === at.id ? "search" : ""}" data-rvid="${x.id}">
        <div class="info"><div class="mn">${escHtml(rivenStatName(x))}</div>
        <div class="me">${x.modeled ? "" : `<div>${escHtml(tr("not modeled — it rolls and it names the riven, but it adds no damage"))}</div>`}</div></div>
      </div>`).join("") || `<div class="opt dis">${escHtml(tr("no matching stat"))}</div>`;
    menu.querySelectorAll("[data-rvid]").forEach((el) => el.onclick = () => {
      at.id = el.dataset.rvid;
      closePopovers();
      markRivenDirty();
      renderRivens();
    });
  };
  const r = anchor.getBoundingClientRect();
  pop.style.left = `${Math.max(8, Math.min(window.innerWidth - 340, r.left))}px`;
  pop.style.top = `${r.bottom + window.scrollY + 4}px`;
  pop.hidden = false;
  search.value = "";
  search.oninput = () => draw(search.value);
  draw("");
  search.focus();
}

function renderRivenFoot() {
  const rules = rivenRules();
  const pols = rules.polarities || ["madurai", "vazarin", "naramon"];
  // Polarity is a SYMBOL everywhere on this page; a name here would be the
  // one place it is spelled out.
  const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
  $("riven-foot").innerHTML =
    `<label class="rv-lbl">${escHtml(tr("Rank"))} <input id="rv-rank" type="range" min="0" max="${rules.max_rank}" step="1" value="${riven.rank}">` +
    `<b id="rv-rank-n">${riven.rank}</b></label>` +
    `<span class="rv-lbl">${escHtml(tr("Polarity"))}</span><span class="oseg">` +
    pols.map((x) => `<span class="seg pol ${riven.polarity === x ? "on" : ""}" data-pol="${x}" title="${cap(x)}">${imgTag(POL(cap(x)), "pol")}</span>`).join("") +
    `</span>` +
    `<button class="ghost-btn small" id="rv-max">${escHtml(tr("roll everything maximal"))}</button>`;
  $("rv-rank").oninput = () => {
    riven.rank = Number($("rv-rank").value);
    $("rv-rank-n").textContent = riven.rank;
    markRivenDirty();
    resolveRiven();
  };
  $("riven-foot").querySelectorAll("[data-pol]").forEach((el) => el.onclick = () => {
    riven.polarity = el.dataset.pol; markRivenDirty(); renderRivenFoot(); resolveRiven();
  });
  // The ceiling, in one click: every bonus at the top of its band and the
  // malus at the bottom, which is the least harmful it can be.
  $("rv-max").onclick = () => {
    riven.bonuses.forEach((s) => { s.roll = rules.roll_max; });
    if (riven.malus) riven.malus.roll = rules.roll_min;
    markRivenDirty();
    renderRivens();
  };
}

// Every riven saved for this weapon, with what it actually rolls — the
// collection bar shows names, this shows the numbers you choose between. The values are the engine's, from the same refresh the
// mod lists use, so nothing here is a second opinion.
function renderRivenAll() {
  const box = $("riven-all");
  if (!box) return;
  const ps = loadPresetList(RIVENS);
  const active = activeRivenId();
  const cap = (s) => String(s || "").replace(/^./, (c) => c.toUpperCase());
  box.innerHTML = ps.length
    ? ps.map((p) => {
        const st = p.state || {};
        const meta = rivenNames[p.id] || {};
        const lines = meta.lines || [];
        const shape = st.shape || `${(st.bonuses || st.positives || []).length}${st.malus || st.curse ? "+1" : ""}`;
        const nBonus = (st.bonuses || st.positives || []).length;
        return `<div class="rv-all ${p.id === active ? "sel" : ""}" data-open="${escHtml(p.id)}">
          <div class="rv-all-h">
            ${imgTag(POL(cap(st.polarity || "madurai")), "pol")}
            <b>${escHtml(p.name)}</b>
            ${meta.name ? `<span class="rv-official">${escHtml(meta.name)}</span>` : ""}
            <span class="rv-meta">${shape} · ${escHtml(tr("Rank"))} ${st.rank ?? 8} · ${2 + 2 * (st.rank ?? 8)} ${escHtml(tr("capacity"))}</span>
          </div>
          <div class="rv-all-s">${
            lines.length
              ? lines.map((x, i) => `<span class="rv-chip ${i >= nBonus ? "neg" : ""}">${escHtml(tf(x))}</span>`).join("")
              : `<span class="sim-empty">${escHtml(tr("nothing rolled yet"))}</span>`
          }</div>
        </div>`;
      }).join("")
    : `<div class="sim-empty">${escHtml(tr("no rivens for this weapon yet"))}</div>`;
  // Clicking one opens it, the same as clicking its chip in the bar.
  // Clicking a card OPENS it — the list is the folder, this is the file.
  box.querySelectorAll("[data-open]").forEach((el) => el.onclick = () => {
    const p = loadPresetList(RIVENS).find((x) => x.id === el.dataset.open);
    if (!p) return;
    activeRiven = p.id;
    localStorage.setItem(presetActiveKey(RIVENS), activeRiven);
    riven = null;   // renderRivens re-reads the file it is being asked to open
    renderRivens();
  });
}

function renderRivenCard() {
  const r = rivenResolved;
  const box = $("riven-stats");
  // Blank every row first, so a slot that lost its stat does not keep an old
  // number sitting next to it.
  box.querySelectorAll(".rv-num").forEach((el) => { el.value = ""; el.disabled = true; });
  box.querySelectorAll(".rv-unit").forEach((el) => { el.textContent = ""; el.className = "rv-unit"; });
  box.querySelectorAll(".rv-pct").forEach((el) => { el.textContent = ""; el.className = "rv-pct"; });
  box.querySelectorAll(".rv-mult").forEach((el) => { el.textContent = ""; el.className = "rv-mult"; });
  (r && r.stats || []).forEach((s) => {
    const num = box.querySelector(`.rv-num[data-slot="${s.slot}"]`);
    const unit = box.querySelector(`.rv-unit[data-slot="${s.slot}"]`);
    const pct = box.querySelector(`.rv-pct[data-slot="${s.slot}"]`);
    const mult = box.querySelector(`.rv-mult[data-slot="${s.slot}"]`);
    // The CARD's precision, which is all anyone can read off a riven they
    // own. The roll behind it stays exact — this is the reading, not the
    // number the sim uses.
    const d = s.decimals ?? 2;
    if (num) {
      num.disabled = false;
      num.value = s.shown.toFixed(d);
      num.step = (0.1 ** d).toFixed(d);
      // The ends of the legal band, so the browser guards the box too.
      num.min = Math.min(s.min, s.max).toFixed(d);
      num.max = Math.max(s.min, s.max).toFixed(d);
      // In the box's OWN units: a faction stat holds a multiplier, so its
      // band reads x0.68 … x0.74 and never looks like a percentage.
      const u = (n) => (s.unit === "x" ? `x${n}` : `${n}${s.unit || ""}`);
      num.title = `legal range ${u(num.min)} … ${u(num.max)}`;
    }
    if (pct) {
      // How good the ROLL is, with disposition, shape and base divided out —
      // so two stats on one card compare, and so do two cards.
      const q = Math.round(s.percentile ?? 50);
      // A bare number in ANGLE brackets. An ordinal suffix read as clutter, and parentheses were taken — DE's own stat text
      // already uses them ("(x2 for Bows)").
      pct.textContent = `<${q}>`;
      pct.className = `rv-pct${q >= 90 ? " top" : ""}${q <= 10 ? " low" : ""}`;
      pct.title = tr("where this roll landed in its 0.9-1.1 band");
    }
    // ...and the ROLL ITSELF, next to it. The percentile says how good the
    // draw was, which is the reading you want when comparing two cards; the
    // multiplier is the number the game actually drew, which is the one you
    // can check against a riven you own (suggested by a player, 2026-08-03).
    // Both, because neither substitutes for the other: <100> and 1.100 are
    // the same fact, <50> and 1.000 are not obviously so, and a MALUS reads
    // backwards — its best draw is the SMALLEST multiplier.
    if (mult) {
      mult.textContent = Number(s.roll).toFixed(3);
      mult.className = "rv-mult";
      mult.title = tr("the roll itself — the random multiplier this stat drew, 0.900 to 1.100");
    }
    if (unit) {
      unit.textContent = tf(s.text);
      unit.className = `rv-unit${s.value < 0 ? " neg" : ""}${s.modeled ? "" : " unmodeled"}`;
    }
    const roll = box.querySelector(`.rv-roll[data-slot="${s.slot}"]`);
    if (roll) roll.value = s.roll;
  });
  const bad = (r && r.illegal) || [];
  if (!rivenComplete()) {
    const n = riven.bonuses.filter((s) => !s.id).length + (riven.malus && !riven.malus.id ? 1 : 0);
    const msg = n === 1
      ? tr("one more stat to finish this riven")
      : tr("pick {n} more stats to finish this riven").replace("{n}", n);
    $("riven-card").innerHTML = `<div class="rv-meta">${escHtml(msg)}</div>`;
    return;
  }
  $("riven-card").innerHTML = bad.length
    ? `<div class="error"><b>${escHtml(tr("not a legal riven"))}</b><ul>${bad.map((x) => `<li>${escHtml(x)}</li>`).join("")}</ul></div>`
    : `<div class="rv-name">${escHtml(r.name)}</div>
       <div class="rv-meta">${r.drain} ${escHtml(tr("capacity"))} · ${escHtml(tr(r.class))} ${escHtml(tr("riven"))} · ${escHtml(tr("disposition"))} ${Number(r.disposition).toFixed(2)}</div>`;
}

// Rivens are a PRESET COLLECTION, on the same bar as builds and the
// optimizer's scopes: "+ new" is a new riven, ⧉ duplicates one to branch a
// roll, ✎ renames, ✕ deletes. Edits auto-save into the active riven, so
// there is no save button — the same contract as everywhere else.
const markRivenDirty = () => { if (typeof markPresetDirty === "function") markPresetDirty(); saveRivenSoon(); };
let rivenSaveTimer = null;
// A riven is CONSUMED by the builder (it is a mod in the pool), so deleting one
// can leave a slot pointing at an id that no longer exists — which nothing
// downstream says: the slot renders blank and the panel prices a build with a
// hole in it.
/// EVERY BUILD THAT NAMES THIS RIVEN, MOVED — or cleared when it is gone.
///
/// A riven's id IS its name (`riven:<name>`), so renaming and deleting are one
/// operation seen from a build. Touching the LIVE build only is too narrow — a
/// weapon's OTHER saved builds keep an id nothing resolves — and filing rivens
/// by FAMILY widens that across weapons.
///
/// THE SCOPE IS PASSED IN rather than derived here: rename and delete pass the
/// FAMILY's members, which is every weapon whose pool offers this card.
///
/// A SLOT IS RECOGNISED BY ITS `mod` and everything else by the exact string.
/// Clearing drops the RANK with it, which a blind string walk cannot do, while
/// anything storing the id some other way still gets swapped.
function repointRivenInBuilds(weapons, from, to) {
  const before = RIVEN_PREFIX + from;
  const after = to ? RIVEN_PREFIX + to : null;
  let moved = 0;
  const walk = (v) => {
    if (Array.isArray(v)) return v.map(walk);
    if (v && typeof v === "object") {
      if (v.mod === before) {
        moved++;
        return after ? { ...v, mod: after } : { ...v, mod: null, rank: null };
      }
      return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, walk(x)]));
    }
    return v === before ? (moved++, after) : v;
  };
  for (const id of weapons) {
    const key = `wfsim-presets-${id}-builder-builds`;
    const raw = localStorage.getItem(key);
    // The cheap gate: most weapons have never heard of this name, and parsing
    // every build list on every rename would be the expensive way to find out.
    if (!raw || raw.indexOf(before) < 0) continue;
    let list;
    try { list = JSON.parse(raw); } catch (_) { continue; }
    localStorage.setItem(key, JSON.stringify(walk(list)));
  }
  return moved;
}

/// The weapons that could be pointing at one of THIS weapon's rivens — every
/// entry filed under the same riven scope, which is what makes the card theirs
/// too. Derived from `rivenScope`, so a family that gains a variant tomorrow is
/// covered by nobody.
const rivenKinWeapons = () => {
  const scope = rivenScope($("weapon").value);
  return ((META && META.weapons) || [])
    .filter((w) => rivenScope(w.id) === scope).map((w) => w.id);
};

function pruneDanglingRivens() {
  let hit = false;
  slots.forEach((s) => {
    if (isRivenId(s.mod) && !modById(s.mod)) {
      s.mod = null; s.rank = null; hit = true;
    }
  });
  if (hit) { renderMods(); refreshPanel(); markPresetDirty(); }
}

function saveRivenSoon() {
  clearTimeout(rivenSaveTimer);
  rivenSaveTimer = setTimeout(() => {
    const ps = loadPresetList(RIVENS);
    const open = activeRivenId();
    const i = ps.findIndex((p) => p.id === open);
    if (i >= 0) {
      ps[i].state = snapshotRiven();
      storePresetList(RIVENS, ps);
      renderRivenTools();
      // The mod lists show each riven's generated name and printed values, so
      // they have to be re-asked for after an edit.
      refreshRivenNames();
    }
  }, 250);
}
// The saved shape keeps `bonuses`/`malus` at the top level — that is what
// the engine reads — and carries the other three drafts alongside so a
// reload does not flatten them back into one.
const snapshotRiven = () => ({
  bonuses: riven.bonuses, malus: riven.malus, rank: riven.rank, polarity: riven.polarity,
  shape: riven.shape, drafts: riven.drafts,
});
let activeRiven = null;
/// WHICH CARD IS OPEN, by id — two cards may share a name now, so a name could
/// not say which.
const activeRivenId = () => activeRiven || localStorage.getItem(presetActiveKey(RIVENS)) || "";

// A custom is a FILE, and the tools strip says which of two modes you are in:
// LIST, nothing open — a real state rather than an empty editor, since most
// weapons own no riven; and EDIT, one open, named, with "← back" closing it.
//
// Deliberately NOT the preset bar: a preset is a label you invented for a state
// your module is always in, while a riven is a thing with its own name,
// capacity and polarity that other modules consume.
// ---- CUSTOM ENEMIES: a target you MADE ---------------------------------
//
// A CUSTOM in AGENTS.md's sense: a thing you made that the OTHER modules
// consume — an entry in the scenario's target list, which is what makes it
// reach the simulator and the optimizer with no code of its own in either. NOT
// WEAPON-SCOPED, unlike a riven: a target is no more a statement about one
// weapon than a fight is, so this collection is SHARED across the roster
// (`SHARED_DOMAINS`) and there is no "⇤ import".
//
// THE ID IS THE NAME, and renaming repoints whatever names it — a custom exists
// only on the machine that made it, so its id comes from something the player
// typed rather than a table nobody can see.
const ENEMIES = "enemies";
const enemyId = (name) => "custom:" + name;
let activeEnemy = null;
let enemyDoc = null;

const DAMAGE_TYPES = ["impact", "puncture", "slash", "heat", "cold", "electricity",
  "toxin", "blast", "corrosive", "gas", "magnetic", "radiation", "viral", "void", "true"];
const SCALING_FACTIONS = ["grineer", "corpus", "infested", "corrupted", "unaffiliated"];

// The blank target: a plain humanoid with nothing unusual about it. Every
// number here is one the player is expected to replace — it is a starting
// point, not a claim about anything in game, which is what `synthetic` says.
const blankEnemy = () => ({
  synthetic: true,
  faction: "grineer",
  scaling_faction: "grineer",
  can_be_eximus: false,
  // A DIFFERENT MECHANIC from taking no damage of a type — see the engine's
  // `status_immunities`. This one moves the PROC DISTRIBUTION: an immune type
  // leaves the denominator and the rest renormalize onto the roll.
  status_immunities: [],
  stats: { base_level: 1, health: 1000, shield: 0, armor: 0, overguard: 0, affinity: 0 },
  // null = take the faction's own column. The moment a player writes one
  // value, the whole column becomes theirs — see `renderEnemyForm`.
  damage_modifiers: null,
  body_parts: [
    { name: "body", multiplier: 1, is_head: false, crit_bonus: false },
    { name: "head", multiplier: 3, is_head: true, crit_bonus: true },
  ],
});

const activeEnemyName = () => {
  if (activeEnemy === null) activeEnemy = localStorage.getItem(presetActiveKey(ENEMIES));
  return activeEnemy;
};
const snapshotEnemy = () => JSON.parse(JSON.stringify(enemyDoc));

/// Every custom target as an ENGINE enemy spec — the same type a published unit
/// has, which is why nothing downstream learns that an enemy can be homemade.
function customEnemySpecs() {
  return loadPresetList(ENEMIES).map((p) => ({
    ...blankEnemy(), ...(p.state || {}),
    id: enemyId(p.name),
    name: p.name,
  }));
}

/// …and as TARGET CARDS, in the shape `/api/meta` publishes, so the picker, the
/// card and the optimizer's read-only view need no branch for them.
function customEnemyCards() {
  const cols = Object.fromEntries((META.factions || []).map((f) => [f.id, f.modifiers]));
  return customEnemySpecs().map((e) => ({
    id: e.id,
    name: e.name,
    custom: true,
    synthetic: true,
    image: null,
    base_level: e.stats.base_level,
    can_be_eximus: !!e.can_be_eximus,
    faction: e.faction || "unknown",
    scaling: e.scaling_faction,
    health: e.stats.health,
    shield: e.stats.shield,
    armor: e.stats.armor,
    overguard: e.stats.overguard,
    unmodeled: [],
    status_immunities: e.status_immunities || [],
    type_modifiers: e.damage_modifiers
      ? Object.entries(e.damage_modifiers).filter(([, v]) => v !== 1)
          .map(([type, mult]) => ({ type, mult }))
      : (cols[e.faction] || []),
    parts: e.body_parts.map((b) => ({ name: b.name, multiplier: b.multiplier, is_head: b.is_head })),
  }));
}

/// THE TARGET LIST, published plus made. One function, because every reader of
/// `META.enemies` is asking "what can this fight be against", and the answer
/// stopped being the roster the moment a player could add to it.
const allEnemies = () => (META.enemies || []).concat(customEnemyCards());
const enemyCard = (id) => allEnemies().find((e) => e.id === id);

/// The custom targets a request has to carry, given the fight it describes.
/// Empty for a published unit — the server has heard of those.
const customEnemiesFor = (id) => customEnemySpecs().filter((e) => e.id === id);

/// THE FIGHT AS A REQUEST BODY. Every path that sends a scenario goes through
/// here, so "a custom target travels with the fight that names it" is one rule
/// rather than one per endpoint — the same reason a riven rides in `rivens`.
// ---- THE ARENA, seen from above -------------------------------------------
//
// A fight is two bodies on a floor, so it is DRAWN as two bodies on a floor and
// you move them with your finger. The picture is not a
// decoration: what it shows is the scenario, and what you drag IS the distance
// the simulation runs at.
//
// It draws the bodies at their REAL radius (`space::BODY_RADIUS_M`, 0.25 m), so
// "as close as they go" is something you can see rather than a rule you are
// told: the two circles touch at 0.5 m and will not pass through each other.
//
// METRES ARE THE UNIT and the view fits itself to them, with a floor on the
// span so a contact-range fight does not zoom to two enormous discs.
const BODY_R_M = 0.2;   // measured: contact stops at 0.4 m (M46)
const CONTACT_M = 2 * BODY_R_M;
// A FIXED INTERNAL COORDINATE SPACE, and the CSS stretches it. The scene used
// to be laid out in whatever pixel width the host happened to have, which is
// ZERO while the panel is on another tab — so the geometry came out NaN and a
// drag wrote `[null, null]` into the fight. A viewBox has no such moment.
const ARENA_VW = 320;
const ARENA_VH = 176;

/// Metres <-> pixels for the current pair of positions.
function arenaGeom(w, h, ...pts) {
  const pad = 1.2;                       // metres of air around the bodies
  const floor = 5;                       // never zoom closer than a 5 m view
  // EVERY BODY IN FRAME. It fitted exactly two until a formation could hold
  // fifty, and a scene that framed two of them would put the rest
  // off the edge — which is the one thing a picture of a fight must not do.
  const xs = pts.map((q) => q[0]), ys = pts.map((q) => q[1]);
  const [lo, hi] = [Math.min(...xs), Math.max(...xs)];
  const [bo, to] = [Math.min(...ys), Math.max(...ys)];
  const spanX = Math.max(hi - lo + 2 * pad, floor);
  const spanY = Math.max(to - bo + 2 * pad, (floor * h) / w);
  const s = Math.min(w / spanX, h / spanY);
  const cx = (lo + hi) / 2, cy = (bo + to) / 2;
  return {
    s,
    // y grows AWAY from the viewer, so "further up the screen" is "further off"
    px: (m) => [w / 2 + (m[0] - cx) * s, h / 2 - (m[1] - cy) * s],
    m: (x, y) => [cx + (x - w / 2) / s, cy - (y - h / 2) / s],
  };
}

/// Push `b` out of `a` so two bodies never overlap — along the line between
/// them, so a drag that overshoots SLIDES rather than snapping to an axis.
function keepApart(a, b) {
  const dx = b[0] - a[0], dy = b[1] - a[1];
  const d = Math.hypot(dx, dy);
  if (d >= CONTACT_M) return b;
  if (d < 1e-9) return [a[0], a[1] + CONTACT_M];
  const k = CONTACT_M / d;
  return [a[0] + dx * k, a[1] + dy * k];
}

/// Put the target `want` metres away, ALONG THE LINE it already stands on.
///
/// Direction is preserved rather than snapped to an axis: a quick-set and a
/// drag are two ways to move the same body, so neither may quietly undo the
/// other's other axis. Below contact it is pushed back out, the same rule the
/// drag obeys.
function setArenaDistance(s, want) {
  const [ax, ay] = s.player_at;
  let dx = s.target_at[0] - ax, dy = s.target_at[1] - ay;
  const d = Math.hypot(dx, dy);
  if (d < 1e-9) { dx = 0; dy = 1; }
  const u = d < 1e-9 ? 1 : d;
  // `want` is a GAP, and the model holds centres — one contact apart.
  const m = Math.max(CONTACT_M, want + CONTACT_M);
  s.target_at = [ax + (dx / u) * m, ay + (dy / u) * m];
}

/// The distances worth one click. CONTACT is first because it is where both
/// boards are scored; the rest are the ranges a falloff window and a spread
/// cone actually change hands at.
const ARENA_JUMPS = [0, 5, 10, 20, 40];

/// CENTRE TO CENTRE — the model's own distance, never below CONTACT_M.
const arenaSpan = (s) =>
  Math.hypot(s.target_at[0] - s.player_at[0], s.target_at[1] - s.player_at[1]);

/// THE GAP — surface to surface, and what a reader is shown. Zero at contact,
/// which is what point blank means to a player. The 0.4 m
/// between the two centres is the model's business; nobody should subtract it
/// to find out how far away they are standing. Everything the page displays,
/// sets and marks is this number; `engine::space::gap` is the same one.
const arenaDistance = (s) => Math.max(0, arenaSpan(s) - CONTACT_M);

/// EVERY BODY ON THE FLOOR, aimed one first — the order the api and the engine
/// both use, so nothing has to be reordered on the way out.
const arenaBodies = (s) => [s.target_at, ...(s.formation || []).map((f) => f.at)];

/// WHICH UNIT A BODY IS, AS A COLOUR — derived, never declared.
///
/// A formation can hold fifty bodies of several units and they were all one
/// red circle, so the only way to find out who was standing where was to click
/// each one. The cheap answer is the right one here: hash
/// the unit's id into a HUE. It costs no data file, no art, no translation and
/// no maintenance — a unit that arrives tomorrow already has a colour, and it
/// is the SAME colour on every machine and in every session, which a palette
/// handed out in load order would not be.
///
/// FNV-1a, because it is four lines and mixes short ASCII ids well; the id is
/// a stable English slug, so the colour is stable too. The saturation and
/// lightness are fixed so nothing lands on the floor's own grey or on the
/// accent, and the same hue is drawn as a swatch wherever a unit is NAMED —
/// the colour is only useful as a key if the key is somewhere.
const unitHue = (id) => {
  let h = 2166136261;
  for (let i = 0; i < String(id).length; i++) {
    h ^= String(id).charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h % 360;
};
const unitColor = (id, a) => `hsl(${unitHue(id)} 62% 58%${a === undefined ? "" : ` / ${a}`})`;
/// The unit a body is, by arena index — 0 is the aimed body, which is the
/// FIGHT's target, and the rest carry their own since 2026-08-18.
const unitAt = (s, i) => (i === 0
  ? s.enemy
  : ((s.formation || [])[i - 1] || {}).enemy || s.enemy);

/// WHERE THE WEAPON POINTS. `null` means "at the target", which is what every
/// scenario written before a formation existed means and what the app has
/// always done.
const arenaAim = (s) => s.aim_at || s.target_at;

/// FIFTY, the api's own cap — the sim pays for every body, so the page refuses
/// the same number the server refuses rather than a friendlier one.
// FROM THE ENGINE, never a copy of it (`formation::MAX_BODIES`, served at
// `/api/meta.max_bodies`). It was written out as 50 here, so the cap the server
// enforces and the cap the canvas offers were two numbers that happened to
// agree — until the ruler work raised one of them. The fallback is only for a
// meta that failed to load, where nothing else works either.
const ARENA_MAX_BODIES = () => (META && META.max_bodies) || 50;

/// WHICH BODY A SHOT CROSSES FIRST — `engine::space::first_hit`, drawn rather
/// than computed for damage. The page needs it for ONE reason: to show which
/// body the beam is on, because aiming is a direction and the answer is not
/// always the nearest thing to the cursor.
function arenaFirstHit(s) {
  const bodies = arenaBodies(s);
  const aim = arenaAim(s);
  const [px, py] = s.player_at;
  const span = Math.hypot(aim[0] - px, aim[1] - py) || 1;
  const [ux, uy] = [(aim[0] - px) / span, (aim[1] - py) / span];
  const [mx, my] = [px + ux * BODY_R_M, py + uy * BODY_R_M];
  let best = null;
  bodies.forEach((b, i) => {
    const [dx, dy] = [b[0] - mx, b[1] - my];
    const along = dx * ux + dy * uy;
    if (along < 0) return;
    if (Math.abs(dx * uy - dy * ux) > BODY_R_M) return;
    if (!best || along < best[1]) best = [i, along];
  });
  return best ? best[0] : -1;
}

/// THE SCENE. `heat` shades each body by what it TOOK and `sel` marks the one
/// being examined — both absent when this is the scenario's own canvas.
///
/// SETTING UP A FIGHT AND READING ONE ARE TWO THINGS, and
/// the same picture serves both only because it is the same FIGHT. The
/// scenario's copy is where a body is placed and carries no result; the result
/// panel's copy is read-only, coloured by the answer, and clicking a body picks
/// it. Neither can be mistaken for the other, and neither is the other's
/// control.
function arenaSvg(s, en, heat, sel) {
  const w = ARENA_VW, h = ARENA_VH;
  const bodies = arenaBodies(s);
  const aim = arenaAim(s);
  const g = arenaGeom(w, h, s.player_at, ...bodies, aim);
  const [px, py] = g.px(s.player_at);
  const [tx, ty] = g.px(aim);
  const r = Math.max(3, BODY_R_M * g.s);
  // A GRID THAT STAYS READABLE: the step grows with the zoom so the lines
  // never crowd, and it is labelled, because a scale nobody can read is a
  // picture rather than a measurement.
  const step = [0.5, 1, 2, 5, 10, 20, 50, 100].find((k) => k * g.s >= 26) || 200;
  const lines = [];
  const [x0, y1] = g.m(0, 0), [x1, y0] = g.m(w, h);
  for (let x = Math.ceil(x0 / step) * step; x <= x1; x += step) {
    lines.push(`<line class="ar-grid" x1="${g.px([x, 0])[0].toFixed(1)}" y1="0" x2="${g.px([x, 0])[0].toFixed(1)}" y2="${h}"/>`);
  }
  for (let y = Math.ceil(y0 / step) * step; y <= y1; y += step) {
    const yy = g.px([0, y])[1].toFixed(1);
    lines.push(`<line class="ar-grid" x1="0" y1="${yy}" x2="${w}" y2="${yy}"/>`);
  }
  const d = arenaDistance(s);
  // THE MUZZLE — where the shot actually leaves, a point on the player's own
  // circumference facing the target (`engine::space::muzzle`). Drawn because
  // it is load-bearing rather than decorative: the cone widens over the flight
  // from HERE, which is one radius shorter than the line between the two
  // bodies, and at contact it puts the muzzle on the enemy's surface — which
  // is why nothing misses there.
  // …AND IT FACES WHERE THE WEAPON POINTS, which may be a body or bare floor.
  const span = Math.hypot(tx - px, ty - py) || 1;
  const ux = (tx - px) / span, uy = (ty - py) / span;
  const mx = px + ux * r, my = py + uy * r;
  const struck = arenaFirstHit(s);
  // THE SHOT STOPS WHERE IT STOPS, and the line says so. Solid from the muzzle
  // to the body it actually reaches; DASHED on from there to wherever you are
  // pointing. Aiming past a body is legal and common — you point at the one
  // behind — and without this the scene showed a line running through a body it
  // cannot pass. No punch-through is modelled, so the first
  // body on the line is where it ends.
  const hitPx = struck >= 0 ? g.px(bodies[struck]) : null;
  const stop = hitPx
    ? [hitPx[0] - ux * r, hitPx[1] - uy * r]
    : [tx, ty];
  const sight = `<line class="ar-link" x1="${mx.toFixed(1)}" y1="${my.toFixed(1)}" `
    + `x2="${stop[0].toFixed(1)}" y2="${stop[1].toFixed(1)}"/>`
    + (hitPx && (Math.abs(stop[0] - tx) > 1 || Math.abs(stop[1] - ty) > 1)
      ? `<line class="ar-past" x1="${stop[0].toFixed(1)}" y1="${stop[1].toFixed(1)}" `
        + `x2="${tx.toFixed(1)}" y2="${ty.toFixed(1)}"/>`
      : "");
  const foes = bodies.map((b, i) => {
    const [bx, by] = g.px(b);
    // THE ONE THE BEAM IS ON is marked, because aiming at a place means the
    // answer is not always what the cursor is nearest to.
    const cls = (i === struck ? " ar-struck" : "")
      + (heat ? " ar-heat" : "")
      + (sel === i ? " ar-sel" : "");
    // HOW MUCH IT TOOK, as a share of the worst-hit body. A body that took
    // NOTHING keeps the outline it has on the scenario's canvas, which is what
    // makes "the chain reached nobody" visible at a glance rather than a table
    // to read.
    const fill = heat && heat[i] > 0
      ? ` style="fill-opacity:${(0.15 + 0.75 * heat[i]).toFixed(3)}"` : "";
    return `<circle class="ar-body ar-foe${cls}" data-drag="foe:${i}" data-foe="${i}"${fill} `
      + `cx="${bx.toFixed(1)}" cy="${by.toFixed(1)}" r="${r.toFixed(1)}"/>`;
  }).join("");
  // A short arrow past the muzzle says which way the body is FACING, so a
  // player being turned by their own aim is visible rather than implied.
  const ax = mx + ux * 9, ay = my + uy * 9;
  const nose = `<line class="ar-face" x1="${mx.toFixed(1)}" y1="${my.toFixed(1)}" x2="${ax.toFixed(1)}" y2="${ay.toFixed(1)}"/>
    <circle class="ar-muzzle" cx="${mx.toFixed(1)}" cy="${my.toFixed(1)}" r="2.2"/>`;
  return `<svg class="ar-svg" viewBox="0 0 ${w} ${h}" preserveAspectRatio="xMidYMid meet">
    ${lines.join("")}
    ${sight}
    ${foes}
    <circle class="ar-aim" data-drag="aim" cx="${tx.toFixed(1)}" cy="${ty.toFixed(1)}" r="${(r * 0.7).toFixed(1)}"/>
    <circle class="ar-body ar-you" data-drag="player_at" cx="${px.toFixed(1)}" cy="${py.toFixed(1)}" r="${r.toFixed(1)}"/>
    ${nose}
    <text class="ar-tag ar-tag-you" x="${px.toFixed(1)}" y="${(py + r + 13).toFixed(1)}">${escHtml(tr("You"))}</text>
    <text class="ar-tag ar-tag-foe" x="${g.px(bodies[Math.max(struck, 0)])[0].toFixed(1)}" y="${(g.px(bodies[Math.max(struck, 0)])[1] - r - 6).toFixed(1)}">${escHtml((en && en.name) || tr("Enemy"))}</text>
    <text class="ar-dist" x="${((px + tx) / 2).toFixed(1)}" y="${((py + ty) / 2 - 8).toFixed(1)}">${d.toFixed(2)} m</text>
    <text class="ar-scale" x="6" y="${h - 6}">${step} m ${escHtml(tr("grid"))}</text>
  </svg>`;
}

/// Draw the scene into `host` and let the two bodies be dragged.
///
/// The drag writes the LIVE scenario and repaints the SVG on every move — the
/// whole panel is not re-rendered until the finger comes up, because the panel
/// contains the thing being dragged and rebuilding it mid-gesture drops the
/// pointer capture.
/// THE NEXT UNUSED NAME in this scenario — `e2` upward, `e1` being the aimed
/// body's and not ours to give.
///
/// One PAST the highest ever used rather than one past the count, so deleting a
/// body never hands its name to the next one.
const nextFoeId = (s) => {
  const n = (s.formation || []).reduce((m, f) => {
    const k = Number(String(f.id || "").replace(/^e/, ""));
    return Number.isFinite(k) ? Math.max(m, k) : m;
  }, 1);
  return `e${n + 1}`;
};

/// ADD A BODY, somewhere it does not stand on anyone.
///
/// It walks OUTWARD in a ring around the target rather than dropping every new
/// enemy on one spot: a formation you have to untangle before you can read it
/// is worse than no formation. Three metres is the owner's own fixture spacing
/// and the distance a chain's step edges sit at.
function arenaAddFoe(s) {
  if (1 + (s.formation || []).length >= ARENA_MAX_BODIES()) return false;
  const [cx, cy] = s.target_at;
  const taken = arenaBodies(s);
  const clear = (p) => taken.every((q) => Math.hypot(q[0] - p[0], q[1] - p[1]) > CONTACT_M + 1e-6);
  for (let ring = 1; ring <= 8; ring++) {
    for (let k = 0; k < ring * 8; k++) {
      const a = (k / (ring * 8)) * Math.PI * 2;
      const at = [cx + Math.cos(a) * ring * 3, cy + Math.sin(a) * ring * 3];
      if (clear(at)) {
        // NAMED WHERE IT IS CREATED. The server fills a blank id in by
        // POSITION, which is right for a scenario written before ids existed
        // and wrong for one being edited: delete the body in front and every
        // name behind it shifts, so a roll call, a heat map and a debuff table
        // would all be about somebody else.
        //
        // NEVER REUSED inside one scenario, which is what makes it an identity
        // rather than a label. `e1` is the aimed body's and is not ours to give.
        // STAMPED WITH THE UNIT, like every other placement — see `placeAt`.
        // A blank one means "whatever the aimed body is", which is what a
        // scenario written before this means and is not what a body being
        // placed now means.
        s.formation.push({ at, enemy: s.enemy, level: null, id: nextFoeId(s) });
        return true;
      }
    }
  }
  return false;
}

/// KEEP A DRAGGED BODY OUT OF EVERYONE ELSE, not just out of the player.
/// Circles do not overlap, and that rule was written for two bodies
/// (`engine::space::CONTACT_RANGE_M`); with fifty it has to hold pairwise.
/// WHERE A DRAGGED BODY MAY ACTUALLY GO — or `null`, meaning it does not move.
///
/// A body is pushed out of the ONE body it is entering, which is what makes two
/// circles touch at contact and slide along each other instead of passing
/// through. It is not iterated: NOTHING ELSE MOVES, and a body that has nowhere
/// legal to go simply stays where it was.
///
/// The old version projected repeatedly, four passes over every body. With two
/// on the floor that is the same answer; in a CROWD it is not — it squeezed the
/// dragged body through gaps until it found somewhere to sit, so a drag toward
/// a packed rank ended somewhere the finger never went. Refusing is the honest
/// answer to "there is no room here", and it makes a wedged body immovable,
/// which is what a wedged body is.
function arenaSettle(s, at, skip) {
  const others = [s.player_at, ...arenaBodies(s).filter((_, i) => i !== skip)];
  const clash = (p) => others.filter((q) => Math.hypot(p[0] - q[0], p[1] - q[1]) < CONTACT_M - 1e-9);
  const hit = clash(at);
  if (!hit.length) return at;
  // THE NEAREST ONE decides, so the slide is along the surface being pressed.
  const q = hit.reduce((a, b) =>
    Math.hypot(at[0] - a[0], at[1] - a[1]) <= Math.hypot(at[0] - b[0], at[1] - b[1]) ? a : b);
  const d = Math.hypot(at[0] - q[0], at[1] - q[1]);
  // Dead centre has no direction to be pushed in; take the one away from the
  // shooter, which is the only axis the scene always has.
  const p = d < 1e-9
    ? [q[0], q[1] + CONTACT_M]
    : [q[0] + (at[0] - q[0]) * (CONTACT_M / d), q[1] + (at[1] - q[1]) * (CONTACT_M / d)];
  // …AND IF THAT LANDS IN SOMEBODY ELSE, THERE IS NO ROOM. Refused rather than
  // projected again: a second push is how the body ends up somewhere nobody
  // dragged it to.
  return clash(p).length ? null : p;
}

/// IS THE SCENE ACCEPTING DRAGS FROM A FINGER?
///
/// OFF BY DEFAULT, and the whole reason is that a browser decides who owns a
/// gesture at `pointerdown` and never gives it back. A body that drags on touch
/// means the finger that started on it can no longer SCROLL — and a 19x19
/// formation covers the canvas in bodies, so on a phone almost every scroll
/// past the arena dragged an enemy instead. The fight moved silently and the
/// result it had just produced was for a fight nobody was in any more.
///
/// A LONG PRESS CANNOT FIX IT: once the browser has given the gesture to
/// scrolling it is gone, so claiming it later is not something the page can do.
/// The honest answer is a MODE the reader turns on, which is also what makes
/// "why can I not move anything" answerable — the button is right there.
///
/// A MOUSE IS UNAFFECTED: it has no scroll to lose, so it drags either way.
let arenaTouchDrag = false;

/// THE ARENA AS AN EDITOR — an infinite canvas you pan, zoom and lay a fight
/// out on: it should feel like Miro or n8n, not like a picture with chips
/// beside it.
///
/// WHAT AN EDITOR NEEDS AND A PICTURE DOES NOT: a floor that extends as far as
/// you drag, a tool that paints bodies where the pointer goes, a marquee that
/// selects them, and a drag that moves the whole selection. A fixed viewBox
/// framing itself to its contents rescales a formation under your hand and
/// leaves nowhere to put a body outside the frame.
///
/// THE TRUTH IS STILL `sim`. There is no scene state — every gesture writes
/// `player_at`, `target_at`, `aim_at` or `formation` and redraws from them, so
/// this is a VIEW of the fight in exactly the way the old one was and nothing
/// downstream (the payload, the share link, the checks that read the scenario)
/// has to learn that the picture changed.
///
/// NOTHING MOVES A BODY FOR YOU unless you asked, and the two things that can
/// are switches on screen: SNAP puts what you place on the grid you can SEE,
/// off by default; COLLIDE keeps two bodies out of the same ground, on by
/// default because it is the engine's own contact rule.
function mountArenaCanvas(host, s, en, opts) {
  const ro = () => opts.readonly || officialScenarioActive();

  // THE TARGET'S OWN CONTROLS ARE ALREADY HERE, rendered by the caller into
  // this host. They are MOVED into the scene rather than re-serialised: an
  // `innerHTML` round trip would drop `pick.onclick`, every `data-k` listener
  // the scenario binding attached, and the identity of every node something
  // else holds a reference to. Detach, build, re-attach.
  const side = host.querySelector(".arc-side");
  if (side) side.remove();
  // THE LOGIC LINE: LEFT IS THE VERB, RIGHT IS THE NOUN.
  //
  //   · LEFT — what you are about to DO. The tools, and directly under them
  //     what the active tool acts WITH: the place tool's brush is an enemy, so
  //     the enemy's own card, level and Steel Path live there. Brush settings
  //     belong with the brush. Under those, the two switches, which are about
  //     how the doing behaves.
  //   · RIGHT — what you have SELECTED. Click a body and this says which one,
  //     where it stands, how far off it is and whether the shot is on it. With
  //     nothing picked it describes the fight instead, which is the honest
  //     answer to "what am I looking at".
  //   · BOTTOM — the read-outs, which are nobody's control.
  //
  // A card floating top-right is BOTH of those things at once: it names the
  // enemy you are placing and it is the only thing the right-hand side says.
  // One panel doing two jobs is why neither is findable.
  host.innerHTML =
    `<div class="arc-wrap">
       <canvas class="arc-cv"></canvas>
       <div class="arc-left">
         <div class="arc-rail" role="toolbar" aria-label="${escHtml(tr("Tools"))}"></div>
         <div class="arc-brush"></div>
         <div class="arc-opts"></div>
         <div class="arc-chips"></div>
       </div>
       <div class="arc-insp"></div>
       <div class="arc-read num"></div>
     </div>
     `;
  const wrap = host.querySelector(".arc-wrap");
  // THE BRUSH IS WHAT YOU PLACE, so the caller's enemy card and its fields go
  // into the LEFT column beside the place tool rather than floating on their
  // own. Moved, never re-serialised — see above.
  if (side) host.querySelector(".arc-brush").appendChild(side);
  const cv = host.querySelector(".arc-cv");
  const ctx = cv.getContext("2d");
  const rail = host.querySelector(".arc-rail");
  const optbox = host.querySelector(".arc-opts");
  const readout = host.querySelector(".arc-read");
  const chipbox = host.querySelector(".arc-chips");
  const insp = host.querySelector(".arc-insp");

  // ---- the view ---------------------------------------------------------
  // METRES ARE THE UNIT and `k` is pixels per metre. Nothing here is stored in
  // the scenario: where you are LOOKING is not part of the fight.
  const view = { x: 0, y: 0, k: 26 };
  let W = 0, H = 0;
  const px = (p) => [W / 2 + (p[0] - view.x) * view.k, H / 2 - (p[1] - view.y) * view.k];
  const mt = (x, y) => [view.x + (x - W / 2) / view.k, view.y - (y - H / 2) / view.k];

  let tool = "select";
  let snapGrid = false, collide = true;
  const sel = new Set();          // indices into `arenaBodies(s)`
  let space = false, panning = false, dragging = false, marquee = null;
  let mode = null, last = null, dragFrom = null, painted = null;
  const touches = new Map();
  let pinch = null;

  const gridStep = () => (view.k < 9 ? 10 : 2);
  const snapTo = (p) => {
    if (!snapGrid) return p;
    const g = gridStep();
    return [Math.round(p[0] / g) * g, Math.round(p[1] / g) * g];
  };
  const bodyAt = (i) => (i === 0 ? s.target_at : (s.formation[i - 1] || {}).at);

  // ---- drawing ----------------------------------------------------------
  const cssv = (n) => getComputedStyle(document.documentElement)
    .getPropertyValue("--" + n).trim() || "#888";

  function fit() {
    const pts = [...arenaBodies(s), s.player_at, arenaAim(s)];
    const xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1]);
    const pad = 2;
    const w = Math.max(Math.max(...xs) - Math.min(...xs) + pad * 2, 6);
    const h = Math.max(Math.max(...ys) - Math.min(...ys) + pad * 2, 6);
    view.k = Math.min(160, Math.max(1.6, Math.min(W / w, H / h)));
    view.x = (Math.min(...xs) + Math.max(...xs)) / 2;
    view.y = (Math.min(...ys) + Math.max(...ys)) / 2;
  }

  function grid() {
    const step = gridStep();
    const [x0, y1] = mt(0, 0), [x1, y0] = mt(W, H);
    ctx.lineWidth = 1;
    for (let pass = 0; pass < 2; pass++) {
      const g = pass ? step * 5 : step;
      if (pass === 0 && view.k * g < 11) continue;
      ctx.strokeStyle = pass ? cssv("arc-grid2") : cssv("arc-grid");
      ctx.beginPath();
      for (let x = Math.ceil(x0 / g) * g; x <= x1; x += g) {
        const q = Math.round(px([x, 0])[0]) + 0.5;
        ctx.moveTo(q, 0); ctx.lineTo(q, H);
      }
      for (let y = Math.ceil(y0 / g) * g; y <= y1; y += g) {
        const q = Math.round(px([0, y])[1]) + 0.5;
        ctx.moveTo(0, q); ctx.lineTo(W, q);
      }
      ctx.stroke();
    }
  }

  function draw() {
    if (!W || !H) return;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = cssv("panel3"); ctx.fillRect(0, 0, W, H);
    grid();

    const r = Math.max(2.5, BODY_R_M * view.k);
    const bodies = arenaBodies(s);
    const aim = arenaAim(s);
    const struck = arenaFirstHit(s);
    const you = px(s.player_at), aimS = px(aim);

    // THE MUZZLE, and the line from it. A straight-line weapon does not stop
    // where you point — the aim marker is a DIRECTION, so
    // the line runs through it and off the floor.
    const span = Math.hypot(aim[0] - s.player_at[0], aim[1] - s.player_at[1]) || 1;
    const u = [(aim[0] - s.player_at[0]) / span, (aim[1] - s.player_at[1]) / span];
    const mz = px([s.player_at[0] + u[0] * BODY_R_M, s.player_at[1] + u[1] * BODY_R_M]);
    const su = [u[0], -u[1]];
    ctx.save();
    ctx.strokeStyle = cssv("accent"); ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(mz[0], mz[1]);
    ctx.lineTo(mz[0] + su[0] * 4000, mz[1] + su[1] * 4000); ctx.stroke();
    ctx.restore();

    for (let i = 0; i < bodies.length; i++) {
      const [x, y] = px(bodies[i]);
      if (x < -r * 3 || x > W + r * 3 || y < -r * 3 || y > H + r * 3) continue;
      const on = sel.has(i);
      // ITS UNIT'S COLOUR (see `unitHue`), so a mixed formation reads as one
      // without clicking through it. SELECTION still wins the outline, because
      // "which ones am I about to move" is the more urgent question and the hue
      // is still visible in the fill underneath.
      const col = unitColor(unitAt(s, i));
      ctx.beginPath(); ctx.arc(x, y, r, 0, 7);
      ctx.fillStyle = col;
      ctx.globalAlpha = i === struck ? 0.62 : on ? 0.5 : 0.3; ctx.fill();
      ctx.globalAlpha = 1;
      ctx.lineWidth = on || i === struck ? 2 : 1.25;
      ctx.strokeStyle = on ? cssv("accent") : col;
      ctx.stroke();
      // THE ONE THE SHOT IS ON, ringed: aiming at a place means the answer is
      // not always the body nearest the cursor.
      if (i === struck) {
        ctx.beginPath(); ctx.arc(x, y, r + 4, 0, 7);
        ctx.strokeStyle = cssv("accent"); ctx.lineWidth = 1.3;
        ctx.setLineDash([3, 3]); ctx.stroke(); ctx.setLineDash([]);
      }
    }

    ctx.beginPath(); ctx.arc(you[0], you[1], Math.max(3, r), 0, 7);
    ctx.fillStyle = cssv("gold"); ctx.globalAlpha = 0.45; ctx.fill(); ctx.globalAlpha = 1;
    ctx.lineWidth = 2; ctx.strokeStyle = cssv("gold"); ctx.stroke();
    // …and a short arrow past the muzzle, so being turned by your own aim is
    // visible rather than implied.
    ctx.beginPath(); ctx.moveTo(mz[0], mz[1]);
    ctx.lineTo(mz[0] + su[0] * 11, mz[1] + su[1] * 11); ctx.stroke();

    // THE AIM MARKER, always drawn: it is a place you set, not a lock that
    // finds a body.
    ctx.beginPath(); ctx.arc(aimS[0], aimS[1], 6.5, 0, 7);
    ctx.strokeStyle = cssv("accent"); ctx.lineWidth = 2; ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(aimS[0] - 10, aimS[1]); ctx.lineTo(aimS[0] + 10, aimS[1]);
    ctx.moveTo(aimS[0], aimS[1] - 10); ctx.lineTo(aimS[0], aimS[1] + 10);
    ctx.lineWidth = 1; ctx.stroke();

    if (marquee) {
      const [x0, y0] = marquee.a, [x1, y1] = marquee.b;
      const [lx, ly] = [Math.min(x0, x1), Math.min(y0, y1)];
      const [w, h] = [Math.abs(x1 - x0), Math.abs(y1 - y0)];
      ctx.fillStyle = cssv("accent"); ctx.globalAlpha = 0.1;
      ctx.fillRect(lx, ly, w, h); ctx.globalAlpha = 1;
      ctx.strokeStyle = cssv("accent"); ctx.lineWidth = 1;
      ctx.setLineDash([4, 3]); ctx.strokeRect(lx + 0.5, ly + 0.5, w, h); ctx.setLineDash([]);
    }
    paintReadout();
    paintInspector();
  }

  /// WHAT YOU HAVE PICKED, in the top right and nowhere else.
  ///
  /// A body is identified by its NAME (`e1`, `e2`, …) because that is what the
  /// roll call, the heat map and the debuff table use — a scene that called it
  /// something else would be the fourth spelling of the same body.
  function paintInspector() {
    const bodies = arenaBodies(s);
    const struck = arenaFirstHit(s);
    const nameOf = (i) => (i === 0
      ? tr("the aimed target")
      : (s.formation[i - 1] || {}).id || "e" + (i + 1));
    const row = (k, v) => `<div class="ai-row"><span>${escHtml(k)}</span>`
      + `<span class="num">${escHtml(String(v))}</span></div>`;
    const gapTo = (b) => Math.max(0,
      Math.hypot(b[0] - s.player_at[0], b[1] - s.player_at[1]) - CONTACT_M).toFixed(2) + " m";

    // WHO IT IS COMES FIRST. A body's NAME is `e3` — what
    // the roll call, the heat map and the debuff table call it, so the header
    // has to say it too or they are about different enemies. But `e3` alone
    // does not tell a reader WHICH of fifty bodies they just picked, and
    // finding that out is the whole reason to pick one. So the identity goes
    // above the geometry: the unit, its art, its LEVEL and what it is made of
    // at that level — `enemyMeta` is the enemy card's own line, which reads the
    // engine's answer once `loadTargetStats` has given it.
    //
    // A body placed on the floor carries no unit of its own (the place tool
    // pushes a position and nothing else), so it IS the scenario's enemy at the
    // scenario's level. Reading it that way is what makes this panel agree with
    // what the sim will actually field.
    const unitOf = (i) => {
      const f = i === 0 ? null : s.formation[i - 1] || {};
      const id = (f && f.enemy) || s.enemy;
      return { id, en: allEnemies().find((e) => e.id === id), level: (f && f.level) || s.level };
    };
    // THE SWATCH IS THE KEY TO THE FLOOR. The bodies are drawn in their unit's
    // hue (`unitHue`), which is only useful if the same hue is beside the name
    // somewhere — this is that somewhere.
    const swatch = (id) => `<i class="ai-sw" style="background:${unitColor(id)}"></i>`;
    if (sel.size === 1) {
      const i = [...sel][0];
      const b = bodies[i];
      if (b) {
        const { id, en, level } = unitOf(i);
        const art = IMG(en && en.image);
        insp.innerHTML = `<p class="ai-h">${escHtml(nameOf(i))}</p>`
          + `<div class="ai-who">`
          + (art ? `<img src="${escHtml(art)}" alt="">` : "")
          + `<div><b>${swatch(id)}${escHtml((en && en.name) || tr("Enemy"))}</b>`
          + `<span>${escHtml(tr("Level"))} ${escHtml(String(level))}`
          + `${s.steel_path ? " · " + escHtml(tr("Steel Path")) : ""}</span>`
          + `<span>${escHtml(enemyMeta(en))}</span></div></div>`
          + row(tr("at"), `${b[0].toFixed(1)}, ${b[1].toFixed(1)}`)
          + row(tr("from you"), gapTo(b))
          + row(tr("on the shot line"), i === struck ? tr("yes") : tr("no"));
        return;
      }
    }
    if (sel.size > 1) {
      const picked = [...sel].map((i) => bodies[i]).filter(Boolean);
      const xs = picked.map((q) => q[0]), ys = picked.map((q) => q[1]);
      insp.innerHTML =
        `<p class="ai-h">${escHtml(String(sel.size))} ${escHtml(tr("selected"))}</p>`
        + row(tr("centre"), `${((Math.min(...xs) + Math.max(...xs)) / 2).toFixed(1)}, `
          + `${((Math.min(...ys) + Math.max(...ys)) / 2).toFixed(1)}`)
        + row(tr("spread"), `${(Math.max(...xs) - Math.min(...xs)).toFixed(1)} x `
          + `${(Math.max(...ys) - Math.min(...ys)).toFixed(1)} m`)
        + row(tr("nearest to you"), gapTo(picked.reduce((a, q) =>
          Math.hypot(q[0] - s.player_at[0], q[1] - s.player_at[1])
            < Math.hypot(a[0] - s.player_at[0], a[1] - s.player_at[1]) ? q : a, picked[0])));
      return;
    }
    // NOTHING PICKED IS AN ANSWER TOO: describe the fight, since that is what
    // you are looking at.
    const { id, en, level } = unitOf(0);
    insp.innerHTML = `<p class="ai-h">${escHtml(tr("the fight"))}</p>`
      + `<div class="ai-who">`
      + (IMG(en && en.image) ? `<img src="${escHtml(IMG(en.image))}" alt="">` : "")
      + `<div><b>${swatch(id)}${escHtml((en && en.name) || tr("Enemy"))}</b>`
      + `<span>${escHtml(tr("Level"))} ${escHtml(String(level))}`
      + `${s.steel_path ? " · " + escHtml(tr("Steel Path")) : ""}</span></div></div>`
      + row(tr("enemy count"), bodies.length)
      + row(tr("range"), gapTo(bodies[Math.max(struck, 0)] || s.target_at))
      + row(tr("aim"), s.aim_at ? tr("a place of its own") : tr("on the target"))
      + `<p class="ai-hint">${escHtml(tr("click a body to inspect it"))}</p>`;
  }

  function paintReadout() {
    const n = arenaBodies(s).length;
    readout.textContent =
      `${n} ${n === 1 ? tr("enemy") : tr("enemies")}  ·  ${arenaDistance(s).toFixed(2)} m` +
      (sel.size ? `  ·  ${sel.size} ${tr("selected")}` : "");
  }

  // READ-ONLY IS ASKED LIVE, not baked in at mount: switching to an official
  // ruler must disable these without a re-render.
  const dis = () => (ro() ? " disabled" : "");

  // ---- WHAT THE CANVAS DID NOT REPLACE ----------------------------------
  //
  // There is no row of quick sets under the scene: the canvas is better to
  // use, so the controls beside it are gone. Each was a way to do something a
  // static scene could not: `contact/5/10/20/40 m` because you could not drag
  // to a
  // distance in a picture that reframed itself, `+1` and `+8` because there
  // was no way to place a body, `one enemy` because there was no way to
  // remove one. Dragging, painting and erasing are those four things, done
  // directly.
  //
  // TWO SURVIVE, because nothing replaced them, and they are canvas controls
  // rather than a row of chips:
  //
  //   · AIM AT THE TARGET. Aim becomes a place of its own the moment you click
  //     the floor, and there is no gesture that means "stop being a place" —
  //     so it needs a control or it is a one-way door.
  //   · THE MOVE MODE. Not an edit to the fight at all: it decides whether a
  //     FINGER belongs to the page's scroll or to this scene, and it is drawn
  //     only where a finger can be the pointer.
  function paintChips() {
    chipbox.innerHTML =
      (s.aim_at
        ? `<button class="arc-opt" data-unaim="1"${dis()}>${
          escHtml(tr("aim at the target"))}</button>`
        : "")
      // A FINGER SCROLLS; IT DOES NOT DRAG THE FIGHT. The
      // rule survived the move to a canvas and so did its reason: a browser
      // decides who owns a gesture at `pointerdown` and never gives it back.
      // `maxTouchPoints`, not a `pointer: coarse` query — a touchscreen laptop
      // reports a FINE pointer and has the same problem. Two fingers are still
      // the view whatever this says.
      + (navigator.maxTouchPoints > 0
        ? `<button class="arc-opt${arenaTouchDrag ? " on" : ""}" data-touchdrag="1"
           aria-pressed="${arenaTouchDrag}"
           title="${escHtml(tr("while this is on, dragging a body moves it instead of scrolling the page"))}"
           >✥ ${escHtml(tr("move"))}</button>`
        : "");
  }

  // ---- the tool rail ----------------------------------------------------
  const TOOLS = [
    ["select", "V", tr("Select"), '<path d="M4 3l6 14 2.2-5.6L18 9.2z"/>'],
    ["place", "B", tr("Place enemies"),
      '<circle cx="8" cy="8" r="3.1"/><circle cx="14.5" cy="13.5" r="3.1"/><path d="M4 16.5h2.6M5.3 15.2v2.6"/>'],
    // AIM IS A TOOL, because it stopped being a side effect. A bare click used
    // to aim, which meant every mis-click while selecting silently re-aimed the
    // weapon; and once it does not, a fight whose aim has never been moved has
    // NOTHING TO GRAB — the marker rides the target, so it sits exactly where
    // the body is and the body wins the grab. An explicit verb answers both:
    // pick it up and drag, and the marker stays draggable in Select afterwards
    // because by then it is a thing of its own standing on the floor.
    ["aim", "A", tr("Aim"),
      '<circle cx="11" cy="11" r="6.2"/><path d="M11 1.6v3.4M11 17v3.4M1.6 11H5m12 0h3.4"/>'],
    ["erase", "E", tr("Erase"),
      '<path d="M6.5 16.5h9"/><path d="M4.6 12.4l5.4-5.4a2 2 0 012.8 0l2.6 2.6a2 2 0 010 2.8l-3.6 3.6H7.4z"/>'],
    ["hand", "H", tr("Pan"),
      '<path d="M7 11V5.4a1.3 1.3 0 012.6 0V10m0-.6V4.6a1.3 1.3 0 012.6 0V10m0-.8V5.8a1.3 1.3 0 012.6 0v6.4c0 3.2-2 5.3-5.2 5.3-2.4 0-3.6-1-4.7-2.6L4.6 12a1.3 1.3 0 012.1-1.5z"/>'],
  ];
  function paintRail() {
    rail.innerHTML = TOOLS.map(([id, key, title, svg]) =>
      `<button class="arc-tool" data-tool="${id}" title="${escHtml(title)} (${key})"
         aria-label="${escHtml(title)}" aria-pressed="${id === tool}"${
        id === "hand" ? "" : dis()}>
         <svg viewBox="0 0 22 22">${svg}</svg></button>`).join("");
    optbox.innerHTML =
      `<button class="arc-opt" data-opt="snap" aria-pressed="${snapGrid}"${dis()}
         title="${escHtml(tr("put what you place and drag on the grid you can see"))}">${
        escHtml(tr("snap"))}</button>`
      + `<button class="arc-opt" data-opt="collide" aria-pressed="${collide}"${dis()}
         title="${escHtml(tr("keep two bodies out of the same ground - the engine's own contact rule"))}">${
        escHtml(tr("collide"))}</button>`
      + `<button class="arc-opt" data-opt="fit" title="${escHtml(tr("frame everything"))}">${
        escHtml(tr("fit"))}</button>`;
  }

  const changed = () => {
    paintChips(); paintRail(); draw();
    markScenarioDirty();
    if (opts.after) opts.after();
  };

  // ---- placement --------------------------------------------------------
  const clearAt = (p, skip) => {
    if (!collide) return true;
    const bodies = arenaBodies(s);
    return bodies.every((b, i) => i === skip
      || Math.hypot(b[0] - p[0], b[1] - p[1]) >= CONTACT_M - 1e-9)
      && Math.hypot(s.player_at[0] - p[0], s.player_at[1] - p[1]) >= CONTACT_M - 1e-9;
  };
  function placeAt(raw) {
    const p = snapTo(raw);
    const floor = collide ? 0 : BODY_R_M;
    if (painted && Math.hypot(painted[0] - p[0], painted[1] - p[1]) < floor) return;
    if (arenaBodies(s).length >= ARENA_MAX_BODIES() || !clearAt(p)) return;
    s.formation = s.formation || [];
    // A BODY IS THE UNIT IT WAS PLACED WITH. The brush on
    // the left says what you are ABOUT to place; it does not reach back and
    // rewrite what is already standing on the floor. Placing a Gunner and then
    // picking a Thrax to place next must not turn every Gunner already down
    // into a Thrax. A body carrying no unit of its own does exactly that: the
    // server reads a blank one as "the aimed body's" — the right default for a
    // scenario written before a formation existed and the wrong one for a
    // formation you are building unit by unit.
    //
    // So the unit is STAMPED here, at the moment of placement, and nothing
    // afterwards moves it. The LEVEL deliberately is not: it is a dial for the
    // whole fight (a ruler pins one number for every body on the floor), so it
    // stays the scenario's and a body left blank keeps following it.
    s.formation.push({ id: nextFoeId(s), at: [p[0], p[1]], enemy: s.enemy });
    painted = [p[0], p[1]];
    changed();
  }
  function eraseAt(p) {
    const i = hitBody(p);
    // THE TARGET IS NOT ERASABLE. It is the body the fight is scored against
    // and `arenaBodies` reads it from `target_at` — deleting it would be
    // deleting the fight, which is what "one enemy" is for in the other
    // direction.
    if (i === null || i === 0) return;
    s.formation.splice(i - 1, 1);
    sel.clear();
    changed();
  }

  // ---- hit tests --------------------------------------------------------
  // HOW CLOSE COUNTS AS ON IT. A body is small on screen when you are zoomed
  // out, so the grab is given a few pixels of slop — but NEVER more than half
  // the closest two bodies can ever be (`CONTACT_M / 2`). Without that cap the
  // player's slop swallowed the enemy standing at contact, and dragging the
  // enemy silently dragged YOU: at 24 px per metre the slop was 0.42 m and the
  // two of them are 0.4 m apart.
  const grab = () => Math.min(CONTACT_M / 2, Math.max(BODY_R_M, 9 / view.k));
  function hitBody(p) {
    const r = grab();
    const bodies = arenaBodies(s);
    let best = null, bd = Infinity;
    for (let i = 0; i < bodies.length; i++) {
      const d = Math.hypot(bodies[i][0] - p[0], bodies[i][1] - p[1]);
      if (d <= r && d < bd) { bd = d; best = i; }
    }
    return best;
  }
  const hitYou = (p) => Math.hypot(s.player_at[0] - p[0], s.player_at[1] - p[1]) <= grab();
  // THE MARKER IS GRABBABLE ONLY ONCE IT IS A PLACE OF ITS OWN.
  //
  // Until you put it somewhere, aim RIDES THE TARGET — which means the marker
  // sits exactly on the body, and hit-testing it first made the target
  // impossible to drag: every grab took the aim instead. It is set by CLICKING
  // BARE FLOOR (see `end`), which is the gesture the "aim is a direction" model
  // is for and the one the SVG scene had; after that it is a handle like any
  // other.
  const hitAim = (p) => {
    if (!s.aim_at) return false;
    const a = s.aim_at;
    return Math.hypot(a[0] - p[0], a[1] - p[1]) <= grab();
  };

  // ---- sizing -----------------------------------------------------------
  const dpr = () => Math.min(window.devicePixelRatio || 1, 2);
  function resize() {
    const b = cv.getBoundingClientRect();
    if (!b.width || !b.height) return;          // on another tab: nothing to do
    const first = !W;
    W = b.width; H = b.height;
    cv.width = Math.round(W * dpr()); cv.height = Math.round(H * dpr());
    ctx.setTransform(dpr(), 0, 0, dpr(), 0, 0);
    if (first) fit();
    draw();
  }
  new ResizeObserver(resize).observe(cv);

  // ---- gestures ---------------------------------------------------------
  const cursor = () => {
    cv.className = "arc-cv arc-" + (space || tool === "hand" ? "hand" : tool)
      + (panning ? " arc-panning" : "") + (dragging ? " arc-moving" : "");
    // TOUCH-ACTION FOLLOWS THE MODE. `pan-y` keeps the page scrollable through
    // the scene; `none` hands every gesture here — a finger scrolls, it does
    // not drag the fight.
    cv.style.touchAction = arenaTouchDrag ? "none" : "pan-y";
  };

  rail.addEventListener("click", (e) => {
    const b = e.target.closest("[data-tool]");
    if (!b || b.disabled) return;
    tool = b.dataset.tool; paintRail(); cursor();
  });
  optbox.addEventListener("click", (e) => {
    const b = e.target.closest("[data-opt]");
    if (!b || b.disabled) return;
    if (b.dataset.opt === "snap") snapGrid = !snapGrid;
    else if (b.dataset.opt === "collide") collide = !collide;
    else if (b.dataset.opt === "fit") fit();
    paintRail(); draw();
  });
  chipbox.addEventListener("click", (e) => {
    const b = e.target.closest("button");
    if (!b) return;
    // THE MOVE MODE IS NOT AN EDIT to the fight, so it is answered before the
    // official-ruler guard: a ruler's scene refuses to MOVE, and offering a
    // dead toggle beside it would say the opposite.
    if (b.dataset.touchdrag) { arenaTouchDrag = !arenaTouchDrag; paintChips(); cursor(); return; }
    if (ro()) return;
    if (b.dataset.unaim) { s.aim_at = null; changed(); }
  });

  const pinchState = () => {
    const [a, b] = [...touches.values()];
    return { d: Math.hypot(a[0] - b[0], a[1] - b[1]),
             c: [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2] };
  };
  const local = (e) => {
    const b = cv.getBoundingClientRect();
    return [e.clientX - b.left, e.clientY - b.top];
  };

  cv.addEventListener("pointerdown", (e) => {
    const [lx, ly] = local(e);
    if (e.pointerType === "touch") {
      if (!arenaTouchDrag && touches.size === 0) return;   // the finger scrolls
      touches.set(e.pointerId, [lx, ly]);
      if (touches.size === 2) {
        if (mode === "paint" && painted) { s.formation.pop(); changed(); }
        mode = null; marquee = null; painted = null;
        const st = pinchState();
        pinch = { d: st.d, w: mt(st.c[0], st.c[1]) };
        return;
      }
    }
    cv.setPointerCapture(e.pointerId);
    const p = mt(lx, ly);
    last = [lx, ly];
    if (space || tool === "hand" || e.button === 1 || e.button === 2) {
      mode = "pan"; panning = true; cursor(); return;
    }
    if (ro()) return;                       // a ruler's fight is not editable
    if (tool === "place") { mode = "paint"; painted = null; placeAt(p); return; }
    if (tool === "erase") { mode = "erase"; eraseAt(p); return; }
    // …and with the aim tool the whole floor is the marker, which is the only
    // way to put an aim somewhere the first time.
    if (tool === "aim") { mode = "aim"; s.aim_at = snapTo(p); draw(); paintChips(); return; }
    // THE ORDER IS WHAT YOU REACH FOR FIRST: a placed aim marker, then an
    // ENEMY, then yourself. The enemy before the player, because at contact
    // they are one grab apart and the enemy is what a formation is made of.
    if (hitAim(p)) { mode = "aim"; return; }
    const i = hitBody(p);
    if (i === null && hitYou(p)) { mode = "you"; return; }
    if (i !== null) {
      if (e.shiftKey) (sel.has(i) ? sel.delete(i) : sel.add(i));
      else if (!sel.has(i)) { sel.clear(); sel.add(i); }
      mode = "move"; dragging = true; dragFrom = snapTo(p); cursor(); draw();
      return;
    }
    if (!e.shiftKey) sel.clear();
    mode = "marquee"; marquee = { a: [lx, ly], b: [lx, ly], base: new Set(sel) };
    draw();
  });

  cv.addEventListener("pointermove", (e) => {
    const [lx, ly] = local(e);
    if (e.pointerType === "touch" && touches.has(e.pointerId)) touches.set(e.pointerId, [lx, ly]);
    if (pinch && touches.size === 2) {
      const st = pinchState();
      view.k = Math.min(160, Math.max(1.6, view.k * (st.d / (pinch.d || 1))));
      const after = mt(st.c[0], st.c[1]);
      view.x += pinch.w[0] - after[0];
      view.y += pinch.w[1] - after[1];
      pinch.d = st.d; pinch.w = mt(st.c[0], st.c[1]);
      draw(); return;
    }
    if (!mode) return;
    const p = mt(lx, ly);
    if (mode === "pan") {
      view.x -= (lx - last[0]) / view.k;
      view.y += (ly - last[1]) / view.k;
      last = [lx, ly]; draw(); return;
    }
    if (mode === "paint") { placeAt(p); return; }
    if (mode === "erase") { eraseAt(p); return; }
    if (mode === "aim") { s.aim_at = snapTo(p); draw(); paintChips(); return; }
    if (mode === "you") {
      s.player_at = snapTo(p);
      s.target_at = keepApart(s.player_at, s.target_at);
      draw(); return;
    }
    if (mode === "move") {
      const to = snapTo(p);
      const dx = to[0] - dragFrom[0], dy = to[1] - dragFrom[1];
      if (!dx && !dy) return;
      // EVERY SELECTED BODY MOVES BY ONE DELTA, and each is settled on its own
      // so the block cannot be pushed through somebody standing outside it.
      for (const i of sel) {
        const b = bodyAt(i);
        if (!b) continue;
        const want = [b[0] + dx, b[1] + dy];
        const at = collide ? arenaSettle(s, want, i) : want;
        if (at === null) continue;
        if (i === 0) s.target_at = at; else s.formation[i - 1].at = at;
      }
      dragFrom = to; draw(); return;
    }
    if (mode === "marquee") {
      marquee.b = [lx, ly];
      const [ax, ay] = mt(marquee.a[0], marquee.a[1]);
      const [bx, by] = mt(marquee.b[0], marquee.b[1]);
      const lo = [Math.min(ax, bx), Math.min(ay, by)];
      const hi = [Math.max(ax, bx), Math.max(ay, by)];
      sel.clear(); marquee.base.forEach((i) => sel.add(i));
      arenaBodies(s).forEach((b, i) => {
        if (b[0] >= lo[0] && b[0] <= hi[0] && b[1] >= lo[1] && b[1] <= hi[1]) sel.add(i);
      });
      draw();
    }
  });

  const end = (e) => {
    if (e && e.pointerType === "touch") {
      touches.delete(e.pointerId);
      if (touches.size < 2) pinch = null;
      if (touches.size === 1) { mode = null; marquee = null; }
    }
    let wrote = mode && mode !== "pan" && mode !== "marquee";
    // A CLICK ON BARE FLOOR CLEARS THE SELECTION AND NOTHING ELSE. Aiming
    // there — on the reasoning that a body is dragged and a place has nothing
    // to grab — ignores that the aim marker is always on the floor and does
    // have something to grab, and a bare click that moves it means every
    // miss-click while selecting silently re-aims the
    // weapon. A fight that moved on a mis-click is a result that was for a
    // fight nobody was in.
    //
    // AIM IS DRAGGED, like everything else on this canvas. One rule for every
    // thing that has a position, and no gesture that edits the fight without
    // being asked to.
    if (mode === "marquee" && marquee) {
      const moved = Math.hypot(marquee.b[0] - marquee.a[0], marquee.b[1] - marquee.a[1]);
      if (moved < 4) { sel.clear(); }
      marquee = null;
    }
    mode = null; panning = false; dragging = false; painted = null;
    cursor();
    if (wrote) changed(); else draw();
  };
  cv.addEventListener("pointerup", end);
  cv.addEventListener("pointercancel", end);
  cv.addEventListener("contextmenu", (e) => e.preventDefault());

  cv.addEventListener("wheel", (e) => {
    e.preventDefault();
    const [lx, ly] = local(e);
    const before = mt(lx, ly);
    view.k = Math.min(160, Math.max(1.6, view.k * Math.exp(-e.deltaY * 0.0016)));
    const after = mt(lx, ly);
    view.x += before[0] - after[0];
    view.y += before[1] - after[1];
    draw();
  }, { passive: false });

  // KEYS ONLY WHILE THE SCENE HAS FOCUS, so typing a level into the box beside
  // it cannot delete the formation.
  wrap.tabIndex = 0;
  wrap.addEventListener("keydown", (e) => {
    if (e.code === "Space" && !space) { space = true; cursor(); e.preventDefault(); return; }
    const k = e.key.toLowerCase();
    if (k === "v" || k === "b" || k === "e" || k === "h") {
      if (ro() && k !== "h") return;
      tool = { v: "select", b: "place", e: "erase", h: "hand" }[k];
      paintRail(); cursor(); return;
    }
    if (ro()) return;
    if (k === "s") { snapGrid = !snapGrid; paintRail(); return; }
    if (k === "c") { collide = !collide; paintRail(); return; }
    if (k === "escape") { sel.clear(); draw(); return; }
    if (e.key === "Delete" || e.key === "Backspace") {
      const gone = [...sel].filter((i) => i > 0).sort((a, b) => b - a);
      if (!gone.length) return;
      gone.forEach((i) => s.formation.splice(i - 1, 1));
      sel.clear(); changed(); e.preventDefault(); return;
    }
    if (e.key.startsWith("Arrow") && sel.size) {
      const d = e.shiftKey ? 1 : 0.1;
      const dx = ((e.key === "ArrowRight") - (e.key === "ArrowLeft")) * d;
      const dy = ((e.key === "ArrowUp") - (e.key === "ArrowDown")) * d;
      for (const i of sel) {
        const b = bodyAt(i);
        if (!b) continue;
        const at = collide ? arenaSettle(s, [b[0] + dx, b[1] + dy], i) : [b[0] + dx, b[1] + dy];
        if (at === null) continue;
        if (i === 0) s.target_at = at; else s.formation[i - 1].at = at;
      }
      changed(); e.preventDefault();
    }
  });
  wrap.addEventListener("keyup", (e) => {
    if (e.code === "Space") { space = false; cursor(); }
  });

  // THE SCENE, ADDRESSABLE. A canvas has no per-body element, so anything that
  // needs to point at a body -- a check driving a drag, a caller re-framing the
  // view -- needs the same metres-to-pixels map the renderer uses. Exposing THAT
  // rather than a set of stand-in DOM nodes keeps one geometry: whatever it says
  // is where the body was drawn.
  host.__arena = {
    view,
    px, mt,
    fit: () => { fit(); draw(); },
    draw,
    tool: (id) => { tool = id; paintRail(); cursor(); },
    get sel() { return sel; },
    get snap() { return snapGrid; },
    get collide() { return collide; },
  };
  // READ-ONLY SAYS SO ON THE HOST, the same class the SVG scene set — it is
  // what tells a reader (and a check) that this copy is a picture rather than
  // an editor, and the optimizer's copy has always carried it.
  host.classList.toggle("ar-ro", !!opts.readonly);
  paintRail(); paintChips(); cursor(); resize();
  // THE HOST MAY BE ON ANOTHER TAB at mount, where the box is zero and there is
  // nothing to size to. The observer catches it the moment it is shown.
}

function mountArena(host, s, en, opts) {
  if (!host) return;
  // THE EDITOR IS A CANVAS as of 2026-08-18; the ANALYSIS mount is still the
  // SVG scene. Setting up a fight and reading one are two things, and only
  // one of them is an editor — the result panel's copy draws a fight that has
  // already been run, picks rather than drags, and shades by damage. Staged
  // deliberately: one renderer moves at a time, and the half a RESULT depends
  // on moves second.
  if (!opts.heat) return mountArenaCanvas(host, s, en, opts);
  // QUICK SETS, in the canvas. The scene is the one place a position is set, so the shortcuts live in it rather than in a second
  // control below that would be a second source of truth for the same fact.
  const dis = opts.readonly ? " disabled" : "";
  const chips = () => {
    const n = 1 + (s.formation || []).length;
    const jumps = ARENA_JUMPS.map((m) => {
      const on = Math.abs(arenaDistance(s) - m) < 0.05;
      const label = m === 0 ? tr("contact") : `${m} m`;
      return `<button class="ar-jump${on ? " on" : ""}" data-jump="${m}"${dis}>${escHtml(label)}</button>`;
    }).join("");
    // THE FORMATION'S OWN ROW. Separate from the distance shortcuts because
    // they answer different questions — one is where the target stands, the
    // other is how many bodies are on the floor.
    const full = n >= ARENA_MAX_BODIES();
    const crowd = `<button class="ar-jump" data-add="1"${dis || (full ? " disabled" : "")}>+1</button>`
      + `<button class="ar-jump" data-add="8"${dis || (full ? " disabled" : "")}>+8</button>`
      // DRAG-ON-TOUCH, off by default — see `arenaTouchDrag`. Drawn wherever a
      // finger CAN be the pointer, because on a mouse there is nothing to
      // choose. `maxTouchPoints` rather than a `pointer: coarse` query: a
      // touchscreen laptop reports a FINE pointer and still has the problem.
      + (navigator.maxTouchPoints > 0
        ? `<button class="ar-jump${arenaTouchDrag ? " on" : ""}" data-touchdrag="1"${dis}
           title="${escHtml(tr("while this is on, dragging a body moves it instead of scrolling the page"))}"
           >✥ ${escHtml(tr("move"))}</button>`
        : "")
      + `<button class="ar-jump" data-clear="1"${dis || (n < 2 ? " disabled" : "")}>${escHtml(tr("one enemy"))}</button>`
      + `<span class="ar-count">${n}${full ? " / " + ARENA_MAX_BODIES() : ""}</span>`
      + (s.aim_at
        ? `<button class="ar-jump" data-unaim="1"${dis}>${escHtml(tr("aim at the target"))}</button>`
        : "");
    return `<div class="ar-jumps">${jumps}</div><div class="ar-jumps ar-crowd">${crowd}</div>`;
  };
  // AN ANALYSIS MOUNT IS NOT AN EDITOR. `opts.heat` says this copy is the
  // RESULT's, so it draws the scene and nothing else — no distance shortcuts,
  // no +1/+8, no drag. Setting up a fight and reading one are two things and
  // the controls of one have no business in the other.
  const analysis = !!opts.heat;
  const paint = () => {
    host.innerHTML = arenaSvg(s, en, opts.heat, opts.selected)
      + (analysis ? "" : chips());
    // TOUCH-ACTION FOLLOWS THE MODE, because it is what the browser reads to
    // decide whether a gesture on this element is a scroll. `pan-y` keeps the
    // page scrollable through the scene; `none` hands every gesture here.
    const svg = host.querySelector(".ar-svg");
    if (svg) svg.style.touchAction = analysis || !arenaTouchDrag ? "pan-y" : "none";
    // THE SCENE, ADDRESSABLE — the same contract the canvas mount publishes on
    // `host.__arena`, so anything that needs to point AT a body reads the map
    // the renderer used rather than guessing from a DOM box. This one answers
    // in the SVG's viewBox, which is what `arenaSvg` draws in; a caller that
    // wants pixels converts through the svg's own client rect.
    host.__arena = {
      vb: arenaGeom(ARENA_VW, ARENA_VH, s.player_at, ...arenaBodies(s), arenaAim(s)).px,
      vw: ARENA_VW,
      vh: ARENA_VH,
    };
  };
  paint();
  if (opts.readonly) {
    host.classList.add("ar-ro");
    // AN ANALYSIS MOUNT IS READ-ONLY AND STILL CLICKABLE: it PICKS, it never
    // moves. Bound here rather than below because everything below belongs to
    // the EDITOR — the drag, the quick sets, the aim marker — and none of that
    // has any business on a picture of a fight that has already been run
    // Setting up a fight and reading one are two things.
    if (opts.onPick) {
      host.addEventListener("pointerdown", (e) => {
        const el = e.target.closest && e.target.closest("[data-drag]");
        const w = el && el.dataset.drag;
        if (w && w.startsWith("foe:")) opts.onPick(Number(w.slice(4)));
      });
    }
    return;
  }
  // DELEGATED, because `paint` replaces the markup on every move: listeners
  // bound to the circles die with the first repaint, which left the scene
  // draggable exactly once.
  host.addEventListener("click", (e) => {
    const b = e.target.closest && e.target.closest("button");
    if (!b) {
      // POINT AT A PLACE. Clicking bare floor aims there, which is the gesture
      // the whole "aim is a direction" model is for — a
      // body is dragged, but a PLACE has nothing to grab, so it is clicked.
      // Bodies and the marker itself are dragged instead, so they are skipped.
      const svg = e.target.closest && e.target.closest(".ar-svg");
      if (!svg || (e.target.closest && e.target.closest("[data-drag]"))) return;
      if (opts.readonly || officialScenarioActive()) return;
      const box = svg.getBoundingClientRect();
      if (!box.width || !box.height) return;
      const g = arenaGeom(ARENA_VW, ARENA_VH, s.player_at, ...arenaBodies(s), arenaAim(s));
      s.aim_at = g.m((e.clientX - box.left) * (ARENA_VW / box.width),
                     (e.clientY - box.top) * (ARENA_VH / box.height));
      paint();
      markScenarioDirty();
      if (opts.after) opts.after();
      return;
    }
    // THE TOUCH-DRAG MODE IS NOT AN EDIT to the fight, so it is answered before
    // the official-ruler guard: a ruler's scene refuses to MOVE, and offering a
    // dead toggle beside it would say the opposite.
    if (b.dataset.touchdrag) {
      arenaTouchDrag = !arenaTouchDrag;
      paint();
      return;
    }
    if (opts.readonly || officialScenarioActive()) return;
    if (b.dataset.jump !== undefined) setArenaDistance(s, Number(b.dataset.jump));
    else if (b.dataset.add) {
      for (let i = 0; i < Number(b.dataset.add); i++) if (!arenaAddFoe(s)) break;
    } else if (b.dataset.clear) {
      // BACK TO ONE BODY, which is the fight every golden value and both
      // boards are measured under — so it is one click away and never
      // something you have to drag your way back to.
      s.formation = [];
      s.aim_at = null;
    } else if (b.dataset.unaim) s.aim_at = null;
    else return;
    paint();
    markScenarioDirty();
    if (opts.after) opts.after();
  });
  host.addEventListener("pointerdown", (e) => {
    const el = e.target.closest && e.target.closest("[data-drag]");
    if (!el) return;
    // AN OFFICIAL RULER'S FIGHT IS NOT DRAGGABLE. The
    // benchmark pins its distance — both boards are scored at CONTACT — so a
    // drag there would silently move the fight off the standard while the bar
    // still said which ruler you were on.
    //
    // CHECKED AT THE GESTURE rather than baked in at mount: `lockOfficialScenario`
    // disables `input,select,button,textarea`, and the bodies here are SVG
    // circles, which that sweep does not reach. Asking live also means
    // switching scenarios needs no re-render to take effect.
    if (opts.readonly || officialScenarioActive()) return;
    // A FINGER SCROLLS UNLESS TOLD OTHERWISE. Returning here leaves the gesture
    // with the browser, which is the only way the page still scrolls.
    if (e.pointerType === "touch" && !arenaTouchDrag) return;
    e.preventDefault();
    const which = el.dataset.drag;
    const box = host.querySelector(".ar-svg").getBoundingClientRect();
    if (!box.width || !box.height) return;   // not on screen: nothing to drag
    const g = arenaGeom(ARENA_VW, ARENA_VH, s.player_at, ...arenaBodies(s), arenaAim(s));
    // CLIENT PIXELS -> the viewBox's own units, which is the one conversion
    // the fixed coordinate space costs and the reason it is worth it.
    const kx = ARENA_VW / box.width, ky = ARENA_VH / box.height;
    const move = (ev) => {
      const at = g.m((ev.clientX - box.left) * kx, (ev.clientY - box.top) * ky);
      if (which === "player_at") {
        s.player_at = at;
        s.target_at = keepApart(at, s.target_at);
      } else if (which === "aim") {
        // DRAGGING THE MARKER MAKES AIM A PLACE OF ITS OWN. Until you do, it
        // rides the target — which is what every scenario written before a
        // formation existed means, and what keeps this a strictly additive
        // feature.
        s.aim_at = at;
      } else if (which.startsWith("foe:")) {
        const i = Number(which.slice(4));
        // `null` = nowhere legal to go, so the body stays put. The gesture is
        // not cancelled — keep moving the finger and it follows again the
        // moment there is room.
        const settled = arenaSettle(s, at, i);
        if (settled === null) return;
        if (i === 0) s.target_at = settled;
        else if (s.formation[i - 1]) s.formation[i - 1].at = settled;
      }
      paint();
    };
    const up = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      markScenarioDirty();
      if (opts.after) opts.after();
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  });
}


/// THE FIGHT — and there is exactly ONE, for every module that simulates.
///
/// `parse_fight` is the server's half of this rule; this is the page's. Five
/// spellings of "the fight" is five chances to measure something the simulator
/// never runs, because a fight keeps GAINING fields and each new one reaches
/// whichever spellings somebody remembered.
///
/// THE LIVE `sim` IS THE FIGHT, not the preset behind it: a scenario preset is
/// a SAVED COPY that `applyScenario` seeds `sim` from and the auto-save writes
/// back, so reading it over the top can only hand back something staler.
///
/// THE BUFF MAP TRAVELS WHOLE, because buff settings are the FIGHT's and it is
/// the BUILD that decides which have a source (the server's `BuffCfg` is a
/// lookup, so an entry nothing grants is never read). Filtering to `buffList`
/// makes the quick calc a different fight the moment a candidate grants a buff
/// the current build lacks — which is every candidate worth ranking.
///
/// `over` is what a CALLER owns rather than the fight — `replay`, a seed, and
/// the quick calc's RUN COUNT, a reader's precision rather than an edit. It
/// lands LAST, which is the whole of that decoupling.
function theFight(over) {
  return { ...sim, runs: simRuns(), custom_enemies: customEnemiesFor(sim.enemy),
    buffs: sim.buffs || {}, ...(over || {}) };
}

function renderEnemies() {
  if (!META || !$("enemy-block")) return;
  const ps = loadPresetList(ENEMIES);
  const open = ps.find((p) => p.name === activeEnemyName());
  $("enemy-sub").textContent = ps.length
    ? `${ps.length} ${tr("saved")}`
    : tr("none yet — a target you build here appears in every scenario's target list");
  renderEnemyTools();
  if (!open) {
    // LIST MODE — nothing is being edited, so nothing pretends to be.
    enemyDoc = null;
    if ($("enemy-form")) $("enemy-form").innerHTML = "";
    renderEnemyAll();
    return;
  }
  if (!enemyDoc) enemyDoc = JSON.parse(JSON.stringify({ ...blankEnemy(), ...(open.state || {}) }));
  renderEnemyForm();
  renderEnemyAll();
}

function saveEnemyDoc() {
  const ps = loadPresetList(ENEMIES);
  const i = ps.findIndex((p) => p.name === activeEnemyName());
  if (i < 0) return;
  ps[i] = { ...ps[i], savedAt: Date.now(), state: snapshotEnemy() };
  storePresetList(ENEMIES, ps);
  // The SCENARIO may be pointing at this target right now, and its card shows
  // the numbers being edited. Redraw it rather than leaving a stale target on
  // a tab the editor cannot see.
  renderSimTargetIfAny();
}

function renderSimTargetIfAny() {
  if (typeof renderEnemy === "function") renderEnemy();
  if (typeof renderOptEnemy === "function") renderOptEnemy();
}

function renderEnemyAll() {
  const box = $("enemy-all");
  if (!box) return;
  const ps = loadPresetList(ENEMIES);
  box.innerHTML = ps.length
    ? ps.map((p) => {
        const s = { ...blankEnemy(), ...(p.state || {}) };
        const parts = s.body_parts.map((b) => `${escHtml(b.name)} ×${b.multiplier}`).join(", ");
        return `<div class="en-row" data-en="${escHtml(p.name)}">
          <span class="nm">${escHtml(p.name)}</span>
          <span class="sm">${escHtml(s.faction || "unknown")} · ${s.stats.health} HP · ${s.stats.armor} ${escHtml(tr("Armor"))} · ${s.stats.shield} ${escHtml(tr("Shield"))}</span>
          <span class="sm">${parts}</span>
          ${enemyId(p.name) === sim.enemy ? `<span class="sm">✓ ${escHtml(tr("in the current fight"))}</span>` : ""}
        </div>`;
      }).join("")
    : `<div class="placeholder">${escHtml(tr("no targets yet"))}</div>`;
  box.querySelectorAll(".en-row").forEach((el) =>
    el.addEventListener("click", () => {
      activeEnemy = el.dataset.en;
      localStorage.setItem(presetActiveKey(ENEMIES), activeEnemy);
      enemyDoc = null;
      renderEnemies();
    })
  );
}

function renderEnemyTools() {
  const box = $("enemy-tools");
  if (!box) return;
  const ps = loadPresetList(ENEMIES);
  const cur = ps.find((x) => x.name === activeEnemyName());
  if (!cur) {
    box.innerHTML =
      `<button class="cu-btn cu-new">+ ${escHtml(tr("new target"))}</button>` +
      `<span class="cu-ops">${undoButtons(ENEMIES)}</span>`;
  } else {
    box.innerHTML =
      `<button class="cu-btn cu-back">← ${escHtml(tr("all targets"))}</button>` +
      `<span class="cu-open"><b>${escHtml(cur.name)}</b></span>` +
      `<span class="cu-ops">` +
      `<button class="cu-btn cu-dup" title="${escHtml(tr("duplicate"))}">⧉</button>` +
      `<button class="cu-btn cu-ren" title="${escHtml(tr("rename"))}">✎</button>` +
      `<button class="cu-btn cu-del" title="${escHtml(tr("delete"))}">✕</button>` +
      undoButtons(ENEMIES) +
      `</span>`;
  }
  wireUndoButtons(box, ENEMIES);
  const q = (s) => box.querySelector(s);
  const openIt = (name) => {
    activeEnemy = name;
    if (name) localStorage.setItem(presetActiveKey(ENEMIES), name);
    else localStorage.removeItem(presetActiveKey(ENEMIES));
    enemyDoc = null;
    renderEnemies();
  };
  const click = (sel, fn) => { const b = q(sel); if (b) b.onclick = (e) => { e.stopPropagation(); fn(); }; };

  click(".cu-new", () => {
    const ps2 = loadPresetList(ENEMIES);
    const name = freeName(ps2, (n) => "target " + n);
    ps2.push({ name, savedAt: Date.now(), state: blankEnemy() });
    storePresetList(ENEMIES, ps2);
    openIt(name);
  });
  click(".cu-back", () => openIt(null));
  click(".cu-dup", () => {
    const ps2 = loadPresetList(ENEMIES);
    const name = freeName(ps2, (n) => `${cur.name} (${n})`);
    ps2.push({ name, savedAt: Date.now(), state: JSON.parse(JSON.stringify(cur.state)) });
    storePresetList(ENEMIES, ps2);
    openIt(name);
  });
  click(".cu-del", () => {
    const ps2 = loadPresetList(ENEMIES).filter((x) => x.name !== cur.name);
    storePresetList(ENEMIES, ps2);
    // DELETING A CUSTOM BREAKS REFERENCES, and this is the one it can break:
    // the fight may be pointing at it. It falls back to the roster's first unit
    // rather than to an id nothing answers to.
    if (sim.enemy === enemyId(cur.name)) {
      sim.enemy = ((META.enemies || [])[0] || {}).id || "thrax_centurion";
      markPresetDirty();
      renderSimTargetIfAny();
    }
    openIt(null);
  });
  click(".cu-ren", () => {
    // NO NATIVE DIALOGS (AGENTS.md): an inline input, as everywhere else.
    const span = q(".cu-open");
    span.innerHTML = `<input class="cu-rename" type="text" value="${escHtml(cur.name)}">`;
    const inp = span.querySelector("input");
    inp.focus(); inp.select();
    let done = false;
    const commit = () => {
      if (done) return;
      done = true;
      const name = inp.value.trim();
      const ps2 = loadPresetList(ENEMIES);
      if (!name || name === cur.name || ps2.some((x) => x.name === name)) return renderEnemyTools();
      const i = ps2.findIndex((x) => x.name === cur.name);
      ps2[i] = { ...ps2[i], name };
      storePresetList(ENEMIES, ps2);
      // The id IS the name, so a rename moves whatever names it — otherwise the
      // fight would point at a target that no longer exists.
      if (sim.enemy === enemyId(cur.name)) { sim.enemy = enemyId(name); markPresetDirty(); }
      openIt(name);
      renderSimTargetIfAny();
    };
    inp.onkeydown = (e) => { if (e.key === "Enter") commit(); if (e.key === "Escape") { done = true; renderEnemyTools(); } };
    inp.onblur = commit;
  });
}

function renderEnemyForm() {
  const box = $("enemy-form");
  if (!box) return;
  const d = enemyDoc;
  const cols = Object.fromEntries((META.factions || []).map((f) => [f.id, f.modifiers]));
  const factionCol = Object.fromEntries((cols[d.faction] || []).map((m) => [m.type, m.mult]));
  const own = d.damage_modifiers;
  const num = (k, label, val, step) =>
    `<label>${escHtml(label)}<input type="number" data-en-k="${k}" value="${val}" step="${step || 1}" min="0"></label>`;
  const opts = (list, cur) => list.map((x) =>
    `<option value="${escHtml(x)}"${x === cur ? " selected" : ""}>${escHtml(x)}</option>`).join("");
  box.innerHTML =
    `<div class="en-grid">
      <label>${escHtml(tr("Faction"))}
        <select data-en-k="faction">${opts(["unknown"].concat((META.factions || []).map((f) => f.id)), d.faction || "unknown")}</select></label>
      <label>${escHtml(tr("Level scaling"))}
        <select data-en-k="scaling_faction">${opts(SCALING_FACTIONS, d.scaling_faction)}</select></label>
      ${num("stats.base_level", tr("Base level"), d.stats.base_level)}
      ${num("stats.health", tr("Health"), d.stats.health)}
      ${num("stats.shield", tr("Shield"), d.stats.shield)}
      ${num("stats.armor", tr("Armor"), d.stats.armor)}
      ${num("stats.overguard", tr("Overguard"), d.stats.overguard)}
      <label>${escHtml(tr("Eximus possible"))}
        <input type="checkbox" data-en-k="can_be_eximus"${d.can_be_eximus ? " checked" : ""}></label>
    </div>` +
    // THE VULNERABILITY COLUMN, and the two states it has. A FACTION ALREADY
    // ANSWERS THIS — that is what a faction is to incoming damage — so writing
    // your own is a deliberate second state rather than a set of blanks to
    // fill. IMMUNITY IS 0 HERE, not a checkbox of its own: the game has no
    // third state between a multiplier and nothing getting through.
    `<div class="en-sect"><b>${escHtml(tr("Damage taken"))}</b>
      <label><input type="checkbox" id="en-own-col"${own ? " checked" : ""}> ${
        escHtml(tr("write my own column (0 = takes none of that type)"))}</label>
      ${own ? "" : `<span>${escHtml(tr("from the faction"))}: ${
        (cols[d.faction] || []).map((m) => `${escHtml(DT(m.type))} ×${m.mult}`).join(", ")
        || escHtml(tr("takes every type as written"))}</span>`}
    </div>` +
    (own
      ? `<div class="en-mods">${DAMAGE_TYPES.map((k) =>
          `<label>${escHtml(DT(k))}<input type="number" data-en-dm="${k}" step="0.1" min="0"
             value="${own[k] === undefined ? (factionCol[k] === undefined ? 1 : factionCol[k]) : own[k]}"></label>`).join("")}</div>`
      : "") +
    // STATUS IMMUNITY, and it is a SECTION OF ITS OWN rather than a 0 in the
    // column above, because it is a different mechanic and the difference is
    // not a detail. Taking no DAMAGE of a type does not
    // stop that type from being drawn for procs; a status immunity removes it
    // from the draw and the remaining types RENORMALIZE — the wiki's own worked
    // example moves the other four from 18/5/9/23% to 33/8/17/42% when
    // Corrosive leaves. So an enemy can be immune to one and not the other, and
    // the page has to let a player say which.
    `<div class="en-sect"><b>${escHtml(tr("Status immunity"))}</b>
      <span>${escHtml(tr("these procs cannot land — the other types take over their share of the roll"))}</span></div>
     <div class="en-mods">${DAMAGE_TYPES.map((k) =>
       `<label><input type="checkbox" data-en-si="${k}"${
         (d.status_immunities || []).includes(k) ? " checked" : ""}> ${escHtml(DT(k))}</label>`).join("")}</div>` +
    // BODY PARTS — the weak points, and what each one is worth. A head is not a
    // NAME: `is_head` is what a headshot-conditional mod asks about, and
    // `crit_bonus` is the separate question of whether the part also multiplies
    // critical damage.
    `<div class="en-sect"><b>${escHtml(tr("Body parts"))}</b>
      <button class="cu-btn" id="en-add-part">+ ${escHtml(tr("part"))}</button></div>
     <div class="en-parts">${d.body_parts.map((b, i) => `
      <div class="en-part" data-i="${i}">
        <input type="text" data-en-p="name" value="${escHtml(b.name)}">
        <input type="number" data-en-p="multiplier" value="${b.multiplier}" step="0.1" min="0">
        <label><input type="checkbox" data-en-p="is_head"${b.is_head ? " checked" : ""}> ${escHtml(tr("head"))}</label>
        <label><input type="checkbox" data-en-p="crit_bonus"${b.crit_bonus ? " checked" : ""}> ${escHtml(tr("crit bonus"))}</label>
        ${d.body_parts.length > 1 ? `<button class="cu-btn en-del-part">✕</button>` : ""}
      </div>`).join("")}</div>`;

  const commit = () => { saveEnemyDoc(); renderEnemyForm(); renderEnemyAll(); };
  const setPath = (path, val) => {
    const [a, b] = path.split(".");
    if (b) d[a][b] = val; else d[a] = val;
  };
  box.querySelectorAll("[data-en-k]").forEach((el) => {
    el.onchange = () => {
      setPath(el.dataset.enK, el.type === "checkbox" ? el.checked
        : el.type === "number" ? Math.max(0, Number(el.value) || 0)
        : el.value);
      commit();
    };
  });
  const oc = $("en-own-col");
  if (oc) oc.onchange = () => {
    // Switching ON copies the faction's column in, so the starting point is
    // what this target already was rather than fifteen ones.
    d.damage_modifiers = oc.checked
      ? Object.fromEntries(DAMAGE_TYPES.map((k) => [k, factionCol[k] === undefined ? 1 : factionCol[k]]))
      : null;
    commit();
  };
  box.querySelectorAll("[data-en-si]").forEach((el) => {
    el.onchange = () => {
      const k = el.dataset.enSi;
      const cur = new Set(d.status_immunities || []);
      if (el.checked) cur.add(k); else cur.delete(k);
      d.status_immunities = DAMAGE_TYPES.filter((x) => cur.has(x));
      commit();
    };
  });
  box.querySelectorAll("[data-en-dm]").forEach((el) => {
    el.onchange = () => {
      d.damage_modifiers = { ...(d.damage_modifiers || {}), [el.dataset.enDm]: Math.max(0, Number(el.value) || 0) };
      commit();
    };
  });
  box.querySelectorAll(".en-part").forEach((row) => {
    const i = Number(row.dataset.i);
    row.querySelectorAll("[data-en-p]").forEach((el) => {
      el.onchange = () => {
        const k = el.dataset.enP;
        d.body_parts[i][k] = el.type === "checkbox" ? el.checked
          : k === "name" ? (el.value.trim() || "part")
          : Math.max(0, Number(el.value) || 0);
        commit();
      };
    });
    const del = row.querySelector(".en-del-part");
    if (del) del.onclick = () => { d.body_parts.splice(i, 1); commit(); };
  });
  const add = $("en-add-part");
  if (add) add.onclick = () => {
    d.body_parts.push({ name: "part", multiplier: 1, is_head: false, crit_bonus: false });
    commit();
  };
}

function renderRivenTools() {
  const box = $("riven-tools");
  if (!box) return;
  const ps = loadPresetList(RIVENS);
  const open = activeRivenId();
  const cur = ps.find((x) => x.id === open);
  const impAvailable = presetSources(RIVENS, presetWeapon()).length > 0;
  const impBtn = impAvailable
    ? `<button class="cu-btn cu-imp" title="${escHtml(tr("copy a riven from another weapon"))}">⇤ ${escHtml(tr("import"))}</button>`
    : "";
  if (!cur) {
    box.innerHTML =
      `<button class="cu-btn cu-new">+ ${escHtml(tr("new riven"))}</button>${impBtn}` +
      `<span class="cu-ops">${undoButtons(RIVENS)}</span>` +
      `<div class="cu-import" hidden></div>`;
  } else {
    const official = (rivenNames[cur.id] || {}).name || "";
    box.innerHTML =
      `<button class="cu-btn cu-back">← ${escHtml(tr("all rivens"))}</button>` +
      `<span class="cu-open"><b>${escHtml(cur.name)}</b>${
        official ? `<span class="rv-official">${escHtml(official)}</span>` : ""}</span>` +
      `<span class="cu-ops">` +
      `<button class="cu-btn cu-dup" title="${escHtml(tr("duplicate"))}">⧉</button>` +
      `<button class="cu-btn cu-ren" title="${escHtml(tr("rename"))}">✎</button>` +
      `<button class="cu-btn cu-del" title="${escHtml(tr("delete"))}">✕</button>` +
      undoButtons(RIVENS) +
      `</span><div class="cu-import" hidden></div>`;
  }
  wireUndoButtons(box, RIVENS);
  const q = (s) => box.querySelector(s);
  const openIt = (id) => {
    activeRiven = id;
    if (id) localStorage.setItem(presetActiveKey(RIVENS), id);
    else localStorage.removeItem(presetActiveKey(RIVENS));
    riven = null;
    renderRivens();
  };
  const click = (sel, fn) => { const b = q(sel); if (b) b.onclick = (e) => { e.stopPropagation(); fn(); }; };

  click(".cu-new", () => {
    const ps2 = loadPresetList(RIVENS);
    const name = freeName(ps2, (n) => "riven " + n);
    const id = newRivenId(loadPresetWhole(RIVENS));
    riven = { ...withDrafts(blankRiven()), __weapon: $("weapon").value };
    ps2.push({ id, name, savedAt: Date.now(), state: snapshotRiven() });
    storePresetList(RIVENS, ps2);
    openIt(id);
    // THE LIST SHOWS NUMBERS, and they are the engine's — so a card that has
    // just appeared has to ask for them. Without this the row is blank until
    // something else happens to refresh it, which is what dragging a value was
    // secretly doing.
    refreshRivenNames();
  });
  click(".cu-back", () => openIt(""));
  click(".cu-dup", () => {
    const ps2 = loadPresetList(RIVENS);
    const from = ps2.find((x) => x.id === open) || {};
    const name = freeName(ps2, (n) => (from.name || "riven") + " copy" + (n > 1 ? " " + n : ""));
    const id = newRivenId(loadPresetWhole(RIVENS));
    ps2.push({ id, name, savedAt: Date.now(), state: snapshotRiven() });
    // THE COPY IS WORTH WHAT THE ORIGINAL IS, so the list can say so at once.
    // Its printed values come from `/api/riven`, which is a round trip away —
    // and a copy of an identical spec cannot answer differently, so seeding it
    // is not an optimistic guess, it is the same answer.
    if (rivenNames[open]) rivenNames[id] = rivenNames[open];
    storePresetList(RIVENS, ps2);
    openIt(id);
    refreshRivenNames();
  });
  click(".cu-del", () => {
    storePresetList(RIVENS, loadPresetList(RIVENS).filter((x) => x.id !== open));
    // …AND EVERY SAVED BUILD IN THE FAMILY LETS IT GO. `pruneDanglingRivens`
    // below clears the LIVE build; these are the ones nobody has open, which
    // would otherwise come back holding an id nothing resolves.
    repointRivenInBuilds(rivenKinWeapons(), open, null);
    // Back to the LIST, not to another riven: deleting the thing you had open
    // is not a request to open a different one.
    openIt("");
    pruneDanglingRivens();
  });
  // Renaming happens in an INLINE input — no prompt(), which the owner's
  // browser blocks. Enter commits, Esc cancels.
  click(".cu-ren", () => {
    const host = q(".cu-open");
    host.innerHTML = `<input class="cu-name" type="text" maxlength="24" value="${
      escHtml((loadPresetList(RIVENS).find((x) => x.id === open) || {}).name || "")}">`;
    const inp = q(".cu-name");
    inp.focus(); inp.select();
    let done = false;
    const commit = (ok) => {
      if (done) return;
      done = true;
      const want = (inp.value || "").trim();
      const ps2 = loadPresetList(RIVENS);
      const at = ps2.findIndex((x) => x.id === open);
      if (!ok || !want || at < 0 || want === ps2[at].name) return renderRivenTools();
      // A LABEL EDIT AND NOTHING ELSE. A build points at the card's id, so
      // nothing has to be chased and two cards may carry one name — which they
      // may genuinely deserve to, and which is not the app's business.
      ps2[at] = { ...ps2[at], name: want };
      storePresetList(RIVENS, ps2);
      openIt(open);
      renderMods(); refreshPanel();
    };
    inp.onkeydown = (ev) => {
      if (ev.key === "Enter") commit(true);
      if (ev.key === "Escape") commit(false);
    };
    inp.onblur = () => commit(true);
  });
  click(".cu-imp", () => {
    const panel = q(".cu-import");
    if (!panel.hidden) { panel.hidden = true; return; }
    panel.innerHTML = presetSources(RIVENS, presetWeapon()).map((w) =>
      `<div class="pimp-w"><span class="pimp-wn">${escHtml(w.name)}</span>` +
      w.presets.map((x) =>
        `<span class="cu-btn pimp-p" data-weapon="${escHtml(w.id)}" data-name="${escHtml(x.name)}">${escHtml(x.name)}</span>`
      ).join("") + `</div>`).join("");
    panel.hidden = false;
    panel.querySelectorAll(".pimp-p").forEach((el) => el.onclick = (ev) => {
      ev.stopPropagation();
      const from = loadPresetList(RIVENS, el.dataset.weapon).find((x) => x.name === el.dataset.name);
      if (!from) return;
      const ps2 = loadPresetList(RIVENS);
      const name = freeName(ps2, (n) => el.dataset.name + (n > 1 ? " " + n : ""));
      const id = newRivenId(loadPresetWhole(RIVENS));
      // A riven's VALUES are its weapon's disposition applied to a roll, so
      // the copy is the roll — the numbers re-derive here, which is the whole
      // reason importing one is useful.
      riven = { ...withDrafts(from.state), __weapon: $("weapon").value };
      ps2.push({ id, name, savedAt: Date.now(), state: snapshotRiven() });
      storePresetList(RIVENS, ps2);
      openIt(id);
      // AN IMPORT CANNOT BE SEEDED the way a copy is: the same roll against a
      // different disposition is a different number, which is the whole reason
      // importing one is useful.
      refreshRivenNames();
    });
  });
}

// ---- SHARING — a link that reproduces the whole thing ------------------
//
// The principle: everything travels, and nothing has to be
// set up by hand on arrival. Most build links elsewhere carry the mods and
// leave you to re-enter the enemy, the buffs, the riven — so the number the
// sharer quoted is one you cannot reproduce. Here the payload is the build,
// the rivens it equips, the fight it was measured in, and the measurement
// itself, and opening it creates a fresh copy of each. Nothing is overwritten.
//
// It rides the QUERY, not the fragment: a fragment never reaches a
// crawler, and the link is meant to be posted, previewed and looked at.
//
// Encoding: JSON -> deflate-raw -> base64url, behind a one-character version
// so the reader knows what it is holding. A full share — build + riven +
// scenario + result — is ~600 characters, which no chat app will break. IDs
// travel as their own stable English slugs rather than as indices into a
// table: the table would have to be append-only forever, and one reordering
// would silently reinterpret every link ever posted.
const SHARE_PARAM = "b";
/// THE KILL SWITCH FOR SHARING, and it is worth keeping rather than deleting:
/// with it false an incoming `?b=` is dropped, the query is stripped, and the
/// visitor lands on the weapon's own page with a line saying why — the worst
/// case a posted link should ever reach.
///
/// It has been used once, for a shared link opening blank that could not be
/// reproduced here, and an unreproducible failure in the one feature whose job
/// is to be pasted somewhere public is not one to leave running. Both halves of
/// that are now covered: `SHARE_AXES` exists so an axis cannot go missing from
/// the tuple without a check going red, and the boot GUARD in the document head
/// plus the footer's BUILD STAMP make a repeat report answerable — without the
/// stamp, "still broken" and "still holding the old file" are the same
/// sentence.
const SHARE_ENABLED = true;
const SHARE_V_DEFLATE = "1";
const SHARE_V_PLAIN = "0";
/// **v3: THE IDS TRAVEL AS INDICES, AND THE PAYLOAD IS PLAIN TEXT**.
///
/// Spelling the ids out and then deflating them costs ~280 characters for a
/// build: the payload is mostly identifiers, and deflate cannot know the ones
/// the payload does NOT contain. The same Laetum is 76 characters
/// as indices — and at that length deflate makes it BIGGER (its own header
/// outweighs what it finds), so v3 goes into the URL as it is.
///
/// EVERY SEPARATOR IS URL-SAFE, which is what lets the text travel raw: `~`,
/// `-`, `.` and `_` are unreserved in RFC 3986 and `:`, `;`, `,` and `!` are
/// sub-delims a query accepts without escaping. Anything that is not — a riven
/// somebody named in Chinese — falls back to the deflate+base64 path, which is
/// still there and still reads every link ever posted.
const SHARE_V_TEXT = "3";
/// The frozen order both ends index into, from `/api/meta`'s `si` per entity.
/// Built once, from what is already travelling — the manifest itself never
/// crosses the wire.
let shareIx = null;
function shareIndex() {
  if (shareIx) return shareIx;
  const to = new Map();
  const from = new Map();
  const take = (x) => {
    if (!x || x.si == null) return;
    to.set(x.id, x.si);
    from.set(x.si, x.id);
  };
  (META.weapons || []).forEach((w) => {
    take(w);
    (w.evolutions || []).forEach((t) => (t.options || []).forEach(take));
  });
  // MODS ARRIVE BY POOL, not as one list — `mod_pools` is a map of pool name to
  // its mods, and a mod in two pools is the same object twice, which `take`
  // absorbs.
  Object.values(META.mod_pools || {}).forEach((list) => (list || []).forEach(take));
  (META.arcanes || []).forEach(take);
  Object.values(META.riven_stats || {}).forEach((list) => (list || []).forEach(take));
  shareIx = { to, from };
  return shareIx;
}
/// An id as a number, or `!<id>` for one the manifest has never been told
/// about — a mod added since the last `gen_share_order.py`. A link that carries
/// one is longer and still correct, which is the only direction this may fail.
const siOf = (id) => {
  const n = shareIndex().to.get(id);
  return n == null ? "!" + id : String(n);
};
const siBack = (tok) => {
  if (tok === "" || tok == null) return "";
  if (tok[0] === "!") return tok.slice(1);
  const id = shareIndex().from.get(Number(tok));
  return id == null ? "" : id;
};
/// The characters v3 may travel raw in. Everything the format itself uses, plus
/// what an id or a rank can contain.
const SHARE_TEXT_OK = /^[A-Za-z0-9~.:;,!_-]*$/;

/// A weapon's evolution id prefix, WITHOUT reading the page — `evoPrefix` asks
/// the DOM and the decoder runs before the weapon has been switched.
const evoPrefixFor = (weaponId) => {
  const w = (META.weapons || []).find((x) => x.id === weaponId);
  const any = ((w && w.evolutions) || [])[0];
  const first = ((any || {}).options || [])[0];
  return first && first.id.startsWith(weaponId + "_") ? weaponId + "_" : "";
};

/// The v2 array as v3 text. One place, and its inverse is directly below it —
/// the pair round-trips, which is what `check_share` asserts over every axis.
function packV3(a) {
  const [, weapon, name, slots9, arcs, evos, rivens, sc, m, md, val, asm] = a;
  if (sc || m) return null;                 // a CLAIM keeps the JSON path
  const pre = evoPrefixFor(weapon);
  const slot = (s) => {
    if (!s) return "";
    const [id, pol, rank] = typeof s === "string" ? [s] : s;
    // A RIVEN SLOT names the riven by its place in field 5, as v2 does with
    // "~0" — `r0` here, because `~` is the field separator.
    const head = String(id)[0] === "~" ? "r" + String(id).slice(1) : siOf(id);
    if (rank != null) return `${head}:${pol || ""}:${rank}`;
    return pol ? `${head}:${pol}` : head;
  };
  const riven = (r) => {
    const [rn, shape, rank, pol, bonuses, malus] = r;
    const stats = (bonuses || []).map(([id, roll]) => `${siOf(id)}:${roll}`).join(",");
    const mal = malus ? `${siOf(malus[0])}:${malus[1]}` : "";
    // A NAME THE SHAPE ALREADY IMPLIES DOES NOT TRAVEL — the same rule every
    // other field here follows. A board riven's local name is
    // `boardRivenName(shape)` and nothing else, so sending it is pure length —
    // and it is the one string in this payload that is NOT url-safe (it is
    // localized: "榜单 · critical_chance / …"), which would have sent every
    // board-riven link back to base64 for a name the reader can compute.
    //
    // AND THE READER NAMES IT IN THEIR OWN LANGUAGE, which is better than
    // carrying the sharer's.
    const derived = boardRivenName({
      bonuses: (bonuses || []).map(([id]) => id),
      malus: malus ? malus[0] : null,
    });
    return [rn === derived ? "" : rn, shape, rank, pol, stats, mal].join(";");
  };
  const out = [
    siOf(weapon),
    name || "",
    (slots9 || []).map(slot).join("."),
    (arcs || []).map((x) => (Array.isArray(x) ? `${siOf(x[0])}:${x[1]}` : siOf(x))).join("."),
    (evos || []).map((e) => (e ? siOf(pre + e) : "")).join("."),
    (rivens || []).map(riven).join("!"),
    md || "",
    val ? `${val[0]}:${val[1]}` : "",
    asm ? `${siOf(asm[0])}:${siOf(asm[1])}` : "",
  ];
  while (out.length > 3 && out[out.length - 1] === "") out.pop();
  const text = out.join("~");
  return SHARE_TEXT_OK.test(text) ? text : null;
}

/// v3 text back into the v2 array, so everything downstream is unchanged.
function unpackV3(text) {
  const f = String(text).split("~");
  const weapon = siBack(f[0]);
  if (!weapon) return null;
  const pre = evoPrefixFor(weapon);
  const list = (i, sep) => (f[i] ? String(f[i]).split(sep || ".") : []);
  const slots9 = list(2).map((t) => {
    if (!t) return 0;
    const [head, pol, rank] = t.split(":");
    const id = head[0] === "r" ? "~" + head.slice(1) : siBack(head);
    if (!id) return 0;
    if (rank != null && rank !== "") return [id, pol || "", Number(rank)];
    return pol ? [id, pol] : id;
  });
  const arcs = list(3).map((t) => {
    const [i, rank] = t.split(":");
    return rank == null ? siBack(i) : [siBack(i), Number(rank)];
  });
  const evos = list(4).map((t) => {
    const id = siBack(t);
    return id && pre && id.startsWith(pre) ? id.slice(pre.length) : id;
  });
  const rivens = list(5, "!").filter(Boolean).map((r) => {
    const [rn, shape, rank, pol, stats, mal] = r.split(";");
    const pair = (t) => { const [i, roll] = t.split(":"); return [siBack(i), Number(roll)]; };
    const bonuses = stats ? stats.split(",").map(pair) : [];
    const malus = mal ? pair(mal) : 0;
    // AN EMPTY NAME MEANS "the one the shape implies" — see `packV3`.
    const name = rn || boardRivenName({
      bonuses: bonuses.map(([id]) => id),
      malus: malus ? malus[0] : null,
    });
    return [name, shape, Number(rank), pol, bonuses, malus];
  });
  const val = f[7] ? f[7].split(":") : null;
  const asm = f[8] ? f[8].split(":") : null;
  return [2, weapon, f[1] || 0, slots9, arcs, evos, rivens, 0, 0,
    f[6] || 0, val ? [val[0], Number(val[1])] : 0,
    asm ? [siBack(asm[0]), siBack(asm[1])] : 0];
}

const b64urlEnc = (u8) => {
  let s = "";
  u8.forEach((b) => { s += String.fromCharCode(b); });
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
};
const b64urlDec = (s) => {
  const b = atob(s.replace(/-/g, "+").replace(/_/g, "/"));
  return Uint8Array.from(b, (c) => c.charCodeAt(0));
};

async function deflate(u8) {
  if (typeof CompressionStream === "undefined") return null;
  const cs = new CompressionStream("deflate-raw");
  const w = cs.writable.getWriter();
  w.write(u8); w.close();
  return new Uint8Array(await new Response(cs.readable).arrayBuffer());
}
async function inflate(u8) {
  const ds = new DecompressionStream("deflate-raw");
  const w = ds.writable.getWriter();
  w.write(u8); w.close();
  return new Uint8Array(await new Response(ds.readable).arrayBuffer());
}

// v2 — POSITIONAL, and nothing that can be derived travels.
//
// v1 was 2.5 kB of JSON before compression and most of it was waste: a
// 914-byte freshness key (a serialised copy of the build, inside the payload
// describing that build), 401 bytes of riven shape DRAFTS the recipient
// regenerates blank anyway, and a JSON key beside every value. Links are
// posted into chat windows and printed into QR codes, so length is a feature.
//
// The layout, by index — read it beside `decodeShare`:
//   0  version (2)
//   1  weapon id
//   2  build name
//   3  slots: 9 entries, each null | [modId] | [modId, pol] | [modId, pol, rank]
//      pol is one letter, rank omitted when it is the mod's max
//   4  arcanes: [] | [id] | [[id, rank], …]      rank omitted when max
//   5  evolutions by tier: ["evo1_incarnon_form", "", …] — the weapon prefix
//      is stripped, since a tier's options belong to the weapon in field 1
//   6  rivens: [[name, shape, rank, pol, [[statId, roll], …], [malusId, roll]|0], …]
//   7  scenario: only what DIFFERS from the server's own defaults
//   8  measurement: [score, duration, dps] | 0
const POL_LETTER = { Madurai: "M", Naramon: "N", Vazarin: "V", Umbra: "U", Omni: "O" };
const LETTER_POL = Object.fromEntries(Object.entries(POL_LETTER).map(([k, x]) => [x, k]));

// The weapon's evolution group, so ids can travel without their prefix.
const evoPrefix = () => {
  const tiers = weaponEvos();
  const any = (tiers[0] || { options: [] }).options[0];
  if (!any) return "";
  const w = $("weapon").value;
  // Ids are "<group>_<name>" and the group is the transform group, which is
  // the weapon id for every weapon that has one today.
  return any.id.startsWith(w + "_") ? w + "_" : "";
};

/// WHICH BUILD AXES THE SHARE TUPLE CARRIES, by their engine ids.
///
/// The tuple is POSITIONAL and omits everything a recipient can derive, so it
/// cannot iterate a served list the way the state table can — appending a field
/// is a format decision, not a loop. What it can do is DECLARE, and
/// `scripts/check_build_axes.mjs` holds this against
/// `engine::builds::BUILD_AXES`: a new axis fails the check until somebody
/// writes its id here, and writing it means being in this function looking at
/// the tuple. That is the whole mechanism — a forced touch point, rather than a
/// hope that the next person remembers a file they have never opened.
///
/// It has been wrong once, and expensively: `mode` and `valence` were both in
/// `snapshotState` and neither was in the tuple, so a shared Kuva Nukor reopened
/// on the default progenitor element — a link claiming a number for a build it
/// did not carry.
const SHARE_AXES = ["mods", "evolutions", "arcanes", "arcane_ranks", "mode",
                    "valence", "rivens", "assembly"];

function sharePayload() {
  const st = snapshotState();
  const p = loadPresetList(BUILDS).find((x) => x.name === activePreset);
  const pre = evoPrefix();

  // The RIVENS the build equips travel whole (field 6), so a slot names one
  // by its index there — "~0" instead of "riven:some long name" repeated.
  const used = st.slots.map((s) => s.mod).filter(isRivenId);
  const rivenOrder = [...new Set(used)].map((id) => String(id).slice(RIVEN_PREFIX.length));
  const slots9 = st.slots.map((s) => {
    if (!s.mod) return 0;
    const id = isRivenId(s.mod)
      ? "~" + rivenOrder.indexOf(String(s.mod).slice(RIVEN_PREFIX.length))
      : s.mod;
    const m = modById(s.mod);
    const pol = POL_LETTER[s.pol] || "";
    const rankOff = m && s.rank != null && s.rank !== m.max_rank;
    // A plain slot is the id alone. The array form only appears when there is
    // something else to say about it.
    if (!pol && !rankOff) return id;
    return rankOff ? [id, pol, s.rank] : [id, pol];
  });

  const arcs = (st.arcane || []).filter((a) => a && a !== "none").map((a, i) => {
    const def = arcaneById(a);
    const rank = (st.arcaneRank || [])[i];
    return (def && rank != null && rank !== def.max_rank) ? [a, rank] : a;
  });

  const tiers = weaponEvos();
  const evos = tiers.map((x) => {
    const id = evoSel[x.tier];
    return id ? (pre && id.startsWith(pre) ? id.slice(pre.length) : id) : "";
  });
  while (evos.length && !evos[evos.length - 1]) evos.pop();

  // The RIVENS the build actually equips, by definition — the recipient has
  // no such item and never will unless it travels. This is the custom/preset
  // line showing up in the wire format: a preset is a state both sides can
  // hold, a custom is a thing only one of them made. Only the ACTIVE shape
  // goes: the other three drafts are scratch paper.
  // BY THE CARD, because that is what a slot names. The wire keeps carrying the
  // NAME as the entry's first field: a card's identity is local — the recipient
  // is being handed a copy and gives it one of their own — so a share format
  // that carried it would be exporting a private key for no reader.
  const byId = new Map(loadPresetList(RIVENS).map((x) => [x.id, x]));
  const rivens = rivenOrder.map((n) => byId.get(n)).filter(Boolean)
    .map((x) => {
      const s = x.state || {};
      return [x.name, s.shape || "", s.rank ?? 8, POL_LETTER[cap1(s.polarity)] || "M",
        (s.bonuses || []).map((b) => [b.id, r3(b.roll)]),
        s.malus ? [s.malus.id, r3(s.malus.roll)] : 0];
    });

  // Only what DIFFERS from the defaults both sides already have.
  const d = META.defaults || {};
  const sc = {};
  const live = snapshotScenario();
  Object.keys(live).forEach((k) => {
    const val = live[k];
    if (k === "buffs") {
      // A buff left at its own default is not a setting — both sides derive
      // the same default from the same mod, so sending it is pure length.
      const def = Object.fromEntries((buffList || []).map((b) => [b.id, b]));
      const out = {};
      Object.entries(val || {}).forEach(([id, c]) => {
        const b = def[id];
        if (b && c.stacks === b.default_stacks && !!c.locked === !!b.default_locked) return;
        out[id] = c.locked ? [c.stacks, 1] : [c.stacks];
      });
      if (Object.keys(out).length) sc.buffs = out;
      return;
    }
    // AN OBJECT NEVER COMPARES EQUAL to another object, so a plain `!==` would
    // send `extra_stats: {}` on every link. Compared by VALUE, which is what
    // "only what differs from the defaults both sides already have" meant all
    // along — it just had no object field to be wrong about until now.
    const same = (a, b) =>
      a && typeof a === "object" ? JSON.stringify(a) === JSON.stringify(b || {}) : a === b;
    if (!same(val, d[k])) sc[k] = val;
  });

  // The sharer's MEASUREMENT, kept as a claim rather than as a fact: the
  // recipient's own run is what decides. Three numbers, not the whole result
  // object — the card needs the headline and the fight, and the fight is
  // field 7.
  const r = p && p.lastResult && p.lastResult.r;
  const m = r ? [r3(r.score), r.duration, Math.round(r.dps || 0)] : 0;

  // THE TWO AXES THAT ARE THE BUILD AND ARE NOT A SLOT: how the weapon is
  // PLAYED, and what a Lich handed it. `snapshotState` has carried both for
  // some time and this tuple read neither, so a shared Kuva Nukor reopened on
  // the default progenitor element and a shared charged Phantasma reopened in
  // base form — a link that changes the build it is claiming a number for.
  //
  // Omitted when the recipient would derive the same value anyway, like every
  // other field here: `defaultMode`/`defaultValence` are what both ends ask,
  // so sending the answer they already have is pure length.
  const dv = defaultValence(st.weapon, null);
  const md = st.mode === defaultMode(st.weapon, null) ? 0 : st.mode;
  const val = (st.valence && st.valence.element !== dv.element) || (st.valence && st.valence.bonus !== dv.bonus)
    ? [st.valence.element, r3(st.valence.bonus)] : 0;

  // **A SHARE LINK IS A BUILD AND NOTHING ELSE**. Fields 7
  // and 8 — the fight and the measurement — are always `0` now, and `0` means
  // NO FIGHT TRAVELLED, which is a different statement from `{}`: an empty
  // object means "a fight travelled and it happens to equal the defaults". The
  // importer has always told the two apart, so every link posted before today
  // still lands exactly as it did; only new ones stop carrying a scenario.
  //
  // WHY IT NARROWED. A link that plants a scenario preset changes the fight the
  // reader is working in, which is the one thing a build link has no business
  // doing — and the measurement beside it is a claim ABOUT that scenario, so
  // without the fight it means nothing anyway. The measured result still
  // travels as the CARD, which is a picture of a run rather than something that
  // lands in the reader's app.
  //
  // It also ends a size argument that should never have existed: the rulers pin
  // every wielder field on purpose, so a ruler-derived link was carrying four
  // Warframe numbers the recipient computes anyway.
  // THE PARTS, on the same terms: omitted when the recipient derives the same
  // answer, since `defaultAssembly` is what both ends ask. Two ids, in the
  // order the control draws them.
  const da = defaultAssembly(st.weapon, null);
  const asm = st.assembly && da
      && (st.assembly.grip !== da.grip || st.assembly.loader !== da.loader)
    ? [st.assembly.grip, st.assembly.loader] : 0;

  // A NAME THE SHARER CHOSE TRAVELS; A MACHINE-GENERATED ONE DOES NOT. A board build's preset id is
  // `single_target#cycle#p#1` — 25 characters that mean nothing to the person
  // opening the link, and the importer already falls back to "build (shared)"
  // when the field is absent. A name somebody typed is theirs and still goes.
  const nm = officialBuildActive() ? 0 : activePreset;

  const out = [2, st.weapon, nm, slots9, arcs, evos, rivens, 0, 0, md, val, asm];
  while (out.length > 9 && !out[out.length - 1]) out.pop();
  return out;
}

const r3 = (x) => Math.round((Number(x) || 0) * 1000) / 1000;
const cap1 = (s) => String(s || "").replace(/^./, (c) => c.toUpperCase());

async function shareUrl() {
  const payload = sharePayload();
  // THE SHORTEST OF THREE, chosen by measuring rather than by rule. v3 wins on
  // every ordinary build — the ids become numbers and the text goes in raw —
  // and loses on a payload it cannot express (a CLAIM, or a riven named in a
  // script the URL would have to escape), where the two older forms are still
  // there and still read every link ever posted.
  const text = packV3(payload);
  const json = new TextEncoder().encode(JSON.stringify(payload));
  const z = await deflate(json);
  const zipped = z && z.length < json.length
    ? SHARE_V_DEFLATE + b64urlEnc(z)
    : SHARE_V_PLAIN + b64urlEnc(json);
  const code = text != null && SHARE_V_TEXT.length + text.length < zipped.length
    ? SHARE_V_TEXT + text
    : zipped;
  const w = weaponInfo($("weapon").value);
  return `${location.origin}${weaponPath(w.id)}?${SHARE_PARAM}=${code}`;
}

async function decodeShare(code) {
  if (!code) return null;
  // v3 IS TEXT, so it never goes near base64 or inflate. Dispatched on the
  // version character the code has always carried, which is why adding a third
  // form costs the older two nothing.
  let data;
  if (code[0] === SHARE_V_TEXT) {
    data = unpackV3(code.slice(1));
    if (!data) return null;
  } else {
    const bytes = b64urlDec(code.slice(1));
    const json = code[0] === SHARE_V_DEFLATE ? await inflate(bytes) : bytes;
    data = JSON.parse(new TextDecoder().decode(json));
  }
  if (!Array.isArray(data)) return v1Share(data);      // links posted before v2
  const [, weapon, name, slots9, arcs, evos, rivens, sc, m, md, val, asm] = data;
  return {
    w: weapon,
    n: name,
    // Absent means "whatever this weapon's default is", which is exactly what
    // `defaultMode`/`defaultValence` answer when handed nothing — so a link
    // posted before these two travelled still lands where it always did.
    mode: md || undefined,
    valence: val ? { element: val[0], bonus: val[1] } : undefined,
    // Absent means this weapon's default, the same as the two above — so a link
    // posted before parts travelled still lands where it always did, and an
    // ordinary weapon (which has none) is unaffected either way.
    assembly: asm ? { grip: asm[0], loader: asm[1] } : undefined,
    slots: (slots9 || []).map((s) => {
      if (!s) return { mod: null, pol: null, rank: null };
      const [id, pol, rank] = typeof s === "string" ? [s] : s;
      return { mod: id, pol: LETTER_POL[pol] || null, rank: rank ?? null };
    }),
    arcane: (arcs || []).map((a) => (Array.isArray(a) ? a[0] : a)),
    arcaneRank: (arcs || []).map((a) => (Array.isArray(a) ? a[1] : null)),
    evos: evos || [],
    rivens: (rivens || []).map(([rn, shape, rank, pol, bonuses, malus]) => ({
      n: rn,
      s: {
        shape, rank, polarity: (LETTER_POL[pol] || "Madurai").toLowerCase(),
        bonuses: (bonuses || []).map(([id, roll]) => ({ id, roll })),
        malus: malus ? { id: malus[0], roll: malus[1] } : null,
      },
    })),
    // `null` means the link carried NO FIGHT — see `sharePayload`. `{}` means
    // it carried one that equals the defaults, and the two must not collapse.
    sc: sc ? expandScenario(sc) : null,
    m: m ? { score: m[0], duration: m[1], dps: m[2] } : null,
  };
}

// `buffs` travels as {id: [stacks] | [stacks, 1]} — the pair the panel wants
// is rebuilt here rather than spelled out in the link.
function expandScenario(sc) {
  if (!sc.buffs) return sc;
  const buffs = {};
  Object.entries(sc.buffs).forEach(([id, c]) => {
    buffs[id] = Array.isArray(c) ? { stacks: c[0], locked: !!c[1] } : c;
  });
  return { ...sc, buffs };
}

// A v1 link (the first shape this shipped in) read into the v2 structure.
function v1Share(d) {
  if (!d || !d.b) return null;
  return {
    w: d.w, n: d.n,
    slots: d.b.slots || [],
    arcane: d.b.arcane || [], arcaneRank: d.b.arcaneRank || [],
    evos: Object.values(d.b.evoSel || {}).map((x) => x || ""),
    rivens: d.r || [],
    sc: (d.sc && d.sc.state) || {},
    m: d.m && d.m.r ? { score: d.m.r.score, duration: d.m.r.duration, dps: d.m.r.dps } : null,
  };
}

// Land a shared link: a NEW copy of every part, never a merge into what is
// already there. A link is someone else's work — it may not overwrite yours,
// and it may not need you to rebuild half of it by hand.
async function importShare(code) {
  let data;
  try { data = await decodeShare(code); } catch (_) { data = null; }
  if (!data) { presetToast(tr("that share link could not be read")); return false; }
  const w = (META.weapons || []).find((x) => x.id === data.w);
  if (!w) { presetToast(tr("that share link is for a weapon this build of the site does not have")); return false; }

  switchWeapon(w.id);

  // 1. The RIVENS first: the slots point at them by the wire's own key, and the
  //    copy made here is a card of the recipient's with an identity of its
  //    own — so what the slots are rewritten with is the map from that key to
  //    the new id.
  const imported = {};
  if ((data.rivens || []).length) {
    const ps = loadPresetList(RIVENS);
    data.rivens.forEach((x) => {
      const name = freeName(ps, (n) => x.n + (n > 1 ? " " + n : ""));
      const id = newRivenId(loadPresetWhole(RIVENS).concat(ps));
      imported[x.n] = id;
      ps.push({ id, name, savedAt: Date.now(), state: withDrafts(x.s) });
    });
    storePresetList(RIVENS, ps);
    refreshRivenNames();
  }

  // 2. The SCENARIO — only when one travelled. A BUILD-only link carries no
  //    fight (`data.sc === null`), and the rule that makes it worth having is
  //    that it CHANGES NOTHING about the reader's own: no new preset, no
  //    switch of the active one. A build is a statement about a weapon and a
  //    fight is not, so posting "here is my Torid" into a chat must not move
  //    the fight of everyone who clicks it.
  //
  //    When one DID travel it lands as its own new entry, because the fight a
  //    number was measured in is half of what makes the number checkable.
  //    Only the differences travelled; the server's own defaults fill the rest
  //    back in, which is the same table the sender diffed against.
  const scState = data.sc ? { ...defaultScenario(), ...data.sc } : null;
  if (scState) {
    const sc = loadPresetList(SCENARIOS);
    const scName = freeName(sc, (n) => "scenario" + (n > 1 ? " " + n : ""));
    sc.push({ name: scName, savedAt: Date.now(), state: scState });
    storePresetList(SCENARIOS, sc);
    activeScenario = scName;
    localStorage.setItem(presetActiveKey(SCENARIOS), scName);
  }

  // 3. The BUILD, with riven ids repointed at the copies just made and any id
  //    this build of the site does not know dropped — said out loud rather
  //    than silently, the same rule the cross-weapon import follows.
  const dropped = [];
  const slots2 = (data.slots || []).map((s) => {
    if (!s || !s.mod) return { mod: null, pol: s ? s.pol : null, rank: null };
    // "~<n>" names the nth riven in field 6 — resolve it to the copy just
    // imported, whatever that copy had to be renamed to.
    if (/^~\d+$/.test(s.mod)) {
      const src = (data.rivens || [])[Number(s.mod.slice(1))];
      const nm = src && (imported[src.n] || src.n);
      return nm ? { ...s, mod: RIVEN_PREFIX + nm } : { mod: null, pol: s.pol, rank: null };
    }
    if (isRivenId(s.mod)) {                       // v1 links
      const was = String(s.mod).slice(RIVEN_PREFIX.length);
      return { ...s, mod: RIVEN_PREFIX + (imported[was] || was) };
    }
    if (!modById(s.mod)) { dropped.push(s.mod); return { mod: null, pol: s.pol, rank: null }; }
    return s;
  });
  const pre = evoPrefix();
  const evoSel2 = {};
  (data.evos || []).forEach((id, i) => { if (id) evoSel2[i + 1] = pre && !id.startsWith(pre) ? pre + id : id; });

  const state = buildState(w.id, {
    slots: slots2,
    arcane: data.arcane,
    arcaneRank: data.arcaneRank,
    evoSel: evoSel2,
    // Handed to `restoreState` raw, because it already cleans both against the
    // weapon being opened: an element this spec does not offer is dropped, a
    // mode it cannot be played in falls back to the arsenal's.
    mode: data.mode,
    valence: data.valence,
    // Same terms: `restoreState` repairs a part this weapon cannot take, and
    // `undefined` on a link posted before parts travelled means its default.
    assembly: data.assembly,
  });
  const builds = loadPresetList(BUILDS);
  // Named for where it came from. Without it a link lands as "build 1 2",
  // which says nothing about being someone else's work.
  const base = `${data.n || "build"} (shared)`;
  const name = freeName(builds, (n) => base + (n > 1 ? " " + n : ""));
  activePreset = name;
  localStorage.setItem(presetActiveKey(BUILDS), name);
  // The build, then the FIGHT — through the scenario's own door. The link
  // carries both and both must land, but a build does not set a scenario:
  // the copy above is already the active `simulator-scenarios` entry, and
  // this is what puts it on screen.
  whileApplying(() => {
    restoreState(state, w.id);
    // …and nothing else touches the fight when none travelled: `applyScenario`
    // is the only door a scenario is set through, so not opening it IS the
    // guarantee (`check_preset_independence.mjs` asserts the same rule for a
    // build being LOADED, which is the case this one now matches).
    if (scState) applyScenario(scState);
  });
  builds.push({
    name, savedAt: Date.now(), state: snapshotState(),
    // The sharer's number, as THEIR claim: it is stamped with a key that
    // cannot match this machine's, so the first thing measured here replaces
    // it rather than silently inheriting someone else's measurement.
    ...(data.m ? { lastResult: { r: data.m, at: Date.now(), key: "shared" } } : {}),
  });
  storePresetList(BUILDS, builds);

  renderPresetBar(); renderScenarioBar(); renderMods(); renderSim(); refreshPanel();
  renderStoredSimResult();
  // WHAT LANDED, said out loud — and a build-only link says so by NOT listing
  // a scenario, which is the one thing a reader would otherwise have to check
  // their own scenario bar to discover.
  const bits = [tr("build")];
  if ((data.rivens || []).length) bits.push(`${data.rivens.length} ${tr("riven")}`);
  if (scState) bits.push(tr("scenario"));
  presetToast(`${tr("imported")}: ${name} · ${bits.join(" + ")}` +
    (dropped.length ? ` · ${tr("dropped")} ${dropped.length}` : ""));
  return true;
}

// The share panel: the link, and a CARD to paste into a chat. Both carry the
// site's own address — an image that travels without one is a screenshot of
// nowhere.
async function openSharePanel(bar) {
  const panel = bar.querySelector(".pshare");
  if (!panel) return;
  if (!panel.hidden) { panel.hidden = true; return; }
  // TWO THINGS ARE SHAREABLE HERE AND ONLY ONE OF THEM IS A CLAIM. A BUILD is a statement about a weapon; a RESULT is that build
  // plus the fight it was measured in plus the number. They were one link, so
  // every "here is my Torid" posted into a chat also carried a fight and a
  // measurement — and planted a scenario preset in the reader's collection.
  //
  // The BUILD link is the default and it is INSTANT: it needs no simulation,
  // so the panel opens on content rather than on a spinner. The claim is one
  // click away and still costs a run, because a number nobody measured is not
  // a claim.
  panel.hidden = false;
  const bUrl = await shareUrl();
  panel.innerHTML =
    `<div class="sh-row"><input class="sh-url" type="text" readonly value="${escHtml(bUrl)}">` +
    `<button class="cu-btn sh-copy">${escHtml(tr("copy link"))}</button></div>` +
    `<div class="sh-note">${escHtml(tr("the build and its rivens, and nothing else: no fight, no measurement, so opening it leaves the reader's own scenario untouched"))}</div>` +
    `<div class="sh-more"><button class="cu-btn sh-full">${
      escHtml(tr("…with the fight and the measurement →"))}</button></div>`;
  const bBox = panel.querySelector(".sh-url");
  bBox.onclick = () => bBox.select();
  panel.querySelector(".sh-copy").onclick = async () => {
    try { await navigator.clipboard.writeText(bUrl); presetToast(tr("link copied")); }
    catch (_) { bBox.select(); presetToast(tr("press Ctrl+C to copy the selected link")); }
  };
  panel.querySelector(".sh-full").onclick = () => openShareClaim(panel, bUrl);
}

/// THE CARD: a picture of this build's run, to paste into a chat window. Split
/// out of the panel above so it costs a simulation only when somebody asks.
///
/// THE LINK IS THE SAME BUILD LINK, never a second longer one carrying the
/// fight and the measurement — a CLAIM: a link may plant a build and never a
/// scenario. The measurement still
/// travels, as the picture, which is a thing a reader looks at rather than
/// something that lands in their app.
async function openShareClaim(panel, url) {
  const more = panel.querySelector(".sh-more");
  if (!more) return;
  // Measure BEFORE building the link, so both the card and the payload carry
  // a number produced by exactly this build in exactly this fight.
  more.innerHTML = `<div class="sh-note">${escHtml(tr("simulating this build in the current scenario…"))}</div>`;
  await resultForShare();
  more.innerHTML =
    `<div class="sh-row"><input class="sh-url" type="text" readonly value="${escHtml(url)}">` +
    `<button class="cu-btn sh-copy">${escHtml(tr("copy link"))}</button>` +
    `<button class="cu-btn sh-img">${escHtml(tr("copy image"))}</button>` +
    `<button class="cu-btn sh-dl">${escHtml(tr("download image"))}</button></div>` +
    `<div class="sh-note">${escHtml(tr("the CARD shows the measurement; the link beside it is the same build-only link — opening it never touches the reader's own scenario"))}</div>` +
    `<canvas class="sh-canvas" width="900" height="640"></canvas>`;
  const urlBox = more.querySelector(".sh-url");
  urlBox.onclick = () => urlBox.select();
  const canvas = more.querySelector(".sh-canvas");
  await drawShareCard(canvas, url);

  // SCOPED TO `more`, NOT TO THE PANEL: the build link above has a `.sh-copy`
  // of its own, and a panel-wide lookup finds THAT one — which would leave the
  // claim's button dead and silently repoint the build's at the claim's url.
  const say = (msg) => presetToast(tr(msg));
  more.querySelector(".sh-copy").onclick = async () => {
    try { await navigator.clipboard.writeText(url); say("link copied"); }
    // Clipboard permission can be refused; selecting the text is the fallback
    // that always works, and no dialog is involved either way.
    catch (_) { urlBox.select(); say("press Ctrl+C to copy the selected link"); }
  };
  more.querySelector(".sh-img").onclick = async () => {
    try {
      const blob = await new Promise((res) => canvas.toBlob(res, "image/png"));
      await navigator.clipboard.write([new ClipboardItem({ "image/png": blob })]);
      say("image copied");
    } catch (_) { say("this browser will not copy images — use download"); }
  };
  more.querySelector(".sh-dl").onclick = () => {
    const a = document.createElement("a");
    a.href = canvas.toDataURL("image/png");
    a.download = `wfsim-${$("weapon").value}-${presetLabel(buildNamed(activePreset))}.png`.replace(/[\s#]+/g, "-");
    a.click();
  };
}

// ---- QR ---------------------------------------------------------------
// A card is pasted into a chat and read on a phone, and a phone cannot click
// a picture. Written here rather than pulled in: the repo
// takes no dependencies, and a QR encoder is a bounded piece of arithmetic —
// byte mode, error correction L (the most data per module, and a card is not
// a sticker on a wet crate), smallest version that fits.
//
// Spec: ISO/IEC 18004. The three tables below are the parts of it that cannot
// be derived — everything else is computed.
const QR_ECC_L = [
  [7, 1], [10, 1], [15, 1], [20, 1], [26, 1], [18, 2], [20, 2], [24, 2], [30, 2], [18, 4],
  [20, 4], [24, 4], [26, 4], [30, 4], [22, 6], [24, 6], [28, 6], [30, 6], [28, 7], [28, 8],
  [28, 8], [28, 9], [30, 9], [30, 10], [26, 12], [28, 12], [30, 12], [30, 13], [30, 14], [30, 15],
  [30, 16], [30, 17], [30, 18], [30, 19], [30, 19], [30, 20], [30, 21], [30, 22], [30, 24], [30, 25],
];
// Total codewords per version (data + ecc).
const QR_TOTAL = [26, 44, 70, 100, 134, 172, 196, 242, 292, 346, 404, 466, 532, 581, 655, 733,
  815, 901, 991, 1085, 1156, 1258, 1364, 1474, 1588, 1706, 1828, 1921, 2051, 2185, 2323, 2465,
  2611, 2761, 2876, 3034, 3196, 3362, 3532, 3706];
// Alignment-pattern centres per version (empty for version 1).
const QR_ALIGN = [[], [6, 18], [6, 22], [6, 26], [6, 30], [6, 34], [6, 22, 38], [6, 24, 42],
  [6, 26, 46], [6, 28, 50], [6, 30, 54], [6, 32, 58], [6, 34, 62], [6, 26, 46, 66], [6, 26, 48, 70],
  [6, 26, 50, 74], [6, 30, 54, 78], [6, 30, 56, 82], [6, 30, 58, 86], [6, 34, 62, 90],
  [6, 28, 50, 72, 94], [6, 26, 50, 74, 98], [6, 30, 54, 78, 102], [6, 28, 54, 80, 106],
  [6, 32, 58, 84, 110], [6, 30, 58, 86, 114], [6, 34, 62, 90, 118], [6, 26, 50, 74, 98, 122],
  [6, 30, 54, 78, 102, 126], [6, 26, 52, 78, 104, 130], [6, 30, 56, 82, 108, 134],
  [6, 34, 60, 86, 112, 138], [6, 30, 58, 86, 114, 142], [6, 34, 62, 90, 118, 146],
  [6, 30, 54, 78, 102, 126, 150], [6, 24, 50, 76, 102, 128, 154], [6, 28, 54, 80, 106, 132, 158],
  [6, 32, 58, 84, 110, 136, 162], [6, 26, 54, 82, 110, 138, 166], [6, 30, 58, 86, 114, 142, 170]];

// GF(256) with the QR primitive polynomial 0x11d.
const GF_EXP = new Uint8Array(512), GF_LOG = new Uint8Array(256);
(() => {
  let x = 1;
  for (let i = 0; i < 255; i++) {
    GF_EXP[i] = x; GF_LOG[x] = i;
    x <<= 1; if (x & 0x100) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i++) GF_EXP[i] = GF_EXP[i - 255];
})();
const gfMul = (a, b) => (a && b ? GF_EXP[GF_LOG[a] + GF_LOG[b]] : 0);

// The generator polynomial for `n` ecc codewords.
function qrGenPoly(n) {
  let poly = [1];
  for (let i = 0; i < n; i++) {
    const next = new Array(poly.length + 1).fill(0);
    for (let j = 0; j < poly.length; j++) {
      next[j] ^= gfMul(poly[j], GF_EXP[i]);
      next[j + 1] ^= poly[j];
    }
    poly = next;
  }
  // Built LOW-degree-first; the division below indexes it high-degree-first
  // (gen[0] is the monic leading 1 it skips). Verified against a reference
  // encoder: without this the ECC block is wrong and nothing scans.
  return poly.reverse();
}

function qrEcc(data, n) {
  const gen = qrGenPoly(n);
  const rem = new Array(n).fill(0);
  for (const d of data) {
    const factor = d ^ rem[0];
    rem.shift(); rem.push(0);
    for (let j = 0; j < n; j++) rem[j] ^= gfMul(gen[j + 1], factor);
  }
  return rem;
}

// Bytes -> the module matrix, or null when the text does not fit any version.
function qrMatrix(text) {
  const bytes = new TextEncoder().encode(text);
  let version = 0, dataCw = 0, eccPer = 0, blocks = 0;
  for (let v = 1; v <= 40; v++) {
    const [e, b] = QR_ECC_L[v - 1];
    const total = QR_TOTAL[v - 1];
    const cap = total - e * b;
    const lenBits = v < 10 ? 8 : 16;
    if (4 + lenBits + bytes.length * 8 <= cap * 8) {
      version = v; dataCw = cap; eccPer = e; blocks = b; break;
    }
  }
  if (!version) return null;

  // ---- bit stream: mode 0100, length, data, terminator, pad --------------
  const bits = [];
  const push = (val, n) => { for (let i = n - 1; i >= 0; i--) bits.push((val >> i) & 1); };
  push(0b0100, 4);
  push(bytes.length, version < 10 ? 8 : 16);
  bytes.forEach((b) => push(b, 8));
  for (let i = 0; i < 4 && bits.length < dataCw * 8; i++) bits.push(0);
  while (bits.length % 8) bits.push(0);
  const cw = [];
  for (let i = 0; i < bits.length; i += 8) {
    cw.push(bits.slice(i, i + 8).reduce((a, b) => (a << 1) | b, 0));
  }
  for (let i = 0; cw.length < dataCw; i++) cw.push(i % 2 ? 0x11 : 0xec);

  // ---- split into blocks, interleave data then ecc ----------------------
  const short = Math.floor(dataCw / blocks), extra = dataCw % blocks;
  const dblocks = [], eblocks = [];
  let at = 0;
  for (let i = 0; i < blocks; i++) {
    const n = short + (i >= blocks - extra ? 1 : 0);
    const d = cw.slice(at, at + n); at += n;
    dblocks.push(d);
    eblocks.push(qrEcc(d, eccPer));
  }
  const out = [];
  for (let i = 0; i < Math.max(...dblocks.map((d) => d.length)); i++) {
    dblocks.forEach((d) => { if (i < d.length) out.push(d[i]); });
  }
  for (let i = 0; i < eccPer; i++) eblocks.forEach((e) => out.push(e[i]));

  // ---- the matrix -------------------------------------------------------
  const size = version * 4 + 17;
  const m = Array.from({ length: size }, () => new Array(size).fill(null));
  const set = (r, c, v) => { if (r >= 0 && c >= 0 && r < size && c < size) m[r][c] = v; };
  const finder = (r, c) => {
    for (let i = -1; i <= 7; i++) for (let j = -1; j <= 7; j++) {
      const on = i >= 0 && i <= 6 && j >= 0 && j <= 6
        && (i === 0 || i === 6 || j === 0 || j === 6 || (i >= 2 && i <= 4 && j >= 2 && j <= 4));
      set(r + i, c + j, on ? 1 : 0);
    }
  };
  finder(0, 0); finder(0, size - 7); finder(size - 7, 0);
  for (let i = 8; i < size - 8; i++) {
    m[6][i] = i % 2 === 0 ? 1 : 0;
    m[i][6] = i % 2 === 0 ? 1 : 0;
  }
  // Alignment patterns sit at every pairing of the centres EXCEPT the three
  // that would land on a finder. Testing "is this module already set" instead
  // also skipped the ones that sit ON the timing line — which the spec puts
  // there deliberately — and every version 7 and up came out unreadable.
  const centres = QR_ALIGN[version - 1];
  const last = centres[centres.length - 1];
  centres.forEach((r) => centres.forEach((c) => {
    if ((r === 6 && c === 6) || (r === 6 && c === last) || (r === last && c === 6)) return;
    for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++) {
      set(r + i, c + j, (Math.abs(i) === 2 || Math.abs(j) === 2 || (i === 0 && j === 0)) ? 1 : 0);
    }
  }));
  m[size - 8][8] = 1;                              // the always-dark module

  // Version information (7 versions and up), BCH(18,6).
  if (version >= 7) {
    // BCH(18,6) over the 6-bit version, generator 0x1F25 — 12 check bits.
    let rem = version;
    for (let i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >> 11) * 0x1f25);
    const info = ((version << 12) | (rem & 0xfff)) >>> 0;
    for (let i = 0; i < 18; i++) {
      const bit = (info >> i) & 1;
      m[Math.floor(i / 3)][size - 11 + (i % 3)] = bit;
      m[size - 11 + (i % 3)][Math.floor(i / 3)] = bit;
    }
  }

  // Reserve the format area so the data walk skips it. Cells are [row, col];
  // the spec states them as (x, y) = (column, row), which is the transposition
  // that had the walk skipping the wrong modules.
  const fmtCells = [[7, 8], [8, 8], [8, 7]];
  for (let i = 0; i <= 5; i++) fmtCells.push([i, 8], [8, i]);
  for (let i = 0; i < 8; i++) fmtCells.push([8, size - 1 - i], [size - 1 - i, 8]);
  fmtCells.forEach(([r, c]) => { if (m[r][c] === null) m[r][c] = 0; });

  // ---- the data walk, mask 0 -------------------------------------------
  // One mask, not eight: the spec's penalty scoring picks the prettiest of
  // eight, but every one of them scans. Mask 0 (`(r+c) % 2`) on a payload
  // this dense is well inside what any reader handles, and eight passes of
  // penalty arithmetic is a lot of code to own for a cosmetic gain.
  const taken = m.map((row) => row.map((x) => x !== null));
  let bi = 0;
  const dataBit = () => {
    const byte = out[bi >> 3];
    const bit = byte === undefined ? 0 : (byte >> (7 - (bi & 7))) & 1;
    bi++;
    return bit;
  };
  let upward = true;
  for (let col = size - 1; col > 0; col -= 2) {
    if (col === 6) col--;                          // the timing column
    for (let n = 0; n < size; n++) {
      const row = upward ? size - 1 - n : n;
      for (const c of [col, col - 1]) {
        if (taken[row][c]) continue;
        const bit = dataBit() ^ ((row + c) % 2 === 0 ? 1 : 0);
        m[row][c] = bit;
      }
    }
    upward = !upward;
  }

  // ---- format information: ecc L (01) + mask 0, BCH(15,5) + 0x5412 ------
  const fmtData = (0b01 << 3) | 0;
  let rem = fmtData << 10;
  for (let i = 4; i >= 0; i--) if ((rem >> (i + 10)) & 1) rem ^= 0x537 << i;
  const fmt = ((fmtData << 10) | rem) ^ 0x5412;
  const fbit = (i) => (fmt >> i) & 1;
  for (let i = 0; i <= 5; i++) m[i][8] = fbit(i);
  m[7][8] = fbit(6);
  m[8][8] = fbit(7);
  m[8][7] = fbit(8);
  for (let i = 9; i <= 14; i++) m[8][14 - i] = fbit(i);
  for (let i = 0; i <= 7; i++) m[8][size - 1 - i] = fbit(i);
  for (let i = 8; i <= 14; i++) m[size - 15 + i][8] = fbit(i);
  m[size - 8][8] = 1;                              // the always-dark module

  return m;
}

// A QR as its OWN canvas, at a whole number of pixels per module.
//
// Drawn straight onto the card it came out unreadable: a dense symbol scaled
// to fit a box lands on fractional module sizes, and rounding each one up
// smears neighbours together. Rendering at an integer scale and then placing
// it at its natural size is the difference between a picture of a QR and one
// that scans. Quiet zone six, not the spec's minimum four — a reference
// encoder's own output fails to scan at four on a dense symbol.
// EIGHT device pixels per module, always — the size is a consequence, not a
// setting. Measured against a real decoder after the resizing a chat app
// does: at 4 px a card only reads at full size, at 6 it survives a 0.66x
// shrink, at 8 it still reads after 0.5x AND JPEG 80. A QR that only scans
// from the original file is a QR nobody scans.
const QR_MODULE_PX = 8;
function qrCanvas(text) {
  const m = qrMatrix(text);
  if (!m) return null;
  const n = m.length, quiet = 6;
  const modulePx = QR_MODULE_PX;
  const side = (n + quiet * 2) * modulePx;
  const c = document.createElement("canvas");
  c.width = side; c.height = side;
  const g = c.getContext("2d");
  g.fillStyle = "#fff"; g.fillRect(0, 0, side, side);
  g.fillStyle = "#000";
  for (let r = 0; r < n; r++) {
    for (let col = 0; col < n; col++) {
      if (m[r][col]) {
        g.fillRect((col + quiet) * modulePx, (r + quiet) * modulePx, modulePx, modulePx);
      }
    }
  }
  return c;
}

// The card. Drawn here rather than server-side: it has to work on a static
// site with no backend, and pasting a picture into a group chat is how a build
// actually gets shown around.
//
// It shows EVERYTHING the link carries that a reader can act on — the weapon,
// the mod cards with their polarities, capacity and Forma, the arcane, the
// evolutions, the riven's own rolls, and the number with the fight and the
// technique it came from. A card that showed the mods and hid the Incarnon
// would be the thing this whole feature exists to stop.
// The site's own name, not wherever this page happens to be served from: the
// card is a thing that travels, and a preview host or a localhost in the
// corner of it would be wrong everywhere it landed.
const SITE_HOST = "wfsim.app";
const CARD_W = 1000, CARD_DPR = 2;

const loadImg = (src) => new Promise((res) => {
  if (!src) return res(null);
  const im = new Image();
  im.onload = () => res(im);
  im.onerror = () => res(null);      // same-origin art, but never block on it
  im.src = src;
});

// Draw `im` to fit a box, centred, aspect kept.
function drawFit(g, im, x, y, w, h) {
  if (!im) return;
  const s = Math.min(w / im.width, h / im.height);
  const dw = im.width * s, dh = im.height * s;
  g.drawImage(im, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh);
}

async function drawShareCard(canvas, url) {
  const W = CARD_W;
  // The QR is built first: its size is fixed by its module count and cannot be
  // squeezed, so the layout is built around it rather than the other way.
  const qc = qrCanvas(url);
  const qs = qc ? qc.width / CARD_DPR : 0;

  const named = slots.map((s, i) => ({ m: s.mod && modById(s.mod), i })).filter((z) => z.m);
  const arc = (arcanes || []).filter((a) => a && a !== "none")
    .map((a) => (arcaneById(a) || {}).name || a);
  const rid = slots.map((s) => s.mod).find(isRivenId);
  const rlines = (rid && ((rivenNames[String(rid).slice(RIVEN_PREFIX.length)] || {}).lines || [])) || [];

  // Below the mod strip the card is TWO COLUMNS: everything a reader reads on
  // the left, the code on the right. One column under a 340px square left a
  // band of empty background as tall as the code itself.
  const NAME_COLS = 2;
  const perCol = Math.ceil(named.length / NAME_COLS) || 1;
  const colTop = 104 + 88 + 26;
  const leftH = perCol * 24 + (arc.length ? 24 : 0) + (rlines.length ? 24 : 0) + 24 + 78;
  const H = colTop + Math.max(leftH, qs + 40) + 22;

  canvas.width = W * CARD_DPR; canvas.height = H * CARD_DPR;
  const g = canvas.getContext("2d");
  g.scale(CARD_DPR, CARD_DPR);

  const css = getComputedStyle(document.documentElement);
  const v = (n, fallback) => (css.getPropertyValue(n) || "").trim() || fallback;
  const bg = v("--surface", "#171a21"), fg = v("--text", "#f2f4f8");
  const dim = v("--muted", "#6b7280"), fg2 = v("--text-2", "#a6adbb");
  const gold = v("--gold", "#e8c37a"), line = v("--line", "rgba(255,255,255,.09)");
  const F = (s, w) => `${w || ""} ${s}px system-ui, -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif`;
  g.fillStyle = bg; g.fillRect(0, 0, W, H);

  const w = weaponInfo($("weapon").value);
  const art = await loadImg(IMG(w.image));
  // The weapon's own art, large and faint behind the lower left — recognisable
  // at a glance in a chat scroll, and never in the way of the text.
  if (art) {
    const h = 300, wid = h * (art.width / art.height || 2);
    g.save();
    g.globalAlpha = 0.09;
    g.drawImage(art, 20, H - h - 10, wid, h);
    g.restore();
  }

  // ---- header: what it is, and what it costs to build ------------------
  g.fillStyle = fg; g.font = F(34, "600");
  g.fillText(w.name, 36, 56);
  if (art) drawFit(g, art, 40 + g.measureText(w.name).width, 26, 60, 34);
  g.fillStyle = dim; g.font = F(15);
  const evos = Object.values(evoSel).filter(Boolean).length;
  g.fillText([presetLabel(buildNamed(activePreset)), tr(w.subtype || w.mod_class || "")]
    .concat(evos ? [`${evos} ${tr("Evolutions")}`] : []).join(" · "), 36, 82);

  // Capacity and Forma, right-aligned — the price of the build, which is half
  // of what a reader is judging.
  const fc = formaCount();
  const cap = capOf(w.id);
  const cost = [`${capacityUsed()} / ${cap}`,
    [`${fc.regular} Forma`, fc.umbra ? `${fc.umbra} Umbra` : null, fc.omni ? `${fc.omni} Omni` : null]
      .filter(Boolean).join(" · ")].join("   ");
  g.textAlign = "right";
  g.fillStyle = capacityUsed() > cap ? v("--critical", "#e05656") : fg2;
  g.font = F(15);
  g.fillText(cost, W - 36, 56);
  g.textAlign = "left";

  // ---- the mod cards, with their polarities ----------------------------
  // An EMPTY slot draws NOTHING — no placeholder, no dash.
  // A gap says "nothing here" without a mark that reads as one.
  const CW = 88, CH = 88, GAP = 8;
  const imgs = await Promise.all(slots.map((s) => {
    const m = s.mod && modById(s.mod);
    return m ? loadImg(IMG(m.image)) : null;
  }));
  const pols = await Promise.all(slots.map((s) => (s.pol ? loadImg(POL(s.pol)) : null)));
  slots.forEach((s, i) => {
    const m = s.mod && modById(s.mod);
    const cx = 36 + i * (CW + GAP), cy = 104;
    if (!m) return;
    if (imgs[i]) drawFit(g, imgs[i], cx, cy, CW, CH);
    else {
      g.strokeStyle = line;
      g.strokeRect(cx + .5, cy + .5, CW - 1, CH - 1);
      g.fillStyle = dim; g.font = F(12);
      g.textAlign = "center";
      g.fillText(m.name.slice(0, 8), cx + CW / 2, cy + CH / 2 + 4);
      g.textAlign = "left";
    }
    if (pols[i]) {
      g.fillStyle = bg;
      g.globalAlpha = .75; g.fillRect(cx, cy, 20, 20); g.globalAlpha = 1;
      drawFit(g, pols[i], cx + 3, cy + 3, 14, 14);
    }
  });

  // ---- left column: names, then the two things names cannot say --------
  let y = colTop;
  g.font = F(15);
  named.forEach((r, n) => {
    const col = Math.floor(n / perCol), row = n % perCol;
    g.fillStyle = fg;
    const tag = r.i === EXILUS ? "E" : String(r.i + 1);
    let label = `${tag}. ${r.m.name}`;
    if (label.length > 22) label = label.slice(0, 21) + "…";
    g.fillText(label, 36 + col * 280, y + row * 24);
  });
  y += perCol * 24 + 8;
  if (arc.length) {
    g.fillStyle = fg2; g.font = F(15);
    g.fillText(`${tr("Arcanes")}: ${arc.join(" · ")}`, 36, y);
    y += 24;
  }
  if (rlines.length) {
    g.fillStyle = fg2; g.font = F(14);
    g.fillText(rlines.map((z) => tf(z)).join("   "), 36, y);
    y += 24;
  }

  // ---- the number, in the app's own units and its own formatting -------
  // `kpm(score, duration)` and `sig2`, exactly as the results panel: the score
  // counts the fraction of a kill too, so a build that drains 0.28% of one
  // enemy reads 0.0028 rather than the 0.00 that `kills` alone produced.
  const p = loadPresetList(BUILDS).find((z) => z.name === activePreset);
  const r = p && p.lastResult && p.lastResult.r;
  const lineEnd = qs ? W - qs - 50 : W - 36;
  y += 8;
  g.strokeStyle = line;
  g.beginPath(); g.moveTo(36, y); g.lineTo(lineEnd, y); g.stroke();
  y += 46;
  if (r) {
    const met = metricOf(sim.metric);
    const v = metricValue(met, r);
    g.fillStyle = gold; g.font = F(40, "600");
    g.fillText(
      (met.per_minute ? sig2(v) : Math.round(v).toLocaleString())
        + " " + metricLabel(met), 36, y);
    g.fillStyle = dim; g.font = F(15);
    const en = allEnemies().find((e) => e.id === sim.enemy) || {};
    // The fight AND the technique. Which form, how often
    // the head is hit and whether aim is held change the number as much as the
    // enemy does. Buffs are deliberately absent: they follow from the build,
    // and a card listing eleven of them would say nothing.
    // The mode is the BUILD's now, so the card reads it there. Still on the
    // card: it changes the number as much as the enemy does, and a share that
    // omitted it would be a claim nobody could reproduce — which is also why
    // a weapon with one way to be fired states it. A card is read away from
    // the app, where "no mode printed" cannot be told from "the mode was left
    // out", and every other term of the claim is printed unconditionally.
    const formLabel = modeLabel(w, mode);
    g.fillText([
      en.name || sim.enemy,
      `Lv ${sim.level}${sim.steel_path ? " SP" : ""}`,
      `${sim.duration}s`,
      formLabel,
      // Only when it is not point blank: 0 m is the fight this card has always
      // described, so printing it on every share would be noise rather than a
      // term of the claim.
      ...(sim.distance > 0 ? [`${sim.distance} m`] : []),
      `${sim.headshot_pct}% ${tr("headshots")}`,
      (w.sentinel || sim.aiming) ? tr("Aiming") : tr("hip-fire"),
      ...(sim.invisible ? [tr("Invisible")] : []),
      ...(sim.airborne ? [tr("Airborne")] : []),
      ...(sim.overshields ? [tr("Overshields")] : []),
      ...(sim.channeling ? [tr("Channeled ability")] : []),
      ...(sim.melee_equipped === false ? [tr("quick-melee")] : []),
      ...(sim.solo_weapon ? [tr("Only this weapon")] : []),
      sim.infinite_ammo === false ? tr("finite ammo") : null,
    ].filter(Boolean).join(" · "), 36, y + 25);
  }

  // ---- right column: the code, and the address -------------------------
  // A card is pasted into a chat and read on a PHONE, which cannot click a
  // picture — without this the link and the image are two things to send.
  if (qc) {
    const qx = W - 26 - qs, qy = colTop;
    g.imageSmoothingEnabled = false;
    g.drawImage(qc, qx, qy, qs, qs);
    g.textAlign = "center";
    g.font = F(21, "600");
    const cx = qx + qs / 2;
    const sw = g.measureText("Sim").width, ww = g.measureText("WF").width;
    g.fillStyle = gold; g.fillText("WF", cx - sw / 2, qy + qs + 26);
    g.fillStyle = fg; g.fillText("Sim", cx + ww / 2, qy + qs + 26);
    g.fillStyle = dim; g.font = F(14);
    g.fillText(SITE_HOST, cx, qy + qs + 46);
    g.textAlign = "left";
  }
}

// ---- Presets ----------------------------------------------------------
// Every preset collection is owned by one of the three modules or by an EDITOR
// that feeds them, and its DOMAIN id is "<owner>-<collection>" — `rivens` alone
// is the owner name by itself, because that editor is ALL collection and there
// is no second one to tell it apart from. Every durable name derives from the
// domain mechanically, and full words only:
//
//   localStorage  wfsim-presets-<weapon>-<domain>        the list
//                 wfsim-preset-active-<weapon>-<domain>  the active pointer
//   DOM id        preset-bar-<domain>
//
// A preset BELONGS TO ONE WEAPON, so the STORAGE key carries the weapon while
// the domain still names the collection — a weapon-less key is one global list
// where edits on the Laetum show up on the Dual Toxocyst. Copying ACROSS
// weapons is the deliberate "⇤ import" on each bar. No count cap: presets live
// in the reader's localStorage rather than with us.
const presetWeapon = () => ($("weapon") && $("weapon").value) || "";
// PRESETS vs CUSTOMS — two kinds of collection, and the difference is who
// consumes them.
//
// A PRESET is a saved state of something that always exists: the builder
// always has a build, the simulator a fight, the optimizer a search. Only its
// own module reads it, there is always at least one, and "active" means the
// state you are currently in.
//
// A CUSTOM is a thing you MADE, and the other modules consume it: a riven
// becomes a mod in the pool, a custom enemy becomes an entry in the scenario's
// enemy list. Owning none is ordinary, each one carries its own identity
// rather than a label you invented, and deleting one breaks references
// elsewhere — which a preset delete can never do. The mental model is a FILE:
// it sits in a list, you open one to edit it, and you can have none open.
//
// Different noun, different key. Everything BELOW the key is shared —
// storage, undo, per-weapon scoping, ⇤ import — because none of that depends
// on which kind it is.
const CUSTOM_DOMAINS = new Set(["rivens", "enemies"]);
const isCustomDomain = (d) => CUSTOM_DOMAINS.has(d);

// …AND ONE COLLECTION THAT IS NOT A WEAPON'S: the FIGHT.
//
// The enemy, its level, Steel Path, the wielder's state, the duration and how
// many runs describe a FIGHT, and a fight is not about any particular gun —
// which the OFFICIAL rulers always were: one `single_target` applies to every
// weapon on the board.
//
// It NARROWS "nothing crosses between weapons" rather than weakening it. That
// rule exists because a BUILD, a SEARCH and a RIVEN are statements about one
// weapon, and inheriting the last weapon's is how you measure a gun you are not
// looking at. A fight is no such statement, so there is nothing to inherit
// wrongly — and the one weapon-scoped knob it still holds, headshot %, is
// handled the way the rulers handle it: the SERVER forces 0 on a weapon that
// cannot headshot.
// …and a TARGET is not a weapon's either, for exactly the reason a fight is
// not: an enemy you built has no opinion about what is shooting it. Same
// consequence — one list for the whole roster, and no "⇤ import", because
// there is no other weapon to import from.

/// …and a RIVEN, which is ABOUT a family and not FILED under one.
///
/// A STORE IS ADDRESSED BY WHAT IT IS AND FILTERED BY WHAT IT IS ABOUT.
/// Content data has no business being a storage address: a key computed from
/// `riven_family` and the mod class makes correcting either one MOVE everybody's
/// saved cards to an address the page no longer computes. So the store is one
/// list, the card carries its own `scope`, and changing a family does exactly
/// what it says — it changes which weapons the card appears under.
const SHARED_DOMAINS = new Set(["simulator-scenarios", "enemies", "rivens"]);
const isSharedDomain = (d) => SHARED_DOMAINS.has(d);

/// WHOSE RIVEN THIS IS — the weapon FAMILY, never the entry: *"Riven mods can
/// be used on variants of a particular weapon, including MK1, Prime, Vandal,
/// Wraith, Dex, Prisma, Mara, and Syndicate variants"* (wiki `Riven Mods`).
/// Filing it under the weapon makes a player build the same card twice and
/// gives them two cards free to drift apart.
///
/// THE NUMBERS FOLLOW BY THEMSELVES, which is why this is a storage change
/// rather than a feature: a saved riven holds ROLLS on 0..1 and the shown value
/// is `roll` against THIS weapon's disposition, computed by `/api/riven` on
/// every render. So one card reads 1.45's worth on a Burston and 1.35's on its
/// Prime with nothing converted — *"the cycling screen allows players to view
/// the Riven stats on every owned variant of said weapon"*. A weapon that
/// declares no family is its own and keeps the key it already had.
///
/// THE RIVEN CLASS IS PART OF THE SCOPE, and a KITGUN is why. A Tombfinger
/// built as a primary takes a RIFLE riven and the same chamber built as a
/// secondary takes a PISTOL one — one family, two cards, two pools. Filing
/// both under `tombfinger` would put a rifle riven in a pistol's list, where
/// the editor offers it and the board refuses it. An engine test holds the
/// other half: every weapon sharing a (family, class) rolls the same pool.
const rivenSlug = (x) => String(x || "")
  .toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
const rivenScope = (id) => {
  // NOT `weaponInfo`: that falls back to the FIRST weapon in the roster for an
  // id it does not know, which would file a riven under a stranger's family.
  const w = ((META && META.weapons) || []).find((x) => x.id === id);
  const fam = rivenSlug((w && w.riven_family) || id);
  const cls = rivenSlug(w && (w.riven_class || w.mod_class));
  return cls ? `${fam}-${cls}` : fam;
};
/// Every scope a riven can legitimately be filed under today.
const rivenScopes = () =>
  new Set(((META && META.weapons) || []).map((w) => rivenScope(w.id)));

const domainScope = (d, w) => {
  if (isSharedDomain(d)) return "";
  return (w ?? presetWeapon()) + "-";
};
const presetListKey = (d, w) =>
  (isCustomDomain(d) ? "wfsim-customs-" : "wfsim-presets-") + domainScope(d, w) + d;
/// …AND WHICH ONE IS OPEN IS THE FOLDER'S, even where the store is not.
///
/// A riven's cards live in one list, but "the card I am looking at" is a
/// property of the weapon in front of you — leaving Burston Prime and coming
/// back should find the same one open, and going to a Laetum should not. This
/// is the ONE riven key still built from the scope, and it is the one place
/// that is safe: a scope that moves loses a pointer, and the worst a lost
/// pointer does is open nothing.
const presetActiveKey = (d, w) =>
  (isCustomDomain(d) ? "wfsim-custom-open-" : "wfsim-preset-active-")
  + (d === RIVENS ? `${rivenScope(w ?? presetWeapon())}-` : domainScope(d, w)) + d;

// ONE-TIME MERGE of every weapon's scenario list into the shared one. A player
// who made a fight on the Torid must not have to make it again — and the lists
// are additive, so this reads them all and keeps every entry, renaming a
// collision rather than dropping either side.
(function mergeScenarioLists() {
  const D = "simulator-scenarios";
  const shared = presetListKey(D);
  const per = [];
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    const m = k && /^wfsim-presets-(.+)-simulator-scenarios$/.exec(k);
    if (m) per.push([k, m[1]]);
  }
  if (!per.length) return;
  let out = [];
  try { out = JSON.parse(localStorage.getItem(shared) || "[]") || []; } catch (_) { out = []; }
  const seen = new Set(out.map((p) => JSON.stringify(p.state)));
  for (const [k, weapon] of per) {
    let list = [];
    try { list = JSON.parse(localStorage.getItem(k) || "[]") || []; } catch (_) { list = []; }
    for (const p of list) {
      // IDENTICAL FIGHTS COLLAPSE. Most players' per-weapon copies are the same
      // fight made twice, and carrying six of them across would turn a merge
      // into a mess the player has to clean up.
      const sig = JSON.stringify(p.state);
      if (seen.has(sig)) continue;
      seen.add(sig);
      let name = p.name;
      if (out.some((q) => q.name === name)) name = `${name} (${weapon})`;
      out.push({ ...p, name });
    }
    localStorage.removeItem(k);
    localStorage.removeItem(`wfsim-preset-active-${weapon}-${D}`);
  }
  if (out.length) localStorage.setItem(shared, JSON.stringify(out));
})();

// One-time rename of every custom collection out of the preset namespace.
// The data is unchanged; only the noun was wrong.
(function migrateCustomKeys() {
  const moves = [];
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    let m = /^wfsim-presets-(.+)-([^-]+)$/.exec(k);
    if (m && isCustomDomain(m[2])) moves.push([k, `wfsim-customs-${m[1]}-${m[2]}`]);
    m = /^wfsim-preset-active-(.+)-([^-]+)$/.exec(k);
    if (m && isCustomDomain(m[2])) moves.push([k, `wfsim-custom-open-${m[1]}-${m[2]}`]);
  }
  moves.forEach(([from, to]) => {
    const v = localStorage.getItem(from);
    if (v !== null && localStorage.getItem(to) === null) localStorage.setItem(to, v);
    localStorage.removeItem(from);
  });
})();
/// ONE-TIME FOLD of every riven list this app has ever written into the ONE
/// list, tagging each card with the scope it was filed under. It RUNS AFTER
/// `META`, because a scope is something only the roster knows.
///
/// IT ALSO GIVES EVERY CARD ITS IDENTITY. A build referenced a riven by NAME
/// once, so this is where `riven:<name>` becomes `riven:<id>` — resolved per
/// old key, which is what makes it unambiguous: two variants of one family
/// could each hold a "riven 1", and only the key says whose build meant which.
/// After this a name is a label and nothing points at it.
function foldRivensIntoOneList() {
  const KEY = "wfsim-customs-rivens";
  const olds = [];
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i) || "";
    const m = /^wfsim-customs-(.+)-rivens$/.exec(k);
    if (m) olds.push(m[1]);
  }
  const live = rivenScopes();
  const roster = new Set(((META && META.weapons) || []).map((w) => w.id));
  const bySlug = new Map();
  for (const sc of live) bySlug.set(rivenSlug(sc), sc);
  // THE TOKEN IS LOOKED UP, NOT PARSED. Three key shapes have existed and no
  // pattern can tell them apart — a migration that tried matched the key it
  // WROTE as well as the one it read, moved every good list onto a dead key and
  // deleted the original. A token nothing answers to keeps its cards.
  const resolve = (token) => {
    if (live.has(token)) return token;                 // already a scope
    if (roster.has(token)) return rivenScope(token);   // the pre-family shape
    return bySlug.get(token) || token;                 // the slugged one, or itself
  };
  const read = (k) => {
    try { return JSON.parse(localStorage.getItem(k) || "[]") || []; } catch (_) { return []; }
  };
  const all = read(KEY);
  let touched = olds.length > 0;
  const same = (p, q) => q.name === p.name
    && JSON.stringify(q.state) === JSON.stringify(p.state);
  // WHOSE BUILDS POINTED AT THIS CARD BY NAME: the one weapon whose list is
  // moving when the token names one, and otherwise the family it resolves to.
  const owners = (token, scope) => (roster.has(token)
    ? [token]
    : ((META && META.weapons) || []).filter((w) => rivenScope(w.id) === scope).map((w) => w.id));
  for (const token of olds) {
    const scope = resolve(token);
    for (const p of read(`wfsim-customs-${token}-rivens`)) {
      // THE SAME CARD FROM TWO OLD KEYS IS ONE CARD: a player who built the
      // Burston's and the Prime's separately built one riven, and both keys
      // resolve to the same scope now.
      const twin = all.find((q) => (q.scope || "") === scope && same(p, q));
      if (twin) {
        if (twin.id) repointRivenInBuilds(owners(token, scope), p.name, twin.id);
        continue;
      }
      const id = p.id || newRivenId(all);
      if (!p.id) repointRivenInBuilds(owners(token, scope), p.name, id);
      all.push({ ...p, id, scope });
    }
    localStorage.removeItem(`wfsim-customs-${token}-rivens`);
    // WHICH CARD IS OPEN stays scoped, and it is the one thing here that may
    // safely miss: the worst a stale pointer does is open nothing.
    const from = `wfsim-custom-open-${token}-rivens`;
    const to = `wfsim-custom-open-${scope}-rivens`;
    const open = localStorage.getItem(from);
    if (open !== null && from !== to) {
      if (localStorage.getItem(to) === null) localStorage.setItem(to, open);
      localStorage.removeItem(from);
    }
  }
  // …AND THE CARDS ALREADY IN THE ONE LIST, which is every card once the loop
  // above has run and the whole store on a second visit. A card with no id
  // predates identities and its scope's builds still name it.
  for (const p of all) {
    if (p.id) continue;
    p.id = newRivenId(all);
    repointRivenInBuilds(owners("", p.scope || ""), p.name, p.id);
    touched = true;
  }
  if (touched) localStorage.setItem(KEY, JSON.stringify(all));
}

// Parsed lists, memoised on the RAW STRING. The stored text IS the
// invalidation — nothing to keep in sync, and a stale read is impossible.
// Worth having because `gainKey()` resolves a whole scenario and is called
// from a sort comparator, i.e. O(n log n) times per picker render.
const presetParseCache = new Map();
const loadPresetWhole = (d, w) => {
  const k = presetListKey(d, w);
  let raw;
  try { raw = localStorage.getItem(k); } catch (_) { return []; }
  const hit = presetParseCache.get(k);
  if (hit && hit.raw === raw) return hit.list;
  let list = [];
  try { const p = JSON.parse(raw); if (Array.isArray(p)) list = p; } catch (_) { /* empty */ }
  presetParseCache.set(k, { raw, list });
  return list;
};
/// WHAT THIS WEAPON CAN SEE. Every other collection is a whole key; a riven's
/// store holds the roster's and the QUERY is what makes it this weapon's, which
/// is the whole point of filing it by what it IS. Callers are unchanged: they
/// asked for "this weapon's list" before and they still get one.
const loadPresetList = (d, w) => {
  const list = loadPresetWhole(d, w);
  if (d !== RIVENS) return list;
  const scope = rivenScope(w ?? presetWeapon());
  return list.filter((p) => (p.scope || "") === scope);
};
// The first "<thing> N" this collection does not already hold. Shared by both
// kinds — naming a new item is the same problem whatever it is called.
const freeName = (ps, mk) => {
  for (let n = 1; ; n++) { const nm = mk(n); if (!ps.some((p) => p.name === nm)) return nm; }
};

/// WHAT A COLLECTION SHEDS when it will not fit, in the order of what it costs
/// the reader to lose. Each stage is applied, the write retried, and the first
/// one that fits wins.
///
/// localStorage is a few megabytes and this app stores MEASUREMENTS in it, so
/// "it does not fit" is a state a long-lived install reaches. Throwing there is
/// the worst outcome available: the edit is on screen and never persisted.
/// THE ACTIVE PRESET'S RESULT IS NEVER SHED: it is what the write is usually
/// FOR, and dropping it throws away the run that just finished — after which
/// the first thing to re-read the collection hides the whole block.
///
/// A REPLAY NEVER REACHES THE DISK.
///
/// It is the biggest thing this app produces by a wide margin — 600 frames of
/// debuff series per followed body — and the ONE part of a result a button
/// regenerates. Stripped on the way to `localStorage` and kept in `resultMem`
/// for the session, which makes the stored footprint of a measurement a few
/// kilobytes of summary and BOUNDED. Not the shed being tidy: shedding responds
/// to a full disk, this is why it stops being full.
const stripReplays = (ps) => ps.map((x) => (x && x.lastResult && x.lastResult.r
  && x.lastResult.r.replay
  ? { ...x, lastResult: { ...x.lastResult, r: { ...x.lastResult.r, replay: null } } }
  : x));

/// EVERY WFSIM KEY, because a quota is the ORIGIN's and a shed was the list's.
///
/// This is what the first version got wrong. Writing
/// `wfsim-presets-phantasma_prime-builder-builds` would fail on a disk filled
/// by `wfsim-presets-boar_prime-builder-builds`, shed its own list down to
/// nothing, still not fit, and give up — while the space it needed sat in
/// another weapon's key that nothing was ever going to look at. So a shed
/// sweeps the ORIGIN, and the list being written is simply the last one it is
/// allowed to touch.
const otherPresetKeys = (skip) => Object.keys(localStorage)
  .filter((k) => k.startsWith("wfsim-presets-") && k !== skip);

/// Drop `lastResult` from every OTHER collection, oldest first, until the write
/// fits. A card falls back to "not measured yet", which is true and is one
/// click from false — and it is the right thing to lose, because it is a
/// measurement of a build the reader is not looking at.
function shedOtherResults(skip) {
  const rows = [];
  for (const k of otherPresetKeys(skip)) {
    let list = null;
    try { list = JSON.parse(localStorage.getItem(k)); } catch (_) { continue; }
    if (!Array.isArray(list)) continue;
    list.forEach((x, i) => {
      if (x && x.lastResult) rows.push({ k, i, at: x.lastResult.at || 0, list });
    });
  }
  rows.sort((a, b) => a.at - b.at);
  return rows.map((row) => () => {
    row.list[row.i].lastResult = null;
    try { localStorage.setItem(row.k, JSON.stringify(row.list)); } catch (_) {}
  });
}

/// …and the ladder for the list actually being written, outside in. The active
/// preset's own result is the LAST thing to go: it is usually what the write is
/// FOR, and dropping it means the run that just finished was thrown away by the
/// act of saving it.
const PRESET_SHED = [
  (ps, active) => ps.forEach((x) => { if (x.name !== active) x.lastResult = null; }),
  (ps, active) => ps.forEach((x) => { if (x.name === active) x.lastResult = null; }),
];

/// A ONE-LINE NOTICE, in the page. No native dialog — `alert` is blocked in the
/// owner's browser, and a message nobody can see is not a message. It replaces
/// itself, so a repeated failure is one line rather than a stack.
function noteInline(msg) {
  let el = document.getElementById("page-note");
  if (!el) {
    el = document.createElement("div");
    el.id = "page-note";
    el.className = "page-note";
    el.addEventListener("click", () => el.remove());
    document.body.appendChild(el);
  }
  el.textContent = msg;
}

const storePresetList = (d, ps, w) => {
  const weapon = w ?? presetWeapon();
  const key = presetListKey(d, weapon);
  // A RIVEN WRITE IS A REPLACEMENT OF THIS SCOPE'S SLICE, not of the file: the
  // caller was handed this weapon's cards and hands them back, and every other
  // family's sit in the same list untouched. The tag is re-applied on the way
  // in so a card copied from another weapon lands under the one it is being
  // saved for.
  if (d === RIVENS) {
    const scope = rivenScope(weapon);
    ps = loadPresetWhole(d, weapon).filter((p) => (p.scope || "") !== scope)
      .concat(ps.map((p) => ({ ...p, scope })));
  }
  const isQuota = (e) => !!e && (e.name === "QuotaExceededError"
    || e.name === "NS_ERROR_DOM_QUOTA_REACHED" || e.code === 22 || e.code === 1014);
  // The REPLAY never travels. `ps` itself keeps it, because the caller and
  // `resultMem` are still holding that object and the panel reads it.
  const flat = stripReplays(ps);
  // UNDO COMPARES LIKE WITH LIKE. Its "is this a no-op write" test is against
  // what is ON THE DISK, which now never has a replay — so a `ps` that still
  // carried one would differ from the stored copy every single time and push a
  // step that undoes nothing.
  recordUndo(d, weapon, flat);
  const put = () => {
    try {
      localStorage.setItem(key, JSON.stringify(flat));
      return true;
    } catch (e) {
      if (!isQuota(e)) throw e;
      return false;
    }
  };
  if (put()) return;
  // OTHER COLLECTIONS FIRST — see `shedOtherResults`. A quota is the origin's,
  // so the space this write needs is usually not in this write's list.
  for (const drop of shedOtherResults(key)) {
    drop();
    if (put()) return;
  }
  for (const shed of PRESET_SHED) {
    shed(flat, activePreset);
    if (put()) return;
  }
  // NOTHING LEFT TO DROP. Say so where the reader is rather than throwing into a
  // console nobody has open: the edit is on screen and it is not saved, and that
  // is the one thing they need to know.
  noteInline(tr("this browser's storage is full - the change is on screen but was not saved"));
};

// ---- UNDO — Ctrl+Z across every preset collection ----------------------
//
// Presets AUTO-SAVE, which is exactly what makes a slip expensive: a cleared
// tier, a deleted preset, a mis-aimed import is written the instant it
// happens and there is no save button to not press. Every
// collection — builds, scenarios, searches, rivens — writes through
// `storePresetList`, so that one call is where a "before" can be taken, and
// one stack covers the whole page rather than four.
//
// What is remembered is the whole COLLECTION plus which preset was active,
// not a field-level diff: a delete and an edit are then the same kind of
// event, and undoing either is a plain write-back.
const UNDO_LIMIT = 60;
// Two consecutive EDITS to the same collection within this window are ONE
// step — the auto-save fires per settled edit, and a Ctrl+Z that walked back
// through every keystroke would not be an undo, it would be a rewind. Adding,
// deleting, renaming or importing a preset never coalesces, however fast it
// follows: those are the slips worth one Ctrl+Z each, and folding a delete
// into the edit before it would undo both or neither.
const UNDO_COALESCE_MS = 900;
let undoStack = [], redoStack = [], undoSuspended = false;

const presetSnapshotOf = (d, w) => ({
  domain: d, weapon: w,
  list: localStorage.getItem(presetListKey(d, w)),
  active: localStorage.getItem(presetActiveKey(d, w)),
  at: Date.now(),
});

function recordUndo(d, w, next) {
  if (undoSuspended) return;
  const before = presetSnapshotOf(d, w);
  if (before.list === null) return;          // nothing existed to go back to
  // A no-op write is not a step. Switching weapons re-applies and re-saves
  // every collection, and a stack full of those would make the first Ctrl+Z
  // do nothing visible.
  if (before.list === JSON.stringify(next)) return;
  const names = (l) => (l || []).map((p) => p.name).join("\u0000");
  let structural = true;
  try { structural = names(JSON.parse(before.list)) !== names(next); } catch (_) {}
  const top = undoStack[undoStack.length - 1];
  // Same collection, still mid-gesture, same presets: keep the OLDER "before".
  if (!structural && top && top.domain === d && top.weapon === w
      && before.at - top.at < UNDO_COALESCE_MS) {
    top.at = before.at;
    return;
  }
  undoStack.push(before);
  if (undoStack.length > UNDO_LIMIT) undoStack.shift();
  redoStack = [];   // a new edit forks the timeline
}

// Each domain's "make the page show this again". The bars already own these
// three operations; this is the same trio the preset bar is built from.
function presetDoc(d) {
  if (d === BUILDS) return {
    setActive: (n) => { activePreset = n; },
    apply: (st) => restoreState(st, presetWeapon()),
    rerender: renderPresetBar,
  };
  if (d === SCENARIOS) return {
    setActive: (n) => { activeScenario = n; },
    apply: applyScenario,
    rerender: renderScenarioBar,
  };
  if (d === OPT_DOMAIN) return {
    setActive: (n) => { activeOptPreset = n; },
    apply: applyOptPreset,
    rerender: renderOptPresetBars,
  };
  if (d === RIVENS) return {
    setActive: (n) => { activeRiven = n; },
    // An undo can land on a collection that is now empty (the last riven
    // deleted) — renderRivens is the one that decides between the list and
    // the editor, so it does the applying too.
    apply: () => { riven = null; },
    rerender: () => { renderRivens(); pruneDanglingRivens(); },
  };
  return null;
}

// Write a remembered collection back and make the page reflect it.
function restorePresetSnapshot(s) {
  undoSuspended = true;
  try {
    if (s.list === null) localStorage.removeItem(presetListKey(s.domain, s.weapon));
    else localStorage.setItem(presetListKey(s.domain, s.weapon), s.list);
    if (s.active === null) localStorage.removeItem(presetActiveKey(s.domain, s.weapon));
    else localStorage.setItem(presetActiveKey(s.domain, s.weapon), s.active);
    // A step taken on ANOTHER weapon is restored in storage but not applied:
    // yanking the editor to a weapon the user has since left would be a
    // second surprise on top of the one being undone.
    if (s.weapon !== presetWeapon()) return;
    const doc = presetDoc(s.domain);
    const list = JSON.parse(s.list || "[]");
    // WHAT NAMES AN ENTRY is its name in every collection but one: a riven's
    // identity is its own id, because its name is a label a player edits.
    const key = (p) => (s.domain === RIVENS ? p && p.id : p && p.name) || "";
    const active = list.find((p) => key(p) === s.active) || list[0];
    if (!doc || !active) return;
    doc.setActive(key(active));
    whileApplying(() => doc.apply(active.state));   // a restore is not an edit
    doc.rerender();
  } finally {
    undoSuspended = false;
  }
}

// The stack is ONE timeline, but a button lives on ONE collection, so it acts
// on that collection's most recent step: undo has to be visible, not only a
// shortcut. Clicking ↶ on the riven toolbar undoing a
// scenario edit would be the shortcut's behaviour wearing a button's clothes.
// Ctrl+Z stays global — that is what a global key should mean.
//
// Filtering is safe because every entry is a whole snapshot of ONE collection:
// restoring an older one for a domain does not depend on what other domains
// did in between.
const lastIn = (stack, d, w) => {
  for (let i = stack.length - 1; i >= 0; i--) {
    if (stack[i].domain === d && stack[i].weapon === w) return i;
  }
  return -1;
};
const canUndoIn = (d) => lastIn(undoStack, d, presetWeapon()) >= 0;
const canRedoIn = (d) => lastIn(redoStack, d, presetWeapon()) >= 0;

function stepIn(from, to, d, label) {
  const w = presetWeapon();
  const i = lastIn(from, d, w);
  if (i < 0) return;
  const step = from.splice(i, 1)[0];
  to.push(presetSnapshotOf(d, w));
  restorePresetSnapshot(step);
  presetToast(`${tr(label)} · ${tr(PRESET_LABELS[d] || d)}`);
}
const undoIn = (d) => stepIn(undoStack, redoStack, d, "undone");
const redoIn = (d) => stepIn(redoStack, undoStack, d, "redone");

// The pair of buttons, for any bar that wants to show them.
const undoButtons = (d) =>
  `<span class="pundo">` +
  `<button class="pop pundo-u" ${canUndoIn(d) ? "" : "disabled"} title="${escHtml(tr("undo (Ctrl+Z)"))}">↶</button>` +
  `<button class="pop pundo-r" ${canRedoIn(d) ? "" : "disabled"} title="${escHtml(tr("redo (Ctrl+Shift+Z)"))}">↷</button>` +
  `</span>`;

// Wire them wherever they were drawn.
function wireUndoButtons(host, d) {
  const u = host.querySelector(".pundo-u"), r = host.querySelector(".pundo-r");
  if (u) u.onclick = (e) => { e.stopPropagation(); undoIn(d); };
  if (r) r.onclick = (e) => { e.stopPropagation(); redoIn(d); };
}

function undoPreset() {
  const step = undoStack.pop();
  if (!step) return presetToast(tr("nothing to undo"));
  redoStack.push(presetSnapshotOf(step.domain, step.weapon));
  restorePresetSnapshot(step);
  presetToast(`${tr("undone")} · ${tr(PRESET_LABELS[step.domain] || step.domain)}`);
}

function redoPreset() {
  const step = redoStack.pop();
  if (!step) return presetToast(tr("nothing to redo"));
  undoStack.push(presetSnapshotOf(step.domain, step.weapon));
  restorePresetSnapshot(step);
  presetToast(`${tr("redone")} · ${tr(PRESET_LABELS[step.domain] || step.domain)}`);
}

const PRESET_LABELS = {
  "builder-builds": "Builds",
  "simulator-scenarios": "Scenarios",
  optimizer: "Searches",
  rivens: "Rivens",
};

// Inline feedback, never a native dialog (those are blocked in the owner's
// browser). It has to say WHICH collection moved: the shortcut is global and
// the slip may have been two tabs ago.
let toastTimer = null;
function presetToast(msg) {
  let el = $("toast");
  if (!el) {
    el = document.createElement("div");
    el.id = "toast";
    document.body.appendChild(el);
  }
  el.textContent = msg;
  el.classList.add("on");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove("on"), 2200);
}

// Ctrl/Cmd+Z, and Ctrl+Shift+Z / Ctrl+Y to come back. Never while a text
// field has focus: there the browser's own undo is the one being asked for,
// and stealing it would make renaming a preset a trap.
document.addEventListener("keydown", (e) => {
  if (!(e.ctrlKey || e.metaKey) || e.altKey) return;
  const k = e.key.toLowerCase();
  if (k !== "z" && k !== "y") return;
  // The event's own target first: that is where a real keystroke lands, and
  // it is true even when the page itself does not hold focus.
  const el = (e.target && e.target.nodeType === 1 ? e.target : null) || document.activeElement;
  if (el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.isContentEditable)) return;
  e.preventDefault();
  if (k === "y" || e.shiftKey) redoPreset(); else undoPreset();
});


// One-time move of the pre-module storage keys.
(function migratePresetKeys() {
  try {
    // Targets are the WEAPON-LESS keys of the previous scheme; migrateWeaponScope()
    // below moves those onto a weapon once META has told us which one.
    const moves = {
      "wfsim-presets": "wfsim-presets-builder-builds",
      "wfsim-active-preset": "wfsim-preset-active-builder-builds",
      "wfsim-opt-mods-presets": "wfsim-presets-optimizer-mods",
      "wfsim-opt-arc-presets": "wfsim-presets-optimizer-arcanes",
      "wfsim-opt-evo-presets": "wfsim-presets-optimizer-evolutions",
    };
    Object.entries(moves).forEach(([from, to]) => {
      const v = localStorage.getItem(from);
      if (v !== null && localStorage.getItem(to) === null) localStorage.setItem(to, v);
      localStorage.removeItem(from);
    });
    const oldActives = JSON.parse(localStorage.getItem("wfsim-opt-active") || "null");
    if (oldActives) {
      Object.entries({ mods: "optimizer-mods", arcs: "optimizer-arcanes", evos: "optimizer-evolutions" }).forEach(([k, d]) => {
        const to = "wfsim-preset-active-" + d;
        if (oldActives[k] && localStorage.getItem(to) === null) localStorage.setItem(to, oldActives[k]);
      });
      localStorage.removeItem("wfsim-opt-active");
    }
  } catch (_) {}
})();

// One-time rewrite of the EVOLUTION ids that dropped their ad-hoc
// abbreviations for full weapon names. Saved builds store the per-tier selection and the
// optimizer's scope stores its option sets, so both collections carry ids
// that would otherwise silently stop resolving.
(function migrateEvolutionIds() {
  try {
    const fix = (id) => (typeof id === "string"
      ? id.replace(/^dt_/, "dual_toxocyst_").replace(/^lae_/, "laetum_")
      : id);
    const rewriteKeys = (obj) => {
      if (!obj || typeof obj !== "object") return obj;
      const out = {};
      for (const [k, v] of Object.entries(obj)) out[fix(k)] = v;
      return out;
    };
    // Build presets: state.evoSel = { tier: id|null }. The domain names
    // are literals here on purpose: this block runs BEFORE the BUILDS
    // constant is initialised, and a temporal-dead-zone throw would be
    // swallowed by the catch, silently skipping the migration.
    const buildsDomain = "builder-builds";
    const builds = loadPresetList(buildsDomain);
    let touched = false;
    builds.forEach((p) => {
      const sel = p.state && p.state.evoSel;
      if (!sel) return;
      Object.keys(sel).forEach((t) => {
        const nv = fix(sel[t]);
        if (nv !== sel[t]) { sel[t] = nv; touched = true; }
      });
    });
    if (touched) storePresetList(buildsDomain, builds);
    // Optimizer evolution presets: state.evos = { tier: { id: mark } }
    const evoDomain = "optimizer-evolutions";
    const evos = loadPresetList(evoDomain);
    let touched2 = false;
    evos.forEach((p) => {
      const tiers = p.state && p.state.evos;
      if (!tiers) return;
      Object.keys(tiers).forEach((t) => {
        const before = JSON.stringify(tiers[t]);
        tiers[t] = rewriteKeys(tiers[t]);
        if (JSON.stringify(tiers[t]) !== before) touched2 = true;
      });
    });
    if (touched2) storePresetList(evoDomain, evos);
  } catch (_) {}
})();

// The builder module's build presets — domain "builder-builds". A build
// preset captures the WHOLE configuration: weapon, mod slots (mod id +
// polarity + rank), arcane + rank, and the per-tier evolution selection.
const BUILDS = "builder-builds";

/// WHAT A BUILD CONSISTS OF, declared once.
///
/// Five things produce a build state — the live page, "+ new", a board row, a
/// share link, an optimizer result — and `restoreState` fills a MISSING axis
/// with the weapon's own default, which is right for a blank build and for a
/// preset written before an axis existed. That is also why forgetting an axis
/// is invisible: a producer that meant "the default" and one that never heard
/// of the axis hand over the same object.
///
/// The same bug arrived FOUR times — `mode` missing from the board submission,
/// `valence` from the worker's table, both from the share tuple, `valence` from
/// the optimizer's "+ add", which a player measured at 22.34 KPM against 17.44.
/// So every producer NAMES every axis, `undefined` stays a legal value meaning
/// "the weapon's default", and adding a row here breaks all five at once.
/// …and the LIST itself is not declared here. `engine::builds::BUILD_AXES` is
/// the one place a build's axes are named, and it arrives in `/api/meta`; this
/// table only says which of THIS page's state keys carry each of them, because
/// the spellings are the page's own and renaming them would migrate every
/// stored preset. `scripts/check_build_axes.mjs` asserts the two agree, so an
/// axis added in Rust cannot stay invisible here.
const BUILD_STATE_KEYS = [
  { axis: "mods", keys: ["slots"] },
  { axis: "evolutions", keys: ["evoSel"] },
  { axis: "arcanes", keys: ["arcane"] },
  { axis: "arcane_ranks", keys: ["arcaneRank"] },
  { axis: "mode", keys: ["mode"] },
  { axis: "valence", keys: ["valence"] },
  { axis: "assembly", keys: ["assembly"] },
  // A RIVEN IS A MOD: its id sits in a slot like any other, and the item
  // itself lives in its own collection rather than inside a build. So the axis
  // is covered, by `slots`, and saying so is the point — an axis with no entry
  // at all is the thing the check is looking for.
  { axis: "rivens", keys: ["slots"] },
];
const BUILD_AXES = [...new Set(BUILD_STATE_KEYS.flatMap((a) => a.keys))];

/// A build state, from a producer that has to account for every axis.
///
/// It THROWS rather than filling in, because there is no data that can reach
/// it: a missing axis is a producer somebody wrote without the table in front
/// of them, so it fails on the first click of the session that introduced it
/// (`scripts/check_opt_to_build.mjs` is the one that forces it).
function buildState(weapon, axes) {
  const missing = BUILD_AXES.filter((k) => !(k in axes));
  if (missing.length) {
    throw new Error(`build state is missing ${missing.join(", ")} — see BUILD_AXES`);
  }
  return { weapon, ...axes };
}

function snapshotState() {
  return buildState($("weapon").value, {
    evoSel: { ...evoSel },
    arcane: arcanes,
    arcaneRank: arcaneRanks,
    slots: slots.map((s) => ({ mod: s.mod, pol: s.pol, rank: s.rank })),
    mode,
    // The VALENCE, for the same reason `mode` is here: it is part of what this
    // build IS, and two builds of one weapon may differ only in it.
    valence: { ...valence },
    // THE PARTS, for the same reason: on a Kitgun they are the stat line, and
    // `null` on everything else, which is what "this weapon has none" means.
    assembly: assembly ? { ...assembly } : null,
    // NO `sim` FIELD. A build carrying a snapshot of the fight is a snapshot
    // `restoreState` then applies, so picking a build silently rewrites the
    // scenario you are working in. The scenario is INDEPENDENT: nothing
    // outside `simulator-scenarios` writes it.
    //
    // Nothing is lost. "What this build was last measured under" was never
    // this field's job — `lastResult.key` is that record, it lives outside
    // `state`, and it is what makes a stale result show as stale.
  });
}

/// Create any BOARD riven this state wears that the reader does not have yet.
///
/// Returns nothing and writes at most once: the riven's name is derived from
/// its shape, so a row taken twice reuses the first copy rather than stacking
/// `… 2`, `… 3` behind it — which is the whole difference between this and the
/// share link's import, where two links legitimately carry two different
/// people's rivens that happen to share a name.
function materialiseBoardRivens(st) {
  const want = (st.slots || [])
    .map((s) => s && s.mod)
    .filter((id) => isRivenId(id) && boardRivenDefs[id]);
  if (!want.length) return;
  const ps = loadPresetList(RIVENS);
  let added = 0;
  for (const id of want) {
    // THE BOARD ROW'S RIVEN KEEPS THE IDENTITY THE BUILD ALREADY NAMES. Its id
    // is derived from the SHAPE (`boardRivenName`), so it is deterministic —
    // which is what makes taking the same row twice reuse the first copy, and
    // what lets the slot the build arrived with go on resolving.
    const key = id.slice(RIVEN_PREFIX.length);
    if (ps.some((p) => p.id === key)) continue;
    ps.push({ id: key, name: key, savedAt: Date.now(),
      state: boardRivenState(boardRivenDefs[id]) });
    added++;
  }
  if (!added) return;
  storePresetList(RIVENS, ps);
  refreshRivenNames();
}

// Apply a saved state. `weapon` is the weapon it belongs to — pass it and the
// payload's own `st.weapon` is IGNORED.
//
// That parameter is the whole anti-crossing design. A preset's owner is already
// decided by its storage key (`wfsim-presets-<weapon>-<domain>`), so carrying a
// weapon inside the payload too gave the same fact two homes — and every
// crossing bug was those two disagreeing: a payload saying `laetum` under Dual
// Toxocyst's key dragged the editor (and the URL, below) to Laetum. Repairing
// the stored data only chased the symptom; not READING it makes crossing
// structurally impossible, whatever a payload happens to contain.
//
// Only the language-switch stash omits the argument: it restores the whole page
// including which weapon was open, so there the payload IS the authority.
function restoreState(st, weapon) {
  const w = weapon || (st && st.weapon);
  if (!st || !weaponInfo(w)) return;
  $("weapon").value = w;
  // Keep the route honest when the restore changes weapon (the stash case);
  // for a preset `w` is already the current weapon, so this is a no-op.
  if (!document.querySelector(".config-page").hidden) {
    history.replaceState(null, "", weaponModPath(w));
  }
  applyWeapon(w, null); // resets pool/innate/visibility
  // A BOARD ROW'S RIVEN IS CREATED HERE, and only here — the moment a build
  // that wears one is actually taken. Without it the loop below would drop the
  // slot as "an id gone from the pool" and hand back a seven-mod build that
  // scores nothing like the row it came from.
  //
  // IDEMPOTENT: the name is derived from the shape, so taking the same row
  // twice finds the riven it made the first time.
  materialiseBoardRivens(st);
  (st.slots || []).forEach((s, i) => {
    if (i >= slots.length) return;
    slots[i].mod = s.mod && modById(s.mod) ? s.mod : null; // drop ids gone from the pool
    slots[i].pol = s.pol ?? null;
    slots[i].rank = s.rank ?? null;
  });
  evoSel = { 1: null, 2: null, 3: null, 4: null, ...(st.evoSel || {}) };
  // ONTO A DEFAULT, never onto whatever the last build was playing. A preset
  // written before this field existed is played the way the arsenal plays it,
  // which is exactly what the board's own migration does with a mode-less
  // submission — and what keeps a builtin board build showing the mode it was
  // MEASURED in rather than the one you happened to be in.
  mode = defaultMode(w, st.mode);
  // ONTO A DEFAULT, never onto the last build's — a valence is a statement
  // about one weapon and nothing crosses between them. `defaultValence` also
  // drops an element this weapon's spec does not offer, which is what a preset
  // copied across weapons carries.
  valence = defaultValence(w, st.valence);
  // ONTO THIS WEAPON'S DEFAULT, never onto the last build's parts — a grip
  // belongs to one slot and a preset copied across weapons carries the other
  // one's. `defaultAssembly` also drops a part this entry cannot take, which is
  // the same repair the server does on the wire.
  assembly = defaultAssembly(w, st.assembly);
  // THE RANKS FOLLOW THE ARCANE, not the index — see `seatArcanes`. Reading
  // them positionally would put a Kitgun arcane's rank on the ordinary seat
  // the moment one of them moved.
  const seat = seatArcanes(w, st.arcane);
  arcanes = seat.ids;
  const rawRanks = Array.isArray(st.arcaneRank) ? st.arcaneRank
    : st.arcaneRank == null ? [] : [st.arcaneRank];
  arcaneRanks = seat.from.map((src) => (src < 0 ? null : rawRanks[src] ?? null));
  // The scenario is NOT restored: it belongs to `simulator-scenarios` and a
  // build has no opinion about it. An old preset may still carry `st.sim`;
  // it is ignored rather than migrated, because reading it back is the exact
  // behaviour this removed.
  // A BOARD ROW IS A BUILD, NOT A LAYOUT: it carries mods and no polarities,
  // so restoring it verbatim shows a legal build as an impossible one — full
  // drain, 91/60 in red. The cheapest legal layout is planned on the spot.
  //
  // IT LIVES HERE because TWO callers restore a build — the build bar, and
  // `initPresets` on boot — so a plan living in the bar's `apply()` alone
  // shows the wrong Forma on a page whose active build is a benchmark build,
  // until you click something. Both
  // callers set the active preset BEFORE restoring, which is what makes
  // the question answerable here.
  //
  // Nothing of yours is at risk: a benchmark build is read-only and has no
  // hand-set polarity to overwrite.
  if (officialBuildActive()) autoForma();
  renderAssembly();
  renderMods(); renderArcanes(); renderEvo(); renderMode(); renderValence(); renderSim(); refreshPanel();
  renderStoredSimResult(); // the simulator shows THIS preset's last test
}

// Kill score PER MINUTE. The score is whole kills plus the fraction of the
// current target's pool already drained, so it grows with the engagement —
// dividing by the clock is what makes two runs of different length
// comparable, exactly as DPS does for damage.
const kpm = (score, duration) => (duration > 0 ? ((score || 0) * 60) / duration : 0);

/// WHAT A SCENARIO IS JUDGED BY — resolved against the table `/api/meta`
/// publishes (`engine::metrics`), never asked as "is it dps".
///
/// THAT QUESTION IS THE FAILURE MODE. `metric === "dps" ? … : KPM` reads a
/// third metric as kills per minute — silently, in the units of a different
/// question — and it was written eight times across this file. A metric added
/// to the engine's table reaches the Measure control, the headline's unit, the
/// gain scan's label and the board strip without any of them naming it.
///
/// AN UNKNOWN ID FALLS BACK TO THE DEFAULT rather than to nothing, because this
/// runs while drawing: `parse_fight` refuses one at the door, so anything that
/// reaches here is a metric this build knows or a scenario that cannot run.
const metricOf = (id) => {
  const all = META.metrics || [];
  return all.find((m) => m.id === (id || META.metric_default))
    || all.find((m) => m.id === META.metric_default)
    || METRIC_FALLBACK;
};
/// The run's number IN THAT METRIC. `score` off the wire is kill PROGRESS over
/// the whole engagement, so a per-minute metric turns it into a rate; a metric
/// that is already a rate reads its own field and is left alone.
const metricValue = (m, r) => {
  const raw = (r || {})[m.field] || 0;
  return m.per_minute ? kpm(raw, (r || {}).duration) : raw;
};
/// Its unit, translated. The label is the engine's; the translation is ours.
const metricLabel = (m) => tr(m.label);

const escHtml = (s) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

// Decimal formatting with a SIGNIFICANCE floor: two
// decimals normally, but a very small number grows decimals until it
// carries 2 significant digits — 0.0085 stays 0.0085 instead of
// collapsing to 0.01. Used for every score/percentage in the results.
// EXACT ZERO keeps the plain "0.00" — only a nonzero-but-tiny value grows
// decimals (log10(0) is -Infinity, so zero must short-circuit first).
const sig2 = (x, min = 2) => {
  const v = Number(x);
  if (!Number.isFinite(v) || v === 0) return (0).toFixed(min);
  const a = Math.abs(v);
  const need = a >= 1 ? min : Math.max(min, 1 - Math.floor(Math.log10(a)));
  return v.toFixed(need);
};
const pct2 = (x) => sig2((Number(x) || 0) * 100) + "%";

// One-time move of the weapon-LESS preset lists onto a weapon. They were
// written before presets were scoped, so they belong to whatever the user
// was last looking at — which we cannot know. They go to the weapon that
// is active when the migration runs (the one being restored on this load),
// and everything else starts empty. Nothing is lost: "⇤ import" reaches
// any weapon's presets from any other.
// The optimizer's three scope domains merged into one on 2026-08-02; the old
// names stay listed so a browser arriving from before the weapon-scope move
// still lands its data where migrateOptPresets can find it.
const PRESET_DOMAINS = ["builder-builds", "optimizer", "optimizer-mods",
  "optimizer-arcanes", "optimizer-evolutions", "simulator-scenarios"];
// The SIMULATOR's collection: one saved fight — enemy, technique, measurement.
// Its own domain because a build is tested against SEVERAL of them, and
// because the marginal-gain scan needs to name which one it ran under. The
// build preset keeps carrying its own `sim` (a build remembers what it was
// last tested with); this is the reusable library beside it.
const SCENARIOS = "simulator-scenarios";
let activeScenario = "";
function migratePresetsToWeaponScope() {
  const w = presetWeapon();
  if (!w) return;
  PRESET_DOMAINS.forEach((d) => {
    // A SHARED DOMAIN IS ALREADY AT ITS FINAL KEY. This migration's whole job is
    // to move a weapon-LESS key under a weapon, which is precisely what the
    // scenario list must not have done to it — it would file the shared list
    // under whichever weapon happened to be open and take it away from every
    // other one, on every load.
    if (isSharedDomain(d)) return;
    [["wfsim-presets-" + d, presetListKey(d, w)],
     ["wfsim-preset-active-" + d, presetActiveKey(d, w)]].forEach(([from, to]) => {
      const v = localStorage.getItem(from);
      if (v === null) return;
      // RESCOPE while moving. The legacy list was global, so its entries carry
      // whatever weapon was current when each was saved — filing them verbatim
      // under `w` leaves a preset that yanks the editor to another weapon the
      // moment it loads. Only the preset LIST needs this; the active-name key
      // is a bare string.
      let out = v;
      if (from.startsWith("wfsim-presets-")) {
        try {
          out = JSON.stringify(JSON.parse(v).map((p) =>
            p && p.state ? { ...p, state: { ...p.state, weapon: w } } : p));
        } catch (_) { /* unparseable: move it as-is, initPresets repairs it */ }
      }
      if (localStorage.getItem(to) === null) localStorage.setItem(to, out);
      localStorage.removeItem(from);
    });
  });
}

// Every weapon that has at least one stored preset in `domain`, for the
// import picker: [{ id, name, presets }]. Iterates META rather than parsing
// key strings — weapon ids and domains both contain separators.
function presetSources(domain, exceptWeapon) {
  return (META ? META.weapons : [])
    .filter((w) => w.id !== exceptWeapon)
    .map((w) => ({ id: w.id, name: w.name, presets: loadPresetList(domain, w.id) }))
    .filter((w) => w.presets.length);
}

// The ACTIVE preset — the one the editor is editing. Never null after
// init: the page always has ≥1 preset and is always editing one (user's
// mental model, 2026-07-28: "if no presets exist, the current state IS
// preset 1"). Restored across reloads.
let activePreset = null;

// A stored buff config outlives the RULE it was written under. A stacking buff
// opens EARNED at zero, and `syncBuffConfig` only seeds an id it has never
// seen — so a scenario saved under an open-at-full-stacks rule keeps the old
// numbers, and the current rule looks broken on exactly the builds that have
// been tested most.
//
// One-time, and it drops the whole map rather than guessing which entries were
// deliberate: `{stacks: 3}` on a 3-stack buff is what "never touched" and
// "chose the maximum" both look like, and there is no third field to tell them
// apart. Re-seeding from the server's defaults is the answer the rule change
// promised; a wrong guess about intent is not.
(function migrateBuffDefaults() {
  const FLAG = "wfsim-buff-defaults-earned";
  try {
    if (localStorage.getItem(FLAG)) return;
    Object.keys(localStorage)
      .filter((k) => /^wfsim-presets-.*-(simulator-scenarios|builder-builds)$/.test(k))
      .forEach((k) => {
        const list = JSON.parse(localStorage.getItem(k));
        if (!Array.isArray(list)) return;
        let hit = false;
        list.forEach((p) => {
          if (p.state && p.state.buffs && Object.keys(p.state.buffs).length) {
            p.state.buffs = {}; hit = true;
          }
          // Builds no longer carry a fight at all — drop the dead copy while
          // we are here rather than leaving it to be misread later.
          if (p.state && p.state.sim) { delete p.state.sim; hit = true; }
        });
        if (hit) localStorage.setItem(k, JSON.stringify(list));
      });
    localStorage.setItem(FLAG, "1");
  } catch (_) { /* a browser with no storage has nothing to migrate */ }
})();

function initPresets() {
  migratePresetsToWeaponScope();
  let ps = loadPresetList(BUILDS);
  // (The old 300-run migration lived here. It rewrote `state.sim.runs` inside
  // BUILD presets — a field nothing reads any more, because a build no longer
  // carries a copy of the fight.)
  // NOTHING IS AUTO-CREATED. A blank "build 1" per weapon opened leaves a
  // reader who browsed forty weapons owning forty builds they never made,
  // which stops being harmless the moment one page lists everything you own:
  // the page's whole answer becomes "everything", the same as no answer.
  //
  // THE RULE IT LOOKS LIKE IT BREAKS, AND DOES NOT: "the modules always have a
  // state" is about the LIVE state, which still always exists — with nothing
  // stored the builder opens on `blankBuildState()` and the simulator on an
  // official ruler, a BUILTIN that was never in this list. What is optional is
  // the SAVED entry, the contract customs have always had. A preset appears on
  // the first EDIT instead (`markPresetDirty`), so the collection means "what
  // you have worked on".
  //
  // What the blank seed was FOR is not lost: a weapon opened for the first time
  // must be a bare weapon rather than the live state of the weapon you just
  // left, and `blankBuildState()` is still what is applied below.
  const sc = loadPresetList(SCENARIOS);
  // Resolved against the JOINT list, so the official scenario can be the one
  // you left open — it is a scenario like any other to everything downstream.
  //
  // THE OFFICIAL ONE IS THE DEFAULT. This costs nothing and
  // corrects something that was quietly misleading: `defaultScenario()` is
  // ALREADY the benchmark's fight, field for field — same enemy, level 9999,
  // Steel Path, 180 s, 1000 runs, kpm, aiming, infinite ammo. "scenario 1" was
  // the ruler wearing a private name, so its number could not be compared with
  // anyone's and could not reach the board, for no reason a player could see.
  //
  // Landing on the official one instead means a first number is a COMPARABLE
  // number. Nobody's results move — it is the same fight.
  const lastSc = localStorage.getItem(presetActiveKey(SCENARIOS));
  // THE ID, like every other write to this pointer. Storing a builtin's NAME
  // here left the boot state spelled differently from every later selection —
  // and `presetId(p) === activeScenario` is false against a name, so readers
  // that resolve by id fell through to the first ruler until you touched the
  // bar once.
  activeScenario =
    presetId(scenarioNamed(lastSc))
    || presetId(builtinScenarios()[0])
    || presetId(sc[0]);
  localStorage.setItem(presetActiveKey(SCENARIOS), activeScenario);

  const here = presetWeapon();
  const last = localStorage.getItem(presetActiveKey(BUILDS));
  activePreset = presetId(buildNamed(last)) || presetId(ps[0]);
  localStorage.setItem(presetActiveKey(BUILDS), activePreset);
  // Applied under THIS weapon, never the payload's — a preset filed here
  // belongs here by definition.
  whileApplying(() => {
    // NO PRESET IS A REAL STATE, so this is the one place that says what it
    // means: a bare weapon. `blankBuildState()` was already the answer — it
    // was simply being written to disk first.
    restoreState((buildNamed(activePreset) || {}).state || blankBuildState(), here);
    if (!activePreset) notePristineBuild();
    // THE FIGHT, from its own collection — never from inside the build
    // preset, which is how picking a build comes to change the scenario. It
    // comes from the active `simulator-scenarios` entry, and this is the only
    // place the live scenario is seeded on load or on a weapon switch.
    // The scenario cannot actually reach the fallback — an official ruler is a
    // BUILTIN and there is always one — but it is written the same way so that
    // the two collections have one rule between them rather than one each.
    applyScenario((scenarioNamed(activeScenario) || {}).state || defaultScenario());
  });
  renderPresetBar();
  lockOfficialBuild();
}

// ---- Auto-save ---------------
// A preset MIRRORS the editor: every edit debounces straight into the
// active preset's stored state, so there is no save button and no
// unsaved-changes dot. Branch before experimenting with "+ new" (empty)
// or the ⧉ duplicate — the preset you leave behind keeps its content.
//
// `presetApplying` guards the other direction: loading a preset (or a
// weapon switch) re-renders everything, and those renders must NOT be
// mistaken for user edits and written back — a cross-weapon apply drops
// unknown ids, which auto-save would otherwise make permanent.
let presetApplying = 0;
function whileApplying(fn) {
  presetApplying++;
  try {
    fn();
  } finally {
    presetApplying--;
    // Renders during the apply queue their own debounced saves — drop
    // them, or the applied (possibly pruned) state writes itself back.
    clearTimeout(presetSaveTimer);
    clearTimeout(optSaveTimer);
  }
}

let presetSaveTimer = null;
/// TWO STATES ARE THE SAME STATE WHATEVER ORDER THEIR KEYS CAME IN.
///
/// `JSON.stringify` is key-ORDER sensitive, and the order is whatever order the
/// producer happened to assign in. `snapshotOpt()` and `blankOpt()` build the
/// identical object and spell it `…modes, evos…` and `…evos, modes…`, so a
/// plain stringify comparison of the two is false for every input — which made
/// the "is this still untouched" guard below always answer "touched" and gave a
/// search preset to anyone who so much as opened the optimizer tab.
const canon = (v) => {
  if (Array.isArray(v)) return v.map(canon);
  if (v && typeof v === "object") {
    return Object.fromEntries(Object.keys(v).sort().map((k) => [k, canon(v[k])]));
  }
  return v;
};
const sameState = (a, b) => JSON.stringify(canon(a)) === JSON.stringify(canon(b));

/// THE LIVE BUILD AS IT STANDS WITH NOTHING OWNED, recorded at the two moments
/// a blank is applied — the boot of a weapon nobody has built for, and the
/// delete of the last build.
///
/// It exists because `markPresetDirty` is NOT only an edit: `refreshPanel`
/// calls it, and `refreshPanel` runs from `renderMods`, `restoreState` and
/// `applyWeapon`. So with birth-on-edit, a render was enough to create a build
/// — and deleting your last one grew it straight back, on the re-render that
/// the delete itself caused.
///
/// It cannot be `sameState(snapshotState(), blankBuildState())`, which was the
/// first attempt: `blankBuildState()` is SPARSE — `slots: []`, `evoSel: {}`, no
/// mode, no valence, every one of them meaning "the weapon's own default" for
/// `restoreState` to fill in — while `snapshotState()` is the dense realized
/// state. They describe the same build and never compare equal.
///
/// So the blank is realized ONCE, through the same path every other state goes
/// through, and remembered. Derived rather than declared: an axis added
/// tomorrow is in the snapshot on the day it is added, and nobody has to be
/// told about this variable.
let pristineBuild = null;
const notePristineBuild = () => { pristineBuild = JSON.stringify(canon(snapshotState())); };
const buildIsUntouched = () =>
  pristineBuild !== null && JSON.stringify(canon(snapshotState())) === pristineBuild;

function markPresetDirty() {
  if (presetApplying) return;
  clearTimeout(presetSaveTimer);
  presetSaveTimer = setTimeout(() => {
    if (presetApplying) return;
    // An official build is not written — same rule as the official scenario,
    // and enforced in the same place. Auto-save is what would otherwise make
    // read-only a suggestion.
    if (officialBuildActive()) return;
    const ps = loadPresetList(BUILDS);
    // A PRESET IS BORN ON THE FIRST EDIT. Nothing is
    // auto-created when a weapon is opened, so this is where "a build you own"
    // begins to exist — the moment you change something.
    //
    // THE TRIGGER IS THE EXISTING DIRTY MARK AND NOT A LIST OF WHAT COUNTS.
    // Every control that edits a build already calls `markPresetDirty`, so an
    // axis added tomorrow creates a preset on the day it is added, by nobody.
    // A hand-kept list of "meaningful" edits would have to be maintained, and
    // this repo has the receipts for what happens to those — `BUILD_AXES`
    // exists because four separate hand lists each went stale once. The cost is
    // that a stray click creates a build, and that build is one row you can see
    // and delete; a missed edit is one you cannot see at all.
    if (!activePreset) {
      // Reaching here is not evidence of an edit — see `pristineBuild`.
      if (buildIsUntouched()) return;
      const name = freeName(ps, (n) => "build " + n);
      ps.push({ name, savedAt: Date.now(), state: snapshotState() });
      storePresetList(BUILDS, ps);
      activePreset = name;
      localStorage.setItem(presetActiveKey(BUILDS), name);
      renderPresetBar();
      return;
    }
    const at = ps.findIndex((p) => p.name === activePreset);
    if (at < 0) return;
    ps[at] = { ...ps[at], savedAt: Date.now(), state: snapshotState() };
    storePresetList(BUILDS, ps);
  }, 400);
}

let scenarioSaveTimer = null;
let gainRefreshTimer = null;
// The scenario's own auto-save. Same contract as the build's — the editor IS
// the preset — but a different collection, because a build is tested against
// several fights and each of them is worth keeping.
function markScenarioDirty() {
  if (presetApplying) return;
  clearTimeout(scenarioSaveTimer);
  scenarioSaveTimer = setTimeout(() => {
    if (!activeScenario || presetApplying) return;
    // NO BIRTH-ON-EDIT HERE, deliberately. The fight always resolves to
    // something — an official ruler when you own nothing — and a ruler is
    // PINNED, so there is no edit to be the first one. A scenario of your own
    // starts at "+ new", which is the only way to leave a ruler at all.
    // THE OFFICIAL SCENARIO IS NOT WRITTEN. Auto-save is what would otherwise
    // make "read-only" a lie: every edit debounces into the active preset, so
    // a disabled control is a suggestion and this line is the rule. It is also
    // why the official one is not in localStorage at all — there is nothing
    // here to write into even if this check were removed.
    if (officialScenarioActive()) return;
    const ps = loadPresetList(SCENARIOS);
    const at = ps.findIndex((p) => presetId(p) === activeScenario);
    if (at < 0) return;
    ps[at] = { ...ps[at], savedAt: Date.now(), state: snapshotScenario() };
    storePresetList(SCENARIOS, ps);
  }, 400);
  // ...and the QUICK CALC, which measures under a scenario and therefore goes
  // stale when one is edited. It waits for the same debounce because the scan
  // resolves the SAVED preset over `sim` — refreshing before the write would
  // re-measure the old fight. `ensureGains` re-checks the key, so an edit the
  // chosen scenario does not use costs nothing.
  clearTimeout(gainRefreshTimer);
  gainRefreshTimer = setTimeout(refreshGains, 450);
}

// ---- The ONE preset-bar component -------------------------------------
// Every preset bar on the page (the build bar and the optimizer's three
// scope bars) is the same template on the same document model: label +
// count, the chips (the active one carries duplicate / rename / delete;
// the last remaining preset cannot be deleted — there is always one),
// "+ new". Edits AUTO-SAVE into the active preset, so there is no save
// button and no dirty marker. "+ new" creates an EMPTY preset instantly
// under an auto-name ("preset N") and switches to it — no naming step; rename after via ✎. Branching an existing preset
// is the ⧉ duplicate on the active chip.
// Counts are UNLIMITED, so past PRESET_FILTER_AT chips the bar grows a
// name filter; the active chip always shows (it is the document being
// edited).
const PRESET_FILTER_AT = 10;
const presetFilters = {}; // per-bar filter text — survives re-renders, not persisted

// SELECT and COPY, lifted out of the bar so the BENCHMARK bar performs the
// same two actions rather than its own versions of them.
// They are the only two a read-only entry has, and "the copy is an ordinary
// editable preset" has to stay one behaviour — a second implementation is how
// one bar's copy comes to capture something the other's does not.
/// WHAT THE ACTIVE POINTER STORES, and it is not the label. An official entry's
/// NAME is a rank inside one ruler — "#1 · Incarnon cycle" — so the aimed board
/// and the no-aim board each have one, and `find(x => x.name === n)` returned
/// whichever came first. That is the whole of the bug where the no-aim board's
/// leader opened the AIMED board's leader instead.
///
/// `builtin` is already unique per ruler, mode and rank; a preset of your own
/// has none and is its own name. So this is the id, and `presetLabel` is what a
/// reader sees — the two were the same string until the board grew a second
/// ruler.
const presetId = (p) => (p || {}).builtin || (p || {}).name || "";
const presetLabel = (p) => (p || {}).name || "";

const pickPreset = (cfg, key) => {
  const ps = cfg.load();
  // By ID first: a name may now be shared by two rulers' rows.
  const p = ps.find((x) => presetId(x) === key) || ps.find((x) => x.name === key);
  if (!p || presetId(p) === cfg.active()) return;
  cfg.setActive(presetId(p));
  whileApplying(() => cfg.apply(p.state)); // a load is not an edit
  cfg.rerender();
};

// The copy captures the LIVE editor state and becomes the active document; the
// original keeps what auto-save last wrote into it. For a read-only entry the
// live state IS that entry, because selecting it is what put it there.
const copyActivePreset = (cfg) => {
  const ps = cfg.load();
  const base = cfg.active();
  const name = freeName(ps, (n) => base + " copy" + (n > 1 ? " " + n : ""));
  ps.push({ name, savedAt: Date.now(), state: cfg.snapshot() });
  cfg.store(ps);
  cfg.setActive(name);
  cfg.rerender();
};

// THE BENCHMARK BAR — official entries, in a bar of their own above the
// player's. Same chip styling, deliberately: it is the same
// kind of thing to pick. A different component, also deliberately: what you can
// DO differs on every count — no new, no rename, no delete, no import, no
// filter, no undo, because none of it is yours.  What is left is select and ⧉.
//
// Splitting them also removes the special-casing that had accumulated inside
// one bar (a `readonly(p)` branch in three places) and the ambiguity it caused:
// a count reading "Builds 4" when three were yours and the fourth was not.
//
// Absent when empty, and empty is ORDINARY — a weapon nobody has submitted a
// build for has no benchmark builds, and a bar with a label and no chips
// invites the question of what is missing.
function renderBenchmarkBarIn(bar, cfg) {
  if (!bar) return;
  const ps = cfg.load().filter((p) => p.builtin);
  const active = cfg.active();
  const noun = cfg.noun || "preset";
  // ONE PICK PER QUESTION: WHICH RULER, WHICH MODE, WHICH KIND, then WHICH ROW.
  // A single list holding rulers x modes x kinds x ranks cannot be scanned, and
  // searching it means knowing what a rank is a rank ON before you can ask.
  //
  // THE SHAPE NEVER MOVES — four controls, always, even where one holds a
  // single item and even on a weapon with no rows. That is what makes this a
  // RETRIEVER rather than a description of the page, and what is OPEN is said
  // by `renderCurrentBuild` instead. docs/CHECKS.md `check_build_retriever`.
  //
  // ONLY AN EMPTY LIST IS DISABLED. A control holding one item is still the way
  // that item is OPENED — picking in this bar is what loads a build — so a
  // weapon whose board has a single row would have no reachable entry point at
  // all if "nothing to choose between" meant "nothing to click".
  //
  // …AND THE FOUR ARE THE BUILD BAR'S QUESTIONS, not every bar's. This renders
  // the official SCENARIOS too, and those are one per ruler: picking the ruler
  // IS picking the scenario, so a mode, a riven-ness and a rank there are three
  // controls answering nothing and a fourth repeating the first. A domain
  // DECLARES its axes; the shape is fixed per bar, which is what a retriever
  // needs, rather than fixed across bars that ask different questions.
  const axes = cfg.axes || ["ruler", "mode", "kind", "row"];
  const asks = (a) => axes.includes(a);
  //
  // EVERY LIST IS STRONGEST-FIRST, and so is its default: the entries arrive in
  // that order from `builtinBuilds`, so a reader who touches nothing is looking
  // at this board's leader.
  const ruler = (p) => p.benchmark || p.builtin;
  const sel = ps.find((p) => presetId(p) === active) || null;
  const rulers = [];
  for (const p of ps) {
    if (!rulers.some((r) => r.id === ruler(p))) rulers.push({ id: ruler(p), label: p.group || p.name });
  }
  const curRuler = sel ? ruler(sel) : (rulers[0] || {}).id;
  const inRuler = ps.filter((p) => ruler(p) === curRuler);
  // THEN HOW THE WEAPON IS PLAYED, and it is a CONTROL rather than a header
  // inside the row list: a rank only means something within one way of
  // playing, so the Torid's Incarnon rows and its base rows are two rankings
  // and a reader after one of them should not scroll through the other.
  const modeOf = (p) => p.mode || "base";
  const curMode = sel ? modeOf(sel) : (inRuler[0] ? modeOf(inRuler[0]) : "");
  const modes = [];
  for (const p of inRuler) {
    if (!modes.some((m) => m.id === modeOf(p))) modes.push({ id: modeOf(p), label: p.modeName || modeOf(p) });
  }
  const inMode = inRuler.filter((p) => modeOf(p) === curMode);
  // THEN WHETHER IT CARRIES A RIVEN, and only then the rank. A weapon's board
  // holds TWO RANKINGS under one ruler and mode — the builds with a riven and
  // the builds without — and "#1" means something different in each. A PICK
  // RATHER THAN A LONGER LABEL, as with the ruler: each list stays the size of
  // ONE question, and the number at the end goes back to being a number.
  const kindOf = (p) => (p.riven ? "riven" : "plain");
  const curKind = sel ? kindOf(sel) : (inMode[0] ? kindOf(inMode[0]) : "");
  // IN THE ORDER THE ROWS COME IN, which is the stronger kind first.
  const kinds = [];
  for (const p of inMode) if (!kinds.includes(kindOf(p))) kinds.push(kindOf(p));
  const inKind = inMode.filter((p) => kindOf(p) === curKind);
  const kindLabel = (k) => tr(k === "riven" ? "With riven" : "Without riven");
  // A DEAD CONTROL STILL SAYS WHAT IT IS FOR. `title` carries the hint on every
  // one of the four, enabled or not, because the disabled ones are exactly the
  // ones a reader has no other way to interrogate.
  const hint = cfg.rowHintTitle || "";
  bar.hidden = false;
  bar.innerHTML =
    // HOW MANY, BY THE DOMAIN'S OWN RECKONING. An official scenario is one per
    // ruler and the count is the list; a board BUILD appears once per cell it
    // was ranked in, and the label says "builds".
    `<span class="plabel bench" title="${escHtml(cfg.benchHint || "")}">${escHtml(cfg.benchLabel)} <b>${
      cfg.count ? cfg.count(ps) : ps.length}</b></span>` +
    // THE RULER. Searched, because this list is the one designed to reach a
    // hundred, and every row of the board hangs off which one you are reading.
    ddButton(`dd-bench-${cfg.domain}`, {
      value: curRuler,
      search: rulers.length > 1,
      disabled: rulers.length === 0,
      title: cfg.benchHint || "",
      items: rulers.map((r) => ({ value: r.id, label: r.label })),
      // Picking a ruler lands on its FIRST row, which is its leader — the same
      // thing clicking that weapon on the board page gives you.
      onPick: (v) => {
        const first = ps.find((p) => ruler(p) === v);
        if (first) pickPreset(cfg, presetId(first));
      },
    }) +
    // HOW IT IS PLAYED.
    (!asks("mode") ? "" : ddButton(`dd-bench-mode-${cfg.domain}`, {
      value: curMode,
      disabled: modes.length === 0,
      title: hint,
      items: modes.map((m) => ({ value: m.id, label: m.label })),
      // Picking a mode lands on ITS leader, the same way picking a ruler
      // lands on the ruler's.
      onPick: (v) => {
        const first = inRuler.find((p) => modeOf(p) === v);
        if (first) pickPreset(cfg, presetId(first));
      },
    })) +
    // WHICH OF THE TWO RANKINGS.
    (!asks("kind") ? "" : ddButton(`dd-bench-kind-${cfg.domain}`, {
      value: curKind,
      disabled: kinds.length === 0,
      title: hint,
      // SAID AS A PROPERTY OF THE BUILD, not as a filter over a list: this
      // control picks one of two rankings, where the board page's own
      // three-way filter narrows one — so "riven only" stays over there.
      items: kinds.map((k) => ({ value: k, label: kindLabel(k) })),
      onPick: (v) => {
        const first = inMode.find((p) => kindOf(p) === v);
        if (first) pickPreset(cfg, presetId(first));
      },
    })) +
    // …AND WHICH ROW. A FLAT LIST OF NUMBERS: the ruler, the mode and which of
    // the two rankings are each answered by a control to its left, so a rank
    // here is a rank again.
    (!asks("row") ? "" : ddButton(`dd-bench-row-${cfg.domain}`, {
      value: sel ? presetId(sel) : (inKind[0] ? presetId(inKind[0]) : ""),
      search: inKind.length > 1,
      disabled: inKind.length === 0,
      title: hint,
      items: inKind.map((p) => ({
        value: presetId(p),
        label: p.rank != null ? `#${p.rank}` : p.name,
        hint: p.rowHint || p.hint || (cfg.roTitle ? cfg.roTitle(p) : ""),
      })),
      onPick: (v) => pickPreset(cfg, v),
    })) +
    (sel
      ? `<button class="pop dup" title="${escHtml(
          tr("copy it into a {thing} of your own — the official one cannot be edited")
            .replace("{thing}", tr(noun)))}">⧉</button>`
      : "");
  const dup = bar.querySelector(".pop.dup");
  if (dup) dup.addEventListener("click", (e) => { e.stopPropagation(); copyActivePreset(cfg); });
}

function renderPresetBarIn(bar, cfg) {
  // WHAT ONE OF THESE IS CALLED. "Preset" is the CATEGORY — a saved state of
  // a module, as opposed to a custom — and no collection is named after its
  // category. A build is a build, a scenario a scenario, a
  // search a search; the noun names new ones and every tooltip that has to
  // refer to one.
  const noun = cfg.noun || "preset";
  // YOURS ONLY. The official entries are drawn by `renderBenchmarkBarIn` in the
  // bar above; keeping them out of `ps` here is what makes the count, the
  // filter threshold and the "the last one cannot be deleted" rule all count
  // the same thing — the presets you own.
  const ps = cfg.load().filter((p) => !p.builtin);
  const active = cfg.active();
  const ftext = presetFilters[bar.id] || "";
  const f = ftext.trim().toLowerCase();
  const shown = f ? ps.filter((p) => p.name === active || p.name.toLowerCase().includes(f)) : ps;
  const hint = cfg.hint ? ` (${cfg.hint})` : "";
  const chip = (p) => {
    const sel = p.name === active;
    const ops = !sel
      ? ""
      : `<button class="pop dup" title="${escHtml(tr("duplicate"))}">⧉</button>` +
        `<button class="pop ren" title="rename">✎</button>` +
        // DELETABLE TO ZERO. "There is always one" was true
        // while one was auto-created; now that nothing is, the last one is as
        // deletable as the first — and a collection you cannot empty is one the
        // config page can never show you an honest count of. `cfg.optional` was
        // already the customs' flag for exactly this and is simply no longer
        // the thing that distinguishes them.
        `<button class="pop del" title="delete">✕</button>`;
    return `<span class="pchip ${sel ? "sel" : ""}" data-name="${escHtml(p.name)}" title="switch to ${escHtml(p.name)}${escHtml(hint)}">${escHtml(p.name)}${ops}</span>`;
  };
  bar.innerHTML =
    // Every bar says the shortcut: auto-save means a slip is written before
    // you can regret it, so the way back has to be visible on the thing that
    // slipped.
    `<span class="plabel" title="${escHtml(tr("Ctrl+Z undoes the last change"))}">${cfg.label} <b>${ps.length}</b></span>` +
    (ps.length > PRESET_FILTER_AT ? `<input class="pfilter" type="text" placeholder="${escHtml(tr("filter…"))}" value="${escHtml(ftext)}">` : "") +
    shown.map(chip).join("") +
    // One template, not two words joined by a space: Chinese does not put one
    // between them, so concatenating produced "新建空白 配装".
    `<span class="pchip add" title="${escHtml(
      tr("new empty {thing}").replace("{thing}", tr(noun)) + (cfg.hint ? " · " + cfg.hint : "")
    )}">+ new</span>` +
    // Presets are per weapon, so bringing one over from another weapon is
    // an explicit action rather than a side effect of switching weapons.
    // …EXCEPT a SHARED one, which has no "another weapon" to import from: the
    // scenario list is the same list everywhere, so the control would offer to
    // copy a fight into the collection it is already in.
    (!isSharedDomain(cfg.domain) && presetSources(cfg.domain, presetWeapon()).length
      ? `<span class="pchip imp" title="${escHtml(tr("copy one from another weapon"))}">⇤ ${escHtml(tr("import"))}</span>`
      : "") +
    (cfg.extra || "") +
    undoButtons(cfg.domain) +
    `<div class="pimport" hidden></div><div class="pshare" hidden></div>`;
  wireUndoButtons(bar, cfg.domain);
  if (cfg.onExtra) cfg.onExtra(bar);

  // Typing re-renders the bar (chips re-filter), so hand focus back.
  const filt = bar.querySelector(".pfilter");
  if (filt) filt.addEventListener("input", () => {
    presetFilters[bar.id] = filt.value;
    cfg.rerender();
    const nf = bar.querySelector(".pfilter");
    if (nf) { nf.focus(); nf.setSelectionRange(nf.value.length, nf.value.length); }
  });
  bar.querySelectorAll(".pchip:not(.add)").forEach((c) =>
    c.addEventListener("click", () => pickPreset(cfg, c.dataset.name)));
  // No prompt()/alert()/confirm() anywhere — the browser can block those
  // dialogs, which made saving silently fail. Naming
  // happens in an INLINE input: Enter commits, Esc cancels.
  const nameInput = (placeholderEl, initial, onCommit) => {
    placeholderEl.outerHTML = `<input class="pname" type="text" value="${escHtml(initial)}" placeholder="name, then Enter…" maxlength="24">`;
    const inp = bar.querySelector(".pname");
    inp.focus();
    if (initial) inp.select();
    let done = false;
    const commit = () => {
      if (done) return;
      done = true;
      onCommit((inp.value || "").trim());
    };
    inp.addEventListener("keydown", (ev) => {
      if (ev.key === "Enter") commit();
      if (ev.key === "Escape") { done = true; cfg.rerender(); }
    });
    inp.addEventListener("blur", commit);
  };
  // Unique auto-names: "+ new" takes the smallest free "preset N";
  // duplicate takes "<name> copy", then "<name> copy 2", …
  const addBtn = bar.querySelector(".pchip.add");
  addBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    const ps2 = cfg.load();
    // "preset N" everywhere except where the thing has its own noun — the
    // riven bar names them "riven N", because that is what they are.
    const name = freeName(ps2, (n) => noun + " " + n);
    // Activate FIRST so everything that renders during apply() (e.g. the
    // sim's per-preset stored result) already sees the NEW preset; then
    // apply the blank and store the resulting live snapshot, so the stored
    // state matches exactly what the editor now shows.
    cfg.setActive(name);
    whileApplying(() => cfg.apply(cfg.blank()));
    ps2.push({ name, savedAt: Date.now(), state: cfg.snapshot() });
    cfg.store(ps2);
    cfg.rerender();
  });
  const on = (sel, fn) => { const b = bar.querySelector(sel); if (b) b.addEventListener("click", (e) => { e.stopPropagation(); fn(); }); };
  on(".pop.dup", () => copyActivePreset(cfg));
  on(".pop.ren", () => {
    const chipEl = bar.querySelector(".pchip.sel");
    if (!chipEl) return;
    nameInput(chipEl, cfg.active(), (name) => {
      const ps2 = cfg.load();
      // Empty, unchanged, or colliding names just cancel the rename.
      if (name && name !== cfg.active() && !ps2.some((p) => p.name === name)) {
        const at = ps2.findIndex((p) => p.name === cfg.active());
        if (at >= 0) {
          ps2[at].name = name;
          cfg.store(ps2);
          cfg.setActive(name);
        }
      }
      cfg.rerender();
    });
  });
  // ⇤ import: an INLINE panel (no native dialogs) listing every OTHER
  // weapon's presets in this same collection. Picking one copies it here
  // under a free name and makes it active; ids the current weapon cannot
  // use are pruned by apply(), exactly as a normal load would.
  const impBtn = bar.querySelector(".pchip.imp");
  const impPanel = bar.querySelector(".pimport");
  if (impBtn) impBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!impPanel.hidden) { impPanel.hidden = true; return; }
    const src = presetSources(cfg.domain, presetWeapon());
    impPanel.innerHTML = src.map((w) =>
      `<div class="pimp-w"><span class="pimp-wn">${escHtml(w.name)}</span>` +
      w.presets.map((p) =>
        `<span class="pchip pimp-p" data-weapon="${escHtml(w.id)}" data-name="${escHtml(p.name)}">${escHtml(p.name)}</span>`
      ).join("") + `</div>`).join("");
    impPanel.hidden = false;
    impPanel.querySelectorAll(".pimp-p").forEach((el) => el.addEventListener("click", (ev) => {
      ev.stopPropagation();
      const from = loadPresetList(cfg.domain, el.dataset.weapon).find((x) => x.name === el.dataset.name);
      if (!from) return;
      const ps2 = cfg.load();
      const name = freeName(ps2, (n) => el.dataset.name + (n > 1 ? " " + n : ""));
      // RESCOPE before applying. A build preset carries its own weapon, and
      // restoreState honours it — so importing without this would navigate
      // the editor back to the SOURCE weapon and then store the copy in the
      // source's list, which is the bleed we are removing, not a fix for it.
      const state = cfg.rescope ? cfg.rescope(from.state, presetWeapon()) : from.state;
      cfg.setActive(name);
      // Apply FIRST, then snapshot: what gets stored is what this weapon
      // can actually hold, not the source weapon's raw state.
      whileApplying(() => cfg.apply(state));
      ps2.push({ name, savedAt: Date.now(), state: cfg.snapshot() });
      cfg.store(ps2);
      cfg.rerender();
    }));
  });

  on(".pop.del", () => {
    // YOURS ONLY, which is what the bar drawing these chips already counts
    // (`renderPresetBarIn` filters `!p.builtin`). Counting the joint list here
    // meant that on a weapon WITH board rows, deleting your last build fell
    // through to a BENCHMARK build — so the page answered "you deleted your
    // build" by loading somebody else's, and the bar's count and this handler's
    // disagreed about what a collection contains.
    const ps2 = cfg.load().filter((p) => !p.builtin && p.name !== cfg.active());
    // EVERY COLLECTION MAY GO TO ZERO, not only the OPTIONAL ones. A module
    // always has a state and "no build" is not a thing the builder can show —
    // both true, and neither needs a stored row: nothing is
    // auto-created any more (`initPresets`), so the state the builder shows
    // when you own nothing is `cfg.blank()`, and a preset comes back the moment
    // you edit it.
    //
    // `cfg.blank` is what the three modules already declare for "+ new", so the
    // state after deleting the last one is the state a new one would start
    // from — one answer, not two. A CUSTOM keeps `null`, which is how its
    // editor knows to stand down.
    cfg.store(ps2);
    cfg.setActive(ps2.length ? ps2[0].name : "");
    whileApplying(() => cfg.apply(
      ps2.length ? ps2[0].state : (cfg.optional || !cfg.blank ? null : cfg.blank())));
    // A DELETE IS NOT AN EDIT, and the state it leaves behind is the pristine
    // one — recorded here so the re-render this very handler causes cannot
    // create the row that was just removed.
    if (!ps2.length && cfg.pristine) cfg.pristine();
    cfg.rerender();
    clearTimeout(presetSaveTimer);
    clearTimeout(optSaveTimer);
  });
}

// An EMPTY build for "+ new": the CURRENT weapon (the page is a weapon
// page — a new preset should not navigate away), bare slots, no arcane, no
// evolutions. NO scenario: a build does not carry a fight, so making one
// cannot reset the fight you are in.
function blankBuildState() {
  return buildState($("weapon").value, {
    evoSel: {},
    arcane: ["none"],
    arcaneRank: [null],
    slots: [],
    // THE ARSENAL'S OWN, said out loud. A new build is played the way the
    // weapon comes, and a Lich weapon comes carrying an element — which is
    // what `defaultMode`/`defaultValence` answer when handed nothing. Named
    // rather than omitted, because an omission is what a producer that forgot
    // an axis also looks like (`BUILD_AXES`).
    // `null`, not `undefined` — see `stateFromBuild`: the two mean the same
    // thing to `restoreState` and only one of them survives being saved.
    mode: null,
    valence: null,
    // …and a modular weapon comes assembled — the derived default, which is
    // also what the server uses for a request that names none, so a brand new
    // build and a blank request describe the same weapon.
    assembly: null,
  });
}

// ---- THE OFFICIAL BUILDS ----------------------------------------------
//
// The board (`data/benchmarks/boards/`), as read-only chips in the BUILD bar.
// Not a tab: what a board row produces is a BUILD, and the
// builder is what consumes a build — so it belongs in the collection that
// already holds builds, marked as something you did not make.
//
// Same three properties as the official scenario: nothing stores them, nothing
// edits them, ⧉ copies one into an ordinary build of your own.
// The board, fetched at RUNTIME rather than compiled in. `data/` is embedded
// into the wasm at build time, so a board served through META would make every
// hourly update a full site rebuild. This is one small file on the same origin,
// written by the scoring job beside the canonical yaml.
//
// An absent or unreachable board is an EMPTY board, not an error: before the
// first submissions there is nothing to show, and that is a state the page has
// to render anyway.
let BOARD = {};
async function loadBoard() {
  try {
    const r = await fetch("/board.json", { cache: "no-cache" });
    BOARD = r.ok ? await r.json() : {};
  } catch (_) {
    BOARD = {};
  }
}

/// THE BOARD'S ROWS, as read-only builds you can open.
///
/// RANKED WITHIN A RULER AND A MODE, because that is the only thing a rank is.
/// `#1` across everything the board holds is unambiguous exactly while there
/// is one benchmark and one way to play; two of each turn it into a number
/// that names nothing. So the grouping is (benchmark, mode) and the chip says
/// which.
///
/// The mode travels IN THE STATE, so opening a board build plays it the way it
/// was measured. Without that, picking "#1" would show its mods in whatever
/// mode you happened to be in and quietly report a different number than the
/// board does — the same shape as the scenario leak, and worse, because this
/// one has a published figure sitting next to it.

/// A BOARD ROW'S BUILD, WITHOUT THE CELL IT WAS RANKED IN.
///
/// A CELL IS ONE BENCHMARK, ONE MODE AND ONE RIVEN-NESS, and a build is scored
/// in every one its weapon has — so counting ROWS counts it up to
/// `benchmarks x modes` times, by a multiple that is the weapon's mode count.
/// That makes a row count not merely large but INCOMPARABLE between weapons.
///
/// DERIVED BY EXCLUSION, never by listing the axes — the rule
/// `build_site_app.py`'s `_ident` states, because a hand-written list is the
/// copy that drops the next axis in silence. Out comes the cell, the
/// measurement and the presentation.
///
/// …AND A RIVEN IS ITS SHAPE: each cell searches its own best corner, so the
/// rolls differ per cell and are a measurement like the score.
const BOARD_CELL_KEYS = ["benchmark", "mode", "score", "rank", "shown", "source"];
function boardRowIdentity(row) {
  const build = {};
  for (const k of Object.keys(row || {}).sort()) {
    if (BOARD_CELL_KEYS.includes(k)) continue;
    build[k] = k === "riven" && row[k] && typeof row[k] === "object"
      ? { bonuses: row[k].bonuses || [], malus: row[k].malus || "" }
      : row[k];
  }
  return JSON.stringify(build);
}

const builtinBuilds = () => {
  const w = weaponInfo($("weapon").value) || {};
  // IN THE RULERS' OWN ORDER, which puts the PRIMARY one first — the same
  // declaration the board page and the scenario bar read (`Benchmark::primary`).
  //
  // It was board.json's order, which is the scorer's, and that was
  // indistinguishable from "the primary ruler first" until a second ruler took
  // rows: a cold load then restored a GROUP-CLEAR build under a weapon page,
  // which is not the row a first-time reader is looking at.
  const order = (id) => {
    const i = benchList().findIndex((b) => b.id === id);
    return i < 0 ? 99 : i;
  };
  // …THEN BY MODE AND BY KIND, STRONGEST GROUP FIRST. Each is a control on the
  // bar and a control's order is its own answer — which way of playing this
  // weapon wins here, and whether the winner carries a riven — so a reader who
  // touches nothing lands on the board's leader. A GROUP IS RANKED BY ITS BEST
  // ROW: one huge build and fifty mediocre ones are not comparable by any
  // other statistic the board holds.
  const best = {};
  for (const r of BOARD[w.id] || []) {
    const k = `${r.benchmark}#${r.mode || "base"}`;
    const k2 = `${k}#${rowHasRiven(r) ? "r" : "p"}`;
    best[k] = Math.max(best[k] ?? -1, r.score || 0);
    best[k2] = Math.max(best[k2] ?? -1, r.score || 0);
  }
  const modeKey = (r) => `${r.benchmark}#${r.mode || "base"}`;
  const kindKey = (r) => `${modeKey(r)}#${rowHasRiven(r) ? "r" : "p"}`;
  // TIES KEEP THE GROUPS CONTIGUOUS, or a rank means nothing — the picker
  // numbers each group as it walks the list. `w.modes` is the order the
  // builder's own Mode control offers, so the tiebreak agrees with it.
  const modeOrder = (m) => {
    const i = (w.modes || []).indexOf(m || "base");
    return i < 0 ? 99 : i;
  };
  const rows = (BOARD[w.id] || []).slice()
    .sort((a, b) =>
      order(a.benchmark) - order(b.benchmark)
      || (best[modeKey(b)] || 0) - (best[modeKey(a)] || 0)
      || modeOrder(a.mode) - modeOrder(b.mode)
      || (best[kindKey(b)] || 0) - (best[kindKey(a)] || 0)
      || (rowHasRiven(a) ? 1 : 0) - (rowHasRiven(b) ? 1 : 0)
      // Best first inside a group. board.json already arrives this way; stating
      // it here is what makes `#1` the leader rather than a bet on the scorer's
      // write order.
      || (b.score || 0) - (a.score || 0));
  const rank = {};
  return rows.map((row) => {
    const mode = row.mode || "base";
    const rv = rowHasRiven(row);
    const key = `${row.benchmark}#${mode}#${rv ? "r" : "p"}`;
    rank[key] = (rank[key] || 0) + 1;
    const n = rank[key];
    const bench = (META.benchmarks || []).find((b) => b.id === row.benchmark);
    // WHAT THIS ROW IS BEST OF, said in its own name. A board that holds both
    // kinds has two leaders per weapon and mode, and "#1" alone would be the
    // one number here that does not say what it ranks among.
    const kind = rv ? tr("riven") : "";
    // A QUALIFIER IN BRACKETS, not another dot-separated part. "Incarnon cycle · riven" reads as two facts of equal weight
    // and the group above it is already dot-separated; "Incarnon cycle (riven)"
    // reads as the same mode, narrowed — which is what it is, and what makes
    // the plain group next to it obviously the rest.
    // THE MODE IS ALWAYS PART OF THE NAME. This label travels away from the
    // control that picked it — the simulator tab, a shared card — where there
    // is no list to infer the missing term from.
    const m = modeLabel(w, mode);
    const label = m && kind ? `${m}（${kind}）` : (m || kind);
    return {
      name: label ? `#${n} · ${label}` : `#${n}`,
      // THE MODE IN WORDS, for the control that picks one — stated even where
      // the name above omits it, since the control is drawn from these entries.
      modeName: modeLabel(w, mode),
      // The rank alone, for the control that picks a row.
      rank: n,
      // Unique per ruler, mode AND kind: the id is what the active pointer
      // stores, and a plain #1 and a riven #1 are two different builds.
      builtin: `${row.benchmark}#${mode}#${rv ? "r" : "p"}#${n}`,
      // STATED, not parsed back out of the id above. The id is a durable key
      // and reading a fact out of one is how a rename becomes a wrong answer.
      riven: rv,
      benchmark: row.benchmark,
      mode,
      board: row,
      // The RULER is the group header; the row says what varies inside it.
      group: bench ? tr(bench.name) : row.benchmark,
      hint: String(row.shown != null ? row.shown : (row.score || 0).toFixed(4)),
      // ...and the flat form, for anywhere that shows no headers.
      hint_flat: `${bench ? tr(bench.name) : row.benchmark} · ${
        row.shown != null ? row.shown : (row.score || 0).toFixed(4)}`,
      savedAt: 0,
      state: buildState(w.id, {
        mode,
        // THE RIVEN'S SLOT IS TRANSLATED BACK. A record carries the bare
        // `riven` at the riven's own position — position is the build — and on
        // this side a mod id has to name an ITEM. The definition is registered
        // rather than written: `restoreState` creates it if and when this build
        // is actually taken.
        // TEN SLOTS, because a melee row's mod list carries its STANCE with the
        // rest — appended, and told apart by looking at it. A row from a gun
        // has nine of these empty and is unchanged.
        slots: (() => {
          const ids = (row.mods || []).slice();
          const si = ids.findIndex((id) => (modById(id) || {}).stance);
          const stance = si >= 0 ? ids.splice(si, 1)[0] : null;
          const out = Array.from({ length: 10 }, (_, k) => {
            const id = ids[k] || null;
            return { mod: id, pol: null, rank: null };
          });
          if (stance) out[STANCE].mod = stance;
          return out;
        })().map((s, k) => {
          const id = s.mod;
          if (id !== BOARD_RIVEN_SLOT || !row.riven) return { mod: id, pol: null, rank: null };
          const local = RIVEN_PREFIX + boardRivenName(row.riven);
          boardRivenDefs[local] = row.riven;
          return { mod: local, pol: null, rank: null };
        }),
        evoSel: (row.evolutions || []).reduce((m, id, k) => ({ ...m, [k + 1]: id }), {}),
        arcane: (row.arcanes || []).length ? row.arcanes : ["none"],
        arcaneRank: [null],
        // THE PROGENITOR ELEMENT the row was scored with, at the roll's
        // MAXIMUM — which is the ruler's own term, not the row's, so it is
        // taken from the weapon's spec rather than stored per row. Without
        // this a Kuva row opens at whatever the last build was carrying and
        // re-running it matches no line on the board.
        valence: row.valence
          ? { element: row.valence, bonus: (valenceSpec(w.id) || {}).max || 0 }
          : null,
        // THE PARTS the row was scored with, from the row's own two flat
        // fields. A modular weapon's assembly IS its stat line, so a row that
        // opened on the default parts would be a build that scores nothing
        // like the number beside it — which is exactly what a missing `mode`
        // did to every Incarnon row, and `valence` to seven Kuva Nukors.
        assembly: row.grip ? { grip: row.grip, loader: row.loader } : null,
      }),
    };
  });
};
/// A BOARD ROW, OPENED. `?bench=<id>` names the ruler the row was read under,
/// `?mode=` how the weapon was played; together they identify exactly one
/// official build, and the row is not reproducible without both halves — so
/// this selects the ruler's own SCENARIO as well as the build.
///
/// Selecting the fight here is not a build writing the fight: it is the LINK
/// carrying both, which is what a board row is. Everything after this point
/// still obeys the rule — picking a build in the bar moves nothing else.
///
/// Silent where it cannot help: a link naming a ruler this build of the site
/// has never heard of, or a weapon with no row under it, leaves the page as it
/// found it rather than clearing what is on screen.
function applyBenchLink(w, benchId, wantMode, wantRiven) {
  const sc = builtinScenarios().find((s) => s.builtin === benchId);
  if (sc) pickPreset(scenarioBarCfg(), presetId(sc));
  let rows = builtinBuilds().filter((p) => p.benchmark === benchId);
  if (!rows.length) return;
  // WHICH OF THE TWO LEADERS, narrowed FIRST because it is the coarser split:
  // a weapon's riven rows and its plain ones are two rankings, and taking the
  // mode's leader out of the union hands back whichever of the two happens to
  // score higher. Skipped when the link predates the parameter, and skipped
  // when it would leave nothing — a board that holds only plain rows still has
  // to answer a `riven=1` link with the row it does have rather than with
  // silence.
  if (wantRiven !== null && wantRiven !== undefined) {
    const narrowed = rows.filter((p) => !!p.riven === wantRiven);
    if (narrowed.length) rows = narrowed;
  }
  // The mode the link asked for, else however this weapon is played — the
  // board's own row order inside a ruler is best-first, so `find` is the
  // leader either way.
  const want = wantMode && (w.modes || []).includes(wantMode) ? wantMode : null;
  const row = (want && rows.find((p) => p.mode === want)) || rows[0];
  pickPreset(buildBarCfg(), presetId(row));
}

const buildList = () => builtinBuilds().concat(loadPresetList(BUILDS));
const buildNamed = (n) => buildList().find((p) => p.name === n || p.builtin === n);
/// Is the build on screen one of the official ones? Then nothing may write it.
const officialBuildActive = () => !!(buildNamed(activePreset) || {}).builtin;

// A benchmark's display name from its id, localized. Falls back to the raw id
// rather than to nothing: a board row naming a benchmark this build of the site
// does not carry is still a row, and hiding which ruler it used would make it
// look like it had none.
const benchmarkName = (id) => {
  const b = (META.benchmarks || []).find((x) => x.id === id);
  return b ? tr(b.name) : id || "—";
};

/// The build collection's config, as a FACTORY like `scenarioBarCfg` — it used
/// to be a local inside the renderer, which meant the only way to select a
/// build was to be a bar. The router selects one too, when a board row names
/// the ruler it came from.
function buildBarCfg() {
  return {
    domain: BUILDS,
    // An imported build keeps its mods/arcane/sim scenario but belongs to
    // the weapon it lands on; restoreState prunes whatever that weapon
    // cannot equip (a different mod class, other evolution ids).
    rescope: (st, weapon) => ({ ...st, weapon }),
    label: tr("Builds"),
    noun: "build",
    // Sharing belongs to the BUILD bar: what travels is the open build, plus
    // everything needed to reproduce its number.
    extra: SHARE_ENABLED ? `<button class="pchip share">${escHtml(tr("share"))}</button>` : "",
    onExtra: (bar) => {
      const b = bar.querySelector(".share");
      if (b) b.onclick = (e) => { e.stopPropagation(); openSharePanel(bar); };
    },
    load: buildList,
    store: (ps) => storePresetList(BUILDS, ps.filter((p) => !p.builtin)),
    readonly: (p) => !!p.builtin,
    roTitle: (p) =>
      tr("a benchmark build — measured under") + " " + benchmarkName(p.benchmark),
    active: () => activePreset,
    setActive: (n) => { activePreset = n; localStorage.setItem(presetActiveKey(BUILDS), n); },
    snapshot: snapshotState,
    // Never the payload's weapon — the scope's. See restoreState.
    // The benchmark build's Forma plan is NOT applied here — `restoreState`
    // owns it, so the boot path gets it too. See the comment there.
    apply: (st) => restoreState(st, presetWeapon()),
    blank: blankBuildState,
    pristine: notePristineBuild,
    rerender: () => { renderPresetBar(); lockOfficialBuild(); },
  };
}

/// WHAT IS OPEN ON THIS PAGE, said in one line and in one place.
///
/// THE BARS ABOVE ARE RETRIEVERS. Their controls say what you are BROWSING, and
/// picking in one loads a build — but a reader on their own preset was still
/// shown a ruler, a mode and a rank up there, because the benchmark bar falls
/// back to the board's leader whenever nothing official is loaded. Two facts
/// wearing one row is what made "which of these am I looking at" unanswerable,
/// and no rearrangement of the bar could have fixed it: the missing sentence
/// was never one the bar was in a position to say.
/// A BUILD'S CONTENTS, IN ONE LINE — every axis it varies on and no other.
///
/// ONE COMPONENT, TWO SURFACES: the simulator says what is OPEN and the
/// optimizer says what it FOUND, which is the same sentence about different
/// builds. `engine::builds::BUILD_AXES` declares what a build consists of, so
/// a describer that omits one is wrong in both places at once — on an adversary
/// weapon, a ranking that cannot say which ELEMENT it scored.
/// docs/CHECKS.md `check_opt_row_axes`.
///
/// IT TAKES A DESCRIPTOR RATHER THAN READING STATE: the two callers hold their
/// build in different shapes, the page's live slots and a result off the wire.
function buildContentsHtml(b) {
  const modName = (id) => (modById(id) || { name: null }).name || prettify(id);
  const bits = [];
  // THE MODE FIRST, because it decides what every number after it means.
  if (b.modeLabel) bits.push(`<span class="bl-mode">${escHtml(b.modeLabel)}</span>`);
  // …AND THE ELEMENT, on the weapons that have one. It is part of what the
  // build IS — two Kuva Nukors differing only in progenitor are two builds
  // with two scores — so a line that omits it describes neither.
  if (b.valence) {
    bits.push(`<span class="bl-valence">${escHtml(tr(prettify(b.valence)))}</span>`);
  }
  // THE PARTS, where the assembly IS the stat line (a Kitgun).
  const parts = b.assembly && Object.values(b.assembly).filter(Boolean);
  if (parts && parts.length) {
    bits.push(escHtml(parts.map((x) => prettify(x)).join(" + ")));
  }
  const arcs = (b.arcanes || [])
    .map((id, i) => (id && id !== "none"
      ? `${arcName(id)}${b.arcaneRanks && b.arcaneRanks[i] != null ? ` r${b.arcaneRanks[i]}` : ""}`
      : ""))
    .filter(Boolean);
  bits.push(`<b>${escHtml(arcs.join(" + ") || tr("no arcane"))}</b>`);
  const evos = (b.evolutions || []).map(evoName).filter(Boolean);
  if (evos.length) bits.push(escHtml(evos.join(" · ")));
  // THE RIVEN IS A MOD and rides in the mod list, but a line that leaves it
  // unnamed cannot tell a riven build from the plain one beside it.
  if (b.riven) bits.push(`<span class="bl-riven">${escHtml(tr("With riven"))}</span>`);
  const mods = (b.mods || []).map(modName).join(", ")
    + (b.exilus && b.exilus !== "none" ? `, ${modName(b.exilus)} (exilus)` : "");
  return `<div class="opt-detail">${bits.join(" · ")}</div>`
    + `<div class="opt-mods">${escHtml(mods)}</div>`;
}

function renderCurrentBuild() {
  const box = $("build-current");
  if (!box) return;
  const p = buildNamed(activePreset);
  let what;
  if (p && p.builtin) {
    // NAMED THE WAY THE BAR NAMES IT — ruler, mode, riven, rank — so the reader
    // can carry the sentence back up to the controls and find it.
    const bits = [p.group || benchmarkName(p.benchmark || p.builtin)];
    if (p.modeName) bits.push(p.modeName);
    bits.push(tr(p.riven ? "With riven" : "Without riven"));
    if (p.rank != null) bits.push(`#${p.rank}`);
    what = `<b>${escHtml(bits.join(" · "))}</b><span class="bc-note">${
      escHtml(tr("a board row, so nothing here can be edited — copy it to open everything up"))}</span>`;
  } else if (p) {
    what = `<b>${escHtml(presetLabel(p))}</b><span class="bc-note">${
      escHtml(tr("one of your own builds"))}</span>`;
  } else {
    // THE THIRD STATE IS A STATE. A build nobody has saved is what the page
    // opens on and what every edit returns you to, and saying nothing there
    // left the line blank exactly when the reader had least context.
    what = `<b>${escHtml(tr("an unsaved build"))}</b><span class="bc-note">${
      escHtml(tr("save it to keep it, or send it to the board"))}</span>`;
  }
  // …AND WHAT IT ACTUALLY IS. The sentence above names the build's SOURCE — a
  // board row, one of yours, an unsaved one — and a reader looking at a page
  // full of controls still has to reconstruct its contents from them. The same
  // describer the optimizer's rows use answers it once.
  const contents = buildContentsHtml({
    mods: slots.slice(0, boardBuildMods()).map((s) => s.mod).filter(Boolean),
    exilus: (slots[EXILUS] || {}).mod || "",
    arcanes,
    arcaneRanks,
    evolutions: Object.values(evoSel || {}).filter(Boolean),
    modeLabel: modeLabel(weaponInfo($("weapon").value) || {}, mode),
    valence: Object.entries(valence || {}).find(([, v]) => v && v !== "off")?.[0] || "",
    assembly,
    riven: slots.some((s) => s.mod === "riven"),
  });
  box.innerHTML = `<span class="bc-k">${escHtml(tr("Open now"))}</span>${what}${contents}`;
}

function renderPresetBar() {
  // TWO BARS, ONE CONFIG. The benchmark bar and the player's bar are handed
  // the same `cfg` — same load, same active, same apply — so a chip in either
  // one selects the same way and a ⧉ copies the same way. What differs is only
  // which entries each draws and which operations it offers.
  const buildsCfg = buildBarCfg();
  renderBenchmarkBarIn($("bench-bar-builder-builds"), {
    ...buildsCfg,
    benchLabel: tr("Benchmark builds"),
    benchHint: tr("submitted by players, scored here — read-only"),
    // DISTINCT BUILDS, not rows: a build is ranked in every cell its weapon
    // has, and the label says what it counts. See `boardRowIdentity`.
    count: (ps) => new Set(ps.map((p) => boardRowIdentity(p.board || {}))).size,
  });
  renderPresetBarIn($("preset-bar-builder-builds"), buildsCfg);
  renderCurrentBuild();
}

// A scenario is the `sim` object, BUFF CONFIG INCLUDED.
//
// Buff ids are global — `arcane:primary_deadhead`, a mod's own buff — so a
// setting travels, and `sim.buffs` deliberately keeps entries for buffs the
// build does not currently carry: that is what lets a scenario say "in THIS
// fight, Deadhead starts at zero stacks" and have it hold when the mod is added
// later. Anything unmentioned takes the buff's own default, full and unlocked.
/// Fields a scenario may no longer hold. A stored preset written before the
/// mode moved into the build still carries `form`, and applying it would put
/// it back on `sim` — where the next auto-save would write it out again, and
/// keep writing it forever. Dropped on the way in, so a custom scenario is
/// clean the first time it is opened and stays clean.
/// FIELDS A SCENARIO NO LONGER CARRIES, stripped in both directions so a stored
/// one — or a benchmark yaml — cannot reintroduce them.
///
/// `runs` joined them on 2026-08-13. HOW HARD YOU MEASURE IS NOT PART OF THE
/// FIGHT. The official rulers still run at 1,000 — that is the number
/// their yaml states and the number the SCORER uses, and no local setting can
/// move it — while the page runs at whatever you set, defaulting to 100. Two
/// different questions that happened to share a field.
const DEAD_SCENARIO_FIELDS = ["form", "mode", "runs"];

/// HOW MANY TIMES THE PAGE REPLAYS A FIGHT. A preference, not a scenario field:
/// it survives switching fights and switching weapons, because "how hard do I
/// want to measure right now" is a fact about the person and not about the
/// engagement.
const SIM_RUNS_KEY = "wfsim-sim-runs";
const SIM_RUNS_DEFAULT = 100;
const simRuns = () => {
  const v = Math.round(Number(localStorage.getItem(SIM_RUNS_KEY)));
  return Number.isFinite(v) && v >= 1 && v <= 20000 ? v : SIM_RUNS_DEFAULT;
};
const setSimRuns = (n) => {
  const v = Math.max(1, Math.min(20000, Math.round(Number(n)) || SIM_RUNS_DEFAULT));
  localStorage.setItem(SIM_RUNS_KEY, String(v));
};

function snapshotScenario() {
  const { __weapon, ...rest } = sim;
  // Belt and braces with the strip on the way IN: a fight has no opinion about
  // how the weapon is fired, so one can never leave here carrying one either.
  DEAD_SCENARIO_FIELDS.forEach((k) => { delete rest[k]; });
  return JSON.parse(JSON.stringify(rest));
}
function applyScenario(st) {
  st = { ...(st || {}) };
  DEAD_SCENARIO_FIELDS.forEach((k) => { delete st[k]; });
  // ONTO THE DEFAULTS, NEVER ONTO THE FIGHT YOU ARE LEAVING.
  //
  // Spreading over the live `sim` leaves any field the incoming scenario does
  // not mention holding the outgoing one's value — and a benchmark yaml
  // mentions only what it has an opinion about. Tick Eximus on a copy of the
  // official ruler, switch back to the official, and the official fight is
  // now against an Eximus, because `single_target.yaml` never says `eximus:`. `invisible` did not leak in the same
  // test only because that yaml happens to state it.
  //
  // A scenario is therefore applied onto a COMPLETE fight — the server's
  // defaults — which makes every preset self-contained whatever it omits. It is
  // the same rule AGENTS.md already states for weapons ("the live `sim` at that
  // moment still belongs to the weapon you just left"), and the same reason: a
  // collection's state may not be written from outside it, and reading the
  // outgoing state is how it gets written from outside it.
  sim = { ...defaultScenario(), ...st, buffs: JSON.parse(JSON.stringify(st.buffs || {})) };
  // A scenario preset is stored per weapon, so its weapon-scoped field
  // (headshot %) is already right — stamp the marker so the re-seed does not
  // overwrite a saved choice with a default.
  sim.__weapon = $("weapon").value;
  // …AND EVERY BODY GETS ITS UNIT, ONCE.
  //
  // A body placed since 2026-08-18 carries the unit it was placed with. Every
  // body placed BEFORE that carries nothing, and a blank means "the aimed
  // body's" — which is exactly what those bodies meant when they were placed,
  // and is also, from the reader's side, indistinguishable from the bug that
  // rule was written to end: switch the enemy on the left and the whole
  // formation follows it — which is still true after the placement fix for
  // every formation saved before it.
  //
  // So the blank is filled in HERE, at the one place a scenario becomes the
  // live fight, from the enemy that scenario itself carries. It changes nothing
  // about what those bodies are — it writes down what they already were — and
  // from that moment they stop following. Growth stopping is not the same as
  // the existing ones being fixed, which is the same lesson as
  // `reclaimStoredReplays` and was missed the same way.
  (sim.formation || []).forEach((f) => { if (!f.enemy) f.enemy = sim.enemy; });
  renderSim();      // redraws every knob, and the bar with them
  refreshPanel();   // the Tenno half of a scenario changes what the build is worth
}
// A scenario is CONSUMED outside the simulator — the quick calc scans under
// one by name, and the optimizer states the one it will search with — so
// creating, renaming or deleting one has to reach those lists at once, the
// way a new riven reaches the mod pool. One hook: the bar
// calls `rerender` after every mutation, switching included.
function scenariosChanged() {
  renderScenarioBar();
  // Switching or copying a scenario changes whether the fight is EDITABLE, and
  // this hook is the only thing every mutation goes through — `renderSim` is
  // not called here, so without this line a copy of an official scenario kept
  // the original's inert controls.
  lockOfficialScenario();
  // ...and whether this fight can reach the board at all — asked of the board.
  renderBoardConsent();
  refreshBoardDoor();
  if ($("opt-buffs")) renderOptBuffs();
  // …and the Warframe buffs, which are the SCENARIO's: switching fights
  // switches which abilities are running, so the cards have to be repainted
  // from the incoming state rather than left showing the outgoing one's.
  if ($("sim-wfbuffs")) renderWfBuffs("sim-wfbuffs", false);
  // …and the QUICK CALC RE-ASKS. Not just repaints: switching fights is the
  // biggest thing that can happen to a ranking, and this hook drew the box
  // under the new fight's name while every chip beside it still answered the
  // old one's question. A `markScenarioDirty` EDIT has
  // re-run the scan since it existed; a SWITCH never did, because a switch is
  // a replacement rather than an edit and goes nowhere near that debounce.
  //
  // Here rather than at the call sites, because this hook is already "the only
  // thing every scenario mutation goes through" — the line above says so for
  // `lockOfficialScenario`, and the same reasoning makes it the one place that
  // cannot be forgotten by a mutation added later.
  refreshGains();
  if ($("opt-target")) renderOptEnemy();
}

// ---- THE OFFICIAL SCENARIOS -------------------------------------------
//
// `data/benchmarks/*.yaml`, served in META. They sit in the scenario bar
// beside the player's own and behave like presets in every way but three:
// nothing stores them (so they cannot drift from one machine to another),
// nothing edits them, and they appear on EVERY weapon — which is the whole
// point, since a number only means something against a ruler someone else can
// pick up. Wanting a variant is what ⧉ is for: it copies the official one into
// an ordinary, editable scenario of your own.
const builtinScenarios = () => (META.benchmarks || []).map((b) => ({
  // TRANSLATED for display, like everything else on the page. Its identity is
  // the `builtin` id below, never this string — see `scenarioNamed`.
  name: tr(b.name),
  // The id, not just a flag: a board row records WHICH ruler it was measured
  // under, and a retired version has to be recognisable as retired.
  builtin: b.id,
  savedAt: 0,
  state: b.scenario,
}));
// The list every reader sees: official first, then the player's own.
const scenarioList = () => builtinScenarios().concat(loadPresetList(SCENARIOS));
// By NAME or by official ID. A benchmark's display name is translated, so the
// name alone cannot be its identity: switching language would orphan the
// pointer that says which scenario is open. The id is what gets stored.
const scenarioNamed = (n) => scenarioList().find((p) => p.name === n || p.builtin === n);
const scenarioKey = (n) => (scenarioNamed(n) || {}).builtin || n;
/// Is the fight on screen the official one? Then nothing may write to it.
const officialScenarioActive = () => !!(scenarioNamed(activeScenario) || {}).builtin;

// The scenario bar's config, as a FACTORY rather than a local — two callers
// need it now: the bar itself, and the "edit a copy of this fight" button in
// the official note, which performs the identical copy. A second hand-written
// config there is how the two come to copy different things.
function scenarioBarCfg() {
  return {
    domain: SCENARIOS,
    label: tr("Scenarios"),
    noun: "scenario",
    load: scenarioList,
    // An official scenario is not stored, so it can never be written back —
    // this is the line that makes "read-only" a property of the DATA rather
    // than of the buttons drawn over it.
    store: (ps) => storePresetList(SCENARIOS, ps.filter((p) => !p.builtin)),
    readonly: (p) => !!p.builtin,
    active: () => activeScenario,
    setActive: (n) => { activeScenario = n; localStorage.setItem(presetActiveKey(SCENARIOS), scenarioKey(n)); },
    snapshot: snapshotScenario,
    apply: applyScenario,
    blank: snapshotScenario,
    rerender: scenariosChanged,
  };
}

/// "Give me an editable copy of the fight I am looking at" — the one
/// implementation, shared by the chip's ⧉ and the note's button.
const copyActiveScenario = () => copyActivePreset(scenarioBarCfg());

function renderScenarioBar() {
  const scenariosCfg = scenarioBarCfg();
  // ONE QUESTION: WHICH RULER. An official scenario is one per ruler, so the
  // other three axes would be controls answering nothing.
  renderBenchmarkBarIn($("bench-bar-simulator-scenarios"), { ...scenariosCfg, axes: ["ruler"], benchLabel: tr("Benchmark scenarios"), benchHint: tr("the official rulers — the same fight on every weapon") });
  renderPresetBarIn($("preset-bar-simulator-scenarios"), scenariosCfg);
}

function fillSelect(id, items) {
  const el = $(id); el.innerHTML = "";
  for (const it of items) { const o = document.createElement("option"); o.value = it.id; o.textContent = it.name; el.appendChild(o); }
}
let currentPool = [];
const weaponInfo = (id) => META.weapons.find((w) => w.id === id) || META.weapons[0];
// Evolutions moved into each weapon's meta entry (they are per transform
// group); this reads the CURRENT weapon's tiers.
/// THE TIERS OF A WEAPON — **the one it is ASKED about**, and only the LIVE one
/// when nobody says.
///
/// It took no argument at all and read `#weapon` every time, which made
/// `weaponAxes(id)` able to disagree with itself: every other axis in that
/// object is derived from the `id` it was handed, and `evolutions` was derived
/// from whatever the select happened to say. So `weaponAxes(A)` could return
/// A's mods, A's arcanes and B's evolution tiers, and the caller has no way to
/// see it — `show("evo-block", AX.evolutions.length > 0)` would then draw the
/// block for a weapon with none.
///
/// That is precisely the shape of `check_parity`'s intermittent "the builder
/// shows an evolution block for a weapon with none" — four times over eight
/// runs, never the same weapon twice, always a weapon with NO evolutions. It
/// is not proven to be the cause and the diagnostic that would prove it is in
/// place; what IS certain is that this could produce it, and that a function
/// reading global state instead of what it was asked about is wrong whether or
/// not it is the bug of the day.
const weaponEvos = (weaponId) =>
  (weaponInfo(weaponId || $("weapon").value) || {}).evolutions || [];
// THE TIER LADDER, in one place. Tier N is choosable only once N-1 is filled:
// a tier-2 perk with no tier 1 is not a weaker build, it is not a build. The
// builder greys the later rows out; the gain scan has to obey the same rule or
// it measures — and recommends — evolutions nobody can select.
const evoOpenTo = () => {
  let n = 0;
  for (const t of weaponEvos()) { if (!evoSel[t.tier]) break; n = t.tier; }
  return n + 1; // the deepest tier that may be chosen
};
const modById = (id) => poolWithRivens().find((m) => m.id === id);
// A SECTION THAT IS NOT THERE IS NOT A DEAD APP.
//
// This threw on a null element, and the throw is upstream of everything:
// `init` -> `applyWeapon` -> `renderOpt` -> here, so ONE missing id put
// "WFSim could not start" on the whole page. Reported from an iPhone with the
// stack ending at this line — `#opt-modes-sect` sits at byte 42,939 of a
// 52,687-byte document, which is exactly the tail a truncated mobile response
// loses.
//
// LOUD, NOT SILENT. Swallowing it would hide a real markup fault, so the
// missing id is named in the console and the app carries on: a page with one
// section unstyled is worth more than a page that will not open.
const show = (id, on) => {
  const el = $(id);
  if (!el) {
    console.warn(`show(${id}): no such element — section skipped`);
    return;
  }
  if (on) el.removeAttribute("hidden");
  else el.setAttribute("hidden", "");
};
// Where (other than exceptIdx) this mod is currently slotted, or -1.
const placedAt = (id, exceptIdx) => slots.findIndex((s, i) => i !== exceptIdx && s.mod === id);

// Switching weapons rebuilds every weapon-scoped view. It runs as an
// APPLY (auto-save stays out of the reset/reseed churn — the optimizer
// scope resets here, and saving that would wipe the scope presets); the
// build preset then follows the new weapon via the explicit
// markPresetDirty() below, which no-ops when this runs inside a preset
// load (restoreState already holds the applying guard).
function applyWeapon(id, presetMods) {
  whileApplying(() => applyWeaponInner(id, presetMods));
  markPresetDirty();
}

// A user-driven weapon CHANGE, as opposed to applyWeapon's "rebuild the
// editor for this weapon". Presets are per weapon, so the bar must reload
// from the new weapon's own storage — initPresets() restores its active
// preset (creating "build 1" the first time). The optimizer's groups
// re-bootstrap on their own: applyWeaponInner clears optSeeded, and
// renderOpt re-runs bootstrapOptPresets against the new scope.
// NOT called from restoreState: loading a preset must not re-enter this.
function switchWeapon(id) {
  $("weapon").value = id;
  applyWeapon(id, null);
  initPresets();
}

/// THE OTHER SLOT OF THE SAME CHAMBER, WITHOUT LEAVING THE PAGE.
///
/// A Kitgun is ONE weapon — one mastery track, one riven, one wiki page — and
/// two roster entries, because the slot decides the mod pool. So the Slot
/// control switches the ENTRY and the address stays where the reader arrived,
/// which is what makes the two a page rather than two pages sharing a name.
///
/// `restoreState` rewrites the address to the incoming weapon's own path, which
/// is right for every other switch and wrong for this one — and was invisible
/// only while the sibling had no address of its own to move to.
function switchSlot(id) {
  const was = location.pathname;
  switchWeapon(id);
  if (location.pathname !== was) history.replaceState(null, "", was);
}

function applyWeaponInner(id, presetMods) {
  const w = weaponInfo(id);
  buffList = []; // rebuilt from the next /api/panel response for this build
  // HOW THIS WEAPON IS PLAYED, reset to its own default. "base" is a legal id
  // on almost every weapon, so without this an Incarnon weapon opened after a
  // plain one would keep the plain one's mode and quietly skip the cycle that
  // is supposed to be its default — the same rule that makes a new weapon get
  // `defaultScenario()` rather than the last one's fight. `restoreState`
  // overwrites this immediately when a preset is being applied.
  mode = defaultMode(id, null);
  // NOTHING CROSSES BETWEEN WEAPONS: a valence is a statement about one of
  // them, so opening another starts with none.
  valence = defaultValence(id, null);
  // …AND SO ARE ITS PARTS. A grip belongs to one slot, so the sibling entry's
  // five are not even legal here; `defaultAssembly` returns null on a weapon
  // that takes none, which is what clears them on the way to an ordinary gun.
  assembly = defaultAssembly(id, null);
  // THE FIGHT DOES NOT MOVE. A scenario is shared across the roster now
  // (`SHARED_DOMAINS`), so switching weapons keeps the fight you are measuring
  // under — which is the entire point of being able to compare two guns.
  //
  // Its one weapon-shaped knob is headshot %, and it is left alone for the same
  // reason the official rulers leave it alone: the ruler pins 100 and applies
  // to the whole roster, and the SERVER forces 0 on a weapon that cannot
  // headshot (`parse_fight`, sentinel). Resetting it here would have rewritten
  // the shared scenario every time you changed weapon, and auto-save would have
  // stored that.
  sim.__weapon = id;
  // `min` IS IN HERE, and it was not — the one field of the scope this reset
  // forgot, since the day the range landed. `updateOptEstimate`
  // reads it as `Math.max(derived, opt.min)`, and `Math.max(n, undefined)` is
  // NaN, so `for (k = NaN; k <= size; k++)` never runs: every weapon with no
  // saved search reported its scope as impossible ("more required (0) than
  // slots (8)") and disabled Run until some control was touched. `modes`,
  // `valence`, `arcanes` and `evos` are absent on purpose — `renderOpt`'s seed
  // block fills those from the build you are holding — while `size` and `min`
  // are this line's to state (owner asked for a floor of 0, 2026-08-29, which
  // is what made the missing field visible).
  opt = { mods: {}, exilus: {}, arcanes: {}, evos: {}, size: 8, min: 0 }; optSeeded = false; // reset scope
  optLast = null;                 // and the winner the quick calc could measure against
  // ...and how it RUNS, for the same reason the scenario resets: a weapon that
  // has never been searched must not inherit the last weapon's finalists or
  // thread count into the "search 1" it is about to be given.
  optRun = { ...OPT_RUN_DEFAULTS };
  // Last weapon's ranking is not this weapon's. Nothing else clears it — the
  // tabs are CSS-hidden rather than re-rendered, so it simply stayed on screen
  // under the new weapon's name.
  if ($("opt-results")) $("opt-results").innerHTML = "";
  // A weapon's pool is the UNION of the pools it draws from: `primary` mods
  // fit any primary weapon, `rifle` is the class pool. One flat list per
  // weapon was right only while every rifle-class weapon was a launcher.
  rivenModCache = { key: null, list: [] };
  refreshRivenNames(); // this weapon's rivens, named by the engine
  // The SERVER decides which mods this weapon can equip (`pool_for_weapon`)
  // and sends the id list; the class tables are only where the mod objects
  // live. A JS re-implementation of the same rules goes stale the moment the
  // engine learns a new one — Amalgam mods are not equippable on a sentinel
  // weapon and ammo mods do nothing on an infinite reserve, and neither
  // reaches the builder or the optimizer while the pool
  // was computed twice.
  const byId = new Map(
    Object.values(META.mod_pools || {}).flat().map((m) => [m.id, m]),
  );
  currentPool = (w.mods || []).map((id) => byId.get(id)).filter(Boolean);
  // NINE, not eight. The server sends 8 main slots plus the EXILUS slot's own
  // innate polarity (`innate_slots_for`, which has appended it since the
  // 2026-07-28 wiki cross-check), and this line sliced that ninth entry off
  // and padded a null over it. So every weapon with an exilus polarity — Boar
  // Prime's Madurai, the Naramon on Torid / Cernos Prime / Dual Toxocyst /
  // Laetum — showed an unpolarized exilus slot: the mod in it paid full drain
  // instead of half, and the Forma plan charged for a polarity the weapon
  // comes with.
  innate = (w.innate_polarities || []).slice(0, 9);
  while (innate.length < 9) innate.push(null);
  // TEN, not nine — and the tenth is the STANCE slot, which has a polarity of
  // its own on almost every melee (the Magistar's is Vazarin). Left off, the
  // slot drew blank and the grant read as a mismatch: the same slice-and-pad
  // that hid the exilus polarity, one slot further along.
  innate[STANCE] = w.stance_polarity || null;

  // A weapon with no asset yet must show NOTHING, not a broken-image box:
  // src="" still resolves (to the page) and renders as a failed load.
  const wimg = IMG(w.image);
  $("w-img").hidden = !wimg;
  if (wimg) $("w-img").src = wimg;
  // The weapon name links to its wiki page too (display suffixes like
  // " (sentinel)" are ours, not part of the page name).
  $("w-name").innerHTML = wl(w.name, wikiUrl(wikiWeaponName(w)));
  // Subtype (e.g. "Dual Pistols") + form tags; the mod-eligibility group
  // (mod_class) drives the picker's pool but isn't shown as a tag.
  // Name the POOL, the way the wiki does ("Rifle Mods" / "Pistol Mods"): the
  // eligibility group is what actually decides which mods equip, and a bare
  // "Mods" heading leaves the visitor guessing which pool a launcher draws
  // from. Falls back to the plain word if a class ever has no label.
  const POOL_NAME = { rifle: "Rifle Mods", pistol: "Pistol Mods", primary: "Primary Mods" };
  // Names the pools it actually draws, widest first — "Primary + Rifle Mods".
  const poolName = (w.mod_pools || [w.mod_class])
    .map((p) => (POOL_NAME[p] || p).replace(/ Mods$/, "")).join(" + ") + " Mods";
  $("mod-block-h").textContent = tr(poolName || "Mods");

  // WHAT THIS WEAPON DOES BEYOND ITS STATS. Generated engine-side from the data
  // that implements each passive, so the line and the simulation cannot say
  // different things. Empty for most weapons; the strip hides itself then.
  //
  // It lives here, in the weapon strip, because a passive is part of the
  // WEAPON — not of the build, not of the fight. Gotva Prime's crit set and
  // Dual Toxocyst's Frenzy are most of what those weapons are, and until
  // 2026-08-05 the page never mentioned either, so both read as ordinary guns.
  const wp = $("w-passives");
  if (wp) {
    const lines = w.passives || [];
    wp.hidden = !lines.length;
    wp.innerHTML = lines.map((x) => `<div>${escHtml(tr(x))}</div>`).join("");
  }
  $("w-tags").innerHTML = [w.subtype, w.uses_evo2 ? "Incarnon" : null, w.sentinel ? "Sentinel" : null]
    .filter(Boolean).map((t) => `<span class="tag">${t}</span>`).join("");

  const AX = weaponAxes(w.id);
  show("arcane-block", AX.arcanes.length > 0);
  show("evo-block", AX.evolutions.length > 0);
  // WHICH WEAPON THE BLOCKS ON SCREEN ARE FOR, stamped where the blocks are
  // decided. `#weapon`'s value is set SYNCHRONOUSLY by the switch while these
  // are drawn after it, so there is a window in which the page names one
  // weapon and shows another's axes — and a reader of the DOM has no way to
  // tell. It is one line and it makes that window observable: `check_parity`
  // waits on it rather than on the value plus a guess, which is where its
  // "builder shows an evolution block for a weapon with none" flake came from
  // (three times over six runs, always a weapon following one WITH evolutions
  // — 2026-08-24).
  document.body.dataset.panelFor = w.id;
  // THE VALENCE AXIS exists only where the weapon has one — an adversary
  // weapon. Same "no choice, no control" rule every other axis follows.
  show("element-block", !!valenceSpec(w.id));
  // …AND THE NUMBERS FOLLOW THE BLOCKS THAT ARE ACTUALLY THERE. They were
  // written into the markup, so a weapon with no evolutions numbered its
  // Valence block 5 with no 4 above it. Derived from the
  // DOM rather than from a table of weapons, so a block added later — or a
  // weapon built in the app one day — is numbered without anyone maintaining a
  // list.
  //
  // Non-numeric badges (Σ, ≡, ▶) are the ones that are not steps, and they keep
  // whatever they say.
  renumberBlocks();
  // An Arch-Gun's two slots are NOT interchangeable, so the line names the
  // pools rather than counting them: "primary + secondary", not "2 slots".
  $("arcane-sub").textContent = w.sentinel
    ? tr("sentinels cannot equip arcanes")
    : (w.arcane_pools || []).map((p) => tr(SLOT_LABEL[p] || p)).join(" + ");
  // The previous weapon's arcanes may not fit this one, slot by slot.
  arcanes = arcanesFor(w.id, arcanes);
  arcaneRanks = asArcaneList(arcaneRanks, arcanes.length).map((x) => x ?? null);

  slots = Array.from({ length: 10 }, (_, i) => ({ mod: null, pol: innate[i], rank: null }));
  (presetMods || []).filter((m) => modById(m)).slice(0, 8).forEach((m, i) => { slots[i].mod = m; slots[i].rank = modById(m).max_rank; });
  autoForma(); // sensible default: minimum-Forma polarities for the preset

  renderAssembly();
  renderMods(); renderArcanes(); renderEvo(); renderMode(); renderValence(); renderSim(); renderOpt();
}

// ---- forma / capacity plan (mirrors engine::mods::plan_forma) ----
function slotDrain(base, modPol, slotPol) {
  if (!slotPol) return base;                                        // no polarity
  if (slotPol === "Omni") return modPol === "Umbra" ? base : Math.ceil(base / 2); // universal, not Umbra
  if (slotPol === modPol) return Math.ceil(base / 2);              // matched: −50% round up
  return Math.round(base * 1.25);                                  // mismatched: +25%
}

// Drain at a given rank: rises 1 per rank from rank 0 (= max-rank drain − max_rank).
function modDrain(m, rank) {
  const r = rank == null ? m.max_rank : Math.max(0, Math.min(m.max_rank, rank));
  return m.drain - m.max_rank + r;
}

// Capacity = Σ effective drain over slots holding a mod (at its rank).
//
// TOLD WHICH SLOTS, because two questions are asked of it: the panel counts
// every slot the weapon has, and the BOARD counts the eight it judges — a
// benchmark build drops the exilus one, so measuring a submission against all
// nine would ask about a slot the board never reads.
const drainOver = (ss) => ss.reduce(
  (sum, s) => { const m = modById(s.mod); return m ? sum + slotDrain(modDrain(m, s.rank), m.polarity, s.pol) : sum; }, 0);
function capacityUsed() {
  return drainOver(slots);
}

// Forma cost, broken down by TYPE (regular / Omni / Umbra cost different items).
// Innate polarities form a free-repositionable pool of REGULAR polarities, so
// regular Forma = max(added-beyond-pool, removed-from-pool): same-polarity
// repositioning nets 0, but BLANKING an innate polarity (removal) costs a Forma,
// and a colour swap costs one (add+remove of one slot). Omni/Umbra are never
// innate here — each such slot is one Omni/Umbra Forma.
function formaCount() {
  const need = {}, pool = {};
  let umbra = 0, omni = 0;
  slots.forEach((s, i) => {
    // THE STANCE SLOT IS NOT IN THE POOL. Its polarity cannot be moved to a mod
    // slot — it is a slot of its own — so it is billed on its own line below
    // rather than competing for the nine the weapon was born with.
    if (i === STANCE || !s.pol) return;
    if (s.pol === "Omni") omni++;
    else if (s.pol === "Umbra") umbra++;
    else need[s.pol] = (need[s.pol] || 0) + 1;
  });
  // THE STANCE SLOT'S COLOUR IS NOT IN THE POOL. A polarity is repositionable
  // between the nine slots the weapon is born with; the stance slot is its own,
  // and letting a mod slot claim its Vazarin for free would pay a Forma nobody
  // spent.
  innate.slice(0, 9).forEach((p) => { if (p && p !== "Omni" && p !== "Umbra") pool[p] = (pool[p] || 0) + 1; });
  let added = 0, removed = 0;
  for (const p of new Set([...Object.keys(need), ...Object.keys(pool)])) {
    const d = (need[p] || 0) - (pool[p] || 0);
    if (d > 0) added += d; else removed += -d;
  }
  // ...and an ADVERSARY weapon is billed its five whatever the slots say. The
  // rank-40 ceiling costs five polarizations and the 80 capacity this build
  // was planned against assumes them, so a build using three has still spent
  // five (engine: `cost.regular += spend - cost.total()`).
  // …AND REPOLARIZING THE STANCE SLOT COSTS ONE. "As with Aura slots, Stance
  // slots can be repolarized using Forma" (wiki), and what it buys is the
  // doubled grant rather than a smaller drain.
  const stancePol = (slots[STANCE] && slots[STANCE].pol) || null;
  // BLANKING IT COSTS ONE TOO. The stance slot is not in the pool, so a colour
  // the weapon was born with cannot be swapped away — removing it is a Forma
  // like any other change to that slot.
  const stanceForma = stancePol !== (stancePolOf($("weapon").value) || null) ? 1 : 0;
  const regular = Math.max(added, removed) + stanceForma;
  const floor = Math.max(0, formaMin($("weapon").value) - regular - umbra - omni);
  return { regular: regular + floor, umbra, omni };
}

// Auto-assign polarities for MINIMUM Forma-to-fit (mirrors engine plan_forma):
// spend the innate pool on the biggest matching mods, then Forma the biggest
// unmatched until it fits. Overwrites polarities: what an unmatched slot ends
// up with is a leftover innate colour that had nowhere free to sit, or nothing.
//
// ...with a FLOOR under it on an adversary weapon (`plan_forma_spending`'s
// `at_least`). Those five polarizations are what put the weapon at rank 40,
// and rank 40 is where the 80 capacity this plan is measured against comes
// from — so a plan that fits in two and stops has spent the capacity of a
// weapon it did not build. They are bought either way; this puts them on the
// biggest mods still unmatched instead of leaving them unspent.
function autoForma() {
  const w = $("weapon").value;
  // THE STANCE SLOT GOES FIRST WHEN ANY FORMA IS SPENT AT ALL, which is the
  // rule `engine::mods::best_stance_plan` follows and the way the slot is
  // actually used: five points of capacity is more than polarizing any mod
  // draining ten or less. A build that fits for FREE keeps its zero, so the
  // choice is made by running the plan once with the slot as it is.
  const st = slots[STANCE].mod ? modById(slots[STANCE].mod) : null;
  if (st) {
    slots[STANCE].pol = stancePolOf(w);
    autoFormaWith(w);
    if (formaCount().regular + formaCount().umbra + formaCount().omni > 0) {
      slots[STANCE].pol = st.polarity;
    }
  }
  autoFormaWith(w);
}

// The plan itself, with the stance slot's colour already decided.
function autoFormaWith(w) {
  // …INCLUDING WHAT THE STANCE HANDS BACK. Planning against the weapon's own
  // capacity alone buys polarizations the build does not need — and reaches for
  // an Umbra Forma to do it, which is the one item this plan is meant to spare.
  const cap = capOf(w) + stanceGrant();
  const filled = [];
  // …AND NOT THE STANCE SLOT, which buys CAPACITY rather than a discount: its
  // Forma is `engine::mods::best_stance_plan`'s decision, and clearing its
  // colour here would hand the plan a mismatch it never chose.
  slots.forEach((s, i) => { const m = modById(s.mod); if (m && i !== STANCE) filled.push({ i, m }); });
  slots.forEach((s, i) => { if (i !== STANCE) s.pol = null; });
  const pool = innate.slice(0, 9).filter(Boolean);
  const poolSize = pool.length;
  // THE WEAPON'S OWN SLOTS, which is how many places a colour can sit — eight,
  // nine where there is an exilus slot, and the stance slot is not one of them.
  const slotCount = 8 + (weaponAxes().hasExilus ? 1 : 0);
  const spareSlots = Math.max(0, slotCount - filled.length);
  const bd = ({ i, m }) => modDrain(m, slots[i].rank);
  const order = filled.slice().sort((a, b) => bd(b) - bd(a));
  const matched = new Set(), free = new Set();
  for (const { i, m } of order) { const k = pool.indexOf(m.polarity); if (k >= 0) { pool.splice(k, 1); matched.add(i); free.add(i); } }
  // A COLOUR CANNOT BE PUT IN A DRAWER. Every innate colour sits on one of the
  // weapon's slots, so one no mod wants is not simply absent: it goes on a
  // mod-less slot (free) or on a modded one (+25%) — unless a Forma spent
  // elsewhere overwrites it, which each one bought does for nothing because the
  // bill is `max(added, removed)`. So this many are STUCK on a mod, and they go
  // on the smallest drains there are. Mirrors `engine::mods::plan_forma`.
  const stuck = () => order.slice().reverse().filter(({ i }) => !matched.has(i))
    .slice(0, Math.max(0, poolSize - matched.size - spareSlots));
  const drainOf = () => {
    const stick = new Set(stuck().map((x) => x.i));
    return filled.reduce((s, x) => s + (matched.has(x.i) ? Math.ceil(bd(x) / 2)
      : stick.has(x.i) ? Math.round(bd(x) * 1.25) : bd(x)), 0);
  };
  // AS LITTLE UMBRA AS POSSIBLE, BUT NEVER FAIL FOR WANT OF IT — the rule
  // `engine::mods::fit` follows, and the page has to follow it too or the two
  // answer differently on the same build. Umbra Forma is the scarce item, so a
  // pass that fits without one is taken over a cheaper-looking one that spends
  // it: an Umbra mod simply pays full drain until nothing else will do.
  const polarize = (umbra) => {
    const next = order.find(({ i, m }) => !matched.has(i) && (umbra || m.polarity !== "Umbra"));
    if (!next) return false;
    matched.add(next.i);
    return true;
  };
  while (drainOf() > cap) { if (!polarize(false)) break; }
  while (drainOf() > cap) { if (!polarize(true)) break; }
  // The innate pool is FREE, so only the slots this plan had to BUY count
  // against the floor — the same order the engine works in, where the pool is
  // spent before `at_least` is looked at. It spends REGULAR polarizations by
  // preference for the same reason the fit above does.
  while (matched.size - free.size < formaMin(w)) {
    if (!polarize(false) && !polarize(true)) break;
  }
  for (const { i, m } of filled) slots[i].pol = matched.has(i) ? m.polarity : null;
  // WHERE THE LEFTOVER COLOURS LAND. A mod-less slot first, at the position the
  // weapon was born with it where that is free — nothing there can mismatch, so
  // keeping the colour costs the reader nothing. What is left over from THAT is
  // the `stuck` set above; anything past both is overwritten by a Forma this
  // plan is spending anyway. An empty build therefore reports 0 Forma.
  const left = pool.slice();
  const emptyAt = (f) => slots.findIndex((s, i) => i < slotCount && !s.mod && !s.pol && f(s, i));
  for (const home of [true, false]) {
    for (let n = 0; n < left.length;) {
      const k = emptyAt((s, i) => !home || innate[i] === left[n]);
      if (k < 0) { n++; continue; }
      slots[k].pol = left[n]; left.splice(n, 1);
    }
  }
  stuck().forEach((x, n) => { slots[x.i].pol = left[n] || null; });
}

// ---- render mods ----
// WHICH POLARITIES WE SHIP ART FOR. `imgTag` hides an image that fails to load,
// so a polarity with no icon draws NOTHING — which is exactly what an empty
// slot draws, and the reader cannot tell "unpolarised" from "polarised in a
// colour this page has no picture of".
//
// The Vinquibus is why it matters: it is "Innate one Madurai and one Aura
// polarities", the wiki hosts no Aura_Pol.svg, and an invisible icon would put
// the page back to claiming the slot is free when it is a +25% penalty. A named letter says more than a missing picture.
const POL_ART = new Set(["Madurai", "Naramon", "Vazarin", "Umbra", "Omni"]);
// ITS OWN, because `cap` is a LOCAL helper inside two other functions and using
// it here threw `cap is not defined` on every render (caught by
// check_debuff_coverage, 2026-08-21).
const polCap = (s) => String(s || "").replace(/^./, (c) => c.toUpperCase());
const polGlyph = (pol) => POL_ART.has(polCap(pol))
  ? imgTag(POL(polCap(pol)), "pol")
  : `<span class="pol pol-txt">${escHtml(polCap(pol).slice(0, 1))}</span>`;

function polBtn(pol, i) {
  const t = pol ? `${polCap(pol)} — ${tr("change polarity")}` : tr("change polarity");
  return `<button class="pol-btn" data-i="${i}" title="${escHtml(t)}">${pol ? polGlyph(pol) : '<span class="nopol">◇</span>'}</button>`;
}
function renderMods() {
  // The quick-calc bar sits above this block and is measured against the same
  // build, so it redraws with it.
  if (typeof renderQuickCalc === "function") renderQuickCalc();
  // ...and so does the mode control: equipping a Cannonade is what takes the
  // cycle away, so the reason it is greyed changes with the slots.
  if (typeof renderMode === "function") renderMode();
  if (typeof renderAssembly === "function") renderAssembly();
  // ...and so does what the BOARD would say about it. The panel's "this one is
  // not sent" is the door's own answer now, so it has to be re-asked when the
  // build it is about changes.
  if (typeof refreshBoardDoor === "function") refreshBoardDoor();
  const used = capacityUsed();
  const cap = capOf($("weapon").value) + stanceGrant();
  const capEl = $("capacity");
  capEl.textContent = `${used} / ${cap}`;
  capEl.classList.toggle("over", used > cap);
  const f = formaCount();
  $("forma").textContent = [`${f.regular} Forma`, f.umbra ? `${f.umbra} Umbra` : null, f.omni ? `${f.omni} Omni` : null]
    .filter(Boolean).join(" · ");

  const box = $("mod-slots");
  box.innerHTML = "";
  for (let i = 0; i < 8; i++) box.appendChild(buildSlot(i));

  // Exilus: a REAL slot (utility mods only, drain counts) — absent on sentinels.
  // A sentinel weapon has no exilus slot, so it shows no exilus block —
  // label included. Standing a placeholder where the slot would be says
  // "something is missing here"; the truth is that nothing belongs there.
  const hasExilus = weaponAxes().hasExilus;
  show("exilus-block", hasExilus);
  const ex = $("exilus");
  ex.innerHTML = "";
  if (hasExilus) ex.appendChild(buildSlot(EXILUS));

  // THE STANCE SLOT, on a weapon that has stances to put in it. Asked of the
  // POOL rather than of the slot — `hasStance` is "this weapon's pool holds a
  // stance", which is the only honest test: a melee class whose stances nobody
  // has transcribed yet would otherwise show an empty slot with nothing to
  // offer, and that reads as a broken picker rather than as missing data.
  const hasStance = weaponAxes().hasStance;
  show("stance-block", hasStance);
  const st = $("stance");
  st.innerHTML = "";
  if (hasStance) st.appendChild(buildSlot(STANCE));
  refreshPanel();
}

// The current build as a request payload — shared by /api/panel and
// /api/simulate so the stats panel and the sim always agree on the loadout.
// Mods keep slot order (elements are position-sensitive).
//
// It carries the TENNO as well as the weapon, because half of what a build is
// worth is a question about the player: a mod gated `while_invisible` pays or
// does not, and Primary Bulwark is worth +500% or nothing depending on the
// frame's armor. A panel resolving against the NEUTRAL player while the sim
// resolves against the fight's offers a buff card the sim never runs, and
// hides a contribution the sim is paying. One player, both
// answers. The scenario fields that describe the
// PLAYER rather than the fight.
const TENNO_KEYS = ["aiming", "invisible", "airborne", "overshields", "channeling", "melee_equipped", "solo_weapon", "frame", "wf_health", "wf_armor", "wf_energy", "wf_sprint", "extra_stats", "auras", "shards"];

// THE FIGHT'S OWN STAT BONUSES: what this weapon is handed by something that is
// not its build — a squad buff, a Warframe ability, an arcane on another weapon.
//
//. So they are not buffs: no trigger, no clock, no stack
// count. They join the same ADDITIVE buckets the mods feed, which is what
// makes them cheap to be right about — a scenario's +60% multishot and Split
// Chamber's +90% sum, exactly as
// two multishot mods would, and every lock still wins over them.
//
// NO ELEMENTS. An elemental mod is position-sensitive and enters a hierarchy,
// so "+90% Heat" is not a number, it is a place in an ordering.
const EXTRA_STAT_KEYS = [
  ["base_damage", "Base Damage"],
  ["multishot", "Multishot"],
  ["crit_chance", "Critical Chance"],
  ["crit_damage", "Critical Damage"],
  ["status_chance", "Status Chance"],
  ["status_damage", "Status Damage"],
  ["fire_rate", "Fire Rate"],
  ["reload_speed", "Reload Speed"],
  ["magazine", "Magazine Capacity"],
  // AMMO EFFICIENCY is the odd one and belongs here anyway: it is not a damage
  // bucket, it is a chance for a shot to cost NOTHING, and half a dozen sources
  // outside a build grant it. Worth zero under Infinite
  // ammo, which the Limits block above already says out loud.
  ["ammo_efficiency", "Ammo Efficiency"],
];

/// THE WARFRAME ROSTER, and what picking one means: it fills armor, max energy
/// and sprint speed at once. Sprint is the one that could not be set at all
/// before — there was no field for it — so every "With Sprint Speed 1.2 or
/// Higher" perk in the roster was unreachable from this page.
///
/// The numbers stay EDITABLE after a pick, because the roster is unmodded: a
/// built frame carries Steel Fiber and Primed Flow and this one does not, and
/// "With Energy Max Over 700" is a gate no frame can open at all (the highest
/// maxed pool in the game is 300). Replacing the fields with a dropdown would
/// have made that unaskable.
const frames = () => (META && META.frames) || [];
const frameOf = (id) => frames().find((f) => f.id === id);

// The fight's player, as request fields. Its own function because three
// callers need exactly this subset and a fourth will: it is the actor, not the
// scenario, and the enemy half of the scenario has no business travelling with
// a panel request.
function tennoPayload() {
  return Object.fromEntries(TENNO_KEYS.map((k) => [k, sim[k]]));
}

function buildPayload() {
  return {
    ...tennoPayload(),
    weapon: $("weapon").value,
    evolutions: Object.values(evoSel).filter(Boolean),
    // One per pool, in the weapon's pool order — the server reads either
    // this or a bare value, so an old saved build still means what it meant.
    arcane: arcanes,
    arcane_rank: arcaneRanks,
    mods: slots.filter((s) => s.mod).map((s) => s.mod),
    // HOW IT IS PLAYED, from the BUILD. Riding in the scenario as `form` lets
    // the FIGHT decide how a weapon is fired, so the official ruler silently
    // plays every Incarnon weapon through its cycle and "never transmuting"
    // cannot be asked for.
    mode,
    // THE VALENCE, as two flat fields rather than an object: `base_for` reads
    // them off the request the same way it reads the deployment, and every
    // path that builds a weapon for a request goes through it.
    valence_element: valence.element,
    valence_bonus: valence.bonus,
    // THE PARTS, as an object, because they are one fact: `assembly_of` reads
    // the pair and repairs it part by part. Omitted entirely on a weapon that
    // has none, so the wire says nothing rather than saying `null`.
    ...(assembly ? { assembly: { ...assembly } } : {}),
    // A `riven:` id means nothing without the riven itself — it is the
    // visitor's item, not a pool entry, so it rides along with the request.
    rivens: rivenPayload(),
  };
}

/// THE INVERSE OF `buildPayload` — a request back into builder state, and the
/// ONLY translation left between the two.
///
/// It exists so that nothing else has to translate. An optimizer row carries
/// `replay`, a complete simulate request the SERVER authored from the very
/// candidate it scored, and "+ add" applies it through here — instead of the
/// page re-deriving a build from a description of one, which is what dropped an
/// axis four times. What makes this pair safe where a hand-written producer was
/// not is that it is a PAIR: `buildPayload(stateFromBuild(p)) === p` is a
/// property one check can assert over a build with every axis set, and it fails
/// for any axis either side forgets. Counting fields cannot say that.
///
/// `exilusId` is the one thing a payload cannot state. The wire carries ONE
/// flat list of mod ids — which is what the engine resolves, and the number
/// never depends on which slot they sat in — so the ninth slot is a matter of
/// LAYOUT (its polarity, the Forma plan) and the caller that knows says so. An
/// optimizer row does; a share link and a board row do not, and take the order
/// the list is in.
function stateFromBuild(p, weapon, exilusId) {
  const w = weaponInfo(weapon) || {};
  const ids = (p.mods || []).filter(Boolean);
  // THE STANCE IS TOLD APART BY LOOKING AT IT, which is the whole reason it
  // needs no field of its own on the wire — where the exilus id has to be
  // PASSED IN, because an exilus-eligible mod is legal in a main slot and the
  // list alone cannot say which entry came out of which slot.
  const stanceId = ids.find((id) => (modById(id) || {}).stance);
  const main = ids.filter((id) => id !== exilusId && id !== stanceId);
  const sl = Array.from({ length: 10 }, () => ({ mod: null, pol: null, rank: null }));
  main.slice(0, 8).forEach((id, i) => { sl[i].mod = id; });
  if (exilusId && exilusId !== "none" && ids.includes(exilusId)) {
    sl[EXILUS].mod = exilusId;
  } else if (main.length > 8) {
    sl[EXILUS].mod = main[8];
  }
  if (stanceId) sl[STANCE].mod = stanceId;
  // A RANK IS THE CARD'S CEILING. The wire carries no mod rank at all — the
  // engine reads a maxed card, which is what every number in this app is
  // measured at — so this is the page filling in what it alone displays.
  sl.forEach((s) => { if (s.mod && modById(s.mod)) s.rank = modById(s.mod).max_rank; });
  const evo = { 1: null, 2: null, 3: null, 4: null };
  (p.evolutions || []).forEach((id) => {
    const t = (w.evolutions || []).find((tt) => tt.options.some((o) => o.id === id));
    if (t) evo[t.tier] = id;
  });
  const nPools = arcanePools(weapon).length;
  return buildState(weapon, {
    slots: sl,
    evoSel: evo,
    arcane: asArcaneList(p.arcane, nPools).map((x) => x || "none"),
    arcaneRank: asArcaneList(p.arcane_rank, nPools).map((x) => x ?? null),
    // BOTH HALVES OR NEITHER. `restoreState` cleans them against the weapon
    // being opened, so a payload naming an element this spec does not offer
    // lands on the default rather than on a weapon nobody has.
    // `null` WHEN THE REQUEST CARRIES NONE, meaning "the weapon's own default"
    // — which is what an omitting request meant and what the server itself
    // used. It was `undefined`, on the same reasoning and one step short of it:
    // `defaultMode`/`defaultValence`/`defaultAssembly` all read `null` as that
    // instruction, and `undefined` is DELETED BY `JSON.stringify` on the way
    // into a preset. So a producer that carefully NAMED the axis handed over an
    // object that had lost it, which is precisely what `BUILD_AXES` exists to
    // catch — and did (check_valence, 2026-08-24, on an optimizer winner's
    // saved build).
    mode: p.mode || null,
    valence: p.valence_element
      ? { element: p.valence_element, bonus: p.valence_bonus }
      : null,
    assembly: p.assembly || null,
  });
}

// ---- Stats panel: merged buckets, each explained by source ----

/// WHAT THE PANEL ON SCREEN WAS BUILT FROM. Null until the first one lands.
let panelKey = null;

/// The build, as a value. Same idea as `simKey`: a key DERIVED from the state,
/// never a hand-listed set of things that ought to trigger a refresh.
const buildKey = () =>
  JSON.stringify([$("weapon").value, slots, arcanes, arcaneRanks, evoSel, rivenPayload(),
                  assembly]);

/// THE PANEL REFRESHES BECAUSE THE BUILD CHANGED, not because a control
/// remembered to say so.
///
/// Making every mutation responsible for calling `refreshPanel` is N places to
/// get right: the picker redraws its own slots while the panel — and the sim's
/// buff bar — keeps showing the previous arcane until an unrelated edit happens
/// to
/// refresh them (reported 2026-08-05). Fixing that one site would have left the
/// same trap for the next control someone adds.
///
/// So the trigger is derived instead. After any interaction anywhere, if the
/// build no longer matches what the panel was built from, the panel is rebuilt.
/// A control cannot forget, because it is never asked: this is the same rule
/// `check_gain_freshness` already asserts for the gain scan — the cache key is
/// DERIVED from the thing it describes, never a copy of it maintained by hand.
///
/// The explicit calls that remain are not redundant belt-and-braces; they make
/// the refresh IMMEDIATE rather than waiting for the next event. This is what
/// makes it CORRECT.
function panelWatchdog() {
  // After the handler that caused it, not during — a click that mutates state
  // runs its own listener first.
  setTimeout(() => {
    if (panelKey !== null && buildKey() !== panelKey) refreshPanel();
  }, 0);
}
for (const ev of ["click", "change", "input", "keyup"]) {
  document.addEventListener(ev, panelWatchdog, true);
}

let panelTimer = null;
function refreshPanel() {
  markPresetDirty(); // every build change funnels through here
  clearTimeout(panelTimer);
  panelTimer = setTimeout(async () => {
    const body = buildPayload();
    // Recorded where the payload is actually BUILT, so the key always
    // describes what was sent — recording it at call time would go stale
    // inside the debounce window.
    panelKey = buildKey();
    try {
      const r = await api("/api/panel", body);
      renderPanel(r);
    } catch (e) {
      $("stats-rows").innerHTML = `<div class="error">panel failed: ${e}</div>`;
    }
  }, 120);
}

function renderPanel(r) {
  if (!r || r.ok === false) {
    $("stats-rows").innerHTML = `<div class="error">${r ? r.error : "no data"}</div>`;
    return;
  }
  $("stats-sub").textContent = `max-rank values · ${r.policy}`;
  // A PASSIVE WE DO NOT MODEL makes every number below a FLOOR, and the reader
  // has no way to know that from the numbers themselves. Gotva Prime is the
  // first: its "15% chance to set the next hit's crit chance to 300%" is absent, so it scores like a weapon without a passive and looks simply
  // weaker rather than partly unmodelled.
  const wInfo = weaponInfo($("weapon").value) || {};
  const passiveNote = $("stats-passive");
  if (passiveNote) {
    // WHAT THIS WEAPON'S ENTRY DOES NOT MODEL, said in words, above the numbers
    // that omit it. Two sources, one banner: · the
    // PASSIVE flag, for a weapon whose prose passive has no rule yet; ·
    // `unmodeled`, the weapon file's own list — the bulk Incarnon intake
    // writes one line here per base attack part it could not carry, and a
    //     bow's uncharged shot or the Angstrum's explosion is exactly the kind
    //     of gap that makes a complete-looking number wrong.
    // A yaml comment is honest to whoever opens the file and invisible to
    // everyone else, which is not the same as honest.
    const gaps = gapsOf(wInfo).slice();
    if (wInfo.passive_unmodeled) {
      gaps.unshift(tr("this weapon's passive is not modelled yet"));
    }
    passiveNote.hidden = !gaps.length;
    passiveNote.innerHTML = gaps.length
      ? `<div class="unmod-h">◈ ${escHtml(tr("not modelled on this weapon — the numbers below are a floor, not its full output"))}</div>`
        // THROUGH `tr`, like the enemy card's gaps. These are OUR sentences,
        // not DE's, so they translate rather than being transcribed — and a
        // line with no entry falls through to the English it was written in,
        // which is the overlay's whole contract. Rendering them raw left a
        // Chinese page with the one paragraph that matters in English.
        // Through `trGap`, which knows a REASON from a sentence: a repeating
        // gap carries its template and parameters, so the overlay translates
        // the template once instead of once per set of numbers.
        + gaps.map((g) => `<div class="unmod-l">${escHtml(trGap(g))}</div>`).join("")
      : "";
    // …AND THE OPPOSITE ADMISSION, in its own block. A LIVE BUG says the number
    // IS right — measured, reproduced — and that nobody can explain it, so a
    // hotfix could take it away. Filing it under "not modelled" would tell the
    // reader the number is a floor, which is the one thing it is not.
    //
    // The case it exists for: the Laetum's Incarnon form pays Secondary
    // Irradiate's echo at 3.6x the hit while the arcane's own card, on the same
    // screen, prints DE's 180%. A number that departs from the card beside it
    // and says so nowhere reads as a bug, and it was reported as one. VERBATIM, not through `trGap`: these are OUR sentences and
    // they translate, but they carry no template holes.
    const bugs = (wInfo.live_bugs || []).slice();
    if ($("stats-livebug")) {
      $("stats-livebug").hidden = !bugs.length;
      $("stats-livebug").innerHTML = bugs.length
        ? `<div class="unmod-h">⚠ ${escHtml(
            tr("measured on this weapon and unexplained — the engine reproduces what the game does, and a hotfix could change it"))}</div>`
          + bugs.map((b) => `<div class="unmod-l">${escHtml(tr(b))}</div>`).join("")
        : "";
    }
  }
  // A source the row's LOCK is ignoring still lists, struck through and said
  // out loud: "Fire Rate cannot be modified" means this mod's bonus is not in
  // the number above, and a line that looks like every other line claims the
  // opposite.
  const srcLine = (s) =>
    `<div class="ssrc${s.ignored ? " sdead" : ""}"${s.ignored ? ` title="${escHtml(tr("ignored — this stat is locked at the weapon's default"))}"` : ""}>${s.value} — ${s.mod}${s.note ? ` <span class="snote">(${s.note})</span>` : ""}${s.ignored ? ` <span class="snote">(${escHtml(tr("ignored"))})</span>` : ""}</div>`;

  // THE MULTIPLICATIVE BUCKET, DRAWN (community request, 2026-08-05: the app
  // does the hard arithmetic and then shows only its answer, so the mechanics
  // stay as murky as they were).
  //
  // Warframe damage is a product of buckets: bonuses inside one bucket ADD,
  // buckets MULTIPLY. Which bucket a mod lands in is the single most useful
  // thing to know about it — adding to a bucket already at +200% is worth far
  // less than opening a new one — and the panel already had every number
  // needed to show it, arranged so you could only infer it.
  //
  // So draw the expression: `40.0 × (1 + 1.65 + 0.60) = 130`. Everything inside
  // one bracket is one bucket, and that shape needs no sentence to explain it.
  // It is the reader's OWN build's arithmetic, which is the thing a wiki cannot
  // give them.
  //
  // ONLY WHEN EVERY TERM IS A FRACTION. Evolution sources send no `frac`
  // because several are flat additions rather than percentages, and a line that
  // rendered them as `+ 0.5` would be asserting arithmetic the engine did not
  // do. Fewer than two terms is left alone as well — `40 × (1 + 1.65)` teaches
  // nothing that `40 → 106` did not.
  const bucketLine = (row) => {
    const src = row.sources || [];
    // A LOCKED row has no arithmetic to draw: its bucket was emptied, so
    // `3.3 × (1 - 0.20) = 3.3` would be a false equation printed in the one
    // place that exists to show the real one.
    if (row.locked_by) return "";
    if (src.length < 2 || !src.every((x) => typeof x.fraction === "number")) return "";
    const base = String(row.base || "").replace(/[^0-9.\-]/g, "");
    if (!base || row.base === "—") return "";
    const terms = src
      .map((x) => `<span class="bterm" title="${escHtml(x.mod)}">${x.fraction.toFixed(2)}</span>`)
      .join(" + ");
    return `<div class="sbucket">${escHtml(base)} × ( 1 + ${terms} ) = <b>${escHtml(row.final)}</b>` +
      ` <span class="bhint" title="${escHtml(
        tr("everything inside the bracket is ONE multiplicative bucket: these add together, and the bucket multiplies against the others"),
      )}">?</span></div>`;
  };

  const rowHtml = (row) => `
    <div class="srow">
      <div class="shead"><span class="sk">${tr(row.label)}</span>
        <span class="sv">${row.base !== "—" && row.base !== row.final ? `<span class="sbase">${tr(row.base)}</span> → ` : ""}<b>${tr(row.final)}</b></span></div>
      ${row.rule ? `<div class="srowrule" title="${escHtml(tr("the rule this weapon is computed under: how the bonus combines, what base it reads, and which attack parts take it"))}">▸ ${escHtml(row.rule)}</div>` : ""}
      ${row.note ? `<div class="srownote">⚙ ${row.note}</div>` : ""}
      ${row.locked_by ? `<div class="srownote">🔒 ${escHtml(tr("locked at the weapon's default by"))} ${escHtml(row.locked_by)}</div>` : ""}
      ${bucketLine(row)}
      ${(row.sources || []).map(srcLine).join("")}
    </div>`;
  const dmgHtml = (p) => (p.damage && p.damage.length)
    ? `<div class="sdmg-title">${tr("Damage (combined)")} — ${p.damage_total} ${tr("total")}</div>` +
      p.damage.map((d) => `<div class="sdmg"><span class="sk">${DT(d.type)}</span><span class="sv"><b>${d.amount}</b> <span class="snote">${d.share}</span></span></div>`).join("")
    : "";
  // A weapon is the GUN plus the PROJECTILE(s) it launches: the gun block
  // carries cadence and capacity, each projectile block its own damage,
  // crit and status — and a radial its blast geometry too. An Incarnon
  // Laetum shot is two instances, so it renders two projectile blocks.
  const partHtml = (p) => `
    <div class="fpart" data-part="${p.id}">
      <div class="fparth">${tr(p.label)}<span class="fmeta">${tr(p.meta)}</span></div>
      ${(p.stats || []).map(rowHtml).join("")}
      ${dmgHtml(p)}
    </div>`;
  // EVERY available form renders as its own section (base + Incarnon side
  // by side — no switching), headed by the form name + trigger mechanics.
  // Indirect stats (recoil, accuracy, ammo…) render like any bucket — they
  // are outside theoretical DPS but real in practice, so the panel states them.
  const section = (f) => `
    <div class="fsec">
      <div class="fhead">${tr(f.label)}<span class="fmeta">${f.meta}</span></div>
      ${[...(f.stats || []), ...(f.elements || []), ...(f.indirect || [])].map(rowHtml).join("")}
      ${(f.parts || []).map(partHtml).join("")}
    </div>`;
  $("stats-rows").innerHTML = (r.forms || []).map(section).join("");
  $("stats-damage").innerHTML = "";

  // WHO IS HOLDING THE GUN, stated before the clauses that read it. Several perks and mods are answered by the PLAYER — a gate at
  // 200 max energy, a bonus per 75 health, Primary Bulwark past 1,000 armor —
  // and the panel listed those clauses while saying nothing about the numbers
  // deciding them. The fields above read "0 = no frame", which is what they
  // MEAN and not what the fight resolved to once a frame, an aura or an archon
  // shard had moved them.
  //
  // The numbers are the SERVER's, from the same `tenno_from` every gate is
  // asked against, so this cannot drift from what was actually simulated.
  const wf = r.tenno;
  $("stats-conditionals").innerHTML = (wf
    ? `<div class="sdmg-title">${escHtml(tr("Who is holding it"))}</div>` +
      // ITS OWN CLASS, not `.scond`: that class IS the list of conditional
      // clauses, and `#stats-conditionals .scond` is how they are counted.
      `<div class="swielder">` + [
        [tr("Health"), wf.health], [tr("Armor"), wf.armor],
        [tr("Max energy"), wf.energy], [tr("Sprint"), wf.sprint],
      ].map(([l, v]) => `<span><b>${escHtml(l)}</b> ${sig2(v || 0)}</span>`).join("")
      + `</div>`
    : "") + ((r.conditionals && r.conditionals.length)
    ? `<div class="sdmg-title">Conditional / not merged</div>` +
      r.conditionals.map((c) => `<div class="scond ${c.active ? "" : "off"}"><b>${c.mod}</b>: ${c.desc} <span class="snote">${c.why}</span></div>`).join("")
    : "");
  // The build's configurable buffs (weapon-scoped) drive the Sim section 2.
  buffList = r.buffs || [];
  renderSimBuffs();
}

// Wiki page for an item, from its display name (the data files' source
// urls follow the same Name_With_Underscores convention).
const wikiUrl = (name) => "https://wiki.warframe.com/w/" + encodeURIComponent(name.replace(/ /g, "_"));
// EVERY item name (mod / arcane / evolution) opens its wiki page in a new
// tab; the click never triggers the card's own handlers.
// ALWAYS pass an explicit url built from the ENGLISH name (x.name_en ||
// x.name) — `text` is the displayed (possibly localized) name, and the
// wiki only has English page names. The no-url fallback exists for plain
// English literals only.
const wl = (text, url) => `<a class="wl" href="${url || wikiUrl(text)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${text}</a>`;

/// THE WIKI PAGE BEHIND A MOD CARD — and a RIVEN'S IS THE MECHANIC'S.
///
/// Every other mod is one published card with one page. A riven is generated:
/// "Argon Critacan" is a name a drop invented, the wiki has no page by it, and
/// building the URL from the name the way the rest do gives a link that always
/// 404s. What a reader clicking a riven wants is the mechanic — disposition,
/// rolling, the stat pools — which is `Riven Mods`.
const modWikiUrl = (m) => (m.riven ? wikiUrl("Riven Mods") : wikiUrl(m.name_en || m.name));

// Description lines at a rank: the verbatim in-game text with the
// rank-varying numbers filled server-side (mods and arcanes alike). Null
// when the pool has no yaml description (hardcoded rifle pool) — callers
// fall back to the model's effect lines.
const descAt = (o, r) => o.desc_ranks
  ? o.desc_ranks[Math.max(0, Math.min(o.desc_ranks.length - 1, r))].split("\n")
  : null;

// The SAME card, in DE's own words, when the active locale has them
// (data/i18n/<locale>/descriptions.yaml — mods and arcanes, one entry per
// rank). Preferred over translating our English line, because a card is not
// a bag of terms: "(x2 for Bows)" is "（弓类武器效果加倍）", which no phrase
// table reaches. Ids never collide across the two tables (engine test).
const officialDesc = (o, r) => {
  if (!I18N || !o || !o.id) return null;
  const t = (I18N.mod_descriptions || {})[o.id] || (I18N.arcane_descriptions || {})[o.id];
  return t && t.length ? t[Math.max(0, Math.min(t.length - 1, r))].split("\n") : null;
};

// Card lines at a rank, ALREADY in the display language: DE's sentence when
// there is one, otherwise our English line with the phrase table applied.
// Every caller renders these verbatim — nothing runs `tf` over a line that
// was already written in the target language.
// An EVOLUTION's card lines. Same rule as a mod's, with one difference that
// matters: when the locale has no transcription, the English falls through
// UNTOUCHED. Running the phrase table over prose is what produced
// "Increase Base 伤害 by +60." — half-swapped is worse than either language,
// and evolutions are the only card written as prose rather than as terms.
// `o.effects` (our own model statement) IS term-shaped, so it still gets tf.
const evoLines = (o) => {
  const zh = I18N && (I18N.evolution_descriptions || {})[o.id];
  if (zh) return zh.split("\n");
  if (o.desc && o.desc.length) return o.desc;      // English, as written
  return (o.effects || []).map(tf);
};

// WHAT WE DO NOT MODEL, appended to whatever the card already says.
//
// Not a replacement: DE's own text is what makes a player expect the thing to
// work, so hiding our gap behind it is the worst of both. `cardLines` prefers
// `officialDesc`, which every one of these has — so a "not modeled" line the
// model produced is suppressed on precisely the items that need it, which is
// how 5 arcanes and 12 mods carried a knowingly skipped effect in silence.
// TWO DIFFERENT ADMISSIONS, and saying "not modelled" for both is what made the
// whole app look unfinished. One is a todo; the other is the edge
// of what a single-target damage simulator IS.
/// AN EVOLUTION'S THREE ADMISSIONS, as chips. A player deciding what to equip
/// needs to know which they are looking at: a todo may be gone next week, an
/// EDGE is what a single-target damage simulator is.
///
/// AND THE THIRD IS NOT A SHORTFALL AT ALL: a clause the GAME does not pay out
/// (M49). It is the chip whose reader ACTION differs most — the other two say
/// wait for us, this one says do not pick the perk for that half, because
/// nobody is going to implement what DE has not shipped.
const evoGapChips = (o, tag) => {
  const todo = o.unmodeled || [];
  const edge = o.out_of_scope || [];
  const dead = o.live_bugs || [];
  const out = [];
  if (todo.length) {
    out.push(`<${tag} class="exchip unmod" title="${escHtml(
      (o.fully_unmodeled && !edge.length
        ? tr("this perk does nothing in the simulation — the model has no rule for it yet")
        : tr("part of this perk is not modelled — what it does here is less than the card says")
      ) + ": " + todo.join(", "))}">${
      escHtml(o.fully_unmodeled && !edge.length ? tr("not modelled yet") : tr("partly modelled"))}</${tag}>`);
  }
  if (edge.length) {
    out.push(`<${tag} class="exchip scope" title="${escHtml(
      tr("this cannot pay out in a one-target fight — it is an edge of the model, not a gap in it")
      + ": " + edge.map((x) => tr(x)).join(" · "))}">${escHtml(tr("nothing to earn here"))}</${tag}>`);
  }
  if (dead.length) {
    out.push(`<${tag} class="exchip livebug" title="${escHtml(
      tr("the card states this and the game does not do it — measured, and the simulation matches the game rather than the card")
      + ": " + dead.map((x) => tr(x)).join(" · "))}">${escHtml(tr("does not work in game"))}</${tag}>`);
  }
  // A FIFTH CHIP, and the second that is not a shortfall of ours — the OPPOSITE
  // advice to the one above it. A live bug says the card is right and the game
  // is broken, so do not pick the perk; a MISPRINT says the effect works and
  // the card is wrong ABOUT it, so pick it for a reason the card does not
  // state. Owner, 2026-08-18: anything that differs from what the game displays
  // is to be noted, and a note nobody can see on the card is not one.
  const wrong = o.misprints || [];
  if (wrong.length) {
    out.push(`<${tag} class="exchip misprint" title="${escHtml(
      tr("this works, and its own card describes it wrongly — the simulation follows the game")
      + ": " + wrong.map((x) => tr(x)).join(" · "))}">${escHtml(tr("card is wrong"))}</${tag}>`);
  }
  return out.length ? " " + out.join(" ") : "";
};

const notModeledLines = (o) => {
  const out = [];
  if (o.not_modeled) {
    out.push(`<span class="unmodeled" title="${escHtml(
      tr("real damage the simulator does not compute yet"),
    )}">⊘ ${escHtml(tr("not modelled yet"))}</span>`);
  }
  // PARTLY modelled: the mod works, and one named effect on it does not. A
  // third line rather than a third flag, because "not modelled yet" over a card
  // that lands 1,000 damage a blast is as wrong as saying nothing.
  const partial = o.unmodeled_effects || [];
  if (partial.length && !o.not_modeled) {
    out.push(`<span class="unmodeled part" title="${escHtml(
      // Each line TRANSLATED, not the label only. An arcane's are short derived
      // tokens with no zh entry and `tr` hands those straight back, so this
      // costs them nothing — but an ABILITY writes whole sentences here, and
      // one of them went out raw the first time (the same way the disclosure
      // banner's paragraph did).
      tr("everything else on this card is modelled; this is not:") + " " +
        partial.map((x) => tr(x)).join(", "),
    )}">⊘ ${escHtml(tr("partly modelled"))}</span>`);
  }
  if (o.out_of_scope) {
    out.push(`<span class="unmodeled oos" title="${escHtml(
      tr("this acts on something a weapon-damage simulator has none of — Warframe energy, enemy behaviour, movement — so it would change no number here"),
    )}">◇ ${escHtml(tr("outside the sim"))}</span>`);
  }
  // A FOURTH ADMISSION, and the only one that is not a shortfall: this IS
  // modelled, it matches the live game, and DE did not mean it to work this way. The other three say the number is lower than the
  // card; this one says the number is right today and a hotfix takes it away,
  // which is a different thing for a player to know before building around
  // it.
  for (const why of o.live_bugs || []) {
    out.push(`<span class="livebug" title="${escHtml(
      tr("this matches the live game and is a bug — DE may patch it, and the number here changes when they do") + ": " + tr(why),
    )}">⚑ ${escHtml(tr("unintended, modelled as it plays"))}</span>`);
  }
  return out;
};

const cardLines = (o, r, fallback) =>
  (officialDesc(o, r) || (descAt(o, r) || fallback || o.effects || []).map(tf))
    .concat(notModeledLines(o));

// One slot card (regular or exilus) with its polarity / rank / menu wiring.
function buildSlot(i) {
  // AN INDEX WITH NO ENTRY IS AN EMPTY SLOT, and this has to be total over the
  // nine of them. `slots` starts empty and is filled while a weapon is applied,
  // so anything that redraws the build during that window — the riven names
  // arriving, say — asked for a slot that did not exist yet and took the whole
  // page down with it, at boot, for everyone.
  const s = slots[i] || {};
  const el = document.createElement("div");
  const m = s.mod ? modById(s.mod) : null;
  // THE SLOT'S NUMBER, because the picker already speaks it and the grid did
  // not answer. A placed mod's chip in the picker reads "slot 5", and the eight
  // slots are drawn two to a row — so nothing on screen said whether 5 was the
  // third row's left cell or the first column's fifth (player report via the
  // owner, 2026-08-10).
  //
  // It is not decoration: the same mod is worth something different in another
  // slot, because ELEMENTS COMBINE IN SLOT ORDER. A player rearranging for
  // Corrosive instead of Radiation is reading exactly this number.
  //
  // The exilus slot is left unnumbered: there is one of it, its block is
  // labelled, and the picker calls it "exilus" rather than a number.
  if (m) {
    el.className = "slot filled" + (m.rarity ? " rar-" + m.rarity : "");
    const r = s.rank == null ? m.max_rank : s.rank;
    const base = modDrain(m, r);
    const eff = slotDrain(base, m.polarity, s.pol);
    const lowered = r < m.max_rank;
    const rank = m.max_rank > 0
      ? `<span class="rank ${lowered ? "lowered" : ""}"><button class="rk" data-d="-1">−</button><b>R${r}${lowered ? "/" + m.max_rank : ""}</b><button class="rk" data-d="1">+</button></span>`
      : "";
    // The configured mod shows its CURRENT description (values at the
    // slot's rank), exactly like the in-game card.
    //
    // ASKED THE WAY THE PICKER ASKS IT. This required a `desc_ranks` or an
    // official description, which a RIVEN has neither of — its card text is its
    // rolled stats, printed by the engine and carried on `effects`. So the same
    // riven listed its lines in the picker and lost them the moment it was
    // equipped, which is the one place a player reads them while building.
    // `cardLines` already falls back to `effects`; the gate was the only thing
    // in the way, and dropping it makes the slot agree with the list it came
    // from rather than adding a second rule about what a card may say.
    const desc = cardLines(m, r);
    // WHAT THE SLOT'S COLOUR DID TO THIS MOD, said the way the arsenal says it:
    // the mod's OWN polarity next to the number, and the number coloured for
    // the three answers — matched halves it, a different colour adds 25%, an
    // unpolarized slot is neither. The card carried the SLOT's colour and not
    // the mod's, so there was nothing on screen to compare it against and a
    // +25% surcharge read as an ordinary drain.
    const matchedPol = s.pol === m.polarity || (s.pol === "Omni" && m.polarity !== "Umbra");
    const fit = !s.pol ? "" : matchedPol ? " matched" : " mismatched";
    el.innerHTML = polBtn(s.pol, i) + imgTag(IMG(m.image), "mod") +
      `<div class="info"><div class="mn">${wl(m.name, modWikiUrl(m))}</div>${desc.length ? `<div class="me">${desc.map((x) => `<div>${x}</div>`).join("")}</div>` : ""}<div class="drow"><div class="dr${fit}"><span class="mpol" title="${escHtml(polCap(m.polarity))}">${polGlyph(m.polarity)}</span>${eff} drain${eff !== base ? ` (base ${base})` : ""}</div>${rank}</div></div>` +
      `<button class="dots" title="options">⋯</button>`;
    el.querySelector(".dots").addEventListener("click", (e) => { e.stopPropagation(); openModSlotMenu(i, e.currentTarget); });
    el.querySelectorAll(".rk").forEach((b) => b.addEventListener("click", (e) => {
      e.stopPropagation();
      const nr = Math.max(0, Math.min(m.max_rank, r + Number(b.dataset.d)));
      slots[i].rank = nr; renderMods();
    }));
  } else {
    el.className = "slot empty";
    el.innerHTML = polBtn(s.pol, i) + `<span class="plus">${i === EXILUS ? "+ add exilus mod" : "+ add mod"}</span>`;
    // the WHOLE empty slot opens the picker (the pol-btn stops propagation)
    el.addEventListener("click", (e) => { e.stopPropagation(); openPicker(i, el); });
  }
  // …AND NEITHER IS THE STANCE SLOT, for the same reason the exilus one is
  // unnumbered: there is one of it, its block is labelled, and the picker calls
  // it "stance" rather than a number. Numbered, it read as a tenth main slot.
  if (i !== EXILUS && i !== STANCE) {
    const no = document.createElement("span");
    no.className = "slotno";
    no.textContent = String(i + 1);
    // The same words the picker's chip uses, so the two are findable as one
    // thing rather than as a number and a coincidence.
    no.title = tr("slot") + " " + (i + 1);
    el.appendChild(no);
  }
  // polarity is decoupled: clickable on every slot (mod or empty, incl. innate)
  el.querySelector(".pol-btn").addEventListener("click", (e) => { e.stopPropagation(); openPolMenu(i); });
  return el;
}

// The DOM node for slot i (popover anchoring).
const slotEl = (i) =>
  i === EXILUS ? $("exilus").firstElementChild
  : i === STANCE ? $("stance").firstElementChild
  : $("mod-slots").children[i];

// ---- popovers ----
// EVERY popover, found by class rather than by a list that a new one has to
// remember to join — the enemy picker opened and would not close, because it
// was not on the list.
//
// `keep` is the node the new panel is anchored to: a popover that CONTAINS it
// stays open, which is what lets a dropdown live inside a picker (the mod
// picker's Sort control is inside `#mod-popover`) without the act of opening
// it closing the thing it belongs to.
function closePopovers(keep) {
  document.querySelectorAll(".popover").forEach((p) => {
    if (keep && p.contains(keep)) return;
    p.hidden = true;
  });
}

// ---- THE dropdown -------------------------------------------------------
//
// ONE choose-one control for the whole site, and not a new component: the
// panel is `.popover`, the search bar `.addbar`, the rows `.combo-menu .opt`,
// so a dropdown cannot drift from the pickers because it IS them.
//
// The SEARCH BAR appears on its own rule rather than always: a list of two is
// read at a glance and a search box over it is furniture, while six is where
// scanning stops being instant. `search: true` forces it for a growing list.
/// The trigger. Emits a button that LOOKS like the select it replaces, and
/// registers what opening it should show. Callers re-render by innerHTML, so
/// registration happens on every draw rather than once.
// EVERYTHING THIS COMPONENT IMPLEMENTS, named once.
//
// A native `<select>` gives `option.disabled` away for free, and a component
// that silently IGNORES the field keeps every caller passing it while the
// options stay clickable — an extra key costs the author nothing, which makes
// such a loss silent. So an unknown key is an ERROR rather than a no-op: it
// means the author expected a behaviour this component does not have, and loud
// is cheap here.
const DD_CFG_KEYS = ["value", "items", "dataK", "title", "placeholder", "onPick", "search",
  "data", "disabled", "axis", "axisLabel"];
// `badge` IS THE ONE RAW-HTML FIELD, and it exists because escaped text cannot
// carry a quick-calc gain. A gain is MARKUP — a class that colours
// it, a title that explains the band it was measured to, and a "…" while it is
// still being measured — so flattening it into `hint` would print "≈+3.1% ±7.2%"
// as words and lose the three shapes that make a chip readable at a glance.
//
// Raw means the CALLER escapes. The only producer is `gainChipFor`, which
// builds its own markup and escapes its own inputs; anything else passed here
// is an injection the component cannot see.
// `key` IS THE SCAN'S NAME FOR THIS ROW, and it is what makes the gain chip
// LIVE. Baking the chip into `badge` when the list is registered puts it
// before the scan that fills it has started, so the rows keep their first
// answer for ever and a freshly opened list shows none at all. It is computed
// at RENDER, like the mod picker's, and the order with it.
const DD_ITEM_KEYS = ["value", "label", "hint", "disabled", "group", "badge", "key"];

function ddCheck(id, cfg) {
  const stray = (obj, known) => Object.keys(obj).filter((k) => !known.includes(k));
  const bad = stray(cfg, DD_CFG_KEYS);
  if (bad.length) throw new Error(`dd "${id}": unknown config ${bad.join(", ")}`);
  (cfg.items || []).forEach((i, n) => {
    const b = stray(i, DD_ITEM_KEYS);
    if (b.length) throw new Error(`dd "${id}" item ${n}: unknown field ${b.join(", ")} — the component does not implement it`);
  });
}

function ddButton(id, cfg) {
  ddCheck(id, cfg);
  ddReg.set(id, cfg);
  const cur = cfg.items.find((i) => String(i.value) === String(cfg.value));
  // `value=` is not decoration: `HTMLButtonElement.value` REFLECTS it, so the
  // scenario panel's generic `[data-k]` binding — which reads `el.value` and
  // listens for `change` — keeps working unchanged across the swap. That is
  // also what keeps `el.disabled = true` meaningful on the optimizer tab,
  // where the whole fight is drawn read-only.
  // `data:` is the general form of `dataK` — a caller whose binding reads some
  // OTHER attribute (the ability element list reads `data-wfel`) declares it
  // here rather than rewriting the markup afterwards, which is what the first
  // swap did and is how a component grows a caller that escapes its own values. `disabled` is the same argument: the read-only optimizer tab
  // sets it on the ELEMENT, and a control that is born disabled had no way to
  // say so.
  const data = Object.entries(cfg.data || {})
    .map(([k, v]) => ` data-${k}="${escHtml(String(v))}"`).join("");
  return `<button type="button" class="dd" id="${id}" data-dd="${id}" value="${
    escHtml(String(cfg.value ?? ""))}"${cfg.dataK ? ` data-k="${escHtml(cfg.dataK)}"` : ""}${
    data}${cfg.disabled ? " disabled" : ""}${
    cfg.title ? ` title="${escHtml(cfg.title)}"` : ""}><span class="dd-v">${
    escHtml(cur ? cur.label : (cfg.placeholder || "—"))}</span><span class="dd-c">▾</span></button>`;
}

function ddRender(id, query) {
  const cfg = ddReg.get(id);
  if (!cfg) return;
  const q = (query || "").trim().toLowerCase();
  // SEARCH SPANS EVERYTHING THE ROW SHOWS — its label, its hint and its group.
  // A list of official builds is `#3 · Incarnon cycle` under a ruler whose name
  // carries the enemy, the level and the metric, so "no aim", "thrax" and
  // "cycle" all have to find rows or the search only works for people who
  // already know where things are.
  // RANKED AT RENDER, so a scan that lands while the list is open re-orders it
  // — the mod picker's own behaviour, and the reason a half-filled ranking
  // marks itself with "…" rather than pretending to be final.
  const items = cfg.axis
    ? [...cfg.items]
        .map((i) => ({ ...i, id: i.key, name: i.label }))
        .sort((a, b) => gainSort(a, b, ["gain", "name"]))
    : cfg.items;
  const hits = items.filter((i) => {
    if (!q) return true;
    const blob = [i.label, i.hint, i.group].filter(Boolean).join(" ").toLowerCase();
    // …and space-insensitively, for the same reason the mod list is: a
    // localized label carries spaces the player does not type.
    return blob.includes(q) || squash(blob).includes(squash(q));
  });
  // A DISABLED item stays LISTED and greyed: "the weapon has no Incarnon form
  // while that mod is on it" is information, and a vanished option is not. It
  // is `.dis`, and `.dis` is what the click binding below skips — the one
  // native `<select>` behaviour this component has to reproduce by hand, and
  // the one it silently dropped when the selects were replaced.
  //
  // IT KEEPS ITS `data-v`. Dropping the value was the first way this was
  // written, and it left a greyed row identifiable only by the words on it —
  // which is the thing that broke `check_opt_gain` the day an evolution got a
  // Chinese name. An option carries its identity whether or not it can be
  // clicked; being clickable is a separate fact and lives in the class.
  // GROUPED, where the data has a grouping. A flat list is right up to about a
  // screenful; the official builds are rulers x modes x ten and the rulers are
  // meant to reach dozens, and past that a reader cannot SCAN even a list they
  // can search. The header is emitted when the group CHANGES, so grouping costs
  // nothing when no item carries one, and it survives filtering — a search that
  // leaves two rulers standing still says which is which.
  let group = null;
  // THE SCAN'S PROGRESS BELONGS WHERE THE WORK IS BEING READ, which for a
  // ranked axis is this list — the same place the mod and arcane pickers put
  // theirs. `scanStrip` draws nothing unless this axis is the one running, and
  // a dropdown that ranks nothing declares no `axis` and gets none.
  const strip = cfg.axis
    ? scanStrip(gainScan, cfg.axis, hits.map((i) => i.key)) : "";
  $("dd-menu").innerHTML = strip + (hits.length
    ? hits.map((i) => {
      const head = (i.group && i.group !== group)
        ? `<div class="ddgroup">${escHtml(i.group)}</div>` : "";
      group = i.group || group;
      const chip = cfg.axis && i.key ? gainChipFor(i.key, cfg.axisLabel || "") : "";
      return head + `<div class="opt${String(i.value) === String(cfg.value) ? " cur" : ""}${
        i.disabled ? " dis" : ""}" data-v="${escHtml(String(i.value))}">
        <div class="info"><div class="mn">${escHtml(i.label)}${chip}${i.badge || ""}</div>${
          i.hint ? `<div class="me"><div>${escHtml(i.hint)}</div></div>` : ""}</div>
      </div>`;
    }).join("")
    : `<div class="opt dis">${escHtml(tr("no matches"))}</div>`);
  $("dd-menu").querySelectorAll(".opt[data-v]:not(.dis)").forEach((el) => {
    el.onclick = (e) => {
      e.stopPropagation();
      $("dd-popover").hidden = true;   // only THIS panel — a parent picker stays
      // The TRIGGER THAT OPENED THIS, not `$(id)`: the scenario's fields are
      // drawn twice — once by the simulator, once read-only by the optimizer —
      // so an id resolves to whichever copy is earlier in the document, which
      // is not necessarily the one being used. The anchor is never ambiguous.
      const btn = $("dd-popover")._anchor;
      if (btn) btn.value = el.dataset.v;
      // IT ANNOUNCES ITSELF, ALWAYS — the same event a native `<select>` fires,
      // which is what every binding this component replaced was written against.
      //
      // It was `if (cfg.dataK)`, on the reasoning that the scenario's generic
      // binding was the only listener. It was not: the ability element list
      // binds `change` on `[data-wfel]`, so converting that select produced a
      // control that opened, closed, showed the picked element on its face and
      // changed nothing. A component that reflects `value` but
      // withholds the event is one every future caller has to be told about.
      //
      // Every listener on this page is bound per element by attribute, so a
      // bubbling `change` from a dropdown nobody listens to reaches nothing.
      if (btn) btn.dispatchEvent(new Event("change", { bubbles: true }));
      if (cfg.onPick) cfg.onPick(el.dataset.v);
    };
  });
}

function ddOpen(id, anchor) {
  const cfg = ddReg.get(id);
  if (!cfg) return;
  closePopovers(anchor);
  const pop = $("dd-popover");
  pop._anchor = anchor;
  place(pop, anchor);
  // Match the trigger's width where it is wider than the panel's default, so
  // the panel reads as belonging to the control rather than floating near it.
  pop.style.minWidth = `${Math.max(anchor.getBoundingClientRect().width, 180)}px`;
  const wantSearch = cfg.search === true || cfg.items.length >= DD_SEARCH_MIN;
  $("dd-addbar").hidden = !wantSearch;
  const s = $("dd-search");
  s.value = "";
  s.oninput = () => ddRender(id, s.value);
  ddRender(id, "");
  if (wantSearch) s.focus();
}

// Delegated, because every caller re-renders its trigger by innerHTML — a
// listener bound to the node would be thrown away with it, and rebinding after
// each draw is the kind of thing that gets forgotten on the eighth dropdown.
// CAPTURE, not bubble: several containers call `stopPropagation` on click to
// survive their own innerHTML redraws (`#quick-calc` and `.picker-tools` both
// do), and a bubbling listener would never see a trigger inside one of them.
document.addEventListener("click", (e) => {
  const t = e.target.closest("[data-dd]");
  if (!t || t.disabled) return;
  e.stopPropagation();
  if (!$("dd-popover").hidden && $("dd-popover")._anchor === t) {
    $("dd-popover").hidden = true;    // clicking the open trigger closes it
    return;
  }
  ddOpen(t.id, t);
}, true);
/// PUT A POPOVER UNDER ITS ANCHOR — AND INSIDE THE SCREEN.
///
/// The anchor's left edge and nothing else is right on a desktop and is
/// HORIZONTAL OVERFLOW on a phone: a mod slot's ⋯ sits at x=295 of a 360px
/// screen, so its 200px menu runs to 495, the DOCUMENT becomes 495 wide, the
/// browser fits that into 360, and the Swap/Remove the reader was reaching for
/// is off the right edge. "The card is too long to reach its top right" and
/// "the menu makes the page smaller" are one bug, which is why the fix is here
/// rather than in either surface.
///
/// THE WIDTH IS CAPPED BEFORE THE CLAMP, because a popover wider than the
/// screen cannot be clamped into it: the mod picker is 331px and a 360px phone
/// has 348 to give. Both are measured after `hidden` is cleared, since a hidden
/// element has no size — and from a known left, since a width read against the
/// right edge comes back squeezed.
///
/// EVERY popover goes through this, so all six are covered by the one change.
/// `check_mobile` asserts it with each of them OPEN, a page at rest being its
/// blind spot.
function place(pop, anchor) {
  const r = anchor.getBoundingClientRect();
  pop.hidden = false;
  const margin = 6;
  const view_width = document.documentElement.clientWidth;
  pop.style.maxWidth = (view_width - 2 * margin) + "px";
  pop.style.left = margin + "px";
  const width = pop.offsetWidth;
  const left = Math.max(margin, Math.min(r.left, view_width - margin - width));
  pop.style.top = (window.scrollY + r.bottom + 4) + "px";
  pop.style.left = (window.scrollX + left) + "px";
}

function openPicker(slotIdx, anchor) {
  closePopovers();
  pickerSlot = slotIdx;
  const pop = $("mod-popover");
  place(pop, anchor);
  const search = $("mod-search");
  search.value = "";
  search.oninput = () => renderMenu(slotIdx, search.value);
  renderTools();
  renderMenu(slotIdx, "");
  // Sorted by EFFECT by default — which means computing it.
  ensureGains({ kind: "mods", idx: slotIdx },
    () => { if (!$("mod-popover").hidden) renderMenu(pickerSlot, $("mod-search").value); },
    true);
  search.focus();
}

function renderTools() {
  const t = $("picker-tools");
  const pols = ["Madurai", "Naramon", "Vazarin", "Umbra"].filter((p) => currentPool.some((m) => m.polarity === p));
  t.innerHTML =
    `<label>${escHtml(tr("Sort"))} ` + ddButton("pk-sort", {
      value: pickerPrefs.sort,
      items: [{ value: "name", label: tr("Name") }, { value: "drain", label: tr("Drain") }]
        .concat(gainPrefs.on === false ? [] : [{ value: "gain", label: tr("Gain") }]),
      onPick: (v) => { pickerPrefs.sort = v; savePickerPrefs(); renderTools(); renderMenu(pickerSlot, $("mod-search").value); },
    }) + `</label>` +
    `<button id="pk-dir" class="ghost-btn small" title="direction">${pickerPrefs.dir === "asc" ? "▲" : "▼"}</button>` +
    `<span class="pk-pols"><span class="pk-pol ${!pickerPrefs.pol ? "sel" : ""}" data-p="">all</span>` +
    pols.map((p) => `<span class="pk-pol ${pickerPrefs.pol === p ? "sel" : ""}" data-p="${p}" title="${p}">${imgTag(POL(p), "pol")}</span>`).join("") +
    `</span>`;
  // redraw() re-renders these tools via innerHTML, which DETACHES the clicked
  // node; without stopPropagation the click would bubble to the document
  // outside-click handler, whose closest(".popover") now fails on the detached
  // target → the picker would wrongly close. Keep every tool click inside.
  const redraw = () => { savePickerPrefs(); renderTools(); renderMenu(pickerSlot, $("mod-search").value); };
  $("pk-dir").onclick = (e) => { e.stopPropagation(); pickerPrefs.dir = pickerPrefs.dir === "asc" ? "desc" : "asc"; redraw(); };
  t.querySelectorAll(".pk-pol").forEach((o) => o.onclick = (e) => { e.stopPropagation(); pickerPrefs.pol = o.dataset.p || null; redraw(); });
}

// ---- MARGINAL GAIN: what is THIS SLOT worth as something else? ------------
//
// Asked OF A SLOT — "if slot N became this mod, what happens to the kill
// rate?" — which is correct rather than convenient: elements combine by MOD
// ORDER (MECHANICS §3) and the payload's list is slot-ordered. Answered by
// SIMULATING each candidate, since the builder has no second damage model; the
// metric is KILL PROGRESS, falling back to DPS when the baseline cannot kill.
// PAIRED randomness is what makes a tenth of the run count usable.
/// ONE MEASUREMENT, and how far it can be from the truth: `{ v, se }`.
///
/// THE MEAN, NOT THE MEDIAN RUN. `score`/`dps` are the median engagement, one
/// run however many were paid for: measured here the median moved 9.8% between
/// seeds at 10 runs where the mean moved 5.9%, and the mean is the statistic
/// the OPTIMIZER ranks (`mean_kill_progress`).
///
/// `se` is the server's own spread over those runs (sigma / sqrt(runs)).
/// Estimating it by re-running the reference at another seed takes ONE sample
/// of a distribution, which on identical inputs answers anywhere from 0.7% to
/// 11.2% — one draw deciding whether EVERY chip is suppressed or none is.
const readGain = (r, useKills) => {
  if (!r || !r.ok) return null;
  const runs = (useKills ? r.score_runs : r.dps_runs) || [];
  return useKills
    ? { v: r.score_mean ?? r.score ?? r.kills ?? 0, se: r.score_se ?? 0, runs }
    : { v: r.dps_mean ?? r.dps ?? 0, se: r.dps_se ?? 0, runs };
};

/// What `cand` is worth against `ref`, with the uncertainty of the COMPARISON.
///
/// PAIRED, because the runs are: `monte_carlo` advances its master rng once per
/// run whatever the run does, so run `i` of each build is drawn from the same
/// luck and the comparison's spread is the spread of the DIFFERENCES.
///
/// The standard ratio-estimator error: with `d_i = c_i − ratio·b_i`,
/// `SE(ratio) = sd(d) / (√n · mean(b))`. It says two things quadrature — the
/// formula for INDEPENDENT samples — cannot:
///
///  · a candidate that scales this fight PROPORTIONALLY gives `d_i = 0` on
///    every run, so the band is exactly zero and the gain is a fact (the
///    Serration / Amalgam Serration pair, 0.9623 = 2.55/2.65 at any run count);
///  · one that changes WHICH fight happens gives a real band, however close
///    its mean lands.
///
/// Quadrature overstates a paired band AND leaves "exact" undecidable. With no
/// series to pair it falls back to quadrature, the honest answer when the
/// pairing cannot be seen.
const gainOver = (cand, ref) => {
  const ratio = cand.v / ref.v;
  const a = cand.runs || [], b = ref.runs || [];
  const n = Math.min(a.length, b.length);
  if (n < 2 || !ref.v) {
    return { pct: ratio - 1, se: ratio * Math.hypot(cand.se / cand.v || 0, ref.se / ref.v || 0) };
  }
  let ss = 0;
  for (let i = 0; i < n; i++) {
    const d = a[i] - ratio * b[i];
    ss += d * d;
  }
  // Σd is zero by construction when both means are taken over the same n, so
  // the sum of squares IS the variance's numerator.
  const se = Math.sqrt(ss / (n - 1) / n) / ref.v;
  // FLOATING-POINT RESIDUE IS NOT A BAND. A candidate that scales this fight
  // proportionally leaves `d_i` at the last bits of a double rather than at
  // zero — measured 4e-15 on the Serration pair — and a band of 4e-15 prints
  // as "±0.0%", which is the "≈0%" this whole display was written to stop.
  return { pct: ratio - 1, se: se < 1e-9 * Math.abs(ratio) ? 0 : se };
};

// ONE seed for the whole scan: the reference and every candidate are measured
// under the same luck, so a candidate that does not perturb the fight compares
// against the reference exactly (see `gainBand`).
//
// There is no second seed. A scan's resolution is a property of THIS scope in
// THIS fight — a status mod perturbs it and a damage mod barely does — so it
// has to be measured rather than assumed; but the runs already paid for measure
// it, and one extra run at another seed only draws a single sample of it.
const GAIN_SEED = 0x5EED;
// TEN, and it is both the floor and the default. Below it a status mod's chip
// is a coin flip — M24: one run swings a status mod +-39 points — so a number
// under ten is not a cheaper answer, it is a wrong one.
const GAIN_RUNS_MIN = 10;
const GAIN_RUNS_MAX = 2000;
const gainRuns = () =>
  Math.max(GAIN_RUNS_MIN, Math.min(GAIN_RUNS_MAX, Math.round(Number(gainPrefs.runs)) || GAIN_RUNS_MIN));
// A gain READS with its sign — "12.3%" and "+12.3%" are different claims.
const gainPct = (x) => (x >= 0 ? "+" : "−") + sig2(Math.abs(x) * 100) + "%";

// Quick calc's TWO settings: which saved scenario, and how many runs.
//
// A run count is the one knob whose right value nobody but the reader knows: it
// depends on how close the answers turn out to be and on how long you are
// willing to wait. Ten is the floor and the default, where a status mod's
// answer stops being a coin flip (M24); above it you are buying resolution the
// scan cannot invent. What a run is MEASURED BY still belongs to the scenario,
// and there is no "current" scenario either — a scan is only worth reading
// against something with a name that can be returned to.
// ON by default: the ranking is the reason the picker is
// worth opening. Off, nothing simulates, no chip is drawn, and is not
// offered as an order — a sort key with no values behind it is a trap.
// NO `scenario` HERE ANY MORE: the fight is the simulator's, and a stale key
// left in a reader's localStorage is inert because nothing reads it. See
// `gainScenario`.
let gainPrefs = { on: true, runs: GAIN_RUNS_MIN };
try { const s = JSON.parse(localStorage.getItem("wfsim-gain")); if (s) gainPrefs = { ...gainPrefs, ...s }; } catch (_) {}
const saveGainPrefs = () => localStorage.setItem("wfsim-gain", JSON.stringify(gainPrefs));

let gainScan = { key: null, running: false, base: 0, floor: 0, by: {}, done: 0, total: 0,
  ids: new Set(), note: "", metric: "" };

/// THE FIGHT A SCAN RUNS UNDER, and there is only one: THE ONE YOU ARE IN.
///
/// A picker of its own — `gainPrefs.scenario`, persisted, and therefore STICKY
/// across weapons, scenarios and sessions — is two controls for one fact, which
/// is how one silently undoes the other: build a nine-body Ocucor fight, switch
/// the simulator to it, and the quick calc keeps
/// ranking every slot under whichever scenario that popover was last left on —
/// an official single-target ruler, most likely, since that is where the app
/// lands a first-time visitor. The mods that only pay in a crowd read as worth
/// nothing, and nothing on screen said the numbers came from another fight.
///
/// So it follows the simulator, and the rule is the arena's own: a fight is
/// EDITED IN ONE PLACE. Ranking a slot under some other scenario is still one
/// click — switch to it, and the simulator shows it too, so the numbers and
/// the fight on screen can no longer disagree.
function gainScenario() {
  const ps = scenarioList();
  // The NAME only — what is measured is `theFight()`. Resolved by ID, not by
  // label: an official ruler's name is a translated sentence while its identity
  // is `single_target_no_aim`.
  const p = ps.find((x) => presetId(x) === activeScenario);
  // ONE PASS, at the reader's own count. It was one run over the field and then
  // the leaders again — two numbers with two precisions, and the cheap one
  // printed a minus sign in front of mods worth +40% (M24: a status mod swings
  // ±39 points on a single run). Ten is where that stops being a coin flip; it
  // is not where it stops moving, which is why every tooltip still says how
  // many runs its number came from.
  //
  // THE COUNT IS THE ONLY THING THIS SCAN OWNS. It is the reader's precision,
  // not an edit to the fight — which is what makes "the quick calc is the
  // simulator run many times" true rather than aspirational.
  return { name: p ? p.name : "—", refine: 0,
    // THE RUNS THEMSELVES, because this scan PAIRS with them. See `gainOver`.
    scenario: theFight({ runs: gainRuns(), seed: GAIN_SEED, run_series: true }) };
}

// A scan belongs to ONE AXIS POSITION of one build under one scenario.
let gainAxis = { kind: "mods", idx: 0 };
// The key is the AXIS, the BUILD and the FIGHT THIS SCAN WILL ACTUALLY RUN —
// `gainScenario()`'s own output, not a hand-listed copy of some of `sim`.
//
// Naming the scenario fields one by one gives a list that drifts: a missing
// `buffs` means raising a buff's starting stacks changes what the scan would
// measure without changing the key, and the old ranking stays on screen looking
// current. Any
// hand-maintained list of "the fields that matter" grows a hole the moment a
// field is added; deriving the key from the payload cannot.
const gainKey = () => JSON.stringify([gainAxis, buildPayload(), gainPrefs.on,
  gainScenario().scenario]);

const famOf = (id) => (modById(id) || {}).family || null;
const modsCompatible = (ids) => {
  const fams = ids.map(famOf).filter(Boolean);
  return new Set(fams).size === fams.length;
};

/// Every candidate for an axis position, as `{ id, payload }` — the payload
/// being what to OVERRIDE on `buildPayload()` to try it.
///
/// The three axes differ only here. A mod replaces one slot, an arcane one
/// pool, an evolution one tier — and evolutions are scanned across EVERY tier
/// at once, because they are all on screen at once and there are a dozen of
/// them, not seventy.
function gainCandidates(axis) {
  if (axis.kind === "arcane") {
    const cur = arcanes.slice();
    return arcanePool(axis.idx)
      .filter((a) => a.id !== cur[axis.idx])
      .map((a) => { const next = cur.slice(); next[axis.idx] = a.id; return { id: a.id, payload: { arcane: next } }; });
  }
  if (axis.kind === "evo") {
    // Every tier at once, because they are all on screen at once — but only
    // the tiers the LADDER opens. Scanning a locked tier's options too makes
    // the picker offer (and rank) an evolution the builder will not let you
    // click, measured on a build that cannot exist.
    //
    // Within a tier this is exactly "current vs replacement": the base run is
    // the build as it stands, and each candidate swaps ONE tier's choice and
    // leaves the rest alone.
    const openTo = evoOpenTo();
    const equipped = slots.map((s) => s.mod).filter(Boolean);
    const out = [];
    weaponEvos().filter((tier) => tier.tier <= openTo).forEach((tier) => {
      tier.options.forEach((o) => {
        if (evoSel[tier.tier] === o.id) return;
        const next = { ...evoSel, [tier.tier]: o.id };
        // An evolution that would take an EQUIPPED mod off the weapon is not a
        // one-step swap — it is that swap plus an eviction, and scoring it
        // against this build would price a build the game refuses. It is still
        // choosable; it just has no gain to report until the mod comes out.
        const no = forbiddenByEvos(next);
        if (equipped.some((m) => no.has(m))) return;
        out.push({ id: o.id, payload: { evolutions: Object.values(next).filter(Boolean) } });
      });
    });
    return out;
  }
  if (axis.kind === "assembly") {
    // BOTH PARTS AT ONCE, the way a tier of evolutions is scanned: they are on
    // screen together, so measuring one and leaving the other blank would be a
    // ranking that only half exists. One axis also keeps them from cancelling
    // each other in `ensureGains`, which gives way per axis.
    //
    // A grip and a loader can share a name, so the candidate id carries the
    // part — it is the key the chip is looked up by.
    const w = $("weapon").value;
    const spec = assemblySpec(w);
    if (!spec || !assembly) return [];
    const out = [];
    [["grip", spec.grips], ["loader", spec.loaders]].forEach(([part, items]) => {
      (items || []).forEach((it) => {
        if (assembly[part] === it.id) return;
        out.push({
          id: part + ":" + it.id,
          payload: { assembly: { ...assembly, [part]: it.id } },
        });
      });
    });
    return out;
  }
  if (axis.kind === "valence") {
    // THE SEVEN PROGENITOR ELEMENTS, scanned the way a tier of evolutions is —
    // all on screen at once, one swap each, everything else left alone.
    //
    // It is the axis a scan is worth the most on: the choice is a whole element
    // entering the hierarchy, so which one wins depends on the mods around it
    // and on the target — a question nobody can answer by reading cards.
    const s = valenceSpec($("weapon").value);
    if (!s) return [];
    return s.elements
      .filter((e) => e !== valence.element)
      .map((e) => ({ id: e, payload: { valence_element: e, valence_bonus: valence.bonus } }));
  }
  const cur = slots.map((s) => s.mod);
  // `buildPool()`, not the weapon's: a scan that ranks a mod this build's
  // evolutions forbid recommends something the picker will not offer.
  return buildPool()
    .filter((m) => !cur.includes(m.id))
    .filter((m) => axis.idx !== EXILUS || m.exilus)
    .map((m) => { const next = cur.slice(); next[axis.idx] = m.id; return { id: m.id, payload: { mods: next.filter(Boolean) } }; })
    .filter((c) => modsCompatible(c.payload.mods));
}

// How many of the leaders AUTO looks at twice. Small on purpose: the second
// pass exists to settle an ORDER, and an order is decided at the top.
const GAIN_REFINE_TOP = 12;

// ---- the quick calc runs WIDE ------------------------------------------
//
// A scan is one simulate per candidate and a mod slot has ~80 candidates once
// family conflicts are dropped, each at 10 runs — so ~810 full engagements.
//
// A nearly-full build is far worse than a bare one because the candidate COUNT
// barely moves while each ENGAGEMENT does: seven mods means multishot, status
// and elements all live, so one fight generates several times the procs, DoT
// stacks and ticks. The per-sim cost is a function of how much is HAPPENING.
//
// The lever is PARALLELISM and only that — the run count is 10 by decision and
// the engagement DURATION is never the lever. A lane is THE PAGE'S POOL, the
// same lanes the simulator shards across and `api` picks from; on the native
// server there is no worker to own, so a lane is plain `api` and the fetches
// parallelise by themselves.
//
// PINNABLE, because a worker is opaque from the page: `check_one_fight` and
// `check_gain_freshness` point the scan back through `api` to read what it
// actually sent.
let gainPool = null;
let nativeLanes = null;
async function gainLanes() {
  if (gainPool) return gainPool;
  if (WASM) return lanes();
  if (!nativeLanes) {
    nativeLanes = Array.from({ length: poolSize() },
      () => ({ call: (p, b) => api(p, b) }));
  }
  return nativeLanes;
}

// The generation of the scan that is allowed to write `gainScan`. Bumped on
// every start, so an older scan discovers at its next await that it has been
// superseded and stands down.
//
// WHY it has to be interruptible: a scan is ~90 SERIAL simulate calls, and the
// old guard was "a scan is running, so ignore this". Editing the fight midway
// therefore did not queue and did not cancel — it was DROPPED, the whole stale
// scan ran to the end under the config you had just left, and only then did
// the refresh notice the key had moved and start again. Every rapid edit paid
// for a full measurement of a question nobody was asking any more. Cancelling at the next await bounds that to one sim.
// WHICH ENEMY THE DEBUFF TABLE IS ABOUT — an index into `replay.tracked`, 0
// being the body the weapon was on.
//
// OUTSIDE the render for the reason every fold on that panel is: a panel that
// resets your selection on every Run Sim is a panel you re-select on every Run
// Sim.
let replayFoe = 0;
/// …CLAMPED TO WHAT THIS REPLAY ACTUALLY FOLLOWED. Three functions ask it —
/// the markup, the frame reader and the wiring — and they run at different
/// times, so it is derived rather than passed. It was written out three times
/// for an hour and the third copy was in a function the other two's binding
/// could not reach, which took the whole panel down with "dBody is not
/// defined" rather than drawing a wrong number: it announced itself.
const replayFoeIdx = (rp) =>
  Math.min(replayFoe, Math.max(0, ((rp && rp.tracked) || [""]).length - 1));

let gainGen = 0;
// An axis whose scan was dropped because another axis was mid-flight. One slot:
// the newest asker wins, and it is consumed when the running scan finishes.
let gainPending = null;

/// THE FIGHT THIS SCAN IS ABOUT — the one it answered, or the one it is
/// answering. Two states, because the key is now stamped on COMPLETION: a scan
/// in flight has only a `want`, and a scan that died has neither.
const gainAbout = () => gainScan.key || (gainScan.running ? gainScan.want : null);

/// END A SCAN AND SAY WHY, which is the whole of what was missing. Every exit
/// dropped `running` and left the reader with a frozen counter and no reason —
/// so a scan that lost its lanes and one that finished looked the same.
/// THE ONE PLACE THE QUICK CALC IS DRAWN.
///
/// NOTHING THAT CHANGES THE SCAN DRAWS IT. Every mutation marks the surface
/// dirty and this runs on a TRAILING timer, whose defining property is that it
/// always runs once more AFTER the last change — a throttle applied at the
/// write cannot, which is how a finished scan kept a frame several answers
/// short while its own books balanced. Three surfaces depend on the scan and
/// the bugs were all the same shape: a new exit path repainted two of them, or
/// none. A mutation site that cannot paint cannot forget to.
let calcPainter = null, calcPaintAt = 0;
const CALC_FRAME_MS = 250;
function paintCalc() {
  calcPaintAt = Date.now();
  renderQuickCalc();
  renderCalcStatus();
  const r = gainScan.repaint;
  if (r) { try { r(); } catch (_) { /* the list it belongs to is gone */ } }
  // …AND THE ONE THAT GAVE WAY TAKES ITS TURN HERE, in the frame that is
  // guaranteed to happen, rather than inside a callback that a throttle can
  // swallow — which is how a parked axis was never started at all.
  if (!gainScan.running && gainPending) {
    const p = gainPending;
    gainPending = null;
    ensureGains(p.axis, p.repaint);
  }
}
function calcDirty() {
  gainScan.beat = Date.now();
  if (calcPainter) return;
  const wait = Math.max(0, CALC_FRAME_MS - (Date.now() - calcPaintAt));
  calcPainter = setTimeout(() => { calcPainter = null; paintCalc(); }, wait);
}

/// IS A SCAN ACTUALLY WORKING — asked instead of `gainScan.running`.
///
/// `running` is asserted by one site and has to be cleared by EVERY exit, so
/// any exit nobody thought of latches it, and a latched flag refused that list
/// for the life of the page. Every hang this file has had was one cause of
/// that; there is always another cause. A refusal that expires ends the whole
/// CLASS: whatever latches it, the calculator answers again a few seconds
/// later. The watchdog on a lane is then about being PROMPT, not about being
/// correct.
///
/// A working scan beats through `calcDirty` — per candidate, and through the
/// baseline's own progress, so a long fight is live rather than merely slow.
const CALC_STALE_MS = 20000;
const scanIsLive = () => gainScan.running
  && Date.now() - (gainScan.beat || 0) < CALC_STALE_MS;

function gainStop(why) {
  gainScan.running = false;
  gainScan.note = why || gainScan.note;
  gainScan.failed = !!why;
  calcDirty();
}

async function scanGains(axis, repaint) {
  const gen = ++gainGen;
  const live = () => gen === gainGen;
  gainAxis = axis;
  const { name, scenario, refine } = gainScenario();
  // The note is WHICH FIGHT this was measured in, and nothing else: each
  // chip's tooltip states its own run count, which is the only place the
  // number changes how a reading should be taken.
  // THE CANDIDATES ARE ENUMERATED BEFORE THE FIRST RUN, so a list drawn while
  // the base fight is still going already knows how many of ITS OWN rows are
  // coming. `gainCandidates` is a pure enumeration and awaits nothing, so this
  // costs the move and no time.
  const cands = gainCandidates(axis);
  // THE KEY IS NOT STAMPED YET. `ensureGains` returns early when the key
  // matches, so stamping it at the START meant a scan that died half way —
  // lanes gone, an exception — left the page believing this fight was already
  // answered, and no later request ever re-asked. It is written at the end, and
  // only when the scan actually finished; `want` is what a live scan is FOR,
  // which is what the interrupt check compares against.
  gainScan = { key: null, want: gainKey(), axis, running: true, base: 0, floor: 0,
    phase: "", by: {}, refused: {}, done: 0, repaint, beat: Date.now(),
    total: cands.length + (refine ? Math.min(GAIN_REFINE_TOP, cands.length) + 1 : 0),
    ids: new Set(cands.map((c) => c.id)), note: name, metric: "", lanesLost: 0 };
  // THE BAR APPEARS WHEN THE WORK STARTS, not when the first candidate lands.
  // The BASE fight runs before any candidate does, and on a crowd at a real run
  // count that is tens of seconds — throughout which `running` is already true
  // and nothing had repainted the list. So the list a reader had just opened
  // sat silent through exactly the wait the strip exists to explain, and the
  // bar turned up only once there was already an answer to show.
  calcDirty();
  // THE SCENARIO'S OWN METRIC, AND NOTHING ELSE.
  //
  // There is no fallback to another one, and there must not be: a ruler
  // declares what it measures, and a ranking quietly produced in a different
  // unit answers a question nobody asked. It cost a second full baseline to do
  // it, and the day a ruler measures something that is neither — how fast a
  // build applies status TYPES, say — a hard-coded pair is not a fallback, it
  // is a wrong answer.
  //
  // IT NEVER HAD ANYTHING TO FALL BACK FOR. Kill progress is not a kill COUNT:
  // it is "kills plus the depleted fraction of the current target's pool", so a
  // build that kills nothing still scores what it drained. Zero means the build
  // dealt no damage at all — and a build that deals no damage has no DPS
  // either, so the second baseline measured the same nothing.
  // BY THE SCENARIO'S OWN METRIC, whatever it is. `per_minute` is the question
  // that decides which baseline is read — a rate over the engagement against a
  // field the run reports directly — and it is the metric's to answer.
  const useKills = metricOf(scenario.metric).per_minute;
  // THE BASELINE IS SHARDED, like every other simulation the page runs.
  //
  // It went through `api`, which takes ONE lane — so the step every candidate
  // waits on ran single-threaded while the rest of the pool idled, and the
  // candidates that follow it use the whole machine. On a crowd at a real run
  // count that is tens of seconds of a fifteen-core machine doing nothing, and
  // it is the whole of what "stuck at 0/77" was.
  //
  // `simulateFleet` falls back to one call where sharding would not pay, and
  // the merge is `simulate_merged` — exactly what one worker would have
  // produced — so this is the same answer, sooner.
  const run = async (override, phase) => {
    const label = phase || "";
    gainScan.phase = label;
    calcDirty();
    // THE BASELINE SAYS HOW FAR IT HAS GOT. Every candidate waits on this one
    // call, so a scan sitting at 0/77 is not stuck — it is measuring the thing
    // the whole ranking is relative to, and saying nothing through it is what
    // made that read as a hang. The beat is also what keeps `scanIsLive` true
    // across a long fight, so this is load-bearing rather than decoration.
    const r = await simulateFleet(
      { ...buildPayload(), ...scenario, ...override },
      (d, total) => {
        gainScan.phase = label ? `${label} ${d}/${total}` : `${d}/${total}`;
        calcDirty();
      },
      { background: true });
    if (!r || !r.ok) return null;
    return readGain(r, useKills);
  };
  let base = await run({}, tr("measuring the baseline"));
  if (!live()) return;
  if (!base?.v) { gainStop("the base fight did not measure"); return; }
  gainScan.base = base.v;
  gainScan.metric = useKills ? tr("kill rate") : tr("DPS");
  // HOW LONG THE REST WILL TAKE, from the rate this scan is actually going.
  //
  // NOT FROM THE BASELINE, which is the first real fight of the page and pays
  // for wasm tiering up on a hot numeric loop — measured at about 4x, so an
  // estimate built on it over-predicts fivefold. Nor from a model of the pool:
  // throughput already contains the lane count, the machine, the fight and
  // whatever else the browser is doing, and it corrects itself as any of them
  // change.
  //
  // AFTER A FEW, because one candidate's wall time is mostly the round trip.
  const candAt = Date.now();
  const reckon = () => {
    if (gainScan.done < 3) return;
    const per = (Date.now() - candAt) / gainScan.done;
    gainScan.etaMs = Math.round(per * Math.max(0, gainScan.total - gainScan.done));
  };
  // ...and how far this same build moves on luck alone — the RESOLUTION the
  // server measured across the runs it was already paid for, not a second run
  // at another seed. See `readGain`.
  gainScan.floor = base.se / base.v;
  // …AND THE CANDIDATES ARE THE COUNTER'S OWN, so the phase line steps aside.
  gainScan.phase = "";
  // One shared cursor, every lane pulling the next candidate as it frees up —
  // so a slow candidate delays itself and nothing else. `live()` is checked
  // after each await, which is what bounds an interrupted scan to one
  // outstanding sim per lane rather than the whole queue.
  let cursor = 0;
  await Promise.all((await gainLanes()).map(async (lane) => {
    for (;;) {
      if (!live()) return;
      // A PERSON'S SIMULATE GOES FIRST. Checked before the candidate is taken,
      // so the scan gives up the machine between candidates rather than holding
      // a lane through one.
      await yieldToForeground(live);
      if (!live()) return;
      const c = cands[cursor++];
      if (!c) return;
      const r = await laneAsk(lane, "/api/simulate",
        { ...buildPayload(), ...scenario, ...c.payload }, live);
      if (!live()) return;               // the fight moved — this answer is stale
      // THE POOL REFUSED TWICE. Counted rather than silent: this lane's share
      // of the candidates goes unmeasured, and a ranking with holes in it has
      // to say so — the sweep below re-asks for them on a fresh worker.
      if (r === null) { gainScan.lanesLost++; return; }
      const g = readGain(r, useKills);
      gainScan.done++;
      reckon();
      if (g) {
        gainScan.by[c.id] = { ...gainOver(g, base), runs: scenario.runs };
      } else if (r.error) {
        // THE ENGINE ANSWERED, AND THE ANSWER IS NO — which is not a failure.
        //
        // A mod the weapon cannot take with these evolutions ("it needs the
        // same trigger on every firing mode") was counted as a HOLE, so the
        // scan could never be complete, never stamped its key, and re-ran on
        // every request for the life of the page. One legal refusal in eighty
        // was enough: the Torid's list never settled.
        //
        // Recorded rather than dropped, because the reader asked what this
        // option is worth and "you cannot equip it" is the answer.
        gainScan.refused[c.id] = String(r.error);
      }
      calcDirty();
    }
  }));
  if (!live()) return;
  // SECOND PASS. One run ranks the field cheaply but cannot separate its top
  // few — so the leaders are asked again with more, against a baseline
  // measured the same way. Everything below them keeps its first answer,
  // which is all a position near the bottom needs to be right about.
  if (refine) {
    const deep = { ...scenario, runs: refine };
    // …AND THE SECOND PASS IS SHARDED FOR THE SAME REASON, at a HIGHER run
    // count than the first: one lane there is the slowest call in the scan.
    const runDeep = async (override) => {
      const r = await simulateFleet(
        { ...buildPayload(), ...deep, ...override },
        () => { calcDirty(); },
        { background: true });
      if (!r || !r.ok) return null;
      return readGain(r, useKills);
    };
    gainScan.phase = tr("re-measuring the leaders");
    calcDirty();
    const deepBase = await runDeep({});
    if (!live()) return;
    gainScan.done++;
    calcDirty();
    if (deepBase?.v) {
      const top = cands
        .filter((c) => gainScan.by[c.id])
        .sort((a, b) => gainScan.by[b.id].pct - gainScan.by[a.id].pct)
        .slice(0, GAIN_REFINE_TOP);
      for (const c of top) {
        const v = await runDeep(c.payload);
        if (!live()) return;
        gainScan.done++;
        if (v) {
          gainScan.by[c.id] = { ...gainOver(v, deepBase), runs: refine };
        }
        calcDirty();
      }
    }
  }
  // WHAT THE LOST LANES NEVER ASKED, asked once more.
  //
  // A lane stands down when the pool refuses it twice, and every candidate it
  // had not reached went unmeasured — silently, because the counter only ever
  // counted answers. `laneAt` builds a fresh worker now, so the retry has
  // somewhere to run; ONCE, because a second refusal means the pool is not
  // coming back and a loop against that is a hang rather than a recovery.
  if (gainScan.lanesLost) {
    for (const c of cands.filter((x) => !gainScan.by[x.id] && !gainScan.refused[x.id])) {
      if (!live()) return;
      const r = await laneAsk(freeLane(), "/api/simulate",
        { ...buildPayload(), ...scenario, ...c.payload }, live);
      if (!live()) return;
      if (r === null) break;             // still gone: stop rather than spin
      const g = readGain(r, useKills);
      if (g) gainScan.by[c.id] = { ...gainOver(g, base), runs: scenario.runs };
      else if (r.error) gainScan.refused[c.id] = String(r.error);
      calcDirty();
    }
  }
  // A SCAN WITH HOLES IS NOT AN ANSWER, so the key stays null and the next
  // request re-asks. The reader is told how many are missing rather than shown
  // a ranking that is quietly short.
  // AN ANSWER OF "NO" IS STILL AN ANSWER, so a refused option is not a hole.
  // Only a candidate nobody ever heard back about is.
  const holes = cands.filter((c) => !gainScan.by[c.id] && !gainScan.refused[c.id]).length;
  if (holes) {
    // …AND THE REASON GIVEN IS THE REASON. Blaming a lost worker when none was
    // lost sends the reader to rebuild a pool that was never the problem.
    gainStop(gainScan.lanesLost
      ? tr("{n} of {total} could not be measured — the calculator lost a worker")
        .replace("{n}", holes).replace("{total}", cands.length)
      : tr("{n} of {total} could not be measured")
        .replace("{n}", holes).replace("{total}", cands.length));
    return;
  }
  // FINISHED, so the fight it answers is recorded — and only now.
  gainScan.key = gainScan.want;
  gainStop("");
}

/// The gain chip: what this option is worth, once scanned. Shared by all
/// three lists — a mod, an arcane and an evolution are the same question
/// asked of different axes, so they say it the same way.
/// HOW WIDE this gain's answer is, as a fraction — 0 when the comparison is
/// exact.
///
/// It is the comparison's OWN error and nothing else. `gainOver` pairs the two
/// builds run by run, so a candidate that scales this fight proportionally
/// leaves every paired difference at zero and lands here as a plain 0: exact,
/// derived, not asserted.
///
/// NOT a PROXY — "did the median run's proc count change?" — which is what two
/// independent summaries reduce you to. The proxy is wrong in the direction
/// that matters: it says "same fight" whenever the count happens to coincide,
/// and on the Kuva Nukor all seven progenitor elements report 6079
/// while their fights differ by up to 30%. Seven chips claimed an exactness
/// none of them had, and the ranking between two of them was a coin flip
/// printed as a fact.
const gainBand = (g) => g.se || 0;

/// The chip. A gain the scan cannot resolve STATES ITS WIDTH rather than
/// collapsing to "about nothing". "≈0%" was one string for
/// two different findings — a mod that does nothing, and a mod nobody measured
/// hard enough — and the difference between them is the only thing a reader
/// can act on: the first says pick something else, the second says raise the
/// runs. A band says which: `+0.1%` is
/// worthless, `≈+3.1% ±7.2%` is unmeasured.
const gainChip = (g, why, tied) => {
  // TIED WITH THE LEADER, said on the chip. The list always produces an order;
  // this is where it admits the order is not one. See `gainTied`.
  const tie = tied
    ? ` <span class="gtie" title="${escHtml(tr("this is as good as the top option — the gap between them is smaller than either answer's own width, so the order between them is the dice"))}">${tr("tied")}</span>`
    : "";
  const band = gainBand(g);
  if (!band) {
    // MEASURED AND MOVED NOTHING — which is a NUMBER, and the number is what
    // is printed. A worded verdict here would be about the reader's own fight
    // rather than a measurement of it: the same card is worth nothing against
    // one standing target and a great deal in a crowd, or the moment a build
    // finally kills something an on-kill trigger is waiting for. The app states
    // what it MEASURED and marks only what it does not MODEL.
    if (g.pct === 0) {
      return `<span class="gainchip flat" title="${escHtml(
        `${tr("this option did not re-roll the fight — run for run it scaled the same engagement, so this comparison is exact")} · ${why}`
      )}">${gainPct(g.pct)}</span>`;
    }
    // Paired exactly — the fight did not re-roll, so this is not an estimate.
    return `<span class="gainchip ${g.pct >= 0 ? "up" : "down"}" title="${escHtml(
      `${tr("this option did not re-roll the fight — run for run it scaled the same engagement, so this comparison is exact")} · ${why}`
    )}">${gainPct(g.pct)}${tie}</span>`;
  }
  const cls = Math.abs(g.pct) < band ? "flat" : (g.pct >= 0 ? "up" : "down");
  return `<span class="gainchip ${cls}" title="${escHtml(
    `${tr("this option re-rolls the fight, so its answer is only good to ±{x} — raise the run count to narrow it")
      .replace("{x}", sig2(band * 100) + "%")} · ${why}`
  )}">≈${gainPct(g.pct)} ±${sig2(band * 100)}%${tie}</span>`;
};

/// IS THIS OPTION TELLING THE READER APART FROM THE BEST ONE?
///
/// A chip answers "what is this worth against the build you have". The LIST
/// answers a second question nobody wrote down — which of these to pick — and
/// it answers it by sorting, which always produces an order even when there is
/// none. Two options whose gains differ by less than the two bands together are
/// the same answer; printing one above the other says otherwise, and the reader
/// acts on the order, so the top one can measure worse than the one under
/// it.
///
/// So an option that is not SEPARATED from the leader is marked as tied with
/// it. Not the leader's neighbour — the leader, because "which do I pick" is
/// asked of the top of the list and every option tied with it is an equally
/// good answer.
const gainTied = (g) => {
  const all = Object.values(gainScan.by || {});
  if (all.length < 2) return false;
  const best = all.reduce((a, b) => (b.pct > a.pct ? b : a));
  const near = (x, y) => x.pct - y.pct < Math.hypot(x.se || 0, y.se || 0);
  // THE LEADER IS ONLY TIED IF SOMETHING ELSE IS TIED WITH IT. Marking it
  // unconditionally put "tied" on the first row of every ranking, including the
  // ones with a clear winner — a caveat printed where there is nothing to
  // caveat, which is noise on every list.
  if (best === g) return all.some((x) => x !== g && near(g, x));
  return near(best, g);
};

// PROGRESS BELONGS WHERE THE WORK IS BEING READ, not only where it was started.
//
// The quick calc counted itself in one place — the panel at the top of the page
// — and the LIST it was ranking said nothing. A pool of 90 mods at 200 runs is
// tens of seconds of a list that does not move, and a list that does not move is
// read as broken. The per-row "…" chip was already there and
// was not enough: it says THIS row has no answer yet, and says nothing about
// whether anything is still happening.
//
// So the strip goes at the top of every list a scan ranks — the mod picker, the
// arcane picker, the evolution tiers, the valence row, and the optimizer's own
// list — and it is the SAME component fed from whichever scan state that list
// reads, because "how far along is it" is one question with one answer.
//
// It draws NOTHING when nothing is running, so a finished list is a finished
// list: a bar sitting at 100% would be one more thing to read and dismiss.
function scanStrip(st, axis, rows) {
  if (!st) return "";
  // AN AXIS ONLY SHOWS ITS OWN. Two lists can be open at once (a picker over
  // the evolution rows), and the scan belongs to exactly one of them — showing
  // it on both would say the other one is being measured when it is waiting.
  if (axis && JSON.stringify(st.axis) !== JSON.stringify(axis)) return "";
  if (!st.running) {
    // …EXCEPT WHEN EVERY ANSWER WAS ZERO, which is a FINDING and not a bar at
    // 100%. A list of "+0.00%" and a list nobody measured are the same picture,
    // and the reader who opens the exilus slot under a single-target ruler gets
    // the first and reads the second — reported as the calculator being stuck
    // when it had measured all eleven correctly. Said only on a COMPLETE scan,
    // so a run with holes in it cannot claim nothing mattered.
    const own = rows && st.ids ? rows.filter((k) => k && st.ids.has(k)) : null;
    const got = (own || Object.keys(st.by || {}))
      .map((k) => (st.by || {})[k]).filter(Boolean);
    if (!st.key || !got.length || got.some((g) => g.pct !== 0)) return "";
    return `<div class="scan-strip flat" role="status">` +
      `<span class="scan-txt">${escHtml(
        tr("all {n} measured — none of them changes this fight")
          .replace("{n}", got.length))}</span></div>`;
  }
  // THE COUNT IS THE LIST'S OWN, and it is DERIVED FROM THE ROWS ON SCREEN. `st.total` is how many SIMULATIONS this scan will run,
  // which is a different number from how many options the reader is looking at
  // — it carries the refine pass, and on an axis whose candidates are split
  // across several lists it carries the other lists too. Both cases read as a
  // denominator that does not match what is in front of you: a Kitgun's grip
  // list is five rows and said `12/23`, because one scan covers the grip and
  // the loader and only one of the two is ever open.
  //
  // So a caller that has rows hands them over and the strip counts those: how
  // many of THESE options have an answer, over how many are coming. It is
  // derived from the list rather than from the axis, so a list added tomorrow
  // — or one an axis splits into three — is right without being taught.
  const mine = rows && st.ids
    ? rows.filter((k) => k && st.ids.has(k)) : null;
  const total = mine ? Math.max(1, mine.length)
    : Math.max(1, st.total || 1);
  const done = mine ? mine.filter((k) => gainOf(k)).length
    : Math.min(st.done || 0, total);
  const pct = Math.round((done / total) * 100);
  return `<div class="scan-strip" role="status" aria-live="polite" title="${escHtml(
    tr("the ranking is still being measured — the order moves until it finishes"))}">` +
    `<span class="scan-bar"><i style="width:${pct}%"></i></span>` +
    `<span class="scan-txt">⚡ ${escHtml(tr("ranking"))} ${done}/${total}</span></div>`;
}

const gainChipFor = (id, where) => {
  const g = gainOf(id);
  // A HALF-FILLED RANKING HAS TO LOOK LIKE ONE.
  //
  // An option with no answer YET rendered exactly like one that finished with
  // nothing to say — no chip at all — while the list re-sorts on every result
  // that lands (an unranked option sorts last, so whatever arrives first sits
  // at the top). Read mid-scan that is a ranking which keeps changing its mind,
  // and the only way to find out it was not final was to click away and back
  // (report, 2026-08-13).
  //
  // The scan already counts itself; it just said so nowhere near the list being
  // read. `gainOf` has checked the key, so this only marks rows on the axis
  // actually being measured.
  // REFUSED, AND THE ROW SAYS WHY. A row with no chip reads as one nobody got
  // to; this one was measured and cannot be equipped, which is a different
  // thing and the only one the reader can act on.
  const no = gainAbout() === gainKey() ? (gainScan.refused || {})[id] : null;
  if (no) {
    return `<span class="gainchip no" title="${escHtml(no)}">${
      escHtml(tr("cannot equip"))}</span>`;
  }
  if (!g) {
    return gainScan.running && gainScan.want === gainKey()
      ? `<span class="gainchip pend" title="${escHtml(
          tr("still measuring — {a} of {b} options ranked so far, and the order moves until it finishes")
            .replace("{a}", gainScan.done).replace("{b}", gainScan.total))}">…</span>`
      : "";
  }
  // A ONE-RUN number is a SCREEN, not a measurement, and it has to read like
  // one. Measured across three seeds on a status mod, a single run lands
  // anywhere in a ±39-point band — wide enough to print a minus sign in front
  // of a mod worth +40%, which reads as adding status chance LOWERING the
  // damage. A damage mod barely moves, because paired seeds
  // cancel almost everything about it; a status mod's payoff is decided by
  // which procs land, which is the one thing the dice still choose.
  //
  // So the screen says "about", and only the second pass — the leaders, run
  // again with a tenth of the scenario's count — prints a bare number.
  // EVERY number here is an average of a few runs, so every number reads the
  // same way: approximate, and said to be. A status mod's payoff is decided by
  // which procs land, and ten runs narrows that without settling it.
  const why = tr("averaged over {n} runs — this number moves between scans, most of all for status mods")
    .replace("{n}", g.runs);
  return gainChip(g, `${where} · ${gainScan.metric} · ${gainScan.note} · ${why}`,
    gainTied(g));
};

// ---- the OPTIMIZER's quick calc ----------------------------------------
//
// SAME QUESTION, NO SLOTS. The builder asks "what if this mod went in THIS
// slot"; the optimizer has no slots, so the reference is the REQUIRED set and
// every mod is measured with-against-without it:
//
//     gain(X) = best(reference ∪ {X}) / best(reference ∖ {X}) − 1
//
// One formula, both directions. A pooled mod's numerator carries it (what it
// would add); a REQUIRED mod's denominator drops it (what it is contributing).
//
// `best` is a MAXIMUM OVER PAIRINGS, not a value — with three distinct
// elements a mod set is three builds, and on the Burston Prime the best is
// 3.3x the worst (2.074 against 0.627 kills/min, measured). Canonicalising
// instead would have frozen whichever pairing the insertion order produced:
// `builds::canonical_mods` normalises only the freedoms that are provably free
// and never moves the PARTITION. Taking the max is also the optimizer's own
// rule — it searches this dimension — so a chip cannot rank a mod under a
// build the search would never return.
let optGain = { key: null, running: false, base: 0, by: {}, orders: [], mode: "require",
  done: 0, total: 0, note: "", metric: "", ref: [] };
let optGainGen = 0;

/// The reference build's EVOLUTIONS: what the scope pins, tier by tier, and
/// the ladder stops at the first tier it does not. A tier carrying exactly one
/// option counts as pinned — a scope with one choice has made it.
function optRefEvos() {
  const out = [];
  for (const t of weaponEvos()) {
    const m = opt.evos[t.tier] || {};
    const ids = Object.keys(m);
    const pick = evoPinned(t.tier) || (ids.length === 1 ? ids[0] : null);
    if (!pick) break;
    out.push(pick);
  }
  return out;
}

/// The reference build's MODS. Either the required set, or — once a search has
/// produced one — the winner, which is the same question asked on a build that
/// is actually full. The required set is usually two or three cards, and a mod
/// measured there meets no diminishing returns at all, so flat base damage
/// reads high and everything conditional reads low. Which one is in use is on
/// screen, never inferred.
function optRefMods() {
  if (optGain.mode === "winner") {
    const w = optWinnerMods();
    if (w && w.length) return w.slice();
  }
  return Object.keys(opt.mods).filter((id) => opt.mods[id] === "fixed");
}

/// The winner of the ranking on screen, if there is one.
function optWinnerMods() {
  const r = (typeof optLast !== "undefined" && optLast && optLast.results) || [];
  return r.length && r[0].mods ? r[0].mods.slice() : null;
}

const optGainKey = () => JSON.stringify([$("weapon").value, opt.mods, optRefEvos(),
  optGain.mode, optWinnerMods(), gainScenario().scenario]);

/// The reference build's ARCANES: what the scope pins in each pool, and
/// nothing where it pins nothing — "no arcane" is a real state, not a gap.
function optRefArcanes() {
  return weaponAxes().arcanes.map((ax) => arcanePinnedIn(ax.pool) || "none");
}

/// Every option the optimizer can show a chip for — mods, ARCANES and
/// EVOLUTIONS alike, because all three are marked the same way and the
/// question asked of them is the same one.
///
/// Each candidate is the ONE set that differs from the reference: a required
/// option drops itself, everything else adds itself. Only mods carry an
/// element, so only they can move the pairing — but an EVOLUTION can too,
/// indirectly, since tier 1 installs the form whose innate element the whole
/// partition then includes. Arcanes cannot, so they reuse the reference's
/// orders and cost one engagement each.
function optGainCandidates(ref, refEvos, refArc) {
  const inRef = new Set(ref);
  const out = poolWithRivens()
    .filter((m) => !famReqBy(m))
    .map((m) => ({
      id: m.id,
      kind: "mod",
      // Family exclusivity applies to the SET BEING MEASURED, not only to the
      // scope: adding a mod whose family is already in the reference would
      // price a build the arsenal refuses.
      mods: inRef.has(m.id)
        ? ref.filter((x) => x !== m.id)
        : ref.filter((x) => !m.family || (modById(x) || {}).family !== m.family).concat([m.id]),
      evolutions: refEvos,
      drops: inRef.has(m.id),
    }));

  // ARCANES. One seat per pool, so this is a REPLACEMENT rather than an
  // addition — the same shape the builder's arcane axis has. An arcane already
  // pinned is measured by emptying its seat, which is what "what is it
  // contributing" means when the alternative is nothing.
  weaponAxes().arcanes.forEach((ax, i) => {
    (ax.options || []).forEach((a) => {
      const drops = refArc[i] === a.id;
      const next = refArc.slice();
      next[i] = drops ? "none" : a.id;
      out.push({ id: a.id, kind: "arcane", mods: ref, evolutions: refEvos, drops,
        override: { arcane: next } });
    });
  });

  // EVOLUTIONS. The LADDER decides which tiers are askable: a tier is open
  // only once the one below it is filled, so the candidate set is the
  // reference's prefix with this tier's option substituted and everything
  // above it dropped. Asking about a locked tier would price a build the
  // builder will not let you assemble (the rule `check_gain_axes` asserts of
  // the builder's own scan).
  weaponEvos().forEach((t) => {
    if (t.tier > refEvos.length + 1) return;
    t.options.forEach((o) => {
      const drops = refEvos[t.tier - 1] === o.id;
      const next = drops
        ? refEvos.slice(0, t.tier - 1)
        : refEvos.slice(0, t.tier - 1).concat([o.id]);
      out.push({ id: o.id, kind: "evo", mods: ref, evolutions: next, drops,
        override: { evolutions: next } });
    });
  });
  return out;
}

async function scanOptGains(onTick) {
  const gen = ++optGainGen;
  const live = () => gen === optGainGen;
  const { name, scenario } = gainScenario();
  const ref = optRefMods();
  const evolutions = optRefEvos();
  const refArc = optRefArcanes();
  optGain = { ...optGain, key: optGainKey(), running: true, base: 0, floor: 0, by: {}, orders: [],
    done: 0, total: 0, note: name, metric: "", ref };
  const cands = optGainCandidates(ref, evolutions, refArc);

  // ONE call for every set the scan will measure, the reference first. The
  // browser is never taught to pair elements: that would be a second copy of
  // `elements::combine`'s innate rules, and it would be wrong the first time a
  // weapon carried an innate element — the Burston's Incarnon form carries
  // Heat, so Cold + Toxin is already Viral + Heat with no Heat mod equipped.
  const base = { ...tennoPayload(), weapon: $("weapon").value, evolutions,
    arcane: refArc, rivens: rivenPayload() };
  const pr = await api("/api/pairings", { ...base, ...scenario,
    sets: [{ mods: ref, evolutions }]
      .concat(cands.map((c) => ({ mods: c.mods, evolutions: c.evolutions }))) });
  if (!live()) return;
  if (!pr || !pr.ok) { optGain.running = false; if (onTick) onTick(optGain); return; }
  const orders = pr.sets.map((x) => x.orders);

  // BY THE SCENARIO'S OWN METRIC, whatever it is. `per_minute` is the question
  // that decides which baseline is read — a rate over the engagement against a
  // field the run reports directly — and it is the metric's to answer.
  const useKills = metricOf(scenario.metric).per_minute;
  const read = (r) => readGain(r, useKills)?.v ?? null;
  const seOf = (r) => readGain(r, useKills)?.se ?? 0;
  // The runs behind each number, so the winner of a candidate set pairs against
  // the winner of the reference set rather than being compared to it as an
  // independent sample — same seed, same run order, so run `i` is run `i`.
  const runsOf = (r) => readGain(r, useKills)?.runs ?? [];
  // Every (set, pairing) is ONE job, flattened into one queue so a set with
  // three pairings does not hold a lane while another waits — the same shared
  // cursor the builder's scan uses, for the same reason.
  const jobs = [];
  orders.forEach((os, si) => os.forEach((o, oi) => jobs.push({
    si, oi, mods: o.mods,
    // The reference is set 0; every other set is a candidate and carries
    // whatever it changes ABOUT the build that is not a mod.
    override: si === 0 ? {} : (cands[si - 1].override || {}),
  })));
  optGain.total = jobs.length;
  const got = orders.map((os) => os.map(() => null));
  const ses = orders.map((os) => os.map(() => 0));
  const runsAt = orders.map((os) => os.map(() => []));
  let cursor = 0;
  await Promise.all((await gainLanes()).map(async (lane) => {
    for (;;) {
      if (!live()) return;
      const j = jobs[cursor++];
      if (!j) return;
      const r = await laneAsk(lane, "/api/simulate",
        { ...base, ...scenario, mods: j.mods, ...j.override }, live);
      if (!live()) return;
      if (r === null) return;            // the pool was taken twice — stand down
      got[j.si][j.oi] = read(r);
      ses[j.si][j.oi] = seOf(r);
      runsAt[j.si][j.oi] = runsOf(r);
      optGain.done++;
      if (onTick) onTick(optGain);
    }
  }));
  if (!live()) return;

  const best = (si) => {
    const vs = got[si].filter((x) => x != null);
    return vs.length ? Math.max(...vs) : null;
  };
  const b = best(0);
  optGain.base = b || 0;
  optGain.metric = useKills ? tr("kill rate") : tr("DPS");
  // The scan's own resolution, from the runs already paid for rather than one
  // more at another seed — see `readGain`.
  const bSe = b ? ses[0][got[0].indexOf(b)] : 0;
  if (b) optGain.floor = bSe / b;
  // THE PAIRING LADDER — the reference's own orders, ranked. It goes first on
  // screen because the swing between pairings is larger than any single mod's.
  optGain.orders = orders[0].map((o, i) => ({
    combined: o.combined, leftover: o.leftover, mods: o.mods, value: got[0][i],
    pct: b && got[0][i] != null ? got[0][i] / b - 1 : null,
  })).sort((x, y) => (y.value || 0) - (x.value || 0));
  if (b) {
    cands.forEach((c, i) => {
      const v = best(i + 1);
      if (v == null) return;
      // `drops` decides which side of the ratio the reference sits on, which
      // is what lets one formula answer both questions.
      const [withX, without] = c.drops ? [b, v] : [v, b];
      if (!without) return;
      const vi = got[i + 1].indexOf(v);
      const bi = got[0].indexOf(b);
      const o = orders[i + 1][vi] || {};
      // `drops` already decided which side is which; the uncertainty is the
      // same either way, so it is built from the two measurements as they sit.
      const [seWith, seWithout] = c.drops ? [bSe, ses[i + 1][vi]] : [ses[i + 1][vi], bSe];
      const [rWith, rWithout] = c.drops
        ? [runsAt[0][bi], runsAt[i + 1][vi]]
        : [runsAt[i + 1][vi], runsAt[0][bi]];
      optGain.by[c.id] = {
        ...gainOver({ v: withX, se: seWith, runs: rWith },
                    { v: without, se: seWithout, runs: rWithout }),
        runs: scenario.runs,
        combined: o.combined || [], leftover: o.leftover || [], drops: c.drops };
    });
  }
  optGain.running = false;
  if (onTick) onTick(optGain);
}

/// The gain for `id` in the optimizer, or null when the scan does not cover
/// the scope on screen.
const optGainOf = (id) => (optGain.key === optGainKey() ? optGain.by[id] || null : null);

/// A pairing, as the elements a player reads: what it MAKES, then whatever is
/// left over uncombined. The leftover is dimmed because it is not a choice —
/// it is what the partition could not pair, innate elements included.
const pairingLabel = (combined, leftover) =>
  (combined || []).map((t) => `<span class="pw">${DT(t)}</span>`).join(" + ")
  + (leftover || []).map((t) => `<span class="pw dim">${DT(t)}</span>`).join(" + ")
    .replace(/^(?=.)/, (combined || []).length ? " + " : "");

/// The optimizer's gain chip. One number per row, NEVER a range — the pairing
/// is one decision shared by the whole scope and is stated once, above.
///
/// ...except where a candidate LANDS somewhere else. Adding a fourth element
/// re-pairs everything: Stormbringer on a Viral + Heat build measures −65%
/// despite reading "+90% Electricity", because the best it can reach is Blast
/// + Corrosive (0.728 against 2.074, measured). Without that label the number
/// looks like a bug — which is exactly what happened the last time a chip went
/// negative for a reason the row does not state, which reads as adding status
/// chance LOWERING the damage.
const optGainChipFor = (id) => {
  const g = optGainOf(id);
  if (!g) return "";
  const why = tr("averaged over {n} runs — this number moves between scans, most of all for status mods")
    .replace("{n}", g.runs);
  const how = g.drops ? tr("what it contributes: this scope with it, against without")
    : tr("what it would add: this scope plus it, against the scope as it stands");
  return gainChip(g, `${how} · ${optGain.metric} · ${optGain.note} · ${why}`);
};

/// The pairing a candidate lands on, shown only when it DIFFERS from the
/// reference's — which also silences it for a second mod of an element the
/// build already has, since those pool and change no partition at all.
const optPairingNoteFor = (id) => {
  const g = optGainOf(id);
  if (!g || !optGain.orders.length) return "";
  const best = optGain.orders[0];
  const same = JSON.stringify([g.combined, g.leftover])
    === JSON.stringify([best.combined, best.leftover]);
  if (same) return "";
  return `<div class="pairnote">${g.drops ? "⇠" : "⇢"} ${pairingLabel(g.combined, g.leftover)}</div>`;
};

/// **ONE CONTROL FOR EVERY QUANTIFIABLE AXIS** — a CARD saying what is
/// installed, with a ⋯ in its corner that opens the RANKED list.
///
/// The arcane slot has been this shape all along and is the model: a card while
/// something is in it, a `+ add` plate while nothing is, and a menu offering
/// Swap and Remove. The parts, the valence element and the evolution tiers are
/// the same question — pick one of N, each worth a measurable amount on THIS
/// build — so they are the same control.
///
/// **WHETHER THE AXIS CAN BE EMPTY IS ONE MENU ITEM, NOT A SECOND SHAPE.**
/// `Remove` appears where nothing-installed is a real state (an arcane, an
/// evolution tier) and does not where it is not: a Kitgun has a grip, and every
/// copy of a Lich weapon carries an element. Offering it there would be a verb
/// that can never be used, which is the "always drawn and disabled" noise this
/// page already refuses — and hiding it costs no consistency, because the
/// consistency a reader actually reads is the CARD and the ranked list behind
/// it, not the length of a menu they have to open to see.
///
/// It registers with `ddReg` and opens through `ddOpen`, so the list, its
/// search and its ordering are the dropdown's own — only the TRIGGER differs.
function rankedSlot(id, cfg) {
  ddReg.set(id, {
    value: cfg.value,
    items: rankedItems(cfg),
    search: cfg.items.length > 8,
    // WHICH AXIS THIS LIST RANKS — what `openRanked` measures, what the strip
    // inside the list reports on, and what tells `ddRender` to rank its rows.
    axis: cfg.axis,
    axisLabel: cfg.label,
    onPick: cfg.onPick,
  });
  const card = cfg.card;
  if (!card) {
    // NOTHING INSTALLED. A locked tier says why instead of inviting a click it
    // would refuse.
    return `<div class="slot empty axis${cfg.locked ? " axlocked" : ""}" data-slot="${id}"${
      cfg.lockedWhy ? ` title="${escHtml(cfg.lockedWhy)}"` : ""}>
      <span class="axl">${escHtml(cfg.label)}</span>
      <span class="plus">${cfg.locked ? escHtml(cfg.lockedWhy || "") : "+ " + escHtml(cfg.addLabel || cfg.label)}</span>
    </div>`;
  }
  const icon = card.icon ? `<img class="eicon" src="${IMG(card.icon)}" alt="">` : "";
  const lines = (card.lines || []).map((x) => `<div>${escHtml(x)}</div>`).join("");
  return `<div class="slot filled axis${card.broken ? " broken" : ""}" data-slot="${id}" data-id="${
    escHtml(String(cfg.value))}"${card.title ? ` title="${escHtml(card.title)}"` : ""}>
    <span class="axl">${escHtml(cfg.label)}</span>
    ${icon}<div class="info"><div class="mn">${card.href ? wl(card.name, card.href) : escHtml(card.name)}${
      card.chips || ""}</div><div class="ed">${lines}</div>${card.notes || ""}</div>
    <button class="dots" title="${escHtml(tr("options"))}">⋯</button>
  </div>`;
}

/// The rows a `rankedSlot` offers, ordered by gain.
function rankedItems(cfg) {
  // NEITHER RANKED NOR CHIPPED HERE. Both are read from the SCAN, which has
  // not started when a list is registered — `ddRender` does them, every time
  // it draws.
  return cfg.items.map((it) => ({
    value: it.value,
    label: it.label,
    hint: it.hint,
    disabled: it.disabled,
    key: it.key,
    badge: it.extra || "",
  }));
}

/// OPEN A RANKED LIST, and start measuring it.
///
/// **THE SCAN FIRES ON OPEN, like the mod and arcane pickers**. Scanning from
/// RENDER is right for rows of chips, "all on screen at once … which is why
/// they can afford to answer without being opened", and wrong for cards — the
/// options live inside a closed list now, so an eager scan spends a fight per
/// candidate on numbers nobody can see, and does it again on every repaint.
///
/// The list opens FIRST and the scan starts after, so the rows are there
/// immediately carrying their "…" chips rather than after a measurement.
function openRanked(id, anchor) {
  const cfg = ddReg.get(id);
  if (!cfg) return;
  ddOpen(id, anchor);
  if (!cfg.axis) return;
  ensureGains(cfg.axis, () => {
    // REPAINT THE OPEN LIST, and only while it is open — the mod picker's own
    // rule. A closed list has nobody reading it, and its next open re-renders.
    if (!$("dd-popover").hidden) ddRender(id, $("dd-search").value);
  }, true);
}

/// The ⋯ menu a `rankedSlot` opens — Swap, and Remove where the axis has one.
function openSlotMenu(anchor, id, cfg) {
  closePopovers();
  const menu = $("slot-menu");
  const swap = `<div class="mi" data-a="swap">${escHtml(tr("Swap") + " " + cfg.label)}</div>`;
  const rm = cfg.removable
    ? `<div class="mi danger" data-a="remove">${escHtml(tr("Remove") + " " + cfg.label)}</div>` : "";
  menu.innerHTML = swap + rm;
  place(menu, anchor);
  menu.querySelector('[data-a="swap"]')
    .addEventListener("click", () => (cfg.onSwap ? cfg.onSwap() : openRanked(id, anchor)));
  const r = menu.querySelector('[data-a="remove"]');
  if (r) r.addEventListener("click", () => { closePopovers(); cfg.onPick(""); });
}

/// WIRE A BLOCK'S SLOTS, once its markup is in the DOM. One call per block
/// rather than per slot: the cards are re-rendered wholesale on every change,
/// so a listener bound to a card dies with the card that carried it — the
/// arena's own lesson.
function bindRankedSlots(box, cfgs) {
  box.querySelectorAll(".slot.axis").forEach((el) => {
    const id = el.dataset.slot;
    const cfg = cfgs[id];
    if (!cfg || cfg.locked) return;
    const dots = el.querySelector(".dots");
    if (dots) {
      // THE MENU HANGS OFF THE ⋯, NOT OFF THE CARD. `place` puts a popover's
      // top-left under its anchor's bottom-left, so anchoring to the whole card
      // dropped the menu at the card's BOTTOM-LEFT while a mod slot's — the one
      // that passes its own button — came out under the ⋯ at the top right.
      // Same control, same gesture, two different places on the page.
      dots.addEventListener("click", (e) => { e.stopPropagation(); openSlotMenu(e.currentTarget, id, cfg); });
    } else {
      // An EMPTY slot opens the list on a click anywhere, which is the mod and
      // arcane slots' own rule: there is nothing in it to select, so the whole
      // plate is the button.
      el.addEventListener("click", () => openRanked(id, el));
    }
  });
}

/// The picker's ONE ordering rule, over whatever keys an axis has.
/// Descending on every key, the chosen one first, the rest in a fixed order —
/// and an unscanned option sorts last whichever way the arrow points, because
/// an absent answer is not a small one.
function gainSort(a, b, keys) {
  const ga = gainOf(a.id), gb = gainOf(b.id);
  if (!ga !== !gb) return ga ? -1 : 1;
  // A GAIN IS RANKED BY ITS MEAN, and the band is shown beside it.
  //
  // The mean is the unbiased estimate of what an option is worth; the spread is
  // a property of the MEASUREMENT, not of the option — run it long enough and
  // the spread goes to zero while the mean stays put. Ranking on a lower bound
  // (`pct - se`) was tried and reverted for exactly that reason: it
  // systematically demotes whatever is merely hard to measure, and a status mod
  // is hard to measure by nature, so the list would have been telling players
  // something about the simulator rather than about their build.
  //
  // THIS DOES NOT MAKE THE ORDER STABLE, and it is not meant to. Two options
  // whose bands overlap are genuinely unranked, so which sits higher can move
  // between scans — that is the measurement talking, and the chip says so with
  // its ±. The answer to an order that moves is more runs, not a different
  // ranking rule; hiding it behind a pessimistic sort would have made a coin
  // flip look like a verdict.
  const cmp = { gain: () => (ga && gb ? gb.pct - ga.pct : 0),
                drain: () => (b.drain || 0) - (a.drain || 0),
                name: () => String(b.name).localeCompare(String(a.name)) };
  for (const k of keys) {
    const c = cmp[k]();
    if (Math.abs(c) > 1e-9) return pickerPrefs.dir === "desc" ? c : -c;
  }
  return 0;
}

/// The gain for `id`, or null when this axis position has not been scanned.
const gainOf = (id) => (gainAbout() === gainKey() ? gainScan.by[id] || null : null);

/// QUICK CALC — page level, above the mods.
///
/// It is ONE configuration for every slot's question, so it does not live
/// inside any slot's picker. Two settings: the SCENARIO (a
/// saved one, which also decides KPM-or-DPS) and how many runs. There is no
/// run button because there is no slot here to run against — opening a
/// picker computes with these, which is what "sorted by effect by default"
/// means in practice.
function renderQuickCalc() {
  const box = $("quick-calc");
  if (!box) return;
  const on = gainPrefs.on !== false;
  box.innerHTML =
    `<label class="pc-h" title="${escHtml(tr("rank a slot's options by what they would change — off, nothing is simulated"))}">` +
    `<input type="checkbox" id="gp-on"${on ? " checked" : ""}> ⚡ ${escHtml(tr("Quick calc"))}</label>` +
    (!on ? "" :

    // WHICH FIGHT, stated and not chosen. It is the simulator's, always — see
    // `gainScenario`. Naming it here is the whole reason the old picker could
    // lie for a session without being noticed: a reader could not see which
    // fight the numbers beside every mod had come from.
    `<span class="pc-scen" id="gp-scen" title="${escHtml(tr("the fight these numbers are measured in — the quick calc runs the Simulator's own scenario, so switch it there and every chip follows"))}">${escHtml(gainScenario().name)}</span>` +

    // HOW MANY RUNS a chip's number is averaged over. Ten is the floor, not a
    // suggestion: under it a status mod's chip is a coin flip. It is clamped on
    // the way out (`gainRuns`) as well as here, because a number input accepts
    // an empty string and a paste.
    `<label class="pc-runs" title="${escHtml(tr("how many simulations each option is averaged over — 10 is the floor, and more costs proportionally more time"))}">` +
    `<input type="number" id="gp-runs" min="${GAIN_RUNS_MIN}" max="${GAIN_RUNS_MAX}" step="10" value="${gainRuns()}">` +
    `<span>${escHtml(tr("runs"))}</span></label>` +

    // PROGRESS while it runs, and an invitation before it has. The run counts
    // ("1x -> 10x") are gone from here: they were a property
    // of the algorithm back when there were two passes at two precisions. The
    // count above is the reader's own, and every chip still carries the one its
    // number came from.
    `<span class="pc-note">${gainScan.running
      ? `${gainScan.done}/${gainScan.total}`
      : (gainScan.note ? "" : escHtml(tr("open a slot to rank its mods by effect")))}</span>`);
  // Every click stays inside: a redraw detaches these nodes, and the document
  // outside-click handler closes on a target whose `.popover` ancestor is gone.
  box.onclick = (e) => e.stopPropagation();
  $("gp-on").onchange = (e) => {
    e.stopPropagation();
    gainPrefs = { ...gainPrefs, on: $("gp-on").checked };
    // A stale ranking must not outlive the switch, and "提升" must not stay
    // selected with nothing behind it.
    if (!gainPrefs.on) {
      // OFF MEANS STOP, not "stop asking for more". A scan already in flight
      // kept its workers and its right to write, so switching off and back on —
      // the first thing anyone does to something that looks stuck — resumed
      // into the state it was stuck in. Now it is the rebuild button.
      restartCalc();
      if (pickerPrefs.sort === "gain") { pickerPrefs.sort = "drain"; savePickerPrefs(); }
    }
    saveGainPrefs();
    renderQuickCalc();
    if (!$("mod-popover").hidden) { renderTools(); renderMenu(pickerSlot, $("mod-search").value); }
    renderEvo(); renderMode();
  };
  // A COUNT CHANGE IS A NEW QUESTION, so it re-runs rather than waiting for
  // the next picker to open — the same contract the scenario dropdown has.
  // `change` and not `input`, because a half-typed "1" on the way to "100" is
  // not a request to re-scan at one run.
  const gr = $("gp-runs");
  if (gr) gr.onchange = (e) => {
    e.stopPropagation();
    gainPrefs = { ...gainPrefs, runs: Number(gr.value) };
    saveGainPrefs();
    gr.value = gainRuns(); // show what was actually taken
    refreshGains();
  };
  // (Picking a scenario is handled by the dropdown's own `onPick`, which does
  // the same thing it always did: save, then answer the new question NOW
  // rather than at the next time a picker happens to open.)
}

/// WHAT THE CALCULATOR IS DOING, AND WHAT IS LEFT OF IT.
///
/// THE POOL'S HEALTH WAS INVISIBLE. A lane dies quietly — the module did not
/// download, the renderer reclaimed the worker, a stop abandoned the pool — and
/// nothing on the page said so, so a scan that lost its workers looked exactly
/// like one that was slow. The reader's only signal was that numbers stopped
/// appearing, and their only move was a reload that rebuilt the same pool the
/// same way.
///
/// IT IS COLLAPSED UNTIL IT HAS SOMETHING TO SAY. A panel that is always there
/// is furniture; this one opens while a scan is running and stays open after
/// one that failed, which are the two moments a reader wants it.
/// OPEN UNTIL SOMEBODY CLOSES IT. A tab is what a reader does not notice, and
/// not noticing is the whole failure this panel exists to end — the report was
/// "the quick calc stopped and there is no indication of anything". Collapsing
/// is remembered, so the reader who does not want it says so once.
let calcStatusOpen = localStorage.getItem("wfsim-calc-status") !== "closed";
/// Opened while there is NOTHING to report — the reader going looking for the
/// rebuild button. Not persisted: an idle panel left open for ever is the
/// clutter collapsing exists to avoid.
let calcStatusPeek = false;
function renderCalcStatus() {
  const box = $("calc-status");
  if (!box) return;
  const made = pool.filter(Boolean);
  const alive = made.filter((l) => !l.dead).length;
  const lost = made.length - alive;
  const busy = gainScan.running;
  // NEVER HIDDEN, because the way out lives in here.
  //
  // A panel that disappears whenever there is nothing to report puts the
  // rebuild button behind the very condition it exists for: a calculator wedged
  // in a state that is neither busy nor failed shows no surface at all, and the
  // reader whose list will not produce numbers has a reload and nothing else.
  // IDLE COLLAPSES TO THE TAB instead — the panel is one click away at all
  // times and costs a tab's worth of corner when quiet.
  box.hidden = false;
  const idle = !busy && !lost && !gainScan.failed;
  const open = idle ? calcStatusPeek : calcStatusOpen;
  // THE PHASE, WHERE THERE IS ONE. `0/77` is not a stall — it is the BASELINE
  // being measured, which every candidate is compared against and which runs
  // before any of them. It can be two of them, when nothing died under the
  // ruler's own metric and the question falls back to DPS. A counter that only
  // counts candidates has nothing to say through either, and the reader reads
  // the silence as a hang.
  // HOW LONG THIS WILL TAKE, from what the baseline actually cost — shown only
  // while it is still true, and only when it is long enough to be worth
  // reading. A number under a couple of seconds is noise a reader has to
  // dismiss; a minute is the one they wanted before they started.
  const left = busy && gainScan.etaMs ? Math.round(gainScan.etaMs / 1000) : 0;
  const head = busy
    ? (gainScan.phase
        ? escHtml(gainScan.phase)
        : `${escHtml(tr("calculating"))} ${gainScan.done}/${gainScan.total}`)
    : (gainScan.failed ? escHtml(tr("the last calculation did not finish"))
                       : escHtml(tr("calculator")));
  if (!open) {
    box.className = `calc-status${gainScan.failed ? " bad" : ""}`;
    box.innerHTML = `<button class="cs-tab" id="cs-tab">⚡ ${head}${
      lost ? ` <span class="cs-lost">${lost}</span>` : ""}</button>`;
  } else {
    box.className = `calc-status open${gainScan.failed ? " bad" : ""}`;
    box.innerHTML =
      `<button class="cs-tab" id="cs-tab">⚡ ${head} ▾</button>` +
      `<div class="cs-body">` +
      // WHICH FIGHT AND WHICH LIST, because "calculating" alone does not say
      // whether it is the thing you are looking at.
      `<div class="cs-row"><span>${escHtml(tr("fight"))}</span><b>${
        escHtml(gainScenario().name)}</b></div>` +
      `<div class="cs-row"><span>${escHtml(tr("measuring"))}</span><b>${
        escHtml(gainScan.note && !gainScan.failed ? gainScan.note : "—")}</b></div>` +
      // WHAT STEP, AND HOW FAR THROUGH IT. Two facts, because the counter is
      // only meaningful during the candidate pass and the phase is only
      // meaningful outside it.
      `<div class="cs-row"><span>${escHtml(tr("step"))}</span><b>${
        escHtml(gainScan.phase || tr("ranking the options"))}</b></div>` +
      `<div class="cs-row"><span>${escHtml(tr("ranked"))}</span><b>${
        gainScan.done} / ${gainScan.total}</b></div>` +
      // THE ONE FACT THAT WAS MISSING. Workers alive against workers made: a
      // pool that has lost half of itself is the difference between slow and
      // broken, and nothing said it.
      `<div class="cs-row"><span>${escHtml(tr("workers"))}</span><b>${alive} / ${
        made.length || poolSize()}${lost ? ` — ${lost} ${escHtml(tr("lost"))}` : ""}</b></div>` +
      (left > 2
        ? `<div class="cs-row"><span>${escHtml(tr("about"))}</span><b>${
          escHtml(tr("{s}s left").replace("{s}", left))}</b></div>`
        : "") +
      (gainScan.failed
        ? `<div class="cs-why">${escHtml(gainScan.note || tr("unknown"))}</div>` : "") +
      // A WAY OUT THAT IS NOT A RELOAD. A reload rebuilds the same pool the
      // same way; this drops the dead workers so the next question opens fresh
      // ones, which is the move a reader could not previously make at all.
      `<button class="ghost-btn small" id="cs-reset">${
        escHtml(tr("rebuild the calculator"))}</button>` +
      `</div>`;
  }
  const tab = $("cs-tab");
  if (tab) tab.onclick = () => {
    if (idle) { calcStatusPeek = !calcStatusPeek; renderCalcStatus(); return; }
    calcStatusOpen = !calcStatusOpen;
    try {
      localStorage.setItem("wfsim-calc-status", calcStatusOpen ? "open" : "closed");
    } catch (_) { /* a browser with storage off still gets the panel */ }
    renderCalcStatus();
  };
  const reset = $("cs-reset");
  if (reset) reset.onclick = () => {
    restartCalc();
    calcStatusPeek = false;
    renderCalcStatus();
    refreshGains();
  };
}

/// STOP EVERYTHING THE QUICK CALC IS DOING, and leave nothing that can write.
///
/// THE GENERATION IS BUMPED FIRST, before a worker is touched. A scan in flight
/// is `live()` until something bumps it, so a restart that only replaced the
/// state left the old scan free to finish into the NEW one and stamp its key —
/// filing a ranking of a fight nobody is looking at as complete, which is worse
/// than the stall it was asked to end.
///
/// BOTH WAYS OUT ARE THIS ONE FUNCTION: the rebuild button, and switching the
/// quick calc off. A reader flicks that switch when it looks stuck, so it has
/// to mean what the button means — anything less makes the obvious gesture the
/// one that does not work.
function restartCalc() {
  gainGen += 1;
  gainPending = null;
  resetPool();
  gainScan = { key: null, want: null, running: false, base: 0, floor: 0, by: {},
    done: 0, total: 0, note: "", metric: "", failed: false, lanesLost: 0 };
}

/// DROP EVERY WORKER, so the next question builds fresh ones.
///
/// A dead lane is replaced on demand now, so this is not the recovery path — it
/// is the reader's own, for the case nobody predicted. `abandon` first, because
/// a worker holding a live request has waiters that must be settled rather than
/// left hanging on a lane nobody will read again.
function resetPool() {
  for (const l of pool) {
    if (!l) continue;
    try { l.abandon(); } catch (_) { /* already gone */ }
    try { l.worker.terminate(); } catch (_) { /* already gone */ }
  }
  pool = [];
  gainPool = null;
}

/// Re-run whatever quick-calc surface is on screen. Called after ANY scenario
/// edit: the scan is measured under the scenario, so a change to it makes the
/// numbers on screen answers to a question nobody is asking any more.
///
/// It is not a repaint — `ensureGains` compares the key first, so a change the
/// chosen scenario does not care about costs nothing here. Evolution rows scan
/// without being opened, so they always refresh; the pickers only when open.
function refreshGains() {
  // The BOX first and unconditionally — it names the fight being measured, so
  // it has to follow a switch even when the scan itself is off.
  renderQuickCalc();
  if (gainPrefs.on === false) return;
  // **AN OPEN PICKER RE-ASKS; A SHUT ONE HAS NOTHING TO RE-ASK**. Every ranked axis now measures when its list is OPENED, so an
  // open list is the only place an answer exists that a fight change can make
  // stale — and all three kinds of list are treated the same way here, which
  // is the point.
  //
  // IT WAS A REPAINT FOR TWO OF THEM. The mod and arcane pickers were
  // re-rendered without being re-measured, and the freshness check passed
  // anyway because this function ended in `renderEvo()` — which asked for an
  // EVOLUTION scan, which made `gainScan.key` catch up with the fight while the
  // open mod picker's own chips still answered the old one. A check passing for
  // the wrong reason is what hid it.
  if ($("mod-popover") && !$("mod-popover").hidden) {
    renderTools();
    ensureGains({ kind: "mods", idx: pickerSlot },
      () => { if (!$("mod-popover").hidden) renderMenu(pickerSlot, $("mod-search").value); });
  }
  if ($("arcane-popover") && !$("arcane-popover").hidden) {
    ensureGains({ kind: "arcane", idx: arcaneSlotIdx },
      () => { if (!$("arcane-popover").hidden) renderArcaneMenu($("arcane-search").value); });
  }
  const dd = $("dd-popover");
  if (dd && !dd.hidden && dd._anchor) {
    const id = dd._anchor.dataset.slot || dd._anchor.dataset.dd;
    if (id && (ddReg.get(id) || {}).axis) openRanked(id, dd._anchor);
  }
  renderMode();
}

/// Compute this axis position's ranking, unless it is already on screen.
/// `gainKey` covers the axis, the build, the scenario and the settings, so
/// re-opening the same picker costs nothing and any edit invalidates it.
/// `user` — a person opened this list, rather than a repaint asking again for
/// one already on screen. It is the difference between preempting and queueing;
/// see the comment on the queue below.
function ensureGains(axis, repaint, user) {
  // Nothing to measure against yet. The evolution rows scan without being
  // opened, so on a cold load they can fire before `initPresets` has seeded
  // the scenario library — and a scan with no named scenario is one nobody
  // can reproduce or compare against (it labelled itself "—").
  if (gainPrefs.on === false) return;
  if (!scenarioList().length) return;
  gainAxis = axis;                       // so the key describes what we want
  // Is what we have MEASURED the fight on screen now? The key is stamped on
  // completion, so this means answered and nothing else — a scan that died
  // half way leaves it null and the next request re-asks, which is the whole
  // point of moving it there.
  if (gainScan.key === gainKey()) return;
  // …AND IS ONE ALREADY IN FLIGHT FOR IT? A separate question from the line
  // above, and it has to be: one check covering both cannot tell "answering"
  // from "answered", and a scan that never finishes is then filed for ever as
  // one that did.
  if (scanIsLive() && gainScan.want === gainKey()
      && JSON.stringify(gainScan.axis) === JSON.stringify(axis)) return;
  // A running scan is STALE and gives way — but only to its own axis. The mod
  // picker and the evolution rows both ask on every refresh (`refreshGains`
  // ends in `renderEvo`), so "the newest request wins" makes the two cancel
  // each other on every repaint and neither ever finishes. Which axis is asking
  // is not a staleness signal; the fight moving is.
  // A PERSON ASKING PREEMPTS; A REPAINT WAITS ITS TURN.
  //
  // The two are not the same request and were treated as one. Opening a slot is
  // a decision — the reader has stopped caring about the list they were looking
  // at — and queueing it behind a scan that is 87 melee engagements deep means
  // minutes before the list they just opened says anything, which reads as the
  // calculator being stuck. A REPAINT is not a decision: the mod picker and the
  // evolution rows both re-ask on every refresh, and letting those preempt each
  // other is what made the two cancel each other for ever and neither finish.
  //
  // So the queue stays, for the case it was built for, and a user request goes
  // straight past it. `scanGains` bumps the generation, so whatever was running
  // stands down at its next await — bounded to one outstanding simulation per
  // lane rather than the whole queue.
  if (user && scanIsLive()) gainPending = null;
  if (!user && scanIsLive()
      && JSON.stringify(gainScan.axis) !== JSON.stringify(axis)) {
    // …BUT IT IS NOT FORGOTTEN. Dropping it silently is what made a player have
    // to click between two evolutions until the numbers appeared (report,
    // 2026-08-13): the evolution rows ask on EVERY refresh while a picker asks
    // only while it is open, so with a picker open the evolution request was
    // dropped and nothing ever re-asked — the running scan's completion
    // repaints the caller that started it, which is the picker, not the rows.
    gainPending = { axis, repaint };
    return;
  }
  // A REJECTION HERE STOPPED THE CALCULATOR FOR GOOD. This is launched without
  // `await`, so anything that throws inside would otherwise leave `running`
  // true and the counter frozen. The scan is handed the LIST'S REPAINT and
  // draws nothing itself — `paintCalc` owns every surface, including the queue
  // taking its turn, so a new exit path cannot forget one of them.
  scanGains(axis, repaint).catch((e) => {
    gainStop(`${tr("the calculator stopped")}: ${(e && e.message) || e}`);
  });
}

function familyConflict(mod, exceptIdx) {
  if (!mod.family) return false;
  return slots.some((s, i) => { if (i === exceptIdx || !s.mod) return false; const o = modById(s.mod); return o && o.family === mod.family; });
}

// Rows grouped under STICKY headings, each section in its own box.
//
// A sticky element is confined to its containing block, so headings that are
// all siblings of the rows share one: the first one sticks at the top and
// never leaves, and the second slides underneath it — two headings on one
// line. A box per section is the whole fix: each heading
// sticks while its own rows are on screen and is pushed out by the next.
function sectionedRows(items, sectionOf, rowHtml) {
  const parts = [];
  let cur = null;
  items.forEach((m, i) => {
    const s = sectionOf(m);
    if (s !== cur) {
      if (cur !== null) parts.push("</div>");
      cur = s;
      parts.push(`<div class="menu-sect"><div class="menu-head">${escHtml(tr(s))}</div>`);
    }
    parts.push(rowHtml(m, i));
  });
  if (cur !== null) parts.push("</div>");
  return parts.join("");
}

/// ONE MOD ROW, drawn by the builder's picker and by the optimizer's scope.
///
/// Both modules show the same card — polarity, image, the wiki-linked name,
/// the EXILUS chip, the effect lines — and the only thing that differs is the
/// TRAILING control, which is the whole difference between the modules: the
/// builder binds a VALUE (the drain of the card it is about to seat) where the
/// optimizer binds a SET (pool / req). Stating that once here is what makes a
/// change to the card reach both tabs.
///
/// It was two copies, with `// The picker's .opt row markup verbatim` written
/// over the second — a comment that stops being true in silence, which is
/// exactly what it did: the optimizer's copy never grew the builder's stance
/// filter, so a melee weapon offered its stances as MAIN-slot marks.
/// `exilusChip` is off in the EXILUS SLOT's own list, where every row is
/// exilus-eligible and the chip is the heading repeated once per card.
const modRow = (m, { cls = "", title = "", attrs = "", chips = "", note = "",
  trailing = "", exilusChip = true } = {}) =>
  `<div class="opt ${cls} ${m.rarity ? "rar-" + m.rarity : ""}" ${attrs} title="${title}">
      ${imgTag(POL(m.polarity), "pol")}${imgTag(IMG(m.image), "mod")}
      <div class="info"><div class="mn">${
    wl(m.name, modWikiUrl(m))}${
    exilusChip && m.exilus ? ' <span class="exchip">EXILUS</span>' : ""}${chips}</div><div class="me">${
    cardLines(m, m.max_rank).map((x) => `<div>${x}</div>`).join("")}</div>${note}</div>${trailing}</div>`;

/// THE SCOPE CONTROL — the optimizer's trailing half of the row above.
///
/// `pool` = an option the search may take, `req` = pinned into every candidate.
/// Six lists carry it (mods, exilus, modes, valence, arcanes, evolution tiers)
/// and it was written out six times; the ATTRIBUTE differs per list because
/// each one's click handler reads its own (`data-m`, `data-a`, `data-t`+`data-e`),
/// which is why that is the parameter and the rest is not.
const oseg = (attrs, st, { poolDead = false, reqDead = false, poolTitle = "",
  reqTitle = "", extra = "" } = {}) =>
  `<div class="oseg">
        <span class="seg ${st === "search" ? "on" : ""} ${poolDead ? "dis" : ""} ${extra}" ${attrs} data-s="search"${
    poolTitle ? ` title="${escHtml(poolTitle)}"` : ""}>${tr("pool")}</span>
        <span class="seg ${st === "fixed" ? "on" : ""} ${reqDead ? "dis" : ""} ${extra}" ${attrs} data-s="fixed"${
    reqTitle ? ` title="${escHtml(reqTitle)}"` : ""}>${tr("req")}</span>
      </div>`;

function renderMenu(slotIdx, query) {
  rivenPickerSlot = slotIdx;
  const menu = $("mod-menu");
  const q = query.trim().toLowerCase();
  // Equipped mods stay LISTED: the current slot's mod is marked, mods in other
  // slots show their slot number — picking one of those EXCHANGES the two slots.
  // ONE group ahead of the rule: this slot's own mod, because it is the
  // baseline every number below is measured against. Everything else obeys
  // the sort — including mods sitting in OTHER slots, which are not pinned
  // into a band of their own. Such a band contradicts whichever order is
  // chosen (eight rows of unsorted drain at the top of a drain sort), and it
  // carries nothing: every placed mod already has a "slot N" chip
  // that says where it is.
  const group = (m) => (slots[slotIdx].mod === m.id ? 0 : 1);
  const hits = buildPool()
    // The exilus slot takes what `exilusPool()` says, which is the same
    // question the optimizer's exilus scope asks.
    .filter((m) => slotIdx !== EXILUS || m.exilus)
    // THE STANCE FILTER RUNS BOTH WAYS. A stance is legal in the stance slot
    // and NOWHERE else — unlike an exilus mod, which the game lets sit in a
    // main slot — so offering one in slot 3 would offer a build nobody can
    // hold.
    .filter((m) => (slotIdx === STANCE) === !!m.stance)
    .filter((m) => !pickerPrefs.pol || m.polarity === pickerPrefs.pol)
    .filter((m) => searchHit(m, q))
    .sort((a, b) => {
      const g = group(a) - group(b); // current first, then equipped, then the rest
      if (g) return g;
      // RIVENS FIRST, as their own block: they are the build's own items and
      // sorting them in by name would scatter them through the pool.
      const r = (b.riven ? 1 : 0) - (a.riven ? 1 : 0);
      if (r) return r;
      // ONE RULE, not three special cases.
      //
      //   · every key sorts DESCENDING — effect, then drain, then name;
      //   · the key you PICK is hoisted to the front, and the rest keep that
      //     fixed order behind it. Pick drain and you get drain, effect, name.
      //
      // Drain descending is deliberate: two mods the target ignores score the
      // same, and the expensive one is doing more (it just is not doing it
      // HERE), so it is the one worth looking at first.
      //
      // The arrow flips the whole comparison, keys and all — one rule means
      // one direction. What it does not flip is UNSCANNED-LAST: an absent
      // answer is not a small one, so it stays at the bottom either way.
      return gainSort(a, b, [pickerPrefs.sort,
        ...["gain", "drain", "name"].filter((k) => k !== pickerPrefs.sort)]);
    });
  // No cap: every pool mod must be reachable. The popover menu scrolls
  // (`.combo-menu` overflow-y), so the whole sorted/filtered list is browsable.
  // Two sections, each labelled. With rivens leading, an unlabelled pool
  // below them would read as a continuation of the riven list.
  const row = (m) => {
    const isCur = slots[slotIdx].mod === m.id;
    const at = placedAt(m.id, slotIdx);
    // Exchanging with the exilus slot would move OUR mod there — only legal
    // if it is exilus-eligible (or the slot is empty).
    const ownMod = slots[slotIdx].mod ? modById(slots[slotIdx].mod) : null;
    const exIllegal = at === EXILUS && ownMod && !ownMod.exilus;
    const conflict = at < 0 && !isCur && familyConflict(m, slotIdx);
    // Every placed mod shows a "slot N" chip (the current one shows ITS OWN
    // slot). No "current" word — same color family; background does the
    // distinguishing, the current slot rendered a touch stronger.
    // LOCALIZED, and it was not until 2026-08-10: this chip is the ONLY place
    // the app names a slot, so a Chinese page read "slot 5" while everything
    // around it was translated — and the number badge on the slot itself now
    // has to agree with it word for word.
    const slotName = (idx) =>
      idx === EXILUS ? tr("exilus")
      : idx === STANCE ? tr("stance")
      : tr("slot") + " " + (idx + 1);
    const badge = isCur ? `<span class="slotchip cur">${slotName(slotIdx)}</span>`
      : at >= 0 ? `<span class="slotchip">${slotName(at)}</span>` : "";
    // The gain is THIS SLOT's — the same mod is worth something different in
    // another slot, because elements combine by mod order.
    const gainChip = gainChipFor(m.id, slotName(slotIdx));
    const title = conflict ? `incompatible (${m.family})`
      : exIllegal ? `cannot swap: ${ownMod.name} is not an exilus mod`
      : at >= 0 ? `swap with ${at === EXILUS ? "the exilus slot" : "slot " + (at + 1)}`
      : m.effects.join(" · ");
    return modRow(m, {
      cls: `${conflict || exIllegal ? "dis" : ""} ${isCur ? "cur" : at >= 0 ? "placed" : ""}`,
      attrs: `data-id="${m.id}"`,
      title,
      chips: ` ${badge}${gainChip}`,
      // THE BUILDER BINDS A VALUE, and this is it: what seating this card
      // costs the slot you are standing in.
      trailing: `<span class="dr">${m.drain}</span>`,
    });
  };
  menu.innerHTML = scanStrip(gainScan, { kind: "mods", idx: slotIdx }, hits.map((m) => m.id))
    + (hits.length
      ? sectionedRows(hits, (m) => (m.riven ? "Riven" : "Mods"), row)
      : `<div class="opt dis">${escHtml(tr("no matches"))}</div>`);
  menu.querySelectorAll(".opt:not(.dis)").forEach((o) => o.addEventListener("click", () => {
    const id = o.dataset.id;
    if (slots[slotIdx].mod === id) { closePopovers(); return; } // already here
    const at = placedAt(id, slotIdx);
    if (at >= 0) {
      // EXCHANGE the two slots' mods (+ranks); polarities stay with their slots
      const a = slots[slotIdx], b = slots[at];
      [a.mod, b.mod] = [b.mod, a.mod];
      [a.rank, b.rank] = [b.rank, a.rank];
    } else {
      slots[slotIdx].mod = id; // polarity is decoupled — keep the slot's polarity
      slots[slotIdx].rank = modById(id).max_rank; // added mods default to max rank
    }
    closePopovers(); renderMods();
  }));
}

// THE MOD SLOT'S MENU, on the shared one. It was a THIRD copy of
// the same two items — and the collision that found it is worth recording: this
// function was called `openSlotMenu` too, and being declared later in the file
// it silently SHADOWED the shared one, so an evolution card's ⋯ opened "Swap
// mod". Its items were hardcoded English as well, which is the same gap the
// arcane menu carried.
//
// MOD ops only: polarity lives on the left icon, and duplicating it here is
// what this menu has always refused.
function openModSlotMenu(slotIdx, anchor) {
  openSlotMenu(anchor, null, {
    label: tr("Mod"),
    removable: true,
    onSwap: () => openPicker(slotIdx, slotEl(slotIdx)),
    // In place: the slot keeps its polarity, which is a property of the SLOT
    // and not of what was in it.
    onPick: () => { slots[slotIdx].mod = null; renderMods(); },
  });
}

function openPolMenu(slotIdx) {
  closePopovers();
  const menu = $("slot-menu");
  const cur = slots[slotIdx].pol;
  menu.innerHTML = GUN_POLS.map((p) => `<div class="mi ${p === cur ? "sel" : ""}" data-p="${p}">${imgTag(POL(p), "pol")} ${p === "Omni" ? "Omni (any)" : p}</div>`).join("") +
    `<div class="mi ${!cur ? "sel" : ""}" data-p="">◇ none</div>`;
  place(menu, slotEl(slotIdx));
  menu.querySelectorAll(".mi").forEach((o) => o.addEventListener("click", () => {
    slots[slotIdx].pol = o.dataset.p || null;
    closePopovers(); renderMods();
  }));
}

// ---- Arcane ----
// Full parity with mods: ONE slot card (rank stepper, ⋯ menu) → click opens a
// searchable picker that matches name OR effect, with effect lines, rarity
// frames, and the equipped arcane highlighted in the accent background family.
// The arcanes the CURRENT weapon can equip: its own slot's pool. Arcane ids
// are globally unique, so lookups stay unfiltered — only the PICKERS narrow.
//
// The EQUIPPABLE arcanes of this weapon's slot. "none" is the empty-slot
// sentinel, not an arcane, and it is offered in NO list: the builder slot has
// its own "Remove arcane", and in the optimizer an empty arcane scope already
// means "run no arcane" — a "None" row there was a second way to say the same
// thing, sitting in a list of real choices.
const arcanePools = (weaponId) =>
  (weaponInfo(weaponId || $("weapon").value) || {}).arcane_pools || [];
// The arcanes SLOT i may hold — pool i's, and only pool i's. A picker that
// offers the whole set and then refuses the pick is a worse way to say the
// same thing.
/// WHICH SEATS an arcane fits, by id. Almost always the one directory it is
/// filed under; a KITGUN arcane fits both, because a Kitgun is one weapon with
/// a roster entry per slot. `slot` is the fallback for a meta served before
/// seats existed, so a page loaded against an older build still sees what it
/// always saw.
const arcaneSeats = (a) => (a && (a.seats || (a.slot ? [a.slot] : []))) || [];
/// Do two arcanes compete for the same seat? The optimizer groups its marks by
/// this, because a pin in the Primary seat must not clear a Secondary mark.
const sameArcaneSeat = (a, b) =>
  arcaneSeats(a).some((s) => arcaneSeats(b).includes(s));

const arcanePool = (i = 0) => {
  const pool = arcanePools()[i];
  // WHICH ARCANES THIS WEAPON MAY SEAT is the ENGINE's answer, per weapon —
  // the CONSEQUENCE, not a rule restated here, which is `evo_forbids`' and
  // `auras`' own pattern. It was `equip_classes` until 2026-08-22, and that was
  // enough while every narrowing arcane named a CLASS (Shotgun Vendetta,
  // Longbow Sharpshot). The eight Kitgun arcanes narrow by a TRAIT instead,
  // because no class can say "Kitgun" — a secondary Tombfinger is a `pistol`
  // exactly like a Lex — so the picker offered all eight on a Lex, and a third
  // kind of gate would have gone stale the same way.
  //
  // `equip_classes` stays as the fallback for a meta served before this field
  // existed, so a page loaded against an older build still narrows the two it
  // could always narrow.
  const w = weaponInfo($("weapon").value) || {};
  const allowed = w.arcanes;
  return (META.arcanes || []).filter(
    (a) =>
      a.id !== "none" &&
      // THE SEATS IT FITS, not the directory it is filed under. A Kitgun
      // arcane fits both, because a Kitgun is one weapon with a roster entry
      // per slot; `slot` is the fallback for a meta served before seats
      // existed.
      arcaneSeats(a).includes(pool) &&
      (allowed
        ? allowed.includes(a.id)
        : !(a.equip_classes || []).length || a.equip_classes.includes(w.class)),
  );
};
// An arcane belongs to ONE slot, so another slot's arcane is not a
// questionable choice on this weapon — it cannot be equipped at all. Ids reach
// the page from saved states, presets, shared URLs and optimizer results, so
// every one of them goes through here instead of being trusted (a SECONDARY
// arcane rode a saved state onto the first primary weapon).
// The engine refuses the same thing independently
// (`arcanes_data::for_slot`); this keeps the UI from ever showing a build the
// sim would not run.
// Pre-data short names, from builds saved before arcane ids were data. They
// are rewritten HERE, at the one point an id enters state, so the wire format
// stays a single shape and nothing downstream reads two spellings. A row in someone's localStorage is history, not a format.
const ARCANE_RENAMED = {
  enervate: "secondary_enervate",
  deadhead: "secondary_deadhead",
  flare: "cascadia_flare",
};
function arcaneFor(weaponId, id, i = 0) {
  if (!id || id === "none") return "none";
  const canon = ARCANE_RENAMED[id] || id;
  const a = arcaneById(canon);
  return a && arcaneSeats(a).includes(arcanePools(weaponId)[i]) ? canon : "none";
}
/// Can this weapon seat this arcane in ANY of its slots?
///
/// `arcaneFor` answers a different question — "does it fit slot i" — and its
/// `i` defaults to 0. The optimizer's SCOPE is not per-slot (an arcane belongs
/// to exactly one pool, so the flat mark map already says which), so asking
/// `arcaneFor(w, id)` there silently meant "does it fit the FIRST pool": every
/// secondary mark was dropped on restoring an optimizer-arcanes preset, and
/// the search then had nothing to put in the second slot.
const arcaneFitsWeapon = (weaponId, id) => {
  const a = arcaneById(ARCANE_RENAMED[id] || id);
  // BY SEAT, NOT BY DIRECTORY. `a.slot` is where the file LIVES, which was the
  // same answer as where it fits for every arcane in the game until the eight
  // Kitgun ones — they are filed under `secondary/` because ids are globally
  // unique, and they seat in `kitgun`. Reading `slot` here dropped every
  // Kitgun mark an optimizer scope carried, the same shape as the
  // secondary-mark bug this function's own comment is about.
  return !!a && arcanePools(weaponId).some((p) => arcaneSeats(a).includes(p));
};
/// SEAT AN ARCANE LIST ON A WEAPON — by POSITION first, then by POOL.
///
/// Position is the wire format and stays it: a build's arcane list is one id
/// per seat in the weapon's own seat order, and a list written under today's
/// seats is left exactly where it is.
///
/// WHAT A SAVED BUILD CANNOT KNOW IS THAT THE ORDER MOVED UNDER IT. A Kitgun
/// gained a seat of its own IN FRONT of its ordinary one,
/// so every Tombfinger build written before that has its Primary arcane
/// sitting in the Kitgun seat — where it fits nothing, and where the old
/// index-only rule dropped it without a word. An id that no longer fits where
/// it sits is offered the seats that are still empty; one that fits nowhere is
/// still dropped, because there is nowhere for it to go.
///
/// Returns the mapping as well, so a positional array BESIDE the ids — the
/// ranks — can follow the move instead of staying behind on an index that now
/// means something else.
function seatArcanes(weaponId, list) {
  const pools = arcanePools(weaponId);
  const raw = Array.isArray(list) ? list.slice() : list == null ? [] : [list];
  const ids = pools.map(() => "none");
  const from = pools.map(() => -1);
  const spare = [];
  raw.forEach((id, i) => {
    const fit = i < pools.length ? arcaneFor(weaponId, id, i) : "none";
    if (fit !== "none") { ids[i] = fit; from[i] = i; return; }
    if (id && id !== "none") spare.push({ id, i });
  });
  spare.forEach(({ id, i }) => {
    const j = pools.findIndex((_, k) => ids[k] === "none" && arcaneFor(weaponId, id, k) !== "none");
    if (j < 0) return;
    ids[j] = arcaneFor(weaponId, id, j);
    from[j] = i;
  });
  return { ids, from };
}
/// Every slot's id, validated against the pool that slot draws from.
const arcanesFor = (weaponId, list) => seatArcanes(weaponId, list).ids;
/// The builder picker's list. Same set — kept as its own name because the
/// picker is where a reader looks for it.
const arcanePickPool = arcanePool;
/// Which slot the picker is filling — the popover is shared, the slot is not.
let arcaneSlotIdx = 0;
const arcaneById = (id) => META.arcanes.find((x) => x.id === id);
// new arcane → max rank, in the slot the picker was opened from
// EVERY ARCANE MUTATION REFRESHES, because the mutation owns the consequence.
//
// Redrawing the arcane slots and nothing else leaves the panel, its stat rows
// and the SIM'S BUFF BAR showing the previous arcane until some unrelated edit
// happens to call `refreshPanel` — toggling a mod, usually.
//
// `refreshPanel` is the funnel — its own comment says "every build change
// funnels through here" — so the fix is not to add the call at each picker but
// to make it impossible to mutate an arcane without it. A future control that
// sets an arcane gets the refresh for free; one that assigns `arcanes[i]`
// directly is the thing to look for in review.
function setArcane(id, i = arcaneSlotIdx) {
  arcanes[i] = id;
  arcaneRanks[i] = null;
  refreshPanel();
}
/// An arcane's RANK is a build change too: its numbers scale per rank, so the
/// panel and the buff bar are wrong until they are re-asked.
function setArcaneRank(i, rank) {
  arcaneRanks[i] = rank;
  refreshPanel();
}
// Effect lines for a specific rank (clamped). Arcane strengths scale per rank
// (wiki), so the slot shows the SELECTED rank; the picker shows max rank.
const effectsAt = (a, r) => {
  const rk = a && a.ranks || [];
  if (!rk.length) return [];
  return rk[Math.max(0, Math.min(rk.length - 1, r))] || [];
};
// Renders card lines that are ALREADY in the display language (cardLines
// did the choosing) — this is layout, not translation.
const effLines = (arr) => arr.length ? `<div class="me">${arr.map((x) => `<div>${x}</div>`).join("")}</div>` : "";

function renderArcanes() {
  const box = $("arcane-slots");
  box.innerHTML = "";
  weaponAxes().arcanes.forEach((ax, i) => box.appendChild(arcaneSlotEl(ax.pool, i)));
}

// One arcane slot: the card if filled, the "+ add" plate if not. The POOL is
// named on the plate only when a weapon seats more than one, because that is
// the only time it tells you anything.
function arcaneSlotEl(pool, i) {
  const many = arcanePools().length > 1;
  const a = arcaneById(arcanes[i]);
  const none = !a || a.id === "none";
  const el = document.createElement("div");
  if (none) {
    el.className = "slot empty arc";
    el.innerHTML = `<span class="plus">+ ${escHtml(
      many ? tr("add {pool} arcane").replace("{pool}", tr(ARC_POOL_LABEL[pool] || pool)) : tr("add arcane"),
    )}</span>`;
  } else {
    const maxr = a.max_rank || 0;
    const r = arcaneRanks[i] == null ? maxr : Math.max(0, Math.min(maxr, arcaneRanks[i]));
    const lowered = r < maxr;
    const rank = maxr > 0
      ? `<span class="rank ${lowered ? "lowered" : ""}"><button class="rk" data-d="-1">−</button><b>R${r}${lowered ? "/" + maxr : ""}</b><button class="rk" data-d="1">+</button></span>`
      : "";
    el.className = "slot filled arc" + (a.rarity ? " rar-" + a.rarity : "");
    // The slot shows the verbatim DESCRIPTION at the selected rank (like
    // the mod cards); model effect lines remain the search text.
    el.innerHTML = imgTag(IMG(a.image), "mod") +
      `<div class="info"><div class="mn">${wl(a.name, wikiUrl(a.name_en || a.name))}</div>${effLines(cardLines(a, r, effectsAt(a, r)))}${rank}</div>` +
      `<button class="dots" title="options">⋯</button>`;
    el.querySelector(".dots").addEventListener("click", (e) => { e.stopPropagation(); openArcaneMenu(e.currentTarget, i); });
    el.querySelectorAll(".rk").forEach((b) => b.addEventListener("click", (e) => {
      e.stopPropagation();
      setArcaneRank(i, Math.max(0, Math.min(maxr, r + Number(b.dataset.d))));
      renderArcanes();
    }));
  }
  // Mod-slot parity: only the EMPTY slot opens the picker on click; a
  // filled card swaps via its ⋯ menu — so its text stays selectable.
  if (none) {
    el.addEventListener("click", (e) => { e.stopPropagation(); openArcanePicker(el, i); });
  }
  return el;
}

function openArcanePicker(anchor, i = 0) {
  arcaneSlotIdx = i;
  closePopovers();
  const pop = $("arcane-popover");
  place(pop, anchor);
  const search = $("arcane-search");
  search.value = "";
  search.oninput = () => renderArcaneMenu(search.value);
  renderArcaneMenu("");
  search.focus();
  ensureGains({ kind: "arcane", idx: i },
    () => { if (!$("arcane-popover").hidden) renderArcaneMenu($("arcane-search").value); },
    true);
}

// Search matches NAME or any EFFECT line (like the mod picker). "None" always
// stays listed as the clear-out option.
function renderArcaneMenu(query) {
  const menu = $("arcane-menu");
  const q = query.trim().toLowerCase();
  // Search matches NAME (localized or English), ANY rank's effect text,
  // or the description — in either language (searchBlob).
  // Same rule as the mod picker, minus a key an arcane does not have: there
  // is no drain on an arcane, so it is effect then name.
  const hits = arcanePickPool(arcaneSlotIdx)
    .filter((a) => !q || searchBlob(a).includes(q))
    .sort((a, b) => (a.id === arcanes[arcaneSlotIdx] ? -1 : b.id === arcanes[arcaneSlotIdx] ? 1 : 0)
      || gainSort(a, b, ["gain", "name"]));
  menu.innerHTML = scanStrip(gainScan, { kind: "arcane", idx: arcaneSlotIdx }, hits.map((a) => a.id))
    + (hits.length ? hits.map((a) => {
    const isCur = a.id === arcanes[arcaneSlotIdx];
    return `<div class="opt ${isCur ? "cur" : ""} ${a.rarity ? "rar-" + a.rarity : ""}" data-id="${a.id}">
      ${imgTag(IMG(a.image), "mod")}
      <div class="info"><div class="mn">${wl(a.name, wikiUrl(a.name_en || a.name))}${isCur ? ' <span class="slotchip cur">equipped</span>' : ""}${gainChipFor(a.id, tr("Arcane"))}</div>${effLines(cardLines(a, a.max_rank, effectsAt(a, a.max_rank)))}</div></div>`;
  }).join("") : `<div class="opt dis">no matches</div>`);
  menu.querySelectorAll(".opt:not(.dis)").forEach((o) => o.addEventListener("click", () => { setArcane(o.dataset.id); closePopovers(); renderArcanes(); }));
}

// ⋯ on a filled arcane slot: mirror the mod slot menu (remove).
// THE ARCANE'S OWN MENU, on the shared one. It was the model for
// `rankedSlot` and had drifted from it in two ways worth ending: its two items
// were HARDCODED ENGLISH — no `tr()` at all, so a Chinese page said "Swap
// arcane" — and a second copy of this markup is how the two would keep
// drifting. The picker stays its own, because an arcane's list carries images
// and a rank that the ranked list does not.
function openArcaneMenu(anchor, i = 0) {
  arcaneSlotIdx = i;
  openSlotMenu(anchor, null, {
    label: tr("Arcane"),
    removable: true,
    onSwap: () => openArcanePicker(anchor, i),
    onPick: () => { setArcane("none", i); renderArcanes(); },
  });
}

// ---- Evolution ----
// Every tier (EVO I–IV) renders its options as CARDS — icon, name, and the
// verbatim effect text, like the mod/arcane cards — PLUS an explicit None
// card (nothing installed). Wiki-flagged broken evolutions carry a red
// BROKEN badge, and selecting one shows a red note: the engine really
// computes them as NO EFFECT. Deselecting tier 1 (the Incarnon Form
// unlock) drops the weapon to its base form.
// Evolution tiers are per weapon, not a fixed four: Zariman weapons run
// I-V (Laetum), Incarnon Genesis adapters I-IV. Build the numeral instead
// of indexing a table that stops at IV.
const ROMAN = (n) => {
  const T = [[10, "X"], [9, "IX"], [5, "V"], [4, "IV"], [1, "I"]];
  let out = "";
  for (const [v, sym] of T) while (n >= v) { out += sym; n -= v; }
  return out;
};
/// The modes this build may be played in, each with the reason it cannot be —
/// `[id, label, offReason]`, the same shape the Form control always took.
///
/// A mode a BUILD rules out is offered DISABLED, not dropped: "the weapon has
/// no Incarnon form while that mod is on it" is information, and a vanished
/// option is not. Asking for a cycle implies its unlock, and installing that
/// unlock takes a Cannonade off the weapon — so a build wearing one has no
/// cycle to run and the sim refuses it.
/// HOW A FORM IS FIRED, in one word. The trigger is weapon data; this is the
/// English for it, and a trigger with no entry simply contributes nothing
/// rather than printing its yaml token at a reader.
// WHAT A FORCED PROC IS CALLED. Two of them are not damage types at all —
// Lifted and Knockdown are their own procs — and a reader should not have to
// know which of the two machines carries which.
const PROC_WORD = {
  impact: "Impact", puncture: "Puncture", slash: "Slash",
  heat: "Heat", cold: "Cold", electricity: "Electricity", toxin: "Toxin",
  blast: "Blast", corrosive: "Corrosive", gas: "Gas", magnetic: "Magnetic",
  radiation: "Radiation", viral: "Viral",
  lifted: "Lifted", knockdown: "Knockdown",
};
const TRIGGER_WORD = {
  auto: "fully automatic", semi_auto: "semi-auto", burst: "burst",
  charge: "charged", held: "held", projectile: "projectile",
};
/// WHAT FILLS A GAUGE, in words. Mirrors `loadout::ChargeOn` — a member the
/// page has no word for falls back to the id, which reads as obviously missing
/// rather than as a silently empty sentence.
const CHARGE_WORD = {
  weakpoint_hits: "weakpoint hits", direct_hits: "direct hits", kills: "kills",
};

/// A FORM, NAMED WITH WHAT TELLS IT FROM THE FORM BESIDE IT: its trigger, or
/// its draw.
const firedForm = (f) => {
  const word = f && TRIGGER_WORD[f.trigger];
  const nm = tr((f || {}).name || "");
  if (!word) return nm;
  if (f.charge_seconds) {
    return trF("{form} ({secs}s charge)", { form: nm, secs: (+f.charge_seconds).toFixed(2) });
  }
  // A FORM NAMED AFTER ITS TRIGGER DOES NOT SAY IT TWICE — the Kuva Hind's
  // read "Semi-Auto (semi-auto)". Compared on the SOURCE strings, because a
  // form name may not be translated yet and the rendered pair ("Semi-Auto"
  // against "半自动") overlaps in neither language; and with BOTH SIDES
  // checked non-empty, since a Chinese string strips to "" and
  // `"".includes("")` is true, which swallowed every translated one.
  const flat = (x) => String(x || "").toLowerCase().replace(/[^a-z]/g, "");
  const said = (a, b) => !!flat(a) && !!flat(b) && flat(a).includes(flat(b));
  const how = tr(word);
  return said(f.name, word) || said(nm, how)
    ? nm
    : trF("{form} ({how})", { form: nm, how });
};

/// Is this mode a CYCLE — one form filling a gauge the other spends?
const isCycleMode = (id) => id === "cycle" || String(id).endsWith("_cycle");

/// THE FORM A MODE IS ABOUT: the one it fires, and for a cycle the one it
/// FILLS THE GAUGE IN. A cycle is named for its feeder — `<mode>_cycle`, the
/// bare `cycle` being the arsenal's own (engine `play_modes`).
const modeForm = (w, id) => {
  const forms = (w || {}).forms || [];
  const def = forms.find((x) => x.is_default) || forms[0] || null;
  const fed = id === "cycle" ? "base" : String(id).replace(/_cycle$/, "");
  if (fed === "base") return def;
  if (fed === "transformed") return earnedForm(w);
  // A WEAPON CAN HAVE MORE THAN ONE ALTERNATE — a bow with an adapter has a
  // tapped shot AND an Incarnon form — told apart by the gauge, as the engine
  // splits them.
  if (fed === "alternate") {
    return forms.find((x) => !x.is_default && !x.gauge_switched) || null;
  }
  // A MODE ID THAT IS A FORM ID — melee's seven, the Hind's two extra
  // triggers. LAST: the form KIND `base` is a bow's TAPPED shot while the
  // `base` MODE is the drawn one, so a direct match would swap them.
  return forms.find((x) => x.id === fed) || def;
};

/// WHAT A MODE ACTUALLY IS, in sentences, derived from the weapon's own forms.
///
/// A mode was a NAME in a dropdown and nothing else, which is fine while every
/// weapon's second mode is the same mechanic — and stopped being fine the day
/// two weapons earned a form by killing rather than by hitting. "Cycle" does not say what fills the gauge, how much of it there
/// is, or what the earned form gets to fire, and those are precisely the
/// numbers that decide whether the mode is worth picking.
///
/// DERIVED, never written per weapon: the forms carry their trigger and their
/// gauge economy (`/api/meta`), so a weapon that arrives tomorrow explains
/// itself. Each sentence is ONE translated template with `{named}` holes, so a
/// weapon with different numbers costs no translation at all.
/// WHAT THIS MODE SWINGS, in the three numbers that decide between the seven:
/// how many swings, what they come to, and how long they take.
///
/// FROM THE STANCE WHEN ONE IS EQUIPPED, because that is the card that moves
/// them — a mode's NAME is fixed and its STRENGTH is not.
/// The form's own is what an empty stance slot fires.
const comboOf = (w, id) => {
  const f = ((w || {}).forms || []).find((x) => x.id === id);
  if (!f) return null;
  const sid = (slots[STANCE] || {}).mod;
  const m = sid ? modById(sid) : null;
  const fromStance = m && m.stance_combos ? m.stance_combos[id] : null;
  return fromStance || f.combo || null;
};

function modeExplain(w, id) {
  const forms = (w || {}).forms || [];
  const def = forms.find((x) => x.is_default) || forms[0] || {};
  const earned = earnedForm(w);
  const alt = forms.find((x) => !x.is_default && !x.gauge_switched);
  // EVERY LINE HAS TO EARN ITS PLACE. "Nothing is spent to
  // be in it, so it can be held forever — a ruler ranks it" was true of the
  // mode it was printed under AND of every mode beside it, which is the
  // definition of a sentence that distinguishes nothing; the same goes for
  // "swung as its neutral combo for the whole engagement" under a heading that
  // already reads "Neutral Combo". What is left either carries a NUMBER or
  // names something this mode does and its neighbours do not.
  const swung = (f) => {
    const c = comboOf(w, f.id);
    if (!c) return [];
    const out = [];
    // THE THREE NUMBERS, all in ONE unit — a share of the WEAPON's base, which
    // is what makes the seven modes comparable at a glance.
    //
    // TWO CONVERSIONS GET THEM THERE. A script's multipliers are relative to
    // the ENTRY they are written in (`swing_share` carries it back, and it is
    // 1.0 on every entry but the slam, whose vector is zero because the whole
    // attack is its explosion), and the explosion is not in the script at all.
    // Without both the heavy slam read 100% for an attack that deals 300%.
    const share = f.swing_share === undefined ? 1 : f.swing_share;
    out.push(trF("{n} swings coming to {total}% of base, over {secs}s at 1.0x attack speed.", {
      n: c.swings, secs: (+c.seconds).toFixed(2),
      total: Math.round((c.total * share + (f.radial_share || 0)) * 100),
    }));
    // A SPIN REACHES THE WHOLE ROOM and an ordinary sweep reaches one body —
    // the one spatial fact separating two combos of the same weapon.
    if (c.spins > 0) {
      out.push(c.spins === c.swings
        ? tr("Every swing is a spin, reaching everything within the weapon's range.")
        : trF("{n} of them are spins, reaching everything within the weapon's range.",
          { n: c.spins }));
    }
    // A SLAM IS NOT BOUNDED BY REACH, which is what makes it the melee mode
    // that answers a crowd.
    if (f.slam) {
      out.push(tr("Its damage is an explosion centred on your own feet, so the weapon's reach does not bound it."));
    }
    // THE COUNTER IS SPENT HERE, and that makes this mode a different BUILD:
    // Blood Rush and Weeping Wounds read the counter this one empties.
    if (f.spends_combo) {
      out.push(tr("It spends the combo counter and is multiplied by it, so the cards that read that counter are worth far less here."));
    }
    if ((c.procs || []).length) {
      out.push(trF("Forces {procs}, whatever the status roll says.",
        { procs: c.procs.map((x) => tr(PROC_WORD[x] || x)).join(tr(", ")) }));
    }
    return out;
  };
  const out = [];
  if (id === "base") {
    // …AND A MELEE WEAPON'S `base` IS A COMBO, whose FORM id is `neutral` and
    // therefore never equals the mode id.
    const lines = swung(def);
    if (lines.length) {
      out.push(...lines);
    } else {
      // "IT NEVER TRANSFORMS" IS ONLY WORTH SAYING WHERE IT COULD BE.
      out.push(forms.some((x) => x.gauge_switched)
        ? trF("Fired in its {form} for the whole engagement — it never transforms.",
          { form: firedForm(def) })
        : trF("Fired in its {form} for the whole engagement.", { form: firedForm(def) }));
    }
  } else if (id === "alternate") {
    out.push(trF("Fired in its {form} for the whole engagement.", { form: firedForm(alt) }));
  } else if (id === "transformed") {
    // THE ONE CONSTRAINT THAT IS NOT TRUE OF ITS NEIGHBOURS stays, because it
    // is the only mode here you cannot actually play: it exists so a form's own
    // numbers can be read.
    out.push(trF("Its {form} alone, from the first second — a form that has to be bought and runs out, so this is here to read its numbers rather than to play.",
      { form: firedForm(earned) }));
  } else if (forms.some((x) => x.id === id)) {
    // **A MODE WHOSE ID IS A FORM'S ID**, which is every melee mode and the
    // Kuva Hind's two extra triggers. `renderMode` DROPS an entry with no
    // lines, so a mode with no arm here is a mode that never draws.
    const f = forms.find((x) => x.id === id) || {};
    const lines = swung(f);
    // A GUN WHOSE MODE IS A FORM has no combo to state, so its trigger is what
    // there is to say — this arm may not REQUIRE a combo.
    out.push(...(lines.length ? lines
      : [trF("Fired in its {form} for the whole engagement.", { form: firedForm(f) })]));
  } else if (isCycleMode(id) && earned) {
    const g = earned.gauge || {};
    // WHICH FORM FILLS THE GAUGE is all one cycle has that the other does not.
    out.push(trF(
      "Fire {base} until the gauge fills, spend it in {other}, come back — and again.",
      { base: firedForm(modeForm(w, id)), other: firedForm(earned) }));
    out.push(trF("{n} {what} fill it, and the earned form fires {rounds} before it ends.", {
      n: g.charges_to_fill, rounds: g.max_rounds,
      what: tr(CHARGE_WORD[g.charge_on] || g.charge_on || ""),
    }));
    // THE TRANSITIONS, and the ZERO CASE IS A FACT. An Incarnon plays an
    // animation in each direction; a form you simply hold the other button for
    // does not, and saying nothing there would read as "unknown" rather than
    // as "none".
    out.push(g.transmute_in > 0 || g.transmute_out > 0
      ? trF("Each way costs an animation — {in}s in, {out}s out, both scaled by reload speed.",
        { in: (+g.transmute_in).toFixed(2), out: (+g.transmute_out).toFixed(2) })
      : tr("There is no transition animation either way."));
    // WHY A KILL-FED GAUGE IS DIFFERENT, said once and only where it applies:
    // it is the only source that the TARGET can refuse.
    if (g.charge_on === "kills") {
      out.push(tr("A gauge bought with kills is worth what the fight lets you earn: against something that will not die, this mode is the base one."));
    }
  }
  return out;
}

function modeOpts(w) {
  const ids = (w.modes || []);
  if (ids.length < 2) return [];
  const cost = (w.unlock_evo && (w.evo_forbids || {})[w.unlock_evo]) || [];
  const blocker = slots
    .map((s) => s.mod)
    .filter((m) => m && cost.includes(m))
    .map((m) => (modById(m) || {}).name || m)[0];
  const off = blocker
    ? `${blocker} ${tr("needs the same trigger on every firing mode, so this build has no Incarnon form")}`
    : null;
  // EVERY cycle: the mod takes the Incarnon form off the weapon, so none of
  // them has anything left to transform into.
  return ids.map((id) => [id, modeLabel(w, id), isCycleMode(id) ? off : null]);
}

/// The mode control, in the BUILDER, in a block of its own above the mods.
///
/// ALWAYS DRAWN. A weapon with one way to be fired is still being fired in it,
/// and a panel that says nothing leaves the reader to assume — which is the
/// same rule the Form control carried, and the reason a single form was stated
/// rather than hidden. Several modes
/// is a dropdown; one is a value.
/// THE VALENCE THIS WEAPON MAY HAVE, or null. One place asks the question, so a
/// control, a payload and a reset cannot disagree about whether the axis exists.
const valenceSpec = (id) => (weaponInfo(id) || {}).valence || null;

/// A build's valence, cleaned against the weapon it is being opened on.
///
/// An element the spec does not offer is DROPPED rather than kept — a preset
/// imported from another weapon carries one, and so does a stale one written
/// before an element was removed. The percentage is clamped to the roll's own
/// range for the same reason.
function defaultValence(id, st) {
  const s = valenceSpec(id);
  if (!s) return { element: "", bonus: 0 };
  // 60% IMPACT, not "none". Every copy of an adversary
  // weapon in the game comes out of its Lich carrying a bonus, so "no element"
  // is not a weaker build of it — it is a weapon nobody has, and the panel
  // would print numbers no player can reproduce.
  //
  // The FIRST element and the roll's CEILING: the ceiling because every player
  // can Valence-fuse to it and it is what the board scores, the first because
  // the wiki lists them in the game's own order and Impact is where it starts.
  const el = st && s.elements.includes(st.element) ? st.element : s.elements[0];
  const b = st && Number.isFinite(Number(st.bonus)) ? Number(st.bonus) : s.max;
  return { element: el, bonus: Math.min(Math.max(b, s.min), s.max) };
}

/// The parts `/api/meta` publishes for a weapon, or `null` if it takes none.
const assemblySpec = (id) => (weaponInfo(id) || {}).assembly || null;

/// THE OTHER SLOT OF THE SAME CHAMBER, or `null`.
///
/// A Kitgun is ONE weapon — one mastery track, one riven, one wiki page, and
/// therefore ONE URL — and it is TWO roster entries, because the slot decides
/// which mods it may hold and that is a question with a static answer. Those
/// two facts meet here: `/weapons/Tombfinger` resolves to one entry and the
/// Slot control moves to the other WITHOUT changing the address, which is what
/// makes the two a page rather than two pages that happen to share a name. The
/// second entry still needs an address of its OWN to be linkable at all, and
/// `urlSlug` gives it one; nothing on the page navigates to it.
///
/// Switching is switching WEAPONS in every other sense — its own build, its own
/// riven slots, its own board rows — which is exactly what "nothing crosses
/// between weapons" already guarantees, so nothing extra is needed for it.
const slotSibling = (id) => {
  const s = assemblySpec(id);
  if (!s) return null;
  const w = (META.weapons || []).find(
    (x) => x.id !== id && x.assembly && x.assembly.chamber === s.chamber);
  return w ? w.id : null;
};

/// THIS WEAPON'S PARTS, repaired against what it can actually take.
///
/// A build with no assembly, or one carrying a part from the sibling slot,
/// lands on the server's own default rather than on nothing — the same repair
/// `assembly_of` does on the wire, and it has to agree with it: a page showing
/// one assembly while the server simulates another is the exact shape of bug
/// that had a player measuring 26 KPM on a ranking and 15 in the simulator.
/// That is why the default comes from `/api/meta` and is not computed here.
function defaultAssembly(id, st) {
  const s = assemblySpec(id);
  if (!s) return null;
  const d = s.default || {};
  const has = (list, v) => list.some((x) => x.id === v);
  return {
    grip: st && has(s.grips, st.grip) ? st.grip : d.grip,
    loader: st && has(s.loaders, st.loader) ? st.loader : d.loader,
  };
}

/// THE PARTS BLOCK — two dropdowns, and what each part is worth beside it.
///
/// The block is HIDDEN on everything that is not modular, where Mode is always
/// drawn: every weapon is fired in some mode, and only a Kitgun has parts.
///
/// EACH OPTION CARRIES ITS OWN NUMBERS, because that is the whole decision. A
/// grip is damage, fire rate and (on a charge chamber) charge time; a loader is
/// three additive deltas that may be NEGATIVE, plus a magazine and a reload.
/// A list of twenty names would say none of it, which is the Mode control's own
/// lesson.
function renderAssembly() {
  const block = $("assembly-block");
  const box = $("assembly-row");
  if (!block || !box || !META) return;
  const w = $("weapon").value;
  const s = assemblySpec(w);
  block.hidden = !s;
  if (!s) return;
  if (!assembly) assembly = defaultAssembly(w, null);
  const sub = $("assembly-sub");
  if (sub) sub.textContent = tr("what this weapon is built from");

  // A ROUND COUNT AND A RELOAD ARE NOT THE SAME KIND OF NUMBER, so the block
  // trims its own rather than borrowing the results panel's two-significant
  // figures: "23 rounds" and "1.70 s" is what a card would say.
  const n = (v) => String(Math.round(Number(v) * 100) / 100);
  const sign = (v, unit) => (v > 0 ? "+" : "") + n(v) + (unit || "");
  const pc = (v) => Math.round(Number(v) * 1000) / 10;
  const gripItem = (g) => {
    const d = s.grip_stats && s.grip_stats[g.id];
    const bits = d
      ? [`${n(d.damage)} ${tr("damage")}`, `${n(d.fire_rate)}/s`,
         d.charge_seconds != null ? `${n(d.charge_seconds)} s ${tr("charge")}` : ""]
        .filter(Boolean)
      : [];
    return { id: g.id, label: g.name, hint: bits.join(" · ") };
  };
  const loaderItem = (l) => {
    // ONLY WHAT IT MOVES. Two of the three deltas are zero on most loaders and
    // six are zero on all three, so printing every one would bury the ones that
    // decide the pick.
    const bits = [
      `${n(l.rounds)} ${tr("rounds")}`,
      `${n(l.reload_seconds)} s`,
      l.crit_chance ? `${sign(pc(l.crit_chance), "%")} ${tr("crit")}` : "",
      l.crit_multiplier ? `${sign(l.crit_multiplier)}x` : "",
      l.status_chance ? `${sign(pc(l.status_chance), "%")} ${tr("status")}` : "",
    ].filter(Boolean);
    return { id: l.id, label: l.name, hint: bits.join(" · ") };
  };

  // THE PARTS, on the page's one ranked control — see `rankedSlot`. A part can
  // never be absent (a Kitgun without a grip is not a Kitgun), so the card has
  // no Remove.
  const partCfgs = {};
  const pick = (part, label, items, hint) => {
    const id = "dd-" + part;
    const cur = items.find((it) => it.id === assembly[part]);
    partCfgs[id] = {
      axis,
      label: tr(label),
      title: hint,
      value: assembly[part],
      removable: false,
      // A grip and a loader may share a name, so the SCAN's key carries the
      // part it belongs to.
      items: items.map((it) => ({ key: part + ":" + it.id, value: it.id, label: it.label, hint: it.hint })),
      card: cur ? { name: cur.label, lines: cur.hint ? [cur.hint] : [], title: hint } : null,
      onPick: (v) => {
        if (!v || assembly[part] === v) return;
        assembly = { ...assembly, [part]: v };
        markPresetDirty();
        renderAssembly();
        refreshPanel();
      },
    };
    return rankedSlot(id, partCfgs[id]);
  };

  // THE SLOT. In game the GRIP decides it; here it is picked first, because it
  // decides the mod pool and therefore which build you are even editing. So the
  // two are one control read in the other direction: choose the slot, then a
  // grip from that slot's five.
  const sibling = slotSibling(w);
  const wSlot = (weaponInfo(w) || {}).slot;
  const slotPick = sibling
    ? `<label title="${escHtml(tr("the grip decides this in game; here it comes first, because it decides which mods the weapon can hold — and switching is switching weapons, so each slot keeps its own build"))}">${
        escHtml(tr("Slot"))} ${ddButton("dd-kitslot", {
        value: wSlot,
        items: [w, sibling].map((id) => ({
          value: (weaponInfo(id) || {}).slot,
          label: tr(cap1((weaponInfo(id) || {}).slot)),
        })).sort((a, b) => a.value.localeCompare(b.value)),
        onPick: (v) => {
          if (v === wSlot) return;
          switchSlot(sibling);
        },
      })}</label>`
    : "";

  // THE CHAMBER IS NOT HERE AT ALL. It was stated as a
  // read-only value on the reasoning that a reader should see what is missing
  // on purpose — but the chamber IS the weapon, whose name is already at the
  // top of the page, so the row said the same word twice and took the first
  // line of the block to do it. What belongs in that line is the one thing
  // about this weapon that IS a choice and is not offered anywhere else: the
  // SLOT.
  //
  // NO SUMMARY LINE: the card each part draws carries its own stats, which is
  // all a line under the shut dropdowns could say.
  const axis = { kind: "assembly", idx: 0 };
  box.innerHTML =
    slotPick +
    pick("grip", "Grip", s.grips.map(gripItem),
      tr("the grip sets damage, fire rate and the charge — only this slot's five are offered, because a grip is what decides the slot")) +
    pick("loader", "Loader", s.loaders.map(loaderItem),
      tr("the loader sets the magazine and the reload, and adds three deltas that can be negative"));
  // THE SCAN FIRES WHEN A LIST IS OPENED — see `openRanked`. The strip that
  // reports it lives inside that list, where the ranking is being read.
  bindRankedSlots(box, partCfgs);
}

/// THE VALENCE BLOCK. Two controls, because a Lich hands you two facts: which
/// element, and how big the roll was.
///
/// THE ELEMENT IS MANDATORY. Every copy of an adversary
/// weapon comes out of a Lich carrying one, so there is no "none" to pick and
/// no empty state to open on: `defaultValence` starts on the first element at
/// the roll's ceiling. The weapon's own printed panel — the wiki infobox's
/// figure — is not a build anyone can play, and offering it as one put a
/// number nobody can reproduce on the same row as six that they can.
function renderValence() {
  const box = $("element-cfg");
  if (!box || !META) return;
  const w = weaponInfo($("weapon").value) || {};
  const s = valenceSpec(w.id);
  const sub = $("valence-sub");
  if (!s) { box.innerHTML = ""; if (sub) sub.textContent = ""; return; }
  if (sub) sub.textContent = tr("the bonus this copy came out of its Lich with — added as the weapon's own BASE damage, so elemental mods and status scale with it");
  const pct = (x) => Math.round(x * 1000) / 10;
  // ON THE PAGE'S ONE RANKED CONTROL — see `rankedSlot`. Which element wins is
  // the question a scan is worth the most on: a progenitor element is a whole
  // element entering the hierarchy, so the answer depends on the mods around it
  // and on the target, and no card states it.
  //
  // THE NAME AND THE NUMBER, and nothing else. An
  // evolution's description earns its space because the perks differ from each
  // other; seven elements do not — every one says the same sentence, so seven
  // copies of it is a wall of text between the reader and the seven numbers
  // that are the actual answer. What the bonus DOES is said once, by the
  // block's own subtitle.
  //
  // NO "NONE" OPTION. Every copy of an adversary weapon comes out of a Lich
  // carrying an element, so an empty valence is not a weaker build of this
  // weapon — it is a weapon nobody has, and a number nobody can reproduce.
  const axis = { kind: "valence", idx: 0 };
  const cfgs = {
    "dd-valence": {
      axis,
      label: tr("Element"),
      value: valence.element,
      // NO REMOVE. Every copy of an adversary weapon comes out of a Lich
      // carrying an element, so there is no empty state to offer.
      removable: false,
      items: s.elements.map((e) => ({ key: e, value: e, label: DT(e) })),
      card: { name: DT(valence.element) },
      onPick: (v) => {
        if (!v || valence.element === v) return;
        valence.element = v;
        markPresetDirty();
        renderValence();
        refreshPanel();
      },
    },
  };
  box.innerHTML =
    rankedSlot("dd-valence", cfgs["dd-valence"]) +
    `<div class="runs-row"><label title="${escHtml(tr("how big the roll was, as a share of base damage — a Lich rolls it randomly and Valence Fusion raises it, capping at the number on the right"))}">${escHtml(tr("Valence bonus"))} <span class="unit">%</span> <input type="number" id="valence-bonus" min="${pct(s.min)}" max="${pct(s.max)}" step="0.5" value="${pct(valence.bonus)}"></label>` +
    `<span class="sim-hint">${escHtml(tr("rolls") + ` ${pct(s.min)}–${pct(s.max)}%`)}</span></div>`;
  bindRankedSlots(box, cfgs);
  const inp = $("valence-bonus");
  if (inp) {
    inp.addEventListener("change", () => {
      const v = Number(inp.value) / 100;
      valence.bonus = Math.min(Math.max(Number.isFinite(v) ? v : s.min, s.min), s.max);
      markPresetDirty(); renderValence(); refreshPanel();
    });
  }
}

function renderMode() {
  const box = $("mode-row");
  if (!box || !META) return;
  const w = weaponInfo($("weapon").value) || {};
  const opts = modeOpts(w);
  const sub = $("mode-sub");
  // **THE MODE YOU ARE IN, and not the other six.** A dropdown names the
  // choices and says nothing about them, and the numbers that decide between
  // them — what fills the gauge, how much of it there is, what the earned form
  // gets to fire — are on no other screen. It FOLDS and remembers, because a
  // reader who has learned this weapon does not need it again.
  //
  // LISTING THEM ALL IS A WALL at seven modes: six blocks about something the
  // reader did not pick, with the one that IS theirs no longer findable. The
  // reason to list them was comparison, and comparison is what the BOARD does —
  // it ranks every mode of every weapon as its own row. So the picked one gets
  // its sentences; `modeExplain` still answers for any mode, and the control
  // beside it still names all seven.
  const explain = (id) => {
    const lines = modeExplain(w, id);
    if (!lines.length) return "";
    return foldBlock("mode-def", tr("What this mode is"), "",
      `<div class="modedef on">
        <div class="modedef-n">${escHtml(modeLabel(w, id))}</div>
        ${lines.map((s) => `<div class="modedef-l">${escHtml(s)}</div>`).join("")}
      </div>`);
  };

  if (!opts.length) {
    // ONE WAY TO FIRE IT. Named from the weapon's own form, so it reads as a
    // fact about the weapon rather than as a control somebody disabled — and
    // it still gets its sentence: "base" is a claim (it never transforms) and
    // not merely the absence of a choice.
    const only = (w.modes || ["base"])[0];
    box.innerHTML = `<label>${escHtml(tr("Mode"))} <span class="fixed-val">${
      escHtml(modeLabel(w, only))}</span></label>${explain(only)}`;
    if (sub) sub.textContent = tr("one firing mode");
    wireFolds(box);
    return;
  }
  // A build naming a mode this weapon does not offer falls back to how the
  // weapon is played — a stale preset, or one copied from another weapon.
  if (!opts.some(([id]) => id === mode)) mode = defaultMode(w.id, null);
  const why = (opts.find(([id]) => id === mode) || [])[2];
  if (sub) sub.textContent = tr("how this build is played");
  box.innerHTML = `<label>${escHtml(tr("Mode"))} ${ddButton("dd-mode", {
    value: mode,
    items: opts.map(([id, label, offReason]) => ({
      value: id, label: label + (offReason ? " ⊘" : ""), hint: offReason || "",
      disabled: !!offReason,
    })),
    onPick: (v) => {
      mode = v;
      // Keep the address bar honest: it may have said a mode, and it is not
      // saying this one any more.
      const q = new URLSearchParams(location.search);
      if (q.get("mode") && q.get("mode") !== v) {
        q.set("mode", v);
        history.replaceState(null, "", `${location.pathname}?${q}`);
      }
      markPresetDirty(); renderMode(); refreshPanel();
    },
  })}</label>${why ? `<span class="warn">⊘ ${escHtml(why)}</span>` : ""}${
    explain(mode)}`;
  wireFolds(box);
}

function renderEvo() {
  const tiers = weaponEvos();
  const rows = [];
  // TIERS UNLOCK IN ORDER, as they do in game: tier N is reachable only once
  // tier N-1 is installed. Without it the whole branch is
  // void — a tier-2 perk with no tier 1 is not a weaker build, it is not a
  // build — so the later rows are DISABLED rather than silently contributing
  // to a number nobody could reach.
  const openTo = evoOpenTo();
  const genesis = wikiUrl(wikiWeaponName(weaponInfo($("weapon").value)));
  const cfgs = {};
  for (const t of tiers) {
    const sel = evoSel[t.tier] || null;
    const locked = t.tier > openTo;
    const id = "dd-evo-" + t.tier;
    const o = (t.options || []).find((x) => x.id === sel);
    cfgs[id] = {
      axis: { kind: "evo", idx: 0 },
      label: `EVO ${ROMAN(t.tier)}`,
      addLabel: tr("add evolution"),
      value: sel || "",
      // A TIER CAN BE EMPTY — a bare weapon is every tier empty — so this one
      // HAS a Remove. That is the whole of the difference from a part or an
      // element, and it is one menu item rather than a second shape.
      removable: !!sel,
      locked,
      lockedWhy: locked ? tr("install the previous tier first") : "",
      items: t.options.map((x) => ({
        key: x.id,
        value: x.id,
        label: x.name,
        // The perk's own lines, flattened: a list row is one line, and the full
        // text is on the card of whichever perk is installed.
        hint: evoLines(x).join(" · "),
        // WHAT THE SIM DOES NOT MODEL, ON THE ROW YOU CHOOSE FROM — the whole
        // point of these chips is to be readable while deciding, which is
        // exactly when the list is open.
        extra: (x.broken ? ' <i class="bx">BROKEN</i>' : "") + evoGapChips(x, "i"),
      })),
      card: o ? evoCardOf(o, genesis) : null,
      onPick: (v) => pickEvolution(t.tier, v || null),
    };
    rows.push(rankedSlot(id, cfgs[id]));
  }
  $("evo-rows").innerHTML = rows.join("");
  // ONE AXIS FOR EVERY TIER, still: they are scanned in a single pass — a dozen
  // candidates, not seventy — so opening any tier's list measures them all and
  // the next tier's opens already answered. What changed is WHEN. The pass used
  // to run from this render, on the reasoning that the options were all on
  // screen at once; they are inside a closed list now, so it runs on open
  // (`openRanked`).
  bindRankedSlots($("evo-rows"), cfgs);
}

/// THE INSTALLED PERK, as its own card — the pieces `rankedSlot` draws.
///
/// A gap this app admits has to be ON THE PAGE, and a chip that appears only
/// inside an open list is a weaker promise than that (`check_disclosure`'s
/// subject). The list carries every option's chips because that is where the
/// choosing happens; this carries the chosen one's, plus the text and the wiki
/// link a list row cannot hold, and it is there without anybody opening
/// anything.
function evoCardOf(o, genesis) {
  // The broken warning lives INSIDE the card, so it never straddles the
  // divider into the next tier.
  const warn = o.broken
    ? `<span class="ed warn">⚠ ${escHtml(tr("does not work in-game (wiki) — the simulation computes it as NO EFFECT"))}</span>`
    : "";
  // THE CONDITION OVERLOAD CAVEAT. A perk flagged here raises base damage
  // WITHOUT feeding the CO term, so it reads strictly better than the tier's
  // other option and is not — every status is worth less, and past a couple of
  // statuses the other one overtakes it. Reported as a bug
  // precisely because the only place saying so was the CO row in the stats
  // panel, which is not where the comparison happens.
  const coNote = o.co_excluded
    ? `<span class="ed caveat" title="${escHtml(
        tr("Condition Overload computes on this weapon's ORIGINAL base damage — this perk's added base is excluded, so every status type is worth less than the card implies"),
      )}">◈ ${escHtml(tr("its added base does not feed Condition Overload"))}</span>`
    : "";
  return {
    name: o.name,
    // Evolutions have no standalone wiki pages, so they link to the WEAPON's —
    // which carries the same evolution tables and is where you wanted to end up
    // anyway.
    href: genesis,
    icon: o.icon,
    broken: o.broken,
    lines: evoLines(o),
    title: (o.effects || []).join(String.fromCharCode(10)),
    chips: (o.broken ? ' <i class="bx">BROKEN</i>' : "") + evoGapChips(o, "i"),
    notes: coNote + warn,
  };
}

/// INSTALLING OR REMOVING ONE TIER, and everything that follows from it.
function pickEvolution(tier, id) {
  const tiers = weaponEvos();
  evoSel[tier] = id;
  // Removing a tier removes everything that stood on it. Leaving them
  // selected-but-void would show a build the game cannot make, and the engine
  // would price perks the weapon never reached.
  if (!id) tiers.forEach((x) => { if (x.tier > tier) evoSel[x.tier] = null; });
  // ...and an installed form takes with it every mod that needed the weapon
  // not to have it (a Cannonade under the Incarnon form). Said out loud, never
  // silently: the slot emptying under you is exactly the kind of change a
  // build must not make without telling you.
  const no = forbiddenByEvos();
  const evicted = slots
    .filter((s) => s.mod && no.has(s.mod))
    .map((s) => (modById(s.mod) || {}).name || s.mod);
  if (evicted.length) {
    slots = slots.map((s) => (s.mod && no.has(s.mod) ? { ...s, mod: null, rank: null } : s));
    presetToast(`${tr("unequipped")}: ${evicted.join(", ")} — ${
      tr("it needs the same trigger on every firing mode")}`);
    renderMods();
  }
  // Redraw the whole ladder, not just this row: a pick opens (or a removal
  // shuts) every tier below it.
  renderEvo(); renderMode(); refreshPanel();
}

// ---- Sim: scenario/buff settings + run against an enemy -----------------
// The build (mods/arcane/evolutions) comes from buildPayload(); this block
// only owns the scenario + engine-modeled buff levers (`sim`). Run POSTs to
// /api/simulate and renders a summary card + an illustrative arena replay.
// The SIMULATOR tab's read-only build summary — the sim always tests the
// ACTIVE preset's build, and this card shows exactly what that is (mods
// at rank, arcane, evolutions). Editing happens in the Builder; the
// button jumps there.
function renderSimBuild() {
  const box = $("sim-build-info");
  if (!box || !META) return;
  const sub = $("sim-build-sub");
  // The LABEL, never the id: an official build's id carries its ruler and rank
  // (`single_target#cycle#1`) and is not a thing to show anyone.
  const activeLabel = presetLabel(buildNamed(activePreset));
  if (sub) sub.textContent = activeLabel ? `${tr("testing build")}: ${activeLabel}` : "";
  const chip = (img, label, rk) =>
    `<span class="sb-chip">${imgTag(img, "sb-img")}<span>${escHtml(label)}</span>${rk != null ? `<span class="rk">R${rk}</span>` : ""}</span>`;
  const w = weaponInfo($("weapon").value);
  const parts = [];
  const modChips = slots.map((s) => {
    const m = s.mod && modById(s.mod);
    if (!m) return "";
    return chip(IMG(m.image), m.name, s.rank == null ? m.max_rank : s.rank);
  }).filter(Boolean);
  // HOW IT IS PLAYED, first, and READ-ONLY. It is part of the build, so the
  // simulator shows it and does not offer to change it — the fight owns the
  // fight and the build owns this. This card is now the ONLY place the mode
  // appears on this tab: the builder's own control is hidden here, because two
  // places to read one field with one of them writable is how a build gets
  // edited somewhere that is not the builder.
  //
  // ALWAYS, including a weapon with one way to be fired — the same rule the
  // builder's block carries ("one mode is stated, not offered"). Drawing it
  // only where there is a choice makes a summary of the build silently drop a
  // field the build has.
  parts.push(`<div class="sb-h">${tr("Mode")}</div>`);
  parts.push(`<div class="sb-chips"><span class="sb-chip">${
    escHtml(modeLabel(weaponInfo($("weapon").value), mode))}</span></div>`);
  parts.push(`<div class="sb-h">${tr("Mods")} · ${modChips.length}</div>`);
  parts.push(`<div class="sb-chips">${modChips.join("") || `<span class="sb-empty">${tr("no mods equipped")}</span>`}</div>`);
  if ((w.arcane_slots || 0) >= 1) {
    const arcChips = arcanes
      .map((id, i) => {
        const a = id !== "none" && arcaneById(id);
        return a ? chip(IMG(a.image), a.name, arcaneRanks[i] ?? ((a.ranks || []).length - 1)) : "";
      })
      .filter(Boolean);
    parts.push(`<div class="sb-h">${tr("Arcane")}</div>`);
    parts.push(`<div class="sb-chips">${arcChips.join("") || `<span class="sb-empty">${tr("no arcane")}</span>`}</div>`);
  }
  if (w.uses_evo2) {
    const evoChips = weaponEvos().map((t) => {
      const o = evoSel[t.tier] && t.options.find((x) => x.id === evoSel[t.tier]);
      return o ? chip(o.icon ? IMG(o.icon) : null, `${t.tier} · ${o.name}`) : "";
    }).filter(Boolean);
    parts.push(`<div class="sb-h">${tr("Evolutions")}</div>`);
    parts.push(`<div class="sb-chips">${evoChips.join("") || `<span class="sb-empty">${tr("none selected")}</span>`}</div>`);
  }
  // THE VALENCE, LAST — which is where the builder puts it. This card reads in the builder's own order so the two can be
  // compared line for line, and that makes it the FOURTH block on an adversary
  // weapon, because such a weapon has no evolutions and the block above it is
  // not drawn. It sat second for a while, beside the mode, which read as a
  // different build from the one the builder shows.
  //
  // It is part of what this build IS: two Kuva Nukors differing only in
  // progenitor element are two different builds and two different numbers, so
  // a card that says "this is what is being tested" and omits it is telling
  // half of it. Only where the weapon HAS one — the same "no choice, no axis"
  // rule the builder's block follows — and the percentage rides with the
  // element, because 60% Heat and 25% Heat are not the same weapon.
  if (valenceSpec(w.id)) {
    parts.push(`<div class="sb-h">${tr("Valence")}</div>`);
    parts.push(`<div class="sb-chips"><span class="sb-chip">${
      escHtml(DT(valence.element))} +${Math.round(valence.bonus * 1000) / 10}%</span></div>`);
  }
  parts.push(`<a class="ghost-btn small sb-edit" href="${weaponPath($("weapon").value)}">${tr("edit in Builder")}</a>`);
  box.innerHTML = parts.join("");
}

// The headshot rate a weapon is played at. A SENTINEL is fired by the
// companion, which picks its own targets and does not aim for the head, so it
// starts at 0 rather than the player's 100. Still a knob
// here — the engine is what PINS a sentinel at 0 whatever a request says, so
// this only decides where the control opens.
const defaultHeadshotPct = (w) => ((w || {}).sentinel ? 0 : META.defaults.headshot_pct);

/// THE WIELDER'S FLOOR, from `/api/meta` — `data/tenno/default.yaml`, the worst
/// max-rank frame that does not exist.
/// WHOSE FLOOR THIS WEAPON'S FIGHT STARTS FROM — a Warframe's, or a SENTINEL's
/// for the 21 companion weapons. Two rosters, two lowest
/// values: 450/130/80 against 250/0/105, so showing one for the other told a
/// reader their Artax had a Warframe's armor.
const tennoFloor = () => {
  const w = (META.weapons || []).find((x) => x.id === ($("weapon") || {}).value);
  const f = (w && w.sentinel ? META.sentinel_floor : META.tenno_floor);
  return f || { name: "", health: 0, shield: 0, armor: 0, energy: 0, sprint: 0.9 };
};

/// ONE OVERRIDABLE WARFRAME STAT — a tick and a number.
///
/// A BARE NUMBER CANNOT SAY "LEAVE IT ALONE". Sent on every fight, it
/// overwrites the floor in `data/tenno/default.yaml` before it is read, so "the
/// neutral Tenno has 105 armor" is true of the data and false of what runs. Nor
/// can it say the other thing: four released frames have NO energy pool, so 0
/// is a real value that "unset" cannot be spelled as.
///
/// So the tick IS the override: unticked, the key is dropped and the server
/// falls back to the floor; ticked, the number is sent and starts AT the floor,
/// so ticking alone changes nothing.
/// WHAT THE FIGHT STARTS FROM, stated before the boxes that change it.
///
/// The four controls under this line are OVERRIDES, and an override shown
/// alone cannot be read: nothing tells "0 because there is no frame" from "0
/// because that IS the floor", and the second is true of two of these stats.
///
/// IT NAMES WHAT IT IS. "The worst max-rank frame that does not exist" is
/// `data/tenno/default.yaml`'s claim, and it is why a number here means
/// something: a bonus this player pays is a bonus EVERY frame pays.
const wfFloorLine = () => {
  const f = tennoFloor();
  // WHOLE NUMBERS STAY WHOLE. Four of these five are integers and `sig2` wrote
  // "250.00" for them, which reads as a measurement rather than as a stat.
  const num = (v) => (Number.isInteger(v) ? String(v) : sig2(v));
  const cell = (l, v) => `<span><b>${escHtml(l)}</b> ${num(v)}</span>`;
  return `<div class="wffloor" title="${escHtml(tr(
    "the fight's wielder before any override: each stat is the LOWEST any released Warframe has at rank 30, so a bonus it pays is one every frame pays. EVERY OFFICIAL BOARD IS SCORED ON THIS WIELDER — tick a box below to test a real frame instead"))}">`
    + `<span class="wffloor-h">${escHtml(
        (f.name === "Sentinel" ? tr("Sentinel floor") : tr("Warframe floor"))
        + " · " + tr("every board is scored on this"))}</span>`
    + cell(tr("Health"), f.health) + cell(tr("Shield"), f.shield)
    + cell(tr("Armor"), f.armor) + cell(tr("Max energy"), f.energy)
    + (f.name === "Sentinel" ? "" : cell(tr("Sprint"), f.sprint))
    + `</div>`;
};

const wfOverride = (key, label, floorKey, min, max, step, why) => {
  const floor = tennoFloor()[floorKey];
  const on = sim[key] !== undefined && sim[key] !== null;
  const shown = on ? sim[key] : floor;
  return `<label class="wfov ${on ? "" : "off"}" title="${escHtml(why)}">`
    + `<input type="checkbox" data-k="${key}" data-wfov="${floorKey}"${on ? " checked" : ""}>`
    + ` ${escHtml(label)} `
    + `<input type="number" data-k="${key}" data-wfovnum="1" min="${min}" max="${max}" step="${step}"`
    + ` value="${shown}"${on ? "" : " disabled"}>`
    + `</label>`;
};

// The SCENARIO — enemy, technique, measurement — is the SIMULATOR's, and the
// optimizer borrows it rather than keeping a lookalike: one state, one
// renderer, so a search is scored under the fight you are simulating with by
// construction. `ids` names the host per section and a section with no host is
// not drawn. ENGAGEMENT LENGTH sits with the enemy rather than the measurement,
// which is why the optimizer needs it and needs neither Runs nor Measure.
/// **THE WHOLE FIGHT — every axis, including the ones this weapon hides.**
///
/// The blocks above show what APPLIES to the weapon in front of you, which
/// leaves a field this weapon FORCES and one it merely does not use invisible;
/// both still travel. SO IT IS A READING SURFACE FIRST: a forced row says what
/// it will run as and WHY — `sim.headshot_pct` can be 100 on a Verglas while
/// the run is computed at 0. EDITABLE WHERE A CONTROL CAN MEAN IT: a flag and a
/// number here, while a formation or a buff map is edited in its own panel.
/// **EVERY RULE THIS FIGHT MAKES, FOR EVERY CLASS** — the one surface where a
/// scenario is edited as the whole document it is. DERIVED FROM THE ENGINE'S
/// OWN LEGALITY TABLE: exactly the (class, axis) pairs
/// `META.class_rules.overridable` lists. A CLASS WITH NOTHING TO ARGUE ABOUT IS
/// STILL LISTED, saying so — dropping it would read as "we did not check".
function houseRulesRow(w) {
  const classes = ((META && META.class_rules) || {}).classes || [];
  const here = w && w.weapon_class;
  const NAMES = {
    primary: tr("Primary"), secondary: tr("Secondary"),
    archgun: tr("Arch-Gun"), sentinel: tr("Companion"),
  };
  const cols = classes.map((cls) => {
    const pairs = overridablePairs().filter((p) => p[0] === cls);
    const body = pairs.length
      ? pairs.map(([, id]) => {
          const rule = classRuleOf(cls, id);
          // The value the CAPABILITY gives, read off any weapon of this class —
          // which is what the tick falls back to and what clearing it restores.
          const sample = (META.weapons || []).find((x) => x.weapon_class === cls);
          const f = settledAxis(sample, id);
          const dflt = f ? f.value : false;
          const on = rule === undefined ? !!dflt : !!rule;
          return `<label class="check" title="${escHtml(f ? tr(f.why) : "")}">`
            + `<input type="checkbox" data-cr="${escHtml(cls)}|${escHtml(id)}" data-crdef="${!!dflt}"`
            + `${on ? " checked" : ""}> <code>${escHtml(id)}</code>`
            + (rule === undefined
                ? ` <span class="wf-was">${escHtml(tr("default"))}</span>`
                : ` <b>${escHtml(tr("ruled by this fight"))}</b>`)
            + `</label>`;
        }).join("")
      : `<i class="wf-absent">${escHtml(tr("nothing to decide"))}</i>`;
    return `<div class="hr-col${cls === here ? " here" : ""}">`
      + `<div class="hr-h">${escHtml(NAMES[cls] || cls)}`
      + (cls === here ? ` <span class="wf-was">${escHtml(tr("this weapon"))}</span>` : "")
      + `</div>${body}</div>`;
  }).join("");
  return `<div class="wf-row wf-hr"><code>class_rules</code>`
    + `<div class="hr-grid">${cols}</div>`
    + `<span class="wf-why">${escHtml(tr(
        "rules this fight makes for a whole weapon class, so any weapon can be measured against this one document. Only what the sim SIMPLIFIES can be ruled on — the game's own limits are not offered"))}</span>`
    + `</div>`;
}

function renderWholeFight() {
  const host = $("sim-whole-fight-body");
  if (!host) return;
  const axes = (META && META.scenario_axes) || [];
  const w = weaponInfo($("weapon").value) || {};
  const GROUPS = [["target", tr("The target")], ["engagement", tr("The engagement")],
                  ["wielder", tr("The wielder")], ["squad", tr("What the Warframe brings")]];
  const shown = (v) => {
    if (v === undefined) return `<i class="wf-absent">${escHtml(tr("not set — the default"))}</i>`;
    if (v === null) return "null";
    if (typeof v === "object") {
      const n = Array.isArray(v) ? v.length : Object.keys(v).length;
      return `<i>${escHtml(n ? tr("{n} entries").replace("{n}", n) : tr("empty"))}</i>`;
    }
    return escHtml(String(v));
  };
  host.innerHTML = GROUPS.map(([g, label]) => {
    const rows = axes.filter((a) => a.group === g).map((a) => {
      // THE HOUSE RULES ARE THE "GLOBAL EDIT", and they are
      // the reason this panel is more than a reading surface: the ordinary
      // blocks show the fight AS IT APPLIES TO THE WEAPON IN FRONT OF YOU,
      // which is the right default and cannot say what this same document does
      // to an Arch-Gun. This row is where a reader edits the classes they are
      // not currently pointed at.
      if (a.id === "class_rules") return houseRulesRow(w);
      const f = settledAxis(w, a.id);
      const live = sim[a.id];
      // THE FORCED ROW SHOWS BOTH NUMBERS. What the document says and what the
      // run will use are different facts, and the gap between them is the one
      // thing this panel exists to make visible.
      // A CLASS RULE BEATS THE CAPABILITY where the capability's absence was
      // ours to begin with, so the row must show the RULED value — otherwise
      // the one panel whose job is "what will actually run" would be the last
      // place still reporting the default.
      const cls = w && w.weapon_class;
      const rule = f && f.overridable && cls ? classRuleOf(cls, a.id) : undefined;
      const runs = rule === undefined ? (f ? f.value : undefined) : rule;
      const val = f
        ? `<b>${escHtml(String(runs))}</b> <span class="wf-was">${
            rule === undefined
              ? escHtml(tr("document says")) + " " + shown(live)
              : escHtml(tr("ruled by this fight for the {c} class").replace("{c}", cls))
          }</span>`
        : shown(live);
      const editable = !f && (a.kind.t === "flag" || a.kind.t === "number");
      const ctl = editable
        ? (a.kind.t === "flag"
            ? `<input type="checkbox" data-k="${a.id}"${live ? " checked" : ""}>`
            : `<input type="number" data-k="${a.id}" min="${a.kind.min}" max="${a.kind.max}" value="${
                live === undefined || live === null ? "" : live}">`)
        : "";
      return `<div class="wf-row${f ? " forced" : ""}">`
        + `<code>${escHtml(a.id)}</code>`
        + `<span class="wf-val">${val}</span>`
        + `<span class="wf-ctl">${ctl}</span>`
        + (f ? `<span class="wf-why">${escHtml(tr(f.why))}</span>` : "")
        + `</div>`;
    }).join("");
    return `<div class="wf-group"><div class="wf-g-h">${escHtml(label)}</div>${rows}</div>`;
  }).join("");
  // The same generic binding every other scenario field uses, so a change here
  // is a change to the fight and nothing else has to know about this panel.
  host.querySelectorAll("[data-cr]").forEach((el) => {
    el.addEventListener("change", () => { applyClassRule(el); renderSim(); });
  });
  host.querySelectorAll("[data-k]").forEach((el) => {
    el.addEventListener("change", () => {
      const k = el.dataset.k;
      sim[k] = el.type === "checkbox" ? el.checked : Number(el.value);
      markScenarioDirty();
      renderSim();
    });
  });
}

function renderScenarioFields(ids, opts = {}) {
  const w = weaponInfo($("weapon").value);
  const enemies = allEnemies();
  const en = enemies.find((e) => e.id === sim.enemy) || enemies[0];
  if (en) sim.enemy = en.id;

  // ---- 1. THE FIGHT: who, where, how strong, how long ------------------
  // Target and arena in ONE block, not two: an enemy is
  // not a name, it is a name plus everything about the encounter, and the
  // enemies still to come bring their own assortment of those — a level, an
  // arena, an Eximus flag, a faction override. They all answer "what am I
  // shooting at, under what conditions", so they belong in one place that can
  // grow rather than in a grid that has to be re-cut every time.
  if (ids.target) {
    // The wiki link sits OUTSIDE the picker button — an <a> inside a <button>
    // is not valid HTML, and the two are different actions anyway: one
    // changes the fight, the other reads about the unit. Built from the
    // ENGLISH name like every other wiki link, and absent for a synthetic
    // target, which has no page to land on.
    const wiki = en && !en.synthetic
      ? `<a class="en-wiki" href="${wikiUrl(en.name_en || en.name)}" target="_blank" rel="noopener"
            title="${escHtml(tr("open the wiki page"))}">${escHtml(tr("wiki"))} ↗</a>`
      : "";
    // WHAT THIS CARD REACHES, said out loud once there is more than one body.
    //
    // It is the AIMED body's unit and it is the BRUSH for the next placement —
    // two jobs that were one thing while a fight had one target, and are still
    // one control because the aimed body IS the thing you place a copy of. What
    // it is NOT is a control over the floor: a body keeps the unit it was
    // placed with (`placeAt`), which is the whole point of a formation built
    // unit by unit and is invisible until somebody switches and watches nothing
    // change. So the count is on screen rather than left to be discovered.
    const brushNote = (s) => {
      const n = (s.formation || []).length;
      if (!n || opts.readonly) return "";
      const kept = (s.formation || []).filter((f) => f.enemy && f.enemy !== s.enemy).length;
      return `<p class="arc-note">${escHtml(kept
        ? trF("this is the aimed enemy, and what the place tool puts down. {n} already on the floor keep the unit they were placed with.", { n: kept })
        : tr("this is the aimed enemy, and what the place tool puts down. Enemies already on the floor keep the unit they were placed with."))}</p>`;
    };
    const card =
      `<div class="en-row">
         <button class="en-card" id="${ids.target}-pick" title="${escHtml(tr("choose the target"))}">
           ${enemyImg(en, "en-img")}
           <span class="en-txt">
             <span class="en-name">${en
               ? `<i class="ai-sw" style="background:${unitColor(en.id)}"></i>` : ""
             }${escHtml(en ? en.name : tr("Enemy"))}</span>
             <span class="en-meta">${escHtml(enemyMeta(en))}</span>
             ${enemyVuln(en)}${enemyStatusImmune(en)}${enemyEffectsNulled(en)}
             ${enemyCaveat(en)}
           </span>
         </button>
         ${wiki}
       </div>`;
    // EVERYTHING ABOUT THE TARGET LIVES IN THE CANVAS, and
    // only the DURATION stays outside: how long the fight runs is a property of
    // the ENGAGEMENT rather than of anybody standing on the floor, and it is the
    // one field in this block that is not about the target.
    //
    // The card and the fields are rendered INTO the arena host and then MOVED —
    // not re-serialised — into the scene by `mountArenaCanvas`. Moving the nodes
    // is what keeps `pick.onclick` bound, every `data-k` listener live, and
    // every selector pointing at the element it always did.
    $(ids.target).innerHTML =
      `<div class="arena" id="${ids.target}-arena">
        <div class="arc-side">${card}
          <div class="arc-fields">
            <label>${escHtml(tr("Level"))} <input type="number" data-k="level" min="1" max="9999" value="${sim.level}"></label>
            <label class="check"><input type="checkbox" data-k="steel_path" ${sim.steel_path ? "checked" : ""}> Steel Path</label>
            ${eximusField(en)}
          </div>
          ${brushNote(sim)}
        </div>
      </div>` +
      `<div class="field-grid">
        ${deployField(w, sim)}
        <label>${escHtml(tr("Duration (s)"))} <input type="number" data-k="duration" min="1" max="3600" value="${sim.duration}"></label>
      </div>`;
    const pick = $(`${ids.target}-pick`);
    if (pick && !opts.readonly) pick.onclick = (e) => { e.stopPropagation(); openEnemyPicker(pick); };
    if (pick && opts.readonly) pick.disabled = true;
    // THE ARENA, drawn last so it can measure the width it was given.
    mountArena($(`${ids.target}-arena`), sim, en, opts);
  }

  // ---- 2. THE WIELDER: whoever is holding the weapon, and what they do ---
  // Block 1 is the other actor; this is your side of the fight. It grew from
  // "technique" when the engine got a second actor: the
  // form you fire, how you fire it, the states a mod card gates on, and the
  // Warframe behind it are all one answer to "who is shooting". A neutral
  // frame wears nothing and is doing nothing, which is why the states are off
  // and the stats are 0 — and why the mods and arcanes that read them
  // contribute nothing until you say otherwise, on the panel, in the sim and
  // in the search alike.
  //
  // NOT "the Tenno". A ROBOTIC weapon is not held by one:
  // the wiki is explicit that MOAs "share Robotic weapons with Sentinels and
  // equip their weapons", so the wielder of Verglas Prime is a Sentinel or a
  // MOA. Naming the section after the commonest case made the model say
  // something false about every companion weapon.
  // NO FORM CONTROL HERE. How the weapon is played is part of the BUILD and
  // lives in the builder — a fight that decided it could only ever measure
  // whichever way the ruler happened to pin, which is what kept "the Torid
  // that never transmutes" unaskable.

  if (ids.technique) {
    $(ids.technique).innerHTML = `
      ${aimField(w, sim)}
      ${headshotField(w, sim)}
      <label class="check" title="${escHtml(tr("the wielder's state: mods that only pay while Invisible (Spectral Serration) grant nothing when this is off"))}"><input type="checkbox" data-k="invisible"${sim.invisible ? " checked" : ""}> ${escHtml(tr("Invisible"))}</label>
      <label class="check" title="${escHtml(tr("the wielder's state: what a card means by \"while Airborne\""))}"><input type="checkbox" data-k="airborne"${sim.airborne ? " checked" : ""}> ${escHtml(tr("Airborne"))}</label>
      <label class="check" title="${escHtml(tr("the wielder's state: what a card means by \"With Overshields\". Nothing here takes them away, so it is a declaration"))}"><input type="checkbox" data-k="overshields"${sim.overshields ? " checked" : ""}> ${escHtml(tr("Overshields"))}</label>
      <label class="check" title="${escHtml(tr("the wielder's state: what a card means by \"With Channeled Ability active\". The ability must DRAIN ENERGY over time — Desecrate, Haven and an empty Gloom do not count"))}"><input type="checkbox" data-k="channeling"${sim.channeling ? " checked" : ""}> ${escHtml(tr("Channeled ability"))}</label>
      <label class="check" title="${escHtml(tr("the wielder's state: what a card means by \"With Melee Weapon Equipped\". It means the weapon is DRAWN — a quick-melee swing out of a gun does not satisfy it. Every ruler runs it drawn"))}"><input type="checkbox" data-k="melee_equipped"${sim.melee_equipped !== false ? " checked" : ""}> ${escHtml(tr("Melee drawn"))}</label>
      <label class="check" title="${escHtml(tr("the LOADOUT, not what the wielder is doing: off means a full one, which is what the board is scored under. On, this weapon is the only one carried — the Vasto's Lone Gun pays its \"With No Primary Equipped\" half, and every \"On Equip from Primary\" or \"while Holstered\" clause becomes impossible rather than merely unmodelled"))}"><input type="checkbox" data-k="solo_weapon"${sim.solo_weapon ? " checked" : ""}> ${escHtml(tr("Only this weapon"))}</label>
      <label title="${escHtml(tr("picking a frame fills armor, max energy and sprint speed below — the roster is UNMODDED, so a built frame carries more and the numbers stay editable"))}">${escHtml(tr("Warframe"))} ${ddButton("sim-frame", {
        value: sim.frame || "",
        dataK: "frame",
        // A ROSTER GROWS, so it is searched — the same rule the scenario list
        // follows. It was the last native `select` in the fight panel; a
        // dropdown that looks like the platform's rather than like the page's
        // is a control a reader has to learn twice.
        search: true,
        // THE EMPTY OPTION IS NAMED, because it stopped meaning "nothing". It is the FLOOR — the worst max-rank frame there
        // is, stat by stat — and every official board is scored on it, so
        // calling it "no frame" described a state the fight has not had since
        // the floor landed and hid the one wielder a reader most needs to know
        // about.
        items: [{ value: "", label: tr("baseline — the floor every board is scored on") }]
          .concat(frames().map((f) => ({ value: f.id, label: f.name }))),
      })}</label>
      ${wfFloorLine()}
      ${wfOverride("wf_health", tr("Health"), "health", 1, 100000, 1,
        tr("your Warframe's health, buffs included — the Basmu's Dreadful Killshot pays +20% damage and status chance for every 75 of it"))}
      ${wfOverride("wf_armor", tr("Armor"), "armor", 0, 100000, 1,
        tr("your Warframe's armor, buffs included — Primary Bulwark pays +1% damage per point past 1,000"))}
      ${wfOverride("wf_energy", tr("Max energy"), "energy", 0, 100000, 1,
        tr("your Warframe's MAX energy — Primary Overcharge turns 35% of it into multishot"))}
      ${wfOverride("wf_sprint", tr("Sprint"), "sprint", 0, 3, 0.05,
        tr("your Warframe's sprint speed — several Incarnon perks pay only at 1.2 or higher"))}`;
  }

  // ---- 2b. WHAT THE WARFRAME BRINGS ------------------------------------
  // Its own renderer because it is a LIST rather than a field: two of them, one
  // capped at five, each row a control with its own remove. It sits in the
  // wielder block because that is whose it is.
  if (ids.squad) renderSquad(ids.squad, w, sim, opts);

  // ---- 3. LIMITS: what the simulation is allowed to assume -------------
  // Infinite ammo is NOT a technique — nobody plays it. It
  // is a statement about what this run does not model, and the things that
  // will join it are the same kind of statement.
  if (ids.limits) {
    $(ids.limits).innerHTML = ammoField(w, sim) + buffTriggersField();
  }

  // ---- 3b. THE FIGHT'S OWN STAT BONUSES --------------------------------
  //
  // Everything this weapon is handed by something that is not its build. They
  // land in the same ADDITIVE buckets the mods feed — "效果等于又塞mod" — so a
  // player who knows what their squad, their frame or an ability is worth types
  // the number and the whole app treats it as one more card: the panel's own
  // arithmetic, the sim, the optimizer's scoring, and every lock.
  //
  // BLANK IS ZERO, not empty: a fight hands this weapon nothing unless someone
  // says otherwise, which is what every ruler and every stored scenario means.
  if (ids.extra) {
    const ex = sim.extra_stats || {};
    $(ids.extra).innerHTML = EXTRA_STAT_KEYS.map(([k, label]) =>
      `<label title="${escHtml(tr("a percentage, into the same bucket a mod of this stat feeds — permanent, no trigger and no clock"))}">${escHtml(tr(label))} <span class="unit">%</span> <input type="number" data-xk="${k}" step="1" value="${ex[k] ? r3(ex[k] * 100) : ""}" placeholder="0"></label>`
    ).join("");
  }

  // ---- 4. MEASUREMENT: nothing the player does in-game -----------------
  if (ids.run) {
    $(ids.run).innerHTML = `
      <label title="${escHtml(tr("what the run is judged by — the headline number and the picker's gain scan both follow it"))}">${escHtml(tr("Measure"))} ${
        ddButton("dd-metric", {
          value: sim.metric,
          dataK: "metric",
          // FROM THE ENGINE'S TABLE, so a metric it declares is offered here
          // without this list being edited — two declarations of one set is
          // one that goes stale.
          items: (META.metrics || []).map((m) => ({
            value: m.id, label: tr(m.label), hint: tr(m.hint),
          })),
        })}</label>`;
  }

  // …AND THE WHOLE-FIGHT PANEL, drawn from the same state as the blocks
  // above so the two can never disagree about what the fight holds.
  renderWholeFight();

  const boxes = [ids.target, ids.technique, ids.limits, ids.extra, ids.run]
    .filter(Boolean)
    .map($);
  // READ-ONLY hosts get the same fields, in the same order, showing the same
  // values — and no way to change them. A preset is edited in exactly ONE
  // place: two editors over one document is how a document
  // gets edited twice and saved once. The optimizer therefore SHOWS the fight
  // and links to the module that owns it.
  if (opts.readonly) {
    boxes.forEach((box) => box.querySelectorAll("[data-k],[data-xk],[data-bev],[data-bevg]").forEach((el) => {
      el.disabled = true;
      el.title = tr("edit this in the Simulator");
    }));
    return;
  }
  // The pools at THIS fight's level, fetched once per (level, Steel Path) and
  // painted in when they arrive. Fired from here because this is the one
  // function that draws the target card, on either tab.
  loadTargetStats().then((changed) => { if (changed) paintTargetMeta(); });
  boxes.forEach((box) =>
    box.querySelectorAll("[data-cr]").forEach((el) =>
      el.addEventListener("change", () => { applyClassRule(el); renderSim(); })));
  // A LIST, so it cannot ride the generic `data-k` binding, which stores a
  // scalar. It is still a scenario field in every other way.
  boxes.forEach((box) => {
    box.querySelectorAll("[data-bev]").forEach((el) =>
      el.addEventListener("change", () => toggleBuffTrigger(el.dataset.bev, el.checked)));
    box.querySelectorAll("[data-bevg]").forEach((el) => {
      // HALF-TICKED, which HTML has no attribute for: the header shows it and
      // a click from there switches the whole group ON, because that is what a
      // reader reaching for a partly-ticked group means.
      if (el.dataset.some) el.indeterminate = true;
      el.addEventListener("change", () => toggleBuffTriggerGroup(el.dataset.bevg, el.checked));
    });
  });
  boxes.forEach((box) =>
    box.querySelectorAll("[data-k]").forEach((el) => {
      el.addEventListener("change", () => {
        const k = el.dataset.k;
        // A WARFRAME OVERRIDE IS TWO CONTROLS FOR ONE FACT, so it cannot use
        // the generic binding: the tick and the number share a `data-k`, and
        // reading `el.checked` into it would store `true` where a number goes.
        //
        // THE TICK DECIDES WHETHER THE KEY EXISTS AT ALL. Deleting it is the
        // whole mechanism — an absent key is what makes the server fall back to
        // the floor, and a `0` would be an override that happens to say zero.
        if (el.dataset.wfov) {
          if (el.checked) sim[k] = tennoFloor()[el.dataset.wfov];
          else delete sim[k];
          renderSim();
          markScenarioDirty();
          return;
        }
        if (applyClassRule(el)) { renderSim(); return; }
        if (el.dataset.wfovnum) { sim[k] = Number(el.value); }
        else if (el.type === "checkbox") sim[k] = el.checked;
        else if (el.type === "number") sim[k] = Number(el.value);
        else sim[k] = el.value;
        // PICKING A FRAME FILLS ITS THREE NUMBERS. They stay editable after —
        // the roster is unmodded, so a built frame carries more armor and more
        // energy than any entry here, and one gate ("With Energy Max Over 700")
        // no frame can open at all. Writing the fields rather than replacing
        // them with a read-only display is what keeps that askable.
        if (k === "frame") {
          const f = frameOf(sim.frame);
          if (f) {
            // PICKING A FRAME IS AN OVERRIDE, so it TICKS the boxes as well as
            // filling them. Writing the numbers without the ticks would fill
            // four fields the fight then ignores, which is the worst of both.
            // (`health` is not in the frame roster yet — see data/frames.yaml —
            // so it is left to the floor rather than set to `undefined`.)
            if (f.health !== undefined) sim.wf_health = f.health;
            sim.wf_armor = f.armor;
            sim.wf_energy = f.energy;
            sim.wf_sprint = f.sprint;
          } else {
            // The BASELINE option clears the overrides rather than zeroing
            // them: back to the floor, which is what it names.
            delete sim.wf_health; delete sim.wf_armor;
            delete sim.wf_energy; delete sim.wf_sprint;
          }
        }
        // No `enemy` case here: the target is the picker's, not a field's, and
        // it repaints the arena through renderSim() like everything else.
        // A TENNO field changes what the BUILD is worth, not just what the
        // fight looks like — the panel resolves against the player now, so it
        // has to be asked again. The enemy half changes no panel number.
        if (TENNO_KEYS.includes(k)) refreshPanel();
        // ONLY the scenario. A build carries no copy of the fight, so a sim
        // knob does not dirty the build preset: this is the scenario's edit
        // and nobody else's.
        markScenarioDirty();
        // Whichever tab drew the field, both are looking at this one state.
        if (opts.after) opts.after();
      });
    }));
  // …AND THE FIGHT'S OWN STAT BONUSES, whose own map they write into. A
  // separate attribute rather than a `data-k` per stat because they are ONE
  // scenario field: nine numbers in one object, so a blank one is absent rather
  // than a zero nobody typed, and the share link carries only what was set.
  boxes.forEach((box) =>
    box.querySelectorAll("[data-xk]").forEach((el) => {
      el.addEventListener("change", () => {
        const next = { ...(sim.extra_stats || {}) };
        // TYPED IN PERCENT, stored as the fraction every bucket in the engine
        // holds — the same units a mod's `rankMax` is in.
        const v = Number(el.value) / 100;
        if (!Number.isFinite(v) || v === 0) delete next[el.dataset.xk];
        else next[el.dataset.xk] = v;
        sim.extra_stats = next;
        // It changes what the BUILD is worth, so the panel has to be asked
        // again — the same reason a Tenno field does.
        refreshPanel();
        markScenarioDirty();
        if (opts.after) opts.after();
      });
    }));
}

// WHAT THE WARFRAME BRINGS: the squad's AURA and the frame's ARCHON SHARDS.
//
// Neither is the weapon's and neither is the build's, which is why they are
// drawn inside the wielder block and travel with the FIGHT — the same place
// and the same reason as the ability buffs. An aura can no more reach the
// board than Roar can.
//
// THEY ARE OFFERED, NEVER TYPED. The Extra stats grid above already accepts any
// number a player wants into any bucket; what it cannot do is say WHERE the
// number came from. A named shard has a source that can be checked against the
// wiki and updated when DE moves it; a typed +45% has nothing behind it.
const AURAS = () => (META && META.auras) || [];
const SHARDS = () => (META && META.shards) || [];
// FIVE SOCKETS. The frame has five and no amount of anything adds a sixth.
const SHARD_SLOTS = 5;
// A SOCKET IS ONE CHOICE, not two. `shard/effect` in one dropdown, grouped by
// colour, because "which colour" is never the question a player has — they know
// the effect they want and the colour follows from it.
const shardKey = (x) => `${x.shard}/${x.effect}`;

// WHY AN AURA IS GREY, said on the row that OFFERS it rather than after it is
// picked. The amp family is the whole reason: three of them are gated on a mod
// POOL and Dead Eye on a CLASS, so "this is a rifle, why is Dead Eye dead" is a
// question the list has to answer where it is asked.
const paidHint = (a, paid) => (paid.has(a.id) ? null : tr("pays this weapon nothing"));

// THE NUMBER IS PRINTED, NOT TRANSLATED. A card reads "+25% (+37.5%)" and the
// bracket is the TAUFORGED value, which is how both the wiki and the game
// present it — so a value DE moves costs zero translation, and the pair is
// visible before the checkbox is ticked.
const shardValue = (o) => {
  const f = (v) => (o.unit === "pct" ? `${r3(v * 100)}%` : String(r3(v)));
  return `+${f(o.value)} (+${f(o.tauforged)})`;
};

function shardItems() {
  const out = [];
  SHARDS().forEach((d) => d.options.forEach((o) => out.push({
    value: `${d.id}/${o.id}`,
    label: `${shardValue(o)} ${LN("shards", `${d.id}/${o.id}`, o.text)}`,
    group: LN("shards", d.id, d.name),
    // WHAT IT PAYS HERE, on the row, because twenty of the twenty-seven pay
    // nothing in this arena and a socket that quietly does nothing is worse
    // than one that says so.
    hint: o.modelled ? null : `${tr("not modelled")} — ${tr(o.why_not || "")}`,
  })));
  return out;
}

const shardOption = (key) => {
  const [sid, eid] = String(key || "").split("/");
  const d = SHARDS().find((x) => x.id === sid);
  return d && d.options.find((o) => o.id === eid);
};

function renderSquad(host, w, sim, opts) {
  const box = $(host);
  if (!box || !META) return;
  const auras = sim.auras || [];
  const shards = sim.shards || [];
  // WHICH AURAS PAY THIS WEAPON is the ENGINE's answer, served per weapon — the
  // amp family does not share one gate, so nothing here re-derives it.
  const paid = new Set((w && w.auras) || []);
  const taken = new Set(auras.map((a) => a.id));

  const auraRow = (a, i) => {
    const d = AURAS().find((x) => x.id === a.id);
    if (!d) return "";
    const pays = paid.has(d.id);
    return `<div class="sq-row${pays ? "" : " sq-dead"}">
      ${ddButton(`sq-aura-${i}`, {
        value: d.id, data: { sqaura: i }, search: true,
        items: AURAS().filter((x) => x.id === d.id || !taken.has(x.id))
          .map((x) => ({ value: x.id, label: LN("auras", x.id, x.name),
            hint: paidHint(x, paid) })),
      })}
      ${d.squad_stacking
        ? `<label class="sq-n" title="${escHtml(tr("how many of the squad are running it — Corrosive Projection reaches 72% four-handed"))}">&times;<input type="number" min="1" max="4" step="1" value="${a.count || 1}" data-sqcount="${i}"></label>`
        : `<span class="sq-n sq-mute" title="${escHtml(tr("this aura does not stack with itself across the squad"))}">&times;1</span>`}
      <button type="button" class="ghost-btn small" data-sqdrop="${i}" title="${escHtml(tr("remove"))}">&#10005;</button>
      ${pays ? "" : `<span class="sq-why">${escHtml(tr("pays this weapon nothing"))}</span>`}
    </div>`;
  };

  const shardRow = (x, i) => {
    const o = shardOption(shardKey(x));
    return `<div class="sq-row${o && !o.modelled ? " sq-dead" : ""}">
      ${ddButton(`sq-shard-${i}`, {
        value: shardKey(x), data: { sqshard: i }, search: true, items: shardItems(),
      })}
      <label class="check sq-tau" title="${escHtml(tr("a TAUFORGED shard of the same colour grants 50% higher stat bonuses"))}"><input type="checkbox" data-sqtau="${i}"${x.tauforged ? " checked" : ""}> ${escHtml(tr("Tauforged"))}</label>
      <button type="button" class="ghost-btn small" data-sqshdrop="${i}" title="${escHtml(tr("remove"))}">&#10005;</button>
      ${o && !o.modelled ? `<span class="sq-why">${escHtml(tr(o.why_not || ""))}</span>` : ""}
    </div>`;
  };

  const free = AURAS().filter((x) => !taken.has(x.id));
  box.innerHTML = `
    <div class="sq-h">${escHtml(tr("Squad aura"))} <span class="sim-hint">${escHtml(tr("the squad's mod — it is the fight's, never the build's, so it cannot reach the board"))}</span></div>
    ${auras.map(auraRow).join("") || `<div class="sq-none">${escHtml(tr("none — nobody in the squad is running an aura"))}</div>`}
    ${free.length ? `<div class="sq-add">${ddButton("sq-aura-add", {
      value: "", placeholder: `+ ${tr("add an aura")}`, search: true, data: { sqadd: "1" },
      items: free.map((x) => ({ value: x.id, label: LN("auras", x.id, x.name),
        hint: paidHint(x, paid) })),
    })}</div>` : ""}
    <div class="sq-h">${escHtml(tr("Archon shards"))} <span class="sim-hint">${escHtml(tr("five sockets on your Warframe — a Tauforged shard of the same colour is worth half again"))}</span></div>
    ${shards.map(shardRow).join("") || `<div class="sq-none">${escHtml(tr("none — the sockets are empty"))}</div>`}
    ${shards.length < SHARD_SLOTS ? `<div class="sq-add">${ddButton("sq-shard-add", {
      value: "", placeholder: `+ ${tr("socket a shard")} (${shards.length}/${SHARD_SLOTS})`,
      search: true, data: { sqshadd: "1" }, items: shardItems(),
    })}</div>` : `<div class="sq-none">${escHtml(tr("all five sockets are filled"))}</div>`}`;

  if (opts && opts.readonly) {
    box.querySelectorAll("button,input").forEach((el) => {
      el.disabled = true;
      el.title = tr("edit this in the Simulator");
    });
    return;
  }
  // A CHANGE HERE IS A CHANGE TO THE FIGHT, and to what the BUILD is worth — an
  // aura lands in the base-damage bucket beside Serration and a shard in the
  // crit one — so the panel is asked again exactly as a Tenno field does.
  const touched = () => {
    renderSquad(host, w, sim, opts);
    refreshPanel();
    markScenarioDirty();
    if (opts && opts.after) opts.after();
  };
  const num = (el, k) => {
    const i = Number(el.dataset[k]);
    return Number.isFinite(i) ? i : -1;
  };
  box.querySelectorAll("[data-sqaura]").forEach((el) => el.addEventListener("change", () => {
    const i = num(el, "sqaura");
    if (i >= 0 && sim.auras[i]) { sim.auras[i] = { ...sim.auras[i], id: el.value }; touched(); }
  }));
  box.querySelectorAll("[data-sqcount]").forEach((el) => el.addEventListener("change", () => {
    const i = num(el, "sqcount");
    // 1-4: a squad is four people, and a count of zero is the remove button.
    const n = Math.min(4, Math.max(1, Math.round(Number(el.value) || 1)));
    if (i >= 0 && sim.auras[i]) { sim.auras[i] = { ...sim.auras[i], count: n }; touched(); }
  }));
  box.querySelectorAll("[data-sqdrop]").forEach((el) => el.addEventListener("click", () => {
    sim.auras = auras.filter((_, k) => k !== num(el, "sqdrop"));
    touched();
  }));
  box.querySelectorAll("[data-sqadd]").forEach((el) => el.addEventListener("change", () => {
    if (!el.value) return;
    sim.auras = auras.concat([{ id: el.value, count: 1 }]);
    touched();
  }));
  box.querySelectorAll("[data-sqshard]").forEach((el) => el.addEventListener("change", () => {
    const i = num(el, "sqshard");
    const [shard, effect] = String(el.value).split("/");
    if (i >= 0 && sim.shards[i]) { sim.shards[i] = { ...sim.shards[i], shard, effect }; touched(); }
  }));
  box.querySelectorAll("[data-sqtau]").forEach((el) => el.addEventListener("change", () => {
    const i = num(el, "sqtau");
    if (i >= 0 && sim.shards[i]) { sim.shards[i] = { ...sim.shards[i], tauforged: el.checked }; touched(); }
  }));
  box.querySelectorAll("[data-sqshdrop]").forEach((el) => el.addEventListener("click", () => {
    sim.shards = shards.filter((_, k) => k !== num(el, "sqshdrop"));
    touched();
  }));
  box.querySelectorAll("[data-sqshadd]").forEach((el) => el.addEventListener("change", () => {
    if (!el.value || shards.length >= SHARD_SLOTS) return;
    const [shard, effect] = String(el.value).split("/");
    sim.shards = shards.concat([{ shard, effect, tauforged: false }]);
    touched();
  }));
}

// The unit's portrait, or NOTHING — never an empty box holding its place.
// `imgTag` renders a placeholder span when the src is null, which is right
// for a mod grid (the slots must stay aligned) and wrong here: an enemy with
// no art yet should read as a name, not as a name with a hole beside it.
const enemyImg = (en, cls) => {
  const src = IMG(en && en.image);
  return src ? `<img class="${cls}" src="${src}" alt="" onerror="this.style.display='none'"/>` : "";
};

// What a run against this unit does not account for (`unmodeled` in its data
// file). An Acolyte carries damage attenuation whose constants DE has never
// published, so the number this app reports against one is too HIGH — that is
// a thing to say on the card, not a thing to leave the reader to discover.
const enemyCaveat = (en) => {
  const gaps = (en && en.unmodeled) || [];
  return gaps.length
    ? `<span class="en-gap" title="${escHtml(tr("the sim does not model this yet, so its number against this target is optimistic"))}">⚠ ${
        escHtml(tr("not modeled") + ": " + gaps.map((g) => tr(g)).join(", "))}</span>`
    : "";
};

// What this unit takes MORE and LESS of — the post-U36 faction column
// (`FactionDamageOverride ?? Faction`), which is half of what picks a build's
// elements. Its own line, not another entry in the meta run-on: a reader
// scanning for "what do I bring" should find it in one place, and up and down
// have to look different at a glance. A unit with a neutral column shows
// nothing at all — no line is the honest rendering of "takes damage as
// written", and an empty "Vulnerabilities:" label would not be.
const enemyVuln = (en) => {
  // What to BRING before what to avoid: the server sends them in damage-type
  // order, which interleaves the two answers.
  const mods = [...((en && en.type_modifiers) || [])].sort((a, b) => b.mult - a.mult);
  return mods.length
    ? `<span class="en-vuln" title="${escHtml(tr("this unit's faction takes more or less of these damage types, whatever its armor and shields do"))}">${
        mods.map((m) => `<span class="${m.mult > 1 ? "up" : "dn"}">${escHtml(DT(m.type))} ×${escHtml(String(m.mult))}</span>`).join("")}</span>`
    : "";
};

// WHAT CANNOT BE PROC'D ON IT, which is a different line because it is a
// different mechanic. A vulnerability says what a hit DEALS; a status immunity
// says what it PROCS, and it moves the whole distribution rather than the one
// entry — the immune type leaves the denominator and the others take over its
// share of the roll (wiki `Status_Effect` §Status Immunity Interactions). A
// reader who saw only "Heat ×0" would conclude the Heat procs stopped too, and
// they did not.
const enemyStatusImmune = (en) => {
  const im = (en && en.status_immunities) || [];
  return im.length
    ? `<span class="en-vuln" title="${escHtml(tr("these procs cannot land on this unit — the other damage types take over their share of the status roll"))}">${
        im.map((k) => `<span class="dn">${escHtml(DT(k))} ⃠</span>`).join("")}</span>`
    : "";
};

/// …AND THE THIRD LINE, which is neither of the two above. The proc LANDS, and
/// what it does is nothing.
///
/// It has to be its own line because the arithmetic differs: an immune type
/// leaves the status roll and makes every other type MORE likely, while this
/// one keeps its share of the roll and still counts as a type for Condition
/// Overload. Showing them together would tell a reader the opposite of both.
///
/// `cannot_be_frozen` rides here for the same reason and reads the other way —
/// Cold is worth MORE on such a unit, because the ladder never spends itself.
const enemyEffectsNulled = (en) => {
  const out = [];
  const nn = (en && en.nullified_status_effects) || [];
  if (nn.length) {
    out.push(`<span class="en-vuln" title="${escHtml(
      tr("these procs still land and still count for Condition Overload — this unit simply ignores what they do"))}">${
      nn.map((k) => `<span class="dim">${escHtml(DT(k))} ${escHtml(tr("no effect"))}</span>`).join("")}</span>`);
  }
  if (en && en.cannot_be_frozen) {
    out.push(`<span class="en-vuln" title="${escHtml(
      tr("Cold never converts on this unit, so the stacks climb to their cap and STAY — the bonus is up all fight instead of being spent on a 3-second Frozen window"))}">${
      `<span class="up">${escHtml(tr("never Frozen — Cold stacks hold"))}</span>`}</span>`);
  }
  return out.join("");
};

// THE POOLS AT THE FIGHT'S LEVEL, from the engine.
//
// A unit's OWN base level — a Corrupted Heavy Gunner as "700 Health · 500
// Armor" — is a number nobody fights: the scenario runs at 9999 Steel Path,
// where the same unit is millions of health and the armour figure has stopped
// meaning what
// the raw number suggests. Choosing a target on those is choosing on the wrong
// axis.
//
// Fetched, not computed here: the level curves belong to the engine and a
// second implementation in JavaScript is a second answer waiting to drift.
// Keyed on the two inputs, so it costs one call per level change and nothing
// per repaint.
let targetStats = { key: null, by: {} };
async function loadTargetStats() {
  const key = `${sim.level}|${sim.steel_path ? 1 : 0}`;
  if (targetStats.key === key) return false;
  const r = await api("/api/targets", { level: sim.level, steel_path: sim.steel_path });
  if (!r || !r.targets) return false;
  const by = {};
  r.targets.forEach((t) => { by[t.id] = t; });
  // Written together with the key: a half-applied cache would serve one
  // level's numbers under another's label.
  targetStats = { key, by };
  return true;
}

// Repaint the target cards' meta line IN PLACE when the numbers land.
//
// Not a re-render: the renderer is what asked for them, so calling it back
// would recurse. One line of text is the whole difference the answer makes,
// and both tabs draw the same card from the same state, so both are patched
// by one selector.
function paintTargetMeta() {
  const en = allEnemies().find((e) => e.id === sim.enemy);
  if (!en) return;
  document
    .querySelectorAll("#sim-target .en-meta, #opt-target .en-meta")
    .forEach((el) => { el.textContent = enemyMeta(en); });
}

// What the target card says under the name. The enemy's own facts, plus what
// it is MADE OF at the level this fight runs at.
function enemyMeta(en) {
  if (!en) return "";
  const bits = [];
  if (en.faction && en.faction !== "unknown") bits.push(tr(cap1(en.faction)));
  // The pools a build has to get through. AT THE FIGHT'S LEVEL when the engine
  // has told us (`loadTargetStats`), falling back to the unit's base numbers
  // before that answer arrives — never a mix of the two, because a row reading
  // "4.9M Health · 500 Armor" would be a lie about both.
  const at = targetStats.by[en.id];
  const src = at && !at.error ? at : en;
  const pools = [
    src.health ? `${Math.round(src.health).toLocaleString()} ${tr("Health")}` : null,
    src.shield ? `${Math.round(src.shield).toLocaleString()} ${tr("Shield")}` : null,
    src.armor ? `${Math.round(src.armor).toLocaleString()} ${tr("Armor")}` : null,
    src.overguard ? `${Math.round(src.overguard).toLocaleString()} ${tr("Overguard")}` : null,
  ].filter(Boolean);
  if (pools.length) {
    // SAY WHICH LEVEL, always. The same list of numbers means something
    // completely different at 9999 than at the unit's base level, and the
    // fallback above can serve either — so the label is not decoration, it is
    // what makes the row readable.
    // "Lv" stays untranslated, the way every other level label in the app is.
    const lv = src === en
      ? `Lv ${en.base_level ?? 1}`
      : `Lv ${sim.level}${sim.steel_path ? " SP" : ""}${at.eximus ? ` ${tr("Eximus")}` : ""}`;
    bits.push(`${lv}: ${pools.join(" · ")}`);
    // What the armour is WORTH — at these levels the raw figure says little
    // and the reduction it buys says everything.
    if (src !== en && at.armor_dr > 0) {
      bits.push(`${Math.round(at.armor_dr * 1000) / 10}% ${tr("damage reduction")}`);
    }
  }
  const head = (en.parts || []).find((p) => p.is_head);
  if (head) bits.push(`${tr("Headshot")} ×${head.multiplier}`);
  // The bare word "Eximus" is now a claim about WHAT YOU ARE SHOOTING and is
  // made above, beside that variant's own pools — there is a switch for it and
  // it defaults on. This line stays only for the case the numbers have not
  // arrived yet, where nothing else would mention the variant at all.
  if (en.can_be_eximus && !targetStats.by[en.id]) bits.push(tr("has an Eximus variant"));
  return bits.join(" · ");
}

// THE TARGET PICKER — the same component as the mod and arcane pickers, on
// the same rule: search matches anything the reader can see. One enemy in the
// roster today, so this is the shape the roster grows into rather than a
// convenience over a two-item list.
function openEnemyPicker(anchor) {
  closePopovers();
  const pop = $("enemy-popover");
  place(pop, anchor);
  const search = $("enemy-search");
  search.value = "";
  search.oninput = () => renderEnemyMenu(search.value);
  renderEnemyMenu("");
  search.focus();
  // Then again with the real numbers. Drawn twice rather than awaited, so the
  // menu opens at once on a cold cache instead of after a round trip — and the
  // first pass is honest either way, because it labels the base level it is
  // actually showing.
  loadTargetStats().then(() => {
    if (pop.classList.contains("open") || pop.style.display !== "none") {
      renderEnemyMenu(search.value);
    }
  });
}

function renderEnemyMenu(query) {
  const menu = $("enemy-menu");
  const q = (query || "").trim().toLowerCase();
  const blob = (e) => [e.name, e.name_en, e.id, e.faction, e.scaling]
    .filter(Boolean).join(" ").toLowerCase();
  const hits = allEnemies().filter((e) => !q || blob(e).includes(q));
  menu.innerHTML = hits.length
    ? hits.map((e) => `<div class="opt ${e.id === sim.enemy ? "sel" : ""}" data-e="${escHtml(e.id)}">
         ${enemyImg(e, "en-thumb")}
         <div class="info"><div class="mn">${escHtml(e.name)}</div>
         <div class="me">${escHtml(enemyMeta(e))}</div>${enemyVuln(e)}${enemyStatusImmune(e)}${enemyEffectsNulled(e)}${enemyCaveat(e)}</div>
       </div>`).join("")
    : `<div class="sim-empty">${escHtml(tr("no enemy matches"))}</div>`;
  menu.querySelectorAll("[data-e]").forEach((el) => el.onclick = () => {
    sim.enemy = el.dataset.e;
    // An explicit "yes, Eximus" cannot follow you onto a unit that has no
    // Eximus variant — the fight would be refused. Dropping it back to null
    // hands the new target its OWN default, which is the elite one wherever
    // there is one. An explicit "no" is legal everywhere and is kept.
    const picked = allEnemies().find((e) => e.id === sim.enemy);
    if (sim.eximus === true && !(picked && picked.can_be_eximus)) sim.eximus = null;
    closePopovers();
    markPresetDirty(); markScenarioDirty();
    renderSim();
    if ($("opt-target")) renderOptEnemy();
  });
}

// Which forms this weapon offers, and the reseed when it does not offer the
// one currently chosen.
//
// The FORMS are the weapon's own (registered in data/weapons, served by
// /api/meta) — not a hardcoded Incarnon triple. The two-form CYCLE is not a
// form but a MODE over them, so it is listed first and only when the weapon
// has something to transform into (`has_cycle`). A weapon with one form and
// no cycle has nothing to choose, so no selector is drawn.
//
// The cycle is offered — and defaulted to — whenever the WEAPON has one,
// installed perk or not. It stays honest because the sim
// falls back to the base form when the unlock is missing, and it stays
// STABLE, which is the point: re-seeding the choice every time tier 1 is
// touched would move the selection under someone who had already made it.

// THERE IS NO ACTOR STRIP: Tenno and enemy markers on a bar are meaningless
// beside a drawn fight. A dot, a lane and a portrait stand in for a fight the
// page cannot draw — and the page draws the fight, at
// the engine's own scale, with every body in it. Two pictures of one fight is
// one too many, and the strip was the one that could not be edited, could not
// be measured off, and showed one enemy however many were standing there.
//
// The enemy's identity did not go with it: it is on the brush card in the
// scene (which is where you pick it) and in the result panel's own copy.


// ---- WARFRAME ABILITY BUFFS (scenario section 3) ------------------------
//
// EARLY ACCESS, and the block says so on screen. Today
// you type an Ability Strength; when frames land it comes from the frame and
// the duration from Ability Duration. Nothing else about these buffs changes
// then, which is why the definitions live in `data/abilities/` and only their
// two INPUTS are here.
//
// It is the SCENARIO's, not the build's: a thing done TO this weapon for a
// while. That is what puts it in section 3 beside the wielder, what carries it
// into the optimizer read-only, and what keeps it off the board — a board row
// is a statement about the weapon, and no ruler casts Roar.
const wfAbilities = () => (META && META.abilities) || [];
// DE'S OWN NAME for the ability, never a translation of ours (the house rule).
// The FRAME keeps its English name because DE's Chinese client does too.
const wfName = (a) => ((I18N && I18N.abilities) || {})[a.id] || a.name;
const wfPick = (id) => (sim.abilities || []).find((a) => a.id === id);
// The strength-scaled value, which is the number the card shows. Linear, and
// the engine agrees by construction: `abilities_data::at_strength` is the same
// multiply, and `check_wf_buffs.mjs` asserts the screen and the sim match.
// …AND THE ONES THE KNOB DOES NOT MOVE. Energized Munitions' ammo efficiency is
// a flat 75% — its wiki row carries no Ability Strength icon — so multiplying it
// here would print a number the game never gives, at every strength but 100%.
// The server states which per ability (`scales_with_strength`), so the page
// cannot disagree with the sim about it.
const wfValue = (a) =>
  a.value * (a.scales_with_strength === false ? 1 : (Number(sim.ability_strength) || 0));

// WHICH PICKS ARE ACTUALLY RUNNING. Same family, only the strongest — the
// wiki's own rule ("Multiple Freeze Forces do not stack; the buff with the
// highest Ability Strength will take effect") and the owner's ask for Roar vs
// Roar (Helminth). Computed here TOO, rather than only in the engine, because
// a page that showed both as active would be lying about a number it printed.
function wfRunning() {
  const best = new Map();
  for (const p of sim.abilities || []) {
    const def = wfAbilities().find((a) => a.id === p.id);
    if (!def) continue;
    const cur = best.get(def.family);
    if (!cur || wfValue(def) > wfValue(cur)) best.set(def.family, def);
  }
  return new Set([...best.values()].map((a) => a.id));
}

// WHAT IT IS WORTH, at the strength you set — the number, on its own, big
// enough to read. A catalogue that showed only the
// ability's name would make you do the multiply the sim is doing. THE ELEMENT
// THIS BUFF IS ACTUALLY SET TO — the picked one where the ability
// offers a choice (Resupply's gear wheel of ten), its own otherwise.
const wfElement = (a) => {
  const p = wfPick(a.id);
  return (p && p.element) || a.element;
};
// `DT` is the one place a damage type is named, and it reads the locale:
// reaching into META instead prints `corrosive` on a Chinese page.
const wfElementName = (id) => DT(id);

function wfValueLabel(a) {
  const pct = Math.round(wfValue(a) * 1000) / 10;
  if (a.kind === "add_element" || a.kind === "extra_hit") {
    return `+${pct}% ${wfElementName(wfElement(a))}`;
  }
  return `+${pct}%`;
}

// …and WHERE it lands, which is the half a number cannot say. Two buffs both
// reading "+50%" are worth different amounts on a DoT weapon, and this line is
// the difference.
function wfEffectLine(a) {
  if (a.kind === "faction_damage") {
    return tr("faction damage — the bracket a Bane mod is in, so a status tick takes it twice");
  }
  if (a.kind === "final_damage") {
    return tr("damage on its own multiplier — applied once, to the hit and to the status alike");
  }
  // AN EXTRA HIT IS NOT A MULTIPLIER, and the line has to say so or the card
  // reads as "+26% damage" — which is not what it is worth. It is a second
  // damage instance, so it takes the faction bonus and the headshot multiplier
  // a SECOND time, and 26% on the card is more like 40% on the number.
  if (a.kind === "extra_hit") {
    return tr("a second damage instance, not a multiplier — it takes faction damage and the headshot multiplier one more time than the hit it copies");
  }
  // NOT A DAMAGE BRACKET AT ALL. What it buys is reloads not taken, so on a
  // weapon that never reloads it is worth nothing and the line has to say
  // where to look instead of implying a damage number.
  if (a.kind === "ammo_efficiency") {
    return tr("ammo efficiency — it does not touch damage: it divides what a shot costs the magazine, so what it buys is reloads not taken. Multiplicative with other ammo-efficiency sources");
  }
  return tr("added on top and NOT combined with the weapon's own elements");
}

function renderWfBuffs(host, readonly) {
  const box = $(host);
  if (!box) return;
  const list = wfAbilities();
  if (!list.length) { box.innerHTML = ""; return; }
  const running = wfRunning();
  const strength = Math.round((Number(sim.ability_strength) || 0) * 100);
  // THE TARGET GETS A SAY. A Demolisher pulses every 5 s and dispels every
  // Warframe ability in range — so against one, nothing ticked here is up, and
  // the sim scores it that way. A section that let you tick Roar and quietly
  // ignored it would be the worst kind of wrong: a number you cannot explain.
  const nulled = (allEnemies().find((e) => e.id === sim.enemy) || {}).nullifies_abilities;
  const rows = list.map((a) => {
    const pick = wfPick(a.id);
    const on = !!pick;
    // SUPERSEDED, not off: you ticked it and something stronger is running.
    // Saying nothing here is how a player ends up believing they have +80%.
    const dead = on && !running.has(a.id);
    return `<div class="wfb${on ? " on" : ""}${(dead || (on && nulled)) ? " dead" : ""}">
      <label class="check wfb-pick"><input type="checkbox" data-wf="${escHtml(a.id)}"${on ? " checked" : ""}${readonly ? " disabled" : ""}>
        <span class="wfb-n">${escHtml(wfName(a))}</span>
        <span class="wfb-f">${escHtml(tr(a.frame))}</span></label>
      <div class="wfb-v">${escHtml(wfValueLabel(a))}</div>
      ${/* A CHOSEN ELEMENT, where the ability offers one. Drawn from the data's
            own list in the game's own order, so the day a member gains or loses
            a choice this follows without being told. */ ""}
      ${(a.elements || []).length
        ? `<label class="wfb-el" title="${escHtml(tr("this ability lets you pick the element — the gear wheel in game"))}">${
            escHtml(tr("element"))} ${ddButton(`wfel-${a.id}`, {
            value: wfElement(a),
            items: a.elements.map((e) => ({ value: e, label: wfElementName(e) })),
            // THE SAME HANDLER, because `ddButton` reflects `value` on the
            // button and fires `change` — which is what let every other native
            // select on this page be swapped without touching its wiring.
            data: { wfel: a.id },
            disabled: !on || readonly,
          })}</label>`
        : ""}
      <div class="wfb-e">${escHtml(wfEffectLine(a))}</div>
      ${/* WHAT IT DOES NOT DO, in the same chips a mod and an arcane card use —
            `notModeledLines` reads `unmodeled_effects` and `live_bugs` off any
            object, and an ability publishes both under those names. The owner
            debugs by reading the card, so a Bullet Attractor this sim has
            nothing to point at has to say so HERE. */ ""}
      <div class="wfb-u">${notModeledLines(a).join("")}</div>
      ${dead ? `<div class="wfb-dead">${escHtml(tr("a stronger buff of the same kind is running — this one adds nothing"))}</div>` : ""}
      ${on && nulled ? `<div class="wfb-dead">${escHtml(tr("this target dispels it — nothing ticked here is running against it"))}</div>` : ""}
      ${a.url ? `<a class="wfb-w" href="${escHtml(a.url)}" target="_blank" rel="noopener">${escHtml(tr("wiki"))} ↗</a>` : ""}
    </div>`;
  }).join("");
  const sub = $(host === "sim-wfbuffs" ? "wfbuff-sub" : "");
  if (sub) {
    sub.textContent = nulled
      ? tr("none — this target dispels them")
      : running.size
        ? `${running.size} ${tr("running")}`
        : tr("none — the weapon on its own");
  }
  box.innerHTML =
    `<div class="wfb-head">
       <label title="${escHtml(tr("your Warframe's Ability Strength, as the arsenal shows it — every value below is this times the wiki's max-rank number"))}">${escHtml(tr("Ability Strength %"))}
         <input type="number" id="${host}-str" min="0" max="1000" step="1" value="${strength}"${readonly ? " disabled" : ""}></label>
       <span class="wfb-early">${escHtml(tr("early access — every buff runs the whole engagement for now, and this block moves onto the Warframe itself once frames land"))}</span>
     </div>
     ${nulled ? `<div class="wfb-null">${escHtml(
        tr("this target nullifies Warframe abilities — it pulses every 5 seconds and dispels everything in range, so none of these are running and the sim scores it that way"))}</div>` : ""}
     <div class="wfb-grid">${rows}</div>`;
  if (readonly) {
    box.querySelectorAll("input").forEach((el) => {
      el.disabled = true;
      el.title = tr("edit this in the Simulator");
    });
    return;
  }
  const touched = () => { markScenarioDirty(); renderSim(); };
  const str = $(`${host}-str`);
  if (str) str.addEventListener("change", () => {
    sim.ability_strength = Math.max(0, Number(str.value) || 0) / 100;
    touched();
  });
  box.querySelectorAll("[data-wfel]").forEach((el) => el.addEventListener("change", () => {
    const p = wfPick(el.dataset.wfel);
    if (p) p.element = el.value;
    touched();
  }));
  box.querySelectorAll("[data-wf]").forEach((el) => el.addEventListener("change", () => {
    const id = el.dataset.wf;
    sim.abilities = (sim.abilities || []).filter((a) => a.id !== id);
    // TICKING IT OPENS IT AT THE WIKI'S OWN DURATION, not at "whole fight":
    // the honest default for "I cast Roar" is one Roar, and the whole-fight
    // box is the deliberate other question.
    // `secs: null` = the whole engagement. The only thing the page offers
    // today, and the honest question to ask of a build: what is this weapon
    // worth UNDER the buff, rather than around it.
    if (el.checked) {
      const def = wfAbilities().find((a) => a.id === id);
      // AN EXPLICIT ELEMENT from the first tick, where there is a choice: a
      // pick that omits it is answered by the definition's first entry, and a
      // player reading the card should see the same thing the sim runs.
      const first = def && (def.elements || [])[0];
      sim.abilities.push(first ? { id, secs: null, element: first } : { id, secs: null });
    }
    touched();
  }));
}

/// THE RUN COUNT, on its own — the page's, not the fight's.
///
/// GLOBAL, and it stays put: switching weapons, switching fights and opening an
/// OFFICIAL ruler all leave it alone, because how long you are willing to wait
/// is not one of a board fight's terms. The METRIC is the opposite and sits in
/// the block above — KPM is a term of the scenario, so a ruler pins it.
/// THE BUILDER'S STEP NUMBERS, recomputed from what is on screen.
///
/// A block whose axis this weapon does not have is hidden, and the visible ones
/// are then 1..n in document order. Only badges that are already a NUMBER are
/// touched: `Σ`, `≡` and `▶` mark panels that are not steps in the build and
/// say so by not being counted.
/// The BUILDER's blocks, in document order — DERIVED, never listed.
///
/// A list of ids is the right answer to the wrong question: `.config-page` also
/// holds the Sim, Rivens, Enemies and Optimizer pages, so a sweep over `.block`
/// renumbers the Rivens editor as step 5 of building a gun. What needs saying
/// is which MODULE a block belongs to, and once every block says it
/// (`data-module`) this, the CSS and the official-build lock are one query —
/// where four hand lists left the Parts block out of all of them.
const builderBlocks = () => [...document.querySelectorAll('[data-module="builder"]')];

/// …and of those, the ones that are a STEP rather than a read-out.
///
/// The badge already says which, and `renumberBlocks` already reads it: a step
/// carries a NUMBER, while `Σ`, `≡` and `▶` mark panels that only report. So
/// the lock derives from the same fact the numbering does, instead of naming
/// four blocks and going stale on the fifth.
const builderSteps = () => builderBlocks().filter((b) => {
  const n = b.querySelector(".bh .n");
  return !!n && /^\d+$/.test(n.textContent.trim());
});

function renumberBlocks() {
  let n = 0;
  // THE STEPS, not every builder block — see `builderSteps`. The doc above has
  // always said "only badges that are already a NUMBER are touched", and the
  // code never did: it was true because the LIST left the read-outs out. Derive
  // the list and the claim has to be implemented, which is how the Stats
  // panel's `Σ` came back as "5" the first time this was a query
  // (caught by check_valence, 2026-08-24).
  builderSteps().forEach((b) => {
    if (b.hidden) return;
    b.querySelector(".bh .n").textContent = String(++n);
  });
}

function renderSimRuns() {
  const box = $("sim-runs-block");
  if (!box) return;
  box.innerHTML =
    `<label title="${escHtml(tr("how many times to replay this fight HERE. Not part of the scenario: it follows you across fights and weapons, and an official ruler does not pin it. The boards themselves are scored at 1,000 by the server whatever this says"))}">${
      escHtml(tr("Runs"))} <input type="number" id="sim-runs-input" min="1" max="20000" step="10" value="${simRuns()}"></label>` +
    `<span class="sim-hint">${escHtml(tr("yours, not the fight's — the boards score at 1,000"))}</span>`;
  const el = $("sim-runs-input");
  el.addEventListener("change", () => {
    setSimRuns(el.value);
    el.value = String(simRuns());
  });
}

function renderSim() {
  if (!META) return;
  renderSimBuild();
  const enemies = allEnemies();
  const en = enemies.find((e) => e.id === sim.enemy) || enemies[0];
  renderScenarioFields({ target: "sim-target", technique: "sim-technique",
    limits: "sim-limits", extra: "sim-extra", run: "sim-run", squad: "sim-squad" });
  renderSimRuns();
  renderWfBuffs("sim-wfbuffs", false);
  // …AND THE OPTIMIZER'S COPY, from the same call. It shows the SIMULATOR's
  // fight, so it is repainted whenever that fight is redrawn rather than when
  // its own tab happens to be entered — a tab that repaints only on arrival
  // shows the buffs you had when you last arrived.
  renderWfBuffs("opt-wfbuffs", true);
  renderScenarioBar();
  $("sim-sub").textContent = "current build vs the enemy";
  renderSimBuffs();
  lockOfficialScenario();
  renderBoardConsent();
  refreshBoardDoor();
}

// ---- THE BOARD: consent, then submission -------------------------------
//
// WHEN THE ASK HAPPENS, and why it is here rather than on load: the first time
// you finish a run under the OFFICIAL scenario. Only then is there any context
// for the question — a score is on screen and "should this build go on the
// board" is a sentence that means something. Asking at startup would be a
// modal before you have done anything, which is a dialog people click away
// rather than a disclosure. (It is also inline: `prompt`/`alert`/`confirm` are
// blocked in this project.)
//
// WHAT TRAVELS, stated because it is short enough to check: the weapon, its
// mods, evolutions and arcanes, and which benchmark. No account, no
// identifier, no riven (they are out of the benchmark entirely), and none of
// the names you gave anything. NO SCORE either — the board scores builds
// itself, which is what makes a row reproducible and a forged number
// pointless.
const BOARD_CONSENT = "wfsim-board-consent";   // "yes" | "no" | absent = never chosen

// DEFAULT ON — and the important word is not "on", it is
// NOT SILENT. Opt-out versus opt-in is a policy choice the owner gets to make;
// silent versus stated is a trust choice, and the board's whole value is that
// its numbers are believable. One screenshot captioned "wfsim 偷偷上传你的配装"
// costs more than every submission it would ever gain.
//
// So the default is yes, and the line saying so is on screen from the moment
// the official scenario is active — before any run, with a one-click opt-out
// beside it. `check_official.mjs` asserts that pairing rather than asserting
// nothing leaves: what has to be true is that nothing leaves UNSAID.
const boardConsent = () => {
  try { return localStorage.getItem(BOARD_CONSENT) || "yes"; } catch (_) { return "yes"; }
};
/// Has the player actually decided, as against inheriting the default? Only
/// this tells the notice apart from the settled state.
const boardConsentChosen = () => {
  try { return localStorage.getItem(BOARD_CONSENT) !== null; } catch (_) { return false; }
};
// WHY the board turned this build away, in its own words. Kept beside
// `boardState` rather than inside it: the state is what happened, this is what
// was said, and only one of the states has anything to say.
let boardRefusal = "";
/// HOW MANY BOARDS TOOK IT, out of how many were asked. Null until a run has
/// asked — "sent" alone does not say whether it will be RANKED anywhere, which
/// is the question a submitter actually has.
let boardBoards = null;
const setBoardConsent = (v) => {
  try { localStorage.setItem(BOARD_CONSENT, v); } catch (_) { /* private mode */ }
  renderBoardConsent();
  refreshBoardDoor();
};

/// The submission itself: the BUILD, and nothing else about you.
/// The mod id a RIVEN takes in a board record — the bare word, because the
/// endpoint's ids are `[a-z0-9_]` and a riven's local name is one player's
/// label for their own item.
const BOARD_RIVEN_SLOT = "riven";

/// THE EQUIPPED RIVEN AS A SHAPE, for a board record: `{riven_pos, riven_neg}`,
/// or `{}` when the build wears none.
///
/// Two flat fields rather than an object, because that is the worker's shape —
/// it validates `id` and `ids` and has no game data to check anything richer
/// against. Spellings are per-protocol and always have been; what is shared is
/// the AXIS, which both fields name.
function boardRivenShape() {
  const slot = mainSlots().find((s) => isRivenId(s.mod));
  if (!slot) return { riven_pos: [], riven_neg: "" };
  const st = (loadPresetList(RIVENS).find(
    (p) => RIVEN_PREFIX + p.id === slot.mod) || {}).state || {};
  const ids = (xs) => (xs || []).map((x) => x && x.id).filter(Boolean);
  return {
    // SORTED, because a riven's stats do not combine with each other — two
    // players listing them in different orders described one riven and must
    // produce one row.
    riven_pos: ids(st.bonuses || st.positives).sort(),
    riven_neg: ((st.malus || st.curse) || {}).id || "",
  };
}

function boardPayload() {
  const bench = (scenarioNamed(activeScenario) || {}).builtin;
  return {
    // WHERE THE SUBMITTER HAPPENED TO BE STANDING — provenance, not identity. A submission has never carried a score, so the ruler
    // was never a property of the record; the store is a LIBRARY OF BUILDS and
    // every ruler crosses the whole of it. A build measured under a scenario of
    // the player's own has no ruler to name and simply omits the field.
    // `undefined`, not a conditional spread and not `null`: `JSON.stringify`
    // drops an undefined key, which is exactly "omit it on the wire", while the
    // key stays visible at this indentation to the cross-file check that reads
    // this literal against the worker's own table (`check_board_submit`). A
    // `null` would travel and the worker would refuse it as a non-string id.
    benchmark: bench || undefined,
    weapon: $("weapon").value,
    // HOW IT IS PLAYED, and it has to travel or the dimension is fed by
    // nothing. The scorer's fallback for a mode-less submission is "the cycle
    // where there is one", which is a MIGRATION rule for rows submitted before
    // the dimension existed — and while this field was missing it was the only
    // rule in play, so every Incarnon weapon's row said `cycle` and no board
    // could ever hold a base-form Torid. Measured on the published boards:
    // 62 cycle rows and 41 base ones, and not one weapon with both — every
    // Incarnon weapon cycle, every other one base, which is the fallback's
    // signature rather than anybody's choice.
    mode,
    // THE EIGHT MAIN SLOTS, and the exilus one is DROPPED here — it has to
    // happen on this side, because the payload is a flat list with no slot
    // positions and an exilus-eligible mod is legal in a MAIN slot. Sending all
    // nine turns away exactly the wrong people: a player who fills their exilus
    // slot sends 9 mods and is refused for not being a complete build.
    //
    // AS PLACED, not sorted: mods combine elements in the order they sit in,
    // so sorting here submits a build the player never made — on the Torid,
    // 12,424 DPS against 46,583. The scorer canonicalises with the pool in
    // front of it, the only place that knows an elemental mod.
    // THE RIVEN RIDES AT ITS OWN POSITION, under the bare id `riven`, because
    // position is the build: an elemental riven pairs with the build's other
    // elementals. The endpoint's ids are `[a-z0-9_]`, so its local name cannot
    // travel — and should not, being what one player called their item.
    // …AND THE STANCE RIDES WITH THEM, appended. It needs no field of its own
    // because a stance mod is legal in the stance slot and NOWHERE else, which
    // is what the exilus slot cannot say and why THAT one is its own key.
    // APPENDED RATHER THAN INSERTED, because the order of `mods` pairs the
    // elementals and a stance carries no element.
    mods: mainSlots()
      .filter((s) => s.mod)
      .map((s) => (isRivenId(s.mod) ? BOARD_RIVEN_SLOT : s.mod))
      .concat((slots[STANCE] || {}).mod ? [slots[STANCE].mod] : []),
    // …AND WHAT THAT SLOT HOLDS, as a SHAPE. Which stats, and which is the
    // malus — never the rolls: the board scores a shape at its own ceiling, the
    // same way it scores every row at full Forma and every valence at the
    // roll's maximum. What one copy landed on is luck.
    //
    // STATED EVEN WHEN EMPTY, like `valence` beside it: a payload that names
    // every axis is one a reader can check against the worker's table, and the
    // endpoint drops an empty one rather than storing it.
    riven_pos: boardRivenShape().riven_pos,
    riven_neg: boardRivenShape().riven_neg,
    evolutions: Object.values(evoSel).filter(Boolean),
    arcanes: arcanes.slice(),
    // THE PROGENITOR ELEMENT, for an adversary weapon. The ELEMENT only: the
    // ruler scores every row at the roll's maximum, so the percentage is not a
    // row's to state — every player can Valence-fuse to it, which makes it
    // investment rather than a choice (the same rule that scores every row at
    // full Forma).
    valence: valence.element,
    // THE EXILUS SLOT'S MOD, as its own field — optional on every ruler, and
    // sent rather than dropped here and never counted.
    //
    // IT HAS TO BE ITS OWN FIELD, which is the same reason it was dropped
    // rather than appended before: the payload's `mods` is a flat list with no
    // slot positions, and an exilus-eligible mod is legal in a MAIN slot, so
    // nothing downstream could tell which entry came out of the exilus slot.
    // Only the page knows, because only the page has the slots.
    //
    // WHY IT IS COUNTED NOW: "exilus mods are handling and mobility, with no
    // single-target damage model" was true of most of the pool and false of the
    // part that decides a group fight — BEAM RANGE is exilus, and beam range is
    // how many bodies a beam reaches.
    exilus: (slots[boardBuildMods()] || {}).mod || undefined,
    // THE PARTS of a modular weapon, flat, because that is the worker's shape.
    // Empty strings on everything else — the field is always sent so a record
    // written today and one written by a Kitgun submitter have the same keys,
    // and the scorer's own fallback never has to guess which kind it is looking
    // at.
    grip: (assembly && assembly.grip) || "",
    loader: (assembly && assembly.loader) || "",
  };
}

/// THE SAME PAYLOAD, FROM A SEARCH RESULT rather than from the page.
///
/// A FINALIST IS A BUILD AND THE BOARD TAKES BUILDS. A search that ranks twenty
/// of them uploaded NONE: the only path to the store ran off a simulator run,
/// one build at a time, so the strongest thing this app produces reached the
/// board only if a player copied a row into the builder by hand and ran it
/// again. Every axis below comes off the ROW — mods, arcanes, evolutions, mode,
/// valence, exilus — because the page's own state is a different build.
///
/// THE RIVEN AND THE ASSEMBLY COME FROM THE PAGE, and that is not an
/// inconsistency: the search was handed the riven the player defined and the
/// weapon they assembled, so those are the row's too. It has no separate answer
/// to give.
/// WHICH MOD CAME OUT OF THE EXILUS SLOT, said once for the two places that
/// need it — the list it must leave and the key it must arrive in.
const exilusOf = (res) =>
  (res && res.exilus && res.exilus !== "none" ? res.exilus : undefined);

function boardPayloadFromResult(res) {
  const bench = (scenarioNamed(activeScenario) || {}).builtin;
  const arcs = asArcaneList(res.arcane, (res.arcane || []).length)
    .filter((a) => a && a !== "none");
  return {
    benchmark: bench || undefined,
    weapon: $("weapon").value,
    mode: res.mode || mode,
    // AS RANKED, not sorted — the order pairs the elementals, and a sorted list
    // is a build the search never measured. The same rule `boardPayload` states.
    // THE EIGHT MAIN SLOTS, and the exilus one is DROPPED — the same rule
    // `boardPayload` states above, and it has to be stated twice because this
    // path builds its list from a RESULT rather than from the slots. A flat
    // list has no positions and an exilus-eligible mod is legal in a main slot,
    // so the endpoint reads a ninth entry as a ninth MAIN mod and refuses the
    // build for having nine. Which one it is, is `exilus` below.
    // …AND THE STANCE RIDES WITH THEM, the same rule `boardPayload` states. The
    // search is HANDED the builder's stance and pins it into every candidate,
    // so a result already names it — the append is for a result that predates
    // that (a saved checkpoint), and it is conditional so the same card cannot
    // arrive twice.
    mods: (() => {
      const st = (slots[STANCE] || {}).mod;
      const out = (res.mods || [])
        .filter((m) => !exilusOf(res) || m !== exilusOf(res))
        .map((m) => (isRivenId(m) ? BOARD_RIVEN_SLOT : m));
      return st && !out.includes(st) ? out.concat([st]) : out;
    })(),
    riven_pos: boardRivenShape().riven_pos,
    riven_neg: boardRivenShape().riven_neg,
    evolutions: (res.evolutions || []).slice(),
    arcanes: arcs,
    valence: res.valence || valence.element,
    exilus: exilusOf(res),
    grip: (assembly && assembly.grip) || "",
    loader: (assembly && assembly.loader) || "",
  };
}

/// EVERY FINALIST, THROUGH THE BOARD'S OWN DOOR.
///
/// NO CLIENT-SIDE PRE-FILTER, HERE OR ANYWHERE. A search result can be short —
/// how full a build must be is the searcher's own setting, and a seven-mod
/// scope produces seven-mod winners — and those are refused by
/// `/api/board/check`, which IS `validate_for_board` rather than a copy of it:
/// a second implementation is a second answer, and the player has to be given
/// the board's. The simulator's path asks the same door for the same reason.
///
/// NO CAP ON HOW MANY. The finalist count is the searcher's setting, they are
/// all real builds, and the store is keyed by identity — so twenty submissions
/// of which twelve are already held collapse onto twelve rows.
async function offerOptBoardSubmit(r) {
  const box = $("opt-board");
  if (!box) return;
  const rows = (r.results || []).filter((x) => x && (x.mods || []).length);
  if (!rows.length) return;
  if (boardConsent() !== "yes") {
    box.innerHTML = `<span class="ob-off">${escHtml(
      tr("board upload is off, so these were not sent"))}</span>`;
    return;
  }
  box.innerHTML = `<span class="ob-run">${escHtml(
    tr("sending {n} finalists to the board…").replace("{n}", rows.length))}</span>`;
  let sent = 0;
  const refused = new Map();
  let failed = 0;
  // ONE AT A TIME. The door is a real request and so is the store's; a search
  // with fifty finalists firing fifty of each at once is a burst nobody asked
  // for, and nothing here is waiting on the answer.
  for (const res of rows) {
    const body = boardPayloadFromResult(res);
    try {
      const verdict = await boardVerdict(body);
      if (verdict && verdict.ok && verdict.accepted === false) {
        const why = verdict.reason || tr("refused");
        refused.set(why, (refused.get(why) || 0) + 1);
        continue;
      }
      const ok = await fetch("/api/board/submit", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
      }).then((x) => x.ok).catch(() => false);
      if (ok) sent += 1; else failed += 1;
    } catch (_) {
      failed += 1;
    }
  }
  // AGGREGATE, because the reader asked one question and got twenty answers.
  // The REASONS are counted rather than listed: twenty rows off one search
  // differ in mods and not in why the board would not take them.
  const parts = [tr("{n} of {of} finalists uploaded")
    .replace("{n}", sent).replace("{of}", rows.length)];
  for (const [why, n] of refused) parts.push(`${n} × ${why}`);
  if (failed) parts.push(tr("{n} could not be sent").replace("{n}", failed));
  box.innerHTML = `<span class="${sent ? "ob-sent" : "ob-off"}">${
    escHtml(parts.join(" · "))}</span>`;
}

let boardState = "";   // "" | "sent" | "failed" | "onboard"
/// THE ROW THIS BUILD ALREADY IS, when it is one — a `builtinBuilds()` entry,
/// so it can be NAMED ("#1 · Incarnon cycle") rather than merely asserted.
let boardOnBoard = null;

/// How many mods a board build is, from the ENGINE via META — never a literal
/// here. The rule is `builds::validate_for_board`; this is the page repeating
/// what it was told so it can explain itself before sending nothing.
const boardBuildMods = () => (META || {}).board_build_mods || 8;
/// The slots a benchmark build is made of: the main ones. `slots` holds nine —
/// the exilus slot is the last — and the benchmark does not count it.
const mainSlots = () => slots.slice(0, boardBuildMods());
/// Filled main slots. The exilus slot is not part of the answer either way.
const buildMods = () => mainSlots().filter((s) => s.mod).length;

/// WHAT THE ACTIVE BENCHMARK ADMITS — its own `build` block, from META. Not a
/// constant here: admission is the benchmark's, so a second ruler answers
/// differently and this page must not assume otherwise.
const boardRequirement = () => {
  const id = (scenarioNamed(activeScenario) || {}).builtin;
  const b = (META.benchmarks || []).find((x) => x.id === id);
  return (b && b.build) || {};
};

/// WHAT THE BOARD SAYS ABOUT THE BUILD ON SCREEN — its own words, cached.
///
/// ONE RULE, AND IT IS THE BOARD'S. This was a second implementation of
/// admission living on the page — how many mods, how many evolution tiers, how
/// many arcane seats, and a capacity floor of its own — and a second
/// implementation is a second answer. It drifted exactly where a copy does: the
/// floor it computed ignored the capacity a STANCE hands back, so a melee build
/// that fits could be told it does not and never reach the door at all.
///
/// `/api/board/check` IS `validate_for_board`, the same call the scorer makes.
/// Asking costs nothing — it is the engine already in this page — and what it
/// answers is what will happen, which no copy can promise.
///
/// `null` = accepted, or not asked yet. A string = the board's own reason.
let boardDoor = null;

/// Ask the door about the build on screen, then repaint what says so.
///
/// TRAILING, because the build changes a slot at a time and the answer is only
/// wanted about the one the reader stopped on. `boardDoorGen` drops a reply
/// that lost the race, so a slow answer about an old build cannot land on top
/// of a fast answer about the current one.
let boardDoorGen = 0;
let boardDoorTimer = null;
function refreshBoardDoor() {
  clearTimeout(boardDoorTimer);
  const gen = ++boardDoorGen;
  boardDoorTimer = setTimeout(async () => {
    if (boardConsent() !== "yes" || officialBuildActive()) {
      boardDoor = null;
      return;
    }
    const body = boardPayload();
    if (!body) return;
    const v = await boardVerdict(body);
    if (gen !== boardDoorGen) return;
    boardDoor = v && v.ok && v.accepted === false ? (v.reason || "") : null;
    renderBoardConsent();
    renderBoardOutcome();
  }, 250);
}

/// WHICH RULERS WOULD TAKE THIS BUILD, asked of the board's own door.
///
/// `/api/board/check` is `validate_for_board` itself — the same call the scorer
/// makes, not a copy of its rules, because a second implementation is a second
/// answer and the player has to be given the board's.
///
/// FROM A RULER, it is asked about that one. FROM A FIGHT OF YOUR OWN there is
/// no ruler to name, so it is asked about ALL of them: a build only has to
/// qualify somewhere to be worth uploading, and "it qualifies for 2 of 3" is
/// the one thing a reader can act on. The page is not predicting a SCORE here —
/// that is the scorer's and always was — only whether the door opens at all.
async function boardVerdict(body) {
  const ids = body.benchmark ? [body.benchmark] : benchList().map((b) => b.id);
  if (!ids.length) return { ok: true, accepted: true, boards: 0, of: 0 };
  let accepted = 0;
  let reason = "";
  for (const id of ids) {
    const v = await api("/api/board/check", { ...body, benchmark: id });
    if (!v || !v.ok) return { ok: false };
    if (v.accepted === false) reason = reason || v.reason || "";
    else accepted += 1;
  }
  return { ok: true, accepted: accepted > 0, reason, boards: accepted, of: ids.length };
}

/// **IS THIS BUILD ALREADY A ROW?** — asked of the ENGINE, in one call.
///
/// Answering it with a POINTER fails: `officialBuildActive()` says whether the
/// ACTIVE PRESET is a builtin, true of a board row opened from the picker and
/// false of the same build reached any other way — so a player who copies one
/// into a preset of their own is told their run is being uploaded to a board
/// that already holds it.
///
/// A BUILD IS NOT ITS SPELLING, which is why this cannot be a comparison here:
/// `builds::canonical_mods` sorts the non-elementals by drain and leaves the
/// elementals in the order that PAIRS them, evolutions are a set, a riven is a
/// shape rather than its rolls, and only the engine has the mod POOL that tells
/// an elemental mod from any other. `/api/build/keys` IS `builds::board_key`,
/// the key the scorer files rows under, asked of the build on screen and every
/// row this weapon holds in one pass.
///
/// A MATCH IS PROOF, AN ABSENCE IS NOT. The board LISTS only builds scoring at
/// least half their weapon's leading row, so a build the store already holds
/// can be missing from `board.json` — which is why this only ever suppresses an
/// upload it can prove is redundant, and never claims the reverse.
async function boardRowMatching(body) {
  const rows = builtinBuilds();
  if (!rows.length) return null;
  const asBuild = (r) => ({
    weapon: body.weapon,
    mods: r.board.mods || [],
    evolutions: r.board.evolutions || [],
    arcanes: r.board.arcanes || [],
    valence: r.board.valence || "",
    exilus: r.board.exilus || undefined,
    mode: r.board.mode || "base",
    // A ROW'S RIVEN IS A SHAPE, in the same two fields the submission uses —
    // the ROLLS beside it are what this engine happened to settle on and are
    // not part of the build.
    riven_pos: (r.board.riven || {}).bonuses || [],
    riven_neg: (r.board.riven || {}).malus || "",
  });
  const res = await api("/api/build/keys", { builds: [body].concat(rows.map(asBuild)) });
  const keys = res && res.ok ? res.keys || [] : [];
  if (!keys[0]) return null;
  const i = keys.findIndex((k, n) => n > 0 && k === keys[0]);
  return i > 0 ? rows[i - 1] : null;
}

/// That row, named the way the picker names it: the ruler it is on and its rank
/// within it. A bare "already on the board" would leave the reader hunting for
/// which row they are looking at.
const boardRowLabel = (r) =>
  `${r.group}${r.name ? ` · ${r.name}` : ""}`;

async function offerBoardSubmit() {
  // NO RULER GATE. Any fight can upload, because what is uploaded is the BUILD
  // and the number is produced by the scorer under ITS fight. Of 914 distinct builds players had submitted, only 46 had ever
  // been scored on more than one board — the gate was holding 95% of everything
  // anyone contributed back from the boards it could also have answered.
  if (officialBuildActive()) return;          // a board row does not resubmit itself
  if (boardConsent() !== "yes") { renderBoardConsent(); renderBoardOutcome(); return; }
  const body = boardPayload();
  if (!body) return;
  // ALREADY A ROW? Asked before the door is, because a build the board already
  // holds has nothing to be refused ABOUT — sending it again would be answered
  // by the store collapsing it onto the row it is, silently, after the reader
  // has been told it was uploaded.
  boardOnBoard = await boardRowMatching(body);
  if (boardOnBoard) {
    boardState = "onboard";
    renderBoardConsent();
    renderBoardOutcome();
    return;
  }
  // THE BOARD'S OWN DOOR, ASKED BEFORE KNOCKING. The store accepts anything;
  // the SCORER decides, an hour later, in a workflow log — so a build the board
  // will never take looked exactly like one it took, forever. Three Kuva Nukor
  // submissions sat there carrying no progenitor element, refused on every run
  // since they arrived, while this panel said "sent".
  //
  // `/api/board/check` is `validate_for_board` itself, the same call the scorer
  // makes — not a copy of its rules, because a second implementation is a
  // second answer and the player has to be given the board's.
  const verdict = await boardVerdict(body);
  boardBoards = verdict && verdict.ok ? { n: verdict.boards, of: verdict.of } : null;
  // ONE ANSWER, TWO READERS. The panel above the run and the line under it both
  // say what the board thinks of this build, and they say it from here.
  boardDoor = verdict && verdict.ok && verdict.accepted === false
    ? (verdict.reason || "") : null;
  if (verdict && verdict.ok && verdict.accepted === false) {
    boardState = "refused";
    boardRefusal = verdict.reason || "";
    renderBoardConsent();
    renderBoardOutcome();
    return;
  }
  boardRefusal = "";
  try {
    // A REAL fetch, not `api()`. Every other endpoint is answered by the engine
    // — locally by the dev server, in the browser by the wasm worker — and the
    // board is the one thing neither of them can answer: it is a service, not a
    // calculation. Routing it through `api()` would hand the path to a worker
    // that has never heard of it.
    //
    // SAME ORIGIN, deliberately. A separate api domain is a second DNS name and
    // a second thing that can be blocked, which is the failure the art rule was
    // written about ("unreliable to blocked from mainland China, i.e. precisely
    // where the players are"). The board lives under this site's own origin.
    const res = await fetch("/api/board/submit", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    boardState = res.ok ? "sent" : "failed";
  } catch (_) {
    // Never an error dialog: a board that is unreachable is not a failed run.
    boardState = "failed";
  }
  renderBoardConsent();
  renderBoardOutcome();
}

/// THE LINE THE BOARD DRAWS, said to the person it applies to. A submission
/// below half its weapon's leading row is stored, scored and then not listed,
/// which from the submitter's side is indistinguishable from one that was lost
/// — and that exact silence has cost this board two migrations already. The
/// rule is stated rather than the consequence counted: a number of hidden rows
/// would need the scorer to publish one, while the RULE is what makes an
/// absence readable, and it is checkable against the board on screen.
const boardCutNote = () =>
  tr("Only builds scoring at least half their weapon's leading row are listed — the board holds the answers, not every attempt.");

/// **WHAT HAPPENED TO THIS RUN**, in one sentence — the ONE statement of it.
///
/// It is written once and read twice: by the consent box at the top of the Sim
/// panel, where the standing policy lives, and by the RESULT, where the reader
/// actually is when they want to know. A run that was sent
/// and a run that was never going to be sent looked identical from the result,
/// which is the same silence the consent box itself was written to end — a
/// player who built their own scenario, ran it, and watched the board.
///
/// A second copy of these branches would be a second answer to "was it sent",
/// which is what `/api/board/check` exists not to have.
function boardRunOutcome() {
  if (officialBuildActive()) {
    return { kind: "none", text: tr("this build is already a row on the board — running it sends nothing") };
  }

  if (boardConsent() !== "yes") return { kind: "none", text: tr("nothing is sent from here") };
  // AN INCOMPLETE BUILD IS A REFUSED ONE, said in the board's own words. It had
  // a branch of its own here fed by a page-side copy of admission, which is how
  // the two could disagree; there is one rule now and one sentence for it.
  if (boardDoor) {
    return { kind: "short",
      text: tr("{what} — the board takes a weapon built as far as it goes, so this one is not sent")
        .replace("{what}", boardDoor) };
  }
  if (boardState === "onboard" && boardOnBoard) {
    // NAMED, not merely asserted. "It is already there" that cannot say WHERE
    // is indistinguishable from a page that declined to send for its own
    // reasons, which is the silence this whole panel exists to end.
    return { kind: "none",
      text: tr("this build is already on the board ({row}) — nothing was sent")
        .replace("{row}", boardRowLabel(boardOnBoard)) };
  }
  if (boardState === "refused") {
    return { kind: "refused",
      text: `${tr("the board would not take this build, so nothing was sent")}: ${boardRefusal}` };
  }
  if (boardState === "failed") {
    return { kind: "failed", text: tr("could not reach the board — nothing was sent") };
  }
  if (boardState === "sent") {
    // WHICH BOARDS, when there is more than one to qualify for. "Sent" alone
    // does not say whether it will be RANKED anywhere, which is the question a
    // submitter actually has — and from a fight of your own it is the only
    // thing the page can honestly answer, since the SCORE is the scorer's.
    //
    // IT SAYS "A BUILD" AND NOT "THIS RUN", because that is what was stored: no
    // submission carries a name, a score or the mode it was tuned for, so the
    // scorer plays it in every mode the weapon has and every ruler crosses the
    // whole library. A sentence about "your run on this mode" would describe a
    // record that does not exist and leave the reader looking for one row when
    // there may be four.
    const b = boardBoards;
    const where = b && b.of > 1
      ? " " + tr("({n} of {of} boards will take it)")
        .replace("{n}", b.n).replace("{of}", b.of)
      : "";
    return { kind: "sent",
      text: tr("uploaded — a submission is a BUILD, so it is scored in every mode this weapon can be played and on every board that takes it. The board re-scores every 20 minutes, so rows appear within about 20, at most 40") + where };
  }
  // NOT YET ANSWERED. `offerBoardSubmit` runs after the result is drawn, so
  // this is the state the first paint is in and it has to say so rather than
  // claiming either outcome.
  return { kind: "pending", text: tr("submitting to the board…") };
}

/// The result's own copy of that sentence. Re-rendered when the verdict lands.
function renderBoardOutcome() {
  const box = $("sim-board-outcome");
  if (!box) return;
  const o = boardRunOutcome();
  box.className = `board-outcome ${o.kind}`;
  box.innerHTML = `<div class="bo-h">${escHtml(o.text)}</div>`
    // THE CUT LINE FOLLOWS A SENT RUN, because that is the reader who is about
    // to go and look for a row that may never appear — and it is its OWN line.
    // Trailing it onto the sentence above made one run-on paragraph out of two
    // separate facts: what happened to this run, and the rule that decides
    // whether it will be listed.
    + (o.kind === "sent"
      ? `<div class="board-state">${escHtml(boardCutNote())}</div>` : "");
}

function renderBoardConsent() {
  const box = $("board-consent");
  if (!box) return;
  // TWO REASONS NOTHING IS SENT, and they must not collapse into one silence.
  // A board ROW explains itself elsewhere ("it is already a row on the
  // board"); with no box on a player's OWN fight, someone who builds a
  // scenario, runs it and watches the board never learns why nothing appeared
  // (player report via the owner, 2026-08-10).
  if (officialBuildActive()) { box.hidden = true; return; }
  box.hidden = false;
  const c = boardConsent();
  // THE FLOOR IS A SUFFIX, NOT A REPLACEMENT. While the build is half-built the
  // standing policy is still the thing a reader most needs to know — replacing
  // it with "this one is not sent" would state the exception and hide the rule,
  // which is the same silence the default-on setting exists not to have.
  const floorNote =
    c === "yes" && boardDoor
      ? ` <span class="board-state">` +
        escHtml(tr("{what} — the board takes a weapon built as far as it goes, so this one is not sent")
          .replace("{what}", boardDoor)) +
        `</span>`
      : "";
  if (!boardConsentChosen()) {
    // THE DEFAULT, STATED. Not a question — the answer is already yes — so it
    // reads as what will happen and what it contains, with the way out next to
    // it. Asking would be dishonest when the default has already decided.
    box.innerHTML =
      `<b>${escHtml(tr("Builds you run here are added to the official board."))}</b> ` +
      escHtml(tr("What is sent is the BUILD: the weapon and its mods, evolutions and arcanes. Not the fight you ran it under — the board scores every build under its OWN rulers, so any scenario can contribute. And nothing about you: no account, no identifier, no address, no time finer than the day, and no score. The board takes a weapon built as far as it goes: every main slot filled, and the exilus slot counted if you use one.")) +
      // WHEN, on the FIRST visit too — this is the branch a new player reads,
      // and it is the one that was silent about the twenty minutes. Saying it
      // only after the consent had been chosen told the fact to everyone except
      // the person meeting the board for the first time.
      ` ${escHtml(tr("A run appears on the board within about 20 minutes, at most 40 — it is re-scored on a schedule, not the instant you send it."))}` +
      ` ${escHtml(boardCutNote())}` +
      floorNote +
      ` <button class="ghost-btn small" id="board-no">${escHtml(tr("don't submit"))}</button>`;
    $("board-no").onclick = () => setBoardConsent("no");
    return;
  }
  // WHEN, not just whether. A submission is stored the moment it is sent and
  // the board is re-scored on a schedule, so "sent" and "on the board" are
  // twenty minutes apart — long enough that a player concludes it failed. The
  // number is the workflow's own: three runs an hour, and GitHub's scheduler
  // slips about fifteen minutes whatever minute is named, so the honest bound
  // is "usually 20, sometimes 40".
  // THE SAME SENTENCE THE RESULT SHOWS — see `boardRunOutcome`. Before any run
  // this box states the standing POLICY instead, which is what a reader at the
  // top of an unrun panel needs; the result says what happened to a run.
  const state = c !== "yes"
    ? tr("nothing is sent from here")
    : boardState === ""
      ? tr("builds you run here are submitted — the board re-scores every 20 minutes, so a run appears there within about 20, at most 40")
      : boardRunOutcome().text;
  box.innerHTML =
    `<span class="board-state">${escHtml(state)}</span>` +
    // THE RULE FOLLOWS THE STATE, and only where it can bite: a reader who
    // has turned submission off is not waiting for a row to appear.
    (c === "yes" ? ` <span class="board-state">${escHtml(boardCutNote())}</span>` : "") +
    floorNote + ` ` +
    `<button class="ghost-btn small" id="board-flip">${escHtml(c === "yes" ? tr("stop submitting") : tr("start submitting"))}</button>`;
  $("board-flip").onclick = () => setBoardConsent(c === "yes" ? "no" : "yes");
}

// The official BUILD, on screen. Same contract as the scenario's lock, but the
// build editor is mostly CLICK HANDLERS on divs (a slot, a polarity, an
// evolution tile) rather than form controls, and `disabled` means nothing to a
// div. `pointer-events: none` on the whole region is the honest equivalent:
// it covers everything the region can ever grow, including a control nobody
// has written yet.
function lockOfficialBuild() {
  const on = officialBuildActive();
  // MODE IS PART OF THE BUILD, so it locks with the build. It was the one
  // control on a read-only board row that stayed live, and the consequence was
  // silent in both directions: switching a #1 Felarx to its base form ran the
  // base form, wrote nothing (`markPresetDirty` refuses an official build), and
  // sent nothing (`offerBoardSubmit` refuses one too) — so a player testing the
  // base form several times saw no row appear and nothing on screen said why.
  // EVERY BUILDER STEP, derived — see `builderSteps`. It was four ids, which
  // is why the Parts block stayed live on a read-only board row. The Stats
  // panel is deliberately not among them: there is nothing in it to click.
  builderSteps().forEach((b) => {
    b.classList.toggle("locked-hard", on);
    // …AND IT SAYS WHY, on the block a player is trying to click. A slot that
    // simply does not react teaches nothing; this names the reason and the way
    // out, and clicking anywhere in the block takes it.
    if (on) {
      b.title = tr("this is a benchmark row — copy it to edit");
      b.onclick = () => copyActivePreset(buildBarCfg());
    } else {
      b.removeAttribute("title");
      b.onclick = null;
    }
  });
  const note = $("build-official");
  if (!note) return;
  note.hidden = !on;
  if (!on) return;
  const row = (buildNamed(activePreset) || {}).board || {};
  const bench = (META.benchmarks || []).find((x) => x.id === row.benchmark);
  // ACTION FIRST. Opening with what the build IS and mentioning copying as a
  // clause, pointing at a ⧉ chip somewhere else on the page, gives a reader who
  // wants to change something no VERB and nothing to click. So: what cannot be
  // done here, the one action that
  // fixes all of it, and a real button — which the scenario's own read-only
  // note has had all along.
  const parts = [
    `<b>${escHtml(tr("Benchmark build — read-only"))}</b>`,
    escHtml(tr("It is already a row on the board, so nothing here can be edited and its runs are not submitted. Copy it and everything opens up — mods, arcanes, evolutions and the mode — and what you run goes to the board as your own entry.")),
  ];
  // WHICH BENCHMARK, stated rather than implied. A board
  // figure means nothing without the ruler that produced it, and "#1" says
  // even less — so the name of the scenario is part of the build, not a
  // caption on the bar it happens to sit in.
  parts.push(
    escHtml(tr("measured under")) +
      ` <span class="official-def">${escHtml(benchmarkName(row.benchmark))}</span>`,
  );
  if (row.score != null) {
    // LABELLED WITH THE BENCHMARK'S OWN METRIC, not a hardcoded one. The
    // number is published in whatever the benchmark declares — a `dps`
    // benchmark would have read "kill rate" here, and a kill-progress figure
    // read as a kill RATE overstated every row by the length of the fight
    // until 2026-08-04.
    const unit = metricLabel(metricOf(((bench || {}).scenario || {}).metric));
    // `shown` is FORMATTED BY THE SCORER (`boards_data::format_score`): at
    // least four significant figures and at least four decimals. The rule is
    // not reimplemented here — the page prints what the record says, so a
    // change to it cannot show one thing in the yaml and another on screen.
    // `score` is the fallback for a board written before the field existed.
    const shown = row.shown || Number(row.score).toFixed(4);
    parts.push(`<span class="official-def">${escHtml(shown)} ${escHtml(unit)}</span>`);
  }
  // NOT the Forma cost: the builder's own header already states capacity and
  // Forma for whatever build is loaded, and this build IS loaded. Two places
  // showing one number is how they come to disagree.
  if (row.source === "seed") {
    parts.push(`<span class="official-seed">${escHtml(tr("seeded by the optimizer — not yet a player submission"))}</span>`);
  }
  note.innerHTML = parts.join(" · ") +
    ` <button class="ghost-btn small" id="build-copy">⧉ ${
      escHtml(tr("copy it to edit"))}</button>`;
  const cp = $("build-copy");
  if (cp) cp.onclick = () => copyActivePreset(buildBarCfg());
}

// The official scenario, ON SCREEN: every control in the fight goes inert and
// the note says why and what to do instead.
//
// This is the VISIBLE half of read-only, and deliberately only the visible
// half — the rule is enforced in `markScenarioDirty`, which is where a write
// would actually happen. A disabled input that auto-save still read would be a
// lie told twice, so the two are separate on purpose.
function lockOfficialScenario() {
  const note = $("sim-official");
  const on = officialScenarioActive();
  // `sim-whole-fight-body` IS IN THE SWEEP, and it was missing for as long as
  // the panel existed. It draws a live control for every editable
  // axis of the fight, so a ruler's pinned level, duration and distance were
  // all editable there — auto-save refuses to write them, which hides the fault
  // rather than preventing it: `sim` still moves in memory, so Run Sim reports
  // a modified ruler under the ruler's own name, which is the exact thing this
  // lock exists to stop. An escape hatch is a place to LOOK at the whole
  // document, not a second editor that outranks the rule.
  const boxes = ["sim-target", "sim-technique", "sim-wfbuffs", "sim-limits", "sim-run",
                 "sim-buffs", "sim-whole-fight-body"]
    .map((id) => $(id)).filter(Boolean);
  // The ARENA's bodies are SVG circles and the input sweep below cannot reach
  // them, so the scene is marked here and refuses the gesture itself.
  ["sim-target-arena", "opt-target-arena"].forEach((id) => {
    const a = $(id);
    if (a) a.classList.toggle("ar-ro", on || id.startsWith("opt-"));
  });
  boxes.forEach((b) => {
    b.classList.toggle("locked", on);
    b.querySelectorAll("input,select,button,textarea").forEach((el) => {
      // ONLY UNLOCK WHAT THIS LOCKED. The first shape remembered each
      // element's prior state and restored it, which is a bookkeeping problem
      // that has to survive every re-render and did not: a second lock pass
      // recorded "was disabled" for an element this had just disabled, so the
      // unlock left it inert and a COPIED scenario could not be edited — the
      // one thing copying is for.
      //
      // Marking instead is idempotent by construction. An element disabled for
      // its OWN reason (a sentinel's infinite-ammo box, ticked and disabled
      // whatever scenario is open) is never marked, so it is never re-enabled
      // here and the page cannot contradict the mechanic.
      if (on) {
        if (!el.disabled) { el.disabled = true; el.dataset.officialLock = "1"; }
      } else if (el.dataset.officialLock) {
        el.disabled = false;
        delete el.dataset.officialLock;
      }
    });
  });
  if (!note) return;
  note.hidden = !on;
  if (on) {
    // A DOOR, NOT A WALL. This is now the scenario a first-time visitor lands
    // on, so the first thing they see is a panel of greyed-out controls — which
    // reads as broken until you know why. The note has always explained it and
    // pointed at the ⧉ on the chip; a chip they have not learned to look at yet
    // is not a route. The button does the same copy, where the locked controls
    // are.
    note.innerHTML =
      `<b>${escHtml(tr("Official test scenario"))}</b> — ` +
      escHtml(tr("the same fight on every weapon, so results can be compared. It cannot be edited.")) +
      ` <span class="official-def">${escHtml((scenarioNamed(activeScenario) || {}).name || "")}</span>` +
      ` <button class="ghost-btn small" id="sim-official-copy">⧉ ${escHtml(tr("edit a copy of this fight"))}</button>`;
    const cp = $("sim-official-copy");
    // The SAME copy the chip's ⧉ performs — `copyActivePreset` with the
    // scenario bar's own config — so there is one implementation of "make me an
    // editable copy" and it cannot drift from the bar.
    if (cp) cp.onclick = () => copyActiveScenario();
  }
}

// Section 2 — one card per configurable buff of the current build (from the
// last /api/panel `buffs`). Each: initial stacks (stepper / on-off) + lock.
// Missing configs default to the buff's `default_*`; ids no longer present are
// dropped from the payload (kept in `sim.buffs` for preset round-trips).
function syncBuffConfig(list, cfg) {
  list.forEach((b) => {
    if (!cfg[b.id]) cfg[b.id] = { stacks: b.default_stacks, locked: b.default_locked };
    else if (!b.uncapped) cfg[b.id].stacks = Math.min(cfg[b.id].stacks, b.max_stacks);
  });
}

// Shared buff-card renderer (Sim panel + Optimizer scope). `list` = the buff
// metadata; `cfg` = the mutated config map.
/// A buff card's name, in the display language.
///
/// The server names a buff after the mod or arcane that grants it — in
/// ENGLISH, because English is the source everywhere. The overlay that
/// translates that name is already on the client (every mod and arcane in
/// META carries `name_en`), so the lookup is by English name and the grant
/// suffix goes through the ordinary UI table. Invisible while the panel only
/// ever showed a build's own two or three cards; the all-potential view shows
/// eleven at once.
function buffCardName(name) {
  const [head, tail] = String(name).split(" (");
  // EVOLUTIONS grant buffs too (Overwhelming Attrition, Lethal Rearmament),
  // and they were missing from this lookup — so those two cards were the only
  // ones on the page still in English.
  const evos = (weaponInfo($("weapon").value).evolutions || [])
    .flatMap((tier) => tier.options || []);
  const owner = [...(META.mods || []), ...(META.arcanes || []), ...evos,
    ...Object.values(META.mod_pools || {}).flat()]
    .find((x) => (x.name_en || x.name) === head);
  // NO OWNER MEANS THE NAME IS OURS. While every card here is a mod's, an
  // arcane's or an evolution's, a head with no owner can only be a lookup that
  // has gone stale — and falling through to the English is the
  // right way to notice. A WEAPON PASSIVE has no owner by construction (the
  // sniper's Shot Combo Counter is the weapon's, not a mod's), so its name is
  // an ordinary UI string and belongs in the overlay like every other one.
  const label = owner ? owner.name : tr(head);
  return tail ? `${label} (${tr(tail.replace(/\)$/, ""))})` : label;
}

function renderBuffCards(box, list, cfg, have, opts = {}) {
  if (!box) return;
  syncBuffConfig(list, cfg);
  if (!list.length) {
    box.innerHTML = `<div class="sim-empty">no configurable buffs here.</div>`;
    return;
  }
  const card = (b) => {
    const c = cfg[b.id];
    // ONE control for every buff, a toggle included: a
    // one-stack buff reads "1 / 1" like the rest instead of a checkbox that
    // said "active" and meant the same thing in different words.
    // WHERE THE RUN STARTS, not what the buff is worth. A timed buff opens at
    // 0 because the modelled fight is "in it a while, but not in contact for
    // the last few seconds" — it is earned back on its own trigger. Only a
    // permanent buff opens full, because a lull cannot take it away.
    const startWhy = b.permanent
      ? tr("permanent — nothing grants or decays it, so it holds all run")
      : tr("stacks the run STARTS with. 0 = earned in-fight on this buff's own trigger, which is what a fight that has not been in contact for a few seconds looks like");
    // UNCAPPED buffs exist: Secondary Enervate ramps a stack per hit with no
    // ceiling until a big crit wipes it. `/ ∞` is the honest maximum, and the
    // input takes no `max` — clamping it to a number we invented would be the
    // one place the UI disagreed with the mechanic.
    const cap = b.uncapped ? "∞" : b.max_stacks;
    const ctl = `<span class="bstep" title="${escHtml(startWhy)}"><input type="number" data-b="${b.id}" data-f="stacks" min="0"${b.uncapped ? "" : ` max="${b.max_stacks}"`} value="${c.stacks}"><span class="bmax">/ ${cap}</span></span>`;
    // NOT "lock": that read as "freeze this buff", so
    // locking one at zero looked like a way to switch it off forever. It only
    // removes the TIMEOUT — the count still starts where it is set and still
    // climbs on every trigger.
    const lock = b.permanent
      ? `<label class="block-lock dis" title="${escHtml(tr("permanent stacks — they never decay and cannot build in-sim, so the count holds for the whole run"))}"><input type="checkbox" checked disabled> ${escHtml(tr("no timeout"))}</label>`
      : `<label class="block-lock" title="${escHtml(tr("the stacks never expire — they still start where you set them and still build on every trigger"))}"><input type="checkbox" data-b="${b.id}" data-f="locked" ${c.locked ? "checked" : ""}> ${escHtml(tr("no timeout"))}</label>`;
    // In the WIDER view, a buff the build does not carry is still settable —
    // it just says so, so the panel never reads as "this is active now".
    const off = have && !have.has(b.id);
    // …AND A BUFF THE FIGHT DENIES IS SHOWN, NOT HIDDEN: "no such buff" and
    // "nothing here triggers it" are the one pair a reader must tell apart.
    const denied = buffDenied(b);
    // What one stack count buys, when the source grants more than one thing
    // off the same trigger — they are the same count by construction.
    const grants = b.grants ? `<small class="bgr">${escHtml(tf(b.grants))}</small>` : "";
    const why = denied
      ? ` <small class="bnot bdenied" title="${escHtml(
          tr("what would trigger it triggers no buff in this fight, so it stays at zero all run"))}">${
          escHtml(tr("not triggered here"))}</small>`
      : "";
    return `<div class="buff-card${off ? " off" : ""}${denied ? " denied" : ""}">
      <span class="bn">${escHtml(buffCardName(b.name))}${grants}${off ? ` <small class="bnot">${escHtml(tr("not equipped"))}</small>` : ""}${why}</span>
      <span class="bctl">${ctl}</span>
      ${lock}
    </div>`;
  };
  box.innerHTML = list.map(card).join("");
  // READ-ONLY: the same cards, the same values, and no way to change them. A
  // preset is edited in exactly one place (the rule the fight above already
  // follows), so the optimizer SHOWS the buffs and links to the module that
  // owns them.
  if (opts.readonly) {
    box.querySelectorAll("[data-b]").forEach((el) => {
      el.disabled = true;
      el.title = tr("edit this in the Simulator");
    });
    return;
  }
  // A DENIED CARD'S KNOBS ARE DEAD, and say why — a control that cannot move
  // the number is worse than none, because it looks like one that can.
  const byId = new Map(list.map((b) => [b.id, b]));
  box.querySelectorAll("[data-b]").forEach((el) => {
    const b = byId.get(el.dataset.b);
    if (b && buffDenied(b)) {
      el.disabled = true;
      el.title = tr("what would trigger it triggers no buff in this fight, so it stays at zero all run");
    }
  });
  box.querySelectorAll("[data-b]").forEach((el) => {
    el.addEventListener("change", () => {
      const id = el.dataset.b, f = el.dataset.f, c = cfg[id];
      if (f === "locked") c.locked = el.checked;
      else if (el.type === "checkbox") c.stacks = el.checked ? 1 : 0;
      else c.stacks = Math.max(0, Number(el.value));
      // A buff belongs to the FIGHT and to nothing else — including settings
      // for mods this build does not carry. A build keeps no copy of the
      // scenario, so this dirties the scenario alone.
      markScenarioDirty();
      // The optimizer shows these read-only, so redraw its copy if it is up.
      if ($("opt-buffs") && !opts.readonly) renderOptBuffs();
    });
  });
}

// The buff panel has TWO views. By default it lists what the current build
// actually carries. "All potential" widens it to every buff this WEAPON could
// ever have — every mod in its pool, every arcane it can seat, every
// evolution option — because a scenario is meant to describe a fight, not a
// build, and a setting for a mod you have not equipped yet is exactly what the
// marginal-gain scan reads: settings reachable only once the mod is on are
// settings nobody can use to decide whether to equip it.
//
// The union comes from `/api/opt-buffs`, which already answers "every buff
// this SCOPE could produce" for the optimizer — handing it a scope of
// everything is the same question, and a second implementation of it would be
// a second thing to keep right.
let simBuffsAll = false;
let allBuffList = null;   // cached per weapon; null = not fetched
let allBuffWeapon = null;

async function fetchAllBuffs() {
  const w = $("weapon").value;
  if (allBuffWeapon === w && allBuffList) return allBuffList;
  const mark = (ids) => Object.fromEntries(ids.map((id) => [id, "search"]));
  const AX = weaponAxes(w);
  const r = await api("/api/opt-buffs", {
    weapon: w,
    mods: mark([...AX.mods.map((m) => m.id), ...AX.exilus.map((m) => m.id)]),
    arcanes: mark(AX.arcanes.flatMap((a) => a.options.map((x) => x.id))),
    evolutions: Object.fromEntries(AX.evolutions.map((t, i) => [i, t.options.map((o) => o.id)])),
    rivens: rivenPayload(),
  });
  allBuffList = r && r.ok ? r.buffs || [] : [];
  allBuffWeapon = w;
  return allBuffList;
}

/// WHICH TRIGGERS FIRE NO BUFF IN THIS FIGHT — the subject is docs/BUFFS.md and
/// the vocabulary is `/api/meta.buff_triggers`, which is the DATA'S OWN: a buff
/// declares what fires it, so a switch per trigger conflates nothing. A coarse
/// set came first and collapsed the distinctions the data already draws — a
/// weak-point KILL is not a kill, and there was no way to say so.
///
/// IT SWITCHES OFF A TRIGGER, NOT AN EVENT. The run still kills, still hits weak
/// points, still procs, and the score still counts every one; what stops is the
/// BUFF those would have granted.
///
/// IT SITS IN LIMITS, beside Infinite ammo, because it is the same kind of
/// statement — not a technique anybody plays, but what this run is allowed to
/// assume. Every trigger is drawn on every weapon: a scenario describes a FIGHT
/// and not a build, and a term that vanished with the mods equipped would be a
/// ruler that changed shape between weapons.
///
/// NINETEEN IS A WALL, so they are GROUPED and folded. The group is presentation
/// and the switches are the truth — a header ticks its members and stores
/// nothing of its own, so a ruler can say `kill` alone or name `headshot_kill`.
const BUFF_TRIGGER_NAME = {
  kill: "any kill",
  headshot_kill: "weak-point kills",
  melee_kill: "melee kills",
  hit: "any hit",
  plain_hit: "hits that neither crit nor proc",
  headshot: "weak-point hits",
  weakpoint_hit: "weak-point hits, counted per pellet",
  consecutive_headshot: "weak-point hits in a row",
  punch_through: "punch through into a second body",
  status_applied: "a status landing",
  hit_enemy_with_status: "hitting a target that already carries a status",
  heat_status: "a Heat status landing",
  electricity_status: "an Electricity status landing",
  toxin_status: "a Toxin status landing",
  cold_status: "a Cold status landing",
  reload_complete: "a completed reload",
  reload_from_empty: "reloads from empty",
  firing: "a round leaving the barrel",
  full_burst: "a burst landing whole",
};
const BUFF_GROUP_NAME = {
  kill: "killing", hit: "hitting", status: "status effects",
  reload: "reloading", firing: "firing",
};

/// The groups, in the order `/api/meta.buff_triggers` lists them.
function buffTriggerGroups() {
  const out = [];
  for (const t of META.buff_triggers || []) {
    const last = out[out.length - 1];
    if (last && last.id === t.group) last.ids.push(t.id);
    else out.push({ id: t.group, ids: [t.id] });
  }
  return out;
}

function buffTriggersField() {
  const groups = buffTriggerGroups();
  if (!groups.length) return "";
  const off = new Set(sim.buff_triggers_off || []);
  const box = (id, label, extra) =>
    `<label class="bev${off.has(id) ? " on" : ""}"><input type="checkbox" ${extra}${
      off.has(id) ? " checked" : ""}> ${escHtml(label)}</label>`;
  return `<div class="bev-h">${escHtml(tr("no buff is triggered by"))}</div>${
    groups.map((g) => {
      // A HEADER IS TICKED WHEN ALL OF ITS OWN ARE, and half-ticked otherwise —
      // the state a reader needs is "is this whole group off", and a bare
      // checkbox has no third position to say "some of it".
      const on = g.ids.filter((id) => off.has(id)).length;
      const mark = on === g.ids.length ? " checked" : (on ? " data-some=\"1\"" : "");
      return `<div class="bevg">
        <label class="bevg-h${on ? " on" : ""}"><input type="checkbox" data-bevg="${
          escHtml(g.id)}"${mark}> ${escHtml(tr(BUFF_GROUP_NAME[g.id] || g.id))}${
          on && on < g.ids.length ? ` <small>${on}/${g.ids.length}</small>` : ""}</label>
        <div class="bev-row">${g.ids.map((id) =>
          box(id, tr(BUFF_TRIGGER_NAME[id] || id), `data-bev="${escHtml(id)}"`)).join("")}</div>
      </div>`;
    }).join("")}
    <div class="bev-why">${escHtml(tr(
      "the run still does all of these and the score still counts them — only the buffs they would trigger are off"))}</div>`;
}

/// THE VOCABULARY'S ORDER, not click order: this travels in a share link, and
/// two spellings of one fight compare as two fights. An id the page does not
/// know is KEPT, so an older page cannot strip a newer fight's terms.
function setBuffTriggersOff(set) {
  const known = (META.buff_triggers || []).map((t) => t.id);
  sim.buff_triggers_off = known.filter((x) => set.has(x))
    .concat([...set].filter((x) => !known.includes(x)));
  markScenarioDirty();
  renderSim();
}

function toggleBuffTrigger(id, on) {
  const set = new Set(sim.buff_triggers_off || []);
  if (on) set.add(id); else set.delete(id);
  setBuffTriggersOff(set);
}

/// A GROUP TICKS ITS MEMBERS AND STORES NOTHING. Off = every one of them off,
/// which is what makes the header's own state readable back out of the list.
function toggleBuffTriggerGroup(group, on) {
  const g = buffTriggerGroups().find((x) => x.id === group);
  if (!g) return;
  const set = new Set(sim.buff_triggers_off || []);
  g.ids.forEach((id) => { if (on) set.add(id); else set.delete(id); });
  setBuffTriggersOff(set);
}

/// Is this card's trigger switched off? The RUN answers it from the same table
/// server-side, which keeps the grey and the number together.
const buffDenied = (b) =>
  !!b.trigger && (sim.buff_triggers_off || []).includes(b.trigger);

function renderSimBuffs() {
  const btn = $("sim-buffs-all");
  const list = simBuffsAll && allBuffList ? allBuffList : buffList;
  if (btn) {
    btn.textContent = simBuffsAll ? tr("in this build") : tr("all potential buffs");
    btn.title = tr("a scenario can set a buff for a mod this build does not carry — the gain scan reads it");
    btn.onclick = async () => {
      simBuffsAll = !simBuffsAll;
      if (simBuffsAll) { btn.disabled = true; await fetchAllBuffs(); btn.disabled = false; }
      renderSimBuffs();
    };
  }
  // Which of them the build actually has, so the wider list still says where
  // you are: everything else is a setting held for later.
  const have = new Set(buffList.map((b) => b.id));
  renderBuffCards($("sim-buffs"), list, sim.buffs, simBuffsAll ? have : null);
}

async function runSim() {
  const btn = $("run-sim");
  btn.disabled = true; btn.textContent = "Simulating…";
  show("sim-results-block", true);
  // A BAR, BECAUSE THE WAIT IS UNBOUNDED. A single-target fight is a
  // millisecond a run; a 361-body one is tens of them, so the rulers' 1000 runs
  // is a minute in the browser — and a line that says "running 1000
  // simulations…" for a minute reads as a hang.
  //
  // IT SAYS THE COUNT, not just a proportion: "412 / 1000" is a number a reader
  // can act on (lower the runs, take the fight apart) where a bar alone is only
  // a feeling.
  $("sim-results").innerHTML = `<div class="placeholder simrun">
    <div class="simrun-t">${escHtml(tr("running {n} simulations…").replace("{n}", simRuns()))}</div>
    <div class="simrun-bar"><span id="sim-prog" style="width:0%"></span></div>
    <div class="simrun-n" id="sim-prog-n"></div>
    <button type="button" id="sim-stop" class="ghost-btn small">${escHtml(tr("stop"))}</button>
  </div>`;
  // STOPPABLE, because the wait is unbounded and a reader who realises the
  // fight is too big should not have to reload the page.
  $("sim-stop").onclick = () => {
    cancelSim();
    $("sim-results").innerHTML =
      `<div class="placeholder">${escHtml(tr("stopped — nothing was measured"))}</div>`;
  };
  // THE READER IS WAITING FOR THIS ONE, so it outranks whatever the quick calc
  // is measuring — released in the `finally` below, whichever way this ends.
  const releasePriority = holdForeground();
  try {
    // `replay: true` only HERE. The gain scan hits the same endpoint once per
    // candidate and shows no replay, so it must not pay for one.
    const body = { ...buildPayload(), ...theFight({ replay: true }) };
    // THROTTLED BY THE FRAME, not by the message: the worker already sends one
    // per percent, and a DOM write per percent is still 100 of them for a fight
    // that takes a second.
    let painted = -1;
    const began = Date.now();
    const r = await simulateFleet(body, (done, total) => {
      const pct = total ? Math.round((done / total) * 100) : 100;
      if (pct === painted) return;
      painted = pct;
      const bar = $("sim-prog");
      const num = $("sim-prog-n");
      if (bar) bar.style.width = `${pct}%`;
      // HOW LONG IS LEFT, from how long it has taken — free, because the run is
      // already happening, and exact enough after a few runs because every run
      // is the same fight. A 361-body ruler is ~28 ms a run, so the default
      // 1000 is half a minute: the number a reader needs is not "how far" but
      // "how much longer".
      //
      // AFTER 5% only. Before that the estimate is one or two runs' noise
      // extrapolated a hundredfold, which reads as a wild guess and is one.
      const secs = (Date.now() - began) / 1000;
      const left = done > 0 && pct >= 5 ? (secs / done) * (total - done) : null;
      if (num) {
        num.textContent = `${done} / ${total}`
          + (left !== null && left > 1
            ? ` · ${tr("about {s}s left").replace("{s}", Math.ceil(left))}`
            : "");
      }
    });
    // A CANCEL IS NOT A FAILURE: the reader asked for it, and the panel already
    // says so. Nothing to report and nothing to complain about.
    if (r && r.cancelled) return;
    if (!r || r.ok === false) {
      $("sim-results").innerHTML = `<div class="error">sim failed: ${r ? r.error : "no data"}</div>`;
      return;
    }
    // A NEW RUN IS A NEW VERDICT. `renderResults` draws the outcome line
    // itself, so leaving the last run's answer standing would state it under a
    // build that has not been asked about yet — and now that one of the answers
    // is "already on the board", a stale one is a claim about the wrong build.
    boardState = "";
    boardOnBoard = null;
    renderResults(r);
    saveSimResult(r);
    // ONE INTEGER PAIR, FOR THE READER'S OWN EYES. `/support` is the only thing
    // that reads it and it never leaves this browser — see `SUPPORT_USE`. It is
    // counted HERE rather than in the worker because what is being counted is a
    // measurement the reader ASKED FOR: the quick calc and the optimizer run
    // thousands of engagements nobody sat and watched.
    noteSimRun(simRuns());
    // A run under the OFFICIAL scenario is the only thing that can reach the
    // board, and only after you have said so. Never blocks the result.
    offerBoardSubmit();
  } catch (e) {
    $("sim-results").innerHTML = `<div class="error">sim failed: ${e}</div>`;
  } finally {
    releasePriority();
    btn.disabled = false; btn.textContent = "Run Simulation";
  }
}

// ---- per-preset result memory ------------------------------------------
// The simulator shows the ACTIVE preset's LAST test — switching builds
// switches the displayed numbers too. A finished run
// saves into the preset's entry — as `lastResult`, OUTSIDE `state`, so
// the unsaved-changes dot ignores it — and every preset switch restores
// it (or clears, when that build was never tested).
// WHAT was measured: the build and the fight, together. A number is only
// this build's number while both are unchanged — the share card states the
// two side by side, so it has to know when the stored one stopped matching.
function simKey() {
  const st = snapshotState();
  return JSON.stringify([st.slots, st.arcane, st.arcaneRank, st.evoSel, snapshotScenario()]);
}

function saveSimResult(r) {
  const ps = loadPresetList(BUILDS);
  const at = ps.findIndex((p) => p.name === activePreset);
  if (at < 0) return;
  ps[at].lastResult = { r, at: Date.now(), key: simKey() };
  // …AND IN MEMORY FIRST, which is where the REPLAY stays for good. See
  // `stripReplays`: the copy that reaches the disk has none.
  resultMem.set(resultMemKey(), ps[at].lastResult);
  storePresetList(BUILDS, ps);
}

// The result to PUT ON A CARD: the stored one if it still describes this
// build in this fight, else a fresh run. Reusing a stale one would be worse than having none — the card
// would attach a measurement to a build that never produced it.
async function resultForShare() {
  const p = loadPresetList(BUILDS).find((x) => x.name === activePreset);
  if (p && p.lastResult && p.lastResult.r && p.lastResult.key === simKey()) return p.lastResult;
  // The PANEL first, awaited. `refreshPanel` is debounced and returns before
  // it has answered, so a share clicked seconds after an edit was composing
  // its buff map from the PREVIOUS build's `buffList` — a buff the new mod
  // grants was simply absent from the payload, and the server fell back to
  // its own default. That is the whole of "0.4 shared vs 0.56 run by hand": same seed, same build, a different buff map.
  try { renderPanel(await api("/api/panel", buildPayload())); } catch (_) { /* keep going */ }
  // THE SAME FIGHT RUN SIM RUNS. It spread a raw `sim` until 2026-08-17, which
  // sent no run count (so the server's own default, not the page's) and no
  // `custom_enemies` — so the claim on a share card for a fight against a
  // target you made was measured against a target the server had never heard
  // of.
  // THROUGH THE FLEET, like Run Sim: it is the same fight at the same run
  // count, and on a crowd the difference is a minute against a quarter of one.
  // A share card that takes a minute to appear is a share card nobody waits
  // for.
  const r = await simulateFleet({ ...buildPayload(), ...theFight() });
  if (!r || r.ok === false) return null;
  saveSimResult(r);
  renderStoredSimResult();
  return { r, at: Date.now(), key: simKey() };
}
/// THE RESULT ON SCREEN, held in memory as well as in storage.
///
/// Redrawing from localStorage alone makes every re-render a bet that the save
/// worked — and on a full disk it has not, so clicking a body in the result
/// deletes the result. This is a RENDER CACHE and nothing else: storage is
/// still where a result persists
/// across a reload, and this is only what the current page is showing.
/// KEYED BY WEAPON AND PRESET, because switching either one asks for a
/// different result and both are legal to do without re-running.
const resultMem = new Map();
const resultMemKey = () => JSON.stringify([presetWeapon(), activePreset]);

function renderStoredSimResult() {
  const box = $("sim-results");
  if (!box) return;
  let p = loadPresetList(BUILDS).find((x) => x.name === activePreset);
  // WHAT IS ON SCREEN WINS over what reached the disk, and only for the build
  // it was measured on — a cache that outlived its build would attach a number
  // to something that never produced it.
  const mem = resultMem.get(resultMemKey());
  // A STORED RESULT HAS NO REPLAY (see `stripReplays`), so memory is not only
  // the fallback for a failed write — it is where the median engagement, the
  // buff curves and the hit account live for the whole session. Prefer it
  // whenever it describes the same run, and fall back to it entirely when the
  // disk has nothing.
  if (mem && (!p || !p.lastResult || !p.lastResult.r
      || (p.lastResult.key === mem.key && mem.r.replay))) {
    p = { lastResult: mem };
  }
  const has = !!(p && p.lastResult && p.lastResult.r);
  show("sim-results-block", has); // an untested build shows no Result block
  if (has) renderResults(p.lastResult.r, p.lastResult.at);
  else box.innerHTML = "";
}

// ---- REPLAY -------------------------------------------------------------
//
// The MEDIAN engagement, played back. Not a new simulation and not an average:
// the engine re-ran that one run from the RNG state it recorded, so this is
// the fight the headline number came from, frame by frame.
//
// One row per buff, each a short curve of LIVE STACKS over time, all open by
// default — the question they answer is "was this thing actually up", and a
// row that has to be clicked to answer it will not be. `mean` and `uptime`
// sit in the header so the group reads without expanding anything at all.
const REPLAY_SPEEDS = [1, 2, 5, 20];
// An UNCAPPED buff has no maximum to draw against, so the curve scales to the
// highest it actually reached and the readout says so.
// NO CEILING IS EITHER SPELLING: the buff roster has always said it with a
// max of 0 (`DummyParams::buff_roster`: "0 means no ceiling, which the api
// and the UI both read as such") and the debuff roster now says it the same
// way. Reading only the flag printed a bare "0" for every uncapped BUFF and
// scaled its chart to 1 — an uncapped row drawn as though it were full from
// the first stack.
const rpUncapped = (b) => !!b.uncapped || Number(b.max) === 0;
// A ROW IS A COUNT OR IT IS A NUMBER, and the roster says which. Almost every buff is capped by a stack count and DE publishes
// that count, so `3/4` is the honest reading. A few publish the NUMBER the pile
// stops at and let the counter run — Hata-Satya's "capped at 500% at all mod
// ranks" — and for those a stack count is a chart of the wrong quantity: it
// climbs past a ceiling nobody printed. Such a row carries `value` from the
// engine ({per, max, unit}) and everything below reads the VALUE: the curve,
// the average, the live readout and the ramp.
//
// `unit: "%"` means the engine's numbers are fractions and the reader
// multiplies by 100 — the same convention `loadout::pct` uses on the Rust side.
// The engine states the quantity; this states the presentation.
const rpValueOf = (b, stacks) => {
  const v = b && b.value;
  if (!v) return Number(stacks);
  return Math.min(Number(stacks) * v.per, v.max);
};
// A point on the row, already in the row's own quantity.
const rpFmtVal = (b, n) => {
  const v = b && b.value;
  if (!v) return String(n);
  return v.unit === "%" ? `${(n * 100).toFixed(1)}%` : `${n.toFixed(2)}${v.unit}`;
};
// …and the same from a raw stack count, which is what the frames carry.
const rpFmt = (b, stacks) => (b && b.value ? rpFmtVal(b, rpValueOf(b, stacks)) : String(stacks));
// The number the row stops at: the published one where there is one, the stack
// ceiling otherwise, and NaN-free where there is neither.
const rpCeil = (b) => (b && b.value ? b.value.max : Number(b.max));
// The ceiling as the row draws it: a stack count, a published number, or ∞.
const rpCap = (b) => {
  if (b && b.value) return b.value.unit === "%"
    ? `${(b.value.max * 100).toFixed(0)}%`
    : `${b.value.max}${b.value.unit}`;
  return rpUncapped(b) ? "∞" : b.max;
};
/// A BUFF SERIES' NAME, from the CARDS — same ids, so the chart, the record's
/// "buffs up" column and the card a reader clicks can never disagree about what
/// a series is called.
const buffRosterName = (id) => {
  const b = (buffList || []).find((x) => x.id === id);
  return b ? buffCardName(b.name) : id;
};

/// A DEBUFF ROW IS NAMED BY ITS DAMAGE TYPE, which is already translated
/// everywhere else on the page (`DT`). The alternative was a new i18n family
/// for the proc names — Virus, Corrosion, Disrupt — and DE's Chinese for those
/// is not something to invent: a string is transcribed, never translated
/// (AGENTS.md). The damage type says the same thing in words the reader has
/// already seen on the damage meter, and it is 1:1 with the proc everywhere
/// except Cold, whose two states are told apart by a suffix of our own.
const DEBUFF_TYPE = {
  virus: "viral", corrosion: "corrosive", disrupt: "magnetic",
  confusion: "radiation", blast: "blast", freeze: "cold", frozen: "cold",
  stagger: "impact", weakened: "puncture", attractor: "void",
  bleed: "slash", poison: "toxin", ignite: "heat",
};
// MICROWAVE is not a damage type, so it has no `DT` name to borrow — it is
// its own thing and DE named it, so it keeps that name rather than being
// translated into a description of what it does, which is exactly what the
// transcribe-never-translate rule forbids.
const DB_OWN_NAME = { microwave: "Microwave", lifted: "Lifted" };
const debuffRosterName = (id) =>
  (DB_OWN_NAME[id] || DT(DEBUFF_TYPE[id] || id)) +
  (id === "frozen" ? ` (${tr("frozen")})` : "");

let replayState = null; // { data, i, playing, speed, raf }

// ---- EVERY BLOCK FOLDS -------------------------------------------------
//
// The result panel grew from one number to nine blocks, and not every reader
// wants all nine every time. So a block is a heading you
// can click, and it REMEMBERS — per block, across runs and reloads, because a
// panel that re-opens everything on every Run Sim is a panel you have to
// re-close on every Run Sim.
//
// The state lives outside the markup, which is what lets `renderResults`
// rebuild the whole panel without losing what you folded.
let foldState = {};
try { foldState = JSON.parse(localStorage.getItem("wfsim-folds")) || {}; } catch (_) {}
const saveFolds = () => localStorage.setItem("wfsim-folds", JSON.stringify(foldState));
const folded = (id) => foldState[id] === true;

/// One collapsible block: a heading, an optional hint, and a body.
function foldBlock(id, title, hint, body) {
  const shut = folded(id);
  return `<div class="fold${shut ? " shut" : ""}" data-fold="${escHtml(id)}">
    <h3 class="fold-h"><span class="fold-c">▾</span>${escHtml(title)}${
      hint ? ` <span class="sim-hint">${escHtml(hint)}</span>` : ""}</h3>
    <div class="fold-b">${body}</div>
  </div>`;
}

/// Wire every block on the page. Called once per render, and delegated from the
/// heading rather than the whole block, so a click inside the body — a scrub
/// bar, a mod row — never folds the thing it is inside.
function wireFolds(root) {
  (root || document).querySelectorAll(".fold > .fold-h").forEach((h) => {
    h.onclick = () => {
      const box = h.parentElement;
      const id = box.dataset.fold;
      const shut = !box.classList.contains("shut");
      box.classList.toggle("shut", shut);
      foldState[id] = shut;
      saveFolds();
    };
  });
}

// ---- WHAT A SPEEDRUNNER READS ------------------------------------------
//
// `dps` is the whole engagement, reloads included, which is the honest number
// for a long fight and the wrong one for a room. These are the others: the rate
// while the trigger is actually down, how long the first body takes to fall,
// what the magazine you walked in with was worth, and the biggest single number
// the build can produce.
function speedMarkup(r) {
  if (!r || r.burst_dps == null) return "";
  const n = (x) => Math.round(x || 0).toLocaleString();
  const secs = (x) => `${(x || 0).toFixed(2)}s`;
  const ttk = r.ttk || {};
  const cell = (k, v, sub) =>
    `<div class="kpi"><div class="kv">${v}</div><div class="kl">${escHtml(tr(k))}</div>${
      sub ? `<div class="ksub">${escHtml(sub)}</div>` : ""}</div>`;
  const body = `<div class="kpi-row">
    ${cell("Burst DPS", n(r.burst_dps), tr("while firing"))}
    ${cell("Sustained DPS", n(r.dps), tr("reloads included"))}
    ${ttk.runs ? cell("Time to first kill", secs(ttk.median),
        `${tr("median")} · P90 ${secs(ttk.p90)} · ${ttk.runs}/${r.runs} ${tr("runs killed")}`)
      : cell("Time to first kill", "—", tr("nothing died"))}
    ${cell("First magazine", n(r.first_magazine), tr("before the first reload"))}
    ${cell("Biggest hit", n(r.max_hit), `${tr("best run")} · ${n(r.mean_max_hit)} ${tr("typical")}`)}
    ${cell("Per shot", n(r.damage_per_shot), `${n(r.damage_per_pellet)} ${tr("per pellet")}`)}
    ${cell("Not firing", secs(r.downtime), tr("reloads and transforms"))}
  </div>`;
  return foldBlock("speed", tr("Pace"), tr("what a room-clear is paced by, as opposed to a long fight"), body);
}

// ---- WHAT THE COMBAT RECORD REPLACES ----------------------------------
//
// "Every hit, sorted" and "The account of one hit" are both gone: the COMBAT
// RECORD below answers what they did. The account explained
// two instances of an engagement; the record explains every one. The histogram
// was the aggregate that existed because the individual hits were not
// available — it sorted them into six buckets so an impossible number could not
// hide in a mean — and once every hit is a row with its own ledger, six means
// are a summary of something the reader can now simply read.
//
// The engine lost `HitAccount` and the two `[[_; 3]; 2]` counters with them, so
// nothing is being computed for a panel that no longer draws it.

// ---- THE COMBAT RECORD -------------------------------------------------
//
// One row per number the game pops, in order, with everything behind it. Every
// other block on this panel is an aggregate, and an aggregate hides an error
// inside an average — a factor applied twice moves a mean by a few per cent and
// reads as a build being good. This is the one output that can be laid beside a
// recording and checked number for number.
//
// IT IS FETCHED, NOT CARRIED. `/api/log` re-runs the median engagement from its
// own RNG state — about a millisecond single-target — so the record costs
// nothing until somebody opens it, nothing on the wire for the runs nobody
// reads, and nothing on disk ever. An ordinary fight is a few thousand rows and
// the densest measured is 408,817, which is why the request takes a WINDOW.
let recordState = null;

/// The fight this record is about, as the key that says whether it is stale.
/// A record is only meaningful for the run it was taken from, so it is thrown
/// away whenever the result it explains is.
function recordKey(r) {
  return `${simKey()}|${(r.run || []).join(",")}`;
}

function recordMarkup(r) {
  if (!r) return "";
  // A RESULT FROM BEFORE THIS EXISTED SAYS SO, rather than drawing nothing.
  //
  // The record is fetched by naming the engagement it explains — the median
  // run's own RNG state, which `/api/simulate` started returning the day this
  // panel landed. A result SAVED before that has no name to give, and the
  // block must not simply vanish: a reader coming back to a stored result then
  // finds the feature absent with nothing saying why. An absence that is not
  // explained reads as a feature that is not there — the same rule
  // this panel already follows about its own caps.
  if (!r.run) {
    return foldBlock("record", tr("Combat record"),
      tr("one row per number the game pops, and everything behind it"),
      `<div class="rec-idle"><span class="sim-hint">${escHtml(
        tr("this result was saved before the record existed — run the fight again to read it"))}</span></div>`);
  }
  // AN EMPTY HOST, filled by `paintRecord` in the same wire pass. Rendering
  // the table here as well builds it TWICE on every result — and, since the
  // record can live in its own window, builds it into the wrong document
  // before the paint moves it out again.
  return foldBlock("record", tr("Combat record"),
    tr("one row per number the game pops, and everything behind it"),
    `<div class="rec" id="rec-host"></div>`);
}

function recordIdle() {
  return `<div class="rec-idle">
    <button class="ghost-btn small" id="rec-load">${escHtml(tr("Read the record"))}</button>
    <span class="sim-hint">${escHtml(tr("re-runs this engagement to list every damage instance"))}</span>
  </div>`;
}

/// FETCH A WINDOW. `from`/`to` are seconds; the whole fight is the default and
/// is the right answer for almost every build — only a status weapon over a
/// formation reaches the cap, and when it does the answer says so.
/// HOW MANY EVENTS A READ ASKS FOR, by default.
///
/// Not a limit on what the fight DID — a limit on what one read hands over. At
/// the measured 481 bytes an event this is ~10 MB and about half a second, and
/// it covers an ordinary fight several times over; what it does not cover is a
/// dense build over the full 180 s, which is exactly the fight somebody is
/// arguing about. So it is a DEFAULT rather than a ceiling: when something did
/// not fit, the panel offers to go and get it, and says what that costs.
const RECORD_LIMIT = 20000;

/// HOW MANY PAGES A "read the whole fight" WILL ASK FOR before giving up.
///
/// A backstop, not a budget: at `RECORD_LIMIT` a page it takes twelve to cover
/// the densest build ever measured, and anything past that is a runaway rather
/// than a fight.
const RECORD_MAX_PAGES = 40;

/// READ THE RECORD, in as many PAGES as it takes.
///
/// `pages` is 1 for the ordinary read and unbounded for "read the whole
/// fight". Each page is one more re-run of the same engagement — about 45 ms of
/// engine — which is the price the owner named when he asked for all of it
/// however many runs that takes.
///
/// PAGING IS BY OFFSET, never by time: a page boundary can fall in the middle
/// of an instant, and several numbers share a timestamp — so "continue from t"
/// either loses them or repeats them. The server skips a count instead, and an
/// event's id is its place in the FIGHT, so the pages concatenate into one
/// stream and a floating number can still name its row across a boundary.
async function loadRecord(r, from, to, limit = RECORD_LIMIT, pages = 1) {
  const key = recordKey(r);
  recordState = { key, from, to, limit, loading: true, body: null, filter: "all", at: 0,
                  page: 0, pages };
  paintRecord(r);
  // THE BUILD AND THE FIGHT, exactly as `runSim` sends them. `theFight()` is
  // the SCENARIO — it carries no mods, no mode, no evolutions, no riven — so a
  // record asked for with it alone was computed for a BLANK build and explained
  // a fight nobody ran. Worse than wrong: with no `evolutions` the parser hands
  // the Incarnon form over free, so the record opened already transmuted while
  // the report beside it had earned the form.
  //
  // The pairing is the whole claim this panel makes, so it is written the same
  // way the run is: `buildPayload()` then the fight, one line apart.
  // `to` IS OMITTED WHEN THERE IS NONE, never sent as null: the server reads a
  // missing key as "the whole fight" and a null one as zero, which silently
  // truncated the window to nothing after the opening events.
  const win = to == null ? { from } : { from, to };
  const events = [];
  let out = null, dropped = 0;
  for (let page = 0; page < Math.max(1, pages); page++) {
    out = await api("/api/log",
      { ...buildPayload(), ...theFight({ run: r.run, ...win, limit, skip: events.length }) });
    if (!recordState || recordState.key !== key) return;  // the result moved on
    const got = (out && out.events) || [];
    events.push(...got);
    dropped = (out && out.dropped) || 0;
    // NOTHING LEFT, or nothing coming: a page that returns no events cannot be
    // followed by one that does, and stopping on it is what keeps a runaway
    // from turning into forty requests.
    if (!dropped || !got.length) break;
    // THE PANEL COUNTS ITSELF WHILE IT WORKS. A read that takes eight runs is a
    // read that looks hung, which is this repo's own rule about long work.
    recordState.page = page + 1;
    recordState.events = events;
    paintRecord(r);
  }
  if (!recordState || recordState.key !== key) return;
  recordState.loading = false;
  recordState.events = events;
  recordState.dropped = dropped;
  // THE TWO ROSTERS the rows' stack lists index into — the shooter's buffs and
  // the target's debuffs, both positional and both named once rather than per
  // row.
  recordState.rosters = { buffs: (out && out.buffs) || [], debuffs: (out && out.debuffs) || [] };
  // THE FACTOR TABLE, sent once. A row names its factors by their index here,
  // because the same thirteen "did nothing" names on every row of a fight were
  // the largest single share of a 17.2 MB window.
  recordState.factors = (out && out.factors) || [];
  // …AND WHAT A ROW LEFT OUT, filled forward. The weapon's state is identical
  // on every row of a trigger pull and the two stack lists change only when
  // something is applied or expires, so an absent field means "the same as the
  // row before". Done ONCE here rather than at each reader, so nothing
  // downstream has to know the wire is compressed at all.
  let carriedWeapon = null, carriedBuffs = null, carriedDebuffs = null;
  for (const e of recordState.events) {
    if (e.weapon) carriedWeapon = e.weapon; else e.weapon = carriedWeapon;
    if (e.kind !== "damage") continue;
    if (e.buffs) carriedBuffs = e.buffs; else e.buffs = carriedBuffs;
    if (e.debuffs) carriedDebuffs = e.debuffs; else e.debuffs = carriedDebuffs;
  }
  recordState.error = out && out.ok === false ? out.error : null;
  paintRecord(r);
}

/// HOW MANY ROWS THE TABLE HOLDS AT ONCE.
///
/// The record covers the WHOLE fight — that was the point of paging the fetch
/// — and the densest build measured is 24,652 events. A table of 24,652 rows is
/// ~250,000 cells, and the browser lays every one of them out on every repaint
/// of the result panel: picking an enemy, scrubbing the replay, or simply
/// re-rendering froze the page for seconds.
///
/// SO THE FETCH AND THE VIEW ARE PAGED SEPARATELY, which is the whole fix: the
/// stream in memory is still the entire fight — `Copy as text` writes all of
/// it, and a floating number can still name its row — and only what is on
/// SCREEN is bounded. A reader looks at one screenful either way.
const REC_PAGE = 500;

/// THE RECORD'S OWN WINDOW, while one is open.
///
/// Asked for as "open the combat record in a whole new page, it is very long
/// and very big and should not be in this window". It is
/// the same markup: the parent keeps the state and calls the same
/// `recordBody`/`wireRecord` against the child's host, so there is ONE
/// implementation of the table and the window is only where it is drawn.
let recWin = null;
/// The result the open record explains, so the window can be repainted — and
/// handed back to the panel — without the caller that opened it.
let recordResult = null;

const recWinOpen = () => !!(recWin && !recWin.closed && recWin.document);

/// WHERE THE TABLE GOES: the child's host while a window is open, this page's
/// otherwise. Every paint goes through it, so nothing else has to know.
function recordHostEl() {
  if (recWinOpen()) {
    const el = recWin.document.getElementById("rec-host");
    if (el) return el;
  }
  return $("rec-host");
}

/// OPEN IT. The child is written rather than fetched: it is this app's own
/// stylesheet over one host element, and a real navigation would boot a second
/// copy of the whole SPA — a second wasm module, a second worker fleet — to
/// display a table the parent already holds.
function openRecordWindow() {
  if (recWinOpen()) { recWin.focus(); return; }
  const w = window.open("", "wfsim-record", "width=1500,height=900");
  // A BLOCKED POPUP IS NOT AN ERROR AND NOT A SILENCE: the table stays where it
  // is and the panel says why, which is the only outcome the reader can act on.
  if (!w) { recWin = null; paintRecord(recordResult); return; }
  recWin = w;
  const doc = w.document;
  doc.open();
  doc.write(`<!doctype html><meta charset="utf-8">`
    + `<meta name="viewport" content="width=device-width,initial-scale=1">`
    + `<title>${escHtml(tr("Combat record"))} · WFSim</title>`
    + `<link rel="stylesheet" href="/style.css">`
    + `<body><div class="rec recwin" id="rec-host"></div>`);
  doc.close();
  // THE READER'S OWN THEME AND LANGUAGE, copied rather than re-derived — the
  // page decides both and a second answer here would be a second setting.
  doc.documentElement.lang = document.documentElement.lang || "en";
  doc.documentElement.className = document.documentElement.className;
  doc.body.className = document.body.className;
  // CLOSING IT HANDS THE TABLE BACK, rather than leaving the panel showing a
  // window that is not there any more.
  w.addEventListener("pagehide", () => {
    recWin = null;
    paintRecord(recordResult);
  });
  paintRecord(recordResult);
}

function paintRecord(r) {
  if (r) recordResult = r;
  const host = recordHostEl();
  if (host) {
    // THE STATE HAS TO BE ABOUT THIS RUN. A record explains ONE engagement, and
    // this now paints on every result render — a stored result picked from the
    // list, an enemy chosen in the roll call — so a record left over from the
    // previous run would be drawn under the new one's heading.
    const st = recordState && recordResult && recordState.key === recordKey(recordResult)
      ? recordState : null;
    host.innerHTML = st ? recordBody(st) : recordIdle();
    wireRecord(recordResult, host);
  }
  // …AND THE PANEL SAYS WHERE IT WENT. An empty block where the table belongs
  // reads as the feature breaking.
  const inline = $("rec-host");
  if (inline && inline !== host) {
    inline.innerHTML = `<div class="rec-idle">`
      + `<span class="sim-hint">${escHtml(tr("the record is open in its own window"))}</span>`
      + `<button class="ghost-btn small" id="rec-back">${escHtml(tr("Bring it back here"))}</button>`
      + `</div>`;
    const back = inline.querySelector("#rec-back");
    if (back) back.onclick = () => { if (recWinOpen()) recWin.close(); recWin = null; paintRecord(recordResult); };
  }
}

/// WHO THE ROWS ARE ABOUT. A weapon event belongs to NOBODY — a reload is not
/// an enemy's business — so a per-enemy view is a FILTER over one stream rather
/// than the same event copied into every table.
function recordBodies(events) {
  const seen = new Map();
  for (const e of events) {
    if (e.body == null) continue;
    const cur = seen.get(e.body) || 0;
    seen.set(e.body, cur + (e.kind === "damage" ? e.effective : 0));
  }
  return [...seen.entries()].sort((a, b) => b[1] - a[1]);
}

const REC_KINDS = [
  ["all", "everything"], ["own", "own"], ["multishot", "multishot"],
  ["punch_through", "punch through"], ["status", "status"],
  // A SHOT, AN ARRIVAL AND A MISS are weapon events rather than numbers, so
  // they sit under one chip with the reloads and the transmutes — and "only
  // the misses" is its own question, because a pellet that went nowhere is
  // invisible in every other view this app has.
  ["event", "events"], ["miss", "misses"],
];

function recordBody(st) {
  if (st.loading) {
    return `<div class="rec-idle"><span class="sim-hint">${escHtml(tr("reading…"))}${
      st.page ? ` ${escHtml(tr("pass {n}").replace("{n}", st.page + 1))} · ${
        (st.events || []).length.toLocaleString()}` : ""}</span></div>`;
  }
  if (st.error) return `<div class="rec-idle"><span class="sim-hint">${escHtml(st.error)}</span></div>`;
  const events = st.events || [];
  if (!events.length) {
    return `<div class="rec-idle"><span class="sim-hint">${escHtml(tr("nothing happened in this window"))}</span></div>`;
  }
  const bodies = recordBodies(events);
  const pick = st.body == null ? (bodies.length ? bodies[0][0] : null) : st.body;
  const rows = events.filter((e) => e.body == null || e.body === pick);
  const shown = rows.filter((e) => recordPasses(e, st.filter));
  const n = (x) => Math.round(x).toLocaleString();
  // ONE SCREENFUL OF THE STREAM — see `REC_PAGE`. `at` is clamped rather than
  // trusted: the list under it changes length whenever the filter or the body
  // does, and a stale offset past the end would draw an empty table over a
  // fight that has thousands of rows in it.
  const at = Math.max(0, Math.min(st.at || 0, Math.max(0, shown.length - 1)));
  const page = shown.slice(at, at + REC_PAGE);

  const chips = bodies.map(([b, dmg]) =>
    `<button class="pchip${b === pick ? " sel" : ""}" data-recbody="${b}">${
      escHtml(b === 0 ? tr("aimed") : `e${b + 1}`)}<span class="ct">${n(dmg)}</span></button>`).join("");
  const kinds = REC_KINDS.map(([k, label]) =>
    `<button class="pchip${st.filter === k ? " sel" : ""}" data-reckind="${k}">${escHtml(tr(label))}</button>`).join("");

  const dmg = shown.filter((e) => e.kind === "damage").length;
  // THE SLICE THIS STREAM ACTUALLY COVERS: where it was asked to start, and
  // where it ran out — which is the LAST EVENT in it when the cap bit, not the
  // window it asked for.
  const cut = st.dropped > 0 || (st.from || 0) > 0;
  const window0 = cut ? (st.from || 0) : null;
  const window1 = cut ? events[events.length - 1].t : null;
  return `<div class="rec-tools">
      ${bodies.length > 1 ? `<span class="tlabel">${escHtml(tr("whose"))}</span>${chips}<span class="rec-sep"></span>` : ""}
      <span class="tlabel">${escHtml(tr("only"))}</span>${kinds}
      <span class="rec-sep"></span>
      <button class="ghost-btn small" id="rec-copy">${escHtml(tr("Copy as text"))}</button>${
      // …AND A WINDOW OF ITS OWN, offered only where it is not already in one.
      recWinOpen() ? "" :
        ` <button class="ghost-btn small" id="rec-pop">${escHtml(tr("Open in its own window"))}</button>`}
    </div>
    <div class="rec-count">${escHtml(tr("{n} numbers popped").replace("{n}", n(dmg)))}${
      // WHICH SLICE OF THE FIGHT THIS IS. Silent for a stream that covers the
      // whole engagement, which is most of them — and never silent when it does
      // not, because a window nobody is told about reads as the whole fight.
      window0 != null
        ? ` · ${escHtml(tr("{a}s to {b}s of the fight")
            .replace("{a}", window0.toFixed(1)).replace("{b}", window1.toFixed(1)))}`
        : ""}${
      st.dropped ? ` · ${escHtml(tr("{n} more did not fit").replace("{n}", n(st.dropped)))}` : ""}${
      // …AND AN OFFER TO GO AND GET THEM. The cap is a default, not a verdict:
      // a reader who came here to check a number against a recording wants the
      // whole fight, and the cost of that is theirs to spend. It says the size
      // rather than hiding it, which is the same rule the cap itself follows.
      st.dropped
        ? ` <button class="ghost-btn small" id="rec-all">${escHtml(tr("read the whole fight"))}</button>`
          + `<span class="sim-hint"> ${escHtml(tr("about {mb} MB").replace("{mb}",
              (((events.length + st.dropped) * 481) / 1e6).toFixed(0)))}</span>`
        : ""}</div>
    ${recordPager(at, shown.length)}
    <div class="rec-scroll"><table class="rec-t">
      <thead><tr>
        <th>${escHtml(tr("time"))}</th><th>${escHtml(tr("damage source"))}</th>
        <th>${escHtml(tr("part"))}</th>
        <th class="num">${escHtml(tr("damage"))}</th>
        <th>${escHtml(tr("procs"))}</th>
        <th>${escHtml(tr("where the number comes from"))}</th>
        <th>${escHtml(tr("weapon"))}</th>
        <th>${escHtml(tr("buffs up"))}</th>
        <th>${escHtml(tr("before · target"))}</th>
        <th>${escHtml(tr("statuses on the target"))}</th>
      </tr></thead>
      <tbody>${page.map((e) => recordRow(e, st.rosters || { buffs: [], debuffs: [] })).join("")}</tbody>
    </table></div>
    ${recordPager(at, shown.length)}`;
}

/// WHICH SCREENFUL OF THE LIST THIS IS, above the table and below it — a reader
/// who has scrolled to the bottom of five hundred rows is exactly the reader
/// who wants the next five hundred, and sending them back to the top for the
/// control would be the whole point of paging thrown away.
///
/// It draws NOTHING for a list that fits, which is most of them: a pager on a
/// forty-row record is furniture that says the same thing twice.
function recordPager(at, total) {
  if (total <= REC_PAGE) return "";
  const to = Math.min(total, at + REC_PAGE);
  const step = (target, label, on) => on
    ? `<button class="pchip" data-recat="${target}">${escHtml(label)}</button>`
    : `<button class="pchip" disabled>${escHtml(label)}</button>`;
  return `<div class="rec-pager">
    ${step(0, "«", at > 0)}
    ${step(Math.max(0, at - REC_PAGE), "‹", at > 0)}
    <span class="tlabel">${escHtml(tr("{a}–{b} of {n}")
      .replace("{a}", (at + 1).toLocaleString())
      .replace("{b}", to.toLocaleString())
      .replace("{n}", total.toLocaleString()))}</span>
    ${step(at + REC_PAGE, "›", to < total)}
    ${step(Math.max(0, (Math.ceil(total / REC_PAGE) - 1) * REC_PAGE), "»", to < total)}
  </div>`;
}

function recordPasses(e, filter) {
  if (filter === "all") return true;
  if (filter === "event") return e.kind !== "damage";
  if (filter === "miss") return e.kind === "miss";
  return e.kind === "damage" && e.origin === filter;
}

const REC_POOL = { shield: "on the shield", health: "through to health", overguard: "on overguard" };

/// A STACK LIST AS CHIPS, with the ones at zero left out. Both sides of a row
/// use it: the shooter's buffs and the target's debuffs are the same shape seen
/// from opposite ends, so they are drawn by one function.
///
/// IT NAMES THEM THE WAY THE REPLAY'S OWN TABLES DO. `tr(id)` for a roster id
/// is the id, so a Chinese reader gets `corrosion`, `on_kill_multishot` and
/// `arcane:secondary_enervate` in a column whose whole job is to say what was
/// up, while the chart two blocks down says 腐蚀 and the
/// buff's own card name. Two spellings of one thing, which is the mistake this
/// panel exists to stop making.
function recStacks(list, roster, cls, now) {
  const nameOf = cls === "on" ? debuffRosterName : buffRosterName;
  const on = (list || [])
    .map(([n, until], i) => [roster[i], n, until])
    .filter(([id, n]) => id && n > 0);
  if (!on.length) return `<span class="z">—</span>`;
  // …AND HOW LONG IT HAS LEFT. The wire carries an ABSOLUTE expiry, so the
  // countdown is this row's own clock subtracted from it — which means two
  // rows a second apart show a buff ticking down rather than both showing the
  // number it had when it was applied. `null` is one whose end the loop does
  // not track and it shows no time at all rather than a guess.
  const left = (until) => {
    if (until == null) return "";
    if (until === "inf") return "";
    const s = until - now;
    return s > 0 ? `<em>${s < 10 ? s.toFixed(1) : Math.round(s)}s</em>` : "";
  };
  return `<div class="rec-stk">${on.map(([id, n, until]) =>
    `<span class="rec-s ${cls}">${escHtml(nameOf(id))}<b>${n}</b>${left(until)}</span>`).join("")}</div>`;
}

/// THE LEDGER, LAYER BY LAYER — and the SHAPE says which mechanic it is.
///
/// A bracket lists its terms and adds them; a snap shows its grid; only a real
/// multiplicative bracket gets a `×`. That is not decoration: printing
/// `×5.706 Condition Overload` puts a multiplication sign in front of a
/// QUOTIENT — the base-damage bracket divided by itself — and
/// `×4.156 element bracket + quantization`, which is the ratio of a per-element
/// snap's two totals. Two numbers the game does not have, both looking exactly
/// like a factor.
///
/// There is no shape here that can draw a quotient, which is what stops it
/// coming back.
function ledgerRows(e) {
  const F = (i) => ((recordState && recordState.factors) || [])[i] || String(i);
  const n = (x) => Math.round(x).toLocaleString();
  const n2 = (x) => x.toLocaleString(undefined, { maximumFractionDigits: 2 });
  const sign = (v) => (v < 0 ? "−" : "+");
  // A TERM OF A BRACKET, with the pair it is a product of where it has one.
  // A TERM NAMES ITSELF ONLY WHEN THE NAME IS EXACT. Where the engine holds a
  // SUM and cannot say which cards are in it, the number goes on alone — a
  // category label there sends a reader looking for a card that matches it and
  // there is none, which is worse than saying nothing.
  const term = (t) => `<span class="lg-term"${t.f == null ? "" : ` data-factor="${
    escHtml(F(t.f))}"`}><i class="lg-op">${sign(t.v)}</i>${n2(Math.abs(t.v))}${
    t.f == null ? "" : `<b>${escHtml(tr(F(t.f)))}</b>`}${
    t.o ? `<em>${n2(t.o[0])} × ${n2(t.o[1])}</em>` : ""}</span>`;

  return (e.layers || []).map((l) => {
    if (l.k === "b") {
      return `<div class="lg lg-b">
        <span class="lg-lbl">${escHtml(tr(F(l.f)))}</span>
        <span class="lg-body">${(l.t || []).map(term).join("")}<span class="lg-sum">= ${
          n2(l.s)}</span><span class="lg-out">${n(l.o)}</span></span></div>`;
    }
    if (l.k === "q") {
      // THE GRID, and the units — because the mechanic IS integer units. A
      // component going from 89.81 units to 90 is a sentence; 2,178.00 going to
      // 2,182.50 is not.
      return `<div class="lg lg-q">
        <span class="lg-lbl">${escHtml(tr("quantization"))}</span>
        <span class="lg-body"><span class="lg-scale">${escHtml(tr("grid"))} ${
          n2(l.scale)}</span><table class="lg-snap"><thead><tr><td></td><td class="num pc">${
          escHtml(tr("of base"))}</td><td class="num">${escHtml(tr("before"))}</td><td></td><td class="num">${
          escHtml(tr("units"))}</td><td></td><td class="num sn">${escHtml(tr("snapped"))}</td><td class="num to">${
          escHtml(tr("after"))}</td></tr></thead>${(l.c || []).map(([ty, from, units, to]) =>
          `<tr><td>${escHtml(DT(ty))}</td><td class="num pc">${
            l.o ? "+" + ((from / (l.scale * 32)) * 100).toFixed(1) + "%" : ""}</td><td class="num">${
            n2(from)}</td><td class="ar">→</td><td class="num">${n2(units)}</td><td class="ar">→</td>${
            ""}<td class="num sn">${Math.round(units)}</td><td class="num to">${n2(to)}</td></tr>`).join("")}</table><span class="lg-out">${n(l.o)}</span></span></div>`;
    }
    // A MULTIPLICATIVE BRACKET — the only shape that earns a sign.
    return `<div class="lg lg-m">
      <span class="lg-lbl"><i class="lg-x">×</i>${n2(l.v)}</span>
      <span class="lg-body"><b>${escHtml(tr(F(l.f)))}</b>${
        l.t ? `<span class="lg-of">${n2(l.head)} × (1${(l.t || []).map(term).join("")})</span>` : ""}${
        F(l.f) === "critical" && e.crit_damage
          ? `<span class="lg-of">1 + ${e.crit} × (${e.crit_damage} − 1)</span>` : ""}<span class="lg-out">${n(l.o)}</span></span></div>`;
  }).join("");
}

function recordRow(e, rosters) {
  const n = (x) => Math.round(x).toLocaleString();
  // A FACTOR IS AN INDEX INTO THE RESPONSE'S OWN TABLE — see `loadRecord`.
  // AT THE TOP, because `const` has no hoisting: declared beside the `return`
  // where the other helpers live, every use above it threw a ReferenceError
  // from inside an async paint, which surfaces as the panel sitting on
  // "reading…" for ever and nothing in the console.
  const F = (i) => ((recordState && recordState.factors) || [])[i] || String(i);
  const w = e.weapon || {};
  // THE WHOLE AMMO PICTURE IN ONE COLUMN — magazine, what is left in reserve,
  // and the Incarnon gauge. They are one question ("can this weapon keep
  // firing, and what is it about to become") and a reader should not have to
  // hold three columns in their head.
  const g = w.gauge;
  const idle = w.idle_magazine;
  const inc = w.form === "transmuted";
  // NOTHING IS HIDDEN HERE. Both magazines are drawn on
  // every row — the one being fired and the one that is not — because a
  // transmute REFILLS the base form's behind the scenes, and a column that
  // showed only the active one made that free reload invisible. Same for the
  // gauge: it is what decides when the form arrives, so it is on every row of
  // the fight rather than only the ones where it moved.
  const wep = `<span class="rec-form ${inc ? "inc" : "base"}">${
    escHtml(tr(inc ? "transmuted" : "base"))}</span>${
    w.magazine_max ? `<span class="rec-mag firing">${escHtml(tr(inc ? "charges" : "magazine"))} ${
      w.magazine} / ${w.magazine_max}</span>` : ""}${
    idle ? `<span class="rec-mag idle">${escHtml(tr(inc ? "magazine" : "charges"))} ${
      idle[0]} / ${idle[1]}</span>` : ""}${
    w.reserve != null ? `<span class="rec-mag">${escHtml(tr("reserve"))} ${n(w.reserve)}</span>` : ""}${
    g ? `<span class="rec-gauge" title="${escHtml(tr("Incarnon gauge"))}"><i style="width:${
      Math.min(100, (g[0] / Math.max(1, g[1])) * 100).toFixed(0)}%"></i></span><span class="rec-mag">${
      escHtml(tr("gauge"))} ${g[0]} / ${g[1]}</span>` : ""}`;

  if (e.kind !== "damage") {
    return `<tr class="rec-evt rec-${escHtml(e.kind)}" data-recevent="${e.id}">
      <td class="rec-t">${e.t.toFixed(3)}${e.cause != null ? `<span class="rec-cause">#${e.cause}</span>` : ""}</td>
      <td colspan="7"><b>${escHtml(tr(recordEventName(e)))}</b>${
        e.into ? ` <span class="sim-hint">${escHtml(tr(e.into === "transmuted" ? "into the transmuted form" : "back to the base form"))}</span>` : ""}${
        e.seconds != null ? ` <span class="sim-hint">${e.seconds.toFixed(2)}s</span>` : ""}${
        e.reason ? ` <span class="sim-hint">${escHtml(tr(e.reason))}</span>` : ""}${
        e.pellets != null ? ` <span class="sim-hint">${e.pellets} ${escHtml(tr("pellets"))}</span>` : ""}</td>
      <td class="rec-wep">${wep}</td><td colspan="2"></td></tr>`;
  }

  // THE CRIT FACTOR CARRIES ITS FORMULA. `×4.40` is a product; `1 + 2 × (2.20
  // − 1)` is something a reader can check against the weapon's card, and the
  // two numbers in it are the only ones they have to trust.
  // A FACTOR CARRIES ITS OWN KEY. The label is translated and the key is not,
  // which is what lets anything asking "did the shield gate apply here" — a
  // check, a bug report, the browser's own find — ask about the FACTOR rather
  // than about the sentence a particular reader happens to see. `data-rpevent`
  // is the same idea for a floating number.
  const mit = (e.mitigation || []).map(([k, v]) =>
    `<span class="rec-f mit" data-factor="${escHtml(F(k))}">×${v}<i>${escHtml(tr(F(k)))}</i></span>`).join("");
  const b = e.before || {};
  const crit = e.crit ? `<span class="rec-crit">${escHtml(tr("crit"))} ${e.crit}</span>` : "";
  // WHICH PELLET, AND WHICH HALF OF ITS ATTACK. A pellet that has an explosion
  // is TWO rows and one pellet, so the two facts are drawn together: three
  // pellets with a radial read as six numbers in three pairs.
  const which = e.pellet != null
    ? `<span class="rec-pel">${escHtml(tr("pellet"))} ${e.pellet}</span><span class="rec-half">${
        escHtml(tr(e.radial ? "explosion" : "direct"))}</span>`
    : "";
  // THE ROW CARRIES ITS OWN NAME. The same id the floating number over the
  // arena points at with `data-rpevent`, so a number on the scene and a line
  // here are the same event under one name rather than two lists that happen
  // to agree.
  // EVERY CELL CARRIES ITS OWN HEADING. On a phone the table becomes a stack
  // of cards — a ten-column, 1080px-wide ledger cannot be read through a 326px
  // window, and the column that matters most is the one furthest off the right
  // edge — and a stacked cell with no heading is a number
  // with nothing to say what it is.
  const L = (k) => ` data-label="${escHtml(tr(k))}"`;
  return `<tr class="rec-dmg rec-${escHtml(e.pool)}" data-recevent="${e.id}">
    <td class="rec-t"${L("time")}>${e.t.toFixed(3)}${e.cause != null ? `<span class="rec-cause">#${e.cause}</span>` : ""}</td>
    <td${L("damage source")}><span class="rec-org rec-o-${escHtml(e.origin)}" data-origin="${escHtml(e.origin)}">${escHtml(tr(e.origin.replace(/_/g, " ")))}</span>${which}</td>
    <td${L("part")}>${e.part ? `<span class="${e.head ? "rec-head" : ""}">${escHtml(tr(e.part))}${e.head ? " ⌖" : ""}</span>` : "<span class=\"z\">—</span>"}</td>
    <td class="num"${L("damage")}><b>${n(e.effective)}</b><span class="rec-pool">${escHtml(tr(REC_POOL[e.pool] || e.pool))}</span>${crit}</td>
    <td class="rec-proc"${L("procs")}>${
      // TWO SIDES, ONE COLUMN. What this instance put ON THE TARGET and what it
      // set off ON THE SHOOTER — the deltas that turn the two state columns
      // into something a reader can check: the next row's state is this row's
      // state plus these.
      (e.procs || []).map((p) => `<span class="rec-p on">${escHtml(DT(p))}</span>`).join("")
      + (e.triggered || []).map((i) => `<span class="rec-p up">${
          escHtml(buffRosterName(((rosters.buffs || [])[i]) || String(i)))}</span>`).join("")
      || "<span class=\"z\">—</span>"}</td>
    <td class="rec-calc"${L("where the number comes from")}><div class="lg lg-base"><span class="lg-lbl">${
      escHtml(tr("base damage"))}</span><span class="lg-body"><span class="lg-out">${n(e.base)}</span></span></div>${
      ledgerRows(e)}${mit ? `<div class="lg-mit">${mit}</div>` : ""}<div class="lg lg-end"><span class="lg-lbl">${
      escHtml(tr("popped"))}</span><span class="lg-body"><span class="lg-exact">${
      escHtml(tr("pool lost"))} ${e.effective.toLocaleString(undefined, { maximumFractionDigits: 4 })}</span><span class="lg-out">${
      n(e.effective)}</span></span></div></td>
    <td class="rec-wep"${L("weapon")}>${wep}</td>
    <td class="rec-buff"${L("buffs up")}>${recStacks(e.buffs, rosters.buffs, "up", e.t)}</td>
    <td class="rec-state"${L("before · target")}>${
      b.overguard > 0 ? `<span data-pool="overguard"><i>${escHtml(tr("overguard"))}</i>${n(b.overguard)}</span>` : ""}<span data-pool="shield"><i>${escHtml(tr("shield"))}</i>${n(b.shield || 0)}</span><span data-pool="health"><i>${escHtml(tr("health"))}</i>${n(b.health || 0)}</span>${
      b.armor > 0 ? `<span data-pool="armour"><i>${escHtml(tr("armour"))}</i>${n(b.armor)}</span>` : ""}${
      // THE SHIELD-GATE WINDOW, drawn even though nothing this app fires takes
      // it: only a melee ground slam does (MEASUREMENTS M61), and melee is not
      // modelled. It is on screen so the claim can be checked the day it is.
      b.shield_gate_until != null
        ? `<span class="rec-gate"><i>${escHtml(tr("gate"))}</i>${b.shield_gate_until.toFixed(2)}s</span>`
        : ""}</td>
    <td class="rec-dbf"${L("statuses on the target")}>${recStacks(e.debuffs, rosters.debuffs, "on", e.t)}</td>
  </tr>`;
}

function recordEventName(e) {
  return {
    shot: "shot", miss: "missed",
    reload_start: "reload begins", reload_end: "reload ends",
    transform_start: "transform begins", transform_end: "transform ends",
    status_expired: "status expired", killed: "killed",
  }[e.kind] || e.kind;
}

/// EVERY CONTROL IS FOUND INSIDE THE HOST, never in `document`.
///
/// The table draws into this page or into the record's own window, and the two
/// are different documents — a `$("rec-copy")` would reach the wrong one, or
/// nothing at all, the moment the window opened. The host is the one thing both
/// paths have.
function wireRecord(r, host) {
  const el = (sel) => (host || document).querySelector(sel);
  const load = el("#rec-load");
  if (load) load.onclick = () => loadRecord(r, 0, null);
  const pop = el("#rec-pop");
  if (pop) pop.onclick = () => openRecordWindow();
  (host || document).querySelectorAll("[data-recat]").forEach((b) => {
    b.onclick = () => { recordState.at = Number(b.dataset.recat); paintRecord(r); };
  });
  const all = el("#rec-all");
  // ROOM FOR WHAT IT SAID DID NOT FIT, plus a fifth — `dropped` is counted one
  // per INSTANCE and a hit on a shielded body is two rows, so asking for
  // exactly the shortfall would come up short again on the one target shape
  // where it matters. The server clamps at 200,000 either way.
  if (all) {
    all.onclick = () => {
      const st = recordState || {};
      loadRecord(r, st.from || 0, st.to, st.limit || RECORD_LIMIT, RECORD_MAX_PAGES);
    };
  }
  // CHANGING WHAT IS LISTED GOES BACK TO THE TOP OF IT. Keeping the row
  // offset across a filter change lands the reader in the middle of a
  // different list, at a position that means nothing.
  (host || document).querySelectorAll("[data-recbody]").forEach((b) => {
    b.onclick = () => { recordState.body = Number(b.dataset.recbody); recordState.at = 0; paintRecord(r); };
  });
  (host || document).querySelectorAll("[data-reckind]").forEach((b) => {
    b.onclick = () => { recordState.filter = b.dataset.reckind; recordState.at = 0; paintRecord(r); };
  });
  const copy = el("#rec-copy");
  if (copy) {
    copy.onclick = () => {
      const txt = (recordState.events || []).map(recordLine).join("\n");
      if (navigator.clipboard) navigator.clipboard.writeText(txt);
      copy.textContent = tr("Copied");
      setTimeout(() => { copy.textContent = tr("Copy as text"); }, 1500);
    };
  }
}

/// ONE ROW AS TEXT, so two runs can be DIFFED. `one_fight` says an answer moved;
/// a diff of two records says WHICH row, which factor, and from what to what —
/// which is the thing nothing in this app could do before.
function recordLine(e) {
  const t = e.t.toFixed(3).padStart(8);
  if (e.kind === "miss") return `${t}  #${e.cause ?? "-"}  [miss]  ${e.reason || ""}`;
  if (e.kind !== "damage") return `${t}  [${e.kind}]`;
  const F = (i) => ((recordState && recordState.factors) || [])[i] || String(i);
  const chain = [...(e.steps || []), ...(e.mitigation || [])]
    .map(([k, v]) => `x${v} ${F(k)}`).join("  ");
  const b = e.before || {};
  return `${t}  #${e.cause ?? "-"}  ${e.origin}  ${e.part || "-"}  ${e.pool}  ${Math.round(e.effective)}`
    + `  | ${Math.round(e.base)}  ${chain}  = ${Math.round(e.raw)}`
    + `  | og ${Math.round(b.overguard || 0)} sh ${Math.round(b.shield || 0)} hp ${Math.round(b.health || 0)}`
    + `  | ${(e.procs || []).join("+") || "-"}`;
}

function replayMarkup(r) {
  const rp = r && r.replay;
  if (!rp || !rp.t || rp.t.length < 2) return { bar: "", curves: "" };
  const named = buffRosterName;
  const dbName = debuffRosterName;
  // WHOSE DEBUFFS. `rp.tracked` names the bodies the replay followed — the
  // aimed one first — and this is the index into it. The selection lives
  // OUTSIDE the render (`replayFoe`) so picking an enemy survives a scrub and
  // a re-run, which is the same rule every fold on this panel follows.
  const dBody = replayFoeIdx(rp);
  // WHICH ENEMY, as chips. Drawn only when there is a choice — one body is the
  // fight this app has always run and needs no control.
  const foeChips = (rp, sel) => {
    const ids = rp.tracked || [];
    if (ids.length < 2) return "";
    const hit = (r.bodies || []).length;
    const more = Math.max(0, hit - ids.length);
    // BY DAMAGE, HARDEST HIT FIRST. The engine follows the
    // aimed body plus the hardest-hit few, and `tracked` came back in ITS
    // order, which is an implementation detail of who got a slot rather than an
    // answer to the question a reader is asking — "who took the most" is the
    // reason to open this table at all.
    //
    // THE ORDER IS THE DISPLAY'S, NOT THE DATA'S. `data-rpfoe` stays the index
    // into `tracked`, because `dstacks[k]` is that body's series and reordering
    // the list itself would draw one body's chip over another's debuffs.
    const dmgOf = Object.fromEntries((r.bodies || []).map((b) => [b.id, b.damage || 0]));
    const order = ids.map((id, k) => k)
      .sort((a, b) => (dmgOf[ids[b]] || 0) - (dmgOf[ids[a]] || 0));
    return `<div class="rp-foes">${
      order.map((k) => `<button type="button" class="rp-foe${k === sel ? " sel" : ""}" data-rpfoe="${
        k}" title="${escHtml(k === 0
          ? tr("the body the weapon was on")
          : tr("an enemy the shot reached"))}">${escHtml(ids[k])} <span class="sm">${
        // THE NUMBER IT IS SORTED BY, on the chip. An order nobody can check is
        // an order nobody trusts, and this is the whole reason the chips exist.
        escHtml(sig2(dmgOf[ids[k]] || 0))}${
        k === 0 ? ` · ${escHtml(tr("aimed"))}` : ""}</span></button>`).join("")
    }${more > 0
      ? `<span class="rp-foe-more">${escHtml(
          tr("+{n} more took damage and are not followed").replace("{n}", more))}</span>`
      : ""}</div>`;
  };
  const dRoster = rp.debuffs || [];
  const dSeries = (rp.dstacks || [])[dBody] || [];
  const W = 600, H = 28;
  const curveRows = (roster, series, name, kind) => roster.map((b, i) => {
    // WHAT IS DRAWN, which is the stack count on an ordinary row and the number
    // the stacks are worth on a value-capped one. Everything below — the area,
    // the average, the dead bands, the ramp — is computed on this, so a clamped
    // pile draws the flat plateau it actually is instead of a line climbing
    // past its own ceiling.
    const raw = series[i] || [];
    const s = b && b.value ? raw.map((n) => rpValueOf(b, n)) : raw;
    const max = b && b.value ? b.value.max
      : Math.max(1, rpUncapped(b) ? Math.max(...s) : b.max);
    const px = (j) => (j / (s.length - 1)) * W;
    const py = (v) => H - 1 - (v / max) * (H - 2);
    const pts = s.map((v, j) => `${px(j).toFixed(1)},${py(v).toFixed(1)}`).join(" ");
    const mean = s.reduce((a, v) => a + v, 0) / (s.length || 1);
    const up = s.filter((v) => v > 0).length / (s.length || 1);
    // TWO DECIMALS, which is what made the "impossible 100%" go away for
    // real: 99.83% is the truth, and rounding it to a whole number was the
    // only thing that ever made it look like a perfect run. `100.00%` now
    // means every single frame was up, and nothing else prints it.
    const upPct = (up * 100).toFixed(2);
    const offPct = (100 - up * 100).toFixed(2);
    // ...and the thing the 100% was hiding: how long the ramp took. This is
    // the answer to "初始肯定要花时间" as a number rather than a rounding.
    const iFull = rpUncapped(b) && !(b && b.value) ? -1 : s.findIndex((v) => v >= rpCeil(b));
    const ramp = iFull < 0
      ? tr("never full")
      : `${tr("full at")} ${(iFull * rp.frame_seconds).toFixed(2)}s`;
    // WHERE IT WAS OFF. A buff at zero is not a low buff, it is an absent one,
    // and a flat line along the axis says that far too quietly — the run that
    // never earned a stack and the run that lost them all draw the same
    // picture. Every zero stretch gets a band.
    const dead = [];
    for (let j = 0; j < s.length; j++) {
      if (s[j] > 0) continue;
      const from = j;
      while (j + 1 < s.length && s[j + 1] === 0) j++;
      dead.push(`<rect class="rp-dead" x="${px(from).toFixed(1)}" y="0" width="${Math.max(1, px(j) - px(from)).toFixed(1)}" height="${H}"/>`);
    }
    return `<div class="rp-row" data-${kind}="${i}">
      <div class="rp-head">
        <span class="rp-caret">▾</span>
        <span class="rp-name">${escHtml(name(b.id))}</span>
        <span class="rp-stat">${escHtml(tr("avg"))} ${b && b.value ? rpFmtVal(b, mean) : mean.toFixed(2)}/${rpCap(b)} · ${escHtml(tr("uptime"))} ${upPct}%${up < 1 ? ` · <span class="rp-off">${escHtml(tr("inactive"))} ${offPct}%</span>` : ""} · ${escHtml(ramp)}</span>
        <span class="rp-now" data-now="${i}" data-series="${kind}">${b && b.value ? rpFmtVal(b, s[s.length - 1]) : s[s.length - 1]}/${rpCap(b)}</span>
      </div>
      <div class="rp-chart">
        <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">
          ${dead.join("")}
          <polygon class="rp-area" points="0,${H} ${pts} ${W},${H}"/>
          <line class="rp-mean" x1="0" x2="${W}" y1="${py(mean).toFixed(1)}" y2="${py(mean).toFixed(1)}"><title>${escHtml(tr("avg"))} ${mean.toFixed(2)}</title></line>
          <polyline class="rp-line" points="${pts}"/>
          <rect class="rp-ahead" data-ahead="${i}" data-series="${kind}" x="${W}" y="0" width="0" height="${H}"/>
          <line class="rp-cur" data-cur="${i}" data-series="${kind}" y1="0" y2="${H}" x1="${W}" x2="${W}"/>
        </svg>
      </div>
    </div>`;
  }).join("");
  const rows = curveRows(rp.buffs, rp.stacks, named, "buff");
  // THE TARGET'S SIDE OF THE SAME FIGHT. Symmetric with the buff table on
  // purpose — same rows, same uptime, same dead bands. A
  // DEATH IS NOT A NEW SERIES: the arena replaces the body it kills and every
  // stack goes with it, so a respawn reads as the curve dropping to zero and
  // climbing again, and the gap counts
  // against uptime. That is what makes the table worth reading — the ramp you
  // pay for on every body is the thing a single averaged number hides.
  //
  // Rows the run never touched are dropped rather than drawn flat: the roster
  // is every status the engine models, and thirteen empty charts would bury the
  // three that moved. A buff row is kept even at zero because the BUILD claimed
  // it; nothing claims a debuff except the fight.
  const dRows = curveRows(
    // A STORED RESULT PREDATES THIS TABLE and carries no debuff series at all —
    // `lastResult` is saved in the scenario preset and replayed on boot, so a
    // payload written by yesterday's build is the FIRST thing this code sees on
    // a returning visitor's machine. It cost the whole app: an unguarded
    // `.filter` on `undefined` threw inside `restoreState`, which is upstream
    // of everything, so the page did not fail to draw a table — it failed to
    // start (reported 2026-08-11).
    dRoster.filter((_, i) => (dSeries[i] || []).some((v) => v > 0)),
    dSeries.filter((s) => (s || []).some((v) => v > 0)),
    dbName, "debuff");
  // …AND HOW MANY NEVER MOVED, said out loud.
  //
  // A row the run never touched is dropped, because seventeen flat lines bury
  // the three that moved. That is a real filter and it looks exactly like a
  // CAP from the reader's side — which is how it was reported: DoTs that were
  // on the enemy and not on the chart. They were missing for a different
  // reason (two whole families had no row at all — `DEBUFF_ROSTER`), but the
  // silence was the same either way.
  //
  // So the omission is counted rather than hidden, which is the rule the body
  // roll call already follows one panel up.
  const dQuiet = dRoster.length - dRoster
    .filter((_, i) => (dSeries[i] || []).some((v) => v > 0)).length;
  // TWO pieces, deliberately far apart. The transport
  // belongs at the top, next to the numbers it drives; the CURVES are charts
  // and belong with the other chart, under the DPS curve. Moving both up put
  // a wall of graphs above the result they explain.
  const bar = `
      <h3>${escHtml(tr("Replay"))}</h3>
      <div class="rp-bar">
        <button id="rp-play" class="ghost-btn small rp-play">▶ ${escHtml(tr("play"))}</button>
        ${ddButton("rp-speed", {
          value: 5,
          items: REPLAY_SPEEDS.map((sp) => ({ value: sp, label: `${sp}x` })),
        })}
        <input id="rp-scrub" class="rp-scrub" type="range" min="0" max="${rp.t.length - 1}" value="${rp.t.length - 1}">
        <span id="rp-clock" class="rp-clock">${rp.t[rp.t.length - 1].toFixed(0)}s / ${rp.t[rp.t.length - 1].toFixed(0)}s</span>
      </div>
      <div class="rp-pools" id="rp-pools"></div>`;
  // ---- WHERE THE DAMAGE WENT ------------------------------------------
  //
  // A SECOND COPY OF THE SCENE, and that is the point:
  // setting up a fight and reading one are two things. The scenario's canvas is
  // where a body is PLACED — draggable, with its distance shortcuts and its
  // +1/+8. This one is read-only, coloured by what each body TOOK, and clicking
  // a body picks it. Neither is the other's control and neither can be mistaken
  // for it.
  //
  // Only when there is a crowd: one body is the fight this app has always run
  // and its picture is already on the scenario.
  // THE ROLL CALL IS THE RESULT's, not the replay's: `bodies` is a mean over
  // every run, while a replay is ONE engagement. Two different questions and
  // two different objects, joined here by the id the page gave each body.
  // HARDEST HIT FIRST, like the chips above it — the two are the same list
  // read two ways, so they are ordered the same way. A copy
  // rather than a sort in place: `r.bodies` is the stored result and a render
  // does not get to reorder it.
  const bodyRows = [...(r.bodies || [])].sort((a, b) => (b.damage || 0) - (a.damage || 0));
  // ONE TEMPLATE, WHATEVER THE FIGHT IS. This block was
  // gated on `bodyRows.length > 1` and called `crowd`, so a single-target
  // simulation drew no scene, no roll call — and no DAMAGE POPS, since the
  // layer they float in is appended to the scene. The one output that is a
  // discrete thing that happened at a place at a time was invisible in the
  // commonest fight this app runs.
  //
  // THE SPECIAL CASE WAS THE MISTAKE, not the missing feature. A fight is a
  // scene with N bodies and N=1 is just N=1: it has a shooter, a target, a
  // distance and an aim point, which is exactly what the SCENARIO's own canvas
  // draws for it. A result that changes shape with the body count is a second
  // template nobody asked for, and the reader has to learn both.
  const crowd = bodyRows.length
    ? `<div class="rp-scene" id="rp-scene"></div>`
      + `<table class="rp-roll"><tbody>${bodyRows.map((b) => {
          const top = Math.max(...bodyRows.map((x) => x.damage)) || 1;
          const share = b.damage / top;
          const on = (rp.tracked || []).indexOf(b.id);
          return `<tr class="rp-rollrow${on === dBody ? " sel" : ""}${
            on < 0 ? " off" : ""}"${on >= 0 ? ` data-rpfoe="${on}"` : ""}>`
            + `<td class="nm">${escHtml(b.id)}${
              b.aimed ? ` <span class="sm">${escHtml(tr("aimed"))}</span>` : ""}</td>`
            + `<td class="bar"><span style="width:${(share * 100).toFixed(1)}%"></span></td>`
            + `<td class="num">${Math.round(b.damage).toLocaleString()}</td></tr>`;
        }).join("")}</tbody></table>`
      // WHAT IS NOT CLICKABLE, and why. A row the replay did not follow has no
      // debuff series to show, and saying so beats a dead click.
      + ((rp.tracked || []).length < bodyRows.length
        ? `<div class="rp-foe-more">${escHtml(
            tr("+{n} more took damage and are not followed")
              .replace("{n}", bodyRows.length - (rp.tracked || []).length))}</div>`
        : "")
    : "";

  const curves =
    (crowd
      ? foldBlock("where", tr("Where the damage went"),
          tr("every body that took something, and how much — click one to read its debuffs"),
          crowd)
      : "")
    + foldBlock("buffs", tr("Buff coverage"), tr("live stacks through the engagement"), rows)
    + (dRows
      ? foldBlock("debuffs", tr("Debuff coverage"),
          tr("what was on the target — a respawn is the same target, so its stacks drop to zero and climb again"),
          // WHOSE, and it is a control rather than a caption. One body is one
          // chip; the fight this app ran until 2026-08-17 has exactly one and
          // draws no chips at all, so a single-target replay looks the way it
          // always did.
          //
          // THE CAP IS SAID OUT LOUD. A replay follows the aimed body plus the
          // hardest-hit few (`REPLAY_TRACKED`) because a series is 18 KB and a
          // 19x19 ruler would be 6.5 MB — so when more bodies took damage than
          // were followed, the line says how many. An absence would read as
          // "that is everyone".
          foeChips(rp, dBody) + dRows + (dQuiet > 0
            ? `<div class="rp-foe-more">${escHtml(
                tr("{n} more statuses this engine models never landed and are not drawn")
                  .replace("{n}", dQuiet))}</div>`
            : ""))
      : "");
  return { bar, curves };
}

// Re-read the WHOLE result panel at frame `i` — KPIs, the damage meter, the
// DPS curve, the buff curves, the target's pools.
//
// This is what makes it a replay rather than a cursor. The
// panel is rendered ONCE at its final state and then re-read in place:
// rebuilding the markup sixty times a second would drop every open sub-row,
// every scroll position and the caret you just clicked.
//
// It starts at the LAST frame, which is the finished fight — the same numbers
// the panel would show with no replay at all. Playing rewinds to 0 and walks
// forward; stopping anywhere leaves the panel reading that instant.
function replayApply(rp, i) {
  const n = (x) => Math.round(x || 0).toLocaleString();
  const pc = (x) => `${((x || 0) * 100).toFixed(1)}%`;
  const last = rp.t.length - 1;
  const frac = last > 0 ? i / last : 1;

  $("rp-clock").textContent = `${rp.t[i].toFixed(1)}s / ${rp.t[last].toFixed(0)}s`;
  $("rp-scrub").value = i;
  // A FIXED GRID, not a flowing row. Every value here
  // changes on every frame, and a flex row re-measures itself each time — the
  // labels slide left and right for the whole playback, which reads as the
  // page shaking. Fixed columns and tabular figures hold still, and the grid
  // is what lets a second and third enemy join without a re-layout.
  const cell = (label, v) =>
    `<span class="rp-cell"><i>${escHtml(label)}</i><b>${v}</b></span>`;
  $("rp-pools").innerHTML =
    cell(tr("Overguard"), n(rp.og[i])) +
    cell(tr("Shield"), n(rp.sh[i])) +
    cell(tr("Health"), n(rp.hp[i])) +
    cell(tr("Damage"), n(rp.dmg[i])) +
    cell(tr("Kills"), rp.kills[i]);

  // The headline. KPM is `kill_progress / minutes`, and `kill_progress` is
  // kills plus the fraction of the CURRENT target's pool already gone — which
  // the frames carry directly, so it is derived here rather than shipped as a
  // fourth series that could disagree with them.
  const hero = document.querySelector("[data-hero]");
  if (hero) {
    const pool0 = (rp.og[0] || 0) + (rp.hp[0] || 0) + (rp.sh[0] || 0);
    const left = (rp.og[i] || 0) + (rp.hp[i] || 0) + (rp.sh[i] || 0);
    const progress = (rp.kills[i] || 0) + (pool0 > 0 ? 1 - left / pool0 : 0);
    const mins = rp.t[i] / 60;
    // THE SAME METRIC THE HEADLINE WAS DRAWN IN, read back by id rather than
    // asked "is it dps": the ticker has to agree with the number it replaces.
    // The replay's own series is what it reads, so the field is looked up on it.
    const hm = metricOf(hero.dataset.hero);
    const v = hm.per_minute
      ? (mins > 0 ? progress / mins : 0).toFixed(2)
      : n((rp.kpi && rp.kpi[hm.field] ? rp.kpi[hm.field][i] : 0));
    const unit = hero.querySelector(".hero-unit");
    hero.textContent = v;
    if (unit) hero.appendChild(unit);
  }

  // KPIs. Rates are fractions, counters are counts, DPS is a number — the
  // key says which, so a new KPI needs no new branch here.
  const k = rp.kpi || {};
  document.querySelectorAll("[data-kpi]").forEach((el) => {
    const key = el.dataset.kpi, s = k[key];
    if (!s) return;
    el.textContent = key === "crit_tier" ? (s[i] || 0).toFixed(2)
      : /_rate$/.test(key) ? pc(s[i])
      : n(s[i]);
  });

  // The damage meter, rescaled to the damage dealt SO FAR: the bars are a
  // composition, and a composition of a fight in progress is read against
  // that fight, not against its end.
  const byKey = {};
  (rp.sources || []).forEach((s) => {
    byKey[s.source] = s.dmg;
    (s.by_type || []).forEach((ty) => { byKey[`${s.source}::${ty.type}`] = ty.dmg; });
  });
  let total = 0, max = 0;
  (rp.sources || []).forEach((s) => { total += s.dmg[i]; max = Math.max(max, s.dmg[i]); });
  document.querySelectorAll("#sim-results [data-mk]").forEach((el) => {
    const s = byKey[el.dataset.mk];
    if (!s) return;
    const v = s[i];
    const sub = el.classList.contains("sub");
    // A sub-row is drawn against its own source's bar, exactly as at the end.
    const own = sub ? (byKey[el.dataset.mk.split("::")[0]] || [])[i] || 1 : max || 1;
    const bar = el.querySelector(".mbar i");
    if (bar) bar.style.width = `${Math.max(0, (v / own) * 100).toFixed(1)}%`;
    const val = el.querySelector(".mval");
    if (val) val.textContent = `${n(v)} · ${total > 0 ? ((v / total) * 100).toFixed(1) : "0.0"}%`;
  });

  // The DPS curve: everything past `t` is greyed rather than removed, so the
  // shape you are walking through stays legible.
  const svg = $("tl-svg");
  if (svg) {
    const w = Number(svg.viewBox.baseVal.width) || 600;
    const now = $("tl-now"), ahead = $("tl-ahead");
    if (now) { now.hidden = false; now.setAttribute("x1", w * frac); now.setAttribute("x2", w * frac); }
    if (ahead) {
      ahead.hidden = false;
      ahead.setAttribute("x", w * frac);
      ahead.setAttribute("width", w * (1 - frac));
    }
  }

  // The buff curves, same treatment, plus the live count in each header.
  document.querySelectorAll("[data-cur]").forEach((el) => {
    el.setAttribute("x1", 600 * frac); el.setAttribute("x2", 600 * frac);
  });
  document.querySelectorAll("[data-ahead]").forEach((el) => {
    el.setAttribute("x", 600 * frac); el.setAttribute("width", 600 * (1 - frac));
  });
  // THE LIVE COUNT in each header, from whichever side of the fight the row
  // belongs to. The DEBUFF rows index a FILTERED roster — the statuses this run
  // never applied are not drawn — so the row rebuilds the same filter rather
  // than indexing the full one and reading somebody else's series.
  // WHOSE, again — this re-reads the panel at a frame and has to pick the same
  // body the table was DRAWN for, or the live count in each header would belong
  // to somebody else.
  const aBody = replayFoeIdx(rp);
  const dLive = (rp.debuffs || [])
    .map((b, k) => [b, ((rp.dstacks || [])[aBody] || [])[k] || []])
    .filter(([, s]) => s.some((v) => v > 0));
  document.querySelectorAll("[data-now]").forEach((el) => {
    const j = Number(el.dataset.now);
    if (el.dataset.series === "debuff") {
      const [b, s] = dLive[j] || [];
      if (b) el.textContent = `${rpFmt(b, s[i])}/${rpCap(b)}`;
      return;
    }
    // THE SAME QUANTITY THE ROW WAS DRAWN IN — a header that scrubs from a
    // percentage to a stack count would be two charts wearing one label.
    el.textContent = `${rpFmt(rp.buffs[j], rp.stacks[j][i])}/${rpCap(rp.buffs[j])}`;
  });
}

function wireReplay(r) {
  const rp = r && r.replay;
  if (replayState && replayState.raf) cancelAnimationFrame(replayState.raf);
  replayState = null;
  if (!rp || !$("rp-scrub")) return;
  // `pos` is a FLOAT cursor in frames — playback advances it by fractions of
  // a frame per animation tick. Every array read goes through the rounded
  // index: `rp.t[3.7]` is `undefined`, which threw inside the animation
  // callback and killed the loop with no console entry to show for it.
  const st = { data: rp, pos: rp.t.length - 1, i: rp.t.length - 1, playing: false, speed: 5, raf: 0, last: 0 };
  replayState = st;

  const draw = () => {
    const was = st.i;
    st.i = Math.max(0, Math.min(rp.t.length - 1, Math.round(st.pos)));
    replayApply(rp, st.i);
    // THE NUMBERS, and only when the frame actually changed. `tick` runs at the
    // browser's refresh rate and the clock at 1x advances a frame every 300 ms,
    // so spawning per paint would draw the same twelve numbers twenty times.
    if (st.playing) {
      if (st.i !== was) popsDraw(rp, st.i, true);
    } else {
      popsDraw(rp, st.i, false);
    }
  };
  const stop = () => {
    st.playing = false; st.last = 0;
    $("rp-play").textContent = `▶ ${tr("play")}`;
  };
  // THE NUMBERS ARE THE RECORD, so reaching for the replay is what asks for
  // it — and it asks for the WINDOW it is looking at. It is deliberately NOT
  // fetched with the result: a dense fight's stream is megabytes and most runs
  // are never replayed at all, which is the same reason `/api/log` is a query
  // rather than a field on `/api/simulate`.
  //
  // A RECORD IS A WINDOW, AND THE PLAYHEAD SETS IT. The cap is real and it
  // bites on exactly the builds people argue about: the board's leading Laetum
  // deals ~230,000 damage instances over 180 s, so a stream asked for from zero
  // runs out after 14 seconds — 8% of the fight, with the other 92% drawing no
  // numbers at all and nothing on screen saying why. Following the playhead is
  // what makes "the numbers are the record" survive the cap, rather than being
  // true only for the opening.
  let loading = false;
  const recordFor = () => (recordState && shownResult
    && recordState.key === recordKey(r) ? recordState : null);
  /// Is `t` inside the stream we hold? A CUT stream covers only as far as it
  /// actually got, which is the last event in it — not the window it asked for.
  const covers = (t) => {
    const rst = recordFor();
    if (!rst || !rst.events || !rst.events.length) return false;
    const lo = rst.from || 0;
    const hi = rst.dropped
      ? rst.events[rst.events.length - 1].t
      : (rst.to == null ? Infinity : rst.to);
    return t >= lo - 1e-9 && t <= hi + 1e-9;
  };
  const withRecord = async () => {
    const at = rp.t[st.i] || 0;
    if (loading || covers(at)) return;
    loading = true;
    // A SECOND BEFORE THE PLAYHEAD, running forward as far as the cap allows.
    // The lead-in is there so a scrub that lands just after a shot still shows
    // the shot's own row rather than starting mid-volley.
    await loadRecord(r, Math.max(0, at - 1));
    loading = false;
    // The reader may have moved on — another run, another weapon — while the
    // engagement was being re-run.
    if (replayState === st) draw();
  };
  const tick = (now) => {
    if (!st.playing) return;
    // Wall-clock paced, so `speed` means what it says however fast the
    // browser paints: 5x is five seconds of fight per second of watching.
    const dtms = st.last ? now - st.last : 16;
    st.last = now;
    st.pos += (dtms / 1000) * st.speed / rp.frame_seconds;
    if (st.pos >= rp.t.length - 1) { st.pos = rp.t.length - 1; stop(); }
    draw();
    // …AND PLAYING OFF THE END OF THE WINDOW FETCHES THE NEXT ONE. Cheap to
    // ask: `covers` is two comparisons, and `withRecord` returns immediately
    // unless the playhead has actually left the stream we hold.
    withRecord();
    if (st.playing) st.raf = requestAnimationFrame(tick);
  };
  // PICK AN ENEMY — from a chip, from a roll-call row, or from the map. Three
  // views of ONE selection, which is why they share the attribute.
  //
  // The debuff table is the only thing that changes: the buffs are the
  // PLAYER's and belong to no body, and the clock does not move — you are
  // asking "what was on THAT one at this instant", not replaying anything.
  const pickFoe = (k) => {
    replayFoe = k;
    // FROM THE RESULT IN HAND. No simulation, and no storage lookup either —
    // see `shownResult`. Picking an enemy is a question about a run that has
    // already happened and cannot be a reason to lose it.
    if (shownResult) renderResults(shownResult.r, shownResult.at);
    else renderStoredSimResult();
  };
  document.querySelectorAll("[data-rpfoe]").forEach((el) => {
    el.onclick = () => pickFoe(Number(el.dataset.rpfoe));
  });
  // THE MAP, mounted last because it measures the box it was given. It is the
  // RESULT's copy of the scene: read-only, shaded by what each body took, and
  // it picks rather than drags (`mountArena`'s analysis mount).
  const sceneEl = $("rp-scene");
  if (sceneEl && (r.bodies || []).length) {
    // BY ARENA INDEX, which is what the scene draws: 0 is the aimed body and
    // `i + 1` is `formation[i]`. The result names bodies by ID, so the two are
    // joined on the name the page itself gave them.
    const idAt = (i) => (i === 0
      ? (rp.tracked || [])[0]
      : ((sim.formation || [])[i - 1] || {}).id || `e${i + 1}`);
    const top = Math.max(...r.bodies.map((b) => b.damage)) || 1;
    const byId = Object.fromEntries(r.bodies.map((b) => [b.id, b.damage / top]));
    const n = 1 + (sim.formation || []).length;
    const heat = Array.from({ length: n }, (_, i) => byId[idAt(i)] || 0);
    const selIdx = Array.from({ length: n }, (_, i) => i)
      .find((i) => idAt(i) === (rp.tracked || [])[replayFoeIdx(rp)]);
    mountArena(sceneEl, sim, (allEnemies().find((e) => e.id === sim.enemy) || allEnemies()[0]), {
      readonly: true,
      heat,
      selected: selIdx,
      onPick: (i) => {
        const k = (rp.tracked || []).indexOf(idAt(i));
        // A BODY THE REPLAY DID NOT FOLLOW has no series to show, so the click
        // does nothing rather than showing somebody else's.
        if (k >= 0) pickFoe(k);
      },
    });
    // THE LAYER THE NUMBERS FLOAT IN, appended AFTER the mount and not before:
    // `mountArena` takes the host over and rewrites its contents, so a layer
    // created first is wiped by the scene it was meant to sit on. It survives
    // the arena's own repaints because those redraw the CANVAS, not the host.
    const layer = document.createElement("div");
    layer.className = "rp-pops";
    sceneEl.appendChild(layer);
  }
  $("rp-play").onclick = () => {
    if (st.playing) { stop(); return; }
    // Pressing play on a FINISHED fight rewinds it — that is what the button
    // means, and leaving it stuck at the end made it look broken.
    if (st.pos >= rp.t.length - 1) { st.pos = 0; draw(); }
    withRecord();
    st.playing = true; st.last = 0;
    $("rp-play").textContent = `❚❚ ${tr("pause")}`;
    st.raf = requestAnimationFrame(tick);
  };
  ddReg.get("rp-speed").onPick = (v) => { st.speed = Number(v) || 1; };
  $("rp-scrub").oninput = () => {
    // AFTER the playhead moves, never before: `withRecord` asks for the window
    // around `st.i`, so asking first fetches the window the reader just left.
    stop(); st.pos = Number($("rp-scrub").value); draw();
    withRecord();
  };
  // Collapse one row without losing its place in the group.
  document.querySelectorAll(".rp-row .rp-head").forEach((h) => {
    h.onclick = () => {
      const chart = h.parentElement.querySelector(".rp-chart");
      const open = chart.hidden;
      chart.hidden = !open;
      h.querySelector(".rp-caret").textContent = open ? "▾" : "▸";
    };
  });
  draw();
}

// THE NUMBERS A FIGHT POPS, over the bodies they landed on.
//
// Everything else the replay draws is a CURVE — a pool falling, a stack count,
// a damage total. This is the one thing that is an EVENT: a discrete number at
// a place at a time, which is how the game reports damage and the only view
// where "one big hit" and "twenty small ones" look different.
//
// THEY ARE THE COMBAT RECORD, REPLAYED, not a second account of it. Two lists
// filled from one `log_damage` call hold DIFFERENT SETS, so a number floats
// over a body with no row to explain it — and for a panel whose claim is "this
// is what happened", one-to-one IS the claim.
//
// So `/api/log` is the ledger, the table lists it, this draws it, and every
// number carries the id of its row. The CAP is a DISPLAY decision made here —
// twelve a frame, biggest kept, the rest counted, which is how the game caps
// its own and unavoidable besides at ~320,000 instances over 600 frames.
//
// A DOM OVERLAY RATHER THAN THE CANVAS: the arena repaints on every resize and
// heat change, and a number wants a CSS animation. `pointer-events: none`, so
// the scene underneath still picks.
const POP_KIND_CLASS = {
  direct: "p-direct", crit: "p-crit", head: "p-head", head_crit: "p-headcrit",
  status: "p-status", blast: "p-blast", blast_area: "p-area",
  field: "p-field", extra: "p-extra", arcane: "p-arcane",
};

// WHERE A BODY STANDS, in the scene's own metres. Index 0 is the aimed body and
// `i + 1` is `formation[i]` — the same numbering `damage_by_body`, the roll
// call and the heat map use, so a number lands on the body the rest of the
// panel is talking about.
const popBodyAt = (i) => (i === 0
  ? (sim.target_at || [0, 0.5])
  : (((sim.formation || [])[i - 1] || {}).at || null));

/// HOW MANY NUMBERS ONE FRAME MAY SHOW. Twelve, and the BIGGEST win: keeping
/// the first twelve would be arbitrary — which twelve depends on the order the
/// engine happened to settle them in — while a reader's eye goes to the big
/// one. What did not fit is counted, never swallowed.
const POPS_PER_FRAME = 12;

/// THE RECORD, BUCKETED INTO THE REPLAY'S OWN FRAMES.
///
/// The engine quantises a replay by pushing a frame every `frame_seconds`, so
/// frame `i` covers `(i x fs, (i+1) x fs]` — the same slice of the clock the
/// curves beside it are drawn from. Computed once per record and cached on it,
/// because a scrub redraws a frame on every pointer move.
///
/// It returns null when there is no record for the result on screen, which is
/// the honest answer rather than an empty overlay: the numbers ARE the record,
/// so before it is read there is nothing to draw. `wireReplay` asks for it.
function popFrames(rp) {
  const st = recordState && shownResult
    && recordState.key === recordKey(shownResult.r) ? recordState : null;
  if (!st || st.loading || !st.events) return null;
  const n = rp.t.length;
  if (st.popFrames && st.popFrames.length === n) return st.popFrames;
  const frames = Array.from({ length: n }, () => []);
  for (const e of st.events) {
    if (e.kind !== "damage" || e.body == null || !(e.effective > 0)) continue;
    const i = Math.min(n - 1, Math.max(0, Math.ceil(e.t / rp.frame_seconds) - 1));
    frames[i].push(e);
  }
  st.popFrames = frames.map((list) => {
    if (list.length <= POPS_PER_FRAME) return { v: list, n: 0 };
    const by = [...list].sort((a, b) => b.effective - a.effective);
    return { v: by.slice(0, POPS_PER_FRAME), n: list.length - POPS_PER_FRAME };
  });
  return st.popFrames;
}

/// Spawn one frame's numbers over the scene.
///
/// `live` distinguishes PLAYING from SCRUBBING: playing spawns each frame once
/// as the clock passes it, scrubbing replaces what is on screen with the frame
/// you landed on. Without that distinction a scrub would either stack hundreds
/// of numbers or show none.
function popsDraw(rp, i, live) {
  const scene = $("rp-scene");
  const host = scene && scene.querySelector(".rp-pops");
  if (!host || !rp) return;
  // VIEWBOX TO PIXELS. The result's scene is the SVG mount, which draws in a
  // fixed coordinate space and lets the browser fit it to the box — so a
  // number's place is that map's answer put through the same fit. Doing the
  // arithmetic here rather than reading a DOM box keeps ONE geometry: whatever
  // `__arena` says is where the body was drawn.
  const ar = scene.__arena;
  const svg = scene.querySelector(".ar-svg");
  if (!ar || !ar.vb || !svg) return;
  const sb = svg.getBoundingClientRect();
  if (!sb.width || !sb.height) return;
  // `xMidYMid meet`, which is the default and what `arenaSvg` relies on.
  const k = Math.min(sb.width / ar.vw, sb.height / ar.vh);
  const ox = (sb.width - ar.vw * k) / 2;
  const oy = (sb.height - ar.vh * k) / 2;
  const map = (m) => {
    const [vx, vy] = ar.vb(m);
    return [ox + vx * k, oy + vy * k];
  };
  // THE MODE IS ON THE LAYER, because it decides the ANIMATION and a CSS class
  // is the only thing that can. Parked numbers rise and hold; playing ones
  // float away.
  host.classList.toggle("live", !!live);
  if (!live) host.textContent = "";
  const all = popFrames(rp);
  if (!all) return;
  const frame = all[i];
  if (!frame) return;
  const box = scene.getBoundingClientRect();
  const dx = sb.left - box.left;
  const dy = sb.top - box.top;
  // FANNED, NOT JITTERED. Several numbers land on ONE body in the same instant —
  // a hit, its crit, three status ticks — and scattering them by a hash of their
  // own value still piles them up as often as not. Counting per BODY and
  // stepping each one out along a fixed fan is readable at any count and
  // identical every time the same frame is drawn, which is what a scrub needs.
  //
  // BIGGEST NEAREST THE BODY, because that is the one the reader came for; the
  // rest step outward and up from it.
  const perBody = new Map();
  // HOW MANY DID NOT FIT ON SCREEN, as opposed to how many the frame's own cap
  // dropped. They are the same fact to a reader — "there were more than this" —
  // so they are counted together and stated in one chip.
  let skipped = 0;
  const ordered = [...(frame.v || [])].sort((a, b) => b.effective - a.effective);
  for (const e of ordered) {
    const body = e.body;
    const amount = e.effective;
    const dtype = e.type;
    const kind = e.pop_kind || "direct";
    const at = popBodyAt(body);
    if (!at) continue;
    const [x, y] = map(at);
    const seen = perBody.get(body) || 0;
    perBody.set(body, seen + 1);
    // A RISING COLUMN, not a fan. A fan needs to clear the number's WIDTH and a
    // five-figure number is 45 px wide, so anything narrow enough to look tidy
    // still overlaps; stacking upward only has to clear the line height. The
    // small left/right alternation is there to break the column's edge so two
    // equal numbers are still visibly two.
    // …AND THE COLUMN STAYS INSIDE THE SCENE, or it is not drawn at all.
    //
    // Twelve numbers can all land on ONE body, and twelve is 250 px of column —
    // taller than the gap above a body standing near the top of the map, so the
    // biggest numbers, which are the ones a reader came for, climbed off the
    // panel entirely (seen on the board's leading Laetum, 2026-08-27). A second
    // COLUMN was the first fix and was worse: a six-figure number is ~110 px
    // wide, so the columns ran through each other and produced digits that
    // belonged to neither.
    //
    // So the geometry decides how many fit, and what does not fit joins the
    // count already beside them. That keeps the two claims this layer makes
    // both true: every number drawn names the row it is, and everything not
    // drawn is stated rather than silently missing.
    const fits = Math.max(1, Math.floor((dy + y - 36) / 21) + 1);
    if (seen >= fits) { skipped += 1; continue; }
    // The step clears the LARGEST line here: a headcrit is set at 19 px, so 17
    // put two of them on top of each other. Starting at -32 clears the body's
    // own name and distance labels rather than landing in them.
    const fx = seen === 0 ? 0 : (seen % 2 ? 11 : -11);
    const fy = -32 - seen * 21;
    const el = document.createElement("span");
    el.className = `rp-pop ${POP_KIND_CLASS[kind] || "p-direct"}`;
    el.style.left = `${dx + x + fx}px`;
    el.style.top = `${dy + y + fy}px`;
    const c = dtColor(dtype);
    if (c) el.style.setProperty("--pop-dt", c);
    el.textContent = Math.round(amount).toLocaleString();
    // THE ROW THIS NUMBER IS. `id` is the event's own place in the stream, so
    // a number on the scene and a line in the table below are the same thing
    // under the same name — which is what one-to-one has to mean to be worth
    // claiming.
    el.dataset.rpevent = e.id;
    el.title = `${DT(dtype)} · ${tr(kind)} · #${e.id}`;
    host.appendChild(el);
    if (live) el.addEventListener("animationend", () => el.remove());
  }
  // …AND WHAT DID NOT FIT. Never silent: a cap nobody is told about reads as
  // "that is all of them", which is the one thing it must not.
  const more = (frame.n || 0) + skipped;
  if (more > 0) {
    const chip = document.createElement("span");
    chip.className = "rp-pop p-more";
    // IN THE CORNER, not above the tallest column. One line above the topmost
    // number is one line above the last line that fits, so the chip itself
    // never does — and the one thing on this layer whose whole job is to say
    // "there were more" is the thing clipped off
    // the top. It is a statement about the FRAME rather than
    // about a body, so the frame's own corner is where it belongs.
    // `.rp-pop` is centred on its point, so the corner needs half a chip of
    // clearance or it hangs over the edge it was moved here to stay inside.
    chip.style.left = `${dx + 26}px`;
    chip.style.top = `${dy + 16}px`;
    chip.textContent = `+${more}`;
    chip.title = tr("more numbers than fit here — the biggest are drawn");
    host.appendChild(chip);
    if (live) chip.addEventListener("animationend", () => chip.remove());
  }
}

/// WHAT IS ON SCREEN RIGHT NOW, and the ONLY thing a redraw reads.
///
/// Picking an enemy in the result must not call `renderStoredSimResult`, which
/// looks the result up in a preset collection: a pick is then a bet that the
/// SAVE worked, and every way it could not have takes the result off screen
/// with it. A full disk is one way. A preset that
/// is not in the list is another, and `saveSimResult` returns early on it
/// without storing anywhere. Neither has anything to do with picking an enemy.
///
/// So a redraw takes the object the panel was drawn from. Storage is what
/// survives a RELOAD or a preset switch, and nothing else asks it a question.
let shownResult = null;

function renderResults(r, testedAt) {
  shownResult = { r, at: testedAt };
  const t = r.target || {};
  const pc = pct2; // 2 decimals, more when the value would otherwise vanish
  const n0 = (x) => Math.round(x || 0).toLocaleString();
  const n2 = sig2;
  const killed = (r.kills || 0) >= 1;
  // ONE scoring unit, killed or not: the KILL SCORE
  // (engine `kill_progress`) = whole kills + the fraction of the current
  // target's pool already drained. 0.85% of an EHP is 0.01; two kills and
  // 30% of the next is 2.30. The sub-line adds the context that differs.
  const ttk = killed ? r.duration / r.kills : Infinity;
  // The headline is a RATE, like DPS: kill score PER MINUTE, so a 20-second
  // run and a 120-second one produce comparable numbers.
  // The score itself is the total over the engagement and stays beside it,
  // the same way total damage sits beside DPS.
  const met = metricOf(sim.metric);
  const heroNum = met.per_minute ? n2(metricValue(met, r)) : n0(metricValue(met, r));
  // The UNIT belongs beside the number, not under it: "5.29" on one line and
  // "KPM · …" starting the next read as two facts. Set
  // small and spaced away, so it labels the figure without competing with it.
  const heroUnit = metricLabel(met);
  // HOW FIRM THE NUMBER IS, said beside the number.
  //
  // A mean with no spread invites a reader to compare two builds that differ by
  // less than either one's own run-to-run swing. The range and the deviation
  // are what say whether the gap they are looking at is a gap — and they belong
  // ON the answer rather than folded away under a table nobody opens.
  //
  // ONLY WHERE IT MEANS SOMETHING: one run has no spread to report, and a fight
  // that kills nothing has no kill count to spread.
  const spread = killed && (r.runs || 0) > 1 && r.kills_max > r.kills_min
    ? ` · ${n0(r.kills_min)}–${n0(r.kills_max)} over ${n0(r.runs)} runs (±${sig2(r.kills_std)})`
    : "";
  // …AND THE DEFAULT MEASURE BESIDE IT, when the headline is not it. What a
  // build is FOR is the kill rate, so a reader judging by anything else still
  // wants it — named by the table rather than by the word "KPM", so a third
  // metric borrows the sentence instead of needing a new one.
  const alt = met.id === metricOf().id ? "" : (() => {
    const d = metricOf();
    return `${d.per_minute ? n2(metricValue(d, r)) : n0(metricValue(d, r))} ${metricLabel(d)} · `;
  })();
  const heroSub = alt +
    `${n2(r.score)} kill score in ${n0(r.duration)}s · ` + (killed
    ? `${n0(r.kills)} killed · ~${isFinite(ttk) ? ttk.toFixed(2) : "∞"}s avg per kill`
    : `${pc(r.score)} of one ${LN("enemies", sim.enemy, t.name || "enemy")}'s EHP drained`)
    + spread;
  // No Forma/capacity here — the simulator reports EFFECTS only; build
  // legality is the Builder's business.
  // `k` names the replay series that re-reads this cell. Without it a replay
  // could only move a cursor; with it the whole row is a function of time.
  const kpi = (l, v, k) => `<div class="kpi"><div class="kv"${k ? ` data-kpi="${k}"` : ""}>${v}</div><div class="kl">${tr(l)}</div></div>`;
  // KPI row: damage pace + crit feel + HANDLING feel (shots, reloads,
  // transforms). In THIS product "DPS" always means
  // EFFECTIVE dps — what the target actually lost, armor and on-target
  // amps included; the weapon-side raw number is out (user: in our
  // context every stat accounts for the enemy).
  const kpis = [
    kpi("DPS", n0(r.dps), "dps"),
    // The TIER leads, and the rate is renamed to what it actually measures.
    // "Crit rate" reads as "my crit chance", and it stops being that the
    // moment a build passes 100%: every pellet crits, so it pins at 100%
    // whether the build is at 110% or 410% (group, 2026-07-31). The tier is
    // the same number without that truncation — and the one that multiplies
    // the damage. 1 = yellow, 2 = orange, 3 = red, and it keeps going.
    kpi("Crit tier", (r.crit_tier ?? 0).toFixed(2), "crit_tier"),
    kpi("Pellets crit", pc(r.crit_rate), "crit_rate"), kpi("Orange+", pc(r.big_crit_rate), "big_crit_rate"),
    kpi("Procs", n0(r.procs), "procs"), kpi("Shots", n0(r.shots), "shots"),
    kpi("Reloads", n0(r.reloads), "reloads"), kpi("Transforms", n0(r.transforms), "transforms"),
    // COUNTED, NOT FOUGHT. The row is drawn only where a weapon leaves
    // something standing, and it says BOTH numbers because neither is the
    // mechanic on its own: how many were left, and how many stood at once.
    r.ghosts == null ? "" : kpi("Ghosts", `${n0(r.ghosts)} (${n0(r.ghosts_peak)} ${tr("at once")})`, "ghosts"),
  ].join("");
  // WoW-style damage meter: effective damage BY SOURCE
  // over the whole engagement — what actually hurt the target. The panel's
  // per-shot theory lives in the Builder's Stats, not here.
  const srcs = r.damage_sources || [];
  const srcTotal = srcs.reduce((a, x) => a + x.dmg, 0) || 1;
  const srcMax = (srcs[0] && srcs[0].dmg) || 1;
  // Bucket rows are named; a status row is named by its damage type. `field`
  // and `radial` fell through to `DT()`, which knows damage types only, so
  // they printed their raw wire key in every language.
  const SRC_LABEL = { direct: "Direct hits", radial: "Radial (AoE)",
    field: "Lingering field", arcane: "Arcane (on status)",
    syndicate: "Syndicate radial", "extra hit": "Extra hit (ability)" };
  const srcLabel = (k) => (SRC_LABEL[k] ? tr(SRC_LABEL[k]) : DT(k));
  // A WEAPON-damage row EXPANDS into the damage types it was dealt as — a
  // status row already IS one type, which is what a proc is. Both levels use
  // the same denominator, so every percentage in the meter reads against the
  // engagement total and the numbers still sum to 100%.
  //
  // The shares are the QUANTIZED ones (the vector that actually landed), so
  // they will not match the Builder's panel exactly — the Torid's 164.73
  // Corrosive / 52.02 Magnetic reads 76/24 there and 75/25 here, because
  // quantization snaps each component to a multiple of total/32.
  // A BAR IS COLOURED BY WHAT IT IS, not by where it sits.
  //
  // A damage TYPE gets DE's own colour (style.css, from the wiki's
  // `Module:DamageTypes/data`); a SOURCE — "Direct hits", "Radial (AoE)" — is
  // not a damage type and has no official colour, so it keeps a positional one
  // from the `--s1..8` ramp. That is the split the meter was missing: it
  // coloured everything positionally, so Heat was one colour under a direct hit
  // and another under a field, and neither was Heat's.
  const mbar = (w, ty, c, dim) => {
    const col = dtColor(ty) || `var(--s${c})`;
    return `<div class="mbar"><i style="width:${w.toFixed(1)}%;background:${col}${dim ? ";opacity:.65" : ""}"></i></div>`;
  };
  // The meter is re-read per frame too, so every row carries the key of the
  // series that feeds it — top-level by source, sub-rows by source+type.
  const mkey = (s, ty) => ` data-mk="${escHtml(ty ? `${s}::${ty}` : s)}"`;
  const meter = srcs.map((x, i) => {
    const c = (i % 8) + 1;
    const parts = x.by_type && x.by_type.length > 1 ? x.by_type : null;
    const open = !!parts && simMeterOpen.has(x.source);
    const head = `<div class="mrow${parts ? " exp" : ""}" data-src="${escHtml(x.source)}"${mkey(x.source)} data-c="${c}">
      <span class="mname">${parts ? `<span class="mcaret">${open ? "▾" : "▸"}</span>` : ""}${dtIcon(x.source)}${srcLabel(x.source)}</span>
      ${mbar(x.dmg / srcMax * 100, x.source, c, false)}
      <span class="mval">${n0(x.dmg)} · ${pct2(x.dmg / srcTotal)}</span>
    </div>`;
    if (!parts) return head;
    return head + parts.map((p) => `<div class="mrow sub" data-of="${escHtml(x.source)}"${mkey(x.source, p.type)} data-c="${c}"${open ? "" : " hidden"}>
      <span class="mname">${dtIcon(p.type)}${DT(p.type)}</span>
      ${mbar(p.dmg / srcMax * 100, p.type, c, true)}
      <span class="mval">${n0(p.dmg)} · ${pct2(p.dmg / srcTotal)}</span>
    </div>`).join("");
  }).join("");
  // WHAT THE DAMAGE WAS MADE OF — one stacked bar over the whole engagement,
  // in DE's own colours.
  //
  // The meter above answers "where did it come from" — direct hits, a cloud, a
  // proc. This answers a different question a build actually turns on: what
  // ELEMENTS is that, added up. They are the same damage counted two ways, so
  // both read against the same total and both come to 100%.
  //
  // Aggregated from the meter's own rows rather than from a second field, so
  // the bar cannot disagree with the list under it: a source that splits by
  // type contributes its split, and a source that IS a type (a status row)
  // contributes itself.
  const typeTotals = {};
  for (const x of srcs) {
    const parts = x.by_type && x.by_type.length ? x.by_type : [{ type: x.source, dmg: x.dmg }];
    for (const p of parts) {
      if (!dtKey(p.type)) continue;   // a source name is not a damage type
      typeTotals[dtKey(p.type)] = (typeTotals[dtKey(p.type)] || 0) + p.dmg;
    }
  }
  const typeRows = Object.entries(typeTotals)
    .filter(([, v]) => v > 0)
    .sort((a, b) => b[1] - a[1]);
  const typeSum = typeRows.reduce((a, [, v]) => a + v, 0);
  // Biggest first, so the bar reads left to right in the order the legend
  // does and the eye can match a segment to a line without hunting.
  const composition = typeRows.length ? `
      <h3>${tr("Damage by type")} <span class="sim-hint">${tr("share of the engagement")}</span></h3>
      <div class="dmg-bar">${typeRows.map(([ty, v]) =>
        `<i class="dmg-seg" style="flex:${(v / typeSum).toFixed(5)};background:${dtColor(ty)}" title="${escHtml(DT(ty))} ${pct2(v / typeSum)}"></i>`).join("")}</div>
      <div class="legend">${typeRows.map(([ty, v]) =>
        `<span class="li">${dtIcon(ty)}${escHtml(DT(ty))} <span class="lv">${pct2(v / typeSum)}</span></span>`).join("")}</div>` : "";

  // DPS-over-time curve: the MEDIAN run's per-bucket
  // EFFECTIVE dps. One series — the accent line, recessive grid, hover
  // crosshair + tooltip; no legend needed.
  const tl = r.timeline || [];
  const bucketSecs = (r.duration || 1) / (tl.length || 1);
  const dpsPts = tl.map((v) => v / bucketSecs);
  const tlMax = Math.max(1, ...dpsPts);
  const W = 600, H = 170, PADL = 8, PADR = 8, PADT = 8, PADB = 6;
  const px = (i) => PADL + ((i + 1) / tl.length) * (W - PADL - PADR);
  const py = (v) => PADT + (1 - v / tlMax) * (H - PADT - PADB);
  const pts = dpsPts.map((v, i) => `${px(i)},${py(v)}`).join(" ");
  const tlGrid = [0.25, 0.5, 0.75].map((f) =>
    `<line class="tl-grid" x1="${PADL}" x2="${W - PADR}" y1="${py(tlMax * f)}" y2="${py(tlMax * f)}"/>`).join("");
  const chart = tl.length ? `
      <h3>${tr("DPS over time")} <span class="sim-hint">${tr("median run")}</span></h3>
      <div class="tl-wrap">
        <svg id="tl-svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">
          ${tlGrid}
          <polyline class="tl-line" points="${pts}"/>
          <rect id="tl-ahead" class="tl-ahead" x="${W}" y="0" width="0" height="${H}" hidden/>
          <line id="tl-now" class="tl-now" y1="0" y2="${H}" x1="0" x2="0" hidden/>
          <line id="tl-cross" class="tl-cross" y1="${PADT}" y2="${H - PADB}" hidden/>
        </svg>
        <div class="tl-x"><span>0s</span><span>${n0(r.duration)}s</span></div>
        <div class="tl-ymax">${n0(tlMax)}</div>
        <div id="tl-tip" class="tl-tip" hidden></div>
      </div>` : "";
  const { bar: replayBar, curves: replayCurves } = replayMarkup(r);
  // THE `Detail` TABLE IS GONE. Five of its six rows were the fight restated —
  // the target, its pools, its armour, the shot count — each of which the
  // scenario panel above states while it is being CHOSEN, which is when a
  // reader needs them. The sixth was the answer's own spread, and that has
  // moved onto the answer (`spread`), where a reader deciding between two
  // builds actually looks.
  // THE ASK, BENEATH THE ANSWER. The topbar is chrome and
  // the ask lived only there, which put it as far from the moment this tool
  // delivers anything as a page can put it. This is not an interruption: it is
  // a line of text below the last fold, after the result, and it never moves,
  // blocks, animates or asks twice.
  //
  // IT STATES THE WORK BEFORE IT STATES THE ASK, and both numbers are ones the
  // reader can check against the Detail table directly above it — `runs` is the
  // count they set, and `pellets` is PER RUN on the wire (webapi/src/lib.rs),
  // so the product is the damage instances this answer was actually averaged
  // over. A figure a reader can verify is the only kind worth printing here.
  const askRuns = Math.round(r.runs || 0), askRolls = Math.round(askRuns * (r.pellets || 0));
  const ask = `<p class="sim-ask">${escHtml(trF(
    "{runs} engagements · {rolls} damage instances rolled, on your own machine.",
    { runs: askRuns.toLocaleString(), rolls: askRolls.toLocaleString() }))} ${
    escHtml(tr("Builder, simulator and optimizer stay free for everyone."))} <a href="/support">${
    escHtml(tr("Chip in ↗"))}</a></p>`;
  $("sim-results").innerHTML = `
    <!-- WHAT BECAME OF THIS RUN, above the result and OUTSIDE it. It sat inside the result, under the headline, and read as
         a footnote to the number — which it is not: it is about the RUN, not
         about the damage, and it carries the one sentence a submitter has to
         act on. Its own block, above the thing it is not part of. -->
    <div id="sim-board-outcome" class="board-outcome"></div>
    <div class="results">
      <div class="hero"><div><div class="hero-num" data-hero="${met.id}">${heroNum}<span class="hero-unit">${heroUnit}</span></div><div class="hero-sub">${heroSub}</div>${testedAt ? `<div class="hero-tested">${tr("last tested")} ${new Date(testedAt).toLocaleString()}</div>` : ""}</div></div>
      ${replayBar}
      <div class="kpi-row">${kpis}</div>
      ${foldBlock("meter", tr("Damage by source"), "",
        `<div class="meter">${meter.length ? meter : `<div class="sb-empty">${tr("no damage dealt")}</div>`}</div>${composition}`)}
      ${speedMarkup(r)}${recordMarkup(r)}${chart}${replayCurves}
      ${ask}
    </div>`;
  // WHAT BECAME OF THIS RUN, drawn on EVERY result — a stored one re-rendered
  // after a reload, a pick in the roll call, and the fresh run that
  // `offerBoardSubmit` is about to repaint when its verdict lands. Filling it
  // only from there would leave "submitting…" standing for ever on the two
  // paths that submit nothing: a scenario of your own, and a board row.
  renderBoardOutcome();
  // Meter rows that carry a per-type split toggle theirs. The choice is kept
  // across runs — a player who opened Direct hits wants it open on the next
  // simulate, not to reopen it every time.
  $("sim-results").querySelectorAll(".mrow.exp").forEach((el) => {
    el.addEventListener("click", () => {
      const k = el.dataset.src;
      const open = !simMeterOpen.has(k);
      if (open) simMeterOpen.add(k);
      else simMeterOpen.delete(k);
      el.querySelector(".mcaret").textContent = open ? "▾" : "▸";
      $("sim-results")
        .querySelectorAll(`.mrow.sub[data-of="${CSS.escape(k)}"]`)
        .forEach((c) => { c.hidden = !open; });
    });
  });
  wireFolds();
  // THE RECORD'S OWN CONTROLS. Its body is rebuilt with the rest of the panel,
  // so its buttons are rebound here rather than kept — and the state that says
  // WHICH body and WHICH filter lives outside the markup, the same rule the
  // fold state follows one function over.
  paintRecord(r);
  wireReplay(r);
  // Chart hover: crosshair + tooltip on the nearest time bucket.
  const wrap = $("sim-results").querySelector(".tl-wrap");
  if (wrap) {
    const svg = wrap.querySelector("#tl-svg");
    const tip = wrap.querySelector("#tl-tip");
    const cross = wrap.querySelector("#tl-cross");
    wrap.addEventListener("mousemove", (ev) => {
      const b = svg.getBoundingClientRect();
      const fx = (ev.clientX - b.left) / b.width;
      const i = Math.max(0, Math.min(tl.length - 1, Math.round(fx * tl.length) - 1));
      cross.hidden = false;
      cross.setAttribute("x1", px(i)); cross.setAttribute("x2", px(i));
      tip.hidden = false;
      tip.textContent = `${(((i + 1) / tl.length) * r.duration).toFixed(1)}s · ${n0(dpsPts[i])} DPS`;
      tip.style.left = Math.min(b.width - 120, Math.max(0, ev.clientX - b.left + 10)) + "px";
    });
    wrap.addEventListener("mouseleave", () => { cross.hidden = true; tip.hidden = true; });
  }
}


// ---- Optimizer: scope (mods/arcanes/evolutions) → top-10 builds ---------
// Mod scope is a 3-state cycle (off / pool / required); the client estimates
// the candidate count (no cap — the server funnel culls large spaces).
function nChooseK(n, k) {
  if (k < 0 || k > n) return 0;
  k = Math.min(k, n - k);
  let r = 1;
  for (let i = 0; i < k; i++) r = (r * (n - i)) / (i + 1);
  return r;
}

// ---- scope mutex helpers -----------------------------------------------
// A SINGLE-SLOT group (the exilus slot, the arcane slot, one evolution tier)
// holds either "these are the options" or "it is this one" — never both. The
// two must not BLOCK each other, which in practice is asymmetric: any pool
// mark greys out every req, while a pin still lets you click pool.
//
// Blocking is the wrong answer to a question that has an obvious one. The
// marks are not in conflict, they are two ways of saying what the slot does,
// so the LAST click wins and the group is rewritten to mean it: req clears
// the pools, pool clears the pin. Nothing is refused and the scope never
// lies about itself — the same rule `clearFamMarks` already applies to
// families.
function setSingleSlotMark(map, id, want) {
  if ((map[id] || "off") === want) {   // clicking the ON seg turns it off
    delete map[id];
    return;
  }
  // req pins the slot: every other mark in the group goes, pools included.
  // pool opens it for search: a pin cannot survive that, but other pools can.
  Object.keys(map).forEach((o) => {
    if (o === id) return;
    if (want === "fixed" || map[o] === "fixed") delete map[o];
  });
  map[id] = want;
}

// Family exclusivity is a GAME rule across all 9 slots: req'ing a mod kills
// its family siblings everywhere (e.g. req Primed Pistol Gambit → plain
// Pistol Gambit can be neither pool nor req). The UI greys them out; setting
// a req actively clears conflicting marks so the scope never lies.
function famReqBy(m) {
  if (!m || !m.family) return null;
  const hit = (map) => Object.keys(map).find((id) => map[id] === "fixed" && id !== m.id && (modById(id) || {}).family === m.family);
  return hit(opt.mods) || hit(opt.exilus) || null;
}
function clearFamMarks(id) {
  const m = modById(id);
  if (!m || !m.family) return;
  [opt.mods, opt.exilus].forEach((map) => Object.keys(map).forEach((o) => {
    if (o !== id && (modById(o) || {}).family === m.family) delete map[o];
  }));
}
const reqCountMain = () => Object.values(opt.mods).filter((s) => s === "fixed").length;
// `none` IS NOT A PIN ON A MOD — it is this slot's range saying "searched
// empty" (see `slotRange`), so nothing may draw it as the pinned option.
const exilusPinned = () =>
  Object.keys(opt.exilus).find((id) => id !== "none" && opt.exilus[id] === "fixed") || null;
// The arcane pinned in a given POOL. A weapon with two slots has two
// independent pins — one Primary and one Secondary — so the question only
// means something with a pool attached.
const arcanePinnedIn = (pool) =>
  Object.keys(opt.arcanes).find(
    (id) => opt.arcanes[id] === "fixed" && arcaneSeats(arcaneById(id)).includes(pool),
  ) || null;
/// Options this seat contributes to the search.
///
/// IT READS THE SEAT'S RANGE, which is the same rule the server applies —
/// and it did not: this counted `marked + 1`, on the belief that the empty
/// choice is always reachable, while `parse_optimize` has dropped it beside
/// marked candidates since 2026-08-01. So the estimate over-counted by one per
/// seat on every scope with an arcane in it (found 2026-08-29, while making
/// the range a control).
const arcaneOptionsIn = (pool) => {
  if (arcanePinnedIn(pool)) return 1;
  const marked = Object.keys(opt.arcanes).filter(
    (id) => opt.arcanes[id] === "search" && arcaneSeats(arcaneById(id)).includes(pool),
  ).length;
  if (!marked) return 1;                                   // the empty seat, alone
  return marked + (opt.arcanes[arcaneEmptyId(pool)] === "fixed" ? -marked + 1
    : opt.arcanes[arcaneEmptyId(pool)] === "search" ? 1 : 0);
};
// `none` IS NOT A PIN ON AN OPTION. It is this tier's range saying "searched
// empty" (see `slotRange`), so a row must not draw itself as the pinned one.
const evoPinned = (tier) => {
  const m = opt.evos[tier] || {};
  return Object.keys(m).find((id) => id !== "none" && m[id] === "fixed") || null;
};
/// The REAL marks of a tier — its range's `none` is not one of them.
const evoRealMarks = (tier) => Object.keys(opt.evos[tier] || {}).filter((id) => id !== "none");

/// Does ANY set this tier produces install a rung here?
///
/// THE LADDER KEYS ON THE RANGE, NOT ON THE MARKS, and it has to: a tier set
/// to 0–0 keeps its candidates — going down and back up must not cost the
/// reader what they marked — so "it has marks" is no longer the same question
/// as "it fills the rung". Count the marks instead and a 0–0 tier opens the
/// one above it, whose every set `ladder_prefix` then truncates back: the
/// marks up there would price nothing and the scope would say otherwise.
/// 0–1 DOES open it — half of its sets carry the rung, and the other half
/// being truncated is the ladder working rather than a scope nobody can ask
/// for.
const evoFillsRung = (tier) =>
  evoRealMarks(tier).length > 0 && (opt.evos[tier] || {}).none !== "fixed";

// ---- HOW MANY OF AN AXIS'S SLOTS A CANDIDATE FILLS ----------------------
//
// EVERY AXIS IS THE SAME SHAPE: N slots, an option set, and a range saying how
// many of the slots a searched build must fill. The mods axis is 8 slots and a
// number 0–8; every other axis is ONE slot and 0–0, 0–1 or 1–1, drawn the same
// way because it is the same question.
//
// IT IS DERIVED FIRST AND ADJUSTED SECOND, which keeps it safe: the derived
// answer is what the scope did before this existed — nothing marked is 0–0, a
// mark is 1–1 — so no search grows unless somebody widens it on purpose. That
// matters most on the ARCANE seats, where an empty seat can only ever TIE the
// same build with the arcane in it, so it is ruled out as a DEFAULT and asking
// for it out loud is a different thing.
//
// THE EMPTY CHOICE IS A MARK LIKE ANY OTHER — `none` on the exilus slot and on
// an evolution tier, `none:<pool>` on an arcane seat, which names its seat
// because a weapon can hold two and the marks are one flat map. So the range
// is a VIEW over the option set rather than a second thing to store, and it
// travels in the search preset, the request and the round trip with no field
// of its own anywhere.
const arcaneEmptyId = (pool) => `none:${pool}`;

/// The range a single-slot axis is currently set to, read off its marks.
///
/// `locked` is a range that cannot be adjusted rather than one nobody has: a
/// pinned candidate settles the slot at 1–1, and a slot with no candidates at
/// all is 0–0 with nothing to widen to.
function slotRange(marks, emptyId, ids) {
  const real = [...ids].filter((id) => id !== emptyId && marks[id]);
  const realPinned = real.find((id) => marks[id] === "fixed") || null;
  const realPooled = real.filter((id) => marks[id] === "search");
  // A REAL PIN IS ASKED FIRST, so a stale empty mark cannot outrank it. On the
  // exilus slot and the evolution tiers `setSingleSlotMark` clears the empty
  // mark on the way to a pin, because they share one map; the arcane seats
  // clear it by hand (their group is per seat and excludes it).
  if (realPinned) return { lo: 1, hi: 1, locked: true, why: "pinned" };
  if (marks[emptyId] === "fixed") return { lo: 0, hi: 0, locked: false };
  if (!realPooled.length) return { lo: 0, hi: 0, locked: true, why: "empty" };
  return marks[emptyId] === "search" ? { lo: 0, hi: 1, locked: false } : { lo: 1, hi: 1, locked: false };
}

/// Write a range back onto the marks. The candidates are never touched: going
/// down to 0–0 and back up must not cost the reader what they marked.
function setSlotRange(marks, emptyId, lo, hi) {
  if (hi === 0) marks[emptyId] = "fixed";       // search it unfilled, marks kept
  else if (lo === 0) marks[emptyId] = "search"; // both
  else delete marks[emptyId];                   // always filled
}

/// The row itself. One renderer for four axes, so a change to how a range is
/// stated reaches all of them.
///
/// `max` is the slot count — 8 for the mods axis, 1 for every other — which is
/// the only thing that differs between them on screen.
function slotRangeHtml(key, { label, lo, hi, max = 1, locked = false, note = "" }) {
  const box = (which, v) =>
    `<input type="number" min="0" max="${max}" value="${v}" data-range="${key}" data-end="${which}"${
      locked ? " disabled" : ""}>`;
  return `<div class="oselrow slot-range${locked ? " locked" : ""}" data-range-row="${key}">
    <span class="osellbl">${escHtml(label)}</span>${box("lo", lo)}<span class="osdash">–</span>${box("hi", hi)}
    ${note ? `<span class="opt-size-eff">${escHtml(note)}</span>` : ""}
  </div>`;
}

/// …and its wiring, given the host that was just re-rendered. `onSet` takes a
/// NORMALISED pair: an end pushes the other rather than allowing lo > hi,
/// which is the rule the mods axis has had since the range landed.
function wireSlotRange(host, max, onSet) {
  host.querySelectorAll("input[data-range]").forEach((el) =>
    el.addEventListener("change", () => {
      const row = el.closest("[data-range-row]");
      const get = (w) => Number(row.querySelector(`input[data-end="${w}"]`).value) || 0;
      let lo = Math.max(0, Math.min(max, get("lo")));
      let hi = Math.max(0, Math.min(max, get("hi")));
      if (el.dataset.end === "lo" && lo > hi) hi = lo;
      if (el.dataset.end === "hi" && hi < lo) lo = hi;
      onSet(el.dataset.range, lo, hi);
    }));
}

/// WHICH BUILDER BLOCK EACH SCOPE SECTION IS THE BULK FORM OF.
///
/// The ONLY hand-written half of the alignment below, and it is a mapping
/// rather than an order: `stats-block` and `assembly-block` have no bulk form
/// (a search does not sum a build, and a kitgun's parts are the weapon), so
/// they are simply absent. Everything else — the sequence, the numbers, the
/// names — is read off the builder itself.
const OPT_SCOPE_OF = {
  "mode-block": "opt-modes-sect",
  "mod-block": "opt-mods-sect",
  "arcane-block": "opt-arcanes-sect",
  "evo-block": "opt-evos-sect",
  "element-block": "opt-valence-sect",
};

/// THE OPTIMIZER IS THE BUILDER, IN BULK.
///
/// Every axis here is a question the builder already asks — the difference is
/// that the builder binds a VALUE and the optimizer binds a SET. So the two
/// must read as one page: the same axes, in the same sequence, under the same
/// numbers and the same names. They did not. The optimizer opened on Mods and
/// put Mode fourth, called the builder's "Arcane" block "Arcanes" and its
/// "Evolution" block "Evolutions", and numbered nothing — three chances for a
/// reader to think the two tabs are about different things.
///
/// NOTHING DECLARES THAT ORDER TWICE. This walks the builder's own blocks in
/// DOM order and appends each axis's section as it meets one, stamping the
/// heading from that block's `.n` and `<h2>` — which `applyI18n` has already
/// translated, so the label is the builder's word in the reader's language
/// rather than a second string to keep in step. Reorder a builder block,
/// renumber one, rename one, and the optimizer follows with NO edit: the map
/// above is touched only when an axis is added or removed.
function orderOptScope() {
  const host = $("opt-scope");
  if (!host) return;
  document.querySelectorAll('section.block[data-module="builder"]').forEach((b) => {
    const sect = $(OPT_SCOPE_OF[b.id] || "");
    if (!sect) return;
    // appendChild MOVES it — walking the builder in order therefore leaves
    // this host in the builder's order, whatever it was before.
    host.appendChild(sect);
    const h = sect.querySelector(".axh");
    const n = b.querySelector(".bh .n"), h2 = b.querySelector(".bh h2");
    if (h && n && h2) h.textContent = `${n.textContent.trim()} · ${h2.textContent.trim()}`;
  });
}

/// THE FINAL ROUND'S RUN COUNT — the simulator's Runs control, said again.
///
/// Deliberately the same component in the same words, because it is the same
/// question: how hard do you want to measure, right now, on this machine. It
/// sits OUTSIDE both halves and is saved by neither preset (`OPT_RUNS_KEY`) —
/// the search preset says what to look through, the scenario says what the
/// fight is, and neither of them has ever had an opinion about precision.
///
/// It is TYPED rather than defaulted from the fight. A blank box meaning "the
/// fight's own count" is one control with two readings, which is how a reader
/// ends up unable to say what number the last round actually used.
function renderOptRuns() {
  const box = $("opt-runs-block");
  if (!box) return;
  box.innerHTML =
    `<label title="${escHtml(tr("how many simulations each finalist gets in the last round. Yours, not the search's and not the fight's: it is saved by no preset and pinned by no ruler. A smaller number searches faster and is worth re-measuring in the simulator"))}">${
      escHtml(tr("Final-round runs"))} <input type="number" id="opt-runs" min="1" max="20000" step="10" value="${finalRuns()}"></label>` +
    `<span class="sim-hint">${escHtml(tr("yours, in neither preset — the simulator's Runs is the same setting for the replay"))}</span>`;
  const el = $("opt-runs");
  el.addEventListener("change", () => {
    setFinalRuns(el.value);
    el.value = String(finalRuns());
    updateOptEstimate(); // the planned funnel quotes this number
  });
}

function renderOpt() {
  // Every weapon is optimizable: the scope is built from the weapon's OWN
  // pools (mod class, arcane slot, evolution tiers), so nothing here is
  // weapon-specific. META is the only prerequisite.
  show("opt-block", !!META);
  if (!META) return;
  // A scope for an axis the weapon does not have is a heading over nothing —
  // and worse, an invitation to configure a slot it cannot equip. The same
  // three facts the builder hides its blocks on.
  const w = weaponInfo($("weapon").value) || {};
  const AX = weaponAxes(w.id);
  // The fight's Warframe buffs, read-only. Painted here as well as from
  // `renderOptEnemy`, because arriving on this tab is its own moment: the
  // scenario may have gained a buff while you were in the simulator.
  renderWfBuffs("opt-wfbuffs", true);
  // A WEAPON WITH ONE WAY TO BE FIRED HAS NO AXIS HERE. The builder still
  // STATES its one mode (a fact about the weapon); a search over one option is
  // not a scope, so this section is simply absent — the same rule the exilus,
  // arcane and evolution sections follow.
  orderOptScope();
  renderOptRuns();
  show("opt-modes-sect", modeOpts(w).length > 0);
  show("opt-valence-sect", !!valenceSpec(w.id));
  show("opt-exilus-sect", AX.hasExilus);
  show("opt-arcanes-sect", AX.arcanes.length > 0);
  show("opt-evos-sect", AX.evolutions.length > 0);
  // Seed scope from the current build once: equipped mods = fixed.
  if (!optSeeded) {
    opt.mods = {}; opt.exilus = {};
    // Everything equipped seeds as REQ (pinned) — first-ever content for
    // the auto-created "search 1"; afterwards the ACTIVE preset is the
    // scope (document model) and immediately overwrite this seed.
    slots.slice(0, 8).forEach((s) => { if (s.mod) opt.mods[s.mod] = "fixed"; });
    if (slots[EXILUS].mod) opt.exilus[slots[EXILUS].mod] = "fixed";
    opt.arcanes = {};
    arcanes.filter((a) => a && a !== "none").forEach((a) => { opt.arcanes[a] = "fixed"; });
    opt.evos = {};
    Object.entries(evoSel).forEach(([t, id]) => { if (id) opt.evos[t] = { [id]: "fixed" }; });
    // The build's own mode seeds as REQ, like everything else equipped — so a
    // scope opened for the first time searches the weapon the way you are
    // holding it, not every way it can be held.
    opt.modes = modeOpts(w).length ? { [mode]: "fixed" } : {};
    // NOTHING CROSSES BETWEEN WEAPONS: the valence axis is seeded from the
    // build's own element, like the mode is.
    opt.valence = valenceSpec(w.id) ? { [valence.element]: "fixed" } : {};
    optSeeded = true;
    bootstrapOptPresets();
  }
  renderOptMods();
  renderOptPresetBars();
  renderOptModes();
  renderOptValence();
  renderOptExilus();
  renderOptArcanes();
  renderOptEvos();
  renderOptEnemy();
  updateOptEstimate();
  renderOptBuffs();
}

// The buffs across the WHOLE scope (union of every fixed/search mod + every
// searched arcane + every marked evolution option) — enumerated server-side;
// The SCENARIO's buffs, READ-ONLY — the optimizer reads the simulator the way
// the simulator reads the builder.
//
// It keeps none of its own. A scope-wide union with its own stack settings —
// because a candidate carries mods the current build does not — buys one real
// thing and costs a worse one: the two modules then score the same fight under
// different buffs, and "add this winner, then Run Sim" only matches
// because adding a winner secretly copied the search's config into your
// scenario. One fight, one buff config, and the disagreement cannot exist.
//
// The list is the WIDE one (`fetchAllBuffs`: every buff this weapon could
// produce, cached per weapon), because a search covers builds you are not
// holding — which is exactly what the scenario's "all potential buffs" view is
// for. A buff nobody set falls to its own default, which is now 0 for anything
// timed: a candidate is credited with a stack only if the fight says so.
async function renderOptBuffs() {
  const box = $("opt-buffs");
  if (!box) return;
  renderBuffCards(box, await fetchAllBuffs(), sim.buffs, null, { readonly: true });
}

// The mod scope: the SAME rich list as the mod picker (image, polarity icon,
// sort / polarity filter, effect lines) — the only difference is the rightmost
// control is pool/req instead of the drain. Plus a summary of selections and
// a "mods per build" size. `optPrefs` mirrors the picker's sort/filter.
function renderOptMods() {
  $("opt-size").value = opt.size;
  $("opt-min").value = opt.min;
  renderOptTools();
  renderOptModSel();
  renderOptModList();
}

// The optimizer does NOT own a scenario: it runs the
// SIMULATOR's, drawn here by the same renderer so the two cannot drift and a
// scenario preset switched on either tab is switched on both. What the search
// owns is its funnel — how many candidates survive each round — and that is
// the block below the buffs, not this one.
//
// No Runs/Measure section here: the funnel decides run counts round by round,
// so the engagement LENGTH is the only measurement input the search takes,
// and it sits beside the enemy.
function renderOptEnemy() {
  if (!$("opt-target")) return;
  renderWfBuffs("opt-wfbuffs", true);
  renderScenarioFields(
    { target: "opt-target", technique: "opt-technique", limits: "opt-limits",
      extra: "opt-extra", squad: "opt-squad" },
    { readonly: true },
  );
  // Which fight, and where it is edited. Not a preset bar: that bar can
  // rename, duplicate, delete and import, all of which are edits, and the
  // scenario collection is the SIMULATOR's to edit.
  const ref = $("opt-scenario-ref");
  if (ref) {
    const w = weaponInfo($("weapon").value) || {};
    ref.innerHTML =
      `<span class="plabel">${escHtml(tr("Scenario"))}</span>` +
      `<span class="pchip sel" title="${escHtml(tr("the scenario the simulator is set to"))}">${escHtml(presetLabel(scenarioNamed(activeScenario)) || tr("current"))}</span>` +
      `<a class="pchip" href="${weaponPath(w.id)}/simulator">${escHtml(tr("edit in the Simulator"))} →</a>`;
  }
}

// Exilus-slot scope (the +1 slot) — exilus-eligible mods with the same
// pool/req segs as the main list: pool = a slot option (empty always
// allowed), req = pin the slot (max one). The same mods may ALSO be marked
// in the main scope above — all 9 slots accept exilus mods; the search
// never equips one twice.
function renderOptExilus() {
  const pinned = exilusPinned();
  const hasPool = Object.values(opt.exilus).some((s) => s === "search");
  const row = (m) => {
    const st = opt.exilus[m.id] || "off";
    const fam = famReqBy(m);
    // Only a FAMILY conflict can kill a row: pool and req no longer block
    // each other — clicking one rewrites the group (setSingleSlotMark).
    const poolDead = !!fam;
    const reqDead = !!fam;
    const why = fam ? `excluded: ${(modById(fam) || { name: fam }).name} is required (same family)` : "";
    return modRow(m, {
      cls: `${st === "off" ? "" : st} ${fam ? "dis-soft" : ""}`,
      title: why,
      exilusChip: false,
      trailing: oseg(`data-m="${m.id}"`, st, {
        poolDead,
        reqDead,
        reqTitle: !reqDead && hasPool ? tr("req pins the slot — the pool marks give way") : "",
      }),
    });
  };
  const ax = weaponAxes().exilus;
  // …AND THE SLOT'S OWN RANGE, the same control the arcane seats and the
  // evolution tiers carry. This axis could always say 0–1 — `exilus_ids` has
  // taken a pooled `none` since it was written — and nothing on the page ever
  // said so, which is half of why the four axes looked like four rules.
  const r = slotRange(opt.exilus, "none", new Set([...ax.map((m) => m.id), "none"]));
  const note = r.locked
    ? (r.why === "pinned" ? tr("pinned — this slot is settled")
      : tr("nothing marked, so the slot is searched empty"))
    : r.hi === 0 ? tr("searched empty — the marks are kept")
      : r.lo === 0 ? tr("empty is searched beside them")
        : tr("every searched build fills it");
  $("opt-exilus").innerHTML = (ax.map(row).join("")
    || `<div class="opt dis">${escHtml(tr("no exilus mods in this pool"))}</div>`);
  const rangeHost = $("opt-exilus-range");
  if (rangeHost) {
    rangeHost.innerHTML = ax.length ? slotRangeHtml("exilus", {
      label: tr("This slot holds"), lo: r.lo, hi: r.hi, locked: r.locked, note,
    }) : "";
    wireSlotRange(rangeHost, 1, (_k, lo, hi) => {
      setSlotRange(opt.exilus, "none", lo, hi);
      renderOptMods(); renderOptExilus(); updateOptEstimate();
    });
  }
  $("opt-exilus").querySelectorAll(".seg:not(.dis)").forEach((el) =>
    el.addEventListener("click", (e) => {
      e.stopPropagation();
      const id = el.dataset.m, want = el.dataset.s;
      setSingleSlotMark(opt.exilus, id, want);
      if (opt.exilus[id] === "fixed") clearFamMarks(id);
      renderOptMods(); renderOptExilus(); updateOptEstimate();
    }));
}

// Arcane scope — the SAME rich rows as the arcane picker (image, name, effect
// lines), searchable, with an include toggle on the right. Marking nothing is
// what searches the empty slot, so there is no "None" row to mark.
/// THE MODE AXIS — how the weapon is played, as a search dimension.
///
/// Mode belongs to the BUILD, which is why the builder has a
/// control for it and the simulator does not. The optimizer is the third case
/// and it is neither: it binds a SET where the builder binds a value, exactly
/// as it does for mods, arcanes and evolutions. Before this the builder's own
/// Mode block was simply drawn on this tab, where it looked like a setting and
/// was not one — the request carried no mode at all, so picking the Phantasma's
/// charged mode here searched its base form and said nothing.
///
/// An UNSUSTAINABLE mode is still offered. `play_modes` marks the ones a board
/// may rank, which is a rule about the leaderboard rather than about what a
/// player may search — and the builder offers them all.
function renderOptModes() {
  const box = $("opt-modes");
  if (!box) return;
  const w = weaponInfo($("weapon").value) || {};
  const opts = modeOpts(w);
  // NEVER EMPTY, and asserted HERE rather than only where the scope is seeded:
  // a preset written before this axis existed carries no modes, a scope
  // imported from another weapon carries modes this one does not have, and
  // both arrive as "no mode at all" — which is not "search them all", it is a
  // question with no answer. The build's own mode is the answer, the same one
  // an empty scope seeds with.
  if (opts.length && !Object.keys(opt.modes).length) opt.modes = { [mode]: "fixed" };
  const marks = Object.keys(opt.modes).filter((id) => opts.some(([o]) => o === id));
  const pinned = marks.find((id) => opt.modes[id] === "fixed") || null;
  const hasPool = marks.some((id) => opt.modes[id] === "search");
  box.innerHTML = opts
    .map(([id, label, offReason]) => {
      const st = opt.modes[id] || "off";
      return `<div class="opt ${st === "off" ? "" : st} ${offReason ? "dis" : ""}">
        <div class="info"><div class="mn">${escHtml(label)}</div>${
          offReason ? `<div class="ef warn">⊘ ${escHtml(offReason)}</div>` : ""}</div>
        ${oseg(`data-m="${escHtml(id)}"`, st, {
          poolDead: !!offReason,
          reqDead: !!offReason,
          poolTitle: pinned && pinned !== id ? tr("pooling opens the slot — the pin gives way") : "",
          reqTitle: hasPool ? tr("req pins the slot — the pool marks give way") : "",
        })}
      </div>`;
    })
    .join("")
    // …AND ITS RANGE, READ-ONLY AT 1–1. A build is played
    // exactly one way, so this axis has no range to adjust — and saying so is
    // what makes the model complete rather than making this the axis the rule
    // forgot. The same row, the same words, disabled.
    + slotRangeHtml("mode", {
      label: tr("Every build is played"), lo: 1, hi: 1, locked: true,
      note: tr("one way — there is no build without a mode"),
    });
  box.querySelectorAll(".seg:not(.dis)").forEach((el) =>
    el.addEventListener("click", (e) => {
      e.stopPropagation();
      const id = el.dataset.m, want = el.dataset.s;
      // ONE GROUP, because a build is played ONE way: the marks here behave
      // like a single slot's — `req` pins it and clears the pool, `pool` opens
      // it and gives way on the pin.
      const was = opt.modes[id];
      if (want === "fixed") {
        opt.modes = { [id]: "fixed" };
      } else if (was === "search") {
        delete opt.modes[id];
      } else {
        Object.keys(opt.modes).forEach((k) => { if (opt.modes[k] === "fixed") delete opt.modes[k]; });
        opt.modes[id] = "search";
      }
      if (was === "fixed" && want === "fixed") delete opt.modes[id];
      // NEVER EMPTY. A scope with no mode is not "search them all", it is a
      // question with no answer — the server would fall back to the request's
      // single mode and the screen would not say so.
      if (!Object.keys(opt.modes).length) opt.modes = { [id]: "fixed" };
      renderOptModes();
      updateOptEstimate(); // the scope's auto-save
    })
  );
}

/// THE VALENCE AXIS, searched exactly like the mode: `pool` opens it, `req`
/// pins one, and the two marks behave as one group because a weapon has ONE
/// progenitor element.
///
/// Never empty for a weapon that has the axis — a scope with no element is not
/// "search them all", it is a question with no answer, and the server would
/// fall back to the request's single element without the screen saying so.
function renderOptValence() {
  const box = $("opt-valence");
  if (!box) return;
  const w = weaponInfo($("weapon").value) || {};
  const s = valenceSpec(w.id);
  if (!s) { box.innerHTML = ""; return; }
  if (!Object.keys(opt.valence || {}).length) {
    opt.valence = { [valence.element]: "fixed" };
  }
  const marks = Object.keys(opt.valence).filter((id) => s.elements.includes(id));
  const pinned = marks.find((id) => opt.valence[id] === "fixed") || null;
  const hasPool = marks.some((id) => opt.valence[id] === "search");
  box.innerHTML = s.elements
    .map((id) => {
      const st = opt.valence[id] || "off";
      return `<div class="opt ${st === "off" ? "" : st}">
        <div class="info"><div class="mn">${escHtml(DT(id))}</div></div>
        ${oseg(`data-m="${escHtml(id)}"`, st, {
          poolTitle: pinned && pinned !== id ? tr("pooling opens the slot — the pin gives way") : "",
          reqTitle: hasPool ? tr("req pins the slot — the pool marks give way") : "",
        })}
      </div>`;
    })
    .join("")
    // …and the same read-only 1–1 the mode axis carries: an adversary weapon
    // has exactly one progenitor element, always.
    + slotRangeHtml("valence", {
      label: tr("Every build carries"), lo: 1, hi: 1, locked: true,
      note: tr("one progenitor element — the weapon always has one"),
    });
  box.querySelectorAll(".seg").forEach((el) =>
    el.addEventListener("click", (e) => {
      e.stopPropagation();
      const id = el.dataset.m, want = el.dataset.s;
      const was = opt.valence[id];
      if (want === "fixed") {
        opt.valence = { [id]: "fixed" };
      } else if (was === "search") {
        delete opt.valence[id];
      } else {
        Object.keys(opt.valence).forEach((k) => { if (opt.valence[k] === "fixed") delete opt.valence[k]; });
        opt.valence[id] = "search";
      }
      if (was === "fixed" && want === "fixed") delete opt.valence[id];
      if (!Object.keys(opt.valence).length) opt.valence = { [id]: "fixed" };
      renderOptValence();
      updateOptEstimate();
    })
  );
}

function renderOptArcanes() {
  const q = ($("opt-arc-filter") && $("opt-arc-filter").value || "").trim().toLowerCase();
  const axes = weaponAxes().arcanes;
  const row = (a, pinned, hasPool) => {
    const st = opt.arcanes[a.id] || "off";
    // Neither mark blocks the other: clicking one rewrites the group
    // (setSingleSlotMark), so every seg here is live.
    const eff = effLines(cardLines(a, a.max_rank, effectsAt(a, a.max_rank)));
    return `<div class="opt ${a.rarity ? "rar-" + a.rarity : ""} ${st === "off" ? "" : st}">
      ${imgTag(IMG(a.image), "mod")}
      <div class="info"><div class="mn">${wl(a.name, wikiUrl(a.name_en || a.name))}${optGainChipFor(a.id)}</div>${eff}</div>
      ${oseg(`data-a="${a.id}"`, st, {
        poolTitle: pinned && pinned !== a.id ? tr("pooling opens the slot — the pin gives way") : "",
        reqTitle: hasPool ? tr("req pins the slot — the pool marks give way") : "",
      })}
    </div>`;
  };
  // ONE SECTION PER SLOT. An arcane belongs to exactly one pool, so the flat
  // `opt.arcanes` map already says which slot each mark is for — what has to
  // be per-pool is the RULE: "req pins the slot" pins THAT slot, and a pin in
  // the Primary section has nothing to do with the Secondary one. The section
  // header is drawn only when there is more than one, as everywhere else.
  $("opt-arcanes").innerHTML = axes
    .map(({ pool, options }, i) => {
      const inPool = options.filter((a) => !q || searchBlob(a).includes(q));
      const ids = new Set(options.map((a) => a.id));
      const marks = Object.keys(opt.arcanes).filter((id) => ids.has(id));
      const pinned = marks.find((id) => opt.arcanes[id] === "fixed") || null;
      const hasPool = marks.some((id) => opt.arcanes[id] === "search");
      const head = axes.length > 1
        ? `<div class="menu-head">${escHtml(tr(ARC_POOL_LABEL[pool] || pool))}</div>`
        : "";
      const rows = inPool.map((a) => row(a, pinned, hasPool)).join("")
        || `<div class="opt dis">${escHtml(tr("no matches"))}</div>`;
      // …AND HOW MANY OF THIS SEAT TO FILL, after the list, for the reason
      // the mods axis states its range after its list: it is a conclusion of
      // the marking and means nothing before it.
      const r = slotRange(opt.arcanes, arcaneEmptyId(pool), ids.add(arcaneEmptyId(pool)));
      const note = r.locked
        ? (r.why === "pinned" ? tr("pinned — this seat is settled")
          : tr("nothing marked, so the seat is searched empty"))
        : r.hi === 0 ? tr("searched unworn — the marks are kept")
          : r.lo === 0 ? tr("unworn is searched beside them")
            : tr("an empty seat can only tie, so it is not searched unless you ask");
      return `<div class="menu-sect">${head}${rows}${slotRangeHtml(`arc:${pool}`, {
        label: tr("This seat holds"), lo: r.lo, hi: r.hi, locked: r.locked, note,
      })}</div>`;
    })
    .join("");
  wireSlotRange($("opt-arcanes"), 1, (key, lo, hi) => {
    setSlotRange(opt.arcanes, arcaneEmptyId(key.slice(4)), lo, hi);
    renderOptArcanes(); updateOptEstimate();
  });
  $("opt-arcanes").querySelectorAll(".seg:not(.dis)").forEach((el) =>
    el.addEventListener("click", (e) => {
      e.stopPropagation();
      // The group is this arcane's OWN pool: pinning a Primary must not
      // clear a Secondary mark, because they fill different slots.
      const own = arcaneById(el.dataset.a);
      const group = {};
      Object.keys(opt.arcanes).forEach((id) => {
        if (sameArcaneSeat(arcaneById(id), own)) group[id] = opt.arcanes[id];
      });
      setSingleSlotMark(group, el.dataset.a, el.dataset.s);
      Object.keys(opt.arcanes).forEach((id) => {
        if (sameArcaneSeat(arcaneById(id), own)) delete opt.arcanes[id];
      });
      Object.assign(opt.arcanes, group);
      // A PIN SETTLES THE SEAT, so its range goes with it. The group above is
      // built from `sameArcaneSeat`, which `none:<pool>` is not a member of —
      // it is the seat's range rather than an arcane — so it is cleared here.
      if (el.dataset.s === "fixed") {
        arcaneSeats(own).forEach((pool) => { delete opt.arcanes[arcaneEmptyId(pool)]; });
      }
      renderOptArcanes(); updateOptEstimate();
    }));
}

// Evolution scope — per tier, the option rows with their verbatim description
// and a search toggle (broken evolutions flagged).
function renderOptEvos() {
  const tiers = weaponEvos();
  // The same LADDER the builder draws: a tier is markable only once the one
  // before it has a mark, because every set the search enumerates installs
  // one option per marked tier — mark tier 2 with tier 1 blank and every set
  // it produces skips a rung. The scope cannot express what the sim would
  // then refuse to price.
  const optOpenTo = (() => {
    let n = 0;
    // A TIER SET TO 0–0 OPENS NOTHING. Its `none` is a mark, and counting it
    // would open the tier above over sets that reach it through a rung the
    // search never installs — `ladder_prefix` would then truncate every one of
    // them and the marks above would price nothing. 0–1 DOES open it: half of
    // its sets carry the rung, and the other half are truncated, which is the
    // ladder working rather than a scope that cannot be expressed.
    for (const t of tiers) { if (!evoFillsRung(t.tier)) break; n = t.tier; }
    return n + 1;
  })();
  // A scope preset saved before the rule existed can still carry marks above
  // the gap. Drop them here so what is drawn, what is counted in the estimate
  // and what is sent all say the same thing — the server truncates the sets
  // either way, and a mark that changes nothing is worse than no mark.
  tiers.forEach((t) => { if (t.tier > optOpenTo) delete opt.evos[t.tier]; });
  $("opt-evos").innerHTML = tiers.map((t) => {
    const sel = opt.evos[t.tier] || {};
    const pinned = evoPinned(t.tier);
    const locked = t.tier > optOpenTo;
    const hasPool = Object.values(sel).some((s) => s === "search");
    const rows = t.options.map((o) => {
      const st = sel[o.id] || "off";
      // Neither mark blocks the other — clicking one rewrites the tier.
      const desc = evoLines(o).map((x) => `<div>${escHtml(x)}</div>`).join("");
      return `<div class="opt ${st === "off" ? "" : st} ${o.broken ? "dis-soft" : ""}">
        <div class="info"><div class="mn">${o.name}${o.broken ? ' <span class="exchip brk">BROKEN</span>' : ""}${
          evoGapChips(o, "span")
        }${optGainChipFor(o.id)}</div><div class="me">${desc}</div>${optPairingNoteFor(o.id)}</div>
        ${oseg(`data-t="${t.tier}" data-e="${o.id}"`, st, {
          extra: locked ? "tlocked" : "",
          poolTitle: pinned && pinned !== o.id ? tr("pooling opens the tier — the pin gives way") : "",
          reqTitle: hasPool ? tr("req pins the tier — the pool marks give way") : "",
        })}
      </div>`;
    }).join("");
    const r = slotRange(sel, "none", new Set([...t.options.map((o) => o.id), "none"]));
    const note = r.locked
      ? (r.why === "pinned" ? tr("pinned — this tier is settled")
        : tr("nothing marked, so this tier is searched empty"))
      : r.hi === 0 ? tr("searched empty — the marks are kept")
        : r.lo === 0 ? tr("empty is searched beside them")
          : tr("every searched build installs one of them");
    const range = locked ? "" : slotRangeHtml(`evo:${t.tier}`, {
      label: tr("This tier installs"), lo: r.lo, hi: r.hi, locked: r.locked, note,
    });
    return `<div class="opt-tier-block${locked ? " locked" : ""}" ${locked
      ? `title="${escHtml(tr("install the previous tier first"))}"` : ""
    }><div class="opt-tier-h">EVO ${ROMAN(t.tier)}</div><div class="combo-menu opt-evolist">${rows}</div>${range}</div>`;
  }).join("");
  wireSlotRange($("opt-evos"), 1, (key, lo, hi) => {
    const t = key.slice(4);
    opt.evos[t] = opt.evos[t] || {};
    setSlotRange(opt.evos[t], "none", lo, hi);
    renderOptEvos(); updateOptEstimate();
  });
  $("opt-evos").querySelectorAll(".seg:not(.dis):not(.tlocked)").forEach((el) =>
    el.addEventListener("click", (e) => {
      e.stopPropagation();
      const t = el.dataset.t, id = el.dataset.e, want = el.dataset.s;
      opt.evos[t] = opt.evos[t] || {};
      setSingleSlotMark(opt.evos[t], id, want);
      // Clearing a tier shuts every tier above it, marks and all — the same
      // cascade the builder does, for the same reason.
      if (!evoRealMarks(t).length) {
        tiers.forEach((x) => { if (x.tier > Number(t)) delete opt.evos[x.tier]; });
      }
      renderOptEvos(); updateOptEstimate();
    }));
}

// ---- The optimizer preset — ONE document per weapon.
//
// It was three (mods / arcanes / evolutions), split so the parts could be
// reused across weapons. They no longer need to be: preset storage is
// weapon-scoped (`wfsim-presets-<weapon>-optimizer`), and carrying a search to
// another weapon is the explicit IMPORT, which filters per axis. Three lists
// bought nothing and cost three bootstraps, three actives and three bars over
// one search.
//
// What it holds is the SEARCH: the scope (mods + exilus + max size, arcanes,
// per-tier evolutions) and the funnel's final-round contract. NOT the
// scenario — the optimizer does not own one; it runs the simulator's, which
// has its own preset domain.
//
// `threads` stays out too: it is a property of the MACHINE, not of a search,
// and a preset carrying it would re-tune the CPU on every load.
const OPT_DOMAIN = "optimizer";
// Same DOCUMENT MODEL as every other bar: there is always >=1 preset, one is always active and being
// edited, edits auto-save in place, and the active survives a reload.
let activeOptPreset = null;

const loadOptPresets = () => loadPresetList(OPT_DOMAIN);
const storeOptPresets = (ps) => storePresetList(OPT_DOMAIN, ps);

// Called from renderOpt's seed block (page load AND weapon switch). The
// first-ever run creates "search 1" from the build-seeded scope; afterwards
// the active preset IS the scope.
function bootstrapOptPresets() {
  // NOTHING IS AUTO-CREATED here either — see `initPresets`. A search that has
  // never been run is not a search you own, and the scope controls are already
  // a complete live state without one (`OPT_RUN_DEFAULTS` plus an empty scope).
  const ps = loadOptPresets();
  const want = activeOptPreset || localStorage.getItem(presetActiveKey(OPT_DOMAIN));
  activeOptPreset = ps.some((p) => p.name === want) ? want : (ps[0] ? ps[0].name : "");
  localStorage.setItem(presetActiveKey(OPT_DOMAIN), activeOptPreset);
  const cur = ps.find((p) => p.name === activeOptPreset);
  if (cur) applyOptState(cur.state);
}

// One-time merges, oldest first: the single legacy bar was split into three
// groups, and the three are now one again. Both run over whatever is on the
// machine, so a browser that skipped a release still lands on the current
// shape. Names are the join key — a preset named "crit" in each group was one
// search described three times, which is exactly what it becomes.
(function migrateOptPresets() {
  const parse = (k) => { try { return JSON.parse(localStorage.getItem(k)); } catch (_) { return null; } };
  // Step 1: one bar -> three groups, under the current weapon.
  const legacy = parse("wfsim-opt-presets");
  if (Array.isArray(legacy)) {
    legacy.forEach((p) => {
      const st = p.state || {};
      [["mods", { mods: st.mods || {}, exilus: (st.exilus && typeof st.exilus === "object") ? st.exilus : {}, size: st.size || 8 }],
       ["arcanes", { arcanes: st.arcanes || {} }],
       ["evolutions", { evos: st.evos || {} }]].forEach(([g, state]) => {
        const key = "wfsim-presets-" + presetWeapon() + "-optimizer-" + g;
        const ps = parse(key) || [];
        if (!ps.some((x) => x.name === p.name)) {
          ps.push({ name: p.name, savedAt: p.savedAt || Date.now(), state });
          localStorage.setItem(key, JSON.stringify(ps));
        }
      });
    });
    localStorage.removeItem("wfsim-opt-presets");
  }
  // Step 2: three groups -> one, for EVERY weapon that has them.
  const groups = ["mods", "arcanes", "evolutions"];
  const weapons = new Set();
  for (let i = 0; i < localStorage.length; i++) {
    const m = /^wfsim-presets-(.+)-optimizer-(mods|arcanes|evolutions)$/.exec(localStorage.key(i));
    if (m) weapons.add(m[1]);
  }
  weapons.forEach((w) => {
    const merged = parse(`wfsim-presets-${w}-optimizer`) || [];
    const byName = new Map(merged.map((p) => [p.name, p]));
    groups.forEach((g) => {
      (parse(`wfsim-presets-${w}-optimizer-${g}`) || []).forEach((p) => {
        const into = byName.get(p.name)
          || { name: p.name, savedAt: p.savedAt || Date.now(), state: {} };
        into.state = { ...into.state, ...(p.state || {}) };
        byName.set(p.name, into);
      });
    });
    if (byName.size) {
      localStorage.setItem(`wfsim-presets-${w}-optimizer`, JSON.stringify([...byName.values()]));
      // The three old actives disagree by construction (three bars, three
      // choices); the mod scope is the one that decided what the search was.
      const act = localStorage.getItem(`wfsim-preset-active-${w}-optimizer-mods`);
      if (act && byName.has(act)) localStorage.setItem(`wfsim-preset-active-${w}-optimizer`, act);
    }
    groups.forEach((g) => {
      localStorage.removeItem(`wfsim-presets-${w}-optimizer-${g}`);
      localStorage.removeItem(`wfsim-preset-active-${w}-optimizer-${g}`);
    });
  });
})();

function snapshotOpt() {
  return {
    mods: { ...opt.mods }, exilus: { ...opt.exilus }, size: opt.size, min: opt.min,
    arcanes: { ...opt.arcanes }, modes: { ...opt.modes },
    evos: JSON.parse(JSON.stringify(opt.evos)),
    finalists: optRun.finalists,
  };
}

// An empty search: nothing marked, a fresh size, the contract left alone (it
// is how hard to search, not what to search).
// `min` IS IN HERE, and it was not: `sameState(snapshotOpt(), blankOpt())` is
// the "has this search been touched" guard, and a field one side carries and
// the other omits makes it answer "touched" for every input — the same shape as
// the key-order bug `canon` was written for.
const blankOpt = () => ({ mods: {}, exilus: {}, size: 8, min: 0, arcanes: {}, evos: {},
  // The build's own mode, the way an empty scope seeds every other axis from
  // what you are holding.
  modes: { [mode]: "fixed" },
  finalists: optRun.finalists });

// State-only apply (validation + cross-weapon id dropping); no re-render.
//
// Every axis drops what THIS weapon cannot hold, which is what makes a preset
// carried over from another weapon land as "the part that still applies"
// rather than as a search the run cannot execute.
function applyOptState(st) {
  const norm = (s) => (s === true ? "search" : s); // boolean-era marks
  // Mods: ids missing from this weapon's pool drop out.
  opt.mods = {}; opt.exilus = {};
  Object.entries(st.mods || {}).forEach(([id, s]) => { if (modById(id)) opt.mods[id] = norm(s); });
  // `none` IS THE SLOT'S RANGE and survives, on every axis. It is the axis's
  // "searched empty" mark, so deleting it here would silently widen a scope
  // back to 1–1 on every preset load.
  Object.entries(st.exilus || {}).forEach(([id, s]) => {
    if (id === "none" || (modById(id) || {}).exilus) opt.exilus[id] = norm(s);
  });
  if (st.size) opt.size = st.size;
  // Presets written before the range existed carry no min, and `?? 0` is what
  // they meant: with marks in them the DERIVED floor is at least 1 anyway, so
  // the two readings differ only on a scope with nothing marked — which such a
  // preset, by definition, is not. `??` rather than `||`, since 0 is now a
  // value a reader can deliberately store.
  opt.min = Math.min(st.min ?? 0, opt.size);
  // Arcanes: another SLOT's arcanes are not equippable here, so they drop
  // rather than becoming search dimensions the run cannot use.
  opt.arcanes = {};
  const w = $("weapon").value;
  Object.entries(st.arcanes || {}).forEach(([id, s]) => {
    // ANY of the weapon's pools, not just the first — see arcaneFitsWeapon.
    // A `none:<pool>` mark is the SEAT'S RANGE rather than an arcane, and it
    // is kept when this weapon actually has that seat — so a scope imported
    // from a weapon with a Primary seat does not leave a range behind on one
    // that has none.
    if (id.startsWith("none:")) {
      if ((weaponInfo(w) || {}).arcane_pools?.includes(id.slice(5))) opt.arcanes[id] = norm(s);
    } else if (arcaneFitsWeapon(w, id)) {
      opt.arcanes[ARCANE_RENAMED[id] || id] = norm(s);
    }
  });
  // Modes: a scope carried over from another weapon names modes this one does
  // not have, and a search over none of them is not a scope — so what does not
  // apply drops and the build's own mode stands in.
  opt.modes = {};
  const mopts = modeOpts(weaponInfo(w) || {});
  Object.entries(st.modes || {}).forEach(([id, s]) => {
    if (mopts.some(([o]) => o === id)) opt.modes[id] = norm(s);
  });
  if (mopts.length && !Object.keys(opt.modes).length) opt.modes = { [mode]: "fixed" };
  // Evolutions: keep only ids the CURRENT weapon's tiers actually offer (ids
  // are globally unique, so a family sharing evolutions imports cleanly and a
  // different weapon's ids just drop).
  const tiers = weaponEvos();
  opt.evos = {};
  Object.entries(st.evos || {}).forEach(([t, m]) => {
    const tier = tiers.find((x) => String(x.tier) === String(t));
    if (!tier) return;
    const valid = {};
    Object.entries(m || {}).forEach(([id, s]) => {
      // `none` is the tier's RANGE, not one of its perks — see `slotRange`.
      if (id === "none" || tier.options.some((o) => o.id === id)) valid[id] = norm(s);
    });
    if (Object.keys(valid).length) opt.evos[t] = valid;
  });
  // FINALISTS IS THE ONLY THING LEFT HERE. A preset written
  // before today also carries `runs` and `threads`; both are read by nothing
  // now — the run count is a preference of the reader's (`OPT_RUNS_KEY`) and
  // the thread count is the topbar's compute share — so they are not migrated
  // into either, they are simply dropped the next time this scope is saved.
  if (st.finalists) optRun.finalists = st.finalists;
  const f = $("opt-finalists");
  if (f) f.value = optRun.finalists;
}

function applyOptPreset(st) {
  applyOptState(st);
  optSeeded = true;
  renderOpt(); updateOptEstimate();
}

function renderOptPresetBars() {
  const bar = $("preset-bar-" + OPT_DOMAIN);
  if (!bar) return;
  renderPresetBarIn(bar, {
    domain: OPT_DOMAIN,
    label: tr("Searches"),
    noun: "search",
    hint: "scope + final round; import filters per axis",
    load: loadOptPresets,
    store: storeOptPresets,
    active: () => activeOptPreset,
    setActive: (n) => { activeOptPreset = n; localStorage.setItem(presetActiveKey(OPT_DOMAIN), n); },
    snapshot: snapshotOpt,
    apply: (st) => applyOptPreset(st || {}),
    blank: blankOpt,
    rerender: renderOptPresetBars,
  });
}

function renderOptTools() {
  const t = $("opt-picker-tools");
  const pols = ["Madurai", "Naramon", "Vazarin", "Umbra"].filter((p) => currentPool.some((m) => m.polarity === p));
  t.innerHTML =
    `<label>${escHtml(tr("Sort"))} ` + ddButton("opk-sort", {
      value: optPrefs.sort,
      items: [{ value: "name", label: tr("Name") }, { value: "drain", label: tr("Drain") }],
      onPick: (v) => { optPrefs.sort = v; renderOptTools(); renderOptModList(); },
    }) + `</label>` +
    `<button id="opk-dir" class="ghost-btn small" title="direction">${optPrefs.dir === "asc" ? "▲" : "▼"}</button>` +
    `<span class="pk-pols"><span class="pk-pol ${!optPrefs.pol ? "sel" : ""}" data-p="">all</span>` +
    pols.map((p) => `<span class="pk-pol ${optPrefs.pol === p ? "sel" : ""}" data-p="${p}" title="${p}">${imgTag(POL(p), "pol")}</span>`).join("") +
    `</span>` +
    // QUICK CALC, on a button rather than on every edit. The builder's scan
    // follows an opened slot because opening one IS the question; here every
    // click on a pool/req control would restart ~250 engagements, and the
    // scope is edited many clicks in a row.
    `<span class="pk-gain"><button id="opk-gain" class="ghost-btn small"${optGain.running ? " disabled" : ""}>${
      optGain.running ? `${optGain.done}/${optGain.total}` : escHtml(tr("quick calc"))}</button>` +
    (optWinnerMods()
      ? ddButton("opk-gain-ref", {
        value: optGain.mode,
        title: tr("the build every number is measured on"),
        items: [
          { value: "require", label: tr("vs required"), hint: tr("the mods you have pinned") },
          { value: "winner", label: tr("vs winner"), hint: tr("the build the search returned") },
        ],
        onPick: (v) => { optGain.mode = v; renderOptTools(); renderOptPairings(); renderOptModList(); renderOptArcanes(); renderOptEvos(); },
      })
      : "") +
    `</span>`;
  $("opk-dir").onclick = () => { optPrefs.dir = optPrefs.dir === "asc" ? "desc" : "asc"; renderOptTools(); renderOptModList(); };
  t.querySelectorAll(".pk-pol").forEach((o) => o.onclick = () => { optPrefs.pol = o.dataset.p || null; renderOptTools(); renderOptModList(); });
  // All three axes are on screen at once and all three now carry numbers, so
  // a tick repaints all three — a chip that appeared on one list and not the
  // others would read as "this axis was not scanned".
  const paint = () => {
    renderOptTools(); renderOptPairings(); renderOptModList();
    renderOptArcanes(); renderOptEvos();
  };
  $("opk-gain").onclick = () => scanOptGains(() => paint());
}

// A chip's ✕ removes; the chip itself REVEALS the mod in the list below.
// Making the whole chip a delete button meant reaching for a selected mod to
// look at it threw it away instead — and the ✕ was sitting
// right there looking like the control that did it.
function revealOptMod(id) {
  const m = modById(id);
  if (!m) return;
  // The list is filtered; a chip must be able to reach a row the current
  // filter hides, so clear whatever would keep it off screen.
  if (optPrefs.pol && m.polarity !== optPrefs.pol) { optPrefs.pol = null; renderOptTools(); }
  const q = ($("opt-mod-filter").value || "").trim().toLowerCase();
  if (q && !searchBlob(m).includes(q)) $("opt-mod-filter").value = "";
  renderOptModList();
  const row = $("opt-mods").querySelector(`.opt .seg[data-m="${CSS.escape(id)}"]`);
  if (!row) return;
  const box = row.closest(".opt");
  box.scrollIntoView({ block: "center", behavior: "smooth" });
  box.classList.add("revealed");
  setTimeout(() => box.classList.remove("revealed"), 1600);
}

function renderOptModSel() {
  const chip = (id, cls) => {
    const m = modById(id);
    return `<span class="oselchip ${cls}" data-m="${id}" title="${escHtml(tr("click to find it in the list below"))}">`
      + `${m ? m.name : id}<button class="oselx" data-x="${id}" title="${escHtml(tr("remove"))}">✕</button></span>`;
  };
  const req = Object.keys(opt.mods).filter((id) => opt.mods[id] === "fixed").map((id) => chip(id, "fixed"));
  const pool = Object.keys(opt.mods).filter((id) => opt.mods[id] === "search").map((id) => chip(id, "search"));
  const box = $("opt-mods-sel");
  // TRANSLATED, and it was not: these three lines and the size row under them
  // are meant to read down as one sentence, and two of them were English on a
  // Chinese page.
  box.innerHTML =
    (req.length ? `<div class="oselrow"><span class="osellbl">${escHtml(tr("required"))} (${req.length}/${opt.size})</span>${req.join("")}</div>` : "") +
    (pool.length ? `<div class="oselrow"><span class="osellbl">${escHtml(tr("pool"))} (${pool.length})</span>${pool.join("")}</div>` : "") +
    (!req.length && !pool.length ? `<div class="sim-empty">${escHtml(tr("nothing marked — the search is the bare weapon. Mark mods below as pool or required."))}</div>` : "");
  box.querySelectorAll("[data-x]").forEach((el) =>
    el.addEventListener("click", (e) => {
      e.stopPropagation();
      delete opt.mods[el.dataset.x];
      renderOptMods(); renderOptExilus(); updateOptEstimate();
    }));
  box.querySelectorAll(".oselchip[data-m]").forEach((el) =>
    el.addEventListener("click", () => revealOptMod(el.dataset.m)));
}

/// THE PAIRING LADDER — the quick calc's first statement, above the mods.
///
/// Absent until there is a choice to make: one pairing is not a ladder, and a
/// scope with no elemental mod has nothing to say. What it reports is the
/// reference build measured every way its elements can pair, best first.
function renderOptPairings() {
  const box = $("opt-pairings");
  if (!box) return;
  const fresh = optGain.key === optGainKey();
  const rows = fresh ? optGain.orders : [];
  if (rows.length < 2) { box.innerHTML = ""; return; }
  const head = `${tr("element pairings")} · ${rows.length} · ${escHtml(optGain.metric)} · ${escHtml(optGain.note)}`;
  box.innerHTML = `<div class="pairbox"><div class="pairhead">${head}</div>${rows.map((o, i) => `
    <div class="pairrow${i === 0 ? " best" : ""}">
      <span class="pl">${pairingLabel(o.combined, o.leftover)}</span>
      <span class="pv">${o.value == null ? "—" : sig2(o.value)}</span>
      <span class="pd">${i === 0 ? tr("best") : gainPct(o.pct)}</span>
    </div>`).join("")}</div>`;
}

function renderOptModList() {
  const q = ($("opt-mod-filter").value || "").trim().toLowerCase();
  // Exilus mods are IN this list too — all 9 slots accept them (game rule),
  // so marking one here makes it compete for a MAIN slot; the exilus SLOT
  // has its own block below.
  const hits = poolWithRivens()
    // A STANCE IS NOT A MAIN-SLOT MOD, and this list offered every melee
    // weapon's as one until 2026-08-29. The builder's picker has run the same
    // filter in both directions since the stance slot landed — a stance is
    // legal there and NOWHERE else — and this copy of the list never grew it,
    // so marking one here asked the search for a build nobody can hold.
    // Searching the stance SLOT is a real axis and is not this: it wants the
    // treatment the exilus slot has, in the optimizer as well as here.
    .filter((m) => !m.stance)
    .filter((m) => !optPrefs.pol || m.polarity === optPrefs.pol)
    .filter((m) => !q || searchBlob(m).includes(q))
    .sort((a, b) => {
      // Rivens first, as their own block, as in the builder's picker.
      const r = (b.riven ? 1 : 0) - (a.riven ? 1 : 0);
      if (r) return r;
      const c = optPrefs.sort === "drain" ? a.drain - b.drain : a.name.localeCompare(b.name);
      return optPrefs.dir === "desc" ? -c : c;
    });
  // The picker's `.opt` row markup verbatim; only the trailing `.dr` is
  // replaced by the pool/req control (`.oseg`). Mutex-aware: a family
  // sibling of a req'd mod is dead (game exclusivity); once required fills
  // every slot, unmarked mods can no longer join; and pooled mods RESERVE
  // one open slot — req may only grow to size−1 while any pool mark exists
  // (pinning the last slot would silently kill the search).
  const fixedN = reqCountMain();
  const poolN = Object.values(opt.mods).filter((s) => s === "search").length;
  const full = fixedN >= opt.size;
  const row = (m) => {
    const st = opt.mods[m.id] || "off";
    const fam = famReqBy(m);
    const dead = !!fam || (full && st === "off");
    // Would req'ing this row leave pooled mods with zero open slots?
    const poolAfter = poolN - (st === "search" ? 1 : 0);
    const reqBlocked = st !== "fixed" && (fixedN + 1 > opt.size - (poolAfter > 0 ? 1 : 0));
    const why = fam ? `excluded: ${(modById(fam) || { name: fam }).name} is required (same family)`
      : dead ? `all ${opt.size} slots are required already` : "";
    return modRow(m, {
      cls: `${st === "off" ? "" : st} ${dead ? "dis-soft" : ""}`,
      title: why || (m.effects || []).join(" · "),
      chips: optGainChipFor(m.id),
      note: optPairingNoteFor(m.id),
      // …AND THE OPTIMIZER BINDS A SET.
      trailing: oseg(`data-m="${m.id}"`, st, {
        poolDead: dead,
        reqDead: dead || reqBlocked,
        reqTitle: !dead && reqBlocked
          ? tr("pooled mods reserve ≥1 open slot — raise max mods or clear pools") : "",
      }),
    });
  };
  // THE OPTIMIZER'S OWN SCAN, same component and a different state. It has no
  // slots and therefore no axis — there is one list and one question — so the
  // strip is asked without one.
  $("opt-mods").innerHTML = scanStrip(optGain) + (hits.length
    ? sectionedRows(hits, (m) => (m.riven ? "Riven" : "Mods"), row)
    : `<div class="opt dis">${escHtml(tr("no matches"))}</div>`);
  $("opt-mods").querySelectorAll(".seg:not(.dis)").forEach((el) =>
    el.addEventListener("click", (e) => {
      e.stopPropagation();
      const id = el.dataset.m, want = el.dataset.s, cur = opt.mods[id] || "off";
      if (cur === want) delete opt.mods[id]; else opt.mods[id] = want; // toggle off if same
      if (opt.mods[id] === "fixed") clearFamMarks(id);
      renderOptMods(); renderOptExilus(); updateOptEstimate();
    }));
}

function updateOptEstimate() {
  // 8 + 1 slots, slots may stay EMPTY: builds are every subset of the main
  // scope from `required` up to `size` mods (an empty scope = the bare
  // weapon, still a legal search). `opt.exilus` scopes the +1 slot (req
  // pins it, pool adds options next to "empty"); arcanes and evolution
  // tiers are pool/req the same way.
  const fixed = Object.values(opt.mods).filter((s) => s === "fixed").length;
  const search = Object.values(opt.mods).filter((s) => s === "search").length;
  const exFixed = exilusPinned();
  const exSearch = Object.keys(opt.exilus)
    .filter((id) => id !== "none" && opt.exilus[id] === "search").length;
  // Pooled exilus marks ARE the option set, and the slot's RANGE says whether
  // the empty choice sits beside them: nothing marked, or 0–0, is one option.
  const exOptions = exFixed ? 1
    : opt.exilus.none === "fixed" || !exSearch ? 1
      : exSearch + (opt.exilus.none === "search" ? 1 : 0);
  // Required in BOTH blocks = impossible (a mod equips once).
  const dupReq = exFixed && opt.mods[exFixed] === "fixed" ? exFixed : null;
  // Slots MULTIPLY: a weapon that seats two arcanes is searched over pairs,
  // because the best Primary and the best Secondary are not independent
  // questions.
  const arcCount = arcanePools().reduce((n, p) => n * arcaneOptionsIn(p), 1);
  // MODE AND VALENCE ARE FACTORS TOO, and they were missing (found 2026-08-29,
  // while completing the axis model). The server's variant table is
  // `modes × evo_sets × valences` — pooling a second mode genuinely doubles
  // the search — and this line counted only the evolution sets, so the
  // candidate count UNDER-reported by exactly those two. It is the arcane
  // over-count's mirror image, and both came from a factor written by hand
  // instead of read off the axis.
  const markedCount = (marks) => {
    const ks = Object.keys(marks);
    if (ks.some((k) => marks[k] === "fixed")) return 1;
    return Math.max(1, ks.filter((k) => marks[k] === "search").length);
  };
  const modeCount = markedCount(opt.modes);
  const valCount = valenceSpec($("weapon").value) ? markedCount(opt.valence) : 1;
  // ONE FACTOR PER TIER, from the tier's own RANGE — a pin is one option, an
  // empty tier is one option, and 0–1 is the marked ones plus that empty.
  let evoProduct = 1;
  (weaponEvos()).forEach((t) => {
    const m = opt.evos[t.tier] || {};
    if (evoPinned(t.tier)) { return; }                       // settled: one option
    const pooled = evoRealMarks(t.tier).filter((id) => m[id] === "search").length;
    if (m.none === "fixed" || !pooled) return;               // the empty tier, alone
    evoProduct *= pooled + (m.none === "search" ? 1 : 0);
  });
  const size = opt.size;
  // The pool group occupies ≥1 slot: with pools marked, every build carries
  // at least one pooled mod (k starts above the required count).
  // ...and `opt.min` raises that floor: "exactly 8 mods" is min 8, max 8.
  // A CEILING OF 0 OUTRANKS THE DERIVED FLOOR — the page's half of the rule
  // `min_slots` applies on the server. The marks say "use these" and 0–0 says
  // "not this time, but keep them"; without this the two contradict and the
  // count comes out empty for a request the server answers happily.
  const minK = size === 0 ? 0 : Math.max(fixed + (search > 0 ? 1 : 0), opt.min);
  // …AND THE READER IS TOLD WHEN THE MARKS RAISE THEIR OWN FLOOR. The floor is the larger of what you TYPED and what the marks
  // IMPLY — every required mod is in every candidate, and pooling is the
  // statement that at least one pooled mod is too — so the box could say 0 over
  // a search that never looks below 3, which is a control that lies about what
  // it does. It is stated only when the two DIFFER: a line repeating the two
  // numbers beside it distinguishes nothing.
  const eff = $("opt-size-eff");
  if (eff) {
    eff.textContent = minK > opt.min
      ? tr("actually {min}–{max}: {why}")
        .replace("{min}", minK).replace("{max}", size)
        .replace("{why}", fixed > 0 && search > 0
          ? tr("{n} required, plus at least one pooled").replace("{n}", fixed)
          : fixed > 0
            ? tr("{n} required").replace("{n}", fixed)
            : tr("at least one pooled"))
      : "";
  }
  let subsets = 0;
  for (let k = minK; k <= size; k++) subsets += nChooseK(search, k - fixed);
  subsets *= evoProduct * exOptions;
  const jobs = subsets * arcCount * modeCount * valCount;
  // Pooled mods reserve ≥1 open slot (reachable only via shrinking max
  // mods after marking — req clicks are blocked before this point).
  // …and the same exemption for the refusal that states that floor. At a
  // ceiling of 0 there is no slot for a pooled mod to reserve, and none is
  // wanted.
  const poolStarved = size > 0 && search > 0 && fixed >= size;
  const valid = fixed <= size && subsets > 0 && !dupReq && !poolStarved;
  // No cap (user: use local resources). Show the estimate + a heads-up when big;
  // only block genuinely invalid scopes.
  const big = jobs > 500000;
  // Scenario + funnel preview: what every candidate is actually tested
  // against — the Sim panel's enemy settings, and the successive-halving
  // schedule (survivors × runs per round; a JS mirror of schedule()).
  let scenario = "";
  if (valid) {
    const en = allEnemies().find((e) => e.id === sim.enemy) || {};
    // Mirror of schedule_to()'s auto-planned cadence: k = ceil(log8(N/F))
    // rounds, even log-space culls landing exactly on the finalists, runs
    // from a halving cost budget ((ρ/2)^i, capped at final/4), then the
    // guaranteed final. Racing/amnesty adapt this plan at runtime.
    const F = optRun.finalists, FR = finalRuns();
    const N = Math.round(jobs);
    const rounds = [];
    if (N > F) {
      const k = Math.max(1, Math.ceil(Math.log(N / F) / Math.log(8)));
      const rho = Math.pow(N / F, 1 / k);
      const growth = Math.max(1, rho / 2);
      const cap = Math.max(1, Math.floor(FR / 4));
      let field = N, runsF = 1;
      for (let i = 0; i < k; i++) {
        const keep = i + 1 === k ? F : Math.max(F, Math.round(field / rho));
        rounds.push([Math.min(cap, Math.max(1, Math.round(runsF))), keep]);
        field = keep; runsF *= growth;
      }
    }
    rounds.push([FR, F]);
    const parts = [];
    let field = Math.round(jobs);
    rounds.forEach(([r, k]) => { parts.push(`${field.toLocaleString()}×${r}`); field = Math.min(field, k); });
    // The scenario's Measure is the SIMULATOR's; the funnel still ranks by
    // kills whatever it says, so say so rather than letting the shared state
    // imply a DPS search that does not exist yet.
    // THE SEARCH RANKS BY KILLS whatever the scenario measures by, so any
    // metric that is not the kill rate is a mismatch worth saying — named, so
    // the sentence stays true when a third one lands.
    const met = metricOf(sim.metric);
    const measured = met.per_minute
      ? ""
      : ` · <span class="warn">${escHtml(tr("the search ranks by kills — the scenario's {m} measure applies to the simulator")
          .replace("{m}", metricLabel(met)))}</span>`;
    scenario = `<div class="opt-scn">each build vs <b>${en.name || sim.enemy}</b> Lv ${sim.level}${sim.steel_path ? " (SP)" : ""}${sim.distance > 0 ? ` · ${sim.distance} m` : ""} · ${sim.headshot_pct}% headshots${sim.aiming ? "" : " · hip-fire"} · ${sim.duration} s engagements · planned funnel (builds×runs): ${parts.join(" → ")} → ${F} finalists at ${FR.toLocaleString()} runs (racing cuts deeper, tie-amnesty keeps up to 2×)${measured}</div>`;
  }
  // ONE total, no decomposition — "×N arcanes" leaked a search-internal
  // dimension into the summary line.
  $("opt-estimate").innerHTML = (valid
    ? `~<b>${Math.round(jobs).toLocaleString()}</b> candidate builds${big ? ` <span class="warn">— large; this may take a while</span>` : ""}`
    : `<span class="warn">${dupReq ? `${(modById(dupReq) || { name: dupReq }).name} is required in both blocks — a mod equips once` : poolStarved ? `pooled mods reserve ≥1 open slot — raise max mods or clear pools` : `more required (${fixed}) than slots (${size})`}</span>`) + scenario;
  // Never re-enable while a background job is still running.
  $("run-opt").disabled = !valid || optJobId != null;
  // Every scope mutation funnels through here — AUTO-SAVE into the active
  // preset (debounced), same contract as the build bar.
  clearTimeout(optSaveTimer);
  optSaveTimer = setTimeout(() => {
    if (presetApplying) return;
    const ps = loadOptPresets();
    // A SEARCH IS BORN ON THE FIRST EDIT, like a build (`markPresetDirty`).
    //
    // …BUT THIS FUNNEL IS NOT ONLY AN EDIT. Unlike `markPresetDirty`, which
    // edit handlers call by hand, `updateOptEstimate` also runs on every render
    // — including the first paint of a tab nobody has touched — so "it ran" is
    // no evidence of an edit. The evidence is the STATE: a search that is still
    // `blankOpt()` is a search nobody has made. Compared as a whole rather than
    // field by field, so an axis added tomorrow counts on the day it is added.
    if (!activeOptPreset) {
      if (sameState(snapshotOpt(), blankOpt())) return;
      const name = freeName(ps, (n) => "search " + n);
      ps.push({ name, savedAt: Date.now(), state: snapshotOpt() });
      storeOptPresets(ps);
      activeOptPreset = name;
      localStorage.setItem(presetActiveKey(OPT_DOMAIN), name);
      renderOptPresetBars();
      return;
    }
    const at = ps.findIndex((p) => p.name === activeOptPreset);
    if (at < 0) return;
    ps[at] = { ...ps[at], savedAt: Date.now(), state: snapshotOpt() };
    storeOptPresets(ps);
    renderOptPresetBars();
  }, 400);
}
let optSaveTimer = null;

// The optimize run is a BACKGROUND JOB on the server: POST /api/optimize
// returns a job_id immediately; we poll /api/optimize/status for live funnel
// progress (overall % is exact — the schedule fixes every round's sim count
// up front) and can /api/optimize/cancel. On page reload, init() reattaches
// to a still-running job via a no-id status call.
let optJobId = null;
let optPollTimer = null;
let optCancelling = false; // survives the poll's 500 ms re-renders

const postJson = (url, body) => api(url, body);

async function runOptimize() {
  clearCheckpoint(); // a fresh run supersedes any interrupted one
  $("run-opt").disabled = true; $("run-opt").textContent = "Optimizing…";
  $("opt-results").innerHTML = `<div class="placeholder">starting…</div>`;
  try {
    // pool/req collapse to effective option lists: a req pins its slot/tier
    // (single option), pools are the searched set.
    // A tier collapses to its effective option list, and `none` is one of the
    // options — it is this tier's range saying "searched empty". A REAL pin is looked for first, for the reason `slotRange`
    // asks in that order: a settled tier outranks a stale range mark.
    const evolutions = {};
    Object.entries(opt.evos).forEach(([t, m]) => {
      const keys = Object.keys(m);
      const f = keys.find((id) => id !== "none" && m[id] === "fixed")
        || keys.find((id) => m[id] === "fixed");
      const ids = f ? [f] : keys.filter((id) => m[id] === "search");
      if (ids.length) evolutions[t] = ids;
    });
    // The MARKS, like `mods` and `exilus` — a pin means "this slot is
    // settled", which a flat list of ids cannot say. The server splits them
    // by pool and takes the product.
    const arcs = {};
    Object.keys(opt.arcanes).forEach((id) => {
      if (opt.arcanes[id] && opt.arcanes[id] !== "off") arcs[id] = opt.arcanes[id];
    });
    const body = {
      weapon: $("weapon").value,
      mods: opt.mods,
      rivens: rivenPayload(),
      build_size: opt.size,
      build_min: opt.min,
      arcanes: arcs,
      evolutions,
      // HOW IT IS PLAYED, as a search dimension — the marks, like the arcanes'.
      // `mode` travels too and is what a scope with no axis falls back to, so
      // every caller written before this keeps meaning what it meant.
      modes: opt.modes,
      mode,
      // THE VALENCE, pinned to the builder's. It is not a search axis yet —
      // every candidate is built with the same bonus, which is the weapon the
      // replay will fire. The day it becomes an axis it joins `modes` above.
      // THE VALENCE AXIS, as marks — the same shape `modes` takes. `_element`
      // travels too and is what a scope with no axis falls back to, so every
      // caller written before this keeps meaning what it meant.
      valence: opt.valence,
      valence_element: valence.element,
      valence_bonus: valence.bonus,
      // THE PARTS, pinned to the builder's. Not a search axis yet: every
      // candidate is assembled the same way, which is the weapon the replay
      // will fire. The day it becomes one it joins `modes` above — 100 grip and
      // loader pairs per chamber is a real scope and a real cost, and it is the
      // owner's call whether a search should spend it.
      ...(assembly ? { assembly: { ...assembly } } : {}),
      exilus: opt.exilus,
      // THE STANCE, PINNED TO THE BUILDER'S — not a search axis, the way the
      // valence and the parts above are not. A stance decides what a swing IS,
      // so a melee search without one ranks builds nobody holds; the mod list
      // filters stances out (a stance is legal in the stance slot and nowhere
      // else), so this is the only thing that puts it back.
      stance: (slots[STANCE] || {}).mod || "",
      // THE FIGHT, WHOLE AND DERIVED — never a hand-written list of its
      // fields. This was twelve of them copied out one by one, under a comment
      // claiming "the TENNO travels whole", which was true only by inspection:
      // every scenario field added since had to be remembered here, and the
      // one nobody remembered would score builds under a fight the replay
      // never runs. That is the divergence AGENTS.md's hard rule is about, and
      // a spread cannot forget (`eximus` was the field that found it).
      //
      // …and it is `theFight()`, the same call the simulator makes, rather
      // than the SNAPSHOT shape of it this sent until 2026-08-17. It also
      // stopped building the buff map itself: whole rather than pruned is what
      // `theFight` does for everyone now, for the reason this spot argued
      // first — a candidate carries mods you are not holding, and a setting for
      // one of them is what the scenario's wide buff view exists to record.
      //
      // Safe to send everything: `parse_fight` reads the fight's fields and
      // `parse_optimize` reads only its own five, so a scenario field the
      // optimizer has no opinion about simply arrives and is used.
      ...theFight(),
      // No `threads`: the server reads an absent one as 0 = auto, which is the
      // only answer this page has now that the compute share is the topbar's.
      final_runs: finalRuns(), finalists: optRun.finalists,
    };
    const r = await postJson("/api/optimize", body);
    if (!r || r.ok === false) {
      optFinish(`<div class="error">optimize failed: ${r ? r.error : "no data"}</div>`);
      return;
    }
    optJobId = r.job_id;
    pollOptimize();
  } catch (e) {
    optFinish(`<div class="error">optimize failed: ${e}</div>`);
  }
}

function optFinish(html) {
  if (optPollTimer) { clearTimeout(optPollTimer); optPollTimer = null; }
  optJobId = null;
  optCancelling = false;
  if (html !== undefined) $("opt-results").innerHTML = html;
  $("run-opt").textContent = "Run Optimizer";
  updateOptEstimate(); // re-enables the button when the scope is valid
}

async function pollOptimize() {
  let st;
  try {
    st = await postJson("/api/optimize/status", optJobId != null ? { id: optJobId } : {});
  } catch (e) {
    optFinish(`<div class="error">optimize status failed: ${e}</div>`);
    return;
  }
  if (!st || st.ok === false) {
    optFinish(`<div class="error">optimize failed: ${st ? st.error : "no data"}</div>`);
    return;
  }
  optJobId = st.job_id;
  if (st.phase === "error") {
    optFinish(`<div class="error">optimize failed: ${(st.result && st.result.error) || "unknown error"}</div>`);
    return;
  }
  if (st.phase === "done" || st.phase === "cancelled") {
    optFinish();
    if (st.result && st.result.results && st.result.results.length) {
      renderOptResults(st.result);
      // …AND EVERY FINALIST GOES TO THE BOARD. After the results are drawn, so
      // a slow door never delays the answer the reader asked for.
      offerOptBoardSubmit(st.result);
      // A cancel is not necessarily the end of the search — the run stopped,
      // but its resume point is still on disk. Offer it under the results.
      if (st.phase === "cancelled") appendResumeOffer();
    } else {
      $("opt-results").innerHTML = `<div class="placeholder">cancelled before anything had been ranked — no results</div>`;
    }
    return;
  }
  renderOptProgress(st);
  optPollTimer = setTimeout(pollOptimize, 500);
}

function renderOptProgress(st) {
  const pct = st.sims_planned ? Math.min(100, (100 * st.sims_done) / st.sims_planned) : 0;
  const head = st.phase === "enumerating"
    ? `enumerating candidates…${st.enumerated ? ` ${st.enumerated.toLocaleString()} so far` : ""}${st.sims_done ? ` · ${st.sims_done.toLocaleString()} screened` : ""}`
    : `round ${st.round}/${st.rounds} — ${(st.round_jobs || 0).toLocaleString()} jobs × ${st.round_runs} runs`;
  const notes = (st.notes || []).map((n) =>
    `<div class="opt-note">round ${n.round}: ${n.jobs.toLocaleString()} × ${n.runs} (${n.by_kills ? "kills" : "dmg"}) → keep ${n.kept.toLocaleString()} · best ${n.by_kills ? sig2(kpm(n.best, sim.duration)) + " KPM" : n.best.toExponential(2) + " dmg"} · ${(n.ms / 1000).toFixed(1)}s</div>`
  ).join("");
  const sub = st.phase === "enumerating"
    ? ""
    : `<div class="opt-prog-sub">${pct.toFixed(1)}% · ${st.sims_done.toLocaleString()} / ${st.sims_planned.toLocaleString()} sims${st.jobs ? ` · ${st.jobs.toLocaleString()} candidate builds` : ""}</div>`;
  $("opt-results").innerHTML = `<div class="opt-progress">
    <div class="opt-prog-head"><span>${head}</span><span class="opt-elapsed">${st.elapsed_s.toFixed(0)}s</span></div>
    <div class="opt-bar"><i style="width:${pct}%"></i></div>
    ${sub}${notes}
    <button class="ghost-btn small" id="opt-cancel" ${optCancelling ? "disabled" : ""}>${optCancelling ? "Cancelling…" : "Cancel"}</button>
  </div>`;
  // The 500 ms poll re-renders this whole block — `optCancelling` keeps the
  // button's cancelling state alive across re-renders, or it snaps back to a
  // live-looking "Cancel" and cancellation looks ignored.
  $("opt-cancel").addEventListener("click", async () => {
    optCancelling = true;
    $("opt-cancel").disabled = true; $("opt-cancel").textContent = "Cancelling…";
    try { await postJson("/api/optimize/cancel", { id: optJobId }); } catch (e) { /* poll reports */ }
  });
}

// Reattach to a job that is still running server-side (e.g. after a page
// reload): a no-id status call returns the latest job.
async function reattachOptimize() {
  try {
    const st = await postJson("/api/optimize/status", {});
    if (st && st.ok !== false && (st.phase === "enumerating" || st.phase === "running")) {
      optJobId = st.job_id;
      $("run-opt").disabled = true; $("run-opt").textContent = "Optimizing…";
      renderOptProgress(st);
      optPollTimer = setTimeout(pollOptimize, 500);
      return;
    }
  } catch (e) { /* no server-side job — nothing to reattach */ }
  offerResume(); // nothing is running: a reload may have killed a wasm run
}

// The run itself is gone, but the field it had narrowed to is not. Offer to
// continue from the last completed round instead of paying for it again.
// Never auto-start: resuming costs minutes of the visitor's CPU, so it takes a
// click — and the offer only appears for the weapon the checkpoint belongs to.
function offerResume() {
  const el = resumeControl();
  if (!el) return;
  const box = $("opt-results");
  box.innerHTML = "";
  box.append(el);
}

// The same control, under a cancelled run's leaderboard.
function appendResumeOffer() {
  const el = resumeControl();
  if (el) $("opt-results").append(el);
}

function resumeControl() {
  const saved = loadCheckpoint();
  const box = $("opt-results");
  if (!saved || !box || optJobId != null) return null;
  if (saved.body.weapon !== $("weapon").value) return null;
  const cp = saved.cp;
  const el = document.createElement("div");
  el.className = "opt-resume";
  const sel = $("weapon");
  const shown = (sel.selectedOptions[0] || {}).textContent || sel.value;
  const where = cp.kind === "screen"
    ? `while screening — ${cp.start_seq.toLocaleString()} candidates walked, `
      + `${(cp.keepers.length / 2).toLocaleString()} jobs still standing`
    : `after round ${cp.round} — ${cp.alive.length.toLocaleString()} builds still standing`;
  el.innerHTML = `<div>An optimization for <b>${escHtml(shown)}</b> stopped ${where}.</div>`;
  const go = document.createElement("button");
  go.className = "ghost-btn"; go.textContent = "resume it";
  go.onclick = () => resumeOptimize(saved);
  const no = document.createElement("button");
  no.className = "ghost-btn small"; no.textContent = "discard";
  no.onclick = () => { clearCheckpoint(); el.remove(); };
  el.append(go, no);
  return el;
}

async function resumeOptimize(saved) {
  $("run-opt").disabled = true; $("run-opt").textContent = "Optimizing…";
  $("opt-results").innerHTML = `<div class="placeholder">${saved.cp.kind === "screen"
    ? `re-walking to the saved point (${saved.cp.start_seq.toLocaleString()} candidates)…`
    : `resuming from round ${saved.cp.round}…`}</div>`;
  try {
    // The STORED body, not the current form: the checkpoint describes a field
    // narrowed under that exact scope, and re-deriving the body from the UI
    // would let an edited setting resume into a run it never belonged to.
    const r = await postJson("/api/optimize", { ...saved.body, __resume: saved.cp });
    if (!r || r.ok === false) {
      clearCheckpoint();
      optFinish(`<div class="error">resume failed: ${r ? r.error : "no data"}</div>`);
      return;
    }
    optJobId = r.job_id;
    pollOptimize();
  } catch (e) {
    optFinish(`<div class="error">resume failed: ${e}</div>`);
  }
}

const prettify = (id) => id.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
const arcName = (id) => (id === "none" ? "no arcane" : ((META.arcanes || []).find((a) => a.id === id) || {}).name || prettify(id));
const evoName = (id) => {
  for (const t of weaponEvos()) { const o = t.options.find((o) => o.id === id); if (o) return o.name; }
  return prettify(id);
};

/// The ranking on screen. Kept so the quick calc can offer the WINNER as its
/// reference build — a mod measured on two required cards meets no diminishing
/// returns, and the winner is the same question asked on a build that is full.
/// Cleared with the results themselves when the weapon changes.
let optLast = null;

function renderOptResults(r) {
  optLast = r;
  const rows = (r.results || []).map((res) => {
    // HOW THIS ROW WAS PLAYED, drawn only when the search RANGED over modes —
    // otherwise every row would repeat the one answer the scope already
    // states. A ranking that mixes them has to say which is which: two rows
    // with the same mods and different modes are two different builds.
    const modes = new Set((r.results || []).map((x) => x.mode).filter(Boolean));
    // …AND THE SAME RULE FOR THE ELEMENT. A search that pinned one says it in
    // its scope; one that ranged over several has to name the winner's, or a
    // ranking of adversary builds is a list of rows nobody can reproduce.
    const valences = new Set((r.results || []).map((x) => x.valence).filter(Boolean));
    const detail = buildContentsHtml({
      mods: res.mods,
      exilus: res.exilus,
      arcanes: asArcaneList(res.arcane, (res.arcane || []).length),
      arcaneRanks: asArcaneList(res.arcane_rank, (res.arcane || []).length),
      evolutions: res.evolutions,
      modeLabel: modes.size > 1 && res.mode
        ? modeLabel(weaponInfo($("weapon").value) || {}, res.mode)
        : "",
      valence: valences.size > 1 ? res.valence : "",
      assembly: res.assembly,
      riven: (res.mods || []).includes("riven"),
    });
    return `<div class="opt-row">
      <div class="opt-head">
        <span class="opt-rank">#${res.rank}</span>
        <span class="opt-kills" id="opt-kpm-${res.rank}" data-search="${
          kpm(res.kill_progress ?? res.kills, r.duration)}">${
          sig2(kpm(res.kill_progress ?? res.kills, r.duration))}<small> KPM</small><span class="opt-repro pending" title="${
          escHtml(tr("re-measuring this build in the simulator"))}">·</span></span>
        <span class="opt-dps">${Math.round(res.dps || res.effective_dps || 0).toLocaleString()} DPS</span>
        <span class="opt-total">${sig2(res.kill_progress ?? res.kills)} kill score / ${Math.round(r.duration || 0)}s</span>
        <span class="forma-badge legal">${res.forma.used} Forma</span>
        <button class="ghost-btn small opt-add" title="${escHtml(tr("save as a new build"))}" data-r='${JSON.stringify(res).replace(/'/g, "&#39;")}'>+ add</button>
      </div>
      ${detail}
    </div>`;
  }).join("");
  // WHAT THE SEARCH COVERED, whenever it did not cover everything. This is not
  // CANCELLED — that means you stopped it and this is the best it had. This
  // means the scope is bigger than one search's budget, so the ranking below
  // was chosen from a SAMPLE. The sample is uniform over the whole space (the
  // search walks a shuffled index range), so the number is a real confidence
  // statement rather than an apology: at 3% of the space the winner is a good
  // build, not necessarily THE build.
  //
  // `exhaustive` is the other half and it is the one worth saying out loud:
  // when the search reaches the end of its space, the answer is not a
  // best-so-far, it is the optimum of everything you pooled.
  const cov = r.exhaustive
    ? `<span class="ok">${escHtml(tr("every build in this scope was searched"))}</span> · `
    : (r.coverage != null && r.coverage < 1
      ? `<span class="warn">${escHtml(tr("searched {pct}% of this scope ({n} of {total} builds) — a uniform sample, so this is a strong build rather than a proven best; pool fewer mods to search all of it"))
          .replace("{pct}", (r.coverage * 100).toFixed(r.coverage < 0.01 ? 3 : 1))
          .replace("{n}", (r.searched || 0).toLocaleString())
          .replace("{total}", Math.round(r.space || 0).toLocaleString())}</span> · `
      : "");
  $("opt-results").innerHTML = `<div class="opt-board" id="opt-board"></div><div class="opt-meta">${cov}${r.cancelled ? `<span class="warn">cancelled — best-so-far ranking (lower precision than a full run)</span> · ` : ""}${(r.jobs || 0).toLocaleString()} candidate builds · vs ${r.target.name} Lv ${r.target.level}${r.target.steel_path ? " (SP)" : ""} · ${r.headshot_pct ?? "?"}% headshots · ${r.duration ?? "?"} s engagements · ${r.finalists || 20} finalists × ${(r.final_runs || 1024).toLocaleString()} runs</div>${rows}`;
  $("opt-results").querySelectorAll(".opt-add").forEach((el) =>
    el.addEventListener("click", () => addResult(JSON.parse(el.dataset.r), el)));
  verifyOptRows(r);
}

/// THE NUMBER ON A ROW IS THE SIMULATOR'S.
///
/// The hard rule made operational on the PAGE. "The simulator is the truth"
/// covers the ENGINE, where `parse_fight` sees to it; a page with its own
/// translation of a ranked row into a build ranks by one thing while the
/// builder fires another, measured at 26 KPM against 15.
///
/// So each row is re-run through `/api/simulate` — with the request the SERVER
/// wrote for that candidate — and the KPM on screen is what came back. The
/// search's own figure keeps one job, ORDERING the list, since re-measuring
/// cannot reorder a ranking without making it meaningless.
///
/// The two are compared, and both sides report their own standard error, so
/// "they disagree" is arithmetic rather than a tolerance somebody picked: 4
/// sigma of the two combined. Any axis lost anywhere on the chain moves the
/// number and trips it, which is why this checks the ANSWER instead of counting
/// fields — it cannot go stale when an axis is added.
///
/// Top-down and sequential: the leader is what a reader looks at first, and
/// twenty engagements at the final round's precision is real time.
let optVerifyToken = 0;
async function verifyOptRows(r) {
  const token = ++optVerifyToken;
  const rows = (r.results || []).slice();
  for (const res of rows) {
    if (token !== optVerifyToken) return;          // a newer ranking owns the panel
    const el = $(`opt-kpm-${res.rank}`);
    if (!el) continue;
    const mark = el.querySelector(".opt-repro");
    if (!res.replay) {
      if (mark) { mark.className = "opt-repro stale"; mark.textContent = ""; mark.title = tr("this ranking predates the simulator re-run"); }
      continue;
    }
    // …ALSO THROUGH THE FLEET. Every ranked row is re-simulated, so on a crowd
    // ruler this is the finalist count TIMES a full simulation — the one place
    // on the page where the fleet is worth the most.
    let s = null;
    try { s = await simulateFleet(res.replay); } catch (_) { s = null; }
    if (token !== optVerifyToken) return;
    if (!s || s.ok === false || s.score_mean == null) {
      if (mark) { mark.className = "opt-repro failed"; mark.textContent = "!"; mark.title = tr("the simulator refused this build — see the build's own card"); }
      continue;
    }
    const shown = kpm(s.score_mean, r.duration);
    const search = Number(el.dataset.search) || 0;
    // FOUR SIGMA OF THE TWO COMBINED. Both are means of independent runs, so
    // their difference has the two standard errors added in quadrature — there
    // is no systematic gap to allow for, and any tolerance written as a flat
    // percentage would be too tight at 40 runs and too loose at 1000.
    const se = Math.hypot(kpm(s.score_se || 0, r.duration),
                          kpm(res.kill_progress_se || 0, r.duration));
    const off = Math.abs(shown - search) > Math.max(4 * se, 0.01 * Math.abs(search));
    el.firstChild.nodeValue = sig2(shown);
    if (mark) {
      mark.className = "opt-repro " + (off ? "off" : "ok");
      mark.textContent = off ? "≠" : "✓";
      mark.title = off
        ? tr("the simulator does not reproduce the search's own score for this build — the build shown may not be the one that was scored")
          + ` (${sig2(search)} → ${sig2(shown)} KPM)`
        : tr("re-run in the simulator: this is the simulator's own number for this build");
    }
    if (off) el.closest(".opt-row").classList.add("opt-unreproduced");
  }
}

// An optimizer result as a builder-builds preset STATE (snapshotState
// shape) — built without touching the build being edited. autoForma()
// works on the global `slots`, so swap in a scratch array for the plan.
function resultToState(res) {
  // THE ROW'S OWN REQUEST, not a build re-derived from a description of one.
  //
  // `replay` is a complete simulate request written by the server out of the
  // very candidate it scored, so applying a result reads exactly ONE field and
  // there is nothing here to keep in step with the search. Every axis the row
  // was measured under is in it, including the ones nobody has invented yet.
  //
  // A row from a run predating `replay` still has to open, so the named fields
  // remain the fallback — and they are a translation, with everything that
  // implies: `mode` and `valence` fall back to the PAGE, which is the mode and
  // the element that run was launched in.
  const payload = res.replay || {
    mods: (res.mods || []).concat(
      res.exilus && res.exilus !== "none" ? [res.exilus] : [],
    ),
    evolutions: res.evolutions || [],
    arcane: res.arcane,
    arcane_rank: res.arcane_rank,
    mode: res.mode || mode,
    valence_element: res.valence || valence.element,
    valence_bonus: valence.bonus,
  };
  const st = stateFromBuild(payload, $("weapon").value, res.exilus);
  // …and the POLARITIES, which are the page's alone: a payload states the
  // build, and the cheapest layout that fits it is a plan the builder makes.
  // `autoForma` works on the global `slots`, so swap in a scratch array.
  const live = slots;
  slots = st.slots.map((s, i) => ({ mod: s.mod, pol: innate[i], rank: s.rank }));
  autoForma(); // minimum-Forma polarities, same as a hand-loaded build
  st.slots = slots.map((s) => ({ mod: s.mod, pol: s.pol, rank: s.rank }));
  slots = live;
  // NO `sim`. Copying the optimizer's own buff config into the scenario so
  // that "add then Run Sim" matches its score makes a result rewrite the fight
  // you are working in; a result is a BUILD. The two configs can still
  // disagree — the search's is scope-wide, the scenario's is this build's —
  // and that disagreement is now visible instead of resolved by silently
  // editing a preset the user owns.
  return st;
}

// "+ add" (not load): the result becomes a NEW preset
// appended after the existing builds; the build being edited is never
// clobbered. Auto-named "opt N" (rename in the preset bar if it earns a
// real name).
function addResult(res, btn) {
  const ps = loadPresetList(BUILDS);
  let n = 1;
  while (ps.some((p) => p.name === "opt " + n)) n++;
  const name = "opt " + n;
  ps.push({ name, savedAt: Date.now(), state: resultToState(res) });
  storePresetList(BUILDS, ps);
  renderPresetBar(); // the builder's bar shows the new chip when you switch back
  if (btn) { btn.textContent = "✓ " + name; btn.disabled = true; }
}

/// RECLAIM WHAT THE OLD RULE LEFT BEHIND, once, on the way in.
///
/// `stripReplays` stops the growth; it does not undo it. Every replay written
/// before 2026-08-18 is still on the reader's disk, in a key for a weapon they
/// may never open again — and a browser that is already at its quota fails the
/// NEXT write, not the one that filled it, so without this the fix would only
/// arrive for whoever cleared their own storage first.
///
/// It rewrites each `wfsim-presets-*` key in place and only when the stripped
/// copy is actually smaller, so a reader with nothing to reclaim pays one parse
/// per key and writes nothing.
function reclaimStoredReplays() {
  let freed = 0;
  for (const k of Object.keys(localStorage)) {
    if (!k.startsWith("wfsim-presets-")) continue;
    const raw = localStorage.getItem(k) || "";
    // The cheap test first: a list with no replay in it is not worth parsing.
    if (!raw.includes('"replay"')) continue;
    let list = null;
    try { list = JSON.parse(raw); } catch (_) { continue; }
    if (!Array.isArray(list)) continue;
    const next = JSON.stringify(stripReplays(list));
    if (next.length >= raw.length) continue;
    try {
      localStorage.setItem(k, next);
      freed += raw.length - next.length;
    } catch (_) {
      // Full enough that even the SMALLER copy will not go in. Removing the key
      // is still better than leaving it: the collection re-creates itself.
      try { localStorage.removeItem(k); freed += raw.length; } catch (_) { /* nothing left to try */ }
    }
  }
  return freed;
}
try { reclaimStoredReplays(); } catch (_) { /* storage may be unavailable entirely */ }

// ---------------------------------------------------------------------------
// THE DESKTOP UPDATE NOTICE
//
// IT LIVES HERE AND NOT IN THE SHELL, and that one decision is the whole update
// strategy. The shell is a binary a reader replaces by running an installer;
// this file is a thing the updater itself replaces. So an updater compiled into
// the shell cannot fix its own bugs — every reader would be frozen on the
// broken version, and the only way out is asking them to download an installer
// by hand, which is precisely what the desktop build exists to avoid. Putting
// it in `app.js` means a mistake here is repairable the same quiet way as any
// other: change a file, push, done.
//
// A NO-OP IN A BROWSER. `__WFSIM_DESKTOP__` is set by the shell and by nothing
// else, so this costs the web build one comparison at boot.
//
// IT NEVER RESTARTS BY ITSELF. A download is silent and a restart is asked for,
// because a page that reloads on its own throws away whatever the reader was
// in the middle of — an hour-long search, a fight half set up — to deliver a
// change they had not asked for yet.
const DESKTOP_POLL_MS = 700;
/// Hourly. The client is not a page a reader refreshes, so it has to look on
/// its own; hourly is often enough that a fix lands the day it ships and rare
/// enough to be invisible.
const DESKTOP_CHECK_MS = 60 * 60 * 1000;

// ---------------------------------------------------------------------------
// THE DESKTOP DOWNLOAD — one platform, and the SOURCE it comes from.
//
// WINDOWS ONLY, FOR NOW. The Linux entry was built and
// listed before anyone had asked for it, and it cost the offer its shape: the
// hero drew a Windows button, a GitHub link beside it, and then a second row
// saying "Linux · GitHub" — four things for what is one decision. Warframe on
// Linux is Proton, which is a smaller audience than the row it was taking.
//
// THE SOURCE IS NAMED BESIDE THE BUTTON, which is the whole point of the badge. The file is not hosted by this site: it lives on a Quark
// network drive, and a reader about to run a downloaded executable is entitled
// to see where it is coming from BEFORE they click rather than after the tab
// has opened. That drive is also the reason the client exists — measured from
// Shanghai, it serves 4.6x faster than Cloudflare does (AGENTS.md), and the
// readers this project is mostly for are exactly the ones GitHub is slowest
// for.
const DOWNLOADS = [
  {
    os: "Windows",
    // Anything that says Windows and is not a phone claiming to be one.
    detect: (ua) => /Windows NT/i.test(ua),
    file: "WFSim.exe",
    source: {
      name: "夸克网盘",
      url: "https://pan.quark.cn/s/dc8fe9046d6a",
      // A GENERIC DRIVE MARK, not Quark's own. The badge has to SAY which
      // service this is, which the name does; reproducing somebody else's
      // logo to do it would be borrowing their trademark for a claim they
      // have not made about this file.
      icon: '<svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true">'
        + '<path fill="none" stroke="currentColor" stroke-width="1.7"'
        + ' stroke-linecap="round" stroke-linejoin="round"'
        + ' d="M6.5 18.5a4 4 0 0 1-.4-8A5.5 5.5 0 0 1 17 10.2a3.6 3.6 0 0 1 .3 8.3z'
        + 'M12 9.5v6m0 0-2.4-2.4M12 15.5l2.4-2.4"/></svg>',
    },
  },
];

/// The button and the source it came from, as one piece of markup.
///
/// THE SOURCE IS NAMED BESIDE THE BUTTON. This site does not host the
/// executable, and a reader about to run a downloaded binary is entitled to see
/// whose drive it is on before they click rather than after the tab has opened.
/// The badge links to the same place, so "where does this come from" and "take
/// me there to look first" are one click apart.
function downloadOffer(d) {
  const src = d.source;
  return `<a class="dl-btn" href="${escHtml(src.url)}" target="_blank" rel="noopener">`
    + `${escHtml(tr("Download for {os}").replace("{os}", d.os))}</a>`
    + `<a class="dl-src" href="${escHtml(src.url)}" target="_blank" rel="noopener"`
    + ` title="${escHtml(trF("hosted on {name} — this is where the file comes from",
      { name: src.name }))}">${src.icon}<span>${escHtml(src.name)}</span></a>`;
}

/// The machine asking, in one answer for both surfaces to use. `null` means a
/// phone: it is already running what a download would install.
function downloadFor(ua) {
  if (/Android|iPhone|iPad|iPod/i.test(ua || "")) return null;
  return DOWNLOADS.find((d) => d.detect(ua || "")) || false;
}

/// THE HOME HERO'S POINTER, one line. The offer is a page of questions — what
/// SmartScreen does, why the program is unsigned, what updating costs — and
/// the hero is read by someone who has not yet seen the tool work, which is the
/// worst moment to ask them to run an unsigned executable.
///
/// A DESKTOP WE DO NOT BUILD FOR IS TOLD SO, rather than handed a link it
/// cannot use. Warframe has no macOS client either, so that reader is rarely
/// anyone — which is exactly why the case would go unnoticed.
function renderDownloads() {
  const host = document.getElementById("hero-dl");
  if (!host) return;
  // ALREADY RUNNING IT. A line inviting the reader to install what they are
  // already inside reads as a page that does not know where it is — and the
  // same index.html serves both, so the element is here either way. It is
  // decided HERE, in the function that decides what the hero offers, rather
  // than by whoever else happens to run in the client.
  if (window.__WFSIM_DESKTOP__) {
    host.hidden = true;
    return;
  }
  const mine = downloadFor(navigator.userAgent);
  if (mine === null) {
    host.hidden = true;
    return;
  }
  host.innerHTML = mine
    ? `<a class="dl-line" href="/download">${escHtml(
      trF("{os} app — opens instantly, works offline, updates itself", { os: mine.os }))}`
      + ` <span class="dl-go">→</span></a>`
    : `<span class="dl-why">${escHtml(tr("A desktop version is available for Windows."))}</span>`;
  host.hidden = false;
}

/// The page at /download: the offer, above the questions the markup asks.
function renderDownloadPage() {
  const host = document.getElementById("dl-offer");
  if (!host) return;
  // ALREADY RUNNING IT. The URL is typed by hand and read off a video, so it
  // has to answer inside the client too — as the fact that there is nothing
  // here to install rather than as a blank.
  if (window.__WFSIM_DESKTOP__) {
    host.innerHTML = `<span class="dl-why">${escHtml(
      tr("You are running the Windows app. It updates itself — there is nothing to download here."))}</span>`;
    return;
  }
  const mine = downloadFor(navigator.userAgent);
  // A PHONE READS THE PAGE. The hero shows a phone nothing because an
  // executable is noise on the one screen with the least room for it; a reader
  // who has navigated HERE asked, and is answered with the button they cannot
  // use today plus the reason.
  const d = mine || DOWNLOADS[0];
  host.innerHTML = downloadOffer(d)
    + (mine ? "" : `<span class="dl-why">${escHtml(
      tr("This is a Windows program — it will not run on the machine you are reading this on."))}</span>`);
}

function mountDesktopUpdater() {
  if (!window.__WFSIM_DESKTOP__ || !window.__TAURI_INTERNALS__) return;
  const invoke = (cmd, args = {}) => window.__TAURI_INTERNALS__.invoke(cmd, args);

  const bar = document.createElement("div");
  bar.className = "dtup";
  bar.hidden = true;
  document.body.appendChild(bar);

  let dismissed = "";
  const hide = () => { bar.hidden = true; };

  // ONE QUESTION, AND IT IS THE ONLY ONE THE READER CAN ANSWER: when to
  // restart. Whether to spend 12 MB on a calculator they already have open is
  // not a decision they have anything to decide it with, and asking it made
  // the update wait behind a button — so the fetch happens on its own and the
  // notice appears when there is something a click can finish.
  const render = (s) => {
    // A version the reader has already waved away stays away until the NEXT
    // one — a notice that comes back every hour is a notice people learn to
    // close without reading. A status with NO version was never dismissed:
    // a check that fails before it reads one carries the empty string, and
    // matching that against a fresh `dismissed` would hide the failure.
    if (s.version && dismissed === s.version) return hide();
    let html = "";
    if (s.phase === "ready") {
      html = `<span class="dtup-t">${escHtml(tr("Update ready — restart to finish"))}</span>`
        + `<button class="dtup-b" data-a="go">${escHtml(tr("Restart now"))}</button>`
        + `<button class="dtup-x" data-a="no" title="${escHtml(tr("Later"))}">×</button>`;
    } else if (s.phase === "failed") {
      // THE ONE FAILURE THAT IS WORTH INTERRUPTING FOR, even unasked: a client
      // that cannot update is a client frozen for good, and silence here is
      // indistinguishable from being up to date.
      html = `<span class="dtup-t dtup-e">${escHtml(tr("Update failed"))}: ${escHtml(s.message || "")}</span>`
        + `<button class="dtup-x" data-a="no">×</button>`;
    } else {
      return hide();
    }
    bar.innerHTML = html;
    bar.hidden = false;
  };

  let polling = false;
  const poll = async () => {
    if (polling) return;
    polling = true;
    try {
      const s = await invoke("update_status");
      if (s.phase === "available") {
        await invoke("update_download");
        polling = false;
        return poll();
      }
      render(s);
      if (s.phase === "checking" || s.phase === "downloading") setTimeout(() => { polling = false; poll(); }, DESKTOP_POLL_MS);
      else polling = false;
    } catch (_) { polling = false; }
  };

  bar.addEventListener("click", async (e) => {
    const b = e.target.closest && e.target.closest("[data-a]");
    if (!b) return;
    const a = b.getAttribute("data-a");
    if (a === "no") {
      try { const s = await invoke("update_status"); dismissed = s.version; } catch (_) { /* hide anyway */ }
      return hide();
    }
    if (a === "go") {
      try {
        await invoke("update_apply");
        // The swap is done; the page is now serving files from a directory
        // that no longer matches what this document was loaded from.
        location.reload();
      } catch (err) {
        render({ phase: "failed", message: String(err), version: "" });
      }
    }
  });

  // THE SOURCE LINK IS PART OF SHIPPING THIS AT ALL. AGPL asks for the source
  // corresponding to the binary being conveyed, and this client conveys itself
  // a new one on every update — so the link has to name the version in the
  // footer beside it, not "the latest", which is the wrong tree for anyone who
  // has not updated yet. The archive for every version is kept on the same
  // bucket the update came from, so this is the same "same place" the licence
  // means. It goes next to the build stamp because that is where a reader
  // already looks to find out what they are running.
  invoke("source_url").then((url) => {
    const stamp = document.getElementById("build-stamp");
    if (!stamp || !url) return;
    const a = document.createElement("a");
    a.href = url;
    a.className = "wl";
    a.textContent = tr("source");
    a.title = "AGPL-3.0";
    stamp.after(document.createTextNode(" · "), a);
  }).catch(() => { /* an older shell without the command still runs */ });

  // AN ASSEMBLED UPDATE IS THE END OF THE LINE UNTIL A RESTART. `check`
  // compares the channel against `current/`, which the download did not touch,
  // so checking again reports the same update as available — and now that the
  // fetch is automatic, that is 12 MB pulled down every hour behind a notice
  // already on screen saying it is ready.
  const look = async () => {
    try {
      const s = await invoke("update_status");
      if (s.phase === "ready" || s.phase === "downloading") return poll();
      await invoke("update_check");
      poll();
    } catch (_) { /* offline is normal */ }
  };
  // Not at boot: the first seconds belong to the page the reader opened.
  setTimeout(look, 8000);
  setInterval(look, DESKTOP_CHECK_MS);
}

// THE BOOT IS OVER, one way or the other, and the page must say which.
//
// Writing a failure into `.config-page` puts it where the home page hides it,
// so a boot that fails there leaves a blank screen and no reason. The banner
// installed in the document head is visible on every page and outlives an
// app.js that never
// parsed; this hands it the reason and clears the placeholder on success.
init()
  .then(() => {
    window.__wfsimReady = true;
    const b = document.getElementById("booting");
    if (b) b.remove();
    // THE DOWNLOAD OFFER IS FOR THE WEB. Inside the desktop app it would be an
    // invitation to install what is already running, so that build draws
    // nothing at all rather than drawing it and hiding it.
    try {
      if (window.__WFSIM_DESKTOP__) mountDesktopUpdater();
      else renderDownloads();
    } catch (_) { /* the app runs without either */ }
  })
  .catch((e) => {
    // …unless the reason already put its own, better sentence on the page.
    if (bootReported) return;
    if (window.__wfsimBootFailed) {
      window.__wfsimBootFailed(
        "WFSim could not start. / WFSim 启动失败。",
        String((e && (e.stack || e.message)) || e),
      );
    }
  });
